func _init(definition_id: String, landlook_id: int, base_tile_id: int, tiles: Array[BattleTerrainTileDefinition]) -> void:
	id = definition_id
	landlook = landlook_id
	base_tile = base_tile_id
	for tile_definition: BattleTerrainTileDefinition in tiles:
		_tiles_by_id[tile_definition.tile] = tile_definition

func has_complete_range(first_tile: int, last_tile: int) -> bool:
	if first_tile < 0 or last_tile < first_tile or _tiles_by_id.size() != last_tile - first_tile + 1:
		return false
	for tile_id: int in range(first_tile, last_tile + 1):
		if not _tiles_by_id.has(tile_id):
			return false
	return true

func _init(monster: MonsterState, definition: MonsterDefinition = null, content: RealmzContent = null) -> void:
	id = monster.id
	definition_id = monster.definition_id
	name = monster.name
	current_health = monster.current_health
	maximum_health = monster.maximum_health
	hit_dice = monster.hit_dice
	armor = monster.armor
	magic_resistance = monster.magic_resistance
	spell_points = monster.spell_points
	maximum_spell_points = monster.maximum_spell_points
	traitor = monster.traitor
	helpless = monster.conditions.is_active(ConditionRules.HELPLESS)
	icon_id = monster.icon_id
	for index: int in monster.conditions.values().size():
		if monster.conditions.value(index) != 0:
			conditions.append(CharacterView.CONDITION_NAMES[index] if index < CharacterView.CONDITION_NAMES.size() else "Classic condition %d" % (index + 1))
	if definition != null:
		classic_id = definition.classic_id
		movement_maximum = definition.movement_max
		attack_count = definition.attack_count
		for index: int in 6:
			if definition.spell_immune(index):
				immunities.append(CharacterView.SAVE_NAMES[index])
		for index: int in 5:
			if definition.save_value(index) < 0:
				vulnerabilities.append(CharacterView.SAVE_NAMES[index])
	if content != null and not monster.weapon_id.is_empty():
		var weapon := content.item_by_id(monster.weapon_id)
		if weapon != null:
			weapon_name = weapon.name

func _init(combat: CombatState, characters: Array[CharacterState] = [], content: RealmzContent = null, inventory_rules: InventoryRules = null, battlefield_rules: BattlefieldRules = null, combat_flow: CombatFlow = null, game_state: GameState = null) -> void:
	battle_id = combat.battle_id
	round_number = combat.round_number
	active_actor_id = combat.active_actor_id()
	outcome = combat.outcome
	turn_order = combat.turn_order()
	if combat.battlefield != null:
		var upper_tileset_id := ""
		if content != null:
			var source_map := content.world.map_by_id(combat.battlefield.map_id)
			if source_map != null and source_map.level_type == &"land" and source_map.landlook >= 0:
				upper_tileset_id = "landlook-%d" % source_map.landlook
		battlefield = BattlefieldView.new(combat.battlefield, upper_tileset_id)
	var adjacent_ids: Array[String] = []
	if combat.battlefield != null and battlefield_rules != null and not active_actor_id.is_empty():
		adjacent_ids = battlefield_rules.adjacent_actor_ids(combat.battlefield, active_actor_id)
	for monster: MonsterState in combat.monsters():
		var definition := content.monster_by_id(monster.definition_id) if content != null else null
		var view := MonsterView.new(monster, definition, content)
		monsters.append(view)
		if monster.current_health > 0 and monster.traitor and adjacent_ids.has(monster.id):
			targets.append(view)
	for character: CharacterState in characters:
		if character.id == active_actor_id:
			attack_units_remaining = character.attacks_remaining
			movement_remaining = character.maximum_movement if combat.active_turn == null else character.movement
		if character.current_health > 0 and character.traitor and adjacent_ids.has(character.id):
			character_targets.append(CharacterView.new(character, content))
	_populate_active_relationships(combat, characters)
	if combat.completed:
		return
	var active_character: CharacterState = null
	for character: CharacterState in characters:
		if character.id == active_actor_id:
			active_character = character
			break
	if active_character != null and content != null and inventory_rules != null:
		if combat_flow != null:
			var retreat_probe: Variant = combat_flow.probe_character_retreat(combat, characters, active_character.id)
			retreat_available = retreat_probe.allowed
			retreat_unavailable_reason = retreat_probe.reason_text
			nearest_enemy_range = retreat_probe.nearest_enemy_range
			auto_turn = ActionAvailabilityView.new(&"auto", true)
			var delay_probe := combat_flow.probe_delay(game_state, active_character.id)
			delay = ActionAvailabilityView.new(&"delay", delay_probe.allowed, delay_probe.reason_text)
			var bandage_probe := combat_flow.probe_bandage(game_state, active_character.id)
			bandage = ActionAvailabilityView.new(&"bandage", bandage_probe.allowed, bandage_probe.reason_text)
			var turn_probe := combat_flow.probe_turn_undead(game_state, content, active_character.id)
			turn_undead = ActionAvailabilityView.new(&"turn_undead", turn_probe.allowed, turn_probe.reason_text)
			var undo_probe := combat_flow.probe_undo(game_state, active_character.id)
			undo = ActionAvailabilityView.new(&"undo", undo_probe.allowed, undo_probe.reason_text)
			for candidate_id: String in combat_flow.bandage_candidate_ids(game_state):
				var candidate := game_state.party.character_by_id(candidate_id)
				if candidate != null:
					bandage_candidates.append(CharacterView.new(candidate, content))
			for target_id: String in combat_flow.turn_undead_target_ids(game_state, content):
				var target := combat.monster_by_id(target_id)
				if target != null:
					turn_undead_targets.append(MonsterView.new(target, content.monster_by_id(target.definition_id), content))
		var equipment := inventory_rules.combat_equipment(active_character, content.item_definitions())
		if equipment.valid:
			weapon_mode = combat.character_weapon_mode(active_character.id)
			melee_weapon_id = equipment.melee_weapon.id if equipment.melee_weapon != null else ""
			missile_weapon_id = equipment.missile_weapon.id if equipment.missile_weapon != null else ""
			weapon_switch_available = weapon_mode == &"missile" or equipment.missile_weapon != null
			weapon_switch_target_mode = &"melee" if weapon_mode == &"missile" else &"missile"
			weapon_switch_unavailable_reason = "" if weapon_switch_available else "The active character has no equipped Classic type-15 missile weapon."
			if weapon_mode != &"melee":
				targets.clear()
				character_targets.clear()
				var profile := combat_flow.character_projectile_profile(active_character, content, equipment) if combat_flow != null else null
				if profile == null or not profile.available:
					ranged_attack_unavailable_reason = profile.error_message if profile != null else "Projectile rules are unavailable."
				else:
					for monster: MonsterState in combat.monsters():
						if monster.current_health > 0 and monster.traitor != active_character.traitor and combat_flow.projectile_target_is_valid(combat, content, active_character.id, monster.id, profile.maximum_range, profile.spell.range_min + profile.spell.range_max > 0):
							targets.append(MonsterView.new(monster, content.monster_by_id(monster.definition_id), content))
					if targets.is_empty():
						ranged_attack_unavailable_reason = "No hostile monster is within the projectile's Classic range and line of sight."
					else:
						legal_actions.append(&"attack")
			if weapon_switch_available:
				legal_actions.append(&"switch_weapon")
		else:
			equipment_error_reason = equipment.error_message
			weapon_switch_unavailable_reason = equipment.error_message
		if combat.battlefield != null and battlefield_rules != null:
			var map := content.world.map_by_id(combat.battlefield.map_id)
			var terrain_set := content.world.battle_terrain_set_by_id(map.battle_terrain_set_id) if map != null else null
			if terrain_set != null:
				var contact_attack_available := false
				var movement_allowance := active_character.maximum_movement if combat.active_turn == null else active_character.movement
				for direction: Vector2i in BattlefieldRules.DIRECTIONS:
					var destination := combat.battlefield.actor_position(active_character.id) + direction
					var edge_retreat: Variant = combat_flow.probe_edge_retreat(combat, active_character.id, destination) if combat_flow != null else null
					var probe := battlefield_rules.probe_step(combat.battlefield, terrain_set, active_character.id, direction, movement_allowance)
					var contact_target_id := ""
					var contact_target_name := ""
					if weapon_mode == &"melee" and probe.reason == &"occupied" and _is_hostile_target(combat, characters, active_character, probe.occupant_id):
						contact_target_id = probe.occupant_id
						contact_target_name = _target_name(combat, characters, contact_target_id)
						contact_attack_available = true
					movement_options.append(CombatMoveOptionView.new(direction, probe, edge_retreat != null and edge_retreat.allowed, edge_retreat != null and edge_retreat.forced, contact_target_id, contact_target_name))
				if weapon_mode == &"melee" and not contact_attack_available:
					melee_attack_unavailable_reason = "No hostile battlefield footprint is adjacent."
				if weapon_mode == &"melee":
					targets.clear()
					character_targets.clear()
	legal_actions.append(&"finish")
	legal_actions.append(&"defend")
	if retreat_available:
		legal_actions.append(&"retreat")
	if auto_turn.enabled:
		legal_actions.append(&"auto")
	if delay.enabled:
		legal_actions.append(&"delay")
	if bandage.enabled:
		legal_actions.append(&"bandage")
	if turn_undead.enabled:
		legal_actions.append(&"turn_undead")
	if undo.enabled:
		legal_actions.append(&"undo")
	if game_state != null:
		auto_character_ids = game_state.combat_auto_character_ids()

func _populate_active_relationships(combat: CombatState, characters: Array[CharacterState]) -> void:
	if combat.battlefield == null:
		return
	for character: CharacterState in characters:
		if character.current_health <= 0 or not combat.battlefield.has_actor(character.id):
			continue
		(friendly_actor_ids if not character.traitor else hostile_actor_ids).append(character.id)
	for monster: MonsterState in combat.monsters():
		if monster.current_health <= 0 or not combat.battlefield.has_actor(monster.id):
			continue
		(friendly_actor_ids if not monster.traitor else hostile_actor_ids).append(monster.id)

static func _is_hostile_target(combat: CombatState, characters: Array[CharacterState], actor: CharacterState, target_id: String) -> bool:
	if target_id.is_empty() or actor == null:
		return false
	var monster := combat.monster_by_id(target_id)
	if monster != null:
		return monster.current_health > 0 and monster.traitor != actor.traitor
	for character: CharacterState in characters:
		if character.id == target_id:
			return character.current_health > 0 and character.traitor != actor.traitor
	return false

static func _target_name(combat: CombatState, characters: Array[CharacterState], target_id: String) -> String:
	var monster := combat.monster_by_id(target_id)
	if monster != null:
		return monster.name
	for character: CharacterState in characters:
		if character.id == target_id:
			return character.name
	return target_id

static func from_race(definition: RaceDefinition) -> DefinitionOptionView:
	var display_facts: Array[String] = [
		"Movement %d" % definition.base_movement,
	]
	var attack_fraction := _race_attack_fraction(definition.base_attacks)
	if not attack_fraction.is_empty():
		display_facts.append("Attacks %s • Maximum %d" % [attack_fraction, definition.maximum_attacks])
	_append_signed(display_facts, "Magic resistance", definition.magic_resistance)
	_append_signed(display_facts, "Missile adjustment", definition.missile_bonus)
	_append_signed(display_facts, "Two-hand adjustment", definition.two_hand_bonus)
	if definition.max_age > 0:
		display_facts.append("Maximum age %d" % definition.max_age)
	var attributes := _named_modifiers(definition.attribute_bonus, ["Brawn", "Knowledge", "Judgment", "Agility", "Vitality", "Luck"])
	if not attributes.is_empty():
		display_facts.append("Attributes • %s" % attributes)
	var saves := _named_modifiers(definition.save_bonus, ["Charm", "Fire", "Cold", "Shock", "Chemical", "Mental", "SP drain", "Special"])
	if not saves.is_empty():
		display_facts.append("Saves • %s" % saves)
	return DefinitionOptionView.new(definition.id, definition.name, definition.description, definition.eligible_caste_ids, display_facts)

func advance_minutes(minutes: int) -> bool:
	if minutes < 0:
		return false
	_total_minutes += minutes
	return true

func set_total_minutes(minutes: int) -> bool:
	if minutes < 0:
		return false
	_total_minutes = minutes
	return true

static func from_data(data: Variant) -> RealmzClock:
	if not data is Dictionary or not data.has("totalMinutes"):
		return null
	var minutes: int = data["totalMinutes"] if data["totalMinutes"] is int else int(data["totalMinutes"]) if data["totalMinutes"] is float and is_equal_approx(data["totalMinutes"], round(data["totalMinutes"])) else -1
	if minutes < 0:
		return null
	return RealmzClock.new(minutes)

func character(character_id: String) -> MoneyCharacterView:
	for option: MoneyCharacterView in characters:
		if option.character_id == character_id:
			return option
	return null

func monster_footprint(actor_id: String) -> Array[Vector2i]:
	var anchor := monster_position(actor_id)
	var size := monster_size(actor_id)
	var footprint: Array[Vector2i] = []
	if anchor.x < 0 or size < 0:
		return footprint
	return BattlefieldState.footprint_cells(anchor, size)

static func from_caste(definition: CasteDefinition) -> DefinitionOptionView:
	var display_facts: Array[String] = [
		"Stamina d%d initially • d%d per level" % [definition.initial_stamina_die(), definition.level_stamina_die()],
		"To hit %+d initially • %+d per level" % [definition.initial_to_hit(), definition.level_to_hit()],
		"Dodge %+d initially • %+d per level" % [definition.initial_dodge(), definition.level_dodge()],
	]
	if definition.can_use_missile:
		display_facts.append("Missile %+d initially • %+d per level" % [definition.initial_missile(), definition.level_missile()])
	else:
		display_facts.append("Cannot use missile weapons")
	display_facts.append("Hand to hand %+d initially • %+d per level" % [definition.initial_hand_to_hand(), definition.level_hand_to_hand()])
	if definition.minimum_age_group > 0:
		display_facts.append("Minimum age %s" % _minimum_age_label(definition.minimum_age_group))
	_append_signed(display_facts, "Movement", definition.movement_bonus)
	var attack_bonus := _caste_attack_fraction(definition.bonus_attacks)
	if not attack_bonus.is_empty():
		display_facts.append("Bonus attacks %s" % attack_bonus)
	_append_signed(display_facts, "Two-hand adjustment", definition.two_hand_bonus)
	_append_signed(display_facts, "Maximum stamina bonus", definition.maximum_stamina_bonus)
	if definition.magic_resistance_multiplier != 1:
		display_facts.append("Magic resistance ×%d" % definition.magic_resistance_multiplier)
	if definition.spellcaster_rows().any(func(row: Vector3i) -> bool: return row.y > 0):
		display_facts.append("Spellcaster")
	if definition.gets_missile_bonus:
		display_facts.append("Receives missile bonus")
	if definition.start_money != 0:
		display_facts.append("Starting gold %d" % definition.start_money)
	var attributes := _named_modifiers(definition.attribute_bonus, ["Brawn", "Knowledge", "Judgment", "Agility", "Vitality", "Luck"])
	if not attributes.is_empty():
		display_facts.append("Attributes • %s" % attributes)
	var saves := _named_modifiers(definition.save_bonus, ["Charm", "Fire", "Cold", "Shock", "Chemical", "Mental", "SP drain", "Special"])
	if not saves.is_empty():
		display_facts.append("Saves • %s" % saves)
	return DefinitionOptionView.new(definition.id, definition.name, definition.description, definition.eligible_race_ids, display_facts)

## Pen boards and implementation order

The active Pen document is the working composition source for the audit. Its representative family boards are:

- visual-audit overview;
- Startup & Party at `1280x720`;
- Character Creator Appearance at `1280x720`;
- Exploration & Interaction at `1280x720`;
- Inventory & Equipment at `1280x720`;
- Combat Spellbook at `1280x720`;
- Character Record at `1280x720`;
- Shop & Services at `1280x720`;
- Treasure Distribution at `1280x720`;
- Combat Command Stage at `1280x720`;
- System & Save at `800x600`.

These boards are screen-family composition contracts for all 59 audited surfaces, not a smaller replacement denominator. They establish pane ownership, hierarchy, fixed actions, original-art opportunities, and density. Closely related states reuse those contracts rather than receiving cosmetic variations. Additional compact boards are required only where the `800x600` information architecture materially differs.

Implementation proceeds in coherent batches:

1. Startup, scenario library, party assembly, Character Files, inspection, and all five creator steps.
2. Land/dungeon exploration, camp, scenario textbox/picture, choices, encounter commands, and typed pickers.
3. Character sheet, allies, inventory/equipment/trade, spellbook, and spell targeting.
4. Money, shop, temple, bank, combined treasure/fumble distribution, level-up, and ally selection.
5. Battle entry, tactical workspace, turn strip, commands, spellbook/targeting, playback, and terminal return.
6. Notes/maps, save/load, preferences, diagnostics, lifecycle, and failure surfaces.

Current remediation status:

- Batch 1 now structurally covers the splash, selected-scenario record, fixed package-progress stage, three-pane party assembly, full-stage Character Files library, setup/vault inspection, and all five creator stages at the canonical and compact composition contracts. S04 remains a host-contract blocker because terminal package diagnostics are not retained as typed categorized state; graphical acceptance remains pending for the recomposed surfaces.
- Batch 2 has recomposed and captured the full-width exploration footer, fixed-measure helper-free narrative interaction stage, camp/light/facing context, compact floating typed choices above the text well, transient save/journal status glyphs, six-command encounter strip, source-limited word entry, party-roster target selection, surviving-allies workspace, thief/item/spell pickers, restrained source-backed pick-lock stage, and exact-media age update. A representative dungeon stage and Providence-complete player maps remain open; live pointer and ordinary-campaign acceptance still own the final interaction proof.
- Batch 3 now covers the full-width Character, Allies, Inventory, and field Spellbook workspaces plus the mandatory party-target stage. Character gives its sheet, six-member portrait selector, dense tabs, and source-backed equipment icons priority while keeping formation editing secondary. Allies owns one read-only current-companion list and record with exact CICN media, source-backed combat facts, a concise empty state, and a deliberate stacked Classic reflow. Inventory now follows Castle's working-screen hierarchy with an icon-led pack, selected-character command rail, integrated six-member selector, full-width selected-item record, fixed action dock, item-local portrait Trade recipients with source-projected load, and one stable exact-item operation stage. Spellbook owns the Classic level/list/record/power hierarchy, scaled source facts, exact Cast/Abort and proven target art, two-column Fast Spell grid, five-slot scroll case, and fixed actions at both supported compositions. C09 now carries its authoritative caster/spell/power/cost/target display context through the strict saved interaction and uses the numbered Party roster rather than a generic picker; ordinary-play acceptance remains outstanding.
- Batch 4 now structurally covers Party Wealth, Shop Stock and Pack, Temple, Bank, ordinary/unidentified Treasure with leading fumbled instances, both Level-Up stages, and surviving-ally selection at the canonical and compact composition contracts. Compact service and reward evidence is reconstructed at `800x600` rather than resized from a wide instance. Item-bearing workflows now carry Castle's exact player-knowable CICN key and resolve shared application art with scenario-first precedence; service and wealth imagery remains absent where no typed identity is proven. Ordinary-play acceptance remains outstanding.
- Batch 5 now covers current canonical and compact captures for exact-icon Active/NOW/NEXT/Shown combat records, fixed two-row commands with restrained primary-action emphasis, distinct Reveal Friends and Shift-aid legends, the original Cast Spell/Abort controls, board-native target confirmation, no-blank battle entry, explicit Auto playback, and retained-board terminal cues. Ordinary-campaign timing, effects, sound, defeat/retreat, and exact-once return acceptance remain open and are not implied by fixture-gallery evidence.
- Batch 6 now covers populated Places, acquired Player Maps, authored Journal, valid and corrupt Save & Load records, every preference tab, compact 150% stress layout, and distinct End Adventure lifecycle choices at both supported compositions. H04 and the package/fatal portion of H06 remain explicit host-contract blockers rather than guessed screens. Ordinary-play and live pointer acceptance remain open because fixture captures do not certify host recovery or campaign transitions.

Repeated controls are components rather than independently styled mockups. Product implementation is complete only when its audit row reaches the acceptance contract below; a Pen board alone is not implementation or live evidence.

func transfer(denomination: StringName) -> MoneyTransferView:
	for option: MoneyTransferView in transfers:
		if option.denomination == denomination:
			return option
	return null

func _init(source_message_id: int, source_text: String) -> void:
	message_id = source_message_id
	text = source_text

func _add_name_restriction(prefix: String, names: Array[String]) -> void:
	if not names.is_empty():
		restrictions.append("%s %s." % [prefix, ", ".join(names)])

static func _named_modifiers(reader: Callable, labels: Array[String]) -> String:
	var values: Array[String] = []
	for index: int in labels.size():
		var value := int(reader.call(index))
		if value != 0:
			values.append("%s %+d" % [labels[index], value])
	return " • ".join(values)

static func _append_signed(target: Array[String], label: String, value: int) -> void:
	if value != 0:
		target.append("%s %s" % [label, "%+d" % value])

static func from_data(data: Variant) -> WealthState:
	if not data is Dictionary:
		return null
	var amounts: Array[int] = []
	for field: String in ["gold", "gems", "jewelry"]:
		if not data.has(field):
			return null
		var value := _integer(data[field])
		if value < 0:
			return null
		amounts.append(value)
	return WealthState.new(amounts[0], amounts[1], amounts[2])

func _add_numeric_fact(id: StringName, label: String, amount: int) -> void:
	if amount != 0:
		facts.append(ItemFactView.new(id, label, "%+d" % amount))

func _populate_properties(definition: ItemDefinition, content: RealmzContent) -> void:
	if not identified:
		return
	if curse_revealed:
		properties.append("The curse has been revealed; this equipped item cannot be removed normally.")
	if definition.heat + definition.cold + definition.electric + definition.vs_undead + definition.vs_demon_devil + definition.vs_evil != 0:
		properties.append("This weapon does special damage.")
	if definition.item_type < 0 or definition.item_type == 23 or definition.item_type == 25:
		properties.append("This special item belongs to this campaign and does not transfer to another campaign.")
	if definition.special_1 == 120:
		properties.append("This weapon always hits in combat.")
	elif definition.special_1 == 121:
		properties.append("This weapon doubles its magical to-hit bonus without doubling its damage bonus.")
	elif definition.special_1 == 122 and definition.special_2 in [1, 2, 3, 4]:
		var attack_labels: Array[String] = ["one-half", "one", "one and one-half", "two"]
		var attacks: String = attack_labels[definition.special_2 - 1]
		properties.append("Gives the character %s extra attack%s per combat round." % [attacks, "" if definition.special_2 == 2 else "s"])
	if definition.special_2 > 1100:
		var spell := content.spell_by_classic_id(definition.special_2) if content != null else null
		properties.append("Stores the spell %s." % (spell.name if spell != null else "Classic spell %d" % definition.special_2))
	if definition.special_3 < 0:
		properties.append("%+d to hit Classic monster type %d." % [definition.special_5, absi(definition.special_3)])
	elif definition.special_3 > 0 and definition.special_3 < 16:
		properties.append("%+d to %s." % [definition.special_5, _ability_name(definition.special_3)])
	if definition.special_4 > 0 and definition.special_4 < 16:
		properties.append("%+d to %s." % [definition.special_5, _ability_name(definition.special_4)])

func _populate_restrictions(definition: ItemDefinition, content: RealmzContent) -> void:
	if not definition.specific_caste_id.is_empty():
		var caste := content.caste_by_id(definition.specific_caste_id) if content != null else null
		restrictions.append("Usable only by %s." % (caste.name if caste != null else _display_id(definition.specific_caste_id)))
	if not definition.specific_race_id.is_empty():
		var race := content.race_by_id(definition.specific_race_id) if content != null else null
		restrictions.append("Usable only by %s." % (race.name if race != null else _display_id(definition.specific_race_id)))
	if content == null:
		if definition.caste_restrictions != 0:
			restrictions.append("Classic class restrictions apply.")
		if definition.race_restrictions != 0:
			restrictions.append("Classic race restrictions apply.")
		if definition.caste_class_only != 0:
			restrictions.append("Only selected Classic class groups may use this item.")
		if definition.race_class_only != 0:
			restrictions.append("Only selected Classic race groups may use this item.")
		return
	var excluded_castes: Array[String] = []
	var allowed_castes: Array[String] = []
	for caste: CasteDefinition in content.caste_definitions():
		var bit := 1 << (caste.caste_class - 1) if caste.caste_class > 0 else 0
		if bit != 0 and (definition.caste_restrictions & bit) != 0:
			excluded_castes.append(caste.name)
		if bit != 0 and (definition.caste_class_only & bit) != 0:
			allowed_castes.append(caste.name)
	_add_name_restriction("Not usable by", excluded_castes)
	_add_name_restriction("Usable only by", allowed_castes)
	var excluded_races: Array[String] = []
	var allowed_races: Array[String] = []
	for race: RaceDefinition in content.race_definitions():
		if (definition.race_restrictions & race.descriptor_flags) != 0:
			excluded_races.append(race.name)
		if definition.race_class_only != 0 and (definition.race_class_only & race.descriptor_flags) == definition.race_class_only:
			allowed_races.append(race.name)
	_add_name_restriction("Not usable by", excluded_races)
	_add_name_restriction("Usable only by", allowed_races)

func present_step(step: SessionStep) -> void:
	if step == null:
		return
	if step.state == SessionStep.State.FAILED:
		set_status("Action failed • %s" % step.error_message, true)
		_append_narrative("Action failed: %s" % step.error_message)
		return
	_picture_stage.visible = false
	for event: DomainEvent in step.events:
		_present_event(event)

static func automatic_workflow_route(current_route: StringName, game_view: GameView, contextual_service_closed: bool = false) -> StringName:
	if game_view == null:
		return current_route
	if game_view.pending_interaction != null and game_view.pending_interaction.kind in [InteractionRequest.SHOP, InteractionRequest.TEMPLE, InteractionRequest.BANK]:
		return &"services"
	if game_view.combat_view != null:
		return &"combat"
	if game_view.pending_interaction != null:
		return &"exploration"
	if contextual_service_closed and current_route == &"services":
		return &"exploration"
	if game_view.combat_view == null and current_route == &"combat":
		return &"exploration"
	return current_route

