func _construct_character_appearance_options(assets: Array[MediaAsset], races: Array[RaceDefinition]) -> Array[CharacterAppearanceDefinition]:
	var result: Array[CharacterAppearanceDefinition] = []
	for asset: MediaAsset in assets:
		var kind := CharacterAppearanceDefinition.PORTRAIT if asset.kind == "portrait" else CharacterAppearanceDefinition.COMBAT_ICON if asset.kind == "combat-icon" else &""
		if kind == &"":
			continue
		var recommended_races: Array[String] = []
		for race: RaceDefinition in races:
			var first_resource_id: int
			if kind == CharacterAppearanceDefinition.PORTRAIT:
				first_resource_id = 257 if race.default_icon_set == 0 else 251 + race.default_icon_set * 6
			else:
				first_resource_id = 9000 + (race.classic_id - 1) * 6
			if asset.resource_id >= first_resource_id and asset.resource_id < first_resource_id + 6:
				recommended_races.append(race.id)
		result.append(CharacterAppearanceDefinition.new(asset.id, asset.label, kind, asset.resource_id, recommended_races))
	result.sort_custom(func(left: CharacterAppearanceDefinition, right: CharacterAppearanceDefinition) -> bool: return left.classic_resource_id < right.classic_resource_id)
	return result

func read_bytes_batch(requested_assets: Array[MediaAsset]) -> Dictionary:
	var result: Dictionary = {}
	if requested_assets.is_empty():
		return result
	var archive := ZIPReader.new()
	if archive.open(package_path) != OK:
		return result
	for asset: MediaAsset in requested_assets:
		if asset == null or not _assets.has(asset):
			continue
		var bytes := archive.read_file(asset.path)
		if bytes.size() != asset.byte_count:
			continue
		var hashing := HashingContext.new()
		if hashing.start(HashingContext.HASH_SHA256) != OK or hashing.update(bytes) != OK:
			continue
		if hashing.finish().hex_encode() == asset.sha256:
			result[asset.id] = bytes
	archive.close()
	return result

func read_bytes(asset: MediaAsset) -> PackedByteArray:
	if asset == null or not _assets.has(asset):
		return PackedByteArray()
	var archive := ZIPReader.new()
	if archive.open(package_path) != OK:
		return PackedByteArray()
	var bytes := archive.read_file(asset.path)
	archive.close()
	if bytes.size() != asset.byte_count:
		return PackedByteArray()
	var hashing := HashingContext.new()
	if hashing.start(HashingContext.HASH_SHA256) != OK or hashing.update(bytes) != OK:
		return PackedByteArray()
	if hashing.finish().hex_encode() != asset.sha256:
		return PackedByteArray()
	return bytes

func validate_render_references(assets: Dictionary, world: Dictionary) -> bool:
	var tileset_ids: Dictionary = {}
	var image_ids: Dictionary = {}
	for asset: Dictionary in assets["assets"]:
		if asset["kind"] == "tileset":
			tileset_ids[asset["id"]] = true
		if asset["mimeType"] is String and asset["mimeType"].begins_with("image/"):
			image_ids[asset["id"]] = true
	if not world.get("maps") is Array:
		return _reject("World maps must be available for tileset validation.")
	for map: Variant in world["maps"]:
		if not map is Dictionary or map.get("topologyFormat") != "realmz2.compact-cell-rows.v2" or not map.get("cells") is Array:
			return _reject("World map is malformed during tileset validation.")
		for cell: Variant in map["cells"]:
			if not cell is Array or cell.size() != 13 or not cell[9] is String:
				return _reject("Topology render facts are malformed during tileset validation.")
			if not tileset_ids.has(cell[9]):
				return _reject("Topology references missing tileset asset '%s'." % cell[9])
			var overlay_asset_id: Variant = cell[10]
			if overlay_asset_id != null and (not overlay_asset_id is String or not image_ids.has(overlay_asset_id)):
				return _reject("Topology references missing image overlay asset '%s'." % overlay_asset_id)
	return true

func _is_installed_package_path(path: String, install_root: String) -> bool:
	var absolute_root := ProjectSettings.globalize_path(install_root).simplify_path().replace("\\", "/").trim_suffix("/").to_lower()
	var absolute_path := ProjectSettings.globalize_path(path).simplify_path().replace("\\", "/").to_lower()
	if not absolute_path.begins_with(absolute_root + "/"):
		return false
	var relative_path := absolute_path.trim_prefix(absolute_root + "/")
	var parts := relative_path.split("/", false)
	if parts.size() != 2 or not _safe_path_component(parts[0]) or not parts[1].ends_with(".realmz2"):
		return false
	return _is_sha256(parts[1].trim_suffix(".realmz2"))

func promote_installed_package(path: String) -> void:
	var receipt := _receipt_store.read(path)
	if receipt.is_empty() or not _receipt_store.validate_archive_sha256(receipt, _archive_reader.sha256_file(path)):
		return
	_package_cache.promote(_receipt_store.cache_key(path, receipt))

func load_package(path: String, progress_callback: Callable = Callable(), cancel_callback: Callable = Callable()) -> PackageLoadResult:
	_last_error = ""
	if _cancel_requested(cancel_callback):
		return PackageLoadResult.failed(&"package_cancelled", "Package operation cancelled.")
	_report_progress(progress_callback, &"opening", 0, 1)
	var archive := ZIPReader.new()
	var open_error := archive.open(path)
	if open_error != OK:
		return PackageLoadResult.failed("package_open_failed", "Could not open package '%s' (error %d)." % [path, open_error])
	var result := _load_open_archive(archive, path, progress_callback, cancel_callback)
	archive.close()
	if result.is_ok():
		_report_progress(progress_callback, &"complete", 1, 1)
	return result

func _load_installed_package(path: String, install_root: String, progress_callback: Callable = Callable(), cancel_callback: Callable = Callable()) -> PackageLoadResult:
	if not _is_installed_package_path(path, install_root):
		return null
	var receipt_path := PackageInstallReceiptStore.path_for(path)
	if not FileAccess.file_exists(receipt_path):
		return null
	_report_progress(progress_callback, &"checking-install", 0, 1)
	if _cancel_requested(cancel_callback):
		return PackageLoadResult.failed(&"package_cancelled", "Package operation cancelled.")
	var receipt := _receipt_store.read(path)
	if receipt.is_empty():
		return PackageLoadResult.failed(&"package_install_receipt_invalid", _receipt_store.last_error if not _receipt_store.last_error.is_empty() else "Installed package receipt is invalid.")
	_report_progress(progress_callback, &"checking-install-integrity", 0, 1)
	var archive_sha256 := _archive_reader.sha256_file(path)
	if not _receipt_store.validate_archive_sha256(receipt, archive_sha256):
		return PackageLoadResult.failed(&"package_install_receipt_invalid", _receipt_store.last_error)
	_report_progress(progress_callback, &"checking-install-integrity", 1, 1)
	if _cancel_requested(cancel_callback):
		return PackageLoadResult.failed(&"package_cancelled", "Package operation cancelled.")
	var cache_key := _receipt_store.cache_key(path, receipt)
	var cached := _package_cache.get_result(cache_key)
	if cached != null:
		_report_progress(progress_callback, &"complete", 1, 1)
		return cached
	var archive := ZIPReader.new()
	var open_error := archive.open(path)
	if open_error != OK:
		return PackageLoadResult.failed(&"package_open_failed", "Could not open installed package '%s' (error %d)." % [path, open_error])
	var result := _load_open_archive(archive, path, progress_callback, cancel_callback, receipt)
	archive.close()
	if result.is_ok():
		_package_cache.retain_candidate(cache_key, result)
		_report_progress(progress_callback, &"complete", 1, 1)
	return result

func load_bundled_package(path: String, expected_campaign_id: String, expected_package_hash: String) -> PackageLoadResult:
	_last_error = ""
	if expected_campaign_id.is_empty() or not _safe_path_component(expected_campaign_id) or not _is_sha256(expected_package_hash):
		return PackageLoadResult.failed(&"bundled_package_identity_invalid", "The bundled package identity is invalid.")
	var cache_key := "bundled:%s:%s:%s:%d" % [ProjectSettings.globalize_path(path).simplify_path(), expected_package_hash, EXPECTED_SCHEMA_HASH, DECODER_VERSION]
	var cached := _package_cache.get_result(cache_key)
	if cached != null:
		return cached
	var archive := ZIPReader.new()
	var open_error := archive.open(path)
	if open_error != OK:
		return PackageLoadResult.failed(&"package_open_failed", "Could not open bundled package '%s' (error %d)." % [path, open_error])
	# This immutable package is generated by Providence and its identity is pinned
	# in the application source. Release signing protects the shipped bytes, so
	# startup verifies the canonical manifest identity but does not rehash every
	# bundled portrait and combat icon on every launch.
	var trusted_identity := {
		"schemaHash": EXPECTED_SCHEMA_HASH,
		"campaignId": expected_campaign_id,
		"packageHash": expected_package_hash,
	}
	var result := _load_open_archive(archive, path, Callable(), Callable(), trusted_identity)
	archive.close()
	if result.is_ok():
		_package_cache.retain_candidate(cache_key, result)
	return result

func _receipt_matches_manifest(receipt: Dictionary, manifest: Dictionary) -> bool:
	if receipt["schemaHash"] != manifest["schemaHash"] or receipt["campaignId"] != manifest["campaignId"] or receipt["packageHash"] != manifest["packageHash"]:
		return _reject("Installed package manifest no longer matches its validated receipt.")
	return true

func _load_open_archive(archive: ZIPReader, source_path: String, progress_callback: Callable = Callable(), cancel_callback: Callable = Callable(), trusted_receipt: Dictionary = {}) -> PackageLoadResult:
	var archive_entries_value: Variant = _archive_reader.entries(archive)
	var archive_entries: Array[String] = []
	if archive_entries_value != null:
		archive_entries = archive_entries_value
	if archive_entries_value == null:
		return _validation_failure()
	var manifest_value: Variant = _archive_reader.read_document(archive, "manifest.json")
	if manifest_value == null:
		return _validation_failure()
	var manifest: Dictionary = manifest_value
	if trusted_receipt.is_empty() and (not _manifest_discovery.validate_structure(manifest, archive_entries) or not _archive_reader.validate_files(manifest, archive, progress_callback, cancel_callback)):
		_last_error = _manifest_discovery.last_error if not _manifest_discovery.last_error.is_empty() else _archive_reader.last_error
		return _validation_failure()
	if not trusted_receipt.is_empty() and (not _manifest_discovery.validate_structure(manifest, archive_entries) or not _receipt_matches_manifest(trusted_receipt, manifest)):
		if not _manifest_discovery.last_error.is_empty():
			_last_error = _manifest_discovery.last_error
		return _validation_failure()
	_report_progress(progress_callback, &"constructing-content", 0, 1)
	var content_value: Variant = _archive_reader.read_document(archive, "content.json")
	var world_value: Variant = _archive_reader.read_document(archive, "world.json")
	var scenario_value: Variant = _archive_reader.read_document(archive, "scenario.json")
	var asset_value: Variant = _archive_reader.read_document(archive, "assets/index.json")
	if content_value == null or world_value == null or scenario_value == null or asset_value == null:
		_last_error = _archive_reader.last_error
		return _validation_failure()
	var content_document: Dictionary = content_value
	var world_document: Dictionary = world_value
	var scenario_document: Dictionary = scenario_value
	var asset_document: Dictionary = asset_value
	if not _validate_document_header(content_document, "realmz2.content") or not _validate_document_header(world_document, "realmz2.world") or not _validate_document_header(scenario_document, "realmz2.scenario") or not _validate_document_header(asset_document, "realmz2.assets"):
		return _validation_failure()
	if trusted_receipt.is_empty():
		_media_validator.clear_error()
		if not _media_validator.validate_assets(asset_document, manifest["files"]):
			_last_error = _media_validator.error_message()
			return _validation_failure()
		if not _media_validator.validate_presentation_capabilities(manifest, asset_document):
			_last_error = _media_validator.error_message()
			return _validation_failure()
		if not _media_validator.validate_render_references(asset_document, world_document):
			_last_error = _media_validator.error_message()
			return _validation_failure()
	var runtime_assets := _media_validator.construct_assets(asset_document)
	var runtime_content := _domain_assembler.assemble(manifest, content_document, world_document, scenario_document, runtime_assets, not trusted_receipt.is_empty())
	if runtime_content == null:
		_last_error = _domain_assembler.error_message()
		return _validation_failure()
	return PackageLoadResult.succeeded(runtime_content, PackageMediaCatalog.new(source_path, manifest["packageHash"], runtime_assets))

static func package_capability_error(capability: Variant) -> String:
	if capability is String and DEFERRED_PACKAGE_CAPABILITIES.has(capability):
		return "Package requires sandboxed GDScript Scenario Actions, but no secure external host is available on this platform."
	if not capability is String or not SUPPORTED_CAPABILITIES.has(capability):
		return "Package requires unknown capability '%s'." % str(capability)
	return ""

func _validate_document_header(document: Dictionary, expected_kind: String) -> bool:
	if document.get("kind") != expected_kind or _integer(document.get("schemaVersion")) != 3:
		return _reject("Package document '%s' has an unsupported header." % expected_kind)
	return true

func _has_fields(value: Dictionary, fields: Array[String], label: String) -> bool:
	for field: String in fields:
		if not value.has(field):
			return _reject("%s is missing required field '%s'." % [label, field])
	return true

func _is_sha256(value: Variant) -> bool:
	if not value is String or value.length() != 64:
		return false
	for character: String in value:
		if not character in "0123456789abcdef":
			return false
	return true

func _reject(message: String) -> bool:
	_last_error = message
	return false

func _validation_failure() -> PackageLoadResult:
	if _last_error == "Package operation cancelled.":
		return PackageLoadResult.failed(&"package_cancelled", _last_error)
	return PackageLoadResult.failed("package_validation_failed", _last_error if not _last_error.is_empty() else "Package validation failed.")

func _report_progress(callback: Callable, phase: StringName, completed: int, total: int) -> void:
	if callback.is_valid():
		callback.call(phase, completed, total)

func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1

func install_package(source_path: String, install_root: String = "user://packages", progress_callback: Callable = Callable(), cancel_callback: Callable = Callable()) -> PackageInstallResult:
	var installed_source := _load_installed_package(source_path, install_root, progress_callback, cancel_callback)
	if installed_source != null:
		if installed_source.is_ok():
			_report_progress(progress_callback, &"complete", 1, 1)
			return PackageInstallResult.succeeded(source_path, installed_source)
		return PackageInstallResult.failed(installed_source.error_code, installed_source.error_message)
	_report_progress(progress_callback, &"validating-source", 0, 1)
	var source := load_package(source_path, progress_callback, cancel_callback)
	if not source.is_ok():
		return PackageInstallResult.failed(source.error_code, source.error_message)
	if _cancel_requested(cancel_callback):
		return PackageInstallResult.failed(&"package_cancelled", "Package operation cancelled.")
	if not _safe_path_component(source.content.campaign_id):
		return PackageInstallResult.failed("campaign_path_unsafe", "Campaign ID cannot be used as a portable installation path.")
	var campaign_root := install_root.trim_suffix("/").path_join(source.content.campaign_id)
	var create_error := DirAccess.make_dir_recursive_absolute(ProjectSettings.globalize_path(campaign_root))
	if create_error != OK:
		return PackageInstallResult.failed("package_install_directory_failed", "Could not create the package installation directory (error %d)." % create_error)
	var target_path := campaign_root.path_join("%s.realmz2" % source.content.package_hash)
	if FileAccess.file_exists(target_path):
		if _same_package_path(source_path, target_path):
			if not _receipt_store.write(target_path, source.content, _archive_reader.sha256_file(target_path)):
				return PackageInstallResult.failed("package_receipt_write_failed", "Could not write the validated package installation receipt.")
			_report_progress(progress_callback, &"complete", 1, 1)
			return PackageInstallResult.succeeded(target_path, source)
		var existing := _load_installed_package(target_path, install_root, progress_callback, cancel_callback)
		if existing == null:
			existing = load_package(target_path, progress_callback, cancel_callback)
			if existing.is_ok() and not _receipt_store.write(target_path, existing.content, _archive_reader.sha256_file(target_path)):
				return PackageInstallResult.failed("package_receipt_write_failed", "Could not write the validated package installation receipt.")
		if existing.is_ok() and existing.content.package_hash == source.content.package_hash:
			_report_progress(progress_callback, &"complete", 1, 1)
			return PackageInstallResult.succeeded(target_path, existing)
		return PackageInstallResult.failed("package_install_collision", "An invalid package already occupies the immutable installation path.")
	_report_progress(progress_callback, &"copying-package", 0, 1)
	var temporary_path := target_path + ".installing"
	if FileAccess.file_exists(temporary_path):
		DirAccess.remove_absolute(ProjectSettings.globalize_path(temporary_path))
	var source_bytes := FileAccess.get_file_as_bytes(source_path)
	if source_bytes.is_empty():
		return PackageInstallResult.failed("package_install_read_failed", "Could not read the source package for installation.")
	var temporary := FileAccess.open(temporary_path, FileAccess.WRITE)
	if temporary == null:
		return PackageInstallResult.failed("package_install_write_failed", "Could not open the temporary package installation file.")
	temporary.store_buffer(source_bytes)
	temporary.flush()
	temporary.close()
	if _cancel_requested(cancel_callback):
		DirAccess.remove_absolute(ProjectSettings.globalize_path(temporary_path))
		return PackageInstallResult.failed(&"package_cancelled", "Package operation cancelled.")
	_report_progress(progress_callback, &"validating-install", 0, 1)
	var archive_sha256 := _archive_reader.sha256(source_bytes)
	var installed_bytes := FileAccess.get_file_as_bytes(temporary_path)
	if installed_bytes.size() != source_bytes.size() or _archive_reader.sha256(installed_bytes) != archive_sha256:
		DirAccess.remove_absolute(ProjectSettings.globalize_path(temporary_path))
		return PackageInstallResult.failed("package_install_readback_failed", "Temporary package installation failed byte-for-byte readback validation.")
	var rename_error := DirAccess.rename_absolute(ProjectSettings.globalize_path(temporary_path), ProjectSettings.globalize_path(target_path))
	if rename_error != OK:
		DirAccess.remove_absolute(ProjectSettings.globalize_path(temporary_path))
		return PackageInstallResult.failed("package_install_commit_failed", "Could not atomically install the verified package (error %d)." % rename_error)
	if not _receipt_store.write(target_path, source.content, archive_sha256):
		DirAccess.remove_absolute(ProjectSettings.globalize_path(target_path))
		return PackageInstallResult.failed("package_receipt_write_failed", "Could not write the validated package installation receipt.")
	var installed := PackageLoadResult.succeeded(source.content, PackageMediaCatalog.new(target_path, source.content.package_hash, source.media.assets()))
	var receipt := _receipt_store.read(target_path)
	if not receipt.is_empty():
		_package_cache.retain_candidate(_receipt_store.cache_key(target_path, receipt), installed)
	_report_progress(progress_callback, &"complete", 1, 1)
	return PackageInstallResult.succeeded(target_path, installed)

func _safe_path_component(value: String) -> bool:
	if value.is_empty() or value.length() > 128:
		return false
	for index: int in value.length():
		var code := value.unicode_at(index)
		var valid := (code >= 48 and code <= 57) or (code >= 65 and code <= 90) or (code >= 97 and code <= 122) or code == 45 or code == 95
		if not valid:
			return false
	return true

func validate_presentation_capabilities(manifest: Dictionary, assets: Dictionary) -> bool:
	var declares_battle_atlas: bool = manifest["capabilities"].has("realmz.presentation.battle-atlas-v1")
	var battle_atlas_count := 0
	for asset: Dictionary in assets["assets"]:
		if asset["kind"] == "battle-tileset":
			battle_atlas_count += 1
	if declares_battle_atlas != (battle_atlas_count == 1):
		return _reject("Battle-atlas capability and packaged battle artwork do not agree.")
	return true

func _validate_monster_media(monsters: Array[MonsterDefinition], media_assets: Array[MediaAsset]) -> bool:
	var assets_by_resource: Dictionary = {}
	for asset: MediaAsset in media_assets:
		if not asset.resource_type.is_empty():
			assets_by_resource[JSON.stringify([asset.resource_type, asset.resource_id])] = asset
	for monster: MonsterDefinition in monsters:
		if monster.icon_id <= 0:
			continue
		var asset := assets_by_resource.get(JSON.stringify(["cicn", monster.icon_id])) as MediaAsset
		if asset == null or asset.mime_type != "image/png" or asset.width < 1 or asset.height < 1:
			return _reject("Monster '%s' requires unavailable Classic cicn %d." % [monster.id, monster.icon_id])
	return true

func validate_assets(document: Dictionary, files: Dictionary) -> bool:
	if not document.get("assets") is Array:
		return _reject("Asset index must contain an assets array.")
	var ids: Dictionary = {}
	var resources: Dictionary = {}
	var portrait_resource_ids: Dictionary = {}
	var combat_icon_resource_ids: Dictionary = {}
	for asset: Variant in document["assets"]:
		if not asset is Dictionary or not _exact_fields(asset, ["id", "label", "kind", "mimeType", "resourceType", "resourceId", "bytes", "sha256", "path", "width", "height", "durationMs", "sampleRate", "channels", "tileWidth", "tileHeight", "columns", "rows", "landlook", "baseTile"]):
			return _reject("Asset index contains a malformed record.")
		if not asset["id"] is String or asset["id"].is_empty() or ids.has(asset["id"]) or not asset["label"] is String or not asset["kind"] is String:
			return _reject("Asset identities, labels, and kinds must be typed and unique.")
		ids[asset["id"]] = true
		if asset["mimeType"] != null and not asset["mimeType"] is String:
			return _reject("Asset MIME type must be a string or null.")
		if asset["resourceType"] != null and not asset["resourceType"] is String:
			return _reject("Asset resource type must be a string or null.")
		if asset["resourceId"] != null and not _is_integer(asset["resourceId"]):
			return _reject("Asset resource ID must be an integer or null.")
		for optional_integer: String in ["width", "height", "durationMs", "sampleRate", "channels", "tileWidth", "tileHeight", "columns", "rows", "landlook", "baseTile"]:
			if asset[optional_integer] != null and (not _is_integer(asset[optional_integer]) or _integer(asset[optional_integer]) < 0):
				return _reject("Asset %s must be a non-negative integer or null." % optional_integer)
		if asset["kind"] in ["tileset", "battle-tileset"]:
			for tileset_field: String in ["width", "height", "tileWidth", "tileHeight", "columns", "rows"]:
				if asset[tileset_field] == null or _integer(asset[tileset_field]) < 1:
					return _reject("Tileset asset '%s' has invalid %s metadata." % [asset["id"], tileset_field])
			if not String(asset["mimeType"]).begins_with("image/") or _integer(asset["width"]) != _integer(asset["tileWidth"]) * _integer(asset["columns"]) or _integer(asset["height"]) != _integer(asset["tileHeight"]) * _integer(asset["rows"]):
				return _reject("Tileset asset '%s' dimensions do not match its atlas grid." % asset["id"])
		if asset["kind"] == "battle-tileset" and (asset["id"] != "classic-battle-tiles-302" or asset["mimeType"] != "image/png" or asset["resourceType"] != null or asset["resourceId"] != null or _integer(asset["width"]) != 640 or _integer(asset["height"]) != 640 or _integer(asset["tileWidth"]) != 32 or _integer(asset["tileHeight"]) != 32 or _integer(asset["columns"]) != 20 or _integer(asset["rows"]) != 20):
			return _reject("Classic battle atlas must be the role-specific 640 by 640 PICT 302 tile grid.")
		if not _is_integer(asset["bytes"]) or _integer(asset["bytes"]) < 0 or not asset["path"] is String or not _is_sha256(asset["sha256"]) or not files.has(asset["path"]):
			return _reject("Asset index contains a malformed or untracked payload.")
		if not asset["path"].begins_with("assets/media/") or files[asset["path"]]["sha256"] != asset["sha256"] or _integer(files[asset["path"]]["bytes"]) != _integer(asset["bytes"]):
			return _reject("Asset payload identity does not match the manifest.")
		if asset["resourceType"] != null and asset["resourceId"] != null:
			var resource_key := JSON.stringify([asset["resourceType"], _integer(asset["resourceId"])])
			if resources.has(resource_key):
				return _reject("Asset resource identities must be unique.")
			resources[resource_key] = true
			if asset["resourceType"] == "cicn" and asset["kind"] == "portrait":
				portrait_resource_ids[_integer(asset["resourceId"])] = true
			if asset["resourceType"] == "cicn" and asset["kind"] == "combat-icon":
				combat_icon_resource_ids[_integer(asset["resourceId"])] = true
		if asset["kind"] in ["portrait", "combat-icon"]:
			if asset["resourceType"] != "cicn" or asset["resourceId"] == null or asset["mimeType"] != "image/png" or asset["width"] == null or _integer(asset["width"]) < 1 or asset["height"] == null or _integer(asset["height"]) < 1:
				return _reject("Character appearance asset '%s' must be a decoded Classic cicn PNG with positive dimensions." % asset["id"])
	for resource_id: int in range(257, 377):
		if not portrait_resource_ids.has(resource_id):
			return _reject("Character portrait catalog is missing Classic cicn %d." % resource_id)
	for resource_id: int in range(9000, 9120):
		if not combat_icon_resource_ids.has(resource_id):
			return _reject("Character combat-icon catalog is missing Classic cicn %d." % resource_id)
	return true

static func _attacks_per_round(total: int) -> String:
	if total >= 2 and total <= 19:
		return "%d/%d" % [floori(float(total) / 2.0) if total % 2 == 0 else total, 1 if total % 2 == 0 else 2]
	if total > 12:
		return ">/10"
	return "1/1"

extends RealmzTestCase

const FIXTURE_PATH: String = "res://tests/fixtures/packages/realmz2-synthetic-fixture.realmz2"
const CORRECTION_PATH: String = "res://tests/fixtures/oracle/money-share-capacity-correction.json"
const DEPARTURE_OBSERVATION_PATH: String = "res://tests/fixtures/oracle/classic-pooled-wealth-departure-source-observation.json"


func selected_case_arguments() -> Array:
	var loaded := PackageRepository.new().load_package(FIXTURE_PATH)
	assert_true(loaded.is_ok(), "money workflow starts from the validated package fixture")
	return [loaded.content] if loaded.is_ok() else []


func run() -> void:
	_test_share_capacity_correction()
	_test_pooled_departure_source_observation()
	var loaded := PackageRepository.new().load_package(FIXTURE_PATH)
	assert_true(loaded.is_ok(), "money workflow starts from the validated package fixture")
	if not loaded.is_ok():
		return
	_test_session_money_workflow(loaded.content)
	_test_pooled_wealth_departure(loaded.content)


func _test_pooled_departure_source_observation() -> void:
	var fixture: Variant = JSON.parse_string(FileAccess.get_file_as_string(DEPARTURE_OBSERVATION_PATH))
	assert_true(fixture is Dictionary, "pooled-wealth departure source observation parses")
	if not fixture is Dictionary:
		return
	assert_equal(fixture.get("caseId"), "economy.pooled-wealth-departure", "the source observation remains linked to its differential case")
	var branches: Array = fixture.get("branches", [])
	assert_equal(branches.size(), 2, "the source observation owns both no-bank choices")
	if branches.size() == 2:
		assert_true(String(branches[0].get("outcome", "")).contains("continue"), "declining distribution continues ordinary movement")
		assert_true(String(branches[1].get("outcome", "")).contains("continue"), "accepted distribution continues the ordinary caller")
	var moveparty_source := (fixture.get("sources", []) as Array).filter(func(source: Dictionary) -> bool: return String(source.get("path", "")).ends_with("moveparty.c"))
	assert_equal(moveparty_source.size(), 1, "the observation distinguishes the internal moveparty fallback")
	if moveparty_source.size() == 1:
		assert_true(String(moveparty_source[0].get("observation", "")).contains("fallback"), "the internal early-return path is not generalized to ordinary travel")


func _test_share_capacity_correction() -> void:
	var fixture: Variant = JSON.parse_string(FileAccess.get_file_as_string(CORRECTION_PATH))
	assert_true(fixture is Dictionary, "FD-ECONOMY-003 source observation fixture parses")
	if not fixture is Dictionary:
		return
	assert_true(bool(fixture["castleSourceObservation"]["shareAssignmentAllowed"]), "Castle Share admits jewelry when only one load unit remains")
	assert_equal(int(fixture["castleSourceObservation"]["shareResultingLoad"]), 114, "Castle Share can exceed maximum load by fourteen")
	var character := CharacterState.new("money.capacity", "Capacity", 10, 10)
	character.carried_load = 99
	character.maximum_load = 100
	var characters: Array[CharacterState] = [character]
	var party := PartyState.new("map.capacity", Vector2i.ZERO, characters)
	party.pooled_wealth.jewelry = 1
	var rules := EconomyRules.new()
	var probe := rules.share_probe(party)
	assert_false(probe.allowed, "FD-ECONOMY-003 requires the complete jewelry weight to fit")
	assert_false(rules.share_pooled_wealth(party), "capacity-blocked Share commits no partial mutation")
	assert_equal([character.carried_load, character.money.jewelry, party.pooled_wealth.jewelry], [99, 0, 1], "the corrected result preserves load and pooled jewelry")


func _test_session_money_workflow(content: RealmzContent) -> void:
	var session := GameSession.new()
	assert_equal(session.start(content, 107).state, SessionStep.State.COMPLETED, "money session starts")
