param(
    [Parameter(Mandatory = $true)]
    [string]$ResourceForkPath,

    [Parameter(Mandatory = $true)]
    [string]$DestinationRoot
)

$ErrorActionPreference = "Stop"
Add-Type -AssemblyName System.Drawing

function Get-U16BE([byte[]]$Bytes, [int]$Offset) {
    if ($Offset -lt 0 -or $Offset + 2 -gt $Bytes.Length) { throw "16-bit read exceeds input at $Offset" }
    return ([int]$Bytes[$Offset] -shl 8) -bor [int]$Bytes[$Offset + 1]
}

function Get-I16BE([byte[]]$Bytes, [int]$Offset) {
    $value = Get-U16BE $Bytes $Offset
    if ($value -ge 0x8000) { return $value - 0x10000 }
    return $value
}

function Get-U32BE([byte[]]$Bytes, [int]$Offset) {
    if ($Offset -lt 0 -or $Offset + 4 -gt $Bytes.Length) { throw "32-bit read exceeds input at $Offset" }
    return ([uint32]$Bytes[$Offset] -shl 24) -bor
        ([uint32]$Bytes[$Offset + 1] -shl 16) -bor
        ([uint32]$Bytes[$Offset + 2] -shl 8) -bor
        [uint32]$Bytes[$Offset + 3]
}

function Get-ClassicResource([byte[]]$Bytes, [string]$ResourceType, [int]$ResourceId) {
    if ($Bytes.Length -lt 32) { throw "Classic resource fork is truncated" }
    $dataOffset = [int](Get-U32BE $Bytes 0)
    $mapOffset = [int](Get-U32BE $Bytes 4)
    if ($mapOffset + 28 -gt $Bytes.Length) { throw "Classic resource map is truncated" }
    $typeListOffset = $mapOffset + (Get-U16BE $Bytes ($mapOffset + 24))
    $rawTypeCount = Get-U16BE $Bytes $typeListOffset
    if ($rawTypeCount -eq 0xFFFF) { throw "Classic resource fork contains no resources" }

    for ($typeIndex = 0; $typeIndex -le $rawTypeCount; $typeIndex++) {
        $typeOffset = $typeListOffset + 2 + ($typeIndex * 8)
        $typeName = [Text.Encoding]::ASCII.GetString($Bytes, $typeOffset, 4)
        if ($typeName -ne $ResourceType) { continue }
        $rawResourceCount = Get-U16BE $Bytes ($typeOffset + 4)
        $referenceListOffset = $typeListOffset + (Get-U16BE $Bytes ($typeOffset + 6))
        for ($referenceIndex = 0; $referenceIndex -le $rawResourceCount; $referenceIndex++) {
            $referenceOffset = $referenceListOffset + ($referenceIndex * 12)
            if ((Get-I16BE $Bytes $referenceOffset) -ne $ResourceId) { continue }
            $relativeDataOffset = ([int]$Bytes[$referenceOffset + 5] -shl 16) -bor
                ([int]$Bytes[$referenceOffset + 6] -shl 8) -bor
                [int]$Bytes[$referenceOffset + 7]
            $lengthOffset = $dataOffset + $relativeDataOffset
            $length = [int](Get-U32BE $Bytes $lengthOffset)
            if ($lengthOffset + 4 + $length -gt $Bytes.Length) { throw "Classic resource payload is truncated" }
            $result = [byte[]]::new($length)
            [Array]::Copy($Bytes, $lengthOffset + 4, $result, 0, $length)
            return $result
        }
    }
    throw "Classic resource $ResourceType $ResourceId was not found"
}

function Get-UnicodeCodepoint([Text.Encoding]$MacRoman, [int]$ClassicCode) {
    $text = $MacRoman.GetString([byte[]]@([byte]$ClassicCode))
    if ([string]::IsNullOrEmpty($text)) { return $null }
    return [char]::ConvertToUtf32($text, 0)
}

$resourceFork = [IO.File]::ReadAllBytes((Resolve-Path -LiteralPath $ResourceForkPath))
$fontData = Get-ClassicResource $resourceFork "FONT" 1601
if ($fontData.Length -ne 2942) { throw "Theldrow FONT 1601 has unexpected length $($fontData.Length)" }

$typeFlags = Get-U16BE $fontData 0
$firstCharacter = Get-U16BE $fontData 2
$lastCharacter = Get-U16BE $fontData 4
$maximumWidth = Get-U16BE $fontData 6
$maximumKerning = Get-I16BE $fontData 8
$rectangleWidth = Get-U16BE $fontData 12
$rectangleHeight = Get-U16BE $fontData 14
$maximumAscent = Get-I16BE $fontData 18
$maximumDescent = Get-I16BE $fontData 20
$leading = Get-I16BE $fontData 22
$bitmapRowWords = Get-U16BE $fontData 24
if (($typeFlags -band 0x000C) -ne 0) { throw "Only the original monochrome Theldrow strike is supported" }
if ($firstCharacter -ne 0 -or $lastCharacter -ne 216 -or $rectangleHeight -ne 15 -or $bitmapRowWords -ne 68) {
    throw "Theldrow FONT 1601 metrics do not match the pinned Castle resource"
}

$bitmapOffset = 26
$bitmapRowBytes = $bitmapRowWords * 2
$bitmapLength = $bitmapRowBytes * $rectangleHeight
$glyphCountWithMissing = ($lastCharacter + 2) - $firstCharacter
$locationTableOffset = $bitmapOffset + $bitmapLength
$widthTableOffset = $locationTableOffset + (($glyphCountWithMissing + 1) * 2)
if ($widthTableOffset + ($glyphCountWithMissing * 2) -gt $fontData.Length) { throw "Theldrow metric tables are truncated" }

$locations = [int[]]::new($glyphCountWithMissing + 1)
for ($index = 0; $index -lt $locations.Length; $index++) {
    $locations[$index] = Get-U16BE $fontData ($locationTableOffset + ($index * 2))
}

$destination = [IO.Path]::GetFullPath($DestinationRoot)
[IO.Directory]::CreateDirectory($destination) | Out-Null
$atlasPath = Join-Path $destination "Theldrow-Classic.png"
$descriptorPath = Join-Path $destination "Theldrow-Classic.fnt"
$atlasWidth = $bitmapRowWords * 16
$atlas = [Drawing.Bitmap]::new($atlasWidth, $rectangleHeight, [Drawing.Imaging.PixelFormat]::Format32bppArgb)
try {
    $transparent = [Drawing.Color]::FromArgb(0, 255, 255, 255)
    $opaque = [Drawing.Color]::FromArgb(255, 255, 255, 255)
    for ($y = 0; $y -lt $rectangleHeight; $y++) {
        for ($x = 0; $x -lt $atlasWidth; $x++) {
            $byteOffset = $bitmapOffset + ($y * $bitmapRowBytes) + [int][Math]::Floor($x / 8)
            $mask = 1 -shl (7 - ($x % 8))
            $atlas.SetPixel($x, $y, $(if (($fontData[$byteOffset] -band $mask) -ne 0) { $opaque } else { $transparent }))
        }
    }
    $atlas.Save($atlasPath, [Drawing.Imaging.ImageFormat]::Png)
}
finally {
    $atlas.Dispose()
}

$macRoman = [Text.Encoding]::GetEncoding(10000)
$characters = [Collections.Generic.List[string]]::new()
$seenCodepoints = [Collections.Generic.HashSet[int]]::new()
for ($index = 0; $index -lt ($glyphCountWithMissing - 1); $index++) {
    $classicCode = $firstCharacter + $index
    $unicodeCodepoint = Get-UnicodeCodepoint $macRoman $classicCode
    if ($null -eq $unicodeCodepoint -or $unicodeCodepoint -lt 32 -or -not $seenCodepoints.Add($unicodeCodepoint)) { continue }
    $glyphStart = $locations[$index]
    $glyphWidth = $locations[$index + 1] - $glyphStart
    $drawingOffset = [int]$fontData[$widthTableOffset + ($index * 2)]
    if ($drawingOffset -ge 128) { $drawingOffset -= 256 }
    $advance = [int]$fontData[$widthTableOffset + ($index * 2) + 1]
    if ($drawingOffset -eq -1 -and $advance -eq 255) { continue }
    $characters.Add("char id=$unicodeCodepoint x=$glyphStart y=0 width=$glyphWidth height=$rectangleHeight xoffset=$drawingOffset yoffset=0 xadvance=$advance page=0 chnl=15")
}

$lines = [Collections.Generic.List[string]]::new()
$lines.Add("info face=`"Theldrow Classic`" size=$rectangleHeight bold=0 italic=0 charset=`"MacRoman`" unicode=1 stretchH=100 smooth=0 aa=0 padding=0,0,0,0 spacing=0,0 outline=0")
$lines.Add("common lineHeight=$($rectangleHeight + $leading) base=$maximumAscent scaleW=$atlasWidth scaleH=$rectangleHeight pages=1 packed=0 alphaChnl=0 redChnl=4 greenChnl=4 blueChnl=4")
$lines.Add("page id=0 file=`"Theldrow-Classic.png`"")
$lines.Add("chars count=$($characters.Count)")
$lines.AddRange($characters)
[IO.File]::WriteAllText($descriptorPath, (($lines -join "`n") + "`n"), [Text.UTF8Encoding]::new($false))

$sha = [Security.Cryptography.SHA256]::Create()
try { $payloadHash = ([BitConverter]::ToString($sha.ComputeHash($fontData))).Replace("-", "").ToLowerInvariant() } finally { $sha.Dispose() }
Write-Host "Exported exact Theldrow FONT 1601: $($characters.Count) Unicode glyphs; ${atlasWidth}x${rectangleHeight}; ascent $maximumAscent; descent $maximumDescent; leading $leading; max width $maximumWidth; max kerning $maximumKerning; payload SHA-256 $payloadHash."

param(
    [Parameter(Mandatory = $true)]
    [string]$ResourceForkPath,
    [Parameter(Mandatory = $true)]
    [int]$ResourceId,
    [Parameter(Mandatory = $true)]
    [string]$OutputPath
)

$ErrorActionPreference = "Stop"

function Get-U16([byte[]]$Bytes, [int]$Offset) {
    return ([int]$Bytes[$Offset] -shl 8) -bor [int]$Bytes[$Offset + 1]
}

function Get-I16([byte[]]$Bytes, [int]$Offset) {
    $value = Get-U16 $Bytes $Offset
    if ($value -ge 0x8000) {
        return $value - 0x10000
    }
    return $value
}

function Get-U32([byte[]]$Bytes, [int]$Offset) {
    return ([uint32]$Bytes[$Offset] -shl 24) -bor ([uint32]$Bytes[$Offset + 1] -shl 16) -bor ([uint32]$Bytes[$Offset + 2] -shl 8) -bor [uint32]$Bytes[$Offset + 3]
}

function Get-ResourceBytes([byte[]]$ForkBytes, [string]$ResourceType, [int]$WantedId) {
    if ($ForkBytes.Length -lt 32) {
        throw "Resource fork is too short"
    }
    $dataOffset = [int](Get-U32 $ForkBytes 0)
    $mapOffset = [int](Get-U32 $ForkBytes 4)
    $typeListOffset = $mapOffset + (Get-U16 $ForkBytes ($mapOffset + 24))
    $rawTypeCount = Get-U16 $ForkBytes $typeListOffset
    if ($rawTypeCount -eq 0xffff) {
        throw "Resource fork has no resource types"
    }
    for ($typeIndex = 0; $typeIndex -le $rawTypeCount; $typeIndex++) {
        $typeOffset = $typeListOffset + 2 + $typeIndex * 8
        $type = [Text.Encoding]::ASCII.GetString($ForkBytes, $typeOffset, 4)
        if ($type -ne $ResourceType) {
            continue
        }
        $rawResourceCount = Get-U16 $ForkBytes ($typeOffset + 4)
        $referenceListOffset = $typeListOffset + (Get-U16 $ForkBytes ($typeOffset + 6))
        for ($referenceIndex = 0; $referenceIndex -le $rawResourceCount; $referenceIndex++) {
            $referenceOffset = $referenceListOffset + $referenceIndex * 12
            if ((Get-I16 $ForkBytes $referenceOffset) -ne $WantedId) {
                continue
            }
            $relativeOffset = ([int]$ForkBytes[$referenceOffset + 5] -shl 16) -bor ([int]$ForkBytes[$referenceOffset + 6] -shl 8) -bor [int]$ForkBytes[$referenceOffset + 7]
            $lengthOffset = $dataOffset + $relativeOffset
            $length = [int](Get-U32 $ForkBytes $lengthOffset)
            $resource = [byte[]]::new($length)
            [Array]::Copy($ForkBytes, $lengthOffset + 4, $resource, 0, $length)
            return $resource
        }
    }
    throw "Resource $ResourceType $WantedId was not found"
}

function Export-CicnPng([byte[]]$Cicn, [string]$Destination) {
    if ($Cicn.Length -lt 82) {
        throw "cicn resource is too short"
    }
    $rowBytes = (Get-U16 $Cicn 4) -band 0x3fff
    $width = (Get-I16 $Cicn 12) - (Get-I16 $Cicn 8)
    $height = (Get-I16 $Cicn 10) - (Get-I16 $Cicn 6)
    $pixelSize = Get-U16 $Cicn 32
    $maskRowBytes = (Get-U16 $Cicn 54) -band 0x3fff
    $maskHeight = (Get-I16 $Cicn 60) - (Get-I16 $Cicn 56)
    if ($maskHeight -le 0) {
        $maskHeight = $height
    }
    $bitmapRowBytes = (Get-U16 $Cicn 68) -band 0x3fff
    $bitmapHeight = (Get-I16 $Cicn 74) - (Get-I16 $Cicn 70)
    if ($width -le 0 -or $height -le 0 -or $width -gt 512 -or $height -gt 512 -or $pixelSize -notin @(1, 2, 4, 8)) {
        throw "Unsupported cicn geometry"
    }

    $maskOffset = 82
    $bitmapOffset = $maskOffset + $maskRowBytes * $maskHeight
    $colorTableOffset = $bitmapOffset + $bitmapRowBytes * $bitmapHeight
    $colorTableFlags = Get-U16 $Cicn ($colorTableOffset + 4)
    $colorCount = (Get-U16 $Cicn ($colorTableOffset + 6)) + 1
    $pixelDataOffset = $colorTableOffset + 8 + $colorCount * 8
    if ($colorCount -lt 1 -or $pixelDataOffset + $rowBytes * $height -gt $Cicn.Length) {
        throw "cicn resource is truncated"
    }

    $colors = @{}
    $orderedColors = @()
    for ($index = 0; $index -lt $colorCount; $index++) {
        $offset = $colorTableOffset + 8 + $index * 8
        $colorNumber = Get-U16 $Cicn $offset
        $color = @(
            [Math]::Floor((Get-U16 $Cicn ($offset + 2)) / 257.0),
            [Math]::Floor((Get-U16 $Cicn ($offset + 4)) / 257.0),
            [Math]::Floor((Get-U16 $Cicn ($offset + 6)) / 257.0)
        )
        $colors[$colorNumber] = $color
        $orderedColors += ,$color
    }

    Add-Type -AssemblyName System.Drawing
    $bitmap = [Drawing.Bitmap]::new($width, $height, [Drawing.Imaging.PixelFormat]::Format32bppArgb)
    try {
        for ($y = 0; $y -lt $height; $y++) {
            for ($x = 0; $x -lt $width; $x++) {
                $pixelByte = $Cicn[$pixelDataOffset + $y * $rowBytes + [Math]::Floor($x * $pixelSize / 8)]
                $shift = 8 - $pixelSize - (($x * $pixelSize) % 8)
                $colorIndex = ($pixelByte -shr $shift) -band ((1 -shl $pixelSize) - 1)
                $rgb = if (($colorTableFlags -band 0x8000) -ne 0) { $orderedColors[$colorIndex] } else { $colors[$colorIndex] }
                if ($null -eq $rgb) {
                    $rgb = @(0, 0, 0)
                }
                $maskByte = $Cicn[$maskOffset + $y * $maskRowBytes + [Math]::Floor($x / 8)]
                $alpha = if ((($maskByte -shr (7 - ($x % 8))) -band 1) -eq 1) { 255 } else { 0 }
                $bitmap.SetPixel($x, $y, [Drawing.Color]::FromArgb($alpha, $rgb[0], $rgb[1], $rgb[2]))
            }
        }
        $parent = Split-Path -Parent $Destination
        if ($parent) {
            New-Item -ItemType Directory -Path $parent -Force | Out-Null
        }
        $bitmap.Save($Destination, [Drawing.Imaging.ImageFormat]::Png)
    }
    finally {
        $bitmap.Dispose()
    }
}

$resolvedResourceFork = (Resolve-Path -LiteralPath $ResourceForkPath).Path
$forkBytes = [IO.File]::ReadAllBytes($resolvedResourceFork)
$cicnBytes = Get-ResourceBytes $forkBytes "cicn" $ResourceId
Export-CicnPng $cicnBytes $OutputPath

extends SceneTree

const PACKAGE_REPOSITORY_SCRIPT := preload("res://src/infrastructure/packages/package_repository.gd")


func _initialize() -> void:
	var arguments := OS.get_cmdline_user_args()
	if arguments.size() != 1:
		printerr("Usage: godot --headless --path <project> --script res://tools/movement_performance_probe.gd -- <package.realmz2>")
		call_deferred("_quit_cleanly", 2)
		return
	var loaded := PACKAGE_REPOSITORY_SCRIPT.new().load_package(arguments[0])
	if not loaded.is_ok():
		printerr("PACKAGE_REJECTED %s: %s" % [loaded.error_code, loaded.error_message])
		call_deferred("_quit_cleanly", 1)
		return
	var session := GameSession.new()
	var step := session.start(loaded.content, 1)
	if step.state == SessionStep.State.FAILED or not _assemble_six_character_party(session, loaded.content):
		printerr("SESSION_REJECTED: a six-character public setup could not be prepared")
		call_deferred("_quit_cleanly", 1)
		return
	var pair := _safe_movement_pair(session, loaded.content)
	if pair.is_empty() or not _place_party(session, loaded.content, pair["origin"]):
		printerr("SESSION_REJECTED: no trigger-free movement pair is available")
		call_deferred("_quit_cleanly", 1)
		return
	var direction: Vector2i = pair["direction"]
	var transaction_samples: Array[int] = []
	var projection_samples: Array[int] = []
	var event_kinds: Array[String] = []
	var event_sequences: Dictionary = {}
	var fatigue_payload: Dictionary = {}
	var ordinary_projection_count := 0
	for index: int in 60:
		var previous_view := session.view()
		var started_at := Time.get_ticks_usec()
		step = session.submit_intent(PlayerIntent.move(direction))
		var transaction_done := Time.get_ticks_usec()
		var view := session.view(step.events)
		var projection_done := Time.get_ticks_usec()
		if step.state != SessionStep.State.COMPLETED or view.pending_interaction != null:
			printerr("MOVEMENT_INTERRUPTED step=%d state=%d events=%s" % [index, step.state, step.events.map(func(event: DomainEvent) -> String: return String(event.kind))])
			call_deferred("_quit_cleanly", 1)
			return
		if index == 0:
			for event: DomainEvent in step.events:
				event_kinds.append(String(event.kind))
		var sequence := ",".join(step.events.map(func(event: DomainEvent) -> String: return String(event.kind)))
		event_sequences[sequence] = int(event_sequences.get(sequence, 0)) + 1
		for event: DomainEvent in step.events:
			if event.kind == &"fatigue_changed" and fatigue_payload.is_empty():
				fatigue_payload = event.payload.duplicate(true)
		if view.domain_revisions.is_ordinary_exploration_update_from(previous_view.domain_revisions):
			ordinary_projection_count += 1
		if index >= 10:
			transaction_samples.append(transaction_done - started_at)
			projection_samples.append(projection_done - transaction_done)
		direction = -direction
	var total_samples: Array[int] = []
	for index: int in transaction_samples.size():
		total_samples.append(transaction_samples[index] + projection_samples[index])
	var output := {
		"campaignId": loaded.content.campaign_id,
		"partySize": session.view().party_members.size(),
		"sampleCount": total_samples.size(),
		"transactionP95Ms": _p95_milliseconds(transaction_samples),
		"projectionP95Ms": _p95_milliseconds(projection_samples),
		"transactionPlusProjectionP95Ms": _p95_milliseconds(total_samples),
		"scheduledStepsPerSecond100": 5,
		"scheduledStepsPerSecond400": 20,
		"ordinaryProjectionCount": ordinary_projection_count,
		"eventKinds": event_kinds,
		"eventSequences": event_sequences,
		"fatiguePayload": fatigue_payload,
		"finalX": session.view().party_coordinate.x,
		"finalY": session.view().party_coordinate.y,
	}
	print(CanonicalJson.encode(output))
	if ordinary_projection_count != 60:
		printerr("MOVEMENT_INCREMENTAL_PROJECTION_MISSED expected=60 actual=%d sequences=%s" % [ordinary_projection_count, event_sequences])
		call_deferred("_quit_cleanly", 1)
		return
	if float(output["transactionPlusProjectionP95Ms"]) >= 50.0:
		printerr("MOVEMENT_P95_EXCEEDED expectedBelowMs=50 actualMs=%s" % output["transactionPlusProjectionP95Ms"])
		call_deferred("_quit_cleanly", 1)
		return
	call_deferred("_quit_cleanly", 0)


func _assemble_six_character_party(session: GameSession, content: RealmzContent) -> bool:
	var races := content.race_definitions()
	var castes := content.caste_definitions()
	if races.is_empty() or castes.is_empty():
		return false
	var race := races[0]
	var caste: CasteDefinition
	for candidate: CasteDefinition in castes:
		if race.eligible_caste_ids.is_empty() or race.eligible_caste_ids.has(candidate.id):
			caste = candidate
			break
	if caste == null:
		return false
	for index: int in 6:
		var character := CharacterState.new("movement-probe-%d" % index, "Probe %d" % (index + 1), 20, 20)
		character.race_id = race.id
		character.caste_id = caste.id
		var imported := session.submit_intent(PlayerIntent.import_vault_character(character.id, "%064d" % (index + 1), character, "movement-probe", content.package_hash))
		if imported.state == SessionStep.State.FAILED:
			return false
	var started := session.submit_intent(PlayerIntent.begin_adventure())
	for ignored: int in 16:
		if started.state != SessionStep.State.WAITING_FOR_INTERACTION:
			break
		if started.interaction == null or started.interaction.kind != InteractionRequest.ACKNOWLEDGE:
			return false
		started = session.respond(InteractionResponse.acknowledge(started.interaction))
	return started.state == SessionStep.State.COMPLETED and session.view().party_members.size() == 6


func _safe_movement_pair(session: GameSession, content: RealmzContent) -> Dictionary:
	var state := session.snapshot().game_state
	var map := content.world.map_by_id(state.party.map_id)
	if map == null:
		return {}
	var directions := MapTopology.land_directions() if map.level_type == &"land" else MapTopology.cardinal_directions()
	for cell: MapCell in map.topology.cells():
		if not _safe_cell(cell):
			continue
		for direction: Vector2i in directions:
			var movement := content.world.probe_movement(map.id, cell.coordinate, direction, state.world)
			if movement.allowed and movement.target_map == map and _safe_cell(movement.topology_result.target_cell):
				return {"origin": cell.coordinate, "direction": direction}
	return {}


static func _safe_cell(cell: MapCell) -> bool:
	return cell != null and cell.passable and cell.trigger_ids().is_empty() and cell.random_rect_ids().is_empty() and cell.features().is_empty()


func _place_party(session: GameSession, content: RealmzContent, coordinate: Vector2i) -> bool:
	var snapshot := session.snapshot()
	snapshot.game_state.party.coordinate = coordinate
	snapshot.game_state.world.mark_visited(snapshot.game_state.party.map_id, coordinate)
	return session.restore(content, snapshot).state == SessionStep.State.COMPLETED


static func _p95_milliseconds(samples: Array[int]) -> float:
	if samples.is_empty():
		return 0.0
	var ordered := samples.duplicate()
	ordered.sort()
	var index := clampi(ceili(float(ordered.size()) * 0.95) - 1, 0, ordered.size() - 1)
	return snappedf(float(ordered[index]) / 1000.0, 0.001)


func _quit_cleanly(exit_code: int) -> void:
	quit(exit_code)

