class_name ClassicMusicCatalog
extends RefCounted

const MANIFEST_PATH := "res://src/presentation/assets/classic-application-music.json"

var last_error: String = ""
var _tracks: Dictionary = {}
var _streams: Dictionary = {}


func _init(manifest_path: String = MANIFEST_PATH) -> void:
	_load_manifest(manifest_path)


func is_valid() -> bool:
	return last_error.is_empty() and _tracks.size() == 11


func has_track(playlist_id: int) -> bool:
	return _tracks.has(_stock_track_id(playlist_id))


func track(playlist_id: int) -> Dictionary:
	return (_tracks.get(_stock_track_id(playlist_id), {}) as Dictionary).duplicate(true)


func title(playlist_id: int) -> String:
	return String((_tracks.get(_stock_track_id(playlist_id), {}) as Dictionary).get("title", ""))


func stream(playlist_id: int) -> AudioStream:
	var stock_track_id := _stock_track_id(playlist_id)
	if _streams.has(stock_track_id):
		return _streams[stock_track_id] as AudioStream
	var record := _tracks.get(stock_track_id, {}) as Dictionary
	if record.is_empty():
		return null
	var path := String(record.get("path", ""))
	var bytes := FileAccess.get_file_as_bytes(path)
	if bytes.size() != int(record.get("bytes", 0)) or _sha256(bytes) != String(record.get("sha256", "")):
		last_error = "Classic application music failed integrity validation for playlist %d." % playlist_id
		return null
	var result := load(path) as AudioStream
	if result is AudioStreamOggVorbis:
		(result as AudioStreamOggVorbis).loop = true
	_streams[stock_track_id] = result
	return result


func _stock_track_id(playlist_id: int) -> int:
	if playlist_id >= 12 and playlist_id <= 14:
		return 1
	return playlist_id


func _load_manifest(path: String) -> void:
	var parsed: Variant = JSON.parse_string(FileAccess.get_file_as_string(path))
	if not parsed is Dictionary:
		last_error = "Classic application music manifest is unavailable or malformed."
		return
	var manifest := parsed as Dictionary
	if int(manifest.get("schema_version", 0)) != 1 or String(manifest.get("ownership", "")) != "classic-application" or int(manifest.get("slot_count", 0)) != 20 or String(manifest.get("lookup", "")) != "playlist-id":
		last_error = "Classic application music manifest contract is unsupported."
		return
	for value: Variant in manifest.get("tracks", []):
		if not value is Dictionary:
			last_error = "Classic application music contains a malformed track."
			return
		var record := value as Dictionary
		var playlist_id := int(record.get("playlist_id", 0))
		if playlist_id < 1 or playlist_id > 11 or _tracks.has(playlist_id) or String(record.get("path", "")).is_empty() or int(record.get("bytes", 0)) <= 0 or String(record.get("sha256", "")).length() != 64:
			last_error = "Classic application music contains an incomplete or duplicate track."
			return
		_tracks[playlist_id] = record.duplicate(true)
	if _tracks.size() != 11:
		last_error = "Classic application music does not contain the complete stock track bank."


static func _sha256(bytes: PackedByteArray) -> String:
	var hashing := HashingContext.new()
	if hashing.start(HashingContext.HASH_SHA256) != OK or hashing.update(bytes) != OK:
		return ""
	return hashing.finish().hex_encode()

class_name ClassicAudioPresenter
extends Node

signal sound_observed(sound_id: int)
signal blocking_state_changed(blocking: bool)
signal music_state_changed(playlist_id: int, title: String, playing: bool)

const CHANNEL_COUNT: int = 4

var last_sound_id: int = 0
var master_volume: float = 1.0
var sound_volume: float = 1.0
var music_volume: float = 0.8
var current_music_playlist_id: int = 0
var current_music_title: String = ""
var last_media_diagnostic: Dictionary = {}
var _players: Array[AudioStreamPlayer] = []
var _channel_index: int = -1
var _pending_sounds: Array[Dictionary] = []
var _processing_sounds: bool = false
var _waiting_player: AudioStreamPlayer
var _waiting_finished_callback: Callable
var _music_player: AudioStreamPlayer


func _ready() -> void:
	for index: int in range(CHANNEL_COUNT):
		var player := AudioStreamPlayer.new()
		player.name = "ClassicSoundChannel%d" % (index + 1)
		_players.append(player)
		add_child(player)
	_music_player = AudioStreamPlayer.new()
	_music_player.name = "ClassicMusicChannel"
	add_child(_music_player)
	_apply_volume()


func present_events(events: Array[DomainEvent], media: ClassicMediaCatalog) -> void:
	for event: DomainEvent in events:
		if event.kind != &"sound_requested":
			continue
		if bool(event.payload.get("stopExisting", false)):
			_stop_all()
		last_sound_id = int(event.payload.get("soundId", 0))
		sound_observed.emit(last_sound_id)
		if media == null:
			continue
		var asset := media.asset_by_resource("snd ", last_sound_id)
		if asset == null:
			last_media_diagnostic = media.resolution_diagnostic("snd ", last_sound_id, "classic-sound")
			continue
		var stream := media.audio_stream_by_resource("snd ", last_sound_id)
		last_media_diagnostic = media.resolution_diagnostic("snd ", last_sound_id, "classic-sound", "decoded" if stream != null else "decode-failed")
		if stream == null:
			continue
		_pending_sounds.append({"stream": stream, "waitForCompletion": bool(event.payload.get("waitForCompletion", false))})
	_drain_sound_queue()


func present_sound(sound_id: int, media: ClassicMediaCatalog, wait_for_completion: bool = false, stop_existing: bool = false) -> void:
	present_events([DomainEvent.new(&"sound_requested", {"soundId": sound_id, "waitForCompletion": wait_for_completion, "stopExisting": stop_existing, "source": "classic-presentation-workspace"})], media)


func set_master_volume(value: float) -> void:
	master_volume = clampf(value, 0.0, 1.0)
	_apply_volume()


func set_sound_volume(value: float) -> void:
	sound_volume = clampf(value, 0.0, 1.0)
	_apply_volume()


func set_music_volume(value: float) -> void:
	music_volume = clampf(value, 0.0, 1.0)
	_apply_volume()


func present_music_context(playlist_id: int, settings: PresentationSettings, media: ClassicMediaCatalog, stock_music: ClassicMusicCatalog) -> void:
	if settings == null or not settings.music_enabled or playlist_id <= 0:
		stop_music()
		return
	var mode := settings.music_mode(playlist_id)
	if mode == PresentationSettings.MUSIC_CONTINUE:
		return
	if mode == PresentationSettings.MUSIC_OFF:
		stop_music()
		return
	if current_music_playlist_id == playlist_id and _music_player != null and _music_player.playing:
		return
	var stream: AudioStream
	var title := ""
	if media != null:
		var package_asset := media.asset_by_resource("music", playlist_id)
		if package_asset != null:
			stream = media.audio_stream_by_resource("music", playlist_id)
			title = package_asset.label
	if stream == null and stock_music != null:
		stream = stock_music.stream(playlist_id)
		title = stock_music.title(playlist_id)
	if stream == null:
		return
	_music_player.stop()
	_music_player.stream = stream
	if _music_player.is_inside_tree():
		_music_player.play()
	current_music_playlist_id = playlist_id
	current_music_title = title if not title.is_empty() else ClassicMusicContext.context_name(playlist_id)
	music_state_changed.emit(current_music_playlist_id, current_music_title, true)


func stop_music() -> void:
	if _music_player != null:
		_music_player.stop()
	var changed := current_music_playlist_id != 0 or not current_music_title.is_empty()
	current_music_playlist_id = 0
	current_music_title = ""
	if changed:
		music_state_changed.emit(0, "", false)


func is_blocking() -> bool:
	return _processing_sounds


func _apply_volume() -> void:
	for player: AudioStreamPlayer in _players:
		var effective_sound := master_volume * sound_volume
		player.volume_db = -80.0 if effective_sound <= 0.0 else linear_to_db(effective_sound)
	if _music_player != null:
		var effective_music := master_volume * music_volume
		_music_player.volume_db = -80.0 if effective_music <= 0.0 else linear_to_db(effective_music)


func _drain_sound_queue() -> void:
	if _processing_sounds:
		return
	while not _pending_sounds.is_empty():
		var request: Dictionary = _pending_sounds.pop_front()
		var player := _next_channel()
		if player == null:
			continue
		player.stop()
		player.stream = request["stream"] as AudioStream
		player.play()
		if bool(request["waitForCompletion"]) and player.playing:
			_processing_sounds = true
			blocking_state_changed.emit(true)
			_waiting_player = player
			_waiting_finished_callback = _on_waiting_sound_finished.bind(player)
			player.finished.connect(_waiting_finished_callback, CONNECT_ONE_SHOT)
			return


func _on_waiting_sound_finished(player: AudioStreamPlayer) -> void:
	if player != _waiting_player:
		return
	_waiting_player = null
	_waiting_finished_callback = Callable()
	_processing_sounds = false
	blocking_state_changed.emit(false)
	_drain_sound_queue()


func _next_channel() -> AudioStreamPlayer:
	if _players.is_empty():
		return null
	_channel_index = (_channel_index + 1) % _players.size()
	return _players[_channel_index]


func _stop_all() -> void:
	var was_blocking := _processing_sounds
	if _waiting_player != null and _waiting_finished_callback.is_valid() and _waiting_player.finished.is_connected(_waiting_finished_callback):
		_waiting_player.finished.disconnect(_waiting_finished_callback)
	_waiting_player = null
	_waiting_finished_callback = Callable()
	_processing_sounds = false
	_pending_sounds.clear()
	for player: AudioStreamPlayer in _players:
		player.stop()
	if was_blocking:
		blocking_state_changed.emit(false)

class_name ClassicMediaCatalog
extends MediaSource

var package_media: MediaSource
var application_media: ApplicationMediaCatalog
var _image_textures: Dictionary = {}


func _init(package_catalog: MediaSource, application_catalog: ApplicationMediaCatalog) -> void:
	package_media = package_catalog
	application_media = application_catalog


func assets() -> Array[MediaAsset]:
	var result: Array[MediaAsset] = []
	var occupied_resource_keys: Dictionary = {}
	if package_media != null:
		for asset: MediaAsset in package_media.assets():
			result.append(asset)
			if not asset.resource_type.is_empty():
				occupied_resource_keys[_resource_key(asset.resource_type, asset.resource_id)] = true
	if application_media != null:
		for asset: MediaAsset in application_media.assets():
			if not occupied_resource_keys.has(_resource_key(asset.resource_type, asset.resource_id)):
				result.append(asset)
	return result


func assets_of_kind(kind: String) -> Array[MediaAsset]:
	var result: Array[MediaAsset] = []
	for asset: MediaAsset in assets():
		if asset.kind == kind:
			result.append(asset)
	result.sort_custom(func(left: MediaAsset, right: MediaAsset) -> bool: return left.resource_id < right.resource_id)
	return result


func asset_by_id(asset_id: String) -> MediaAsset:
	var package_asset := package_media.asset_by_id(asset_id) if package_media != null else null
	if package_asset != null:
		return package_asset
	return application_media.asset_by_id(asset_id) if application_media != null else null


func asset_by_resource(resource_type: String, resource_id: int) -> MediaAsset:
	if package_media != null:
		var package_status := package_media.resource_status(resource_type, resource_id)
		if package_status == &"ambiguous":
			return null
		if package_status == &"resolved":
			return package_media.asset_by_resource(resource_type, resource_id)
	return application_media.asset_by_resource(resource_type, resource_id) if application_media != null else null


func tileset_by_id(tileset_id: String) -> MediaAsset:
	var asset := asset_by_id(tileset_id)
	return asset if asset != null and asset.is_tileset() else null


func battle_tileset() -> MediaAsset:
	var asset := asset_by_id("classic-battle-tiles-302")
	return asset if asset != null and asset.is_battle_tileset() else null


func resolution_diagnostic(resource_type: String, resource_id: int, presentation_role: String, decode_result: String = "not-attempted") -> Dictionary:
	if package_media != null and package_media.resource_status(resource_type, resource_id) != &"missing":
		var package_diagnostic: Dictionary = package_media.resolution_diagnostic(resource_type, resource_id, presentation_role, decode_result)
		package_diagnostic["sourceOwner"] = "scenario-package"
		package_diagnostic["resolvedAssetId"] = package_diagnostic.get("packageAssetId", "")
		return package_diagnostic
	var diagnostic := {
		"authoredResourceType": resource_type,
		"authoredResourceId": resource_id,
		"presentationRole": presentation_role,
		"decodeResult": decode_result,
		"status": "missing",
		"sourceOwner": "",
		"packageAssetId": "",
		"applicationAssetId": "",
		"resolvedAssetId": "",
		"sha256": "",
	}
	if application_media == null:
		return diagnostic
	var application_status := application_media.resource_status(resource_type, resource_id)
	if application_status == &"ambiguous":
		diagnostic["status"] = "ambiguous"
		diagnostic["sourceOwner"] = "classic-application"
		return diagnostic
	var asset := application_media.asset_by_resource(resource_type, resource_id)
	if asset == null:
		return diagnostic
	diagnostic["status"] = "resolved"
	diagnostic["sourceOwner"] = "classic-application"
	diagnostic["applicationAssetId"] = asset.id
	diagnostic["resolvedAssetId"] = asset.id
	diagnostic["sha256"] = asset.sha256
	return diagnostic


func read_bytes(asset: MediaAsset) -> PackedByteArray:
	if package_media != null and package_media.owns_asset(asset):
		return package_media.read_bytes(asset)
	if application_media != null and application_media.owns_asset(asset):
		return application_media.read_bytes(asset)
	return PackedByteArray()


func read_bytes_batch(requested_assets: Array[MediaAsset]) -> Dictionary:
	var result: Dictionary = {}
	var package_assets: Array[MediaAsset] = []
	for asset: MediaAsset in requested_assets:
		if package_media != null and package_media.owns_asset(asset):
			package_assets.append(asset)
		elif application_media != null and application_media.owns_asset(asset):
			var bytes := application_media.read_bytes(asset)
			if not bytes.is_empty():
				result[asset.id] = bytes
	if package_media != null:
		result.merge(package_media.read_bytes_batch(package_assets), true)
	return result


func image_texture(asset: MediaAsset) -> Texture2D:
	if asset == null:
		return null
	if _image_textures.has(asset.id):
		return _image_textures[asset.id] as Texture2D
	var bytes := read_bytes(asset)
	var texture: Texture2D
	if not bytes.is_empty():
		var image := Image.new()
		var error := ERR_FILE_UNRECOGNIZED
		match asset.mime_type:
			"image/png": error = image.load_png_from_buffer(bytes)
			"image/jpeg": error = image.load_jpg_from_buffer(bytes)
			"image/webp": error = image.load_webp_from_buffer(bytes)
		if error == OK and (asset.width <= 0 or asset.height <= 0 or image.get_width() == asset.width and image.get_height() == asset.height):
			texture = ImageTexture.create_from_image(image)
	_image_textures[asset.id] = texture
	return texture


func audio_stream_by_resource(resource_type: String, resource_id: int) -> AudioStream:
	var asset := asset_by_resource(resource_type, resource_id)
	if asset == null:
		return null
	if application_media != null and application_media.owns_asset(asset):
		return application_media.audio_stream(asset)
	return _decode_stream(asset, package_media.read_bytes(asset)) if package_media != null else null


static func _decode_stream(asset: MediaAsset, bytes: PackedByteArray) -> AudioStream:
	if bytes.is_empty():
		return null
	var mime := asset.mime_type.to_lower()
	var extension := asset.path.get_extension().to_lower()
	if mime == "audio/wav" or mime == "audio/x-wav" or extension == "wav":
		return AudioStreamWAV.load_from_buffer(bytes)
	if mime in ["audio/mpeg", "audio/mp3"] or extension == "mp3":
		return AudioStreamMP3.load_from_buffer(bytes)
	if mime in ["audio/ogg", "audio/vorbis"] or extension == "ogg":
		return AudioStreamOggVorbis.load_from_buffer(bytes)
	return null


static func _resource_key(resource_type: String, resource_id: int) -> String:
	return JSON.stringify([resource_type, resource_id])

class_name PackageCrossReferenceValidator
extends PackageDecoderBase

func _validate_rule_references(races: Array[RaceDefinition], castes: Array[CasteDefinition], items: Array[ItemDefinition], spells: Array[SpellDefinition], monsters: Array[MonsterDefinition], battles: Array[BattleDefinition], treasures: Array[TreasureDefinition], shops: Array[ShopDefinition], message_ids: Dictionary) -> bool:
	var race_ids := _definition_ids(races)
	var caste_ids := _definition_ids(castes)
	var item_ids := _definition_ids(items)
	var monster_ids := _definition_ids(monsters)
	for item: ItemDefinition in items:
		if not item.cursed_item_id.is_empty() and not item_ids.has(item.cursed_item_id):
			return _reject("Item '%s' references unavailable cursed item '%s'." % [item.id, item.cursed_item_id])
		if not item.specific_race_id.is_empty() and not race_ids.has(item.specific_race_id):
			return _reject("Item '%s' references unavailable race '%s'." % [item.id, item.specific_race_id])
		if not item.specific_caste_id.is_empty() and not caste_ids.has(item.specific_caste_id):
			return _reject("Item '%s' references unavailable caste '%s'." % [item.id, item.specific_caste_id])
	for caste: CasteDefinition in castes:
		for item_id: String in caste.start_items():
			if not item_ids.has(item_id):
				return _reject("Caste '%s' references unavailable starting item '%s'." % [caste.id, item_id])
	if not _validate_monster_record_references(monsters, items, spells):
		return false
	for battle: BattleDefinition in battles:
		for slot: BattleMonsterSlotDefinition in battle.monster_slots():
			if not monster_ids.has(slot.monster_id):
				return _reject("Battle '%s' references unavailable monster '%s'." % [battle.id, slot.monster_id])
		for message_id: int in [battle.message_before_id, battle.message_after_id]:
			if message_id != 0 and not message_ids.has(absi(message_id)):
				return _reject("Battle '%s' references unavailable message %d." % [battle.id, message_id])
	for treasure: TreasureDefinition in treasures:
		for item_id: String in treasure.item_ids():
			if not item_ids.has(item_id):
				return _reject("Treasure '%s' references unavailable item '%s'." % [treasure.id, item_id])
	for shop: ShopDefinition in shops:
		for item_id: String in shop.item_ids():
			if not item_ids.has(item_id):
				return _reject("Shop '%s' references unavailable item '%s'." % [shop.id, item_id])
	return true

func _validate_monster_record_references(monsters: Array[MonsterDefinition], items: Array[ItemDefinition], spells: Array[SpellDefinition]) -> bool:
	var item_ids := _definition_ids(items)
	var spell_ids := _definition_ids(spells)
	for monster: MonsterDefinition in monsters:
		for spell_id: String in monster.spell_ids():
			if spell_id.is_empty():
				continue
			if not spell_ids.has(spell_id):
				return _reject("Monster '%s' references unavailable spell '%s'." % [monster.id, spell_id])
		for item_id: String in monster.item_ids():
			if not item_id.is_empty() and not item_ids.has(item_id):
				return _reject("Monster '%s' references unavailable item '%s'." % [monster.id, item_id])
		if not monster.weapon_id.is_empty() and not item_ids.has(monster.weapon_id):
			return _reject("Monster '%s' references unavailable weapon '%s'." % [monster.id, monster.weapon_id])
		for random_weapon_id: String in MonsterRules.random_weapon_item_ids(monster.random_weapon_table):
			if not item_ids.has(random_weapon_id):
				return _reject("Monster '%s' random weapon table %d can produce unavailable weapon '%s'." % [monster.id, monster.random_weapon_table, random_weapon_id])
	return true

func _validate_scenario_references(scenario: ScenarioDefinition, message_ids: Dictionary, encounters: Array[SimpleEncounterDefinition], complex_encounters: Array[ComplexEncounterDefinition], thief_encounters: Array[ThiefEncounterDefinition]) -> bool:
	var encounter_ids: Dictionary = {}
	for encounter: SimpleEncounterDefinition in encounters:
		encounter_ids[encounter.id] = true
		if not message_ids.has(absi(encounter.prompt_message_id)):
			return _reject("Simple Encounter %d references unavailable prompt message %d." % [encounter.id, encounter.prompt_message_id])
		for response: SimpleEncounterResponse in encounter.responses():
			if scenario.program_by_id(response.result_program_id) == null:
				return _reject("Simple Encounter %d response '%s' references unavailable result program '%s'." % [encounter.id, response.id, response.result_program_id])
	var complex_ids: Dictionary = {}
	var thief_ids: Dictionary = {}
	for thief_encounter: ThiefEncounterDefinition in thief_encounters:
		thief_ids[thief_encounter.id] = true
	for encounter: ComplexEncounterDefinition in complex_encounters:
		complex_ids[encounter.id] = true
		if not message_ids.has(absi(encounter.prompt_message_id)):
			return _reject("Complex Encounter %d references unavailable prompt message %d." % [encounter.id, encounter.prompt_message_id])
		for outcome: int in range(1, 5):
			if scenario.program_by_id(encounter.result_program_id(outcome)) == null:
