			return null
		var map_id: String = ""
		var coordinate := Vector2i(-1, -1)
		if record.get("mapId") != null or record.get("coordinate") != null:
			if not record.get("mapId") is String or not record.get("coordinate") is Dictionary or not _exact_fields(record["coordinate"], ["x", "y"]):
				_reject("Placed trigger '%s' has incomplete map coordinates." % record["id"])
				return null
			map_id = record["mapId"]
			coordinate = Vector2i(_integer(record["coordinate"].get("x")), _integer(record["coordinate"].get("y")))
			if coordinate.x < 0 or coordinate.y < 0:
				_reject("Placed trigger '%s' has invalid map coordinates." % record["id"])
				return null
			var placed_record_key := "%s:%d" % [map_id, _integer(record["classicRecordIndex"])]
			if placed_record_keys.has(placed_record_key):
				_reject("Placed trigger '%s' duplicates Classic record %d on map '%s'." % [record["id"], _integer(record["classicRecordIndex"]), map_id])
				return null
			placed_record_keys[placed_record_key] = true
		var chance := _integer(record.get("chancePercent"))
		if chance < -128 or chance > 127:
			_reject("Trigger '%s' chance is outside Classic storage." % record["id"])
			return null
		var destination_record: Variant = record.get("postActionLocation")
		var destination: TriggerDestinationDefinition = null
		if destination_record != null:
			if not destination_record is Dictionary or not _exact_fields(destination_record, ["mapId", "coordinate"]) or not destination_record.get("mapId") is String or not destination_record.get("coordinate") is Dictionary or not _exact_fields(destination_record["coordinate"], ["x", "y"]):
				_reject("Trigger '%s' post-action location is malformed." % record["id"])
				return null
			var destination_coordinate: Dictionary = destination_record["coordinate"]
			if not _is_integer(destination_coordinate.get("x")) or not _is_integer(destination_coordinate.get("y")):
				_reject("Trigger '%s' post-action coordinate is malformed." % record["id"])
				return null
			destination = TriggerDestinationDefinition.new(destination_record["mapId"], Vector2i(_integer(destination_coordinate["x"]), _integer(destination_coordinate["y"])))
		triggers.append(TriggerDefinition.new(record["id"], record["programId"], map_id, coordinate, record["active"], chance, destination, _integer(record["classicRecordIndex"])))
	return triggers

func _construct_battle_terrain_sets(value: Variant) -> Variant:
	if not value is Array:
		_reject("World battle terrain sets must be an array.")
		return null
	var terrain_sets: Array[BattleTerrainSetDefinition] = []
	var set_ids: Dictionary = {}
	for record: Variant in value:
		if not record is Dictionary or not _exact_fields(record, ["id", "landlook", "baseTile", "tiles"]) or not record["id"] is String or record["id"].is_empty() or set_ids.has(record["id"]) or not record["tiles"] is Array:
			_reject("Battle terrain set is malformed or duplicated.")
			return null
		var dungeon_set := record["landlook"] == null
		if dungeon_set != (record["baseTile"] == null):
			_reject("Battle terrain set '%s' has inconsistent landlook/base-tile identity." % record["id"])
			return null
		if not dungeon_set and (not _is_integer(record["landlook"]) or not _is_integer(record["baseTile"])):
			_reject("Battle terrain set '%s' has non-integer landlook or base-tile identity." % record["id"])
			return null
		var landlook := -1 if dungeon_set else _integer(record["landlook"])
		var base_tile := -1 if dungeon_set else _integer(record["baseTile"])
		if not dungeon_set and (landlook < -128 or landlook > 127 or base_tile < 0 or base_tile > 400):
			_reject("Battle terrain set '%s' has invalid landlook or base-tile identity." % record["id"])
			return null
		var tiles: Array[BattleTerrainTileDefinition] = []
		var tile_ids: Dictionary = {}
		for tile_record: Variant in record["tiles"]:
			var tile_definition := _construct_battle_terrain_tile(tile_record)
			if tile_definition == null or tile_ids.has(tile_definition.tile):
				_reject("Battle terrain set '%s' contains a malformed or duplicate tile." % record["id"])
				return null
			tile_ids[tile_definition.tile] = true
			tiles.append(tile_definition)
		var terrain_set := BattleTerrainSetDefinition.new(record["id"], landlook, base_tile, tiles)
		if dungeon_set and not terrain_set.has_complete_range(200, 400):
			_reject("Dungeon battle terrain set '%s' must contain every Combat Data BD tile 200 through 400." % record["id"])
			return null
		if not dungeon_set and not terrain_set.has_complete_range(0, 400):
			_reject("Land battle terrain set '%s' must contain every effective mapstats tile 0 through 400." % record["id"])
			return null
		set_ids[terrain_set.id] = true
		terrain_sets.append(terrain_set)
	return terrain_sets

func _construct_battle_terrain_tile(value: Variant) -> BattleTerrainTileDefinition:
	var fields: Array[String] = ["tile", "sound", "time", "solid", "shore", "needBoat", "isPath", "los", "flyFloat", "forest", "combatBuild"]
	if not value is Dictionary or not _exact_fields(value, fields):
		return null
	var record: Dictionary = value
	var integers_value: Variant = _validated_integer_fields(record, ["tile", "sound", "time", "solid", "needBoat", "forest"], "Battle terrain tile")
	if integers_value == null:
		return null
	var integers: Dictionary = integers_value
	if integers["tile"] < 0 or integers["tile"] > 400 or not _integers_in_range(integers, ["sound", "time", "solid", "needBoat", "forest"], -32768, 32767):
		return null
	for flag: String in ["shore", "isPath", "los", "flyFloat"]:
		if not record[flag] is bool:
			return null
	if not record["combatBuild"] is Array or record["combatBuild"].size() != 3:
		return null
	var combat_build: Array = []
	for row: Variant in record["combatBuild"]:
		if not row is Array or row.size() != 3:
			return null
		var parsed_row: Array[int] = []
		for entry: Variant in row:
			if not _is_integer(entry):
				return null
			var tile_id := _integer(entry)
			if tile_id < -32768 or tile_id > 32767:
				return null
			parsed_row.append(tile_id)
		combat_build.append(parsed_row)
	return BattleTerrainTileDefinition.new(integers["tile"], integers["sound"], integers["time"], integers["solid"], record["shore"], integers["needBoat"], record["isPath"], reco...

class_name PackageArchiveReader
extends RefCounted

var last_error: String = ""


func entries(archive: ZIPReader) -> Variant:
	last_error = ""
	var paths := archive.get_files()
	if paths == null:
		last_error = "Could not enumerate ZIP entries."
		return null
	var result: Array[String] = []
	result.assign(paths)
	result.sort()
	return result


func read_document(archive: ZIPReader, path: String) -> Variant:
	last_error = ""
	if not archive.file_exists(path):
		last_error = "Package document '%s' is missing." % path
		return null
	var bytes := archive.read_file(path)
	var text := bytes.get_string_from_utf8()
	var parsed: Variant = JSON.parse_string(text)
	if not parsed is Dictionary:
		last_error = "Package document '%s' is not a JSON object." % path
		return null
	return parsed


func validate_files(manifest: Dictionary, archive: ZIPReader, progress_callback: Callable = Callable(), cancel_callback: Callable = Callable()) -> bool:
	last_error = ""
	var file_paths: Array[String] = []
	file_paths.assign(manifest["files"].keys())
	file_paths.sort()
	for file_index: int in file_paths.size():
		if cancel_callback.is_valid() and bool(cancel_callback.call()):
			last_error = "Package operation cancelled."
			return false
		var file_path := file_paths[file_index]
		_report_progress(progress_callback, &"validating-integrity", file_index, file_paths.size())
		var integrity: Dictionary = manifest["files"][file_path]
		var bytes := archive.read_file(file_path)
		if bytes.size() != int(integrity["bytes"]) or sha256(bytes) != integrity["sha256"]:
			last_error = "Package file '%s' failed size or SHA-256 validation." % file_path
			return false
	_report_progress(progress_callback, &"validating-integrity", file_paths.size(), file_paths.size())
	return true


func sha256(bytes: PackedByteArray) -> String:
	var context := HashingContext.new()
	context.start(HashingContext.HASH_SHA256)
	context.update(bytes)
	return context.finish().hex_encode()


func sha256_file(path: String) -> String:
	var file := FileAccess.open(path, FileAccess.READ)
	if file == null:
		return ""
	var context := HashingContext.new()
	context.start(HashingContext.HASH_SHA256)
	while file.get_position() < file.get_length():
		context.update(file.get_buffer(mini(1024 * 1024, file.get_length() - file.get_position())))
	file.close()
	return context.finish().hex_encode()


func _report_progress(callback: Callable, phase: StringName, completed: int, total: int) -> void:
	if callback.is_valid():
		callback.call(phase, completed, total)

class_name MapTopology
extends RefCounted

var width: int
var height: int
var _cells: Array[MapCell]
var _cells_by_coordinate: Dictionary = {}
var _compact_map_id: String = ""
var _compact_rows: Array = []
var _compact_cells_by_index: Dictionary = {}
var _boat_removed_profile: LandTileProfile
var _boat_placed_profile: LandTileProfile


func _init(map_width: int, map_height: int, map_cells: Array[MapCell]) -> void:
	width = map_width
	height = map_height
	_cells = map_cells.duplicate()
	for cell: MapCell in _cells:
		_cells_by_coordinate[cell.coordinate] = cell


static func from_compact_rows(map_id: String, map_width: int, map_height: int, rows: Array, boat_removed_profile: LandTileProfile = null, boat_placed_profile: LandTileProfile = null) -> MapTopology:
	var topology := MapTopology.new(map_width, map_height, [])
	topology._compact_map_id = map_id
	topology._compact_rows = rows
	topology._boat_removed_profile = boat_removed_profile
	topology._boat_placed_profile = boat_placed_profile
	return topology


func contains(coordinate: Vector2i) -> bool:
	return coordinate.x >= 0 and coordinate.y >= 0 and coordinate.x < width and coordinate.y < height


func cell_at(coordinate: Vector2i) -> MapCell:
	if not contains(coordinate):
		return null
	if not _compact_rows.is_empty():
		var index := coordinate.y * width + coordinate.x
		var cached := _compact_cells_by_index.get(index) as MapCell
		if cached != null:
			return cached
		var decoded := _decode_compact_cell(index, coordinate)
		if decoded != null:
			_compact_cells_by_index[index] = decoded
		return decoded
	return _cells_by_coordinate.get(coordinate) as MapCell


func effective_cell_at(coordinate: Vector2i, world_state: WorldState) -> MapCell:
	var cell := cell_at(coordinate)
	if cell == null or world_state == null or _compact_map_id.is_empty():
		return cell
	match world_state.boat_presence_state(_compact_map_id, coordinate):
		0:
			return cell if _boat_removed_profile == null else _boat_removed_profile.apply_to(cell)
		1:
			return cell if _boat_placed_profile == null else _boat_placed_profile.apply_to(cell)
		_:
			return cell


func cells() -> Array[MapCell]:
	if not _compact_rows.is_empty():
		var result: Array[MapCell] = []
		result.resize(_compact_rows.size())
		for index: int in _compact_rows.size():
			result[index] = cell_at(Vector2i(index % width, index / width))
		return result
	return _cells.duplicate()


func probe_entry(coordinate: Vector2i, move_direction: Vector2i, world_state: WorldState) -> TopologyMoveResult:
	var cell_probe := probe_land_entry(coordinate, world_state)
	if not cell_probe.allowed:
		return cell_probe
	var cell := cell_probe.target_cell
	var entry_direction_name := direction_name(move_direction)
	if not is_cardinal_direction(move_direction):
		return TopologyMoveResult.blocked(&"invalid_direction")
	var edge := cell.edge(entry_direction_name)
	if edge == null or not edge.passable:
		return TopologyMoveResult.blocked(&"edge_blocked")
	return TopologyMoveResult.permitted(cell, edge.door_id, edge.secret_id)


func probe_land_entry(coordinate: Vector2i, world_state: WorldState, party_in_boat: bool = false) -> TopologyMoveResult:
	var cell := effective_cell_at(coordinate, world_state)
	if cell == null:
		return TopologyMoveResult.blocked(&"outside_map")
	var boat_requirement := cell.boat_requirement
	if party_in_boat:
		if cell.is_shore:
			return TopologyMoveResult.blocked(&"boat_shore", cell)
		if boat_requirement == 2:
			return TopologyMoveResult.permitted(cell)
		return TopologyMoveResult.blocked(&"boat_terrain_blocked", cell)
	if boat_requirement == 1:
		return TopologyMoveResult.blocked(&"board_boat", cell)
	if boat_requirement == 2:
		return TopologyMoveResult.blocked(&"water_requires_boat", cell)
	if not cell.passable:
		return TopologyMoveResult.blocked(&"terrain_blocked", cell)
	var cell_secret := cell.feature_by_kind(&"secret")
	if cell_secret != null and cell_secret.orientation.is_empty() and not world_state.secret_is_discovered(cell_secret.id, cell_secret.initial_state == &"revealed"):
		return TopologyMoveResult.blocked(&"secret_hidden", cell)
	return TopologyMoveResult.permitted(cell)


func probe_movement(coordinate: Vector2i, move_direction: Vector2i, world_state: WorldState, level_type: StringName, party_in_boat: bool = false) -> TopologyMoveResult:
	if level_type == &"land":
		if not is_cardinal_direction(move_direction) and not is_diagonal_direction(move_direction):
			return TopologyMoveResult.blocked(&"invalid_direction")
		return probe_land_entry(coordinate, world_state, party_in_boat)
	if not is_cardinal_direction(move_direction):
		return TopologyMoveResult.blocked(&"invalid_direction")
	return probe_entry(coordinate, move_direction, world_state)


func has_line_of_sight(from: Vector2i, to: Vector2i, world_state: WorldState) -> bool:
	if not contains(from) or not contains(to):
		return false
	var x := from.x
	var y := from.y
	var dx := absi(to.x - from.x)
	var dy := -absi(to.y - from.y)
	var step_x := 1 if from.x < to.x else -1
	var step_y := 1 if from.y < to.y else -1
	var error := dx + dy
	while x != to.x or y != to.y:
		var twice_error := 2 * error
		if twice_error >= dy:
			error += dy
			x += step_x
		if twice_error <= dx:
			error += dx
			y += step_y
		var cell := effective_cell_at(Vector2i(x, y), world_state)
		if cell == null:
			return false
		if Vector2i(x, y) != to and _cell_blocks_los(cell, world_state):
			return false
	return true


func visible_cells(origin: Vector2i, radius: int, world_state: WorldState, use_los: bool) -> Array[Vector2i]:
	var result: Array[Vector2i] = []
	var first_x := 0 if not use_los else maxi(0, origin.x - radius)
	var first_y := 0 if not use_los else maxi(0, origin.y - radius)
	var last_x := width if not use_los else mini(width, origin.x + radius + 1)
	var last_y := height if not use_los else mini(height, origin.y + radius + 1)
	for y: int in range(first_y, last_y):
		for x: int in range(first_x, last_x):
			var coordinate := Vector2i(x, y)
			if not use_los or origin.distance_squared_to(coordinate) <= radius * radius and has_line_of_sight(origin, coordinate, world_state):
				result.append(coordinate)
	return result


func _decode_compact_cell(index: int, coordinate: Vector2i) -> MapCell:
	if index < 0 or index >= _compact_rows.size():
		return null
	var row: Array = _compact_rows[index]
	var flags := int(row[2])
	var trigger_ids: Array[String] = []
	trigger_ids.assign(row[4])
	var random_rect_ids: Array[String] = []
	random_rect_ids.assign(row[5])
	var edges: Dictionary = {}
	var edge_rows: Array = row[6]
	var directions: Array[StringName] = [&"north", &"east", &"south", &"west"]
	for direction_index: int in directions.size():
		var edge_row: Array = edge_rows[direction_index]
		var edge_flags := int(edge_row[1])
		edges[directions[direction_index]] = MapEdge.new(
			StringName(edge_row[0]),
			bool(edge_flags & 1),
			bool(edge_flags & 2),
			"" if edge_row[2] == null else String(edge_row[2]),
			"" if edge_row[3] == null else String(edge_row[3]),
			bool(edge_flags & 4)
		)
	var features: Array[MapFeature] = []
	for feature_value: Variant in row[7]:
		var feature_row: Array = feature_value
		features.append(MapFeature.new(
			String(feature_row[0]),
			StringName(feature_row[1]),
			&"" if feature_row[2] == null else StringName(feature_row[2]),
			&"" if feature_row[3] == null else StringName(feature_row[3])
		))
	return MapCell.new(
		"%s:cell:%d,%d" % [_compact_map_id, coordinate.x, coordinate.y],
		coordinate,
		String(row[0]),
		bool(flags & 1),
		int(row[1]),
		bool(flags & 2),
		bool(flags & 4),
		bool(flags & 8),
		bool(flags & 16),
		bool(flags & 32),
		bool(flags & 64),
		bool(flags & 128),
		-1 if row[3] == null else int(row[3]),
		int(row[8]),
		String(row[9]),
		trigger_ids,
		rando...

