		if candidate != instance and candidate.equipped and not item.cursed_item_id.is_empty():
			return InventoryActionProbe.block("An equipped cursed stack cannot be absorbed into another item.")
	return InventoryActionProbe.permit()


func equip_classic(character: CharacterState, instance: ItemInstance, item: ItemDefinition, race: RaceDefinition, caste: CasteDefinition, party: Array[CharacterState], definitions: Array[ItemDefinition]) -> InventoryActionProbe:
	var probe := classic_equip_probe(character, instance, item, race, caste, party, definitions)
	if not probe.allowed:
		return probe
	instance.equipped = true
	if not item.cursed_item_id.is_empty():
		instance.identified = true
	return probe


func unequip_classic(character: CharacterState, instance: ItemInstance, item: ItemDefinition, definitions: Array[ItemDefinition]) -> InventoryActionProbe:
	var probe := classic_unequip_probe(character, instance, item, definitions)
	if probe.allowed:
		instance.equipped = false
	return probe


func trade_classic(source: CharacterState, destination: CharacterState, instance: ItemInstance, item: ItemDefinition) -> InventoryActionProbe:
	var probe := classic_trade_probe(source, destination, instance, item)
	if not probe.allowed:
		return probe
	var removed := remove_item(source, instance.id, item)
	if removed == null or not restore_item(destination, removed, item):
		if removed != null:
			restore_item(source, removed, item)
		return InventoryActionProbe.block("The item transfer could not be committed.")
	return probe


func split_classic(character: CharacterState, instance: ItemInstance, item: ItemDefinition, new_instance_id: String) -> InventoryActionProbe:
	var probe := classic_split_probe(character, instance, item)
	if not probe.allowed:
		return probe
	if new_instance_id.is_empty():
		return InventoryActionProbe.block("The split item requires a stable instance identity.")
	var items := character.inventory()
	for carried: ItemInstance in items:
		if carried.id == new_instance_id:
			return InventoryActionProbe.block("The split item identity is already in use.")
	var source_index := items.find(instance)
	if source_index < 0:
		return InventoryActionProbe.block("The selected item is no longer carried.")
	var previous_weight := item.instance_weight(instance.charges)
	var split_charges := int(instance.charges / 2)
	instance.charges -= split_charges
	var split_instance := ItemInstance.new(new_instance_id, instance.definition_id, split_charges, false, instance.identified)
	items.insert(source_index + 1, split_instance)
	character.set_inventory(items)
	var updated_weight := item.instance_weight(instance.charges) + item.instance_weight(split_instance.charges)
	character.carried_load = maxi(0, character.carried_load + updated_weight - previous_weight)
	return probe


func join_classic(character: CharacterState, instance: ItemInstance, item: ItemDefinition) -> InventoryActionProbe:
	var probe := classic_join_probe(character, instance, item)
	if not probe.allowed:
		return probe
	var items := character.inventory()
	var matches := _matching_instances(character, instance.definition_id)
	var total_charges := 0
	var previous_weight := 0
	var merged_equipped := false
	var merged_identified := false
	for candidate: ItemInstance in matches:
		total_charges += candidate.charges
		previous_weight += item.instance_weight(candidate.charges)
		merged_equipped = merged_equipped or candidate.equipped
		merged_identified = merged_identified or candidate.identified
		if candidate != instance:
			items.erase(candidate)
	instance.charges = total_charges
	instance.equipped = merged_equipped
	instance.identified = merged_identified
	character.set_inventory(items)
	character.carried_load = maxi(0, character.carried_load + item.instance_weight(total_charges) - previous_weight)
	return probe


func add_item(character: CharacterState, item: ItemDefinition, instance_id: String, identified: bool = false) -> ItemInstance:
	if character == null or item == null or character.inventory().size() >= MAX_ITEMS:
		return null
	var instance := ItemInstance.new(instance_id, item.id, item.initial_charges, false, identified)
	var items := character.inventory()
	if character.carried_load + item.instance_weight(instance.charges) > character.maximum_load:
		return null
	items.append(instance)
	character.set_inventory(items)
	character.carried_load += item.instance_weight(instance.charges)
	return instance


func calculated_load(character: CharacterState, definitions: Array[ItemDefinition]) -> int:
	if character == null:
		return -1
	var definitions_by_id := _definitions_by_id(definitions)
	var total := character.money.gold + character.money.gems + character.money.jewelry * 15
	for instance: ItemInstance in character.inventory():
		var definition: ItemDefinition = definitions_by_id.get(instance.definition_id)
		if definition == null:
			return -1
		total += definition.instance_weight(instance.charges)
	return maxi(0, total)


func equip(character: CharacterState, instance_id: String, definition: ItemDefinition) -> bool:
	if not can_equip(character, definition):
		return false
	for instance: ItemInstance in character.inventory():
		if instance.id == instance_id and instance.definition_id == definition.id:
			instance.equipped = true
			return true
	return false


func use_charge(character: CharacterState, instance_id: String, definition: ItemDefinition) -> bool:
	var items := character.inventory()
	for index: int in items.size():

	for index: int in 15:
		var amount := character.ability_value(index)
		if amount != 0:
			var detail := "The original label is not recoverable from the pinned source tree; the Classic slot and value are preserved." if ABILITY_NAMES[index].begins_with("Classic ability") else ""
			abilities.append(CharacterMetricView.new(StringName("ability-%d" % index), index, ABILITY_NAMES[index], amount, detail))
	for item: ItemInstance in character.inventory():
		var definition := null if content == null else content.item_by_id(item.definition_id)
		var presentation_definition: ItemDefinition = definition
		if definition != null and not item.equipped and not definition.cursed_item_id.is_empty():
			presentation_definition = content.item_by_id(definition.cursed_item_id)
		items.append(ItemView.new(item, definition, presentation_definition, content))
	if content != null:
		for spell_id: String in character.known_spells():
			var definition := content.spell_by_id(spell_id)
			if definition != null:
				spells.append(SpellView.new(definition))
		for index: int in character.scroll_case().size():
			var scroll := character.scroll_at(index)
			scrolls.append(SpellScrollView.new(index, scroll, content.spell_by_id(scroll.spell_id) if scroll != null and not scroll.is_empty() else null))
	for index: int in character.fast_spells().size():
		var binding := character.fast_spell_at(index)
		fast_spells.append(FastSpellBindingView.new(index, binding, content.spell_by_id(binding.spell_id) if content != null and binding != null and not binding.is_empty() else null))


func apply_equipment(equipment: CharacterCombatEquipment) -> void:
	if equipment == null or not equipment.valid:
		return
	damage_bonus = equipment.effective_damage_bonus
	luck = equipment.effective_luck
	armor = equipment.effective_armor
	_refresh_display_bonuses(equipment.equipped_damage_bonus)


func _refresh_display_bonuses(equipped_damage: int) -> void:
	attack_bonus = to_hit + 5 * equipped_damage
	attack_bonus += 15 if _condition(ConditionRules.STRONG) != 0 else 0
	attack_bonus -= 15 if _condition(ConditionRules.SLOW) != 0 else 0
	attack_bonus -= 10 if _condition(ConditionRules.CONFUSED) != 0 else 0
	attack_bonus -= 15 if _condition(ConditionRules.BLIND) != 0 else 0
	attack_bonus += 5 if _condition(ConditionRules.MAGIC_AURA) != 0 else 0
	attack_bonus -= 5 if _condition(ConditionRules.CURSED) != 0 else 0
	attack_bonus -= absi(_condition(ConditionRules.TANGLED))
	attack_bonus -= absi(_condition(ConditionRules.HINDERED_ATTACKS))
	defense_bonus = armor
	defense_bonus += 10 if _condition(ConditionRules.INVISIBLE) != 0 else 0
	defense_bonus -= 15 if _condition(ConditionRules.SLOW) != 0 else 0
	defense_bonus -= 10 if _condition(ConditionRules.CONFUSED) != 0 else 0
	defense_bonus -= 15 if _condition(ConditionRules.BLIND) != 0 else 0
	defense_bonus += 5 if _condition(ConditionRules.MAGIC_AURA) != 0 else 0
	defense_bonus -= 5 if _condition(ConditionRules.CURSED) != 0 else 0
	defense_bonus -= absi(_condition(ConditionRules.TANGLED))
	defense_bonus -= absi(_condition(ConditionRules.HINDERED_DEFENSE))
	defense_bonus += absi(_condition(ConditionRules.DEFENSE_BONUS))
	defense_bonus += 2 * absi(_condition(ConditionRules.SHIELD_FROM_HITS))


func _condition(index: int) -> int:
	return condition_values[index] if index >= 0 and index < condition_values.size() else 0


func _populate_race_details(race: RaceDefinition) -> void:
	race_traits = [
		CharacterMetricView.new(&"base-movement", 0, "Base Movement", race.base_movement),
		CharacterMetricView.new(&"magic-resistance", 1, "Magic Resistance", race.magic_resistance),
		CharacterMetricView.new(&"two-hand", 2, "Two-Hand Bonus", race.two_hand_bonus),
		CharacterMetricView.new(&"missile", 3, "Missile Bonus", race.missile_bonus),
		CharacterMetricView.new(&"base-attacks", 4, "Base Attacks", race.base_attacks),
		CharacterMetricView.new(&"maximum-attacks", 5, "Maximum Attacks", race.maximum_attacks),
		CharacterMetricView.new(&"maximum-age", 6, "Maximum Age", race.max_age, "Does not die of age" if race.does_not_die else ""),
		CharacterMetricView.new(&"regeneration", 7, "Regenerates", 1 if race.can_regenerate else 0, "Yes" if race.can_regenerate else "No"),
	]
	for band_index: int in 5:
		var age_range := race.age_range(band_index)
		var active := age_years >= age_range.x and age_years <= age_range.y
		age_bands.append(CharacterAgeBandView.new(band_index + 1, _age_group_name(band_index + 1), age_range, active, race.age_change(band_index), AGE_CHANGE_NAMES))


func _populate_caste_details(caste: CasteDefinition) -> void:
	caste_traits = [
		CharacterMetricView.new(&"minimum-age-group", 0, "Minimum Age Group", caste.minimum_age_group, _age_group_name(caste.minimum_age_group)),
		CharacterMetricView.new(&"movement-bonus", 1, "Movement Bonus", caste.movement_bonus),
		CharacterMetricView.new(&"magic-resistance-multiplier", 2, "Magic Resistance Multiplier", caste.magic_resistance_multiplier),
		CharacterMetricView.new(&"two-hand", 3, "Two-Hand Bonus", caste.two_hand_bonus),
		CharacterMetricView.new(&"maximum-stamina-bonus", 4, "Maximum Stamina Bonus", caste.maximum_stamina_bonus),
		CharacterMetricView.new(&"bonus-attacks", 5, "Bonus Attacks", caste.bonus_attacks),
		CharacterMetricView.new(&"maximum-attacks", 6, "Maximum Attacks", caste.maximum_attacks),
		CharacterMetricView.new(&"missile-use", 7, "Can Use Missile Weapons", 1 if caste.can_use_missile else 0, "Yes" if caste.can_use_missile else "No"),
		CharacterMetricView.new(&"missile-bonus", 8, "Receives Missile Bonus", 1 if caste.gets_missile_bonus else 0, "Yes" if caste.gets_missile_bonus else "No"),
	]


static func _attacks_per_round(total: int) -> String:
	if total >= 2 and total <= 19:
		return "%d/%d" % [floori(float(total) / 2.0) if total % 2 == 0 else total, 1 if total % 2 == 0 else 2]
	if total > 12:
		return ">/10"
	return "1/1"


static func _label_at(labels: Array[String], index: int, fallback: String) -> String:
	return fallback if index < 0 or index >= labels.size() else labels[index]


static func _age_group_name(group: int) -> String:
	return CharacterAgingResult.age_group_name(group)

class_name CombatView
extends RefCounted

var battle_id: String
var round_number: int
var active_actor_id: String
var attack_units_remaining: int = 0
var movement_remaining: int = 0
var weapon_mode: StringName = &"melee"
var melee_weapon_id: String = ""
var missile_weapon_id: String = ""
var weapon_switch_available: bool = false
var weapon_switch_target_mode: StringName = &""
var weapon_switch_unavailable_reason: String = "The active combatant has no alternate weapon mode."
var ranged_attack_unavailable_reason: String = ""
var melee_attack_unavailable_reason: String = ""
var equipment_error_reason: String = ""
var retreat_available: bool = false
var retreat_unavailable_reason: String = "Retreat is unavailable."
var nearest_enemy_range: int = 127
var outcome: StringName
var turn_order: Array[String] = []
var friendly_actor_ids: Array[String] = []
var hostile_actor_ids: Array[String] = []
var legal_actions: Array[StringName] = []
var targets: Array[MonsterView] = []
var character_targets: Array[CharacterView] = []
var movement_options: Array[CombatMoveOptionView] = []
var monsters: Array[MonsterView] = []
var battlefield: BattlefieldView
var auto_turn: ActionAvailabilityView = ActionAvailabilityView.new(&"auto", false, "Auto Turn is unavailable.")
var delay: ActionAvailabilityView = ActionAvailabilityView.new(&"delay", false, "Delay is unavailable.")
var bandage: ActionAvailabilityView = ActionAvailabilityView.new(&"bandage", false, "Bandage is unavailable.")
var turn_undead: ActionAvailabilityView = ActionAvailabilityView.new(&"turn_undead", false, "Turn Undead is unavailable.")
var undo: ActionAvailabilityView = ActionAvailabilityView.new(&"undo", false, "Undo is unavailable.")
var bandage_candidates: Array[CharacterView] = []
var turn_undead_targets: Array[MonsterView] = []
var auto_character_ids: Array[String] = []


func _init(combat: CombatState, characters: Array[CharacterState] = [], content: RealmzContent = null, inventory_rules: InventoryRules = null, battlefield_rules: BattlefieldRules = null, combat_flow: CombatFlow = null, game_state: GameState = null) -> void:
	battle_id = combat.battle_id
	round_number = combat.round_number
	active_actor_id = combat.active_actor_id()
	outcome = combat.outcome
	turn_order = combat.turn_order()
	if combat.battlefield != null:
		var upper_tileset_id := ""
		if content != null:
			var source_map := content.world.map_by_id(combat.battlefield.map_id)
			if source_map != null and source_map.level_type == &"land" and source_map.landlook >= 0:
				upper_tileset_id = "landlook-%d" % source_map.landlook
		battlefield = BattlefieldView.new(combat.battlefield, upper_tileset_id)
	var adjacent_ids: Array[String] = []
	if combat.battlefield != null and battlefield_rules != null and not active_actor_id.is_empty():
		adjacent_ids = battlefield_rules.adjacent_actor_ids(combat.battlefield, active_actor_id)
	for monster: MonsterState in combat.monsters():
		var definition := content.monster_by_id(monster.definition_id) if content != null else null
		var view := MonsterView.new(monster, definition, content)
		monsters.append(view)
		if monster.current_health > 0 and monster.traitor and adjacent_ids.has(monster.id):
			targets.append(view)
	for character: CharacterState in characters:
		if character.id == active_actor_id:
			attack_units_remaining = character.attacks_remaining
			movement_remaining = character.maximum_movement if combat.active_turn == null else character.movement
		if character.current_health > 0 and character.traitor and adjacent_ids.has(character.id):
			character_targets.append(CharacterView.new(character, content))
	_populate_active_relationships(combat, characters)
	if combat.completed:
		return
	var active_character: CharacterState = null
	for character: CharacterState in characters:
		if character.id == active_actor_id:
			active_character = character
			break
	if active_character != null and content != null and inventory_rules != null:
		if combat_flow != null:
			var retreat_probe: Variant = combat_flow.probe_character_retreat(combat, characters, active_character.id)
			retreat_available = retreat_probe.allowed
			retreat_unavailable_reason = retreat_probe.reason_text
			nearest_enemy_range = retreat_probe.nearest_enemy_range
			auto_turn = ActionAvailabilityView.new(&"auto", true)
			var delay_probe := combat_flow.probe_delay(game_state, active_character.id)
			delay = ActionAvailabilityView.new(&"delay", delay_probe.allowed, delay_probe.reason_text)
			var bandage_probe := combat_flow.probe_bandage(game_state, active_character.id)
			bandage = ActionAvailabilityView.new(&"bandage", bandage_probe.allowed, bandage_probe.reason_text)
			var turn_probe := combat_flow.probe_turn_undead(game_state, content, active_character.id)
			turn_undead = ActionAvailabilityView.new(&"turn_undead", turn_probe.allowed, turn_probe.reason_text)
			var undo_probe := combat_flow.probe_undo(game_state, active_character.id)
			undo = ActionAvailabilityView.new(&"undo", undo_probe.allowed, undo_probe.reason_text)
			for candidate_id: String in combat_flow.bandage_candidate_ids(game_state):
				var candidate := game_state.party.character_by_id(candidate_id)
				if candidate != null:
					bandage_candidates.append(CharacterView.new(candidate, content))
			for target_id: String in combat_flow.turn_undead_target_ids(game_state, content):
				var target := combat.monster_by_id(target_id)
				if target != null:
					turn_undead_targets.append(MonsterView.new(target, content.monster_by_id(target.definition_id), content))
		var equipment := inventory_rules.combat_equipment(active_character, content.item_definitions())
		if equipment.valid:
			weapon_mode = combat.character_weapon_mode(active_character.id)
			melee_weapon_id = equipment.melee_weapon.id if equipment.melee_weapon != null else ""
			missile_weapon_id = equipment.missile_weapon.id if equipment.missile_weapon != null else ""
			weapon_switch_available = weapon_mode == &"missile" or equipment.missile_weapon != null
			weapon_switch_target_mode = &"melee" if weapon_mode == &"missile" else &"missile"
			weapon_switch_unavailable_reason = "" if weapon_switch_available else "The active character has no equipped Classic type-15 missile weapon."
			if weapon_mode != &"melee":
				targets.clear()
				character_targets.clear()
				var profile := combat_flow.character_projectile_profile(active_character, content, equipment) if combat_flow != null else null
				if profile == null or not profile.available:
					ranged_attack_unavailable_reason = profile.error_message if profile != null else "Projectile rules are unavailable."
				else:
					for monster: MonsterState in combat.monsters():
						if monster.current_health > 0 and monster.traitor != active_character.traitor and combat_flow.projectile_target_is_valid(combat, content, active_character.id, monster.id, profile.maximum_range, profile.spell.range_min + profile.spell.range_max > 0):
							targets.append(MonsterView.new(monster, content.monster_by_id(monster.definition_id), content))
					if targets.is_empty():
						ranged_attack_unavailable_reason = "No hostile monster is within the projectile's Classic range and line of sight."
					else:
						legal_actions.append(&"attack")
			if weapon_switch_available:
				legal_actions.append(&"switch_weapon")
		else:
			equipment_error_reason = equipment.error_message
			weapon_switch_unavailable_reason = equipment.error_message
		if combat.battlefield != null and battlefield_rules != null:
			var map := content.world.map_by_id(combat.battlefield.map_id)
			var terrain_set := content.world.battle_terrain_set_by_id(map.battle_terrain_set_id) if map != null else null
			if terrain_set != null:
				var contact_attack_available := false
				var movement_allowance := active_character.maximum_movement if combat.active_turn == null else active_character.movement
				for direction: Vector2i in BattlefieldRules.DIRECTIONS:
					var destination := combat.battlefield.actor_position(active_character.id) + direction
					var edge_retreat: Variant = combat_flow.probe_edge_retreat(combat, active_character.id, destination) if combat_flow != null else null
					var probe := battlefield_rules.probe_step(combat.battlefield, terrain_set, active_character.id, direction, movement_allowance)
					var contact_target_id := ""
					var contact_target_name := ""
					if weapon_mode == &"melee" and probe.reason == &"occupied" and _is_hostile_target(combat, characters, active_character, probe.occupant_id):
						contact_target_id = probe.occupant_id
						contact_target_name = _target_name(combat, characters, contact_target_id)
						contact_attack_available = true
					movement_options.append(CombatMoveOptionView.new(direction, probe, edge_retreat != null and edge_retreat.allowed, edge_retreat != null and edge_retreat.forced, contact_target_id, contact_target_name))
				if weapon_mode == &"melee" and not contact_attack_available:
					melee_attack_unavailable_reason = "No hostile battlefield footprint is adjacent."
				if weapon_mode == &"melee":
					targets.clear()
					character_targets.clear()
	legal_actions.append(&"finish")
	legal_actions.append(&"defend")
	if retreat_available:
		legal_actions.append(&"retreat")
	if auto_turn.enabled:
		legal_actions.append(&"auto")
	if delay.enabled:
		legal_actions.append(&"delay")
	if bandage.enabled:
		legal_actions.append(&"bandage")
	if turn_undead.enabled:
		legal_actions.append(&"turn_undead")

	if undo.enabled:
		legal_actions.append(&"undo")
	if game_state != null:
		auto_character_ids = game_state.combat_auto_character_ids()


func _populate_active_relationships(combat: CombatState, characters: Array[CharacterState]) -> void:
	if combat.battlefield == null:
		return
	for character: CharacterState in characters:
		if character.current_health <= 0 or not combat.battlefield.has_actor(character.id):
			continue
		(friendly_actor_ids if not character.traitor else hostile_actor_ids).append(character.id)
	for monster: MonsterState in combat.monsters():
		if monster.current_health <= 0 or not combat.battlefield.has_actor(monster.id):
			continue
		(friendly_actor_ids if not monster.traitor else hostile_actor_ids).append(monster.id)


static func _is_hostile_target(combat: CombatState, characters: Array[CharacterState], actor: CharacterState, target_id: String) -> bool:
	if target_id.is_empty() or actor == null:
		return false
	var monster := combat.monster_by_id(target_id)
	if monster != null:
		return monster.current_health > 0 and monster.traitor != actor.traitor
	for character: CharacterState in characters:
		if character.id == target_id:
			return character.current_health > 0 and character.traitor != actor.traitor
	return false


static func _target_name(combat: CombatState, characters: Array[CharacterState], target_id: String) -> String:
	var monster := combat.monster_by_id(target_id)
	if monster != null:
		return monster.name
	for character: CharacterState in characters:
		if character.id == target_id:
			return character.name
	return target_id

class_name DefinitionOptionView
extends RefCounted

var id: String
var name: String
var description: String = ""
var related_ids: Array[String] = []
var facts: Array[String] = []


func _init(definition_id: String, display_name: String, display_description: String = "", related_definition_ids: Array[String] = [], display_facts: Array[String] = []) -> void:
	id = definition_id
	name = display_name
	description = display_description
	related_ids = related_definition_ids.duplicate()
	facts = display_facts.duplicate()


static func from_race(definition: RaceDefinition) -> DefinitionOptionView:
	var display_facts: Array[String] = [
		"Movement %d" % definition.base_movement,
	]
	var attack_fraction := _race_attack_fraction(definition.base_attacks)
	if not attack_fraction.is_empty():
		display_facts.append("Attacks %s • Maximum %d" % [attack_fraction, definition.maximum_attacks])
	_append_signed(display_facts, "Magic resistance", definition.magic_resistance)
	_append_signed(display_facts, "Missile adjustment", definition.missile_bonus)
	_append_signed(display_facts, "Two-hand adjustment", definition.two_hand_bonus)
	if definition.max_age > 0:
		display_facts.append("Maximum age %d" % definition.max_age)
	var attributes := _named_modifiers(definition.attribute_bonus, ["Brawn", "Knowledge", "Judgment", "Agility", "Vitality", "Luck"])
	if not attributes.is_empty():
		display_facts.append("Attributes • %s" % attributes)
	var saves := _named_modifiers(definition.save_bonus, ["Charm", "Fire", "Cold", "Shock", "Chemical", "Mental", "SP drain", "Special"])
	if not saves.is_empty():
		display_facts.append("Saves • %s" % saves)
	return DefinitionOptionView.new(definition.id, definition.name, definition.description, definition.eligible_caste_ids, display_facts)


static func from_caste(definition: CasteDefinition) -> DefinitionOptionView:
	var display_facts: Array[String] = [
		"Stamina d%d initially • d%d per level" % [definition.initial_stamina_die(), definition.level_stamina_die()],
		"To hit %+d initially • %+d per level" % [definition.initial_to_hit(), definition.level_to_hit()],
		"Dodge %+d initially • %+d per level" % [definition.initial_dodge(), definition.level_dodge()],
	]
	if definition.can_use_missile:
		display_facts.append("Missile %+d initially • %+d per level" % [definition.initial_missile(), definition.level_missile()])
	else:
		display_facts.append("Cannot use missile weapons")
	display_facts.append("Hand to hand %+d initially • %+d per level" % [definition.initial_hand_to_hand(), definition.level_hand_to_hand()])
	if definition.minimum_age_group > 0:
		display_facts.append("Minimum age %s" % _minimum_age_label(definition.minimum_age_group))
	_append_signed(display_facts, "Movement", definition.movement_bonus)
	var attack_bonus := _caste_attack_fraction(definition.bonus_attacks)
	if not attack_bonus.is_empty():
		display_facts.append("Bonus attacks %s" % attack_bonus)
	_append_signed(display_facts, "Two-hand adjustment", definition.two_hand_bonus)
	_append_signed(display_facts, "Maximum stamina bonus", definition.maximum_stamina_bonus)
	if definition.magic_resistance_multiplier != 1:
		display_facts.append("Magic resistance ×%d" % definition.magic_resistance_multiplier)
	if definition.spellcaster_rows().any(func(row: Vector3i) -> bool: return row.y > 0):
		display_facts.append("Spellcaster")
	if definition.gets_missile_bonus:
		display_facts.append("Receives missile bonus")
	if definition.start_money != 0:
		display_facts.append("Starting gold %d" % definition.start_money)
	var attributes := _named_modifiers(definition.attribute_bonus, ["Brawn", "Knowledge", "Judgment", "Agility", "Vitality", "Luck"])
	if not attributes.is_empty():
		display_facts.append("Attributes • %s" % attributes)
	var saves := _named_modifiers(definition.save_bonus, ["Charm", "Fire", "Cold", "Shock", "Chemical", "Mental", "SP drain", "Special"])
	if not saves.is_empty():
		display_facts.append("Saves • %s" % saves)
	return DefinitionOptionView.new(definition.id, definition.name, definition.description, definition.eligible_race_ids, display_facts)


static func _append_signed(target: Array[String], label: String, value: int) -> void:
	if value != 0:
		target.append("%s %s" % [label, "%+d" % value])


static func _named_modifiers(reader: Callable, labels: Array[String]) -> String:
	var values: Array[String] = []
	for index: int in labels.size():
		var value := int(reader.call(index))
		if value != 0:
			values.append("%s %+d" % [labels[index], value])
	return " • ".join(values)


static func _race_attack_fraction(value: int) -> String:
	match value:
		2: return "1"
		3: return "1 1/2"
		4: return "2"
		_: return ""


static func _caste_attack_fraction(value: int) -> String:
	match value:
		1: return "1/2"
		2: return "1"
		3: return "1 1/2"
		4: return "2"
		_: return ""


static func _minimum_age_label(value: int) -> String:
	match value:
		2: return "Young"
		3: return "Prime"
		4: return "Adult"
		5: return "Senior"
		_: return "Youth"

