class_name LocationNoteState
extends RefCounted

const MAX_TEXT_BYTES: int = 255
const MAX_NOTES_PER_MAP_KIND: int = 501

var map_id: String = ""
var map_kind: StringName = &""
var level_index: int = -1
var coordinate: Vector2i = Vector2i.ZERO
var native_location_id: int = -1
var darkness_value: int = 0
var record_ordinal: int = -1
var text: String = ""


func _init(note_map_id: String = "", note_map_kind: StringName = &"", note_level_index: int = -1, note_coordinate: Vector2i = Vector2i.ZERO, note_text: String = "", note_darkness_value: int = 0, note_record_ordinal: int = -1) -> void:
	map_id = note_map_id
	map_kind = note_map_kind
	level_index = note_level_index
	coordinate = note_coordinate
	native_location_id = native_id_for(level_index, coordinate)
	darkness_value = note_darkness_value
	record_ordinal = note_record_ordinal
	text = note_text


func id() -> String:
	return key_for(map_id, coordinate)


func to_data() -> Dictionary:
	return {
		"mapId": map_id,
		"mapKind": String(map_kind),
		"levelIndex": level_index,
		"x": coordinate.x,
		"y": coordinate.y,
		"nativeLocationId": native_location_id,
		"darknessValue": darkness_value,
		"recordOrdinal": record_ordinal,
		"text": text,
	}


static func from_data(data: Variant) -> LocationNoteState:
	if not data is Dictionary:
		return null
	for field: String in ["mapId", "mapKind", "levelIndex", "x", "y", "nativeLocationId", "darknessValue", "recordOrdinal", "text"]:
		if not data.has(field):
			return null
	if not data["mapId"] is String or String(data["mapId"]).is_empty() or not data["mapKind"] is String or not data["text"] is String:
		return null
	var map_kind_value := StringName(String(data["mapKind"]))
	if map_kind_value != &"land" and map_kind_value != &"dungeon":
		return null
	var level := _integer(data["levelIndex"])
	var x := _integer(data["x"])
	var y := _integer(data["y"])
	var native_id := _integer(data["nativeLocationId"])
	var darkness := _integer(data["darknessValue"])
	var ordinal := _integer(data["recordOrdinal"])
	var note_text := String(data["text"])
	if level < 0 or x < 0 or y < 0 or native_id != native_id_for(level, Vector2i(x, y)) or darkness < 0 or darkness > 255 or ordinal < 0 or ordinal >= MAX_NOTES_PER_MAP_KIND or note_text.is_empty() or not text_is_valid(note_text):
		return null
	return LocationNoteState.new(String(data["mapId"]), map_kind_value, level, Vector2i(x, y), note_text, darkness, ordinal)


static func text_is_valid(value: String) -> bool:
	return value.to_utf8_buffer().size() <= MAX_TEXT_BYTES


func is_structurally_valid() -> bool:
	return (
		not map_id.is_empty()
		and (map_kind == &"land" or map_kind == &"dungeon")
		and level_index >= 0
		and coordinate.x >= 0
		and coordinate.y >= 0
		and native_location_id == native_id_for(level_index, coordinate)
		and darkness_value >= 0
		and darkness_value <= 255
		and record_ordinal >= 0
		and record_ordinal < MAX_NOTES_PER_MAP_KIND
		and not text.is_empty()
		and text_is_valid(text)
	)


static func key_for(note_map_id: String, note_coordinate: Vector2i) -> String:
	return "%s:%d,%d" % [note_map_id, note_coordinate.x, note_coordinate.y]


static func native_id_for(note_level_index: int, note_coordinate: Vector2i) -> int:
	return 10_000 * note_level_index + note_coordinate.x * 90 + note_coordinate.y


static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -100_000

class_name MonsterState
extends RefCounted

var id: String
var definition_id: String
var name: String
var hit_dice: int
var current_health: int
var maximum_health: int
var agility: int
var armor: int
var magic_resistance: int
var spell_points: int
var maximum_spell_points: int
var traitor: bool
var icon_id: int = 0
var surrender_percent: int = 0
var weapon_id: String = ""
var target_id: String = ""
var conditions: ConditionSet
var _saves: Array[int] = []
var _saves_initialized: bool = false
var _loot_item_ids: Array[String] = []


func _init(instance_id: String, source_definition_id: String, display_name: String, health: int, max_health: int, hd: int = 1, dexterity: int = 1, armor_rating: int = 0, magic_resist: int = 0, spell_energy: int = 0, is_traitor: bool = true) -> void:
	id = instance_id
	definition_id = source_definition_id
	name = display_name
	current_health = health
	maximum_health = max_health
	hit_dice = hd
	agility = dexterity
	armor = armor_rating
	magic_resistance = magic_resist
	spell_points = spell_energy
	maximum_spell_points = spell_energy
	traitor = is_traitor
	conditions = ConditionSet.new()
	_saves.resize(8)
	_saves.fill(0)


func save_value(index: int) -> int:
	return 0 if index < 0 or index >= _saves.size() else _saves[index]


func set_save_value(index: int, value: int) -> bool:
	if index < 0 or index >= _saves.size() or value < -128 or value > 32767:
		return false
	_saves[index] = value
	_saves_initialized = true
	return true


func save_values() -> Array[int]:
	return _saves.duplicate()


func has_runtime_saves() -> bool:
	return _saves_initialized


func loot_item_ids() -> Array[String]:
	return _loot_item_ids.duplicate()


func set_loot_item_ids(values: Array[String]) -> bool:
	if values.size() > 6:
		return false
	_loot_item_ids = values.duplicate()
	return true


func to_data() -> Dictionary:
	var result := {
		"id": id,
		"definitionId": definition_id,
		"name": name,
		"hitDice": hit_dice,
		"currentHealth": current_health,
		"maximumHealth": maximum_health,
		"agility": agility,
		"armor": armor,
		"magicResistance": magic_resistance,
		"spellPoints": spell_points,
		"maximumSpellPoints": maximum_spell_points,
		"traitor": traitor,
		"iconId": icon_id,
		"surrenderPercent": surrender_percent,
		"weaponId": weapon_id,
		"targetId": target_id,
		"lootItemIds": _loot_item_ids.duplicate(),
		"conditions": conditions.to_data(),
	}
	if _saves_initialized:
		result["saves"] = _saves.duplicate()
	return result


static func from_data(data: Variant) -> MonsterState:
	if not data is Dictionary:
		return null
	for field: String in ["id", "definitionId", "name", "hitDice", "currentHealth", "maximumHealth", "agility", "armor", "magicResistance", "spellPoints", "maximumSpellPoints", "traitor", "weaponId", "conditions"]:
		if not data.has(field):
			return null
	if not data["id"] is String or data["id"].is_empty() or not data["definitionId"] is String or data["definitionId"].is_empty() or not data["name"] is String or not data["traitor"] is bool or not data["weaponId"] is String:
		return null
	var values: Dictionary = {}
	for field: String in ["hitDice", "currentHealth", "maximumHealth", "agility", "armor", "magicResistance", "spellPoints", "maximumSpellPoints"]:
		var value := _integer(data[field])
		if value == -100_000:
			return null
		values[field] = value
	if values["hitDice"] < 0 or values["maximumHealth"] < 1 or values["maximumHealth"] > 32_767 or values["currentHealth"] < -32_768 or values["currentHealth"] > 32_767 or values["maximumSpellPoints"] < 0 or values["maximumSpellPoints"] > 32_767 or values["spellPoints"] < -32_768 or values["spellPoints"] > 32_767:
		return null
	var loaded_conditions := ConditionSet.from_data(data["conditions"], ConditionSet.CHARACTER_COUNT)
	if loaded_conditions == null:
		return null
	var result := MonsterState.new(data["id"], data["definitionId"], data["name"], values["currentHealth"], values["maximumHealth"], values["hitDice"], values["agility"], values["armor"], values["magicResistance"], values["maximumSpellPoints"], data["traitor"])
	result.spell_points = values["spellPoints"]
	result.icon_id = _integer(data.get("iconId", 0))
	if result.icon_id == -100_000:
		return null
	result.surrender_percent = _integer(data.get("surrenderPercent", 0))
	if result.surrender_percent == -100_000:
		return null
	result.weapon_id = data["weaponId"]
	var loot_data: Variant = data.get("lootItemIds", [])
	if not loot_data is Array or loot_data.size() > 6:
		return null
	var loot_ids: Array[String] = []
	for loot_id: Variant in loot_data:
		if not loot_id is String:
			return null
		loot_ids.append(loot_id)
	if not result.set_loot_item_ids(loot_ids):
		return null
	if data.has("targetId"):
		if not data["targetId"] is String:
			return null
		result.target_id = data["targetId"]
	if data.has("saves"):
		var saves_data: Variant = data["saves"]
		if not saves_data is Array or saves_data.size() != 8:
			return null
		for index: int in 8:
			var save := _integer(saves_data[index])
			if save == -100_000 or not result.set_save_value(index, save):
				return null
	result.conditions = loaded_conditions
	return result


static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -100_000

class_name PartyState
extends RefCounted

var map_id: String
var coordinate: Vector2i
var _characters: Array[CharacterState]
var pooled_wealth: WealthState
var banked_wealth: WealthState
var fatigue: int = 4
var conditions: ConditionSet
var _allies: Array[MonsterState] = []
var _storage: Array[ItemInstance] = []
var _equipment_storage: Dictionary = {}
var _equipment_wealth: WealthState
var equipment_storage_active: bool = false


func _init(location_map_id: String, location: Vector2i, party_characters: Array[CharacterState]) -> void:
	map_id = location_map_id
	coordinate = location
	_characters = party_characters.duplicate()
	pooled_wealth = WealthState.new()
	banked_wealth = WealthState.new()
	_equipment_wealth = WealthState.new()
	conditions = ConditionSet.new(ConditionSet.PARTY_COUNT)


func characters() -> Array[CharacterState]:
	return _characters.duplicate()


func character_by_id(character_id: String) -> CharacterState:
	for character: CharacterState in _characters:
		if character.id == character_id:
			return character
	return null


func add_character(character: CharacterState) -> bool:
	if character == null or character.id.is_empty() or character_by_id(character.id) != null or not _items_are_unique_with(character.inventory()):
		return false
	_characters.append(character)
	return true


func owns_item_instance(item_instance_id: String) -> bool:
	if item_instance_id.is_empty():
		return false
	return item_instance_ids().has(item_instance_id)


func item_instance_ids() -> Array[String]:
	var result: Array[String] = []
	for character: CharacterState in _characters:
		for item: ItemInstance in character.inventory():
			result.append(item.id)
	for item: ItemInstance in _storage:
		result.append(item.id)
	for character_id: Variant in _equipment_storage:
		for item: ItemInstance in _equipment_storage[character_id]:
			result.append(item.id)
	return result


func has_unique_item_ownership() -> bool:
	return _items_are_unique_with([])


func remove_character(character_id: String) -> bool:
	for index: int in _characters.size():
		if _characters[index].id != character_id:
			continue
		_characters.remove_at(index)
		return true
	return false


func reorder_characters(character_ids: Array[String]) -> bool:
	if character_ids.size() != _characters.size():
		return false
	var by_id: Dictionary = {}
	for character: CharacterState in _characters:
		by_id[character.id] = character
	var seen: Dictionary = {}
	var reordered: Array[CharacterState] = []
	for character_id: String in character_ids:
		if character_id.is_empty() or seen.has(character_id) or not by_id.has(character_id):
			return false
		seen[character_id] = true
		reordered.append(by_id[character_id])
	_characters = reordered
	return true


func allies() -> Array[MonsterState]:
	return _allies.duplicate()


func set_allies(party_allies: Array[MonsterState]) -> void:
	_allies = party_allies.duplicate()


func add_ally(ally: MonsterState) -> bool:
	if ally == null:
		return false
	for current: MonsterState in _allies:
		if current.id == ally.id:
			return false
	_allies.append(ally)
	return true


func remove_allies_by_definition(definition_id: String, maximum: int = 0) -> int:
	var removed := 0
	for index: int in range(_allies.size() - 1, -1, -1):
		if _allies[index].definition_id != definition_id:
			continue
		_allies.remove_at(index)
		removed += 1
		if maximum > 0 and removed >= maximum:
			break
	return removed


func storage() -> Array[ItemInstance]:
	return _storage.duplicate()


func set_storage(items: Array[ItemInstance]) -> void:
	_storage = items.duplicate()


func add_storage_item(item: ItemInstance) -> bool:
	if item == null:
		return false
	_storage.append(item)
	return true


func capture_equipment() -> bool:
	if equipment_storage_active:
		return false
	_equipment_storage.clear()
	for character: CharacterState in _characters:
		_equipment_storage[character.id] = character.inventory()
		character.set_inventory([])
	_equipment_wealth = WealthState.new(pooled_wealth.gold, pooled_wealth.gems, pooled_wealth.jewelry)
	pooled_wealth = WealthState.new()
	equipment_storage_active = true
	return true


func restore_equipment() -> bool:
	if not equipment_storage_active:
		return false
	for character: CharacterState in _characters:
		var current_items := character.inventory()
		_storage.append_array(current_items)
		var stored: Array[ItemInstance] = []
		for value: Variant in _equipment_storage.get(character.id, []):

			if value is ItemInstance:
				stored.append(value)
		character.set_inventory(stored)
	pooled_wealth.gold += _equipment_wealth.gold
	pooled_wealth.gems += _equipment_wealth.gems
	pooled_wealth.jewelry += _equipment_wealth.jewelry
	_equipment_storage.clear()
	_equipment_wealth = WealthState.new()
	equipment_storage_active = false
	return true


func to_data() -> Dictionary:
	var character_data: Array[Dictionary] = []
	for character: CharacterState in _characters:
		character_data.append(character.to_data())
	var ally_data: Array[Dictionary] = []
	for ally: MonsterState in _allies:
		ally_data.append(ally.to_data())
	var storage_data: Array[Dictionary] = []
	for item: ItemInstance in _storage:
		storage_data.append(item.to_data())
	var equipment_data: Dictionary = {}
	var equipment_character_ids: Array = _equipment_storage.keys()
	equipment_character_ids.sort()
	for character_id: Variant in equipment_character_ids:
		var item_data: Array[Dictionary] = []
		for item: ItemInstance in _equipment_storage[character_id]:
			item_data.append(item.to_data())
		equipment_data[character_id] = item_data
	return {"mapId": map_id, "x": coordinate.x, "y": coordinate.y, "characters": character_data, "pooledWealth": pooled_wealth.to_data(), "bankedWealth": banked_wealth.to_data(), "fatigue": fatigue, "conditions": conditions.to_data(), "allies": ally_data, "storage": storage_data, "equipmentStorageActive": equipment_storage_active, "equipmentStorage": equipment_data, "equipmentWealth": _equipment_wealth.to_data()}


static func from_data(data: Variant) -> PartyState:
	if not data is Dictionary:
		return null
	for field: String in ["mapId", "x", "y", "characters"]:
		if not data.has(field):
			return null
	if not data["mapId"] is String or data["mapId"].is_empty():
		return null
	var x := _integer(data["x"])
	var y := _integer(data["y"])
	if x < 0 or y < 0 or not data["characters"] is Array:
		return null
	var loaded_characters: Array[CharacterState] = []
	for character_data: Variant in data["characters"]:
		var character := CharacterState.from_data(character_data)
		if character == null:
			return null
		loaded_characters.append(character)
	var result := PartyState.new(data["mapId"], Vector2i(x, y), loaded_characters)
	if not data.has("pooledWealth"):
		return result if result.has_unique_item_ownership() else null
	for field: String in ["pooledWealth", "fatigue", "conditions", "allies", "storage"]:
		if not data.has(field):
			return null
	var wealth := WealthState.from_data(data["pooledWealth"])
	var banked := WealthState.from_data(data.get("bankedWealth", {"gold": 0, "gems": 0, "jewelry": 0}))
	var party_conditions := ConditionSet.from_data(data["conditions"], ConditionSet.PARTY_COUNT)
	var loaded_fatigue := _integer(data["fatigue"])
	if wealth == null or banked == null or party_conditions == null or loaded_fatigue < 4 or loaded_fatigue > 135 or not data["allies"] is Array or not data["storage"] is Array:
		return null
	var loaded_allies: Array[MonsterState] = []
	for ally_data: Variant in data["allies"]:
		var ally := MonsterState.from_data(ally_data)
		if ally == null:
			return null
		loaded_allies.append(ally)
	var stored_items: Array[ItemInstance] = []
	for item_data: Variant in data["storage"]:
		var item := ItemInstance.from_data(item_data)
		if item == null:
			return null
		stored_items.append(item)
	result.pooled_wealth = wealth
	result.banked_wealth = banked
	result.fatigue = loaded_fatigue
	result.conditions = party_conditions
	result._allies = loaded_allies
	result._storage = stored_items
	if data.has("equipmentStorageActive"):
		if not data["equipmentStorageActive"] is bool or not data.get("equipmentStorage") is Dictionary:
			return null
		var equipment_wealth := WealthState.from_data(data.get("equipmentWealth"))
		if equipment_wealth == null:
			return null
		var equipment_storage: Dictionary = {}
		for character_id: Variant in data["equipmentStorage"]:
			if not character_id is String or result.character_by_id(character_id) == null or not data["equipmentStorage"][character_id] is Array:
				return null
			var equipment_items: Array[ItemInstance] = []
			for item_data: Variant in data["equipmentStorage"][character_id]:
				var item := ItemInstance.from_data(item_data)
				if item == null:
					return null
				equipment_items.append(item)
			equipment_storage[character_id] = equipment_items
		result.equipment_storage_active = data["equipmentStorageActive"]
		result._equipment_storage = equipment_storage
		result._equipment_wealth = equipment_wealth
	return result if result.has_unique_item_ownership() else null


func _items_are_unique_with(additional_items: Array[ItemInstance]) -> bool:
	var seen: Dictionary = {}
	for item_id: String in item_instance_ids():
		if item_id.is_empty() or seen.has(item_id):
			return false
		seen[item_id] = true
	for item: ItemInstance in additional_items:
		if item == null or item.id.is_empty() or seen.has(item.id):
			return false
		seen[item.id] = true
	return true


static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1

class_name PendingMonsterAttack
extends RefCounted

var actor_id: String
var target_id: String
var action: StringName
var damage: int
var chance: int
var roll: int
var weapon_condition_index: int = -1
var weapon_condition_before: int = 0
var weapon_condition_after: int = 0
var physical_feedback_sound_id: int = 0


func _init(source_actor_id: String, source_target_id: String, source_action: StringName, pending_damage: int, hit_chance: int, hit_roll: int, condition_index: int = -1, condition_before: int = 0, condition_after: int = 0, feedback_sound_id: int = 0) -> void:
	actor_id = source_actor_id
	target_id = source_target_id
	action = source_action
	damage = pending_damage
	chance = hit_chance
	roll = hit_roll
	weapon_condition_index = condition_index
	weapon_condition_before = condition_before
	weapon_condition_after = condition_after
	physical_feedback_sound_id = feedback_sound_id


func to_data() -> Dictionary:
	var data := {
		"actorId": actor_id,
		"targetId": target_id,
		"action": String(action),
		"damage": damage,
		"chance": chance,
		"roll": roll,
	}
	if weapon_condition_index >= 0:
		data["weaponConditionIndex"] = weapon_condition_index
		data["weaponConditionBefore"] = weapon_condition_before
		data["weaponConditionAfter"] = weapon_condition_after
	if physical_feedback_sound_id > 0:
		data["physicalFeedbackSoundId"] = physical_feedback_sound_id
	return data


static func from_data(data: Variant) -> PendingMonsterAttack:
	if not data is Dictionary or data.size() not in [6, 7, 9, 10]:
		return null
	for field: String in ["actorId", "targetId", "action", "damage", "chance", "roll"]:
		if not data.has(field):
			return null
	if not data["actorId"] is String or data["actorId"].is_empty() or not data["targetId"] is String or data["targetId"].is_empty() or not data["action"] is String or data["action"].is_empty():
		return null
	var pending_damage := _integer(data["damage"])
	var hit_chance := _integer(data["chance"])
	var hit_roll := _integer(data["roll"])
	if data["action"] not in ["advance", "missile", "guard", "withdrawal"] or pending_damage < 0 or hit_roll < 1 or hit_roll > 100 or hit_chance == -100_000:
		return null
	var condition_index := _integer(data.get("weaponConditionIndex", -1))
	var condition_before := _integer(data.get("weaponConditionBefore", 0))
	var condition_after := _integer(data.get("weaponConditionAfter", 0))
	var has_condition_fields: bool = data.has("weaponConditionIndex") and data.has("weaponConditionBefore") and data.has("weaponConditionAfter")
	var feedback_sound_id := _integer(data.get("physicalFeedbackSoundId", 0))
	var has_feedback_sound: bool = data.has("physicalFeedbackSoundId")
	var expected_size := 6 + (3 if has_condition_fields else 0) + (1 if has_feedback_sound else 0)
	if data.size() != expected_size or has_condition_fields != (condition_index >= 0) or condition_index < -1 or condition_index >= ConditionSet.CHARACTER_COUNT or condition_before == -100_000 or condition_after == -100_000 or feedback_sound_id < 0:
		return null
	return PendingMonsterAttack.new(data["actorId"], data["targetId"], StringName(data["action"]), pending_damage, hit_chance, hit_roll, condition_index, condition_before, condition_after, feedback_sound_id)


static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -100_000

class_name RandomRegionState
extends RefCounted

var id: String
var chance_ten_thousand: int
var battle_minimum: int
var battle_maximum: int
var _random_door_percents: Array[int]


func _init(region_id: String, chance: int, battle_min: int, battle_max: int, door_percents: Array[int] = []) -> void:
	id = region_id
	chance_ten_thousand = chance
	battle_minimum = battle_min
	battle_maximum = battle_max
	_random_door_percents = door_percents.duplicate()


func random_door_percents() -> Array[int]:
	return _random_door_percents.duplicate()


func consume_random_door(index: int) -> void:
	if index >= 0 and index < _random_door_percents.size() and _random_door_percents[index] > 0:
		_random_door_percents[index] = 0


func to_data() -> Dictionary:
	return {"id": id, "chanceTenThousand": chance_ten_thousand, "battleMinimum": battle_minimum, "battleMaximum": battle_maximum, "randomDoorPercent": _random_door_percents.duplicate()}


static func from_data(data: Variant) -> RandomRegionState:
	if not data is Dictionary:
		return null
	for field: String in ["id", "chanceTenThousand", "battleMinimum", "battleMaximum", "randomDoorPercent"]:
		if not data.has(field):
			return null
	if not data["id"] is String or data["id"].is_empty():
		return null
	var chance := _signed_integer(data["chanceTenThousand"])
	var battle_min := _signed_integer(data["battleMinimum"])
	var battle_max := _signed_integer(data["battleMaximum"])
	if chance == -100_000 or battle_min == -100_000 or battle_max == -100_000 or not data["randomDoorPercent"] is Array or data["randomDoorPercent"].size() != 3:
		return null
	var door_percents: Array[int] = []
	for value: Variant in data["randomDoorPercent"]:
		var percent := _signed_integer(value)
		if percent == -100_000:
			return null
		door_percents.append(percent)
	return RandomRegionState.new(data["id"], chance, battle_min, battle_max, door_percents)


static func _signed_integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -100_000

class_name SpellScrollState
extends RefCounted

var spell_id: String
var power: int


func _init(scroll_spell_id: String = "", power_level: int = 0) -> void:
	spell_id = scroll_spell_id
	power = power_level


func is_empty() -> bool:
	return spell_id.is_empty() and power == 0


func to_data() -> Dictionary:
	return {"spellId": spell_id, "power": power}


static func from_data(data: Variant) -> SpellScrollState:
	if not data is Dictionary or data.size() != 2 or not data.get("spellId") is String:
		return null
	var parsed_power := _integer(data.get("power"))
	var parsed_spell_id: String = data["spellId"]
	if parsed_power < 0 or parsed_power > 7:
		return null
	if parsed_power == 0 and not parsed_spell_id.is_empty() or parsed_power > 0 and parsed_spell_id.is_empty():
		return null
	return SpellScrollState.new(parsed_spell_id, parsed_power)


static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1

class_name WorldState
extends RefCounted

var _terrain_overrides: Dictionary = {}
var _boat_presence_overrides: Dictionary = {}
var _door_states: Dictionary = {}
var _discovered_secrets: Dictionary = {}
var _disabled_triggers: Dictionary = {}
var _visited_cells: Dictionary = {}
var _trigger_chances: Dictionary = {}
var _acquired_maps: Dictionary = {}
var _random_regions: Dictionary = {}
var _map_darkness: Dictionary = {}
var _location_notes: Dictionary = {}


func terrain_for(map_id: String, cell: MapCell) -> String:
	return String(_terrain_overrides.get(_cell_key(map_id, cell.coordinate), cell.terrain_id))


func replace_terrain(map_id: String, coordinate: Vector2i, terrain_id: String) -> void:
	_terrain_overrides[_cell_key(map_id, coordinate)] = terrain_id


func set_boat_present(map_id: String, coordinate: Vector2i, present: bool) -> void:
	_boat_presence_overrides[_cell_key(map_id, coordinate)] = present


func boat_presence_state(map_id: String, coordinate: Vector2i) -> int:
	var key := _cell_key(map_id, coordinate)
	if not _boat_presence_overrides.has(key):
		return -1
	return 1 if bool(_boat_presence_overrides[key]) else 0


func boat_presence_overrides() -> Dictionary:
	return _boat_presence_overrides.duplicate()


func open_door(door_id: String) -> void:
	if not door_id.is_empty():
		_door_states[door_id] = "open"


func door_is_open(door_id: String, initially_open: bool = false) -> bool:
	if door_id.is_empty():
		return true
	return _door_states.get(door_id, "open" if initially_open else "closed") == "open"


func discover_secret(secret_id: String) -> void:
	if not secret_id.is_empty():
		_discovered_secrets[secret_id] = true


func secret_is_discovered(secret_id: String, initially_discovered: bool = false) -> bool:
	return secret_id.is_empty() or initially_discovered or _discovered_secrets.has(secret_id)


func disable_trigger(trigger_id: String) -> void:
	_disabled_triggers[trigger_id] = true


func trigger_is_disabled(trigger_id: String) -> bool:
	return _disabled_triggers.has(trigger_id)


func set_trigger_chance(trigger_id: String, percent: int) -> void:
	if trigger_id.is_empty():
		return
	_trigger_chances[trigger_id] = clampi(percent, -1, 100)
	if percent < 0:
		disable_trigger(trigger_id)


func trigger_chance(trigger_id: String, authored_percent: int) -> int:
	return int(_trigger_chances.get(trigger_id, authored_percent))


func acquire_map(map_id: String) -> void:
	if not map_id.is_empty():
		_acquired_maps[map_id] = true


func has_map(map_id: String) -> bool:
	return _acquired_maps.has(map_id)


func acquired_map_ids() -> Array[String]:
	var result: Array[String] = []
	for map_id: Variant in _acquired_maps.keys():
		if map_id is String:
			result.append(map_id)
	result.sort()
	return result


func upsert_location_note(note: LocationNoteState) -> bool:
	if note == null or not note.is_structurally_valid():
		return false
	for current: LocationNoteState in location_notes_for_kind(note.map_kind):
		if current.record_ordinal == note.record_ordinal and current.id() != note.id():
			return false
	_location_notes[note.id()] = note
	return true


func remove_location_note(map_id: String, coordinate: Vector2i) -> bool:
	return _location_notes.erase(LocationNoteState.key_for(map_id, coordinate))


func location_note_at(map_id: String, coordinate: Vector2i) -> LocationNoteState:
	return _location_notes.get(LocationNoteState.key_for(map_id, coordinate)) as LocationNoteState


func location_notes() -> Array[LocationNoteState]:
	var result: Array[LocationNoteState] = []
	for value: Variant in _location_notes.values():
		result.append(value as LocationNoteState)
	result.sort_custom(func(left: LocationNoteState, right: LocationNoteState) -> bool:
		return String(left.map_kind) < String(right.map_kind) or left.map_kind == right.map_kind and left.record_ordinal < right.record_ordinal
	)
	return result


func location_notes_for_kind(map_kind: StringName) -> Array[LocationNoteState]:
	var result: Array[LocationNoteState] = []
	for note: LocationNoteState in location_notes():
		if note.map_kind == map_kind:
			result.append(note)
	return result


func next_location_note_ordinal(map_kind: StringName) -> int:
	var used: Dictionary = {}
	for note: LocationNoteState in location_notes_for_kind(map_kind):
		used[note.record_ordinal] = true
	for ordinal: int in LocationNoteState.MAX_NOTES_PER_MAP_KIND:
		if not used.has(ordinal):
			return ordinal
	return -1


func set_random_region(region: RandomRegionState) -> void:
	if region != null and not region.id.is_empty():
		_random_regions[region.id] = region


func random_region(region: RandomEncounterRegion) -> RandomRegionState:
	if _random_regions.has(region.id):
		return _random_regions[region.id] as RandomRegionState
	return RandomRegionState.new(region.id, region.chance_ten_thousand, region.battle_minimum, region.battle_maximum, region.random_door_percents())


func set_map_darkness(map_id: String, dark: bool) -> void:
	if not map_id.is_empty():
		_map_darkness[map_id] = dark


func map_is_dark(map: MapDefinition) -> bool:

	return false if map == null else bool(_map_darkness.get(map.id, map.dark))


func mark_visited(map_id: String, coordinate: Vector2i) -> void:
	_visited_cells[_cell_key(map_id, coordinate)] = true


func was_visited(map_id: String, coordinate: Vector2i) -> bool:
	return _visited_cells.has(_cell_key(map_id, coordinate))


func visited_coordinates(map_id: String) -> Array[Vector2i]:
	var result: Array[Vector2i] = []
	var prefix := "%s:" % map_id
	for key_value: Variant in _visited_cells.keys():
		var key := String(key_value)
		if not key.begins_with(prefix):
			continue
		var components := key.trim_prefix(prefix).split(",", false, 1)
		if components.size() != 2 or not components[0].is_valid_int() or not components[1].is_valid_int():
			continue
		result.append(Vector2i(int(components[0]), int(components[1])))
	result.sort_custom(func(left: Vector2i, right: Vector2i) -> bool: return left.y < right.y or left.y == right.y and left.x < right.x)
	return result


func to_data() -> Dictionary:
	var random_regions: Array[Dictionary] = []
	var random_region_ids: Array = _random_regions.keys()
	random_region_ids.sort()
	for region_id: Variant in random_region_ids:
		random_regions.append((_random_regions[region_id] as RandomRegionState).to_data())
	var location_notes_data: Array[Dictionary] = []
	for note: LocationNoteState in location_notes():
		location_notes_data.append(note.to_data())
	return {
		"terrainOverrides": _sorted_dictionary(_terrain_overrides),
		"boatPresenceOverrides": _sorted_dictionary(_boat_presence_overrides),
		"doorStates": _sorted_dictionary(_door_states),
		"discoveredSecrets": _sorted_keys(_discovered_secrets),
		"disabledTriggers": _sorted_keys(_disabled_triggers),
		"visitedCells": _sorted_keys(_visited_cells),
		"triggerChances": _sorted_dictionary(_trigger_chances),
		"acquiredMaps": _sorted_keys(_acquired_maps),
		"randomRegions": random_regions,
		"mapDarkness": _sorted_dictionary(_map_darkness),
		"locationNotes": location_notes_data,
	}


static func from_data(data: Variant) -> WorldState:
	if not data is Dictionary:
		return null
	for field: String in ["terrainOverrides", "doorStates", "discoveredSecrets", "disabledTriggers", "visitedCells"]:
		if not data.has(field):
			return null
	if not data["terrainOverrides"] is Dictionary or not data["doorStates"] is Dictionary:
		return null
	var state := WorldState.new()
	for key: Variant in data["terrainOverrides"]:
		if not key is String or not data["terrainOverrides"][key] is String:
			return null
		state._terrain_overrides[key] = data["terrainOverrides"][key]
	if data.has("boatPresenceOverrides"):
		if not data["boatPresenceOverrides"] is Dictionary:
			return null
		for key: Variant in data["boatPresenceOverrides"]:
			if not key is String or key.is_empty() or not data["boatPresenceOverrides"][key] is bool:
				return null
			state._boat_presence_overrides[key] = data["boatPresenceOverrides"][key]
	for key: Variant in data["doorStates"]:
		if not key is String or data["doorStates"][key] not in ["open", "closed"]:
			return null
		state._door_states[key] = data["doorStates"][key]
	if not _load_key_array(data["discoveredSecrets"], state._discovered_secrets) or not _load_key_array(data["disabledTriggers"], state._disabled_triggers) or not _load_key_array(data["visitedCells"], state._visited_cells):
		return null
	if data.has("triggerChances"):
		if not data["triggerChances"] is Dictionary:
			return null
		for key: Variant in data["triggerChances"]:
			var percent := _integer(data["triggerChances"][key])
			if not key is String or key.is_empty() or percent < -1 or percent > 100:
				return null
			state._trigger_chances[key] = percent
	if data.has("acquiredMaps") and not _load_key_array(data["acquiredMaps"], state._acquired_maps):
		return null
	if data.has("randomRegions"):
		if not data["randomRegions"] is Array:
			return null
		for entry: Variant in data["randomRegions"]:
			var region := RandomRegionState.from_data(entry)
			if region == null or state._random_regions.has(region.id):
				return null
			state._random_regions[region.id] = region
	if data.has("mapDarkness"):
		if not data["mapDarkness"] is Dictionary:
			return null
		for key: Variant in data["mapDarkness"]:
			if not key is String or key.is_empty() or not data["mapDarkness"][key] is bool:
				return null
			state._map_darkness[key] = data["mapDarkness"][key]
	if data.has("locationNotes"):
		if not data["locationNotes"] is Array:
			return null
		for entry: Variant in data["locationNotes"]:
			var note := LocationNoteState.from_data(entry)
			if note == null or state._location_notes.has(note.id()):
				return null
			state._location_notes[note.id()] = note
	return state


static func _load_key_array(value: Variant, target: Dictionary) -> bool:
	if not value is Array:
		return false
	for key: Variant in value:
		if not key is String or key.is_empty() or target.has(key):
			return false
		target[key] = true
	return true


static func _sorted_dictionary(source: Dictionary) -> Dictionary:
	var result: Dictionary = {}
	var keys: Array = source.keys()
	keys.sort()
	for key: Variant in keys:
		result[key] = source[key]
	return result


static func _sorted_keys(source: Dictionary) -> Array[String]:
	var keys: Array[String] = []
	for key: Variant in source.keys():
		keys.append(String(key))
	keys.sort()
	return keys


static func _cell_key(map_id: String, coordinate: Vector2i) -> String:
	return "%s:%d,%d" % [map_id, coordinate.x, coordinate.y]


static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -100_000

class_name RealmzClock
extends RefCounted

const MINUTES_PER_DAY: int = 1_440

var _total_minutes: int = 0


func _init(initial_total_minutes: int = 0) -> void:
	_total_minutes = maxi(initial_total_minutes, 0)


func advance_minutes(minutes: int) -> bool:
	if minutes < 0:
		return false
	_total_minutes += minutes
	return true


func set_total_minutes(minutes: int) -> bool:
	if minutes < 0:
		return false
	_total_minutes = minutes
	return true


func total_minutes() -> int:
	return _total_minutes


func day() -> int:
	return 1 + floori(float(_total_minutes) / float(MINUTES_PER_DAY))


func hour() -> int:
	return floori(float(_total_minutes % MINUTES_PER_DAY) / 60.0)


func minute() -> int:
	return _total_minutes % 60


func to_data() -> Dictionary:
	return {"totalMinutes": _total_minutes}


static func from_data(data: Variant) -> RealmzClock:
	if not data is Dictionary or not data.has("totalMinutes"):
		return null
	var minutes: int = data["totalMinutes"] if data["totalMinutes"] is int else int(data["totalMinutes"]) if data["totalMinutes"] is float and is_equal_approx(data["totalMinutes"], round(data["totalMinutes"])) else -1
	if minutes < 0:
		return null
	return RealmzClock.new(minutes)

class_name BattlefieldView
extends RefCounted

var map_id: String
var upper_tileset_id: String
var source_origin: Vector2i
var map_shift: Vector2i
var party_anchor: Vector2i
var direction_degrees: int
var rolled_distance: int
var _terrain_tiles: Array[int]
var _character_positions: Dictionary
var _monster_positions: Dictionary
var _monster_sizes: Dictionary


func _init(battlefield: BattlefieldState, terrain_upper_tileset_id: String = "") -> void:
	map_id = battlefield.map_id
	upper_tileset_id = terrain_upper_tileset_id
	source_origin = battlefield.source_origin
	map_shift = battlefield.map_shift
	party_anchor = battlefield.party_anchor
	direction_degrees = battlefield.direction_degrees
	rolled_distance = battlefield.rolled_distance
	_terrain_tiles = battlefield.terrain_tiles()
	_character_positions = battlefield.character_positions()
	_monster_positions = battlefield.monster_positions()
	for actor_id: Variant in _monster_positions:
		_monster_sizes[actor_id] = battlefield.monster_size(String(actor_id))


func terrain_tiles() -> Array[int]:
	return _terrain_tiles.duplicate()


func terrain_at(coordinate: Vector2i) -> int:
	return -1 if not BattlefieldState.contains(coordinate) else _terrain_tiles[coordinate.y * BattlefieldState.SIZE + coordinate.x]


func character_position(actor_id: String) -> Vector2i:
	return _character_positions.get(actor_id, Vector2i(-1, -1)) as Vector2i


func monster_position(actor_id: String) -> Vector2i:
	return _monster_positions.get(actor_id, Vector2i(-1, -1)) as Vector2i


func monster_size(actor_id: String) -> int:
	return int(_monster_sizes.get(actor_id, -1))


func monster_footprint(actor_id: String) -> Array[Vector2i]:
	var anchor := monster_position(actor_id)
	var size := monster_size(actor_id)
	var footprint: Array[Vector2i] = []
	if anchor.x < 0 or size < 0:
		return footprint
	return BattlefieldState.footprint_cells(anchor, size)

class_name WealthState
extends RefCounted

enum Kind {
	GOLD,
	GEMS,
	JEWELRY,
}

var gold: int = 0
var gems: int = 0
var jewelry: int = 0


func _init(gold_amount: int = 0, gem_amount: int = 0, jewelry_amount: int = 0) -> void:
	gold = maxi(0, gold_amount)
	gems = maxi(0, gem_amount)
	jewelry = maxi(0, jewelry_amount)


func amount(kind: Kind) -> int:
	match kind:
		Kind.GOLD:
			return gold
		Kind.GEMS:
			return gems
		Kind.JEWELRY:
			return jewelry
	return 0


func set_amount(kind: Kind, value: int) -> void:
	match kind:
		Kind.GOLD:
			gold = maxi(0, value)
		Kind.GEMS:
			gems = maxi(0, value)
		Kind.JEWELRY:
			jewelry = maxi(0, value)


func add(kind: Kind, value: int) -> void:
	set_amount(kind, amount(kind) + value)


func to_data() -> Dictionary:
	return {"gold": gold, "gems": gems, "jewelry": jewelry}


static func from_data(data: Variant) -> WealthState:
	if not data is Dictionary:
		return null
	var amounts: Array[int] = []
	for field: String in ["gold", "gems", "jewelry"]:
		if not data.has(field):
			return null
		var value := _integer(data[field])
		if value < 0:
			return null
		amounts.append(value)
	return WealthState.new(amounts[0], amounts[1], amounts[2])


static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1

class_name MapCellView
extends RefCounted

var coordinate: Vector2i
var terrain_id: String
var render_tile: int
var tileset_id: String
var overlay_asset_id: String
var passable: bool
var blocks_los: bool
var visible: bool
var visited: bool
var has_trigger: bool
var in_random_region: bool
var _feature_kinds: Array[StringName]
var _feature_orientations: Dictionary = {}
var _edge_kinds: Dictionary = {}
var _edge_passability: Dictionary = {}


func _init(cell_coordinate: Vector2i, terrain: String, tile: int, cell_tileset_id: String, can_enter: bool, blocks_visibility: bool, is_visible: bool, was_visited: bool, trigger_present: bool, random_region_present: bool, feature_kinds: Array[StringName], feature_orientations: Dictionary, edge_kinds: Dictionary, edge_passability: Dictionary, cell_overlay_asset_id: String = "") -> void:
	coordinate = cell_coordinate
	terrain_id = terrain
	render_tile = tile
