func _finish_with_age_updates(events: Array[DomainEvent], resume_kind: StringName, resume_continuation: SessionContinuation = null) -> SessionCoordinatorResult:
	var updates = CharacterAgingResult.update_bodies(events)
	if updates.is_empty():
		if resume_kind == &"post-move":
			_context.set_continuation(resume_continuation.copy())
			return _context.exploration()._continue_post_move(events)
		if resume_kind == &"post-clock":
			_context.set_continuation(resume_continuation.copy())
			return _context.exploration()._continue_post_time(events)
		if resume_kind == &"combat-monster-turns":
			return _continue_after_session_combat_age_update(events)
		return _context.completed(events)
	var age = SessionContinuation.AgeBody.new()
	for update: InteractionRequest.AgeUpdateBody in updates:
		age.updates.append(InteractionRequest.age_update_body("session.age-copy", update).body as InteractionRequest.AgeUpdateBody)
	age.index = 1
	age.resume_kind = resume_kind
	age.resume_continuation = null if resume_continuation == null else resume_continuation.copy()
	_context.set_continuation(SessionContinuation.age_updates(age))
	_context.session_interaction = InteractionRequest.age_update_body(_session_age_update_request_id(updates[0], 0), updates[0])
	events.append(CharacterAgingResult.sound_event_for_update(updates[0]))
	return _context.waiting(_context.session_interaction, events)


func _respond_session_age_update(response: InteractionResponse) -> SessionCoordinatorResult:
	if response.kind != InteractionRequest.AGE_UPDATE or response.body is not InteractionResponse.EmptyBody:
		return _context.failed(&"invalid_interaction_response", "Classic age updates require an empty age-update acknowledgement.")
	var age = _context.session_continuation.age()
	if age == null:
		return _context.failed(&"invalid_session_continuation", "The age-update queue is unavailable.")
	var updates = age.updates
	var index = age.index
	if updates.is_empty() or index < 1 or index > updates.size():
		return _context.failed(&"invalid_session_continuation", "The age-update queue is unavailable.")
	var acknowledged: InteractionRequest.AgeUpdateBody = updates[index - 1]
	var events: Array[DomainEvent] = [DomainEvent.new(&"character_age_update_acknowledged", {"characterId": acknowledged.character_id})]
	if index < updates.size():
		var next_payload: InteractionRequest.AgeUpdateBody = updates[index]
		age.index = index + 1
		_context.session_interaction = InteractionRequest.age_update_body(_session_age_update_request_id(next_payload, index), next_payload)
		events.append(CharacterAgingResult.sound_event_for_update(next_payload))
		return _context.waiting(_context.session_interaction, events)
	var resume_kind = age.resume_kind
	var resume_continuation = age.resume_continuation
	_context.session_interaction = null
	_context.session_continuation.clear()
	if resume_kind == &"post-move":
		_context.set_continuation(resume_continuation.copy())
		return _context.exploration()._continue_post_move(events)
	if resume_kind == &"post-clock":
		_context.set_continuation(resume_continuation.copy())
		return _context.exploration()._continue_post_time(events)
	if resume_kind == &"combat-monster-turns":
		return _continue_after_session_combat_age_update(events)
	if resume_kind == &"completed":
		return _context.completed(events)
	return _context.failed(&"invalid_session_continuation", "The age-update queue has no valid completion path.", events)


func _continue_after_session_combat_age_update(events: Array[DomainEvent]) -> SessionCoordinatorResult:
	var continued = _context.rules.combat_flow.continue_after_age_update(_context.state, _context.content, _context.rng)
	if not continued.ok:
		return _context.failed(continued.error_code, continued.error_message, events)
	events.append_array(continued.events)
	if not CharacterAgingResult.update_payloads(continued.events).is_empty():
		return _finish_with_age_updates(events, "combat-monster-turns")
	if not _context.event_payload(continued.events, &"monster_death_macro_requested").is_empty():
		return _context.scenario()._start_session_death_macro(events)
	if continued.completed:
		return _context.scenario()._finish_direct_battle(events)
	return _context.completed(events)


func _session_age_update_request_id(update: InteractionRequest.AgeUpdateBody, index: int) -> String:
	return "session.age-update:%s:%d:%d" % [update.character_id, _context.next_revision(), index]


func _respond_session_ally_selection(response: InteractionResponse) -> SessionCoordinatorResult:
	var body = response.body as InteractionResponse.AllySelectionBody
	if response.kind != &"ally_selection" or body == null:
		return _context.failed(&"invalid_interaction_response", "Ally selection requires selectedIds.")
	var continuation = _context.session_continuation.combat()
	if continuation == null or _context.state.combat == null or not _context.state.combat.completed or _context.state.combat.battle_id != continuation.battle_id:
		return _context.failed(&"invalid_session_continuation", "The completed battle is unavailable for ally selection.")
	# Development saves from before the Castle body-count correction can retain an
	# impossible empty selection boundary. Re-evaluate the source-backed candidate
	# set and advance it exactly as a fresh terminal battle now does.
	if _context.rules.combat_flow.ally_selection_payload(_context.state, _context.content).is_empty():
		_context.session_interaction = null
		_context.session_continuation.clear()
		return _context.scenario()._finish_direct_battle_recovery(_no_events())
	var result = _context.rules.combat_flow.apply_ally_selection(_context.state, _context.content, body.selected_ids)
	if not result.ok:
		return _context.failed(result.error_code, result.error_message)
	_context.session_interaction = null
	_context.session_continuation.clear()
	var events: Array[DomainEvent] = []
	events.assign(result.events)
	return _context.scenario()._finish_direct_battle_recovery(events)


func _respond_session_fumble_recovery(response: InteractionResponse) -> SessionCoordinatorResult:
	var body = response.body as InteractionResponse.TreasureBody
	if response.kind != InteractionRequest.TREASURE_DISTRIBUTION or body == null:
		return _context.failed(&"invalid_interaction_response", "Fumbled-weapon recovery requires a treasure-distribution response.")
	var continuation = _context.session_continuation.combat()
	if continuation == null or _context.state.combat == null or not _context.state.combat.completed or _context.state.combat.battle_id != continuation.battle_id:
		return _context.failed(&"invalid_session_continuation", "The completed battle is unavailable for fumbled-weapon recovery.")
	var result = _context.rules.combat_flow.apply_fumble_recovery(_context.state, _context.content, body.action, body.instance_id, body.character_id)
	if not result.ok:
		return _context.failed(result.error_code, result.error_message)
	_context.session_interaction = null
	_context.session_continuation.clear()
	var events: Array[DomainEvent] = []
	events.assign(result.events)
	return _context.scenario()._finish_direct_battle_recovery(events)


func _respond_session_battle_reward(response: InteractionResponse) -> SessionCoordinatorResult:
	var continuation = _context.session_continuation.reward()
	if continuation == null or _context.state.combat == null or not _context.state.combat.completed or _context.state.combat.battle_id != continuation.battle_id:
		return _context.failed(&"invalid_session_continuation", "The completed battle is unavailable for reward distribution.")
	if continuation.runtime_continuation == null:
		return _context.failed(&"invalid_session_continuation", "The battle reward continuation is unavailable.")
	var return_continuation = _context.battle_return_continuation.copy()
	var battle_outcome = _context.state.combat.outcome
	var result = _context.runtime_api.resume_classic(continuation.runtime_continuation, response, response.request_id)

	if result.state == ScenarioRuntimeOperationResult.State.FAILED:
		return _context.failed(result.error_code, result.error_message, result.events)
	if result.state == ScenarioRuntimeOperationResult.State.WAITING:
		continuation.runtime_continuation = result.continuation.copy()
		_context.session_interaction = result.interaction
		return _context.waiting(_context.session_interaction, result.events)
	_context.session_interaction = null
	_context.session_continuation.clear()
	return _context.scenario()._finish_after_direct_battle(result.events, return_continuation, battle_outcome)


func _finish_magic_transition(result: InventoryMagicServicesWorkflow.MagicTransitionResult) -> SessionCoordinatorResult:
	if result == null:
		return _context.failed(&"invalid_workflow_result", "The magic workflow returned no result.")
	if not result.ok:
		return _context.failed(result.error_code, result.error_message)
	if result.completed:
		if result.process_age_updates:
			return _finish_magic_workflow(SessionWorkflowResult.completed(result.events))
		return _context.completed(result.events)
	if result.continuation == null or result.continuation.is_empty() or result.interaction == null:
		return _context.failed(&"invalid_workflow_result", "The magic workflow returned an incomplete interaction transition.")
	_context.set_continuation(result.continuation)
	_context.session_interaction = result.interaction
	return _context.waiting(_context.session_interaction, result.events)


func _finish_magic_workflow(result: SessionWorkflowResult) -> SessionCoordinatorResult:
	if result == null:
		return _context.failed(&"invalid_workflow_result", "The magic workflow returned no result.")
	if not result.ok:
		return _context.failed(result.error_code, result.error_message)
	if not CharacterAgingResult.update_payloads(result.events).is_empty():
		return _finish_with_age_updates(result.events, &"completed")
	return _context.completed(result.events)


func _commit_character_draft(events: Array[DomainEvent] = []) -> SessionCoordinatorResult:
	var result := LifecyclePartyWorkflow.commit_character_draft(_context.workflow_context())
	if not result.ok:
		return _context.failed(result.error_code, result.error_message, events)
	events.append_array(result.events)
	var request_id := "character-vault:%s:%d" % [result.character_id, _context.next_revision()]
	_context.set_continuation(SessionContinuation.character_vault_publication(result.character_id))
	_context.session_interaction = SessionInteractionFactory.character_vault_confirmation(request_id, result.character_name)
	events.append(DomainEvent.new(&"character_vault_confirmation_requested", {"characterId": result.character_id}))
	return _context.waiting(_context.session_interaction, events)


func _finish_combat_result(result: CombatFlowResult) -> SessionCoordinatorResult:
	if not result.ok:
		return _context.failed(result.error_code, result.error_message)
	if not CharacterAgingResult.update_payloads(result.events).is_empty():
		return _finish_with_age_updates(result.events, &"combat-monster-turns")
	if not _context.event_payload(result.events, &"monster_death_macro_requested").is_empty():
		return _context.scenario()._start_session_death_macro(result.events)
	if result.completed:
		return _context.scenario()._finish_direct_battle(result.events)
	return _context.completed(result.events)


func _open_contextual_service(service_id: String, preceding_events: Array[DomainEvent]) -> SessionCoordinatorResult:
	var request_id := "service:%s:%d" % [service_id, _context.current_revision()]
	var operation: ScenarioRuntimeOperationResult
	if service_id == "realmz.service.temple":
		operation = _context.runtime_api.request_available_temple(request_id)
	elif service_id == "realmz.service.bank":
		operation = _context.runtime_api.request_available_bank(request_id)
	elif service_id == _context.state.active_shop_id:
		operation = _context.runtime_api.request_available_shop(request_id)
	else:
		return _context.failed(&"service_unavailable", "The selected service is not available at this location.", preceding_events)
	operation.events = preceding_events + operation.events
	return _begin_runtime_service(service_id, operation)

class_name SessionScenarioCoordinator
extends RefCounted

var _context: SessionCoordinatorContext


func _init(context: SessionCoordinatorContext) -> void:
	_context = context

func _start_application_hook(hook: StringName, resume_kind: StringName, service_id: String, preceding_events: Array[DomainEvent], suspended: SessionContinuation.ApplicationBody = null) -> SessionCoordinatorResult:
	var continuation = ScenarioApplicationHookWorkflow.continuation(_context.content, hook, resume_kind, service_id, suspended)
	if continuation == null:
		return _context.failed(&"invalid_application_hook_resume", "The application hook has an unsupported resume path.", preceding_events)
	_context.session_continuation = continuation
	var body = _context.session_continuation.body as SessionContinuation.ApplicationBody
	var program_id = body.program_id
	if program_id.is_empty():
		return _continue_application_hook(preceding_events)
	var started = _context.scenario_vm.start_program(program_id, ScenarioApplicationHookWorkflow.start_context(hook, service_id))
	if started.state == ScenarioVmResult.State.FAILED:
		_context.session_continuation.clear()
		return _context.failed(started.error_code, started.error_message, preceding_events)
	var result = _context.scenario_vm.run(_context.runtime_api)
	var events: Array[DomainEvent] = []
	events.assign(preceding_events)
	events.append(DomainEvent.new(&"application_hook_started", {"hook": String(hook), "programId": program_id}))
	events.append_array(result.events)
	if _events_have(result.events, &"party_revived"):
		body.party_revived = true
	if result.state == ScenarioVmResult.State.SUSPENDED:
		return _context.failed(&"nested_party_defeat_handoff", "An application hook cannot suspend another total-party defeat.", events)
	if result.state == ScenarioVmResult.State.FAILED:
		_context.session_continuation.clear()
		return _context.failed(result.error_code, result.error_message, events)
	if result.state == ScenarioVmResult.State.WAITING:
		return _context.waiting(result.interaction, events)
	return _continue_application_hook(events)


func _continue_application_hook(events: Array[DomainEvent]) -> SessionCoordinatorResult:
	var body = _context.session_continuation.body as SessionContinuation.ApplicationBody
	if body == null:
		return _context.failed(&"invalid_session_continuation", "Application-hook continuation body is unavailable.", events)
	var hook = body.hook
	var program_id = body.program_id
	var resume_kind = String(body.resume_kind)
	var service_id = body.service_id
	var party_revived = body.party_revived
	var suspended_vm = ScenarioVmSnapshot.from_data(body.suspended_vm.to_data()) if body.suspended_vm != null else null
	var suspended_owner = body.suspended_owner
	var vm_handoff = body.vm_handoff.copy() if body.vm_handoff != null else null
	_context.session_continuation.clear()
	if not program_id.is_empty():
		events.append(ScenarioApplicationHookWorkflow.completion_event(body))
	match resume_kind:
		"begin-adventure":
			events.append(DomainEvent.new(&"adventure_begun", {"campaignId": _context.content.campaign_id}))
			return _context.completed(events)
		"service":
			return _context.responses()._open_contextual_service(service_id, events)
		"end-adventure":
			return _start_application_hook(ScenarioApplicationHooks.PARTY_DEATH, "end-adventure-close", "", events)
		"end-adventure-close":
			if party_revived:
				events.append(DomainEvent.new(&"adventure_end_suppressed", {"reason": "classic-party-death-revival"}))
				return _context.completed(events)
			return _context.closed(events, "end-adventure")
		"party-defeat":
			if not party_revived:
				return _context.closed(events, "party-defeat")
			if _context.state.combat == null or not _context.state.combat.completed or _context.state.combat.outcome != &"defeat":
				return _context.failed(&"invalid_battle_continuation", "Party Death revival lost its completed defeat.", events)
			_context.state.combat.outcome = &"retreated"
			_context.state.last_battle_outcome = &"retreated"
			events.append(DomainEvent.new(&"party_defeat_revived", {"battleId": _context.state.combat.battle_id, "source": "classic-party-death-hook"}))
			return _finish_direct_battle_without_rewards(events)
		"scenario-party-defeat":
			if not party_revived:
				return _context.closed(events, "party-defeat")
			return _resume_scenario_party_defeat(suspended_vm, suspended_owner, vm_handoff, events)
	return _context.failed(&"invalid_session_continuation", "Application hook '%s' has invalid resume kind '%s'." % [hook, resume_kind], events)


func _begin_scenario_handoff(result: ScenarioVmResult, events: Array[DomainEvent]) -> SessionCoordinatorResult:
	if result == null or result.state != ScenarioVmResult.State.SUSPENDED or result.handoff == null or result.handoff.runtime == null:
		_context.session_continuation.clear()
		return _context.failed(&"invalid_vm_handoff", "The Scenario VM did not provide a typed application handoff.", events)
	if _context.session_continuation.kind not in [&"post-clock", &"post-move"]:
		_context.session_continuation.clear()
		return _context.failed(&"unsupported_vm_handoff_owner", "Total-party defeat cannot suspend this scenario caller.", events)
	var saved = _context.scenario_vm.snapshot()
	if not ScenarioVm.handoff_is_valid(result.handoff, saved) or not RealmzRuntimeApi.party_defeat_handoff_is_valid(_context.content, _context.state, result.handoff.runtime):
		_context.session_continuation.clear()
		return _context.failed(&"invalid_party_defeat_handoff", "The Scenario VM total-party defeat handoff is invalid.", events)
	var suspended = SessionContinuation.ApplicationBody.new()
	suspended.suspended_vm = ScenarioVmSnapshot.from_data(saved.to_data())
	suspended.suspended_owner = _context.session_continuation.copy()
	suspended.vm_handoff = result.handoff.copy()
	_context.scenario_vm.reset()
	return _start_application_hook(ScenarioApplicationHooks.PARTY_DEATH, &"scenario-party-defeat", "", events, suspended)


func _resume_scenario_party_defeat(saved: ScenarioVmSnapshot, suspended_owner: SessionContinuation, vm_handoff: ScenarioVmHandoff, events: Array[DomainEvent]) -> SessionCoordinatorResult:
	if not ScenarioVm.handoff_is_valid(vm_handoff, saved) or not RealmzRuntimeApi.party_defeat_handoff_is_valid(_context.content, _context.state, vm_handoff.runtime) or not SessionRestoreValidator.suspended_scenario_owner_is_valid(_context.content, _context.state, suspended_owner, saved):
		return _context.failed(&"invalid_party_defeat_handoff", "The saved scenario defeat continuation is invalid.", events)
	var restored_vm = ScenarioVm.new()
	restored_vm.configure(_context.content.scenario)
	if not restored_vm.restore(saved):
		return _context.failed(&"invalid_vm_state", "The suspended scenario cannot be restored after Party Death.", events)
	var operation = _context.runtime_api.complete_party_defeat_handoff(vm_handoff.runtime)
	if operation.state == ScenarioRuntimeOperationResult.State.FAILED:
		return _context.failed(operation.error_code, operation.error_message, events)
	_context.scenario_vm = restored_vm
	var resumed = _context.scenario_vm.resume_handoff(vm_handoff, operation, _context.runtime_api)
	events.append_array(resumed.events)
	_context.set_continuation(suspended_owner.copy())
	if resumed.state == ScenarioVmResult.State.SUSPENDED:
		return _begin_scenario_handoff(resumed, events)
	if resumed.state == ScenarioVmResult.State.WAITING:
		return _context.waiting(resumed.interaction, events)
	if resumed.state == ScenarioVmResult.State.FAILED:
		_context.session_continuation.clear()
		return _context.failed(resumed.error_code, resumed.error_message, events)
	if _context.session_continuation.is_empty():
		return _context.completed(events)
	return _context.exploration()._continue_exploration_continuation(events)


func _apply_trigger_destination(trigger: TriggerDefinition, events: Array[DomainEvent], allow_destination: bool) -> bool:
	var destination = trigger.post_action_location
	var destination_is_source: bool = destination != null and destination.map_id == trigger.map_id and destination.coordinate == trigger.coordinate
	if not allow_destination or destination == null or destination_is_source or destination.map_id == _context.state.party.map_id and destination.coordinate == _context.state.party.coordinate:
		return false
	var source_map_id = _context.state.party.map_id
	var source_coordinate = _context.state.party.coordinate
	_context.state.party.map_id = destination.map_id
	_context.state.party.coordinate = destination.coordinate
	_context.state.world.mark_visited(destination.map_id, destination.coordinate)
	events.append(DomainEvent.new(&"party_moved", {"fromMapId": source_map_id, "fromX": source_coordinate.x, "fromY": source_coordinate.y, "mapId": destination.map_id, "x": destination.coordinate.x, "y": destination.coordinate.y, "source": "action-point-destination", "triggerId": trigger.id}))
	return true


func _finalize_completed_trigger(trigger: TriggerDefinition, events: Array[DomainEvent]) -> void:
	if _events_keep_trigger(events, trigger.id) or _context.state.world.trigger_is_disabled(trigger.id):
		return
	_context.state.world.disable_trigger(trigger.id)
	events.append(DomainEvent.new(&"trigger_disabled", {"triggerId": trigger.id, "source": "classic-default-one-shot"}))


static func _events_have(events: Array[DomainEvent], kind: StringName) -> bool:
	for event: DomainEvent in events:
		if event.kind == kind:
			return true
	return false


static func _events_keep_trigger(events: Array[DomainEvent], trigger_id: String) -> bool:
	for event: DomainEvent in events:
		if event.kind == &"action_point_kept" and String(event.payload.get("triggerId", "")) == trigger_id:
			return true

	return false


static func _event_payload(events: Array[DomainEvent], kind: StringName) -> Dictionary:
	for index: int in range(events.size() - 1, -1, -1):
		if events[index].kind == kind:
			return events[index].payload
	return {}


func _start_session_death_macro(preceding_events: Array[DomainEvent]) -> SessionCoordinatorResult:
	var request = _event_payload(preceding_events, &"monster_death_macro_requested")
	var combat = _context.state.combat
	if request.is_empty() or combat == null:
		return _context.failed(&"invalid_death_macro_request", "Monster death-macro execution requires an active combatant request.", preceding_events)
	var combatant_id = str(request.get("combatantId", ""))
	var program_id = str(request.get("programId", ""))
	var monster = combat.monster_by_id(combatant_id)
	if monster == null or _context.content.scenario.program_by_id(program_id) == null:
		return _context.failed(&"invalid_death_macro_request", "Monster death-macro execution references unavailable content.", preceding_events)
	var continuation_body = SessionContinuation.CombatBody.new()
	continuation_body.battle_id = combat.battle_id
	continuation_body.combatant_id = combatant_id
	continuation_body.program_id = program_id
	continuation_body.reset_traitor_on_complete = bool(request.get("resetTraitorOnComplete", true))
	_context.set_continuation(SessionContinuation.combat_state(&"combat-death-macro", continuation_body))
	var death_context = ScenarioExecutionContext.calling(&"monster-death-macro")
	death_context.set_battle(combat.battle_id)
	death_context.set_combatant(combatant_id, int(request.get("classicMonsterId", 0)), bool(request.get("traitor", monster.traitor)), true)
	var started = _context.scenario_vm.start_program(program_id, death_context)
	if started.state == ScenarioVmResult.State.FAILED:
		_context.session_continuation.clear()
		return _context.failed(started.error_code, started.error_message, preceding_events)
	var result = _context.scenario_vm.run(_context.runtime_api)
	var events: Array[DomainEvent] = []
	events.assign(preceding_events)
	events.append(DomainEvent.new(&"monster_death_macro_started", {"battleId": combat.battle_id, "combatantId": combatant_id, "programId": program_id}))
	events.append_array(result.events)
	if result.state == ScenarioVmResult.State.SUSPENDED:
		_context.session_continuation.clear()
		return _context.failed(&"unsupported_vm_handoff_owner", "A session-owned monster death macro cannot suspend a total-party defeat.", events)
	if result.state == ScenarioVmResult.State.FAILED:
		_context.session_continuation.clear()
		return _context.failed(result.error_code, result.error_message, events)
	if result.state == ScenarioVmResult.State.WAITING:
		return _context.waiting(result.interaction, events)
	return _continue_session_death_macro(events)


func _continue_session_death_macro(events: Array[DomainEvent]) -> SessionCoordinatorResult:
	var combat = _context.state.combat
	var continuation = _context.session_continuation.combat()
	if continuation == null:
		return _context.failed(&"invalid_battle_continuation", "Monster death-macro continuation is unavailable.", events)
	var battle_id = continuation.battle_id
	var combatant_id = continuation.combatant_id
	var program_id = continuation.program_id
	if combat == null or combat.battle_id != battle_id:
		_context.session_continuation.clear()
		return _context.failed(&"invalid_battle_continuation", "Monster death-macro completion lost its battle.", events)
	var monster = combat.monster_by_id(combatant_id)
	if monster != null and continuation.reset_traitor_on_complete:
		monster.traitor = false
	events.append(DomainEvent.new(&"monster_death_macro_completed", {"battleId": battle_id, "combatantId": combatant_id, "programId": program_id, "revived": monster != null and monster.current_health > 0}))
	_context.session_continuation.clear()
	var continued = _context.rules.combat_flow.continue_after_monster_death_macro(_context.state, _context.content, _context.rng, combatant_id)
	if not continued.ok:
		return _context.failed(continued.error_code, continued.error_message, events)
	events.append_array(continued.events)
	if not CharacterAgingResult.update_payloads(continued.events).is_empty():
		return _context.responses()._finish_with_age_updates(events, "combat-monster-turns")
	if not _event_payload(continued.events, &"monster_death_macro_requested").is_empty():
		return _start_session_death_macro(events)
	if continued.completed:
		return _finish_direct_battle(events)
	return _context.completed(events)


func _append_session_battle_after_message(battle_id: String, events: Array[DomainEvent]) -> void:
	var battle = _context.content.battle_by_id(battle_id)
	if battle == null or battle.message_after_id == 0:
		return
	var message = _context.content.message_by_id(absi(battle.message_after_id))
	if message != null:
		events.append(DomainEvent.new(&"message_shown", {"messageId": message.id, "text": message.text, "source": "classic-battle-definition"}))


func _finish_direct_battle(events: Array[DomainEvent]) -> SessionCoordinatorResult:
	if _context.state.combat == null or not _context.state.combat.completed:
		return _context.failed(&"invalid_battle_continuation", "Post-battle completion requires a completed battle.", events)
	if _context.state.combat.outcome == &"defeat":
		return _start_application_hook(ScenarioApplicationHooks.PARTY_DEATH, "party-defeat", "", events)
	var payload = _context.rules.combat_flow.ally_selection_payload(_context.state, _context.content)
	if not payload.is_empty():
		var request_id = "session.ally-selection.%d" % _context.next_revision()
		var combat = SessionContinuation.CombatBody.new()
		combat.battle_id = _context.state.combat.battle_id
		_context.set_continuation(SessionContinuation.combat_state(&"combat-ally-selection", combat))
		_context.session_interaction = InteractionRequest.from_payload(request_id, &"ally_selection", payload)
		return _context.waiting(_context.session_interaction, events)
	return _finish_direct_battle_recovery(events)


func _finish_direct_battle_recovery(events: Array[DomainEvent]) -> SessionCoordinatorResult:
	return _begin_direct_battle_reward(events)


func _finish_direct_battle_without_rewards(events: Array[DomainEvent]) -> SessionCoordinatorResult:
	if _context.state.combat == null or not _context.state.combat.completed:
		return _context.failed(&"invalid_battle_continuation", "Suppressed battle rewards require a completed battle.", events)
	var battle_id = _context.state.combat.battle_id
	var return_continuation = _context.battle_return_continuation.copy()
	var battle_outcome = _context.state.combat.outcome
	events.append(DomainEvent.new(&"battle_returned", {"battleId": battle_id, "outcome": String(battle_outcome)}))
	_context.state.combat = null
	return _finish_after_direct_battle(events, return_continuation, battle_outcome)


func _begin_direct_battle_reward(events: Array[DomainEvent]) -> SessionCoordinatorResult:
	var return_continuation = _context.battle_return_continuation.copy()
	var battle_outcome = _context.state.combat.outcome
	var request_id = "session.battle-reward.%d" % _context.next_revision()
	var operation = _context.runtime_api.begin_completed_battle_reward(request_id)
	events.append_array(operation.events)
	if operation.state == ScenarioRuntimeOperationResult.State.FAILED:
		return _context.failed(operation.error_code, operation.error_message, events)
	if operation.state == ScenarioRuntimeOperationResult.State.WAITING:
		_context.set_continuation(SessionContinuation.combat_reward(_context.state.combat.battle_id, operation.continuation))
		_context.session_interaction = operation.interaction
		return _context.waiting(_context.session_interaction, events)
	_context.session_interaction = null
	_context.session_continuation.clear()
	return _finish_after_direct_battle(events, return_continuation, battle_outcome)


func _finish_after_direct_battle(events: Array[DomainEvent], return_continuation: SessionContinuation, battle_outcome: StringName) -> SessionCoordinatorResult:
	_context.battle_return_continuation.clear()
	if return_continuation == null or return_continuation.is_empty() or battle_outcome == &"defeat" or not _events_have(events, &"battle_returned"):
		return _context.completed(events)
	_context.set_continuation(return_continuation.copy())
	return _context.exploration()._continue_post_time(events)

class_name InventoryMagicServicesWorkflow
extends RefCounted


class MagicTransitionResult:
	extends RefCounted
	var ok: bool
	var completed: bool
	var process_age_updates: bool
	var events: Array[DomainEvent]
	var continuation: SessionContinuation
	var interaction: InteractionRequest
	var error_code: StringName
	var error_message: String

	static func failed(code: StringName, message: String) -> MagicTransitionResult:
		var result := MagicTransitionResult.new()
		result.error_code = code
		result.error_message = message
		return result

	static func committed(workflow_result: SessionWorkflowResult, should_process_age_updates: bool = false) -> MagicTransitionResult:
		if workflow_result == null:
			return failed(&"invalid_workflow_result", "The magic workflow returned no result.")
		if not workflow_result.ok:
			return failed(workflow_result.error_code, workflow_result.error_message)
		var result := MagicTransitionResult.new()
		result.ok = true
		result.completed = true
		result.process_age_updates = should_process_age_updates
		result.events = workflow_result.events
		return result

	static func waiting(pending_continuation: SessionContinuation, pending_interaction: InteractionRequest, pending_events: Array[DomainEvent]) -> MagicTransitionResult:
		var result := MagicTransitionResult.new()
		result.ok = true
		result.continuation = pending_continuation
		result.interaction = pending_interaction
		result.events = pending_events
		return result


static func set_fast_spell(context: SessionWorkflowContext, payload: PlayerIntent.SpellPayload) -> SessionWorkflowResult:
	if context.state.combat != null and not context.state.combat.completed:
		return SessionWorkflowResult.failed(&"fast_spell_binding_in_battle", "Fast Spell bindings cannot be changed during battle.")
	var character := context.state.party.character_by_id(payload.caster_id)
	if character == null or payload.scroll_slot < 0 or payload.scroll_slot >= 10:
		return SessionWorkflowResult.failed(&"invalid_fast_spell_slot", "The selected Fast Spell slot is unavailable.")
	if payload.spell_id.is_empty():
		if not character.clear_fast_spell(payload.scroll_slot):
			return SessionWorkflowResult.failed(&"fast_spell_binding_failed", "The Fast Spell slot could not be cleared.")
		return SessionWorkflowResult.completed([DomainEvent.new(&"fast_spell_changed", {"characterId": character.id, "slot": payload.scroll_slot, "spellId": "", "power": 0, "source": "classic"})])
	var spell := context.content.spell_by_id(payload.spell_id)
	if spell == null or not character.known_spells().has(spell.id):
		return SessionWorkflowResult.failed(&"invalid_fast_spell", "Fast Spells must reference a spell known by this character.")
	if payload.power < 1 or payload.power > 7 or spell.cost < 0 and payload.power != 1:
		return SessionWorkflowResult.failed(&"invalid_fast_spell_power", "The selected spell does not support that Fast Spell power.")
	if not character.bind_fast_spell(payload.scroll_slot, spell.id, payload.power):
		return SessionWorkflowResult.failed(&"fast_spell_binding_failed", "The Fast Spell binding could not be committed.")
	return SessionWorkflowResult.completed([DomainEvent.new(&"fast_spell_changed", {"characterId": character.id, "slot": payload.scroll_slot, "spellId": spell.id, "power": payload.power, "source": "classic"})])


static func classic_torch_item(context: SessionWorkflowContext) -> Array[String]:
	var torch := context.content.item_by_classic_id(805)
	if torch == null:
		return []
	for character: CharacterState in context.state.party.characters():
		for instance: ItemInstance in character.inventory():
			if instance.definition_id == torch.id:
				return [character.id, instance.id]
	return []


static func classic_torch_probe(context: SessionWorkflowContext) -> InventoryActionProbe:
	var identity := classic_torch_item(context)
	if identity.is_empty():
		return InventoryActionProbe.block("The party carries no usable torch.")
	var character := context.state.party.character_by_id(identity[0])
	var instance := _item_instance(character, identity[1])
	var item: ItemDefinition = null if instance == null else context.content.item_by_id(instance.definition_id)
	var spell: SpellDefinition = null if item == null else context.content.spell_by_classic_id(item.special_2)
	return field_spell_item_probe(context, character, instance, item, spell)


static func begin_classic_torch(context: SessionWorkflowContext, request_revision: int) -> MagicTransitionResult:
	var identity := classic_torch_item(context)
	if identity.is_empty():
		return MagicTransitionResult.failed(&"torch_unavailable", "The party carries no usable torch.")
	return begin_field_spell_item(context, identity[0], identity[1], "", [], request_revision)


static func equip_item(context: SessionWorkflowContext, payload: PlayerIntent.ItemActionPayload) -> SessionWorkflowResult:
	var character := context.state.party.character_by_id(payload.actor_id)
	var instance := _item_instance(character, payload.item_id)
	var definition: ItemDefinition = null if instance == null else context.content.item_by_id(instance.definition_id)
	if character == null or instance == null or definition == null:
		return SessionWorkflowResult.failed(&"unknown_item_instance", "The selected character does not carry that item instance.")
	var probe := context.rules.inventory.equip_classic(character, instance, definition, context.content.race_by_id(character.race_id), context.content.caste_by_id(character.caste_id), context.state.party.characters(), context.content.item_definitions())
	if not probe.allowed:
		return SessionWorkflowResult.failed(&"item_cannot_equip", probe.reason)
	return SessionWorkflowResult.completed([DomainEvent.new(&"item_equipped", {"characterId": character.id, "instanceId": instance.id, "itemId": definition.id, "identified": instance.identified})])


static func unequip_item(context: SessionWorkflowContext, payload: PlayerIntent.ItemActionPayload) -> SessionWorkflowResult:
	var character := context.state.party.character_by_id(payload.actor_id)
	var instance := _item_instance(character, payload.item_id)
	var definition: ItemDefinition = null if instance == null else context.content.item_by_id(instance.definition_id)
	if character == null or instance == null or definition == null:
		return SessionWorkflowResult.failed(&"unknown_item_instance", "The selected character does not carry that item instance.")
	var probe := context.rules.inventory.unequip_classic(character, instance, definition, context.content.item_definitions())
	if not probe.allowed:
		return SessionWorkflowResult.failed(&"item_cannot_unequip", probe.reason)
	return SessionWorkflowResult.completed([DomainEvent.new(&"item_unequipped", {"characterId": character.id, "instanceId": instance.id, "itemId": definition.id})])


static func trade_item(context: SessionWorkflowContext, payload: PlayerIntent.ItemActionPayload) -> SessionWorkflowResult:
	var source := context.state.party.character_by_id(payload.actor_id)
	var destination := context.state.party.character_by_id(payload.destination_character_id)
	var instance := _item_instance(source, payload.item_id)
	var definition: ItemDefinition = null if instance == null else context.content.item_by_id(instance.definition_id)
	if source == null or destination == null or instance == null or definition == null:
		return SessionWorkflowResult.failed(&"invalid_item_trade", "Trade requires a carried item and two current party members.")
	var probe := context.rules.inventory.trade_classic(source, destination, instance, definition)
	if not probe.allowed:
		return SessionWorkflowResult.failed(&"item_cannot_trade", probe.reason)
	return SessionWorkflowResult.completed([DomainEvent.new(&"item_traded", {"fromCharacterId": source.id, "toCharacterId": destination.id, "instanceId": instance.id, "itemId": definition.id})])


static func split_item(context: SessionWorkflowContext, payload: PlayerIntent.ItemActionPayload) -> SessionWorkflowResult:
	var character := context.state.party.character_by_id(payload.actor_id)
	var instance := _item_instance(character, payload.item_id)
	var definition: ItemDefinition = null if instance == null else context.content.item_by_id(instance.definition_id)
	if character == null or instance == null or definition == null:
		return SessionWorkflowResult.failed(&"unknown_item_instance", "The selected character does not carry that item instance.")
	var probe := context.rules.inventory.classic_split_probe(character, instance, definition)
	if not probe.allowed:
		return SessionWorkflowResult.failed(&"item_cannot_split", probe.reason)
	var previous_charges := instance.charges
	var new_instance_id := context.state.next_instance_id("inventory.item")
	probe = context.rules.inventory.split_classic(character, instance, definition, new_instance_id)
	if not probe.allowed:
		return SessionWorkflowResult.failed(&"item_split_failed", probe.reason)
	var split_instance := _item_instance(character, new_instance_id)
	if split_instance == null:
		return SessionWorkflowResult.failed(&"item_split_failed", "The split item was not created.")
	return SessionWorkflowResult.completed([
		DomainEvent.new(&"item_split", {"characterId": character.id, "instanceId": instance.id, "newInstanceId": split_instance.id, "itemId": definition.id, "previousCharges": previous_charges, "remainingCharges": instance.charges, "splitCharges": split_instance.charges}),
		DomainEvent.new(&"sound_requested", {"soundId": 678, "waitForCompletion": false, "source": "classic-item"}),
	])


static func join_item(context: SessionWorkflowContext, payload: PlayerIntent.ItemActionPayload) -> SessionWorkflowResult:
	var character := context.state.party.character_by_id(payload.actor_id)
	var instance := _item_instance(character, payload.item_id)
	var definition: ItemDefinition = null if instance == null else context.content.item_by_id(instance.definition_id)
	if character == null or instance == null or definition == null:
		return SessionWorkflowResult.failed(&"unknown_item_instance", "The selected character does not carry that item instance.")
	var probe := context.rules.inventory.classic_join_probe(character, instance, definition)
	if not probe.allowed:
		return SessionWorkflowResult.failed(&"item_cannot_join", probe.reason)

class_name GameSession
extends RefCounted

const ExplorationCoordinatorType = preload("res://src/session/coordinators/session_exploration_coordinator.gd")
const ScenarioCoordinatorType = preload("res://src/session/coordinators/session_scenario_coordinator.gd")
const ResponseCoordinatorType = preload("res://src/session/coordinators/session_responses_coordinator.gd")
var _content: RealmzContent
var _state: GameState
var _rng: RealmzRng
var _rules: RealmzRules
var _scenario_vm: ScenarioVm
var _scenario_action_state: ScenarioActionState
var _runtime_api: RealmzRuntimeApi
var _session_continuation: SessionContinuation = SessionContinuation.new()
var _battle_return_continuation: SessionContinuation = SessionContinuation.new()
var _session_interaction: InteractionRequest
var _started: bool = false
var _view_revision: int = 0
var _view_projector := SessionViewProjector.new()
var _coordinator_context: SessionCoordinatorContext
var _exploration_coordinator: RefCounted
var _scenario_coordinator: RefCounted
var _response_coordinator: RefCounted


func _ensure_coordinators() -> void:
	_coordinator_context = SessionCoordinatorContext.new(
		_content,
		_state,
		_rng,
		_rules,
		_scenario_vm,
		_scenario_action_state,
		_runtime_api,
		_session_continuation,
		_battle_return_continuation,
		_session_interaction,
		_view_revision
	)
	_exploration_coordinator = ExplorationCoordinatorType.new(_coordinator_context)
	_scenario_coordinator = ScenarioCoordinatorType.new(_coordinator_context)
	_response_coordinator = ResponseCoordinatorType.new(_coordinator_context)
	_coordinator_context.bind_coordinators(_exploration_coordinator, _scenario_coordinator, _response_coordinator)


func _apply_coordinator_context() -> void:
	assert(_coordinator_context != null, "A coordinator result requires its explicit session context")
	_content = _coordinator_context.content
	_state = _coordinator_context.state
	_rng = _coordinator_context.rng
	_rules = _coordinator_context.rules
	_scenario_vm = _coordinator_context.scenario_vm
	_scenario_action_state = _coordinator_context.scenario_action_state
	_runtime_api = _coordinator_context.runtime_api
	_session_continuation = _coordinator_context.session_continuation
	_battle_return_continuation = _coordinator_context.battle_return_continuation
	_session_interaction = _coordinator_context.session_interaction
	_coordinator_context.release_coordinators()
	_coordinator_context = null
	_exploration_coordinator = null
	_scenario_coordinator = null
	_response_coordinator = null


func _commit_coordinator_result(result: SessionCoordinatorResult) -> SessionStep:
	_apply_coordinator_context()
	if result == null:
		return _finish_failed(&"invalid_coordinator_result", "The session coordinator returned no typed result.", [])
	match result.state:
		SessionCoordinatorResult.State.COMPLETED:
			return _finish_completed(result.events)
		SessionCoordinatorResult.State.WAITING:
			return _finish_waiting(result.interaction, result.events)
		SessionCoordinatorResult.State.FAILED:
			return _finish_failed(result.error_code, result.error_message, result.events)
		SessionCoordinatorResult.State.CLOSE:
			return _commit_close(result.events, result.close_reason)
	return _finish_failed(&"invalid_coordinator_result", "The session coordinator returned an unknown state.", [])


func start(content: RealmzContent, initial_seed: int) -> SessionStep:
	if _started:
		return SessionStep.failed(_view_revision, &"session_already_started", "The session has already started.")
	if content == null or content.scenario == null:
		return SessionStep.failed(_view_revision, &"invalid_content", "Validated Realmz content is required.")
	var start_map := content.world.map_by_id(content.start_map_id)
	if start_map == null or start_map.topology.cell_at(content.start_coordinate) == null:
		return SessionStep.failed(_view_revision, &"invalid_start_location", "The package start location is unavailable.")
	var starting_characters: Array[CharacterState] = []
	var game_state := GameState.new(PartyState.new(content.start_map_id, content.start_coordinate, starting_characters), RealmzClock.new())
	game_state.world.mark_visited(content.start_map_id, content.start_coordinate)
	var random_source := RealmzRng.new(initial_seed)
	var action_state := ScenarioActionState.new()
	var scenario_vm := ScenarioVm.new()
	scenario_vm.configure(content.scenario)
	_content = content
	_state = game_state
	_rng = random_source
	_rules = RealmzRules.new()
	_scenario_action_state = action_state
	_scenario_vm = scenario_vm
	_runtime_api = RealmzRuntimeApi.new(_content, _state, _rng, _scenario_action_state, _rules)
	_session_continuation.clear()
	_battle_return_continuation.clear()
	_session_interaction = null
	_view_projector.clear()
	_started = true
	_view_revision = 1
	return SessionStep.completed(_view_revision, [DomainEvent.new("session_started", {"campaignId": content.campaign_id})])


func restore(content: RealmzContent, save_envelope: SessionSnapshot) -> SessionStep:
	var result := SessionRestoreValidator.validate(content, save_envelope)
	if not result.ok:
		return SessionStep.failed(_view_revision, result.error_code, result.error_message)
	var candidate := result.candidate
	_content = content
	_state = candidate.state
	_rng = candidate.rng
	_rules = candidate.rules
	_scenario_action_state = candidate.scenario_action_state
	_scenario_vm = candidate.scenario_vm
	_runtime_api = RealmzRuntimeApi.new(_content, _state, _rng, _scenario_action_state, _rules)
	_session_continuation = candidate.continuation
	_battle_return_continuation = candidate.battle_return_continuation
	_session_interaction = candidate.session_interaction
	_view_projector.clear()
	_view_revision = candidate.view_revision
	_started = true
	return SessionStep.completed(_view_revision, [DomainEvent.new("session_restored")])


func close() -> SessionStep:
	if not _started:
		return SessionStep.failed(_view_revision, &"session_not_started", "There is no active session to close.")
	var pending := _pending_interaction()
	if (_scenario_vm.is_active() and pending == null) or (pending != null and pending.kind != InteractionRequest.COMBAT):
		return SessionStep.failed(_view_revision, &"session_not_committed", "The session can close only at a committed boundary.")
	# Castle permits End Adventure during combat after confirmation. Abandon the
	# interrupted combat/VM interaction before the synchronous Global hooks run.
	if pending != null:
		_session_continuation.clear()
		_battle_return_continuation.clear()
		_session_interaction = null
		_scenario_vm = ScenarioVm.new()
		_scenario_vm.configure(_content.scenario)
		_runtime_api = RealmzRuntimeApi.new(_content, _state, _rng, _scenario_action_state, _rules)
	return _start_application_hook(ScenarioApplicationHooks.END_ADVENTURE, "end-adventure", "", [])


func _commit_close(events: Array[DomainEvent], reason: String) -> SessionStep:
	var campaign_id := _content.campaign_id
	_session_continuation.clear()
	_battle_return_continuation.clear()
	_session_interaction = null
	_runtime_api = null
	_scenario_vm = null
	_scenario_action_state = null
	_rules = null
	_rng = null

	if _session_interaction != null:
		interaction = InteractionRequest.from_data(_session_interaction.to_data())
	if state == null or vm_state == null or action_state == null or _session_interaction != null and interaction == null:
		return null
	var continuation := null if _session_continuation.is_empty() else SessionContinuation.from_data(_session_continuation.to_data())
	var battle_return := null if _battle_return_continuation.is_empty() else SessionContinuation.from_data(_battle_return_continuation.to_data())
	return SessionSnapshot.new(_content.campaign_id, _content.package_hash, _content.rules_version, _view_revision, state, _rng.snapshot(), vm_state, action_state, continuation, battle_return, interaction)


func rng_trace() -> Array[Dictionary]:
	return [] if _rng == null else _rng.trace()


func scenario_trace() -> Array[Dictionary]:
	return [] if _scenario_vm == null else _scenario_vm.trace()


func _camp() -> SessionStep:
	var result := ExplorationTimeWorkflow.toggle_camp(_workflow_context())
	if not result.ok:
		return _finish_failed(result.error_code, result.error_message, result.events)
	if not _state.party_camping and result.timed_day == 0:
		return _finish_with_age_updates(result.events, "completed")
	_set_post_time_continuation(result.map, "completed", Vector2i.ZERO, result.check_random, result.timed_day, _state.party.coordinate)
	return _finish_with_age_updates(result.events, &"post-clock", _session_continuation.copy())


func _rest() -> SessionStep:
	var result := ExplorationTimeWorkflow.rest(_workflow_context())
	if not result.ok:
		return _finish_failed(result.error_code, result.error_message, result.events)
	_set_post_time_continuation(result.map, "completed", Vector2i.ZERO, result.check_random, result.timed_day, _state.party.coordinate)
	return _finish_with_age_updates(result.events, &"post-clock", _session_continuation.copy())


func _heal() -> SessionStep:
	var result := ExplorationTimeWorkflow.heal(_workflow_context())
	if not result.ok:
		return _finish_failed(result.error_code, result.error_message, result.events)
	_set_post_time_continuation(result.map, "heal", Vector2i.ZERO, result.check_random, result.timed_day, _state.party.coordinate)
	return _finish_with_age_updates(result.events, &"post-clock", _session_continuation.copy())


func _use_item(intent: PlayerIntent) -> SessionStep:
	var actor_id := ""
	var item_id := ""
	var target_id := ""
	var target_ids: Array[String] = []
	if intent.payload is PlayerIntent.ItemUsePayload:
		var use_payload := intent.payload as PlayerIntent.ItemUsePayload
		actor_id = use_payload.actor_id
		item_id = use_payload.item_id
	else:
		var target_payload := intent.payload as PlayerIntent.ItemTargetPayload
		actor_id = target_payload.actor_id
		item_id = target_payload.item_id
		target_id = target_payload.target_id
		target_ids = target_payload.target_ids.duplicate()
	var character := _state.party.character_by_id(actor_id)
	if character == null:
		character = InventoryMagicServicesWorkflow.item_owner(_workflow_context(), item_id)
	var instance := _item_instance(character, item_id)
	var item: ItemDefinition = null if instance == null else _content.item_by_id(instance.definition_id)
	if character == null or instance == null or item == null:
		return SessionStep.failed(_view_revision, &"unknown_item_instance", "The selected character does not carry that item instance.")
	if _state.combat != null and not _state.combat.completed:
		var combat_result := _rules.combat_flow.use_spell_item(_state, _content, character.id, target_id, instance.id, _rng)
		if not combat_result.ok:
			return SessionStep.failed(_view_revision, combat_result.error_code, combat_result.error_message)
		if not CharacterAgingResult.update_payloads(combat_result.events).is_empty():
			return _finish_with_age_updates(combat_result.events, "combat-monster-turns")
		if not _event_payload(combat_result.events, &"monster_death_macro_requested").is_empty():
			return _start_session_death_macro(combat_result.events)
		if combat_result.completed:
			return _finish_direct_battle(combat_result.events)
		return _finish_completed(combat_result.events)
	return _finish_magic_transition(InventoryMagicServicesWorkflow.begin_field_spell_item(_workflow_context(), actor_id, item_id, target_id, target_ids, _view_revision + 1))


func _request_drop_item(intent: PlayerIntent) -> SessionStep:
	var payload := intent.payload as PlayerIntent.ItemActionPayload
	var character := _state.party.character_by_id(payload.actor_id)
	var instance := _item_instance(character, payload.item_id)
	var definition: ItemDefinition = null if instance == null else _content.item_by_id(instance.definition_id)
	if character == null or instance == null or definition == null:
		return SessionStep.failed(_view_revision, &"unknown_item_instance", "The selected character does not carry that item instance.")
	var probe := _rules.inventory.classic_drop_probe(character, instance)
	if not probe.allowed:
		return SessionStep.failed(_view_revision, &"item_cannot_drop", probe.reason)
	var targeting := SessionContinuation.TargetingBody.new()
	targeting.character_id = character.id
	targeting.instance_id = instance.id
	_set_continuation(SessionContinuation.targeting_selection(&"drop-item-confirmation", targeting))
	var display_name := definition.name if instance.identified else definition.unidentified_name
	_session_interaction = SessionInteractionFactory.drop_item_confirmation("session.drop-item:%s:%d" % [instance.id, _view_revision + 1], display_name)
	return _finish_waiting(_session_interaction, [DomainEvent.new(&"item_drop_requested", {"characterId": character.id, "instanceId": instance.id})])


func _item_instance(character: CharacterState, instance_id: String) -> ItemInstance:
	if character == null or instance_id.is_empty():
		return null
	for instance: ItemInstance in character.inventory():
		if instance.id == instance_id:
			return instance
	return null


func _cast_spell(intent: PlayerIntent) -> SessionStep:
	var payload := intent.payload as PlayerIntent.SpellPayload
	if payload.operation == &"identify-inventory":
		return _commit_workflow_result(InventoryMagicServicesWorkflow.identify_inventory(_workflow_context(), payload))
	if payload.operation == &"make-scroll":
		return _commit_workflow_result(InventoryMagicServicesWorkflow.make_scroll(_workflow_context(), payload))
	if payload.operation == &"use-scroll":
		return _use_scroll(payload)
	if _state.combat == null or _state.combat.completed:
		return _cast_field_spell(payload)
	var result := _rules.combat_flow.cast_spell(_state, _content, payload.caster_id, payload.target_id, payload.spell_id, payload.power, _rng, payload.coordinate, payload.rotation, payload.target_ids)
	if not result.ok:
		return SessionStep.failed(_view_revision, result.error_code, result.error_message)
	if not CharacterAgingResult.update_payloads(result.events).is_empty():
		return _finish_with_age_updates(result.events, "combat-monster-turns")
	if not _event_payload(result.events, &"monster_death_macro_requested").is_empty():
		return _start_session_death_macro(result.events)
	if result.completed:
		return _finish_direct_battle(result.events)
	return _finish_completed(result.events)


func _use_scroll(payload: PlayerIntent.SpellPayload) -> SessionStep:
	if _state.combat != null and not _state.combat.completed:
		var combat_result := _rules.combat_flow.use_combat_scroll(_state, _content, payload.caster_id, payload.scroll_slot, payload.target_id, _rng, payload.coordinate, payload.rotation, payload.target_ids)
		if not combat_result.ok:
			return SessionStep.failed(_view_revision, combat_result.error_code, combat_result.error_message)
		if not _event_payload(combat_result.events, &"monster_death_macro_requested").is_empty():
			return _start_session_death_macro(combat_result.events)
		if combat_result.completed:
			return _finish_direct_battle(combat_result.events)
		return _finish_completed(combat_result.events)
	return _finish_magic_transition(InventoryMagicServicesWorkflow.begin_field_scroll(_workflow_context(), payload, _view_revision + 1))


func _cast_field_spell(payload: PlayerIntent.SpellPayload) -> SessionStep:
	return _finish_magic_transition(InventoryMagicServicesWorkflow.begin_field_spell(_workflow_context(), payload, _view_revision + 1))


func _combat_action(intent: PlayerIntent) -> SessionStep:
	var payload := intent.payload as PlayerIntent.CombatActionPayload
	if payload.action == &"retreat":
		var retreat_probe: Variant = _rules.combat_flow.probe_character_retreat(_state.combat, _state.party.characters(), payload.actor_id)
		if not retreat_probe.allowed:
			return SessionStep.failed(_view_revision, retreat_probe.reason, retreat_probe.reason_text)
		return _request_session_retreat(payload.actor_id, &"explicit", Vector2i(-100_000, -100_000))
	var result := CombatRewardsWorkflow.submit_action(_workflow_context(), payload)
	if not result.ok:
		return SessionStep.failed(_view_revision, result.error_code, result.error_message)
	if not CharacterAgingResult.update_payloads(result.events).is_empty():
		return _finish_with_age_updates(result.events, "combat-monster-turns")
	if not _event_payload(result.events, &"monster_death_macro_requested").is_empty():
		return _start_session_death_macro(result.events)

	if result.completed:
		return _finish_direct_battle(result.events)
	return _finish_completed(result.events)


func _set_combat_auto(intent: PlayerIntent) -> SessionStep:
	var payload := intent.payload as PlayerIntent.CombatAutoPayload
	if _state == null or _state.combat == null or _state.combat.completed:
		return SessionStep.failed(_view_revision, &"combat_auto_unavailable", "Persistent Auto can be changed only during an active battle.")
	var character := _state.party.character_by_id(payload.character_id)
	if character == null or character.current_health <= 0:
		return SessionStep.failed(_view_revision, &"invalid_combat_auto_character", "Persistent Auto requires a living party character.")
	var pending := _pending_interaction()
	if pending != null:
		if pending.kind != InteractionRequest.COMBAT or _session_interaction != null:
			return SessionStep.failed(_view_revision, &"interaction_pending", "Persistent Auto cannot replace this pending interaction.")
		if _scenario_vm != null and _scenario_vm.pending_request() == pending:
			var response_body := InteractionResponse.CombatBody.new(&"set_auto", payload.character_id)
			response_body.enabled = payload.enabled
			return respond(InteractionResponse.new(pending.request_id, pending.kind, response_body))
	return _finish_combat_result(CombatRewardsWorkflow.set_persistent_auto(_workflow_context(), payload))


func _combat_move(intent: PlayerIntent) -> SessionStep:
	var payload := intent.payload as PlayerIntent.CombatMovePayload
	var edge_probe: Variant = _rules.combat_flow.probe_edge_retreat(_state.combat, payload.actor_id, payload.destination)
	if edge_probe.allowed:
		if not edge_probe.forced:
			return _request_session_retreat(payload.actor_id, &"edge", payload.destination)
		var forced_result := CombatRewardsWorkflow.move_character(_workflow_context(), payload, true)
		return _finish_combat_result(forced_result)
	var result := CombatRewardsWorkflow.move_character(_workflow_context(), payload, false)
	return _finish_combat_result(result)


func _finish_combat_result(result: CombatFlowResult) -> SessionStep:
	if not result.ok:
		return SessionStep.failed(_view_revision, result.error_code, result.error_message)
	if not CharacterAgingResult.update_payloads(result.events).is_empty():
		return _finish_with_age_updates(result.events, "combat-monster-turns")
	if not _event_payload(result.events, &"monster_death_macro_requested").is_empty():
		return _start_session_death_macro(result.events)
	if result.completed:
		return _finish_direct_battle(result.events)
	return _finish_completed(result.events)


func _request_session_retreat(actor_id: String, mode: StringName, destination: Vector2i) -> SessionStep:
	if _state.combat == null or _state.combat.active_actor_id() != actor_id:
		return SessionStep.failed(_view_revision, &"invalid_combat_actor", "The active character cannot retreat.")
	var combat := SessionContinuation.CombatBody.new()
	combat.battle_id = _state.combat.battle_id
	combat.actor_id = actor_id
	combat.mode = mode
	combat.destination = destination
	_set_continuation(SessionContinuation.combat_state(&"combat-retreat-confirmation", combat))
	_session_interaction = SessionInteractionFactory.retreat_confirmation("session.combat-retreat:%d" % (_view_revision + 1))
	return _finish_waiting(_session_interaction, [])


