	quit(exit_code)

param(
    [Parameter(Mandatory = $true)]
    [string]$ManifestPath,
    [string]$GodotPath = ""
)

$ErrorActionPreference = "Stop"
$repoRoot = Split-Path -Parent $PSScriptRoot
if (-not (Test-Path -LiteralPath $ManifestPath)) {
    throw "Corpus manifest does not exist: $ManifestPath"
}
if ([string]::IsNullOrWhiteSpace($GodotPath)) {
    $godotCommand = Get-Command Godot_v4.7.1-stable_win64_console.exe -ErrorAction SilentlyContinue
    if ($null -eq $godotCommand) {
        $godotCommand = Get-Command godot -ErrorAction Stop
    }
    $GodotPath = $godotCommand.Source
}

$manifest = Get-Content -Raw -LiteralPath $ManifestPath | ConvertFrom-Json
if ($manifest.schemaVersion -ne 1 -or $null -eq $manifest.campaigns -or $manifest.campaigns.Count -eq 0) {
    throw "Corpus manifest must use schemaVersion 1 and declare at least one campaign."
}

$failures = @()
foreach ($campaign in $manifest.campaigns) {
    foreach ($field in @("id", "package", "route", "report")) {
        if ([string]::IsNullOrWhiteSpace($campaign.$field)) {
            throw "Corpus entry is missing $field."
        }
    }
    foreach ($inputPath in @($campaign.package, $campaign.route)) {
        if (-not (Test-Path -LiteralPath $inputPath)) {
            throw "Corpus input does not exist: $inputPath"
        }
    }
    $reportDirectory = Split-Path -Parent $campaign.report
    if (-not [string]::IsNullOrWhiteSpace($reportDirectory)) {
        New-Item -ItemType Directory -Force -Path $reportDirectory | Out-Null
    }
    Write-Host "CERTIFY $($campaign.id)"
    & $GodotPath --headless --path $repoRoot --script res://tools/route_acceptance.gd -- $campaign.package $campaign.route $campaign.report
    if ($LASTEXITCODE -ne 0) {
        $failures += $campaign.id
    }
}

if ($failures.Count -gt 0) {
    throw "Campaign route certification failed: $($failures -join ', ')"
}
Write-Host "Corpus route certification passed for $($manifest.campaigns.Count) campaign(s)."

param(
    [Parameter(Mandatory = $true)]
    [string]$SourcePng,
    [int]$TargetWidth = 48,
    [int]$TargetHeight = 468
)

$ErrorActionPreference = "Stop"
Add-Type -AssemblyName System.Drawing
$toolRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
$repoRoot = Split-Path -Parent (Split-Path -Parent $toolRoot)
$outputPath = Join-Path $repoRoot "src/presentation/assets/ui/classic-exploration-rail.png"
$sourcePath = (Resolve-Path -LiteralPath $SourcePng).Path
$stagingPath = Join-Path ([IO.Path]::GetTempPath()) ("realmz2-exploration-rail-" + [Guid]::NewGuid().ToString("N") + ".png")

if ($TargetWidth -lt 1 -or $TargetHeight -lt 1) {
    throw "Target dimensions must be positive."
}

$source = [Drawing.Bitmap]::new([string]$sourcePath)
try {
    $minimumX = $source.Width
    $minimumY = $source.Height
    $maximumX = -1
    $maximumY = -1
    for ($y = 0; $y -lt $source.Height; $y++) {
        for ($x = 0; $x -lt $source.Width; $x++) {
            if ($source.GetPixel($x, $y).A -eq 0) {
                continue
            }
            $minimumX = [Math]::Min($minimumX, $x)
            $minimumY = [Math]::Min($minimumY, $y)
            $maximumX = [Math]::Max($maximumX, $x)
            $maximumY = [Math]::Max($maximumY, $y)
        }
    }
    if ($maximumX -lt $minimumX -or $maximumY -lt $minimumY) {
        throw "The selected rail has no visible pixels."
    }

    $sourceRect = [Drawing.Rectangle]::new(
        $minimumX,
        $minimumY,
        $maximumX - $minimumX + 1,
        $maximumY - $minimumY + 1
    )
    $output = [Drawing.Bitmap]::new($TargetWidth, $TargetHeight, [Drawing.Imaging.PixelFormat]::Format32bppArgb)
    $graphics = [Drawing.Graphics]::FromImage($output)
    try {
        $graphics.Clear([Drawing.Color]::Transparent)
        $graphics.CompositingMode = [Drawing.Drawing2D.CompositingMode]::SourceCopy
        $graphics.CompositingQuality = [Drawing.Drawing2D.CompositingQuality]::HighQuality
        $graphics.InterpolationMode = [Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
        $graphics.PixelOffsetMode = [Drawing.Drawing2D.PixelOffsetMode]::HighQuality
        $graphics.DrawImage(
            $source,
            [Drawing.Rectangle]::new(0, 0, $TargetWidth, $TargetHeight),
            $sourceRect,
            [Drawing.GraphicsUnit]::Pixel
        )
    }
    finally { $graphics.Dispose() }
    try { $output.Save($stagingPath, [Drawing.Imaging.ImageFormat]::Png) }
    finally { $output.Dispose() }

    New-Item -ItemType Directory -Path (Split-Path -Parent $outputPath) -Force | Out-Null
    Copy-Item -LiteralPath $stagingPath -Destination $outputPath -Force
    $sourceHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $sourcePath).Hash.ToLowerInvariant()
    $outputHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $outputPath).Hash.ToLowerInvariant()
    Write-Host "Built exploration rail from crop $($sourceRect.X),$($sourceRect.Y),$($sourceRect.Width),$($sourceRect.Height)."
    Write-Host "Source SHA-256: $sourceHash"
    Write-Host "Output SHA-256: $outputHash"
}
finally {
    $source.Dispose()
    if (Test-Path -LiteralPath $stagingPath) {
        Remove-Item -LiteralPath $stagingPath -Force
    }
}

param(
    [Parameter(Mandatory = $true)]
    [string]$SourcePng,

    [string]$ExpectedSourceSha256 = "2bd8594faccb531aa1c0a9d013e2136ccbfe6017d8f6d3ce00fb327327ae4878"
)

$ErrorActionPreference = "Stop"
Add-Type -AssemblyName System.Drawing

$toolRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
$repoRoot = Split-Path -Parent (Split-Path -Parent $toolRoot)
$outputPath = Join-Path $repoRoot "src/presentation/assets/ui/classic-intro-frame.png"
$sourcePath = (Resolve-Path -LiteralPath $SourcePng).Path
$sourceHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $sourcePath).Hash.ToLowerInvariant()
if ($sourceHash -ne $ExpectedSourceSha256.ToLowerInvariant()) {
    throw "Intro-frame source hash does not match the approved SpriteCook asset"
}

$stagingPath = Join-Path ([IO.Path]::GetTempPath()) ("realmz-intro-frame-" + [Guid]::NewGuid().ToString("N") + ".png")
$source = [Drawing.Bitmap]::new([string]$sourcePath)
try {
    if ($source.Width -ne 1024 -or $source.Height -ne 1024) {
        throw "Intro-frame source must be 1024x1024"
    }

    $working = [Drawing.Bitmap]$source.Clone()
    try {
        # SpriteCook supplied an alpha exterior but an opaque neutral center.
        # Clear only the measured opening, leaving the inner gold fillet intact.
        for ($y = 181; $y -le 841; $y++) {
            for ($x = 181; $x -le 841; $x++) {
                $working.SetPixel($x, $y, [Drawing.Color]::Transparent)
            }
        }

        $output = [Drawing.Bitmap]::new(512, 512, [Drawing.Imaging.PixelFormat]::Format32bppArgb)
        try {
            $graphics = [Drawing.Graphics]::FromImage($output)
            try {
                $graphics.Clear([Drawing.Color]::Transparent)
                $graphics.CompositingMode = [Drawing.Drawing2D.CompositingMode]::SourceCopy
                $graphics.CompositingQuality = [Drawing.Drawing2D.CompositingQuality]::HighQuality
                $graphics.InterpolationMode = [Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
                $graphics.PixelOffsetMode = [Drawing.Drawing2D.PixelOffsetMode]::HighQuality
                $graphics.DrawImage(
                    $working,
                    [Drawing.Rectangle]::new(0, 0, 512, 512),
                    [Drawing.Rectangle]::new(88, 88, 848, 848),
                    [Drawing.GraphicsUnit]::Pixel
                )
            }
            finally { $graphics.Dispose() }

            if ($output.GetPixel(256, 256).A -ne 0 -or $output.GetPixel(8, 256).A -eq 0) {
                throw "Derived intro frame does not preserve the expected transparent opening and visible rail"
            }
            $output.Save($stagingPath, [Drawing.Imaging.ImageFormat]::Png)
        }
        finally { $output.Dispose() }
    }
    finally { $working.Dispose() }

    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $outputPath) | Out-Null
    Copy-Item -LiteralPath $stagingPath -Destination $outputPath -Force
    $outputHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $outputPath).Hash.ToLowerInvariant()
    Write-Host "Built 512x512 intro frame from SpriteCook asset source."
    Write-Host "Source SHA-256: $sourceHash"
    Write-Host "Output SHA-256: $outputHash"
}
finally {
    $source.Dispose()
    if (Test-Path -LiteralPath $stagingPath) {
        Remove-Item -LiteralPath $stagingPath -Force
    }
}

