param(
    [Parameter(Mandatory = $true)]
    [string]$VectorFontPath,

    [Parameter(Mandatory = $true)]
    [string]$ClassicBmFontPath,

    [Parameter(Mandatory = $true)]
    [string]$OutputPath
)

$ErrorActionPreference = "Stop"

function Get-U16BE([byte[]]$Bytes, [int]$Offset) {
    if ($Offset -lt 0 -or $Offset + 2 -gt $Bytes.Length) { throw "16-bit read exceeds input at $Offset" }
    return ([int]$Bytes[$Offset] -shl 8) -bor [int]$Bytes[$Offset + 1]
}

function Get-U32BE([byte[]]$Bytes, [int]$Offset) {
    if ($Offset -lt 0 -or $Offset + 4 -gt $Bytes.Length) { throw "32-bit read exceeds input at $Offset" }
    return ([uint32]$Bytes[$Offset] -shl 24) -bor
        ([uint32]$Bytes[$Offset + 1] -shl 16) -bor
        ([uint32]$Bytes[$Offset + 2] -shl 8) -bor
        [uint32]$Bytes[$Offset + 3]
}

function Set-U16BE([byte[]]$Bytes, [int]$Offset, [uint16]$Value) {
    $Bytes[$Offset] = [byte](($Value -shr 8) -band 0xFF)
    $Bytes[$Offset + 1] = [byte]($Value -band 0xFF)
}

function Set-U32BE([byte[]]$Bytes, [int]$Offset, [uint32]$Value) {
    $Bytes[$Offset] = [byte](($Value -shr 24) -band 0xFF)
    $Bytes[$Offset + 1] = [byte](($Value -shr 16) -band 0xFF)
    $Bytes[$Offset + 2] = [byte](($Value -shr 8) -band 0xFF)
    $Bytes[$Offset + 3] = [byte]($Value -band 0xFF)
}

function Get-TableDirectory([byte[]]$Bytes) {
    $count = Get-U16BE $Bytes 4
    $result = @{}
    for ($index = 0; $index -lt $count; $index++) {
        $recordOffset = 12 + ($index * 16)
        $tag = [Text.Encoding]::ASCII.GetString($Bytes, $recordOffset, 4)
        $result[$tag] = [ordered]@{
            RecordOffset = $recordOffset
            Offset = [int](Get-U32BE $Bytes ($recordOffset + 8))
            Length = [int](Get-U32BE $Bytes ($recordOffset + 12))
        }
    }
    return $result
}

function Get-CmapSubtable([byte[]]$Bytes, [hashtable]$Tables) {
    $cmap = $Tables["cmap"]
    if ($null -eq $cmap) { throw "Vector font has no cmap table" }
    $count = Get-U16BE $Bytes ($cmap.Offset + 2)
    $candidates = @()
    for ($index = 0; $index -lt $count; $index++) {
        $recordOffset = $cmap.Offset + 4 + ($index * 8)
        $platform = Get-U16BE $Bytes $recordOffset
        $encoding = Get-U16BE $Bytes ($recordOffset + 2)
        $offset = $cmap.Offset + [int](Get-U32BE $Bytes ($recordOffset + 4))
        $format = Get-U16BE $Bytes $offset
        $priority = if ($format -eq 12 -and $platform -eq 3 -and $encoding -eq 10) { 0 } elseif ($format -eq 12 -and $platform -eq 0) { 1 } elseif ($format -eq 4 -and $platform -eq 3) { 2 } elseif ($format -eq 4 -and $platform -eq 0) { 3 } else { 99 }
        if ($priority -lt 99) { $candidates += [pscustomobject]@{ Priority = $priority; Format = $format; Offset = $offset } }
    }
    $selected = $candidates | Sort-Object Priority | Select-Object -First 1
    if ($null -eq $selected) { throw "Vector font has no supported Unicode cmap format" }
    return $selected
}

function Get-GlyphId([byte[]]$Bytes, [object]$Cmap, [int]$Codepoint) {
    if ($Cmap.Format -eq 12) {
        $groupCount = [int](Get-U32BE $Bytes ($Cmap.Offset + 12))
        for ($index = 0; $index -lt $groupCount; $index++) {
            $groupOffset = $Cmap.Offset + 16 + ($index * 12)
            $first = [int](Get-U32BE $Bytes $groupOffset)
            $last = [int](Get-U32BE $Bytes ($groupOffset + 4))
            if ($Codepoint -lt $first) { return 0 }
            if ($Codepoint -le $last) { return [int](Get-U32BE $Bytes ($groupOffset + 8)) + ($Codepoint - $first) }
        }
        return 0
    }

    $segmentCount = (Get-U16BE $Bytes ($Cmap.Offset + 6)) / 2
    $endCodesOffset = $Cmap.Offset + 14
    $startCodesOffset = $endCodesOffset + ($segmentCount * 2) + 2
    $deltasOffset = $startCodesOffset + ($segmentCount * 2)
    $rangeOffsetsOffset = $deltasOffset + ($segmentCount * 2)
    for ($index = 0; $index -lt $segmentCount; $index++) {
        $last = Get-U16BE $Bytes ($endCodesOffset + ($index * 2))
        if ($Codepoint -gt $last) { continue }
        $first = Get-U16BE $Bytes ($startCodesOffset + ($index * 2))
        if ($Codepoint -lt $first) { return 0 }
        $delta = Get-U16BE $Bytes ($deltasOffset + ($index * 2))
        $rangeOffsetAddress = $rangeOffsetsOffset + ($index * 2)
        $rangeOffset = Get-U16BE $Bytes $rangeOffsetAddress
        if ($rangeOffset -eq 0) { return ($Codepoint + $delta) -band 0xFFFF }
        $glyphAddress = $rangeOffsetAddress + $rangeOffset + (($Codepoint - $first) * 2)
        $glyph = Get-U16BE $Bytes $glyphAddress
        if ($glyph -eq 0) { return 0 }
        return ($glyph + $delta) -band 0xFFFF
    }
    return 0
}

function Get-TableChecksum([byte[]]$Bytes, [int]$Offset, [int]$Length) {
    [uint64]$sum = 0
    $paddedLength = ($Length + 3) -band -4
    for ($index = 0; $index -lt $paddedLength; $index += 4) {
        [uint32]$word = 0
        for ($part = 0; $part -lt 4; $part++) {
            $sourceIndex = $Offset + $index + $part
            $value = if ($index + $part -lt $Length) { [uint32]$Bytes[$sourceIndex] } else { [uint32]0 }
            $word = $word -bor ($value -shl (24 - ($part * 8)))
        }
        $sum = ($sum + $word) -band 0xFFFFFFFFL
    }
    return [uint32]$sum
}

$bytes = [IO.File]::ReadAllBytes((Resolve-Path -LiteralPath $VectorFontPath))
$tables = Get-TableDirectory $bytes
foreach ($requiredTable in @("cmap", "head", "hhea", "hmtx", "maxp")) {
    if (-not $tables.ContainsKey($requiredTable)) { throw "Vector font is missing $requiredTable" }
}
$unitsPerEm = Get-U16BE $bytes ($tables["head"].Offset + 18)
$glyphCount = Get-U16BE $bytes ($tables["maxp"].Offset + 4)
$metricCount = Get-U16BE $bytes ($tables["hhea"].Offset + 34)
if ($unitsPerEm -le 0 -or $metricCount -ne $glyphCount) { throw "Vector font must contain one horizontal metric per glyph" }

$classicLines = Get-Content -LiteralPath $ClassicBmFontPath
$info = $classicLines | Where-Object { $_ -like "info *" } | Select-Object -First 1
if ($info -notmatch '(?:^| )size=(\d+)') { throw "Classic BMFont has no source size" }
$classicSize = [int]$Matches[1]
$classicAdvances = @{}
foreach ($line in $classicLines) {
    if ($line -match '^char id=(\d+).* xadvance=(-?\d+) ') {
        $classicAdvances[[int]$Matches[1]] = [int]$Matches[2]
    }
}
if ($classicAdvances.Count -lt 100) { throw "Classic BMFont metric set is incomplete" }

$cmap = Get-CmapSubtable $bytes $tables
$updatedGlyphs = [Collections.Generic.HashSet[int]]::new()
$sampleRecords = [Collections.Generic.List[string]]::new()
foreach ($entry in $classicAdvances.GetEnumerator()) {
    $glyphId = Get-GlyphId $bytes $cmap ([int]$entry.Key)
    if ($glyphId -le 0 -or $glyphId -ge $glyphCount -or -not $updatedGlyphs.Add($glyphId)) { continue }
    $metricOffset = $tables["hmtx"].Offset + ($glyphId * 4)
    $oldAdvance = Get-U16BE $bytes $metricOffset
    $newAdvance = [Math]::Clamp([int][Math]::Round(([double]$entry.Value * $unitsPerEm) / $classicSize), 1, 65535)
    Set-U16BE $bytes $metricOffset ([uint16]$newAdvance)
    if ([int]$entry.Key -in @(32, 65, 73, 77, 87, 97, 105, 109, 119)) {
        $sampleRecords.Add("U+$(([int]$entry.Key).ToString('X4')):$oldAdvance->$newAdvance")
    }
}
if ($updatedGlyphs.Count -lt 100) { throw "Too few Samuel glyphs map to original Theldrow metrics: $($updatedGlyphs.Count)" }

param(
    [Parameter(Mandatory = $true)]
    [string]$CastleRepository
)

$ErrorActionPreference = "Stop"

function Get-U16([byte[]]$Bytes, [int]$Offset) {
    return ([int]$Bytes[$Offset] -shl 8) -bor [int]$Bytes[$Offset + 1]
}

function Get-I16([byte[]]$Bytes, [int]$Offset) {
    $value = Get-U16 $Bytes $Offset
    if ($value -ge 0x8000) {
        return $value - 0x10000
    }
    return $value
}

function Get-U32([byte[]]$Bytes, [int]$Offset) {
    return ([uint32]$Bytes[$Offset] -shl 24) -bor ([uint32]$Bytes[$Offset + 1] -shl 16) -bor ([uint32]$Bytes[$Offset + 2] -shl 8) -bor [uint32]$Bytes[$Offset + 3]
}

function Get-ResourceEntries([byte[]]$ForkBytes, [string]$ResourceType) {
    if ($ForkBytes.Length -lt 32) {
        throw "Resource fork is too short"
    }
    $dataOffset = [int](Get-U32 $ForkBytes 0)
    $mapOffset = [int](Get-U32 $ForkBytes 4)
    $typeListOffset = $mapOffset + (Get-U16 $ForkBytes ($mapOffset + 24))
    $rawTypeCount = Get-U16 $ForkBytes $typeListOffset
    if ($rawTypeCount -eq 0xffff) {
        return @()
    }
    $entries = @()
    for ($typeIndex = 0; $typeIndex -le $rawTypeCount; $typeIndex++) {
        $typeOffset = $typeListOffset + 2 + $typeIndex * 8
        $type = [Text.Encoding]::ASCII.GetString($ForkBytes, $typeOffset, 4)
        if ($type -ne $ResourceType) {
            continue
        }
        $rawResourceCount = Get-U16 $ForkBytes ($typeOffset + 4)
        $referenceListOffset = $typeListOffset + (Get-U16 $ForkBytes ($typeOffset + 6))
        for ($referenceIndex = 0; $referenceIndex -le $rawResourceCount; $referenceIndex++) {
            $referenceOffset = $referenceListOffset + $referenceIndex * 12
            $resourceId = Get-I16 $ForkBytes $referenceOffset
            $relativeOffset = ([int]$ForkBytes[$referenceOffset + 5] -shl 16) -bor ([int]$ForkBytes[$referenceOffset + 6] -shl 8) -bor [int]$ForkBytes[$referenceOffset + 7]
            $lengthOffset = $dataOffset + $relativeOffset
            $length = [int](Get-U32 $ForkBytes $lengthOffset)
            if ($lengthOffset + 4 + $length -gt $ForkBytes.Length) {
                throw "Resource $ResourceType $resourceId is truncated"
            }
            $resource = [byte[]]::new($length)
            [Array]::Copy($ForkBytes, $lengthOffset + 4, $resource, 0, $length)
            $entries += [pscustomobject]@{ Id = $resourceId; Bytes = $resource }
        }
    }
    return $entries
}

function Add-LittleEndian([Collections.Generic.List[byte]]$Output, [uint32]$Value, [int]$Width) {
    for ($index = 0; $index -lt $Width; $index++) {
        $Output.Add([byte](($Value -shr (8 * $index)) -band 0xff))
    }
}

function New-Wav([byte[]]$Samples, [uint32]$SampleRate) {
    $output = [Collections.Generic.List[byte]]::new()
    $paddedLength = $Samples.Length + ($Samples.Length -band 1)
    $output.AddRange([Text.Encoding]::ASCII.GetBytes("RIFF"))
    Add-LittleEndian $output ([uint32](36 + $paddedLength)) 4
    $output.AddRange([Text.Encoding]::ASCII.GetBytes("WAVEfmt "))
    Add-LittleEndian $output 16 4
    Add-LittleEndian $output 1 2
    Add-LittleEndian $output 1 2
    Add-LittleEndian $output $SampleRate 4
    Add-LittleEndian $output $SampleRate 4
    Add-LittleEndian $output 1 2
    Add-LittleEndian $output 8 2
    $output.AddRange([Text.Encoding]::ASCII.GetBytes("data"))
    Add-LittleEndian $output ([uint32]$Samples.Length) 4
    $output.AddRange($Samples)
    if (($Samples.Length -band 1) -ne 0) {
        $output.Add(0)
    }
    return ,$output.ToArray()
}

function Convert-SndToWav([byte[]]$Snd, [int]$ResourceId) {
    if ($Snd.Length -lt 2) {
        throw "snd $ResourceId is too short"
    }
    $format = Get-U16 $Snd 0
    $headerOffset = -1
    if ($format -eq 1) {
        if ($Snd.Length -lt 22) {
            throw "format-1 snd $ResourceId is truncated"
        }
        $commandCount = Get-U16 $Snd 10
        $cursor = 12
        for ($index = 0; $index -lt $commandCount; $index++) {
            if ($cursor + 8 -gt $Snd.Length) {
                break
            }
            $command = Get-U16 $Snd $cursor
            if (($command -band 0x7fff) -eq 0x51 -and ($command -band 0x8000) -ne 0) {
                $headerOffset = [int](Get-U32 $Snd ($cursor + 4))
                break
            }
            $cursor += 8
        }
    }
    elseif ($format -eq 2) {
        if ($Snd.Length -lt 36) {
            throw "format-2 snd $ResourceId is truncated"
        }
        $commandCount = Get-U16 $Snd 4
        $command = Get-U16 $Snd 6
        $commandKind = $command -band 0x7fff
        $commandParameter = [int](Get-U32 $Snd 10)
        if ($commandCount -gt 0 -and $commandKind -eq 0x50 -and ($command -band 0x8000) -ne 0 -and $commandParameter -ge 14) {
            $headerOffset = $commandParameter
        }
        elseif ($commandCount -gt 0 -and $commandKind -eq 0x51) {
            $headerOffset = 14
        }
    }
    else {
        throw "snd $ResourceId uses unsupported format $format"
    }
    if ($headerOffset -lt 0 -or $headerOffset + 22 -gt $Snd.Length) {
        throw "snd $ResourceId has no supported sampled-sound header"
    }
    $sampleLength = [int](Get-U32 $Snd ($headerOffset + 4))
    $sourceRate = [uint32]((Get-U32 $Snd ($headerOffset + 8)) -shr 16)
    if ($sourceRate -lt 1) {
        $sourceRate = 1
    }
    $sampleStart = $headerOffset + 22
    if ($sampleStart + $sampleLength -gt $Snd.Length) {
        throw "snd $ResourceId sample data is truncated"
    }
    $sourceSamples = [byte[]]::new($sampleLength)
    [Array]::Copy($Snd, $sampleStart, $sourceSamples, 0, $sampleLength)
    $playbackRate = $sourceRate
    $playbackSamples = $sourceSamples
    if ($sourceRate -lt 8000) {
        $playbackRate = 8000
        $outputLength = [Math]::Max(1, [int](($sourceSamples.Length * 8000L) / $sourceRate))
        $playbackSamples = [byte[]]::new($outputLength)
        for ($index = 0; $index -lt $outputLength; $index++) {
            $sourceIndex = [Math]::Min($sourceSamples.Length - 1, [int](($index * [long]$sourceRate) / 8000L))
            $playbackSamples[$index] = if ($sourceSamples.Length -gt 0) { $sourceSamples[$sourceIndex] } else { 128 }
        }
    }
    return [pscustomobject]@{
        Bytes = New-Wav $playbackSamples $playbackRate
        SourceRate = $sourceRate
        PlaybackRate = $playbackRate
        Samples = $sourceSamples.Length

                $stagedSidecar = Join-Path $sidecarRoot $relativePath
                New-Item -ItemType Directory -Path (Split-Path -Parent $stagedSidecar) -Force | Out-Null
                Copy-Item -LiteralPath $sidecar.FullName -Destination $stagedSidecar
            }
            Remove-Item -LiteralPath $destinationDirectory -Recurse -Force
        }
        $stagedDirectory = Join-Path $outputRoot $ownedDirectory
        if (Test-Path -LiteralPath $stagedDirectory) {
            Copy-Item -LiteralPath $stagedDirectory -Destination $destinationRoot -Recurse -Force
        }
    }
    foreach ($sidecar in Get-ChildItem -LiteralPath $sidecarRoot -Recurse -File -Filter "*.import") {
        $relativePath = [IO.Path]::GetRelativePath($sidecarRoot, $sidecar.FullName)
        $sourceAssetRelativePath = $relativePath.Substring(0, $relativePath.Length - ".import".Length)
        if (Test-Path -LiteralPath (Join-Path $destinationRoot $sourceAssetRelativePath) -PathType Leaf) {
            $destinationSidecar = Join-Path $destinationRoot $relativePath
            New-Item -ItemType Directory -Path (Split-Path -Parent $destinationSidecar) -Force | Out-Null
            Copy-Item -LiteralPath $sidecar.FullName -Destination $destinationSidecar
        }
    }
    Copy-Item -LiteralPath $stagedManifest -Destination $manifestPath -Force
    Write-Host "Imported $($records.Count) exact-commit Classic application media assets."
}
finally {
    if (Test-Path -LiteralPath $stagingRoot) {
        Remove-Item -LiteralPath $stagingRoot -Recurse -Force
    }
}

param(
    [Parameter(Mandatory = $true)]
    [string]$CastleRepository,
    [Parameter(Mandatory = $true)]
    [string]$OpenMpt123Path,
    [Parameter(Mandatory = $true)]
    [string]$FfmpegPath
)

$ErrorActionPreference = "Stop"

function Get-SafeSlug([string]$Value) {
    return ($Value.ToLowerInvariant() -replace '[^a-z0-9]+', '-').Trim('-')
}

function Invoke-Checked([string]$Program, [string[]]$Arguments, [string]$Failure) {
    & $Program @Arguments
    if ($LASTEXITCODE -ne 0) {
        throw "$Failure (exit $LASTEXITCODE)"
    }
}

$toolRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
$repoRoot = Split-Path -Parent (Split-Path -Parent $toolRoot)
$catalogPath = Join-Path $toolRoot "application-music-catalog.json"
$catalog = Get-Content -Raw -LiteralPath $catalogPath | ConvertFrom-Json
$castleRoot = (Resolve-Path -LiteralPath $CastleRepository).Path
$openMpt = (Resolve-Path -LiteralPath $OpenMpt123Path).Path
$ffmpeg = (Resolve-Path -LiteralPath $FfmpegPath).Path

foreach ($commit in @($catalog.tracks | ForEach-Object { $_.source_commit } | Sort-Object -Unique)) {
    $resolved = (& git -C $castleRoot rev-parse "$commit^{commit}").Trim()
    if ($LASTEXITCODE -ne 0 -or $resolved -ne $commit) {
        throw "The requested Castle music source commit is unavailable: $commit"
    }
}

$openMptVersion = (& $openMpt --version 2>&1 | Out-String)
if ($LASTEXITCODE -ne 0 -or $openMptVersion -notmatch [regex]::Escape([string]$catalog.decoder.version)) {
    throw "openmpt123 $($catalog.decoder.version) is required"
}
$ffmpegVersion = (& $ffmpeg -version 2>&1 | Select-Object -First 1 | Out-String)
if ($LASTEXITCODE -ne 0 -or $ffmpegVersion -notmatch [regex]::Escape([string]$catalog.encoder.version)) {
    throw "FFmpeg $($catalog.encoder.version) is required"
}

$stagingRoot = Join-Path ([IO.Path]::GetTempPath()) ("realmz-application-music-" + [Guid]::NewGuid().ToString("N"))
$sourceRoot = Join-Path $stagingRoot "source"
$outputRoot = Join-Path $stagingRoot "output"
New-Item -ItemType Directory -Path $sourceRoot, $outputRoot | Out-Null

try {
    $records = @()
    foreach ($track in @($catalog.tracks | Sort-Object playlist_id)) {
    $playlistId = [int]$track.playlist_id
    $slug = Get-SafeSlug ([string]$track.context)
    $archivePath = Join-Path $stagingRoot ("source-{0:D2}.zip" -f $playlistId)
    $extractRoot = Join-Path $sourceRoot ("{0:D2}" -f $playlistId)
    $sourcePath = "base/Realmz/Realmz Music/$($track.filename)"
    Invoke-Checked "git" @("-C", $castleRoot, "archive", "--format=zip", "--output=$archivePath", [string]$track.source_commit, "--", $sourcePath) "Castle music archive failed for playlist $playlistId"
    Expand-Archive -LiteralPath $archivePath -DestinationPath $extractRoot
    $modulePath = Join-Path $extractRoot ($sourcePath -replace '/', [IO.Path]::DirectorySeparatorChar)
    $sourceHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $modulePath).Hash.ToLowerInvariant()
    $sourceBytes = (Get-Item -LiteralPath $modulePath).Length
    if ($sourceHash -ne [string]$track.source_sha256 -or $sourceBytes -ne [long]$track.source_bytes) {
        throw "Catalog source mismatch for playlist $playlistId"
    }

    $wavPath = Join-Path $stagingRoot ("playlist-{0:D2}.wav" -f $playlistId)
    $fileName = "playlist-{0:D2}-{1}.ogg" -f $playlistId, $slug
    $oggPath = Join-Path $outputRoot $fileName
    Invoke-Checked $openMpt @("--batch", "--quiet", "--samplerate", [string]$catalog.decoder.sample_rate, "--channels", [string]$catalog.decoder.channels, "--float", "--force", "--output", $wavPath, "--", $modulePath) "OpenMPT render failed for playlist $playlistId"
    Invoke-Checked $ffmpeg @("-hide_banner", "-loglevel", "error", "-y", "-i", $wavPath, "-map_metadata", "-1", "-c:a", "libvorbis", "-q:a", [string]$catalog.encoder.quality, $oggPath) "Vorbis encode failed for playlist $playlistId"
    $oggBytes = [IO.File]::ReadAllBytes($oggPath)
    if ($oggBytes.Length -lt 4 -or [Text.Encoding]::ASCII.GetString($oggBytes, 0, 4) -ne "OggS") {
        throw "Generated music is not an Ogg stream for playlist $playlistId"
    }
    $records += [ordered]@{
        playlist_id = $playlistId
        context = [string]$track.context
        title = [string]$track.title
        path = "res://src/presentation/assets/classic-media/music/$fileName"
        mime_type = "audio/ogg"
        bytes = $oggBytes.Length
        sha256 = (Get-FileHash -Algorithm SHA256 -LiteralPath $oggPath).Hash.ToLowerInvariant()
        duration_ms = [int]$track.duration_ms
        source_repository = [string]$catalog.source_repository
        source_commit = [string]$track.source_commit
        source_path = $sourcePath
        source_bytes = $sourceBytes
        source_sha256 = $sourceHash
        classification = "classic-application-music"
    }
    if ($null -ne $track.legacy_source_commit) {
        $records[-1]["legacy_source_commit"] = [string]$track.legacy_source_commit
        $records[-1]["legacy_source_sha256"] = [string]$track.legacy_source_sha256
        $records[-1]["replacement_reason"] = "Pinned Castle Outdoor Music is a legacy MADG module unsupported by OpenMPT; the exact later Castle MOD replacement preserves the stock title."
    }
    }

    $manifest = [ordered]@{
    schema_version = 1
    ownership = "classic-application"
    slot_count = 20
    lookup = "playlist-id"
    decoder = $catalog.decoder
    encoder = $catalog.encoder
    tracks = $records
    }
    $manifestJson = $manifest | ConvertTo-Json -Depth 12
    $stagedManifest = Join-Path $stagingRoot "classic-application-music.json"
    Set-Content -LiteralPath $stagedManifest -Value $manifestJson -Encoding utf8

    $destinationRoot = Join-Path $repoRoot "src/presentation/assets/classic-media/music"
    $manifestPath = Join-Path $repoRoot "src/presentation/assets/classic-application-music.json"
    New-Item -ItemType Directory -Path $destinationRoot -Force | Out-Null
    foreach ($existing in @(Get-ChildItem -LiteralPath $destinationRoot -File -Filter "playlist-*.ogg")) {
        if ($existing.Name -notin @($records | ForEach-Object { [IO.Path]::GetFileName([string]$_.path) })) {
            Remove-Item -LiteralPath $existing.FullName -Force
        }
    }
    Copy-Item -Path (Join-Path $outputRoot "*.ogg") -Destination $destinationRoot -Force
    Copy-Item -LiteralPath $stagedManifest -Destination $manifestPath -Force
    Write-Host "Generated $($records.Count) Classic application music tracks through OpenMPT."
}
finally {
    $expectedPrefix = Join-Path ([IO.Path]::GetTempPath()) "realmz-application-music-"
    if ($stagingRoot.StartsWith($expectedPrefix, [StringComparison]::OrdinalIgnoreCase) -and (Test-Path -LiteralPath $stagingRoot -PathType Container)) {
        Remove-Item -LiteralPath $stagingRoot -Recurse -Force
    }
}

param(
    [Parameter(Mandatory = $true)]
    [string]$CastleRepository
)

$ErrorActionPreference = "Stop"
$sourceCommit = "491816ad60037394f92c428e99c004494d3c28b3"
$sourcePath = "base/Realmz/Data Files/The Family Jewels.rsrc"
$sourceSha256 = "8dbae6c6a418c82250dca93937c5958dacea9874d654c62da4e4dafa184dc85c"
$destination = Join-Path (Split-Path -Parent (Split-Path -Parent $PSScriptRoot)) "src/infrastructure/packages/classic-application-spell-descriptions.json"

function Get-U16([byte[]]$Bytes, [int]$Offset) {
    return ([int]$Bytes[$Offset] -shl 8) -bor [int]$Bytes[$Offset + 1]
}

function Get-I16([byte[]]$Bytes, [int]$Offset) {
    $value = Get-U16 $Bytes $Offset
    if ($value -ge 0x8000) {
        return $value - 0x10000
    }
    return $value
}

function Get-U32([byte[]]$Bytes, [int]$Offset) {
    return ([uint32]$Bytes[$Offset] -shl 24) -bor ([uint32]$Bytes[$Offset + 1] -shl 16) -bor ([uint32]$Bytes[$Offset + 2] -shl 8) -bor [uint32]$Bytes[$Offset + 3]
}

function Get-MacRomanEncoding {
    try {
        return [Text.Encoding]::GetEncoding(10000)
    }
    catch {
        [void][Reflection.Assembly]::Load("System.Text.Encoding.CodePages")
        $providerType = [Type]::GetType("System.Text.CodePagesEncodingProvider, System.Text.Encoding.CodePages", $true)
        $provider = $providerType.GetProperty("Instance", [Reflection.BindingFlags]"Public,Static").GetValue($null)
        $register = [Text.Encoding].GetMethod("RegisterProvider", [Reflection.BindingFlags]"Public,Static")
        [void]$register.Invoke($null, @($provider))
        return [Text.Encoding]::GetEncoding(10000)
    }
}

function ConvertTo-JsonString([string]$Value) {
    $builder = [Text.StringBuilder]::new($Value.Length + 2)
    [void]$builder.Append('"')
    foreach ($character in $Value.ToCharArray()) {
        switch ([int]$character) {
            8 { [void]$builder.Append('\b'); continue }
            9 { [void]$builder.Append('\t'); continue }
            10 { [void]$builder.Append('\n'); continue }
            12 { [void]$builder.Append('\f'); continue }
            13 { [void]$builder.Append('\r'); continue }
            34 { [void]$builder.Append('\"'); continue }
            92 { [void]$builder.Append('\\'); continue }
        }
        if ([int]$character -lt 32) {
            [void]$builder.AppendFormat('\u{0:x4}', [int]$character)
        }
        else {
            [void]$builder.Append($character)
        }
    }
    [void]$builder.Append('"')
    return $builder.ToString()
}

function Get-StringLists([byte[]]$ForkBytes) {
    $macRoman = Get-MacRomanEncoding
    $dataOffset = [int](Get-U32 $ForkBytes 0)
    $mapOffset = [int](Get-U32 $ForkBytes 4)
    $typeListOffset = $mapOffset + (Get-U16 $ForkBytes ($mapOffset + 24))
    $rawTypeCount = Get-U16 $ForkBytes $typeListOffset
    $result = @{}
    for ($typeIndex = 0; $typeIndex -le $rawTypeCount; $typeIndex++) {
        $typeOffset = $typeListOffset + 2 + $typeIndex * 8
        if ([Text.Encoding]::ASCII.GetString($ForkBytes, $typeOffset, 4) -ne "STR#") { continue }
        $rawResourceCount = Get-U16 $ForkBytes ($typeOffset + 4)
        $referenceListOffset = $typeListOffset + (Get-U16 $ForkBytes ($typeOffset + 6))
        for ($referenceIndex = 0; $referenceIndex -le $rawResourceCount; $referenceIndex++) {
            $referenceOffset = $referenceListOffset + $referenceIndex * 12
            $resourceId = Get-I16 $ForkBytes $referenceOffset
            if ($resourceId -gt -1000 -or $resourceId -lt -3006) { continue }
            $absoluteId = [Math]::Abs($resourceId)
            $class = [Math]::Floor($absoluteId / 1000)
            $levelIndex = $absoluteId % 1000
            if ($class -lt 1 -or $class -gt 3 -or $levelIndex -lt 0 -or $levelIndex -gt 6) { continue }
            $relativeOffset = ([int]$ForkBytes[$referenceOffset + 5] -shl 16) -bor ([int]$ForkBytes[$referenceOffset + 6] -shl 8) -bor [int]$ForkBytes[$referenceOffset + 7]
            $lengthOffset = $dataOffset + $relativeOffset
            $length = [int](Get-U32 $ForkBytes $lengthOffset)
            $cursor = $lengthOffset + 4
            $limit = $cursor + $length
            $count = Get-U16 $ForkBytes $cursor
            $cursor += 2
            if ($count -lt 1 -or $count -gt 15) { throw "Classic spell description STR# $resourceId contains an invalid $count entries." }
            for ($slot = 0; $slot -lt $count; $slot++) {
                if ($cursor -ge $limit) { throw "Classic spell description STR# $resourceId is truncated." }
                $textLength = [int]$ForkBytes[$cursor]
                $cursor += 1
                if ($cursor + $textLength -gt $limit) { throw "Classic spell description STR# $resourceId is truncated." }
                $classicId = $class * 1000 + ($levelIndex + 1) * 100 + $slot + 1
                $result[[string]$classicId] = $macRoman.GetString($ForkBytes, $cursor, $textLength)
                $cursor += $textLength
            }
        }
    }
    return $result
}

$castleRoot = (Resolve-Path -LiteralPath $CastleRepository).Path
$resolvedCommit = (& git -C $castleRoot rev-parse "HEAD^{commit}").Trim()
if ($LASTEXITCODE -ne 0 -or $resolvedCommit -ne $sourceCommit) { throw "Castle reference must be pinned at $sourceCommit." }
$resolvedSource = Join-Path $castleRoot $sourcePath
$actualSha256 = (Get-FileHash -Algorithm SHA256 -LiteralPath $resolvedSource).Hash.ToLowerInvariant()
if ($actualSha256 -ne $sourceSha256) { throw "The Family Jewels resource hash does not match the pinned application library." }
$descriptions = Get-StringLists ([IO.File]::ReadAllBytes($resolvedSource))
if ($descriptions.Count -ne 252) { throw "Expected 252 stock player-spell descriptions; found $($descriptions.Count)." }
$json = [Text.StringBuilder]::new()
[void]$json.Append('{"schemaVersion":1,"sourceCommit":')
[void]$json.Append((ConvertTo-JsonString $sourceCommit))
[void]$json.Append(',"sourcePath":')
[void]$json.Append((ConvertTo-JsonString $sourcePath))
[void]$json.Append(',"sourceFileSha256":')
[void]$json.Append((ConvertTo-JsonString $sourceSha256))
[void]$json.Append(',"descriptions":{')
$first = $true
foreach ($key in ($descriptions.Keys | Sort-Object {[int]$_})) {
    if (-not $first) { [void]$json.Append(',') }
    $first = $false
    [void]$json.Append((ConvertTo-JsonString $key))
    [void]$json.Append(':')
    [void]$json.Append((ConvertTo-JsonString $descriptions[$key]))
}
[void]$json.Append("}}`n")
[IO.File]::WriteAllText($destination, $json.ToString(), [Text.UTF8Encoding]::new($false))
Write-Output "Wrote $($descriptions.Count) Classic application spell descriptions to $destination"

param(
    [Parameter(Mandatory = $true)]
    [string]$SourceRepository,
    [string]$CastleRepository = "",
    [string]$UiDonorRepository = "",
    [string]$PictDecoderPath = ""
)

$ErrorActionPreference = "Stop"
$toolRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
$repoRoot = Split-Path -Parent (Split-Path -Parent $toolRoot)
$catalogPath = Join-Path $toolRoot "catalog.json"
$catalog = Get-Content -Raw -LiteralPath $catalogPath | ConvertFrom-Json
$sourceRoot = (Resolve-Path -LiteralPath $SourceRepository).Path
$classicEntries = @($catalog.assets | Where-Object { $_.source_kind -in @("classic-cicn", "classic-pict") })
$classicPictEntries = @($classicEntries | Where-Object { $_.source_kind -eq "classic-pict" })
$uiDonorEntries = @($catalog.assets | Where-Object { $_.source_kind -eq "licensed-ui-donor" })
$castleRoot = ""
$uiDonorRoot = ""
$destinationRoot = Join-Path $repoRoot "src/presentation/assets/classic-controls"
$manifestPath = Join-Path $repoRoot "src/presentation/assets/classic-ui-assets.json"
$cicnExporterPath = Join-Path $toolRoot "export-classic-cicn.ps1"
$pictExporterPath = Join-Path $toolRoot "export-classic-pict.ps1"

$resolvedCommit = (& git -C $sourceRoot rev-parse "$($catalog.source_commit)^{commit}").Trim()
if ($LASTEXITCODE -ne 0 -or $resolvedCommit -ne $catalog.source_commit) {
    throw "The requested Remake source commit is unavailable: $($catalog.source_commit)"
}
if ($classicEntries.Count -gt 0) {
    if (-not $CastleRepository) {
        throw "CastleRepository is required for cataloged Classic resource-fork assets"
    }
    $castleRoot = (Resolve-Path -LiteralPath $CastleRepository).Path
    $castleCommits = @($classicEntries | ForEach-Object { $_.source_commit } | Sort-Object -Unique)
    if ($castleCommits.Count -ne 1) {
        throw "Classic resource-fork assets must share one Castle source commit"
    }
    $resolvedCastleCommit = (& git -C $castleRoot rev-parse "$($castleCommits[0])^{commit}").Trim()
    if ($LASTEXITCODE -ne 0 -or $resolvedCastleCommit -ne $castleCommits[0]) {
        throw "The requested Castle source commit is unavailable: $($castleCommits[0])"
    }
    if ($classicPictEntries.Count -gt 0 -and -not $PictDecoderPath) {
        throw "PictDecoderPath is required for cataloged Classic PICT assets"
    }
}
if ($uiDonorEntries.Count -gt 0) {
    if (-not $UiDonorRepository) {
        throw "UiDonorRepository is required for cataloged licensed UI donor assets"
    }
    $uiDonorRoot = (Resolve-Path -LiteralPath $UiDonorRepository).Path
    $uiDonorCommits = @($uiDonorEntries | ForEach-Object { $_.source_commit } | Sort-Object -Unique)
    foreach ($uiDonorCommit in $uiDonorCommits) {
        $resolvedUiDonorCommit = (& git -C $uiDonorRoot rev-parse "$uiDonorCommit`^{commit}").Trim()
        if ($LASTEXITCODE -ne 0 -or $resolvedUiDonorCommit -ne $uiDonorCommit) {
            throw "The requested licensed UI donor commit is unavailable: $uiDonorCommit"
        }
    }
}

$stagingRoot = Join-Path ([IO.Path]::GetTempPath()) ("realmz2-ui-assets-" + [Guid]::NewGuid().ToString("N"))
$archivePath = Join-Path $stagingRoot "source.zip"
$extractRoot = Join-Path $stagingRoot "source"
$castleArchivePath = Join-Path $stagingRoot "castle-source.zip"
$castleExtractRoot = Join-Path $stagingRoot "castle-source"
$uiDonorExtractRoot = Join-Path $stagingRoot "ui-donor-source"
$outputRoot = Join-Path $stagingRoot "output"
$sidecarRoot = Join-Path $stagingRoot "sidecars"
New-Item -ItemType Directory -Path $extractRoot, $castleExtractRoot, $uiDonorExtractRoot, $outputRoot, $sidecarRoot | Out-Null

try {
    $sourcePaths = @($catalog.assets | Where-Object { $_.source_kind -notin @("classic-cicn", "classic-pict", "licensed-ui-donor") } | ForEach-Object { $_.source_path } | Sort-Object -Unique)
    & git -C $sourceRoot archive --format=zip --output=$archivePath $catalog.source_commit -- @sourcePaths
    if ($LASTEXITCODE -ne 0) {
        throw "git archive failed"
    }
    Expand-Archive -LiteralPath $archivePath -DestinationPath $extractRoot
    if ($classicEntries.Count -gt 0) {
        $castleSourcePaths = @($classicEntries | ForEach-Object { $_.source_path } | Sort-Object -Unique)
        $castleCommit = $classicEntries[0].source_commit
        & git -C $castleRoot archive --format=zip --output=$castleArchivePath $castleCommit -- @castleSourcePaths
        if ($LASTEXITCODE -ne 0) {
            throw "Castle git archive failed"
        }
        Expand-Archive -LiteralPath $castleArchivePath -DestinationPath $castleExtractRoot
    }
    foreach ($uiDonorCommit in @($uiDonorEntries | ForEach-Object { $_.source_commit } | Sort-Object -Unique)) {
        $commitRoot = Join-Path $uiDonorExtractRoot $uiDonorCommit
        $commitArchivePath = Join-Path $stagingRoot ("ui-donor-" + $uiDonorCommit + ".zip")
        $uiDonorPaths = @($uiDonorEntries | Where-Object { $_.source_commit -eq $uiDonorCommit } | ForEach-Object { $_.source_path } | Sort-Object -Unique)
        & git -C $uiDonorRoot archive --format=zip --output=$commitArchivePath $uiDonorCommit -- @uiDonorPaths
        if ($LASTEXITCODE -ne 0) {
            throw "Licensed UI donor git archive failed"
        }
        New-Item -ItemType Directory -Path $commitRoot | Out-Null
        Expand-Archive -LiteralPath $commitArchivePath -DestinationPath $commitRoot
    }

    $records = @()
    foreach ($entry in $catalog.assets) {
        $isClassicCicn = $entry.source_kind -eq "classic-cicn"
        $isClassicPict = $entry.source_kind -eq "classic-pict"
        $isLicensedUiDonor = $entry.source_kind -eq "licensed-ui-donor"
        $entryExtractRoot = if ($isClassicCicn -or $isClassicPict) {
            $castleExtractRoot
        }
        elseif ($isLicensedUiDonor) {
            Join-Path $uiDonorExtractRoot $entry.source_commit
        }
        else {
            $extractRoot
        }
        $sourcePath = Join-Path $entryExtractRoot ($entry.source_path -replace "/", [IO.Path]::DirectorySeparatorChar)
        if (-not (Test-Path -LiteralPath $sourcePath -PathType Leaf)) {
            throw "Catalog source is missing from the recorded commit: $($entry.source_path)"
        }
        if ($entry.PSObject.Properties.Name -contains "source_file_sha256") {
            $sourceSha256 = (Get-FileHash -Algorithm SHA256 -LiteralPath $sourcePath).Hash.ToLowerInvariant()
            if ($sourceSha256 -ne $entry.source_file_sha256) {
                throw "Catalog source hash mismatch: $($entry.source_path)"
            }
        }
        $targetPath = Join-Path $outputRoot ($entry.target_path -replace "/", [IO.Path]::DirectorySeparatorChar)
        New-Item -ItemType Directory -Path (Split-Path -Parent $targetPath) -Force | Out-Null
        if ($isClassicCicn) {
            & $cicnExporterPath -ResourceForkPath $sourcePath -ResourceId $entry.resource_id -OutputPath $targetPath
        }
        elseif ($isClassicPict) {
            & $pictExporterPath -ResourceForkPath $sourcePath -ResourceId $entry.resource_id -PictDecoderPath $PictDecoderPath -OutputPath $targetPath
        }
        else {
            [IO.File]::WriteAllBytes($targetPath, [IO.File]::ReadAllBytes($sourcePath))
        }
        $bytes = [IO.File]::ReadAllBytes($targetPath)
        if ($bytes.Length -lt 24 -or [Text.Encoding]::ASCII.GetString($bytes, 1, 3) -ne "PNG") {
            throw "Only validated PNG controls may be imported: $($entry.source_path)"
        }
        $width = [Net.IPAddress]::NetworkToHostOrder([BitConverter]::ToInt32($bytes, 16))
        $height = [Net.IPAddress]::NetworkToHostOrder([BitConverter]::ToInt32($bytes, 20))
        if ($width -le 0 -or $height -le 0) {
            throw "Invalid PNG dimensions: $($entry.source_path)"
        }
        $sha256 = (Get-FileHash -Algorithm SHA256 -LiteralPath $targetPath).Hash.ToLowerInvariant()
        if ($entry.PSObject.Properties.Name -contains "sha256" -and $sha256 -ne $entry.sha256) {
            throw "Catalog output hash mismatch: $($entry.target_path)"
        }
        $classification = if ($entry.PSObject.Properties.Name -contains "classification") { $entry.classification } else { "tracked-remake-bitmap" }
        $evidenceStatus = if ($entry.PSObject.Properties.Name -contains "evidence_status") { $entry.evidence_status } else { "remake-scene-use" }
        $evidenceNote = if ($entry.PSObject.Properties.Name -contains "evidence_note") { $entry.evidence_note } else { "Semantic use is proven by the tracked Remake scene; direct extraction from a Classic resource fork is not claimed." }
        $evidence = [ordered]@{
            status = $evidenceStatus
            path = if ($entry.PSObject.Properties.Name -contains "evidence_path") { $entry.evidence_path } else { $catalog.contexts.($entry.context) }
            note = $evidenceNote
        }
        if ($entry.PSObject.Properties.Name -contains "evidence_repository") {
            $evidence["repository"] = $entry.evidence_repository
        }
        if ($entry.PSObject.Properties.Name -contains "evidence_commit") {
            $evidence["commit"] = $entry.evidence_commit
        }
        $record = [ordered]@{

            id = $entry.id
            path = "res://src/presentation/assets/classic-controls/$($entry.target_path)"
            source_repository = if ($entry.PSObject.Properties.Name -contains "source_repository") { $entry.source_repository } else { $catalog.source_repository }
            source_commit = if ($entry.PSObject.Properties.Name -contains "source_commit") { $entry.source_commit } else { $catalog.source_commit }
            source_path = $entry.source_path
            native_width = $width
            native_height = $height
            sha256 = $sha256
            classification = $classification
            classic_evidence = $evidence
            rendering = [ordered]@{
                filter = "nearest"
                allowed_scales = @(1, 2)
                source_pixels_modified = $false
            }
        }
        if ($isClassicCicn -or $isClassicPict) {
            $record["source_file_sha256"] = $entry.source_file_sha256
            $record["source_resource_type"] = $entry.resource_type
            $record["source_resource_id"] = $entry.resource_id
        }
        if ($entry.PSObject.Properties.Name -contains "license") {
            $record["license"] = $entry.license
        }
        if ($entry.PSObject.Properties.Name -contains "license_note") {
            $record["license_note"] = $entry.license_note
        }
        $records += $record
    }

    $manifest = [ordered]@{
        schema_version = 1
        source_repository = $catalog.source_repository
        source_commit = $catalog.source_commit
        generated_by = "tools/ui-assets/sync-classic-ui-assets.ps1"
        assets = $records
    }
    $manifestText = ($manifest | ConvertTo-Json -Depth 8) + [Environment]::NewLine
    $stagedManifest = Join-Path $stagingRoot "classic-ui-assets.json"
    [IO.File]::WriteAllText($stagedManifest, $manifestText, [Text.UTF8Encoding]::new($false))
    $parsed = Get-Content -Raw -LiteralPath $stagedManifest | ConvertFrom-Json
    if ($parsed.assets.Count -ne $catalog.assets.Count) {
        throw "Generated asset manifest failed validation"
    }

    if (Test-Path -LiteralPath $destinationRoot) {
        foreach ($sidecar in Get-ChildItem -LiteralPath $destinationRoot -Recurse -File -Filter "*.import") {
            $relativePath = [IO.Path]::GetRelativePath($destinationRoot, $sidecar.FullName)
            $stagedSidecar = Join-Path $sidecarRoot $relativePath
            New-Item -ItemType Directory -Path (Split-Path -Parent $stagedSidecar) -Force | Out-Null
            Copy-Item -LiteralPath $sidecar.FullName -Destination $stagedSidecar
        }
        Remove-Item -LiteralPath $destinationRoot -Recurse -Force
    }
    New-Item -ItemType Directory -Path $destinationRoot | Out-Null
    Copy-Item -Path (Join-Path $outputRoot "*") -Destination $destinationRoot -Recurse -Force
    foreach ($sidecar in Get-ChildItem -LiteralPath $sidecarRoot -Recurse -File -Filter "*.import") {
        $relativePath = [IO.Path]::GetRelativePath($sidecarRoot, $sidecar.FullName)
        $sourceAssetRelativePath = $relativePath.Substring(0, $relativePath.Length - ".import".Length)
        if (-not (Test-Path -LiteralPath (Join-Path $destinationRoot $sourceAssetRelativePath) -PathType Leaf)) {
            continue
        }
        $destinationSidecar = Join-Path $destinationRoot $relativePath
        New-Item -ItemType Directory -Path (Split-Path -Parent $destinationSidecar) -Force | Out-Null
        Copy-Item -LiteralPath $sidecar.FullName -Destination $destinationSidecar
    }
    Copy-Item -LiteralPath $stagedManifest -Destination $manifestPath -Force
    Write-Host "Imported $($records.Count) exact-commit Classic UI assets."
}
finally {
    if (Test-Path -LiteralPath $stagingRoot) {
        Remove-Item -LiteralPath $stagingRoot -Recurse -Force
    }
}

    finally {
        $env:PYTHONPATH = $previousPythonPath
    }
    $actualModernizedHash = (Get-FileHash -Algorithm SHA256 -LiteralPath (Join-Path $stagingRoot "Theldrow-Rebuilt.ttf")).Hash.ToLowerInvariant()
    if ($actualModernizedHash -ne $modernizedFontSha256) {
        throw "Modernized Theldrow output hash does not match: $actualModernizedHash"
    }
    Remove-Item -LiteralPath $pythonDependencyRoot -Recurse -Force

    $remakeLicenseRoot = Join-Path $stagingRoot "remake-license"
    Expand-Archive -LiteralPath $remakeLicenseArchivePath -DestinationPath $remakeLicenseRoot
    Copy-Item -LiteralPath (Join-Path $remakeLicenseRoot "license.txt") -Destination (Join-Path $stagingRoot "licenses/Theldrow-CC0-LICENSE.txt")
    Copy-Item -LiteralPath (Join-Path $remakeLicenseRoot "readme.txt") -Destination (Join-Path $stagingRoot "licenses/Theldrow-CC0-README.txt")
    Remove-Item -LiteralPath (Join-Path $stagingRoot "source") -Recurse -Force
    Remove-Item -LiteralPath $remakeArchivePath, $remakeExtractRoot, $remakeLicenseRoot -Recurse -Force

    foreach ($notice in @("BlackChancery-PUBLIC-DOMAIN.txt", "ChicagoFLF-PUBLIC-DOMAIN.txt", "Theldrow-REALMZ-NONCOMMERCIAL.txt")) {
        $source = Join-Path $destinationRoot "licenses/$notice"
        if (-not (Test-Path -LiteralPath $source -PathType Leaf)) { throw "Committed font notice is missing: $notice" }
        Copy-Item -LiteralPath $source -Destination (Join-Path $stagingRoot "licenses/$notice")
    }

    $manifestRecords = @()
    foreach ($definition in $records) {
        $target = Join-Path $stagingRoot ($definition.Target -replace "/", [IO.Path]::DirectorySeparatorChar)
        if (-not (Test-Path -LiteralPath $target -PathType Leaf)) { throw "Staged font asset is missing: $($definition.Target)" }
        $record = [ordered]@{
            id = $definition.Id
            path = "res://src/presentation/assets/fonts/$($definition.Target)"
            source_repository = $definition.Repository
            source_commit = $definition.Commit
