2, PresentationSettings.MUSIC_PLAY); presenter.present_music_context(12, settings, null, catalog); assert_equal([presenter.current_music_playlist_id, presenter.current_music_title], [12, "After the Rain"], "Desert retains its distinct preference context while reusing Outdoor music"); settings.set_music_mode(2, PresentationSettings.MUSIC_CONTINUE); presenter.present_music_context(2, settings, null, catalog); assert_equal([presenter.current_music_playlist_id, presenter.current_music_title], [12, "After the Rain"], "Continue retains the current title across contexts"); settings.set_music_mode(2, PresentationSettings.MUSIC_OFF); presenter.present_music_context(2, settings, null, catalog); assert_equal(presenter.current_music_playlist_id, 0, "Off stops the prior context title on entry"); presenter.free(); var dialog := MusicPlaylistDialog.new(); (Engine.get_main_loop() as SceneTree).root.add_child(dialog); dialog.call("_ready"); settings = PresentationSettings.new(); dialog.open(settings, 1, "After the Rain", true); assert_true(dialog.visible and dialog.find_child("MusicDone", true, false) != null and dialog.find_children("Playlist??", "HBoxContainer", true, false).size() == 20, "the locked window exposes all twenty slots and a contiguous Done action"); assert_true((dialog.find_child("Playlist18Play", true, false) as Button).disabled and (dialog.find_child("Playlist20Off", true, false) as Button).disabled, "unused slots remain visible and reserved"); (dialog.find_child("Playlist11Continue", true, false) as Button).pressed.emit(); assert_equal(settings.music_mode(11), PresentationSettings.MUSIC_CONTINUE, "playlist controls update the selected context mode"); dialog.set_anchors_and_offsets_preset(Control.PRESET_TOP_LEFT); dialog.size = Vector2(1280, 720); dialog.call("_apply_layout"); var panel := dialog.find_child("MusicPlaylistWindow", true, false) as PanelContainer; assert_true(panel.custom_minimum_size.x <= 1232.0 and panel.custom_minimum_size.y <= 680.0, "the playlist