class_name PackageScenarioDecoder
extends PackageDecoderBase

const SUPPORTED_SAFE_CAPABILITIES: Array[String] = RealmzRuntimeApi.SUPPORTED_SAFE_CAPABILITIES
const SUPPORTED_ACTION_CONTEXTS: Array[String] = ["action", "encounter", "spell", "item", "monster-ai", "lifecycle", "rule-modifier"]
const SUPPORTED_VALUE_TYPES: Array[String] = ["void", "bool", "int", "float", "string", "location-snapshot", "time-snapshot", "wealth-snapshot", "character-snapshot", "character-snapshot-array", "combat-snapshot", "action-outcome", "encounter-outcome", "effect-outcome", "spell-validation-outcome", "spell-cast-outcome", "spell-effect-outcome", "spell-tick-outcome", "spell-expiration-outcome", "item-outcome", "monster-decision", "rule-modifier", "bool-array", "int-array", "float-array", "string-array"]

func _construct_scenario(document: Dictionary, campaign_id: String) -> ScenarioDefinition:
	var reference_validator := PackageCrossReferenceValidator.new(_diagnostic)
	if not _has_fields(document, ["applicationHooks", "programs", "scenarioActions", "stateDefinitions", "migrations"], "scenario document"):
		return null
	if not document["stateDefinitions"] is Array or document["stateDefinitions"].size() > 4096 or not document["migrations"] is Array or document["migrations"].size() > 4096 or not _json_safe(document["stateDefinitions"], 0) or not _json_safe(document["migrations"], 0):
		_reject("Scenario state definitions or migrations are malformed.")
		return null
	var programs_value: Variant = _construct_programs(document["programs"])
	var actions_value: Variant = _construct_scenario_actions(document["scenarioActions"], campaign_id)
	var hooks_value: Variant = _construct_application_hooks(document["applicationHooks"])
	if programs_value == null or actions_value == null or hooks_value == null:
		return null
	var programs: Array[ScenarioProgramDefinition] = programs_value
	var actions: Array[ScenarioActionDefinition] = actions_value
	var hooks: ScenarioApplicationHooks = hooks_value
	var definition := ScenarioDefinition.new(programs, actions, hooks)
	for hook: StringName in [ScenarioApplicationHooks.START_GAME, ScenarioApplicationHooks.PARTY_DEATH, ScenarioApplicationHooks.END_ADVENTURE, ScenarioApplicationHooks.SHOP, ScenarioApplicationHooks.TEMPLE]:
		var hook_program_id := definition.application_hook_program_id(hook)
		if not hook_program_id.is_empty() and definition.program_by_id(hook_program_id) == null:
			_reject("Scenario application hook '%s' references missing program '%s'." % [hook, hook_program_id])
			return null
	for program: ScenarioProgramDefinition in programs:
		for index: int in range(program.instruction_count()):
			var instruction: Variant = program.instruction_at(index)
			if instruction is CallScenarioActionInstruction:
				var called_action := definition.action_by_id(instruction.action_id)
				var calling_context: StringName = reference_validator._program_context(program.owner_kind)
				if called_action == null or called_action.visibility != &"public" or calling_context == &"" or not called_action.allows_context(calling_context) or not reference_validator._call_arguments_match(instruction.argument_names(), instruction.result_target, called_action):
					_reject("Scenario program '%s' has an invalid public Scenario Action call to '%s'." % [program.id, instruction.action_id])
					return null
	for action: ScenarioActionDefinition in actions:
		for index: int in range(action.program.instruction_count()):
			var instruction := action.program.instruction_at(index)
			if instruction.kind == SafeInstructionDefinition.Kind.CALL_ACTION:
				var called_action := definition.action_by_id(instruction.action_id)
				if called_action == null or not reference_validator._call_arguments_match(instruction.argument_names(), instruction.result_target, called_action) or not reference_validator._contexts_are_compatible(action, called_action):
					_reject("Scenario Action '%s' has an invalid call to '%s'." % [action.id, instruction.action_id])
					return null
	return definition

func _construct_application_hooks(value: Variant) -> Variant:
	var fields: Array[String] = ["startGame", "partyDeath", "endAdventure", "shop", "temple"]
	if not value is Dictionary or not _exact_fields(value, fields):
		_reject("Scenario application hooks are malformed.")
		return null
	var hook_ids: Array[String] = []
	for field: String in fields:
		var hook_id: Variant = value[field]
		if hook_id != null and (not hook_id is String or hook_id.is_empty() or hook_id.length() > 255):
			_reject("Scenario application hook '%s' has an invalid program ID." % field)
			return null
		hook_ids.append("" if hook_id == null else String(hook_id))
	return ScenarioApplicationHooks.new(hook_ids[0], hook_ids[1], hook_ids[2], hook_ids[3], hook_ids[4])

func _construct_programs(value: Variant) -> Variant:
	if not value is Array:
		_reject("Scenario programs must be an array.")
		return null
	var programs: Array[ScenarioProgramDefinition] = []
	var ids: Dictionary = {}
	for program: Variant in value:
		if not program is Dictionary or not _exact_fields(program, ["id", "ownerKind", "ownerId", "instructions"]) or not program["id"] is String or program["id"].is_empty() or not program["ownerKind"] is String or program["ownerKind"] not in ["trigger", "extra-action-point", "simple-encounter-result", "complex-encounter-result"] or not program["ownerId"] is String or program["ownerId"].is_empty() or not program["instructions"] is Array or program["instructions"].size() > 4096:
			_reject("Scenario program is malformed.")
			return null
		if ids.has(program["id"]):
			_reject("Scenario program '%s' is duplicated." % program["id"])
			return null
		var instructions: Array[Variant] = []
		for instruction: Variant in program["instructions"]:
			var constructed: Variant = _construct_program_instruction(instruction)
			if constructed == null:
				return null
			instructions.append(constructed)
		ids[program["id"]] = true
		programs.append(ScenarioProgramDefinition.new(program["id"], StringName(program["ownerKind"]), program["ownerId"], instructions))
	return programs

func _construct_program_instruction(instruction: Variant) -> Variant:
	if not instruction is Dictionary or not instruction.get("kind") is String:
		_reject("Scenario instruction is malformed.")
		return null
	if instruction["kind"] == "callScenarioAction":
		return _construct_call_instruction(instruction)
	if instruction["kind"] != "classicAction" or not _exact_fields(instruction, ["kind", "slot", "rawOpcode", "opcode", "id", "gosub", "extraCode"]):
		_reject("Scenario program contains an unknown instruction kind.")
		return null
	for field: String in ["slot", "rawOpcode", "opcode", "id"]:
		if not _is_integer(instruction[field]):
			_reject("Classic instruction field '%s' is not an integer." % field)
			return null
	if _integer(instruction["slot"]) < 0 or not instruction["gosub"] is bool:
		_reject("Classic instruction slot or GOSUB identity is malformed.")
		return null
	var raw_opcode := _integer(instruction["rawOpcode"])
	var normalized := ClassicOpcodeCatalog.normalize(raw_opcode)
	if normalized != _integer(instruction["opcode"]) or instruction["gosub"] != (raw_opcode < 0 and raw_opcode not in [-14, -23]):
		_reject("Classic instruction raw/normalized/GOSUB identity is inconsistent.")
		return null
	if not ClassicOpcodeCatalog.is_executable(normalized):
		_reject("Scenario program requires unsupported Classic opcode %d." % normalized)
		return null
	var extra_code: Array[int] = []
	if instruction["extraCode"] != null:
		if not instruction["extraCode"] is Array or instruction["extraCode"].size() != 5:
			_reject("Classic E-code must contain five integers.")
			return null
		for extra: Variant in instruction["extraCode"]:
			if not _is_integer(extra):
				_reject("Classic E-code contains a non-integer.")
				return null
			extra_code.append(_integer(extra))
	return ClassicActionDefinition.new(_integer(instruction["slot"]), raw_opcode, normalized, _integer(instruction["id"]), instruction["gosub"], extra_code)

func _construct_call_instruction(record: Dictionary) -> CallScenarioActionInstruction:
	if not _exact_fields(record, ["kind", "actionId", "arguments", "result"]) or not record["actionId"] is String or record["actionId"].is_empty() or not record["arguments"] is Dictionary or record["result"] != null and not record["result"] is String:
		_reject("Scenario Action call instruction is malformed.")
		return null
	var arguments: Dictionary = {}
	var count := [0]
	for name: Variant in record["arguments"].keys():
		if not name is String or name.is_empty():
			_reject("Scenario Action call contains an invalid argument name.")
			return null
		var expression := _construct_safe_expression(record["arguments"][name], count, 0)
		if expression == null:
			return null
		arguments[name] = expression
	return CallScenarioActionInstruction.new(record["actionId"], arguments, "" if record["result"] == null else record["result"])

func _construct_scenario_actions(value: Variant, campaign_id: String) -> Variant:
	if not value is Array:
		_reject("Scenario Actions must be an array.")
		return null
	var actions: Array[ScenarioActionDefinition] = []
	var ids: Dictionary = {}
	var required_prefix := "scenario.%s." % campaign_id
	for record: Variant in value:
		var fields: Array[String] = ["id", "name", "description", "visibility", "category", "abiVersion", "implementationVersion", "stateSchemaVersion", "parameters", "returnType", "allowedContexts", "requiredCapabilities", "persistentState", "backend", "program"]
		if not record is Dictionary or not _exact_fields(record, fields) or not record["id"] is String or record["id"].is_empty() or not record["name"] is String or record["name"].is_empty() or not record["description"] is String or record["visibility"] not in ["public", "private"] or not record["category"] is String or record["category"].is_empty() or not record["returnType"] is String or not SUPPORTED_VALUE_TYPES.has(record["returnType"]) or record["backend"] != "safe" or not record["persistentState"] is Dictionary or not _json_safe(record["persistentState"], 0):
			_reject("Scenario Action definition is malformed or uses an unavailable backend.")
			return null
		if record["id"].begins_with("realmz.") or not record["id"].begins_with(required_prefix) or ids.has(record["id"]):
			_reject("Scenario Action ID '%s' has an invalid or duplicate namespace." % record["id"])
			return null
		for version_field: String in ["abiVersion", "implementationVersion", "stateSchemaVersion"]:
			if _integer(record[version_field]) < 1:
				_reject("Scenario Action '%s' has invalid version field '%s'." % [record["id"], version_field])
				return null
		if not record["parameters"] is Array or record["parameters"].size() > 256:
			_reject("Scenario Action '%s' parameters are malformed." % record["id"])
			return null
		var parameters: Array[ScenarioActionParameter] = []
		var parameter_names: Dictionary = {}

		for parameter: Variant in record["parameters"]:
			if not parameter is Dictionary or not _exact_fields(parameter, ["name", "valueType", "maxLength"]) or not parameter["name"] is String or not _safe_identifier(parameter["name"]) or parameter_names.has(parameter["name"]) or not parameter["valueType"] is String or not SUPPORTED_VALUE_TYPES.has(parameter["valueType"]) or parameter["valueType"] == "void" or (parameter["maxLength"] != null and (_integer(parameter["maxLength"]) < 1 or _integer(parameter["maxLength"]) > 256)):
				_reject("Scenario Action '%s' contains a malformed or duplicate parameter." % record["id"])
				return null
			parameter_names[parameter["name"]] = true
			parameters.append(ScenarioActionParameter.new(parameter["name"], StringName(parameter["valueType"]), -1 if parameter["maxLength"] == null else _integer(parameter["maxLength"])))
		var contexts_value: Variant = _string_array(record["allowedContexts"], "Scenario Action allowed contexts")
		var capabilities_value: Variant = _string_array(record["requiredCapabilities"], "Scenario Action required capabilities")
		if contexts_value == null or capabilities_value == null:
			return null
		var context_strings: Array[String] = contexts_value
		if context_strings.is_empty():
			_reject("Scenario Action '%s' has no allowed calling context." % record["id"])
			return null
		var contexts: Array[StringName] = []
		for context: String in context_strings:
			if not SUPPORTED_ACTION_CONTEXTS.has(context) or contexts.has(StringName(context)):
				_reject("Scenario Action '%s' has an unknown or duplicate calling context '%s'." % [record["id"], context])
				return null
			contexts.append(StringName(context))
		var capabilities: Array[String] = capabilities_value
		for capability: String in capabilities:
			if not SUPPORTED_SAFE_CAPABILITIES.has(capability) or capabilities.count(capability) > 1:
				_reject("Scenario Action '%s' requires unknown capability '%s'." % [record["id"], capability])
				return null
		var program := _construct_safe_program(record["program"], capabilities)
		if program == null:
			return null
		ids[record["id"]] = true
		actions.append(ScenarioActionDefinition.new(record["id"], record["name"], record["description"], StringName(record["visibility"]), StringName(record["category"]), _integer(record["abiVersion"]), _integer(record["implementationVersion"]), _integer(record["stateSchemaVersion"]), parameters, StringName(record["returnType"]), contexts, capabilities, &"safe", program))
	return actions

func _construct_safe_program(value: Variant, declared_capabilities: Array[String]) -> SafeProgramDefinition:
	if not value is Dictionary or not _exact_fields(value, ["format", "instructions"]) or value["format"] != "realmz.safe-bytecode.v1" or not value["instructions"] is Array or value["instructions"].size() > 4096:
		_reject("Safe Scenario Action bytecode is malformed or exceeds 4,096 instructions.")
		return null
	var instructions: Array[SafeInstructionDefinition] = []
	var node_count := [value["instructions"].size()]
	for record: Variant in value["instructions"]:
		var instruction := _construct_safe_instruction(record, node_count)
		if instruction == null:
			return null
		if instruction.kind == SafeInstructionDefinition.Kind.OPERATION and not declared_capabilities.has(instruction.capability):
			_reject("Safe program uses undeclared capability '%s'." % instruction.capability)
			return null
		instructions.append(instruction)
	for index: int in range(instructions.size()):
		var instruction := instructions[index]
		if instruction.kind in [SafeInstructionDefinition.Kind.JUMP, SafeInstructionDefinition.Kind.JUMP_IF_FALSE, SafeInstructionDefinition.Kind.BEGIN_FOR_EACH] and instruction.target > instructions.size():
			_reject("Safe instruction %d jumps outside its program." % index)
			return null
		if instruction.kind == SafeInstructionDefinition.Kind.NEXT_FOR_EACH and (instruction.target < 0 or instruction.target >= instructions.size() or instructions[instruction.target].kind != SafeInstructionDefinition.Kind.BEGIN_FOR_EACH):
			_reject("Safe for-each continuation at %d has an invalid begin target." % index)
			return null
		if instruction.kind == SafeInstructionDefinition.Kind.BEGIN_FOR_EACH and (instruction.target <= index + 1 or instructions[instruction.target - 1].kind != SafeInstructionDefinition.Kind.NEXT_FOR_EACH or instructions[instruction.target - 1].target != index):
			_reject("Safe for-each beginning at %d has an invalid bounded loop target." % index)
			return null
	return SafeProgramDefinition.new(instructions)

func _construct_safe_instruction(value: Variant, node_count: Array) -> SafeInstructionDefinition:
	if not value is Dictionary or not value.get("kind") is String:
		_reject("Safe instruction is malformed.")
		return null
	match value["kind"]:
		"operation":
			if not _exact_fields(value, ["kind", "capability", "arguments", "result"]) or not value["capability"] is String or not SUPPORTED_SAFE_CAPABILITIES.has(value["capability"]) or not value["arguments"] is Dictionary or value["result"] != null and not value["result"] is String:
				_reject("Safe operation instruction is malformed or unavailable.")
				return null
			var instruction := SafeInstructionDefinition.new(SafeInstructionDefinition.Kind.OPERATION)
			instruction.capability = value["capability"]
			instruction.result_target = "" if value["result"] == null else value["result"]
			var arguments: Variant = _construct_safe_arguments(value["arguments"], node_count)
			if arguments == null:
				return null
			instruction.set_arguments(arguments)
			return instruction
		"callScenarioAction":
			if not _exact_fields(value, ["kind", "actionId", "arguments", "result"]) or not value["actionId"] is String or value["actionId"].is_empty() or not value["arguments"] is Dictionary or value["result"] != null and not value["result"] is String:
				_reject("Safe Scenario Action call is malformed.")
				return null
			var instruction := SafeInstructionDefinition.new(SafeInstructionDefinition.Kind.CALL_ACTION)
			instruction.action_id = value["actionId"]
			instruction.result_target = "" if value["result"] == null else value["result"]
			var arguments: Variant = _construct_safe_arguments(value["arguments"], node_count)
			if arguments == null:
				return null
			instruction.set_arguments(arguments)
			return instruction
		"setValue":
			if not _exact_fields(value, ["kind", "scope", "stateScope", "ownerId", "name", "value"]) or value["scope"] not in ["local", "persistent"] or value["stateScope"] != null and not value["stateScope"] is String or value["ownerId"] != null and not value["ownerId"] is String or not value["name"] is String or value["name"].is_empty():
				_reject("Safe value assignment is malformed.")
				return null
			var instruction := SafeInstructionDefinition.new(SafeInstructionDefinition.Kind.SET_VALUE)
			instruction.scope = StringName(value["scope"])
			instruction.state_scope = "" if value["stateScope"] == null else value["stateScope"]
			instruction.owner_id = "" if value["ownerId"] == null else value["ownerId"]
			instruction.name = value["name"]
			instruction.value = _construct_safe_expression(value["value"], node_count, 0)
			return instruction if instruction.value != null else null
		"jumpIfFalse":
			if not _exact_fields(value, ["kind", "condition", "target"]) or _integer(value["target"]) < 0:
				_reject("Safe conditional jump is malformed.")
				return null
			var instruction := SafeInstructionDefinition.new(SafeInstructionDefinition.Kind.JUMP_IF_FALSE)
			instruction.condition = _construct_safe_expression(value["condition"], node_count, 0)
			instruction.target = _integer(value["target"])
			return instruction if instruction.condition != null else null
		"jump":
			if not _exact_fields(value, ["kind", "target"]) or _integer(value["target"]) < 0:
				_reject("Safe jump is malformed.")
				return null
			var instruction := SafeInstructionDefinition.new(SafeInstructionDefinition.Kind.JUMP)
			instruction.target = _integer(value["target"])
			return instruction
		"beginForEach":
			if not _exact_fields(value, ["kind", "itemName", "collection", "endTarget"]) or not value["itemName"] is String or value["itemName"].is_empty() or _integer(value["endTarget"]) < 0:
				_reject("Safe for-each beginning is malformed.")
				return null
			var instruction := SafeInstructionDefinition.new(SafeInstructionDefinition.Kind.BEGIN_FOR_EACH)
			instruction.item_name = value["itemName"]
			instruction.collection = _construct_safe_expression(value["collection"], node_count, 0)
			instruction.target = _integer(value["endTarget"])
			return instruction if instruction.collection != null else null
		"nextForEach":
			if not _exact_fields(value, ["kind", "beginTarget"]) or _integer(value["beginTarget"]) < 0:
				_reject("Safe for-each continuation is malformed.")
				return null
			var instruction := SafeInstructionDefinition.new(SafeInstructionDefinition.Kind.NEXT_FOR_EACH)
			instruction.target = _integer(value["beginTarget"])
			return instruction
		"return":
			if not _exact_fields(value, ["kind", "value"]):
				_reject("Safe return instruction is malformed.")
				return null
			var instruction := SafeInstructionDefinition.new(SafeInstructionDefinition.Kind.RETURN)
			if value["value"] != null:
				instruction.value = _construct_safe_expression(value["value"], node_count, 0)
				if instruction.value == null:
					return null
			return instruction
		"halt":
			if not _exact_fields(value, ["kind", "outcome"]):
				_reject("Safe halt instruction is malformed.")
				return null
			var instruction := SafeInstructionDefinition.new(SafeInstructionDefinition.Kind.HALT)
			instruction.outcome = value["outcome"]
			return instruction
	_reject("Safe program contains unknown instruction kind '%s'." % value["kind"])
	return null

func _construct_safe_arguments(value: Dictionary, node_count: Array) -> Variant:
	var result: Dictionary = {}
	for name: Variant in value.keys():
		if not name is String or name.is_empty():
			_reject("Safe instruction contains an invalid argument name.")
			return null
		var expression := _construct_safe_expression(value[name], node_count, 0)
		if expression == null:
			return null
		result[name] = expression

class_name PackageWorldDecoder
extends PackageDecoderBase

const DIRECTIONS: Array[String] = ["north", "east", "south", "west"]
const TRANSITION_DIRECTIONS: Array[String] = ["north", "northeast", "east", "southeast", "south", "southwest", "west", "northwest"]
const EDGE_KINDS: Array[String] = ["open", "wall", "door", "secret", "archway", "map-boundary"]
const FEATURE_KINDS: Array[String] = ["door", "secret", "stairs", "column", "unmapped", "note", "action-point", "archway", "no-wall-in-battle"]

func _construct_triggers(value: Variant, scenario: ScenarioDefinition) -> Variant:
	if not value is Array:
		_reject("World triggers must be an array.")
		return null
	var triggers: Array[TriggerDefinition] = []
	var placed_record_keys: Dictionary = {}
	for record: Variant in value:
		if not record is Dictionary or not _exact_fields(record, ["id", "programId", "classicRecordIndex", "mapId", "coordinate", "active", "chancePercent", "postActionLocation"]) or not record.get("id") is String or record["id"].is_empty() or not record.get("programId") is String or record["programId"].is_empty() or not _is_integer(record.get("classicRecordIndex")) or _integer(record["classicRecordIndex"]) < 0 or not record.get("active") is bool:
			_reject("Trigger record is malformed.")
			return null
		var trigger_program := scenario.program_by_id(record["programId"])
		if trigger_program == null or trigger_program.owner_id != record["id"] or trigger_program.owner_kind not in [&"trigger", &"extra-action-point"]:
			_reject("Trigger '%s' references unavailable scenario program '%s'." % [record["id"], record["programId"]])
			return null
		var map_id: String = ""
		var coordinate := Vector2i(-1, -1)
		if record.get("mapId") != null or record.get("coordinate") != null:
			if not record.get("mapId") is String or not record.get("coordinate") is Dictionary or not _exact_fields(record["coordinate"], ["x", "y"]):
				_reject("Placed trigger '%s' has incomplete map coordinates." % record["id"])
				return null
			map_id = record["mapId"]
			coordinate = Vector2i(_integer(record["coordinate"].get("x")), _integer(record["coordinate"].get("y")))
			if coordinate.x < 0 or coordinate.y < 0:
				_reject("Placed trigger '%s' has invalid map coordinates." % record["id"])
				return null
			var placed_record_key := "%s:%d" % [map_id, _integer(record["classicRecordIndex"])]
			if placed_record_keys.has(placed_record_key):
				_reject("Placed trigger '%s' duplicates Classic record %d on map '%s'." % [record["id"], _integer(record["classicRecordIndex"]), map_id])
				return null
			placed_record_keys[placed_record_key] = true
		var chance := _integer(record.get("chancePercent"))
		if chance < -128 or chance > 127:
			_reject("Trigger '%s' chance is outside Classic storage." % record["id"])
			return null
		var destination_record: Variant = record.get("postActionLocation")
		var destination: TriggerDestinationDefinition = null
		if destination_record != null:
			if not destination_record is Dictionary or not _exact_fields(destination_record, ["mapId", "coordinate"]) or not destination_record.get("mapId") is String or not destination_record.get("coordinate") is Dictionary or not _exact_fields(destination_record["coordinate"], ["x", "y"]):
				_reject("Trigger '%s' post-action location is malformed." % record["id"])
				return null
			var destination_coordinate: Dictionary = destination_record["coordinate"]
			if not _is_integer(destination_coordinate.get("x")) or not _is_integer(destination_coordinate.get("y")):
				_reject("Trigger '%s' post-action coordinate is malformed." % record["id"])
				return null
			destination = TriggerDestinationDefinition.new(destination_record["mapId"], Vector2i(_integer(destination_coordinate["x"]), _integer(destination_coordinate["y"])))
		triggers.append(TriggerDefinition.new(record["id"], record["programId"], map_id, coordinate, record["active"], chance, destination, _integer(record["classicRecordIndex"])))
	return triggers

func _construct_battle_terrain_sets(value: Variant) -> Variant:
	if not value is Array:
		_reject("World battle terrain sets must be an array.")
		return null
	var terrain_sets: Array[BattleTerrainSetDefinition] = []
	var set_ids: Dictionary = {}
	for record: Variant in value:
		if not record is Dictionary or not _exact_fields(record, ["id", "landlook", "baseTile", "tiles"]) or not record["id"] is String or record["id"].is_empty() or set_ids.has(record["id"]) or not record["tiles"] is Array:
			_reject("Battle terrain set is malformed or duplicated.")
			return null
		var dungeon_set := record["landlook"] == null
		if dungeon_set != (record["baseTile"] == null):
			_reject("Battle terrain set '%s' has inconsistent landlook/base-tile identity." % record["id"])
			return null
		if not dungeon_set and (not _is_integer(record["landlook"]) or not _is_integer(record["baseTile"])):
			_reject("Battle terrain set '%s' has non-integer landlook or base-tile identity." % record["id"])
			return null
		var landlook := -1 if dungeon_set else _integer(record["landlook"])
		var base_tile := -1 if dungeon_set else _integer(record["baseTile"])
		if not dungeon_set and (landlook < -128 or landlook > 127 or base_tile < 0 or base_tile > 400):
			_reject("Battle terrain set '%s' has invalid landlook or base-tile identity." % record["id"])
			return null
		var tiles: Array[BattleTerrainTileDefinition] = []
		var tile_ids: Dictionary = {}
		for tile_record: Variant in record["tiles"]:
			var tile_definition := _construct_battle_terrain_tile(tile_record)
			if tile_definition == null or tile_ids.has(tile_definition.tile):
				_reject("Battle terrain set '%s' contains a malformed or duplicate tile." % record["id"])
				return null
			tile_ids[tile_definition.tile] = true
			tiles.append(tile_definition)
		var terrain_set := BattleTerrainSetDefinition.new(record["id"], landlook, base_tile, tiles)
		if dungeon_set and not terrain_set.has_complete_range(200, 400):
			_reject("Dungeon battle terrain set '%s' must contain every Combat Data BD tile 200 through 400." % record["id"])
			return null
		if not dungeon_set and not terrain_set.has_complete_range(0, 400):
			_reject("Land battle terrain set '%s' must contain every effective mapstats tile 0 through 400." % record["id"])
			return null
		set_ids[terrain_set.id] = true
		terrain_sets.append(terrain_set)
	return terrain_sets

func _construct_battle_terrain_tile(value: Variant) -> BattleTerrainTileDefinition:
	var fields: Array[String] = ["tile", "sound", "time", "solid", "shore", "needBoat", "isPath", "los", "flyFloat", "forest", "combatBuild"]
	if not value is Dictionary or not _exact_fields(value, fields):
		return null
	var record: Dictionary = value
	var integers_value: Variant = _validated_integer_fields(record, ["tile", "sound", "time", "solid", "needBoat", "forest"], "Battle terrain tile")
	if integers_value == null:
		return null
	var integers: Dictionary = integers_value
	if integers["tile"] < 0 or integers["tile"] > 400 or not _integers_in_range(integers, ["sound", "time", "solid", "needBoat", "forest"], -32768, 32767):
		return null
	for flag: String in ["shore", "isPath", "los", "flyFloat"]:
		if not record[flag] is bool:
			return null
	if not record["combatBuild"] is Array or record["combatBuild"].size() != 3:
		return null
	var combat_build: Array = []
	for row: Variant in record["combatBuild"]:
		if not row is Array or row.size() != 3:
			return null
		var parsed_row: Array[int] = []
		for entry: Variant in row:
			if not _is_integer(entry):
				return null
			var tile_id := _integer(entry)
			if tile_id < -32768 or tile_id > 32767:
				return null
			parsed_row.append(tile_id)
		combat_build.append(parsed_row)
	return BattleTerrainTileDefinition.new(integers["tile"], integers["sound"], integers["time"], integers["solid"], record["shore"], integers["needBoat"], record["isPath"], record["los"], record["flyFloat"], integers["forest"], combat_build)

func _construct_maps(value: Variant, trigger_ids: Dictionary, battle_terrain_sets: Dictionary = {}, require_battle_terrain: bool = false, validate_compact_rows: bool = true) -> Variant:
	if not value is Array or value.is_empty():
		_reject("World maps must be a non-empty array.")
		return null
	var maps: Array[MapDefinition] = []
	var map_ids: Dictionary = {}
	for record: Variant in value:
		if not record is Dictionary or not record.get("id") is String or record["id"].is_empty() or not record.get("name") is String:
			_reject("Map definition is malformed.")
			return null
		if map_ids.has(record["id"]):
			_reject("Map ID '%s' is duplicated." % record["id"])
			return null
		map_ids[record["id"]] = true
		var width := _integer(record.get("width"))
		var height := _integer(record.get("height"))
		if width < 1 or height < 1 or width > 256 or height > 256 or record.get("topologyFormat") != "realmz2.compact-cell-rows.v2" or not record.get("cells") is Array or record["cells"].size() != width * height:
			_reject("Map '%s' dimensions do not match its topology cells." % record["id"])
			return null
		var level_index := _integer(record.get("levelIndex"))
		var level_type: Variant = record.get("levelType")
		if level_index < 0 or not level_type is String or level_type not in ["land", "dungeon"]:
			_reject("Map '%s' has an invalid Classic level index." % record["id"])
			return null
		var regions_value: Variant = _construct_random_regions(record.get("randomRectangles"), width, height, record["id"])
		if regions_value == null:
			return null
		var regions: Array[RandomEncounterRegion] = regions_value
		var region_ids: Dictionary = {}
		for region: RandomEncounterRegion in regions:
			region_ids[region.id] = true

		if validate_compact_rows:
			for cell_index: int in record["cells"].size():
				if not _validate_compact_cell(record["cells"][cell_index], record["id"], cell_index, trigger_ids, region_ids, StringName(level_type)):
					return null
		var metadata: Variant = record.get("metadata")
		if not metadata is Dictionary or not _exact_fields(metadata, ["dark", "usesLos", "landlook", "battleTerrainSetId"]) or not metadata.get("dark") is bool or not metadata.get("usesLos") is bool or metadata.get("landlook") != null and not _is_integer(metadata.get("landlook")):
			_reject("Map '%s' metadata is malformed." % record["id"])
			return null
		var landlook := -1 if metadata["landlook"] == null else _integer(metadata["landlook"])
		if metadata["battleTerrainSetId"] != null and (not metadata["battleTerrainSetId"] is String or metadata["battleTerrainSetId"].is_empty()):
			_reject("Map '%s' battle terrain set identity is malformed." % record["id"])
			return null
		var terrain_set_id: String = "" if metadata["battleTerrainSetId"] == null else metadata["battleTerrainSetId"]
		var terrain_set := battle_terrain_sets.get(terrain_set_id) as BattleTerrainSetDefinition
		if require_battle_terrain and terrain_set == null:
			_reject("Map '%s' does not reference a complete battle terrain set." % record["id"])
			return null
		if not terrain_set_id.is_empty() and terrain_set == null:
			_reject("Map '%s' references unknown battle terrain set '%s'." % [record["id"], terrain_set_id])
			return null
		if terrain_set != null and ((level_type == "land" and terrain_set.landlook != landlook) or (level_type == "dungeon" and terrain_set.landlook != -1)):
			_reject("Map '%s' references a battle terrain set for the wrong level type or landlook." % record["id"])
			return null
		var boat_profiles_value: Variant = _construct_boat_replacement_profiles(record.get("boatReplacementProfiles"), StringName(level_type), record["id"])
		if boat_profiles_value == null:
			return null
		var boat_profiles: Array = boat_profiles_value
		var topology := MapTopology.from_compact_rows(record["id"], width, height, record["cells"], boat_profiles[0] as LandTileProfile, boat_profiles[1] as LandTileProfile)
		maps.append(MapDefinition.new(record["id"], record["name"], StringName(level_type), level_index, topology, metadata["dark"], metadata["usesLos"], landlook, regions, terrain_set_id))
	return maps


func _construct_boat_replacement_profiles(value: Variant, level_type: StringName, map_id: String) -> Variant:
	if level_type == &"dungeon":
		if value != null:
			_reject("Dungeon map '%s' contains land-only boat replacement profiles." % map_id)
			return null
		return [null, null]
	if not value is Dictionary or not _exact_fields(value, ["removed", "placed"]):
		_reject("Land map '%s' is missing exact Classic boat replacement profiles." % map_id)
		return null
	var removed := _construct_land_tile_profile(value["removed"], map_id, "removed")
	var placed := _construct_land_tile_profile(value["placed"], map_id, "placed")
	if removed == null or placed == null:
		return null
	return [removed, placed]


func _construct_land_tile_profile(value: Variant, map_id: String, role: String) -> LandTileProfile:
	if not value is Array or value.size() != 7:
		_reject("Land map '%s' has a malformed %s boat replacement profile." % [map_id, role])
		return null
	var row: Array = value
	var movement_cost := _integer(row[1])
	var flags := _integer(row[2])
	var render_tile := _integer(row[4])
	var boat_requirement := _integer(row[5])
	var blocked_attempts := _integer(row[6])
	if not row[0] is String or row[0].is_empty() or movement_cost < 0 or flags < 0 or flags > 255 or row[3] != null and not _is_integer(row[3]) or render_tile < 1 or boat_requirement < 0 or boat_requirement > 2 or blocked_attempts < 0:
		_reject("Land map '%s' has invalid %s boat replacement facts." % [map_id, role])
		return null
	if not bool(flags & 4) or bool(flags & 8) != (boat_requirement == 2) or bool(flags & 64) != (boat_requirement != 0):
		_reject("Land map '%s' has contradictory %s boat replacement semantics." % [map_id, role])
		return null
	return LandTileProfile.new(row[0], movement_cost, flags, -1 if row[3] == null else _integer(row[3]), render_tile, boat_requirement, blocked_attempts)

func _validate_compact_cell(value: Variant, map_id: String, cell_index: int, trigger_ids: Dictionary, region_ids: Dictionary, level_type: StringName) -> bool:
	if not value is Array or value.size() != 13:
		return _reject("Map '%s' compact topology row %d is malformed." % [map_id, cell_index])
	var row: Array = value
	if not row[0] is String or row[0].is_empty() or not _is_integer(row[1]) or _integer(row[1]) < 0 or not _is_integer(row[2]) or _integer(row[2]) < 0 or _integer(row[2]) > 255:
		return _reject("Map '%s' compact topology row %d has malformed terrain facts." % [map_id, cell_index])
	if row[3] != null and not _is_integer(row[3]):
		return _reject("Map '%s' compact topology row %d has malformed movement sound." % [map_id, cell_index])
	var cell_triggers_value: Variant = _string_array(row[4], "compact cell trigger IDs")
	var random_rects_value: Variant = _string_array(row[5], "compact cell random rectangle IDs")
	if cell_triggers_value == null or random_rects_value == null:
		return false
	for trigger_id: String in cell_triggers_value:
		if not trigger_ids.has(trigger_id):
			return _reject("Topology cell references unknown trigger '%s'." % trigger_id)
	for region_id: String in random_rects_value:
		if not region_ids.has(region_id):
			return _reject("Topology cell references unknown random rectangle '%s'." % region_id)
	if not row[7] is Array:
		return _reject("Map '%s' compact topology row %d has malformed features." % [map_id, cell_index])
	var feature_kinds_by_id: Dictionary = {}
	for feature_value: Variant in row[7]:
		if not feature_value is Array or feature_value.size() != 4:
			return _reject("Map '%s' compact topology row %d contains a malformed feature." % [map_id, cell_index])
		var feature: Array = feature_value
		if not feature[0] is String or feature[0].is_empty() or feature_kinds_by_id.has(feature[0]) or not feature[1] is String or not FEATURE_KINDS.has(feature[1]):
			return _reject("Map '%s' compact topology row %d contains a malformed or duplicate feature." % [map_id, cell_index])
		if feature[2] != null and not feature[2] is String:
			return _reject("Topology feature '%s' state is malformed." % feature[0])
		if feature[3] != null and (not feature[3] is String or not DIRECTIONS.has(feature[3]) and feature[3] not in ["horizontal", "vertical"]):
			return _reject("Topology feature '%s' orientation is malformed." % feature[0])
		feature_kinds_by_id[feature[0]] = feature[1]
	if not row[6] is Array or row[6].size() != 4:
		return _reject("Map '%s' compact topology row %d has malformed edges." % [map_id, cell_index])
	for edge_value: Variant in row[6]:
		if not edge_value is Array or edge_value.size() != 4:
			return _reject("Map '%s' compact topology row %d contains a malformed edge." % [map_id, cell_index])
		var edge: Array = edge_value
		if not edge[0] is String or not EDGE_KINDS.has(edge[0]) or not _is_integer(edge[1]) or _integer(edge[1]) < 0 or _integer(edge[1]) > 7:
			return _reject("Map '%s' compact topology row %d contains invalid edge facts." % [map_id, cell_index])
		for reference_index: int in [2, 3]:
			if edge[reference_index] != null and (not edge[reference_index] is String or edge[reference_index].is_empty()):
				return _reject("Map '%s' compact topology row %d contains an invalid edge reference." % [map_id, cell_index])
		var door_id := "" if edge[2] == null else String(edge[2])
		var secret_id := "" if edge[3] == null else String(edge[3])
		if not door_id.is_empty() and feature_kinds_by_id.get(door_id) != "door":
			return _reject("Topology edge references unknown door '%s'." % door_id)
		if not secret_id.is_empty() and feature_kinds_by_id.get(secret_id) != "secret":
			return _reject("Topology edge references unknown secret '%s'." % secret_id)
	if not _is_integer(row[8]) or not row[9] is String or row[9].is_empty() or row[10] != null and (not row[10] is String or row[10].is_empty()):
		return _reject("Map '%s' compact topology row %d has malformed render facts." % [map_id, cell_index])
	if not _is_integer(row[11]) or _integer(row[11]) < 0 or _integer(row[11]) > 2 or not _is_integer(row[12]) or _integer(row[12]) < 0:
		return _reject("Map '%s' compact topology row %d has malformed Classic movement facts." % [map_id, cell_index])
	var boat_requirement := _integer(row[11])
	var flags := _integer(row[2])
	if bool(flags & 8) != (boat_requirement == 2) or bool(flags & 64) != (boat_requirement != 0):
		return _reject("Map '%s' compact topology row %d has contradictory boat facts." % [map_id, cell_index])
	if level_type == &"dungeon" and (boat_requirement != 0 or _integer(row[12]) != 0):
		return _reject("Dungeon map '%s' compact topology row %d contains land-only movement facts." % [map_id, cell_index])
	return true

func _construct_player_maps(value: Variant, maps: Array[MapDefinition], media_assets: Array[MediaAsset]) -> Variant:
	if not value is Array or value.size() > 20:
		_reject("World player maps must be an array of no more than twenty records.")
		return null
	var maps_by_id: Dictionary = {}
	for map: MapDefinition in maps:
		maps_by_id[map.id] = map
	var assets_by_id: Dictionary = {}
	for asset: MediaAsset in media_assets:
		assets_by_id[asset.id] = asset
	var result: Array[PlayerMapDefinition] = []
	var ids: Dictionary = {}
	var classic_ids: Dictionary = {}
	var fields: Array[String] = ["id", "classicId", "name", "unavailableName", "mode", "mapId", "start", "iconSize", "pictureAssetId", "scrollingTextAssetId", "partyMarkerAssetId", "pictureRect", "markers", "note"]
	var modes: Array[String] = ["scrolling-text", "picture", "land-crop", "dungeon-crop"]
	for value_record: Variant in value:
		if not value_record is Dictionary:
			_reject("Player-map definition is not an object.")
			return null
		var record: Dictionary = value_record
		if not _exact_fields(record, fields) or not record["id"] is String or record["id"].is_empty() or ids.has(record["id"]) or not _is_integer(record["classicId"]) or not record["name"] is String or record["name"].is_empty() or not record["unavailableName"] is String or not record["mode"] is String or record["mode"] not in modes or not _is_integer(record["iconSize"]) or _integer(record["iconSize"]) <= 0 or not record["note"] is String:
			_reject("Player-map definition is malformed or duplicated.")
			return null
		var classic_id := _integer(record["classicId"])
		if classic_id < 0 or classic_id > 19 or classic_ids.has(classic_id):
			_reject("Player-map Classic ID must be unique and between 0 and 19.")
			return null
		if not record["start"] is Dictionary or not _exact_fields(record["start"], ["x", "y"]) or not _is_integer(record["start"]["x"]) or not _is_integer(record["start"]["y"]):
			_reject("Player-map start coordinate is malformed.")
			return null
		if not record["pictureRect"] is Dictionary or not _exact_fields(record["pictureRect"], ["top", "left", "bottom", "right"]):
			_reject("Player-map picture rectangle is malformed.")
			return null

		for field: String in ["top", "left", "bottom", "right"]:
			if not _is_integer(record["pictureRect"][field]):
				_reject("Player-map picture rectangle is malformed.")
				return null
		var mode := StringName(record["mode"])
		var map_id := "" if record["mapId"] == null else String(record["mapId"])
		var picture_asset_id := "" if record["pictureAssetId"] == null else String(record["pictureAssetId"])
		var scrolling_text_asset_id := "" if record["scrollingTextAssetId"] == null else String(record["scrollingTextAssetId"])
		var party_marker_asset_id := "" if record["partyMarkerAssetId"] == null else String(record["partyMarkerAssetId"])
		var party_marker_asset := assets_by_id.get(party_marker_asset_id) as MediaAsset
		if record["mapId"] != null and (not record["mapId"] is String or map_id.is_empty()) or record["pictureAssetId"] != null and (not record["pictureAssetId"] is String or picture_asset_id.is_empty()) or record["scrollingTextAssetId"] != null and (not record["scrollingTextAssetId"] is String or scrolling_text_asset_id.is_empty()) or record["partyMarkerAssetId"] != null and (not record["partyMarkerAssetId"] is String or party_marker_asset_id.is_empty()):
			_reject("Player-map content references are malformed.")
			return null
		var crop := mode in [PlayerMapDefinition.LAND_CROP, PlayerMapDefinition.DUNGEON_CROP]
		if crop:
			var source_map := maps_by_id.get(map_id) as MapDefinition
			var expected_type := &"dungeon" if mode == PlayerMapDefinition.DUNGEON_CROP else &"land"
			if source_map == null or source_map.level_type != expected_type or not picture_asset_id.is_empty() or not scrolling_text_asset_id.is_empty():
				_reject("Player-map crop references an unavailable or wrong-kind topology map.")
				return null
		if mode == PlayerMapDefinition.PICTURE:
			var picture_map := maps_by_id.get(map_id) as MapDefinition
			if picture_map == null or not _player_map_asset_matches(assets_by_id.get(picture_asset_id), "PICT") or not _player_map_asset_matches(party_marker_asset, "cicn") or party_marker_asset.resource_id != 138 or not scrolling_text_asset_id.is_empty():
				_reject("Picture-backed player map references unavailable PICT media.")
				return null
		elif mode == PlayerMapDefinition.SCROLLING_TEXT:
			if not map_id.is_empty() or not _player_map_asset_matches(assets_by_id.get(scrolling_text_asset_id), "TEXT") or not picture_asset_id.is_empty() or not party_marker_asset_id.is_empty():
				_reject("Scrolling player map references unavailable TEXT media.")
				return null
		elif not _player_map_asset_matches(party_marker_asset, "cicn") or party_marker_asset.resource_id != 138:
			_reject("Player-map crop references unavailable current-party cicn media.")
			return null
		var markers_value: Variant = record["markers"]
		if not markers_value is Array or markers_value.size() > 10 or not crop and not markers_value.is_empty():
			_reject("Player-map markers are malformed or attached outside a crop map.")
			return null
		var markers: Array[PlayerMapMarkerDefinition] = []
		for marker_value: Variant in markers_value:
			if not marker_value is Dictionary or not _exact_fields(marker_value, ["classicIconId", "iconAssetId", "x", "y"]) or not _is_integer(marker_value["classicIconId"]) or not marker_value["iconAssetId"] is String or marker_value["iconAssetId"].is_empty() or not _is_integer(marker_value["x"]) or not _is_integer(marker_value["y"]):
				_reject("Player-map marker is malformed.")
				return null
			var marker_asset := assets_by_id.get(marker_value["iconAssetId"]) as MediaAsset
			if not _player_map_asset_matches(marker_asset, "cicn") or marker_asset.resource_id != _integer(marker_value["classicIconId"]):
				_reject("Player-map marker does not match its exact cicn resource identity.")
				return null
			markers.append(PlayerMapMarkerDefinition.new(_integer(marker_value["classicIconId"]), marker_value["iconAssetId"], Vector2i(_integer(marker_value["x"]), _integer(marker_value["y"]))))
		ids[record["id"]] = true
		classic_ids[classic_id] = true
		var rect: Dictionary = record["pictureRect"]
		result.append(PlayerMapDefinition.new(record["id"], classic_id, record["name"], record["unavailableName"], mode, map_id, Vector2i(_integer(record["start"]["x"]), _integer(record["start"]["y"])), _integer(record["iconSize"]), picture_asset_id, scrolling_text_asset_id, party_marker_asset_id, Rect2i(_integer(rect["left"]), _integer(rect["top"]), _integer(rect["right"]) - _integer(rect["left"]), _integer(rect["bottom"]) - _integer(rect["top"])), markers, record["note"]))
	result.sort_custom(func(left: PlayerMapDefinition, right: PlayerMapDefinition) -> bool: return left.classic_id < right.classic_id)
	return result

func _player_map_asset_matches(value: Variant, resource_type: String) -> bool:
	return value is MediaAsset and value.resource_type == resource_type

func _construct_random_regions(value: Variant, width: int, height: int, map_id: String) -> Variant:
	if not value is Array:
		_reject("Map '%s' random rectangles must be an array." % map_id)
		return null
	var regions: Array[RandomEncounterRegion] = []
	var ids: Dictionary = {}
	for record: Variant in value:
		if not record is Dictionary or not record.get("id") is String or record["id"].is_empty() or ids.has(record["id"]):
			_reject("Map '%s' contains a malformed or duplicate random rectangle." % map_id)
			return null
		for field: String in ["top", "left", "bottom", "right", "chanceTenThousand", "option", "soundId", "textId"]:
			if not _is_integer(record.get(field)):
				_reject("Random rectangle '%s' field '%s' is malformed." % [record["id"], field])
				return null
		var top := _integer(record["top"])
		var left := _integer(record["left"])
		var bottom := _integer(record["bottom"])
		var right := _integer(record["right"])
		var chance := _integer(record["chanceTenThousand"])
		var classic_scalars := {"chance": chance, "option": _integer(record["option"]), "sound": _integer(record["soundId"]), "text": _integer(record["textId"])}
		if top < 0 or left < 0 or bottom < top or right < left or bottom >= height or right >= width or not _integers_in_range(classic_scalars, ["chance", "option", "sound", "text"], -32768, 32767) or not record.get("only") is bool:
			_reject("Random rectangle '%s' bounds or flags are malformed." % record["id"])
			return null
		var battle_range_value: Variant = _integer_array(record.get("battleRange"), 2, "battle range")
		var doors_value: Variant = _integer_array(record.get("randomDoors"), 3, "random doors")
		var percents_value: Variant = _integer_array(record.get("randomDoorPercent"), 3, "random door percentages")
		if battle_range_value == null or doors_value == null or percents_value == null:
			return null
		var battle_range: Array[int] = battle_range_value
		var doors: Array[int] = doors_value
		var percents: Array[int] = percents_value
		if not _integers_in_range({"battleMinimum": battle_range[0], "battleMaximum": battle_range[1]}, ["battleMinimum", "battleMaximum"], -32768, 32767) or not _integers_in_range({"door0": doors[0], "door1": doors[1], "door2": doors[2]}, ["door0", "door1", "door2"], -32768, 32767) or not _integers_in_range({"chance0": percents[0], "chance1": percents[1], "chance2": percents[2]}, ["chance0", "chance1", "chance2"], -32768, 32767):
			_reject("Random rectangle '%s' has values outside Classic 16-bit storage." % record["id"])
			return null
		ids[record["id"]] = true
		regions.append(RandomEncounterRegion.new(record["id"], Rect2i(left, top, right - left + 1, bottom - top + 1), chance, battle_range[0], battle_range[1], doors, percents, record["only"], _integer(record["option"]), _integer(record["soundId"]), _integer(record["textId"])))
	return regions

func _construct_transitions(value: Variant, maps: Array[MapDefinition]) -> Variant:
	if not value is Array:
		_reject("World transitions must be an array.")
		return null
	var map_ids: Dictionary = {}
	for map: MapDefinition in maps:
		map_ids[map.id] = true
	var transitions: Array[MapTransition] = []
	var ids: Dictionary = {}
	var sources: Dictionary = {}
	for record: Variant in value:
		if not record is Dictionary or not record.get("id") is String or record["id"].is_empty() or ids.has(record["id"]) or not record.get("source") is Dictionary or not record.get("target") is Dictionary:
			_reject("World contains a malformed or duplicate transition.")
			return null
		var source: Dictionary = record["source"]
		var target: Dictionary = record["target"]
		if not source.get("mapId") is String or not target.get("mapId") is String or not map_ids.has(source["mapId"]) or not map_ids.has(target["mapId"]) or not source.get("edge") is String or not TRANSITION_DIRECTIONS.has(source["edge"]) or not target.get("edge") is String or not TRANSITION_DIRECTIONS.has(target["edge"]):
			_reject("Transition '%s' references an invalid map edge." % record["id"])
			return null
		var source_key := "%s:%s" % [source["mapId"], source["edge"]]
		if sources.has(source_key):
			_reject("World transition source '%s' is ambiguous." % source_key)
			return null
		ids[record["id"]] = true
		sources[source_key] = true
		transitions.append(MapTransition.new(record["id"], source["mapId"], StringName(source["edge"]), target["mapId"], StringName(target["edge"])))
	return transitions

class_name SaveEnvelope
extends SessionSnapshot

const FORMAT: String = "realmz2-save"
const FORMAT_VERSION: int = 4


func _init(campaign: String, package_identity: String, rules: String, revision: int, state: GameState, random_state: RealmzRngState, vm_state: ScenarioVmSnapshot = null, action_state: ScenarioActionState = null, pending_continuation: SessionContinuation = null, pending_battle_return: SessionContinuation = null, pending_session_interaction: InteractionRequest = null) -> void:
	super(campaign, package_identity, rules, revision, state, random_state, vm_state, action_state, pending_continuation, pending_battle_return, pending_session_interaction)


func to_data() -> Dictionary:
	return {
		"format": FORMAT,
		"formatVersion": FORMAT_VERSION,
		"campaignId": campaign_id,
		"packageHash": package_hash,
		"rulesVersion": rules_version,
		"deviationIds": deviation_ids.duplicate(),
		"viewRevision": view_revision,
		"gameState": game_state.to_data(),
		"rng": rng_state.to_data(),
		"scenarioVm": scenario_vm.to_data(),
		"scenarioActionState": scenario_action_state.to_data(),
		"sessionContinuation": {} if continuation == null else continuation.to_data(),
		"battleReturnContinuation": {} if battle_return_continuation == null else battle_return_continuation.to_data(),
		"sessionInteraction": {} if session_interaction == null else session_interaction.to_data(),
	}


static func from_snapshot(snapshot: SessionSnapshot) -> SaveEnvelope:
	if snapshot == null:
		return null
	var envelope := SaveEnvelope.new(snapshot.campaign_id, snapshot.package_hash, snapshot.rules_version, snapshot.view_revision, snapshot.game_state, snapshot.rng_state, snapshot.scenario_vm, snapshot.scenario_action_state, snapshot.continuation, snapshot.battle_return_continuation, snapshot.session_interaction)
	envelope.deviation_ids = snapshot.deviation_ids.duplicate()
	return envelope


static func from_data(data: Variant) -> SaveEnvelope:
	var fields: Array[String] = ["format", "formatVersion", "campaignId", "packageHash", "rulesVersion", "deviationIds", "viewRevision", "gameState", "rng", "scenarioVm", "scenarioActionState", "sessionContinuation", "battleReturnContinuation", "sessionInteraction"]
	if not data is Dictionary or data.size() != fields.size():
		return null
	for field: String in fields:
		if not data.has(field):
			return null
	if data["format"] != FORMAT or data["formatVersion"] != FORMAT_VERSION:
		return null
	if not data["campaignId"] is String or data["campaignId"].is_empty() or not data["packageHash"] is String or data["packageHash"].length() != 64 or not data["rulesVersion"] is String or data["rulesVersion"].is_empty():
		return null
	var revision := _integer(data["viewRevision"])
	if revision < 0 or not data["deviationIds"] is Array or not data["sessionContinuation"] is Dictionary or not data["battleReturnContinuation"] is Dictionary or not data["sessionInteraction"] is Dictionary:
		return null
	var deviations: Array[String] = []
	for deviation: Variant in data["deviationIds"]:
		if not deviation is String or deviation.is_empty() or deviations.has(deviation):
			return null
		deviations.append(deviation)
	var state := GameState.from_data(data["gameState"])
	var random_state := RealmzRngState.from_data(data["rng"])
	var vm_state := ScenarioVmSnapshot.from_data(data["scenarioVm"])
	var action_state := ScenarioActionState.from_data(data["scenarioActionState"])
	if state == null or random_state == null or vm_state == null or action_state == null:
		return null
	var typed_continuation: SessionContinuation = null
	if not data["sessionContinuation"].is_empty():
		typed_continuation = SessionContinuation.from_data(data["sessionContinuation"])
		if typed_continuation == null:
			return null
	var typed_battle_return: SessionContinuation = null
	if not data["battleReturnContinuation"].is_empty():
		typed_battle_return = SessionContinuation.from_data(data["battleReturnContinuation"])
		if typed_battle_return == null or typed_battle_return.kind != &"post-clock":
			return null
	var session_request: InteractionRequest = null
	if not data["sessionInteraction"].is_empty():
		session_request = InteractionRequest.from_data(data["sessionInteraction"])
		if session_request == null or not _json_safe(session_request.body.to_data(), 0):
			return null
	var envelope := SaveEnvelope.new(data["campaignId"], data["packageHash"], data["rulesVersion"], revision, state, random_state, vm_state, action_state, typed_continuation, typed_battle_return, session_request)
	envelope.deviation_ids = deviations
	return envelope


static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1


static func _json_safe(value: Variant, depth: int) -> bool:
	if depth > 32:
		return false
	if value == null or value is bool or value is int or value is float or value is String:
		return true
	if value is Array:
		if value.size() > 4096:
			return false
		for child: Variant in value:
			if not _json_safe(child, depth + 1):
				return false
		return true
	if value is Dictionary:
		if value.size() > 4096:
			return false
		for key: Variant in value.keys():
			if not key is String or not _json_safe(value[key], depth + 1):
				return false
		return true
	return false

		return false
	for index: int in value.length():
		var code := value.unicode_at(index)
		var valid := (code >= 48 and code <= 57) or (code >= 65 and code <= 90) or (code >= 97 and code <= 122) or code == 45 or code == 95
		if not valid:
			return false
	return true


func _reject(message: String) -> bool:
	_last_error = message
	return false


func _validation_failure() -> PackageLoadResult:
	if _last_error == "Package operation cancelled.":
		return PackageLoadResult.failed(&"package_cancelled", _last_error)
	return PackageLoadResult.failed("package_validation_failed", _last_error if not _last_error.is_empty() else "Package validation failed.")


func _report_progress(callback: Callable, phase: StringName, completed: int, total: int) -> void:
	if callback.is_valid():
		callback.call(phase, completed, total)


func _cancel_requested(callback: Callable) -> bool:
	return callback.is_valid() and bool(callback.call())

class_name SaveRepository
extends RefCounted

const SaveSlotPreviewScript := preload("res://src/core/view/save_slot_preview.gd")

var _root_path: String
var last_error: String = ""


func _init(root_path: String = "user://saves") -> void:
	_root_path = root_path.trim_suffix("/")


func save(campaign_id: String, slot_id: String, snapshot: SessionSnapshot) -> bool:
	last_error = ""
	if snapshot == null or snapshot.campaign_id != campaign_id:
		return _fail("Save envelope does not match the requested campaign.")
	var envelope := SaveEnvelope.from_snapshot(snapshot)
	if envelope == null:
		return _fail("The session snapshot could not be encoded.")
	if not _safe_component(campaign_id) or not _safe_component(slot_id):
		return _fail("Campaign and slot IDs must be portable path components.")
	var campaign_path := "%s/%s" % [_root_path, campaign_id]
	var create_error := DirAccess.make_dir_recursive_absolute(ProjectSettings.globalize_path(campaign_path))
	if create_error != OK:
		return _fail("Could not create the campaign save directory (error %d)." % create_error)
	var slot_path := "%s/%s.r2save" % [campaign_path, slot_id]
	var temp_path := slot_path + ".tmp"
	var backup_path := slot_path + ".bak"
	var file := FileAccess.open(temp_path, FileAccess.WRITE)
	if file == null:
		return _fail("Could not open the temporary save file.")
	file.store_string(JSON.stringify(envelope.to_data()))
	file.flush()
	file.close()
	var verified := _read_envelope(temp_path)
	if verified == null or verified.campaign_id != envelope.campaign_id or verified.package_hash != envelope.package_hash:
		_delete_file(temp_path)
		return _fail("Temporary save verification failed.")
	if FileAccess.file_exists(backup_path) and not _delete_file(backup_path):
		_delete_file(temp_path)
		return _fail("Could not rotate the previous save backup.")
	var absolute_slot := ProjectSettings.globalize_path(slot_path)
	var absolute_backup := ProjectSettings.globalize_path(backup_path)
	var absolute_temp := ProjectSettings.globalize_path(temp_path)
	if FileAccess.file_exists(slot_path):
		var backup_error := DirAccess.rename_absolute(absolute_slot, absolute_backup)
		if backup_error != OK:
			_delete_file(temp_path)
			return _fail("Could not move the current save to its backup (error %d)." % backup_error)
	var replace_error := DirAccess.rename_absolute(absolute_temp, absolute_slot)
	if replace_error != OK:
		if FileAccess.file_exists(backup_path):
			DirAccess.rename_absolute(absolute_backup, absolute_slot)
		_delete_file(temp_path)
		return _fail("Could not atomically install the verified save (error %d)." % replace_error)
	return true


func load(campaign_id: String, slot_id: String, expected_package_hash: String) -> SaveEnvelope:
	return _load_path(campaign_id, slot_id, expected_package_hash, false)


func load_backup(campaign_id: String, slot_id: String, expected_package_hash: String) -> SaveEnvelope:
	return _load_path(campaign_id, slot_id, expected_package_hash, true)


func list_previews(campaign_id: String, expected_package_hash: String) -> Array:
	last_error = ""
	var previews: Array = []
	if not _safe_component(campaign_id):
		_fail("Campaign ID must be a portable path component.")
		return previews
	var campaign_path := "%s/%s" % [_root_path, campaign_id]
	if not DirAccess.dir_exists_absolute(ProjectSettings.globalize_path(campaign_path)):
		return previews
	for file_name: String in DirAccess.get_files_at(campaign_path):
		var source: StringName = SaveSlotPreviewScript.PRIMARY
		var slot_id := ""
		if file_name.ends_with(".r2save.bak"):
			source = SaveSlotPreviewScript.BACKUP
			slot_id = file_name.trim_suffix(".r2save.bak")
		elif file_name.ends_with(".r2save"):
			slot_id = file_name.trim_suffix(".r2save")
		else:
			continue
		if not _safe_component(slot_id):
			continue
		previews.append(_preview_for_path(campaign_path.path_join(file_name), slot_id, source, campaign_id, expected_package_hash))
	previews.sort_custom(func(left: RefCounted, right: RefCounted) -> bool:
		if left.slot_id != right.slot_id:
			return left.slot_id.naturalnocasecmp_to(right.slot_id) < 0
		return left.source == SaveSlotPreviewScript.PRIMARY and right.source == SaveSlotPreviewScript.BACKUP
	)
	return previews


func _load_path(campaign_id: String, slot_id: String, expected_package_hash: String, backup: bool) -> SaveEnvelope:
	last_error = ""
	if not _safe_component(campaign_id) or not _safe_component(slot_id):
		_fail("Campaign and slot IDs must be portable path components.")
		return null
	var suffix := ".r2save.bak" if backup else ".r2save"
	var path := "%s/%s/%s%s" % [_root_path, campaign_id, slot_id, suffix]
	var envelope := _read_envelope(path)
	if envelope == null:
		var incompatibility := _incompatible_schema_message(path)
		_fail(incompatibility if not incompatibility.is_empty() else ("Save backup is missing or corrupt." if backup else "Save file is missing or corrupt."))
		return null
	if envelope.campaign_id != campaign_id or envelope.package_hash != expected_package_hash:
		_fail("Save package identity does not match the installed campaign.")
		return null
	return envelope


func _preview_for_path(path: String, slot_id: String, source: StringName, expected_campaign_id: String, expected_package_hash: String) -> RefCounted:
	var envelope := _read_envelope(path)
	if envelope == null:
		var incompatibility := _incompatible_schema_message(path)
		var corrupt := SaveSlotPreviewScript.new(slot_id, source, SaveSlotPreviewScript.INCOMPATIBLE if not incompatibility.is_empty() else SaveSlotPreviewScript.CORRUPT)
		corrupt.modified_unix = int(FileAccess.get_modified_time(path))
		corrupt.error_message = incompatibility if not incompatibility.is_empty() else "This save is corrupt."
		return corrupt
	var status: StringName = SaveSlotPreviewScript.VALID
	var error_message := ""
	if envelope.campaign_id != expected_campaign_id:
		status = SaveSlotPreviewScript.CAMPAIGN_MISMATCH
		error_message = "This save belongs to campaign '%s'." % envelope.campaign_id
	elif envelope.package_hash != expected_package_hash:
		status = SaveSlotPreviewScript.PACKAGE_MISMATCH
		error_message = "This save was created for a different immutable package revision."
	var preview := SaveSlotPreviewScript.new(slot_id, source, status)
	preview.campaign_id = envelope.campaign_id
	preview.package_hash = envelope.package_hash
	preview.rules_version = envelope.rules_version
	preview.view_revision = envelope.view_revision
	preview.modified_unix = int(FileAccess.get_modified_time(path))
	preview.realmz_day = envelope.game_state.clock.day()
	preview.realmz_hour = envelope.game_state.clock.hour()
	preview.realmz_minute = envelope.game_state.clock.minute()
	preview.map_id = envelope.game_state.party.map_id
	preview.coordinate = envelope.game_state.party.coordinate
	for character: CharacterState in envelope.game_state.party.characters():
		preview.character_names.append(character.name)
	preview.error_message = error_message
	preview.can_load = status == SaveSlotPreviewScript.VALID
	return preview


func _read_envelope(path: String) -> SaveEnvelope:
	var data: Variant = _read_document(path)
	return SaveEnvelope.from_data(data) if data != null else null


func _read_document(path: String) -> Variant:
	if not FileAccess.file_exists(path):
		return null
	var file := FileAccess.open(path, FileAccess.READ)
	if file == null:
		return null

class_name SettingsRepository
extends RefCounted

var settings_path: String
var last_error: String = ""


func _init(path: String = "user://settings.json") -> void:
	settings_path = path


func load_settings() -> PresentationSettings:
	last_error = ""
	if not FileAccess.file_exists(settings_path):
		return PresentationSettings.new()
	var text := FileAccess.get_file_as_string(settings_path)
	var parsed: Variant = JSON.parse_string(text)
	var settings := PresentationSettings.from_data(parsed)
	if settings == null:
		last_error = "Presentation settings are malformed; defaults were restored."
		return PresentationSettings.new()
	return settings


func save_settings(settings: PresentationSettings) -> bool:
	last_error = ""
	if settings == null:
		last_error = "Presentation settings are missing."
		return false
	var directory := settings_path.get_base_dir()
	if not directory.is_empty() and DirAccess.make_dir_recursive_absolute(ProjectSettings.globalize_path(directory)) != OK:
		last_error = "Could not create the presentation settings directory."
		return false
	var temporary_path := settings_path + ".tmp"
	var file := FileAccess.open(temporary_path, FileAccess.WRITE)
	if file == null:
		last_error = "Could not open the temporary presentation settings file."
		return false
	file.store_string(CanonicalJson.encode(settings.to_data()))
	file.flush()
	file.close()
	var readback := PresentationSettings.from_data(JSON.parse_string(FileAccess.get_file_as_string(temporary_path)))
	if readback == null:
		DirAccess.remove_absolute(ProjectSettings.globalize_path(temporary_path))
		last_error = "Presentation settings failed readback validation."
		return false
	if FileAccess.file_exists(settings_path) and DirAccess.remove_absolute(ProjectSettings.globalize_path(settings_path)) != OK:
		DirAccess.remove_absolute(ProjectSettings.globalize_path(temporary_path))
		last_error = "Could not replace the previous presentation settings."
		return false
	if DirAccess.rename_absolute(ProjectSettings.globalize_path(temporary_path), ProjectSettings.globalize_path(settings_path)) != OK:
		last_error = "Could not commit presentation settings."
		return false
	return true

class_name ApplicationMediaCatalog
extends MediaSource

const MANIFEST_PATH := "res://src/presentation/assets/classic-application-media.json"
const CASTLE_SOURCE_COMMIT := "491816ad60037394f92c428e99c004494d3c28b3"

var source_commit: String = ""
var last_error: String = ""
var _assets: Array[MediaAsset] = []
var _assets_by_id: Dictionary = {}
var _assets_by_resource: Dictionary = {}
var _ambiguous_resource_keys: Dictionary = {}


func _init(manifest_path: String = MANIFEST_PATH) -> void:
	_load_manifest(manifest_path)


func is_valid() -> bool:
	return last_error.is_empty() and not _assets.is_empty()


func assets() -> Array[MediaAsset]:
	return _assets.duplicate()


func asset_by_id(asset_id: String) -> MediaAsset:
	return _assets_by_id.get(asset_id) as MediaAsset


func asset_by_resource(resource_type: String, resource_id: int) -> MediaAsset:
	if resource_type.is_empty():
		return null
	return _assets_by_resource.get(_resource_key(resource_type, resource_id)) as MediaAsset


func resource_status(resource_type: String, resource_id: int) -> StringName:
	if resource_type.is_empty():
		return &"missing"
	var key := _resource_key(resource_type, resource_id)
	if _ambiguous_resource_keys.has(key):
		return &"ambiguous"
	return &"resolved" if _assets_by_resource.has(key) else &"missing"


func owns_asset(asset: MediaAsset) -> bool:
	return asset != null and _assets.has(asset)


func read_bytes(asset: MediaAsset) -> PackedByteArray:
	if not owns_asset(asset):
		return PackedByteArray()
	var bytes := FileAccess.get_file_as_bytes(asset.path)
	if bytes.size() != asset.byte_count or _sha256(bytes) != asset.sha256:
		return PackedByteArray()
	return bytes


func audio_stream(asset: MediaAsset) -> AudioStream:
	if not owns_asset(asset) or not asset.is_sound():
		return null
	return load(asset.path) as AudioStream


func _load_manifest(manifest_path: String) -> void:
	var parsed: Variant = JSON.parse_string(FileAccess.get_file_as_string(manifest_path))
	if not parsed is Dictionary:
		last_error = "Classic application media manifest is unavailable or malformed."
		return
	var manifest := parsed as Dictionary
	if int(manifest.get("schema_version", 0)) != 1 or String(manifest.get("lookup", "")) != "scenario-first-application-fallback":
		last_error = "Classic application media manifest contract is unsupported."
		return
	source_commit = String(manifest.get("source_commit", ""))
	if source_commit != CASTLE_SOURCE_COMMIT:
		last_error = "Classic application media source revision is unsupported."
		return
	for value: Variant in manifest.get("assets", []):
		if not value is Dictionary:
			last_error = "Classic application media contains a malformed asset."
			return
		var record := value as Dictionary
		var asset := MediaAsset.new(
			String(record.get("id", "")),
			String(record.get("label", "")),
			String(record.get("kind", "")),
			String(record.get("mime_type", "")),
			String(record.get("resource_type", "")),
			int(record.get("resource_id", 0)),
			int(record.get("bytes", 0)),
			String(record.get("sha256", "")),
			String(record.get("path", "")),
			int(record.get("width", 0)),
			int(record.get("height", 0)),
			int(record.get("duration_ms", 0)),
			int(record.get("sample_rate", 0)),
			int(record.get("channels", 0)),
			int(record.get("tile_width", 0)),
			int(record.get("tile_height", 0)),
			int(record.get("columns", 0)),
			int(record.get("rows", 0)),
			int(record.get("landlook", -1)),
			int(record.get("base_tile", -1))
		)
		if asset.id.is_empty() or asset.resource_type.is_empty() or asset.path.is_empty() or asset.byte_count <= 0 or asset.sha256.length() != 64:
			last_error = "Classic application media contains an incomplete asset."
			return
		if _assets_by_id.has(asset.id):
			last_error = "Classic application media contains duplicate asset IDs."
			return
		_assets.append(asset)
		_assets_by_id[asset.id] = asset
		var key := _resource_key(asset.resource_type, asset.resource_id)
		if _ambiguous_resource_keys.has(key):
			continue
		if _assets_by_resource.has(key):
			_assets_by_resource.erase(key)
			_ambiguous_resource_keys[key] = true
			last_error = "Classic application media contains duplicate resource keys."
			continue
		_assets_by_resource[key] = asset


static func _sha256(bytes: PackedByteArray) -> String:
	var hashing := HashingContext.new()
	if hashing.start(HashingContext.HASH_SHA256) != OK or hashing.update(bytes) != OK:
		return ""
	return hashing.finish().hex_encode()


static func _resource_key(resource_type: String, resource_id: int) -> String:
	return JSON.stringify([resource_type, resource_id])

	var parser := JSON.new()
	var parse_error := parser.parse(file.get_as_text())
	file.close()
	if parse_error != OK:
		return null
	return parser.data


func _incompatible_schema_message(path: String) -> String:
	var data: Variant = _read_document(path)
	if not data is Dictionary or data.get("format") != SaveEnvelope.FORMAT:
		return ""
	var version: Variant = data.get("formatVersion")
	if version is float and is_equal_approx(version, round(version)):
		version = int(version)
	if not version is int or version == SaveEnvelope.FORMAT_VERSION:
		return ""
	return "Save format v%d is incompatible with Realmz Rebuilt save v%d." % [version, SaveEnvelope.FORMAT_VERSION]


func _delete_file(path: String) -> bool:
	if not FileAccess.file_exists(path):
		return true
	return DirAccess.remove_absolute(ProjectSettings.globalize_path(path)) == OK


func _safe_component(value: String) -> bool:
	if value.is_empty() or value.length() > 128:
		return false
	for index: int in value.length():
		var code := value.unicode_at(index)
		var valid := (code >= 48 and code <= 57) or (code >= 65 and code <= 90) or (code >= 97 and code <= 122) or code == 45 or code == 95
		if not valid:
			return false
	return true


