func _validate_rule_references(races: Array[RaceDefinition], castes: Array[CasteDefinition], items: Array[ItemDefinition], spells: Array[SpellDefinition], monsters: Array[MonsterDefinition], battles: Array[BattleDefinition], treasures: Array[TreasureDefinition], shops: Array[ShopDefinition], message_ids: Dictionary) -> bool:
	var race_ids := _definition_ids(races)
	var caste_ids := _definition_ids(castes)
	var item_ids := _definition_ids(items)
	var monster_ids := _definition_ids(monsters)
	for item: ItemDefinition in items:
		if not item.cursed_item_id.is_empty() and not item_ids.has(item.cursed_item_id):
			return _reject("Item '%s' references unavailable cursed item '%s'." % [item.id, item.cursed_item_id])
		if not item.specific_race_id.is_empty() and not race_ids.has(item.specific_race_id):
			return _reject("Item '%s' references unavailable race '%s'." % [item.id, item.specific_race_id])
		if not item.specific_caste_id.is_empty() and not caste_ids.has(item.specific_caste_id):
			return _reject("Item '%s' references unavailable caste '%s'." % [item.id, item.specific_caste_id])
	for caste: CasteDefinition in castes:
		for item_id: String in caste.start_items():
			if not item_ids.has(item_id):
				return _reject("Caste '%s' references unavailable starting item '%s'." % [caste.id, item_id])
	if not _validate_monster_record_references(monsters, items, spells):
		return false
	for battle: BattleDefinition in battles:
		for slot: BattleMonsterSlotDefinition in battle.monster_slots():
			if not monster_ids.has(slot.monster_id):
				return _reject("Battle '%s' references unavailable monster '%s'." % [battle.id, slot.monster_id])
		for message_id: int in [battle.message_before_id, battle.message_after_id]:
			if message_id != 0 and not message_ids.has(absi(message_id)):
				return _reject("Battle '%s' references unavailable message %d." % [battle.id, message_id])
	for treasure: TreasureDefinition in treasures:
		for item_id: String in treasure.item_ids():
			if not item_ids.has(item_id):
				return _reject("Treasure '%s' references unavailable item '%s'." % [treasure.id, item_id])
	for shop: ShopDefinition in shops:
		for item_id: String in shop.item_ids():
			if not item_ids.has(item_id):
				return _reject("Shop '%s' references unavailable item '%s'." % [shop.id, item_id])
	return true

func _validate_monster_record_references(monsters: Array[MonsterDefinition], items: Array[ItemDefinition], spells: Array[SpellDefinition]) -> bool:
	var item_ids := _definition_ids(items)
	var spell_ids := _definition_ids(spells)
	for monster: MonsterDefinition in monsters:
		for spell_id: String in monster.spell_ids():
			if spell_id.is_empty():
				continue
			if not spell_ids.has(spell_id):
				return _reject("Monster '%s' references unavailable spell '%s'." % [monster.id, spell_id])
		for item_id: String in monster.item_ids():
			if not item_id.is_empty() and not item_ids.has(item_id):
				return _reject("Monster '%s' references unavailable item '%s'." % [monster.id, item_id])
		if not monster.weapon_id.is_empty() and not item_ids.has(monster.weapon_id):
			return _reject("Monster '%s' references unavailable weapon '%s'." % [monster.id, monster.weapon_id])
		for random_weapon_id: String in MonsterRules.random_weapon_item_ids(monster.random_weapon_table):
			if not item_ids.has(random_weapon_id):
				return _reject("Monster '%s' random weapon table %d can produce unavailable weapon '%s'." % [monster.id, monster.random_weapon_table, random_weapon_id])
	return true

func _validate_scenario_references(scenario: ScenarioDefinition, message_ids: Dictionary, encounters: Array[SimpleEncounterDefinition], complex_encounters: Array[ComplexEncounterDefinition], thief_encounters: Array[ThiefEncounterDefinition]) -> bool:
	var encounter_ids: Dictionary = {}
	for encounter: SimpleEncounterDefinition in encounters:
		encounter_ids[encounter.id] = true
		if not message_ids.has(absi(encounter.prompt_message_id)):
			return _reject("Simple Encounter %d references unavailable prompt message %d." % [encounter.id, encounter.prompt_message_id])
		for response: SimpleEncounterResponse in encounter.responses():
			if scenario.program_by_id(response.result_program_id) == null:
				return _reject("Simple Encounter %d response '%s' references unavailable result program '%s'." % [encounter.id, response.id, response.result_program_id])
	var complex_ids: Dictionary = {}
	var thief_ids: Dictionary = {}
	for thief_encounter: ThiefEncounterDefinition in thief_encounters:
		thief_ids[thief_encounter.id] = true
	for encounter: ComplexEncounterDefinition in complex_encounters:
		complex_ids[encounter.id] = true
		if not message_ids.has(absi(encounter.prompt_message_id)):
			return _reject("Complex Encounter %d references unavailable prompt message %d." % [encounter.id, encounter.prompt_message_id])
		for outcome: int in range(1, 5):
			if scenario.program_by_id(encounter.result_program_id(outcome)) == null:
				return _reject("Complex Encounter %d references unavailable result program %d." % [encounter.id, outcome])
		if encounter.thief and not thief_ids.has(encounter.thief_success):
			return _reject("Complex Encounter %d references unavailable Thief Encounter %d." % [encounter.id, encounter.thief_success])
	for program_id: String in scenario.program_ids():
		var program := scenario.program_by_id(program_id)
		for index: int in range(program.instruction_count()):
			var instruction: Variant = program.instruction_at(index)
			if not instruction is ClassicActionDefinition:
				continue
			match instruction.opcode:
				1:
					if not message_ids.has(absi(instruction.operand_id)):
						return _reject("Scenario program '%s' references unavailable message %d." % [program.id, instruction.operand_id])
				4:
					if not encounter_ids.has(instruction.operand_id):
						return _reject("Scenario program '%s' references unavailable Simple Encounter %d." % [program.id, instruction.operand_id])
				5:
					if not complex_ids.has(instruction.operand_id):
						return _reject("Scenario program '%s' references unavailable Complex Encounter %d." % [program.id, instruction.operand_id])
				39:
					if scenario.program_by_id("xap:%d" % instruction.operand_id) == null:
						return _reject("Scenario program '%s' references unavailable XAP %d." % [program.id, instruction.operand_id])
	return true


func _validate_timed_encounter_references(scenario: ScenarioDefinition, encounters: Array[TimedEncounterDefinition]) -> bool:
	for encounter: TimedEncounterDefinition in encounters:
		var expected_program_id := "xap:%d" % encounter.classic_macro_id
		var program := scenario.program_by_id(encounter.program_id)
		if encounter.program_id != expected_program_id or program == null or program.owner_kind != &"extra-action-point":
			return _reject("Timed Encounter %d references unavailable Classic XAP program '%s'." % [encounter.id, encounter.program_id])
	return true

func _validate_random_region_references(maps: Array[MapDefinition], scenario: ScenarioDefinition, battles: Array[BattleDefinition]) -> bool:
	var battle_ids: Dictionary = {}
	for battle: BattleDefinition in battles:
		battle_ids[battle.classic_id] = true
	for map: MapDefinition in maps:
		for region: RandomEncounterRegion in map.random_regions():
			var doors := region.random_doors()
			var door_percents := region.random_door_percents()
			for index: int in doors.size():
				if door_percents[index] != 0 and (doors[index] < 0 or scenario.program_by_id("xap:%d" % doors[index]) == null):
					return _reject("Random rectangle '%s' references unavailable XAP %d." % [region.id, doors[index]])
			if region.battle_minimum == 0:
				continue
			if region.battle_minimum < 1 or region.battle_maximum < region.battle_minimum:
				return _reject("Random rectangle '%s' has an invalid battle range." % region.id)
			for battle_id: int in range(region.battle_minimum, region.battle_maximum + 1):
				if not battle_ids.has(battle_id):
					return _reject("Random rectangle '%s' references unavailable battle %d." % [region.id, battle_id])
	return true

func _validate_player_map_opcode_references(scenario: ScenarioDefinition, world: WorldDefinition) -> bool:
	for program_id: String in scenario.program_ids():
		var program := scenario.program_by_id(program_id)
		for index: int in range(program.instruction_count()):
			var instruction: Variant = program.instruction_at(index)
			if instruction is ClassicActionDefinition and instruction.opcode == 29 and world.player_map_by_classic_id(absi(instruction.operand_id)) == null:
				_reject("Scenario program '%s' references unavailable player-map record %d." % [program.id, absi(instruction.operand_id)])
				return false
	return true

func _program_context(owner_kind: StringName) -> StringName:
	match owner_kind:
		&"simple-encounter-result", &"complex-encounter-result":
			return &"encounter"
		&"trigger", &"extra-action-point":
			return &"action"
	return &""

func _call_arguments_match(argument_names: Array[String], result_target: String, action: ScenarioActionDefinition) -> bool:
	if argument_names != action.parameter_names():
		return false
	if result_target.is_empty():
		return true
	return action.return_type != &"void" and _safe_identifier(result_target)

func _contexts_are_compatible(caller: ScenarioActionDefinition, called: ScenarioActionDefinition) -> bool:
	for context: StringName in caller.allowed_contexts():
		if not called.allows_context(context):
			return false
	return true

class_name PackageDecoderBase
extends RefCounted

var _diagnostic: Dictionary

func _init(diagnostic: Dictionary = {}) -> void:
	_diagnostic = diagnostic
	if not _diagnostic.has("message"):
		_diagnostic["message"] = ""

func clear_error() -> void:
	_diagnostic["message"] = ""

func error_message() -> String:
	return String(_diagnostic.get("message", ""))

func _has_fields(value: Dictionary, fields: Array[String], label: String) -> bool:
	for field: String in fields:
		if not value.has(field):
			return _reject("%s is missing required field '%s'." % [label, field])
	return true

func _is_sha256(value: Variant) -> bool:
	if not value is String or value.length() != 64:
		return false
	for character: String in value:
		if not character in "0123456789abcdef":
			return false
	return true

func _exact_fields(value: Dictionary, fields: Array[String]) -> bool:
	if value.size() != fields.size():
		return false
	for field: String in fields:
		if not value.has(field):
			return false
	return true

func _string_array(value: Variant, label: String) -> Variant:
	if not value is Array:
		_reject("%s must be an array." % label)
		return null
	var strings: Array[String] = []
	for item: Variant in value:
		if not item is String or item.is_empty() or strings.has(item):
			_reject("%s contains an invalid or duplicate ID." % label)
			return null
		strings.append(item)
	return strings

func _string_list(value: Variant, label: String, allow_empty: bool = false) -> Variant:
	if not value is Array or value.size() > 4096:
		_reject("%s must be a bounded array." % label)
		return null
	var strings: Array[String] = []
	for item: Variant in value:
		if not item is String or not allow_empty and item.is_empty():
			_reject("%s contains an invalid ID." % label)
			return null
		strings.append(item)
	return strings

func _fixed_string_list(value: Variant, expected_size: int, maximum_length: int, label: String) -> Variant:
	if not value is Array or value.size() != expected_size:
		_reject("%s must contain %d strings." % [label, expected_size])
		return null
	var strings: Array[String] = []
	for item: Variant in value:
		if not item is String or item.length() > maximum_length:
			_reject("%s contains an invalid string." % label)
			return null
		strings.append(item)
	return strings

func _fixed_or_empty_string_list(value: Variant, expected_size: int, maximum_length: int, label: String) -> Variant:
	if value is Array and value.is_empty():
		var empty_slots: Array[String] = []
		empty_slots.resize(expected_size)
		empty_slots.fill("")
		return empty_slots
	return _fixed_string_list(value, expected_size, maximum_length, label)

func _boolean_array(value: Variant, expected_size: int, label: String) -> Variant:
	if not value is Array or value.size() != expected_size:
		_reject("%s must contain %d booleans." % [label, expected_size])
		return null
	var booleans: Array[bool] = []
	for item: Variant in value:
		if not item is bool:
			_reject("%s contains a non-boolean." % label)
			return null
		booleans.append(item)
	return booleans

func _validated_integer_fields(record: Dictionary, fields: Array[String], label: String) -> Variant:
	var result: Dictionary = {}
	for field: String in fields:
		if not record.has(field) or not _is_integer(record[field]):
			_reject("%s field '%s' must be an integer." % [label, field])
			return null
		result[field] = _integer(record[field])
	return result

func _integers_in_range(values: Dictionary, fields: Array[String], minimum: int, maximum: int) -> bool:
	for field: String in fields:
		var value := int(values[field])
		if value < minimum or value > maximum:
			return false
	return true

func _array_values_in_range(values: Array[int], minimum: int, maximum: int) -> bool:
	for value: int in values:
		if value < minimum or value > maximum:
			return false
	return true

func _definition_identity(record: Dictionary, ids: Dictionary, _label: String, requires_name: bool = true) -> bool:
	if not record.get("id") is String or record["id"].is_empty() or requires_name and (not record.get("name") is String or record["name"].is_empty()) or ids.has(record["id"]):
		return false
	ids[record["id"]] = true
	return true

func _definition_ids(values: Array) -> Dictionary:
	var result: Dictionary = {}
	for value: Variant in values:
		result[value.id] = true
	return result

func _integer_array(value: Variant, expected_size: int, label: String) -> Variant:
	if not value is Array or value.size() != expected_size:
		_reject("%s must contain %d integers." % [label, expected_size])
		return null
	var integers: Array[int] = []
	for item: Variant in value:
		if not _is_integer(item):
			_reject("%s contains a non-integer." % label)
			return null
		integers.append(_integer(item))
	return integers

func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1

func _is_integer(value: Variant) -> bool:
	return value is int or value is float and is_equal_approx(value, round(value))

func _safe_identifier(value: String) -> bool:
	if value.is_empty():
		return false
	for index: int in value.length():
		var code := value.unicode_at(index)
		var lower := code >= 97 and code <= 122
		var digit := code >= 48 and code <= 57
		if not lower and not (digit and index > 0) and not (code == 95 and index > 0):
			return false
	return true

func _json_safe(value: Variant, depth: int) -> bool:
	if depth > 64:
		return false
	if value == null or value is bool or value is int or value is float or value is String:
		return true
	if value is Array:
		if value.size() > 4096:
			return false
		for child: Variant in value:
			if not _json_safe(child, depth + 1):
				return false
		return true
	if value is Dictionary:
		if value.size() > 4096:
			return false
		for key: Variant in value.keys():
			if not key is String or not _json_safe(value[key], depth + 1):
				return false
		return true
	return false

func _reject(message: String) -> bool:
	_diagnostic["message"] = message
	return false

class_name PackageDomainAssembler
extends PackageDecoderBase


func assemble(manifest: Dictionary, content: Dictionary, world: Dictionary, scenario: Dictionary, media_assets: Array[MediaAsset] = [], trusted_install: bool = false) -> RealmzContent:
	clear_error()
	var _content_decoder := PackageContentDecoder.new(_diagnostic)
	var _scenario_decoder := PackageScenarioDecoder.new(_diagnostic)
	var _world_decoder := PackageWorldDecoder.new(_diagnostic)
	var _reference_validator := PackageCrossReferenceValidator.new(_diagnostic)
	var _media_validator := PackageMediaValidatorResolver.new(_diagnostic)
	if not content.has("campaign") or not content["campaign"] is Dictionary or content["campaign"].get("id") != manifest["campaignId"]:
		_reject("Content campaign identity does not match the manifest.")
		return null
	var campaign_definition := _content_decoder._construct_campaign_definition(content["campaign"])
	if campaign_definition == null:
		return null
	var messages_value: Variant = _content_decoder._construct_messages(content.get("messages"))
	if messages_value == null:
		return null
	var messages: Array[MessageDefinition] = messages_value
	var option_labels_value: Variant = _content_decoder._construct_option_labels(content.get("optionLabels"))
	if option_labels_value == null:
		return null
	var option_labels: Array[OptionLabelDefinition] = option_labels_value
	var message_ids: Dictionary = {}
	for message: MessageDefinition in messages:
		message_ids[message.id] = true
	var encounters_value: Variant = _content_decoder._construct_simple_encounters(content.get("simpleEncounters"))
	if encounters_value == null:
		return null
	var simple_encounters: Array[SimpleEncounterDefinition] = encounters_value
	var complex_encounters_value: Variant = _content_decoder._construct_complex_encounters(content.get("complexEncounters"))
	var thief_encounters_value: Variant = _content_decoder._construct_thief_encounters(content.get("thiefEncounters"))
	var timed_encounters_value: Variant = _content_decoder._construct_timed_encounters(content.get("timedEncounters"))
	if complex_encounters_value == null or thief_encounters_value == null or timed_encounters_value == null:
		return null
	if not trusted_install and CanonicalJson.encode(content.get("timedEncounters")) != CanonicalJson.encode(world.get("timedEncounters")):
		_reject("Content and world timed-encounter inventories do not match.")
		return null
	var complex_encounters: Array[ComplexEncounterDefinition] = complex_encounters_value
	var thief_encounters: Array[ThiefEncounterDefinition] = thief_encounters_value
	var timed_encounters: Array[TimedEncounterDefinition] = timed_encounters_value
	var races_value: Variant = _content_decoder._construct_races(content.get("races"))
	var castes_value: Variant = _content_decoder._construct_castes(content.get("castes"))
	var items_value: Variant = _content_decoder._construct_items(content.get("items"))
	var spells_value: Variant = _content_decoder._construct_spells(content.get("spells"))
	var monsters_value: Variant = _content_decoder._construct_monsters(content.get("monsters"))
	var monster_sets_value: Variant = _content_decoder._construct_monster_sets(content.get("monsterSets"))
	var battles_value: Variant = _content_decoder._construct_battles(content.get("battles"))
	var treasures_value: Variant = _content_decoder._construct_treasures(content.get("treasures"))
	var shops_value: Variant = _content_decoder._construct_shops(content.get("shops"))
	if races_value == null or castes_value == null or items_value == null or spells_value == null or monsters_value == null or monster_sets_value == null or battles_value == null or treasures_value == null or shops_value == null:
		return null
	var races: Array[RaceDefinition] = races_value
	var castes: Array[CasteDefinition] = castes_value
	var items: Array[ItemDefinition] = items_value
	var spells: Array[SpellDefinition] = spells_value
	var monsters: Array[MonsterDefinition] = monsters_value
	var monster_sets: Dictionary = monster_sets_value
	var battles: Array[BattleDefinition] = battles_value
	var treasures: Array[TreasureDefinition] = treasures_value
	var shops: Array[ShopDefinition] = shops_value
	var all_monsters: Array[MonsterDefinition] = monsters.duplicate()
	var base_monster_ids := _definition_ids(monsters)
	for set_id: Variant in monster_sets:
		var set_monsters: Array[MonsterDefinition] = monster_sets[set_id]
		var covered_classic_ids: Dictionary = {}
		for monster: MonsterDefinition in set_monsters:
			covered_classic_ids["classic.monster.%d" % monster.classic_id] = true
			all_monsters.append(monster)
		if not trusted_install and covered_classic_ids.size() != base_monster_ids.size():
			_reject("Monster set %d does not define every packaged Classic monster." % int(set_id))
			return null
		for base_id: Variant in base_monster_ids if not trusted_install else []:
			if not covered_classic_ids.has(base_id):
				_reject("Monster set %d is missing Classic monster '%s'." % [int(set_id), base_id])
				return null
	if not trusted_install and not _media_validator._validate_monster_media(all_monsters, media_assets):
		return null
	var appearance_options := _media_validator._construct_character_appearance_options(media_assets, races)
	var scenario_definition := _scenario_decoder._construct_scenario(scenario, manifest["campaignId"])
	if scenario_definition == null:
		return null
	var triggers_value: Variant = _world_decoder._construct_triggers(world.get("triggers"), scenario_definition)
	if triggers_value == null:
		return null
	var triggers: Array[TriggerDefinition] = triggers_value
	if not trusted_install and not _reference_validator._validate_scenario_references(scenario_definition, message_ids, simple_encounters, complex_encounters, thief_encounters):
		return null
	if not trusted_install and not _reference_validator._validate_timed_encounter_references(scenario_definition, timed_encounters):
		return null
	if not trusted_install and not _reference_validator._validate_rule_references(races, castes, items, spells, monsters, battles, treasures, shops, message_ids):
		return null
	for set_id: Variant in monster_sets if not trusted_install else {}:
		if not _reference_validator._validate_monster_record_references(monster_sets[set_id], items, spells):
			return null
	var trigger_ids: Dictionary = {}
	for trigger: TriggerDefinition in triggers:
		if trigger_ids.has(trigger.id):
			_reject("Trigger ID '%s' is duplicated." % trigger.id)
			return null
		trigger_ids[trigger.id] = true
	var battle_terrain_sets_value: Variant = _world_decoder._construct_battle_terrain_sets(world.get("battleTerrainSets"))
	if battle_terrain_sets_value == null:
		return null
	var battle_terrain_sets: Array[BattleTerrainSetDefinition] = battle_terrain_sets_value
	var battle_terrain_sets_by_id: Dictionary = {}
	for terrain_set: BattleTerrainSetDefinition in battle_terrain_sets:
		battle_terrain_sets_by_id[terrain_set.id] = terrain_set
	var maps_value: Variant = _world_decoder._construct_maps(world.get("maps"), trigger_ids, battle_terrain_sets_by_id, not battles.is_empty(), not trusted_install)
	if maps_value == null:
		return null
	var maps: Array[MapDefinition] = maps_value
	var player_maps_value: Variant = _world_decoder._construct_player_maps(world.get("playerMaps"), maps, media_assets)
	if player_maps_value == null:
		return null
	var player_maps: Array[PlayerMapDefinition] = player_maps_value
	if not trusted_install and not _reference_validator._validate_random_region_references(maps, scenario_definition, battles):
		return null
	var transitions_value: Variant = _world_decoder._construct_transitions(world.get("transitions"), maps)
	if transitions_value == null:
		return null
	var transitions: Array[MapTransition] = transitions_value
	var world_definition := WorldDefinition.new(maps, transitions, battle_terrain_sets, player_maps)
	if not trusted_install and not _reference_validator._validate_player_map_opcode_references(scenario_definition, world_definition):
		return null
	var start: Variant = manifest.get("start")
	if not start is Dictionary or not start.get("mapId") is String or _integer(start.get("x")) < 0 or _integer(start.get("y")) < 0:
		_reject("Manifest start location is malformed.")
		return null
	var start_coordinate := Vector2i(_integer(start["x"]), _integer(start["y"]))
	var start_map := world_definition.map_by_id(start["mapId"])
	if start_map == null or not trusted_install and start_map.topology.cell_at(start_coordinate) == null:
		_reject("Manifest start location does not identify a topology cell.")
		return null
	for trigger: TriggerDefinition in triggers if not trusted_install else []:
		if not trigger.map_id.is_empty():
			var map := world_definition.map_by_id(trigger.map_id)
			if map == null or map.topology.cell_at(trigger.coordinate) == null:
				_reject("Trigger '%s' references an unavailable topology coordinate." % trigger.id)
				return null
		if trigger.post_action_location != null:
			var destination_map := world_definition.map_by_id(trigger.post_action_location.map_id)
			if destination_map == null or destination_map.topology.cell_at(trigger.post_action_location.coordinate) == null:
				_reject("Trigger '%s' references an unavailable post-action location." % trigger.id)
				return null
	return RealmzContent.new(manifest["campaignId"], manifest["packageHash"], manifest["contentId"], manifest["engine"]["rulesVersion"], start["mapId"], start_coordinate, world_definition, scenario_definition, messages, triggers, simple_encounters, races, castes, items, spells, monsters, battles, treasures, shops, complex_encounters, thief_encounters, timed_encounters, option_labels, campaign_definition, appearance_options, monster_sets_value)

class_name PackageRepository
extends RefCounted

const EXPECTED_SCHEMA_HASH: String = "6ef382e35335ba91fc72a94c4600633f68255ad30651a4da195e134887e05bdb"
const DECODER_VERSION: int = 5
const REQUIRED_DOCUMENTS: Array[String] = ["assets/index.json", "content.json", "scenario.json", "world.json"]
const SUPPORTED_CAPABILITIES: Array[String] = [
	"realmz.core.classic-rules-v1",
	"realmz.presentation.content-addressed-media-v1",
	"realmz.presentation.battle-atlas-v1",
	"realmz.presentation.tileset-atlases-v1",
	"realmz.scenario.classic-vm-v1",
	"realmz.scenario.safe-actions-v1",
	"realmz.world.topology-v2",
]
const DEFERRED_PACKAGE_CAPABILITIES: Array[String] = [
	"realmz.scenario.gdscript-actions-v1",
]

var _last_error: String = ""
var _package_cache := PackageGraphCache.new()
var _receipt_store := PackageInstallReceiptStore.new(EXPECTED_SCHEMA_HASH, DECODER_VERSION)
var _archive_reader := PackageArchiveReader.new()
var _manifest_discovery := PackageManifestDiscovery.new(EXPECTED_SCHEMA_HASH, SUPPORTED_CAPABILITIES, DEFERRED_PACKAGE_CAPABILITIES, _archive_reader)
var _media_validator := PackageMediaValidatorResolver.new()
var _domain_assembler := PackageDomainAssembler.new()


func promote_installed_package(path: String) -> void:
	var receipt := _receipt_store.read(path)
	if receipt.is_empty() or not _receipt_store.validate_archive_sha256(receipt, _archive_reader.sha256_file(path)):
		return
	_package_cache.promote(_receipt_store.cache_key(path, receipt))


func retained_package_count() -> int:
	return _package_cache.retained_count()


func close() -> void:
	_package_cache.clear()


func load_package(path: String, progress_callback: Callable = Callable(), cancel_callback: Callable = Callable()) -> PackageLoadResult:
	_last_error = ""
	if _cancel_requested(cancel_callback):
		return PackageLoadResult.failed(&"package_cancelled", "Package operation cancelled.")
	_report_progress(progress_callback, &"opening", 0, 1)
	var archive := ZIPReader.new()
	var open_error := archive.open(path)
	if open_error != OK:
		return PackageLoadResult.failed("package_open_failed", "Could not open package '%s' (error %d)." % [path, open_error])
	var result := _load_open_archive(archive, path, progress_callback, cancel_callback)
	archive.close()
	if result.is_ok():
		_report_progress(progress_callback, &"complete", 1, 1)
	return result


func load_bundled_package(path: String, expected_campaign_id: String, expected_package_hash: String) -> PackageLoadResult:
	_last_error = ""
	if expected_campaign_id.is_empty() or not _safe_path_component(expected_campaign_id) or not _is_sha256(expected_package_hash):
		return PackageLoadResult.failed(&"bundled_package_identity_invalid", "The bundled package identity is invalid.")
	var cache_key := "bundled:%s:%s:%s:%d" % [ProjectSettings.globalize_path(path).simplify_path(), expected_package_hash, EXPECTED_SCHEMA_HASH, DECODER_VERSION]
	var cached := _package_cache.get_result(cache_key)
	if cached != null:
		return cached
	var archive := ZIPReader.new()
	var open_error := archive.open(path)
	if open_error != OK:
		return PackageLoadResult.failed(&"package_open_failed", "Could not open bundled package '%s' (error %d)." % [path, open_error])
	# This immutable package is generated by Providence and its identity is pinned
	# in the application source. Release signing protects the shipped bytes, so
	# startup verifies the canonical manifest identity but does not rehash every
	# bundled portrait and combat icon on every launch.
	var trusted_identity := {
		"schemaHash": EXPECTED_SCHEMA_HASH,
		"campaignId": expected_campaign_id,
		"packageHash": expected_package_hash,
	}
	var result := _load_open_archive(archive, path, Callable(), Callable(), trusted_identity)
	archive.close()
	if result.is_ok():
		_package_cache.retain_candidate(cache_key, result)
	return result


func install_package(source_path: String, install_root: String = "user://packages", progress_callback: Callable = Callable(), cancel_callback: Callable = Callable()) -> PackageInstallResult:
	var installed_source := _load_installed_package(source_path, install_root, progress_callback, cancel_callback)
	if installed_source != null:
		if installed_source.is_ok():
			_report_progress(progress_callback, &"complete", 1, 1)
			return PackageInstallResult.succeeded(source_path, installed_source)
		return PackageInstallResult.failed(installed_source.error_code, installed_source.error_message)
	_report_progress(progress_callback, &"validating-source", 0, 1)
	var source := load_package(source_path, progress_callback, cancel_callback)
	if not source.is_ok():
		return PackageInstallResult.failed(source.error_code, source.error_message)
	if _cancel_requested(cancel_callback):
		return PackageInstallResult.failed(&"package_cancelled", "Package operation cancelled.")
	if not _safe_path_component(source.content.campaign_id):
		return PackageInstallResult.failed("campaign_path_unsafe", "Campaign ID cannot be used as a portable installation path.")
	var campaign_root := install_root.trim_suffix("/").path_join(source.content.campaign_id)
	var create_error := DirAccess.make_dir_recursive_absolute(ProjectSettings.globalize_path(campaign_root))
	if create_error != OK:
		return PackageInstallResult.failed("package_install_directory_failed", "Could not create the package installation directory (error %d)." % create_error)
	var target_path := campaign_root.path_join("%s.realmz2" % source.content.package_hash)
	if FileAccess.file_exists(target_path):
		if _same_package_path(source_path, target_path):
			if not _receipt_store.write(target_path, source.content, _archive_reader.sha256_file(target_path)):
				return PackageInstallResult.failed("package_receipt_write_failed", "Could not write the validated package installation receipt.")
			_report_progress(progress_callback, &"complete", 1, 1)
			return PackageInstallResult.succeeded(target_path, source)
		var existing := _load_installed_package(target_path, install_root, progress_callback, cancel_callback)
		if existing == null:
			existing = load_package(target_path, progress_callback, cancel_callback)
			if existing.is_ok() and not _receipt_store.write(target_path, existing.content, _archive_reader.sha256_file(target_path)):
				return PackageInstallResult.failed("package_receipt_write_failed", "Could not write the validated package installation receipt.")
		if existing.is_ok() and existing.content.package_hash == source.content.package_hash:
			_report_progress(progress_callback, &"complete", 1, 1)
			return PackageInstallResult.succeeded(target_path, existing)
		return PackageInstallResult.failed("package_install_collision", "An invalid package already occupies the immutable installation path.")
	_report_progress(progress_callback, &"copying-package", 0, 1)
	var temporary_path := target_path + ".installing"
	if FileAccess.file_exists(temporary_path):
		DirAccess.remove_absolute(ProjectSettings.globalize_path(temporary_path))
	var source_bytes := FileAccess.get_file_as_bytes(source_path)
	if source_bytes.is_empty():
		return PackageInstallResult.failed("package_install_read_failed", "Could not read the source package for installation.")
	var temporary := FileAccess.open(temporary_path, FileAccess.WRITE)
	if temporary == null:
		return PackageInstallResult.failed("package_install_write_failed", "Could not open the temporary package installation file.")
	temporary.store_buffer(source_bytes)
	temporary.flush()
	temporary.close()
	if _cancel_requested(cancel_callback):
		DirAccess.remove_absolute(ProjectSettings.globalize_path(temporary_path))
		return PackageInstallResult.failed(&"package_cancelled", "Package operation cancelled.")
	_report_progress(progress_callback, &"validating-install", 0, 1)
	var archive_sha256 := _archive_reader.sha256(source_bytes)
	var installed_bytes := FileAccess.get_file_as_bytes(temporary_path)
	if installed_bytes.size() != source_bytes.size() or _archive_reader.sha256(installed_bytes) != archive_sha256:
		DirAccess.remove_absolute(ProjectSettings.globalize_path(temporary_path))
		return PackageInstallResult.failed("package_install_readback_failed", "Temporary package installation failed byte-for-byte readback validation.")
	var rename_error := DirAccess.rename_absolute(ProjectSettings.globalize_path(temporary_path), ProjectSettings.globalize_path(target_path))
	if rename_error != OK:
		DirAccess.remove_absolute(ProjectSettings.globalize_path(temporary_path))
		return PackageInstallResult.failed("package_install_commit_failed", "Could not atomically install the verified package (error %d)." % rename_error)
	if not _receipt_store.write(target_path, source.content, archive_sha256):
		DirAccess.remove_absolute(ProjectSettings.globalize_path(target_path))
		return PackageInstallResult.failed("package_receipt_write_failed", "Could not write the validated package installation receipt.")
	var installed := PackageLoadResult.succeeded(source.content, PackageMediaCatalog.new(target_path, source.content.package_hash, source.media.assets()))
	var receipt := _receipt_store.read(target_path)
	if not receipt.is_empty():
		_package_cache.retain_candidate(_receipt_store.cache_key(target_path, receipt), installed)
	_report_progress(progress_callback, &"complete", 1, 1)
	return PackageInstallResult.succeeded(target_path, installed)


