class_name PackageGraphCache
extends RefCounted

var _active_key: String = ""
var _active_result: PackageLoadResult
var _candidate_key: String = ""
var _candidate_result: PackageLoadResult


func get_result(key: String) -> PackageLoadResult:
	if key == _active_key:
		return _active_result
	if key == _candidate_key:
		return _candidate_result
	return null


func retain_candidate(key: String, result: PackageLoadResult) -> void:
	if key.is_empty() or result == null or not result.is_ok():
		return
	if key == _active_key:
		_active_result = result
		return
	_candidate_key = key
	_candidate_result = result


func promote(key: String) -> void:
	if key.is_empty() or key == _active_key:
		return
	if key != _candidate_key:
		return
	_active_key = _candidate_key
	_active_result = _candidate_result
	_candidate_key = ""
	_candidate_result = null


func clear_candidate() -> void:
	_candidate_key = ""
	_candidate_result = null


func clear() -> void:
	_active_key = ""
	_active_result = null
	clear_candidate()


func retained_count() -> int:
	var count := 0
	if _active_result != null:
		count += 1
	if _candidate_result != null:
		count += 1
	return count

class_name PackageManifestDiscovery
extends RefCounted

const REQUIRED_DOCUMENTS: Array[String] = ["assets/index.json", "content.json", "scenario.json", "world.json"]

var last_error: String = ""
var _expected_schema_hash: String
var _supported_capabilities: Array[String]
var _deferred_capabilities: Array[String]
var _archive_reader: PackageArchiveReader


func _init(expected_schema_hash: String, supported_capabilities: Array[String], deferred_capabilities: Array[String], archive_reader: PackageArchiveReader) -> void:
	_expected_schema_hash = expected_schema_hash
	_supported_capabilities = supported_capabilities.duplicate()
	_deferred_capabilities = deferred_capabilities.duplicate()
	_archive_reader = archive_reader


func discover_packages(search_roots: Array[String]) -> Array[PackageDiscoveryResult]:
	var paths: Array[String] = []
	for root: String in search_roots:
		_collect_paths(root, paths, 0)
	paths.sort()
	var discovered: Array[PackageDiscoveryResult] = []
	for path: String in paths:
		discovered.append(inspect(path))
	return discovered


func discover_campaigns(search_roots: Array[String]) -> Array[PackageDiscoveryResult]:
	var selected_by_campaign: Dictionary = {}
	var rejected_by_key: Dictionary = {}
	var visible: Array[PackageDiscoveryResult] = []
	for candidate: PackageDiscoveryResult in discover_packages(search_roots):
		if not candidate.ready:
			var rejection_key := candidate.campaign_id if not candidate.campaign_id.is_empty() else "error:%s" % candidate.error_message
			var selected_rejection := rejected_by_key.get(rejection_key) as PackageDiscoveryResult
			if selected_rejection == null or _revision_is_newer(candidate, selected_rejection):
				rejected_by_key[rejection_key] = candidate
			continue
		var selected := selected_by_campaign.get(candidate.campaign_id) as PackageDiscoveryResult
		if selected == null or _revision_is_newer(candidate, selected):
			selected_by_campaign[candidate.campaign_id] = candidate
	var campaign_ids: Array[String] = []
	campaign_ids.assign(selected_by_campaign.keys())
	campaign_ids.sort()
	for campaign_id: String in campaign_ids:
		visible.append(selected_by_campaign[campaign_id] as PackageDiscoveryResult)
	var rejection_keys: Array[String] = []
	rejection_keys.assign(rejected_by_key.keys())
	rejection_keys.sort()
	for rejection_key: String in rejection_keys:
		var rejected := rejected_by_key[rejection_key] as PackageDiscoveryResult
		if not rejected.campaign_id.is_empty() and selected_by_campaign.has(rejected.campaign_id):
			continue
		visible.append(rejected)
	return visible


func inspect(path: String) -> PackageDiscoveryResult:
	last_error = ""
	var archive := ZIPReader.new()
	var open_error := archive.open(path)
	if open_error != OK:
		return PackageDiscoveryResult.new(path, false, "", "", "", "Could not open package (error %d)." % open_error)
	var entries_value: Variant = _archive_reader.entries(archive)
	var manifest_value: Variant = _archive_reader.read_document(archive, "manifest.json")
	if entries_value == null or manifest_value == null:
		archive.close()
		return PackageDiscoveryResult.new(path, false, "", "", "", _archive_reader.last_error if not _archive_reader.last_error.is_empty() else "Package manifest is unavailable.")
	var entries: Array[String] = []
	entries.assign(entries_value)
	var manifest: Dictionary = manifest_value
	var campaign_id := String(manifest.get("campaignId", "")) if manifest.get("campaignId") is String else ""
	var package_hash := String(manifest.get("packageHash", "")) if manifest.get("packageHash") is String else ""
	var display_name := String(manifest.get("name", "")) if manifest.get("name") is String else ""
	var engine: Variant = manifest.get("engine")
	var rules_version := String(engine.get("rulesVersion", "")) if engine is Dictionary and engine.get("rulesVersion") is String else ""
	if not validate_structure(manifest, entries):
		archive.close()
		return PackageDiscoveryResult.new(path, false, campaign_id, package_hash, rules_version, last_error, display_name)
	archive.close()
	return PackageDiscoveryResult.new(path, true, campaign_id, package_hash, rules_version, "", display_name)


func validate_structure(manifest: Dictionary, archive_entries: Array[String]) -> bool:
	last_error = ""
	var required_fields: Array[String] = ["kind", "format", "formatVersion", "schemaVersion", "schemaHash", "campaignId", "contentId", "engine", "start", "capabilities", "files", "packageHash"]
	for field: String in required_fields:
		if not manifest.has(field):
			return _reject("manifest is missing required field '%s'." % field)
	if manifest["kind"] != "realmz2.manifest" or manifest["format"] != "realmz2" or not _is_integer(manifest["formatVersion"]) or int(manifest["formatVersion"]) != 2 or not _is_integer(manifest["schemaVersion"]) or int(manifest["schemaVersion"]) != 3:
		return _reject("Unsupported Realmz 2.0 package or schema version.")
	if manifest["schemaHash"] != _expected_schema_hash:
		return _reject("Package schema hash does not match the runtime contract mirror.")
	if not _is_sha256(manifest["packageHash"]) or not _is_sha256(manifest["contentId"]):
		return _reject("Manifest package/content identity is malformed.")
	if not manifest["campaignId"] is String or not _safe_path_component(manifest["campaignId"]):
		return _reject("Manifest campaign ID is missing.")
	if not manifest["engine"] is Dictionary or manifest["engine"].get("rulesVersion") != "realmz-classic-1":
		return _reject("Package requires an unsupported Realmz rules version.")
	if not manifest["capabilities"] is Array:
		return _reject("Manifest capabilities must be an array.")
	for capability: Variant in manifest["capabilities"]:
		var readiness_error := capability_error(capability)
		if not readiness_error.is_empty():
			return _reject(readiness_error)
	if not manifest["files"] is Dictionary:
		return _reject("Manifest file integrity table is missing.")
	var expected_entries: Array[String] = ["manifest.json"]
	for required: String in REQUIRED_DOCUMENTS:
		if not manifest["files"].has(required):
			return _reject("Manifest is missing required file '%s'." % required)
	for file_path: Variant in manifest["files"].keys():
		if not file_path is String or file_path.begins_with("/") or file_path.contains("..") or file_path.contains("\\"):
			return _reject("Manifest contains an unsafe package path.")
		var integrity: Variant = manifest["files"][file_path]
		if not integrity is Dictionary or not integrity.has("bytes") or not integrity.has("sha256") or not _is_sha256(integrity["sha256"]):
			return _reject("File integrity record for '%s' is malformed." % file_path)
		expected_entries.append(file_path)
	expected_entries.sort()
	if archive_entries != expected_entries:
		return _reject("ZIP entries do not exactly match the sorted manifest inventory.")
	var unhashed := manifest.duplicate(true)
	unhashed.erase("packageHash")
	if _archive_reader.sha256(CanonicalJson.encode(unhashed).to_utf8_buffer()) != manifest["packageHash"]:
		return _reject("Package hash does not match the canonical unhashed manifest.")
	return true


func capability_error(capability: Variant) -> String:
	if capability is String and _deferred_capabilities.has(capability):
		return "Package requires sandboxed GDScript Scenario Actions, but no secure external host is available on this platform."
	if not capability is String or not _supported_capabilities.has(capability):
		return "Package requires unknown capability '%s'." % str(capability)
	return ""


func _collect_paths(root: String, paths: Array[String], depth: int) -> void:
	if depth > 4 or not DirAccess.dir_exists_absolute(root):
		return
	for file_name: String in DirAccess.get_files_at(root):
		if file_name.to_lower().ends_with(".realmz2"):
			paths.append(root.path_join(file_name))
	for directory_name: String in DirAccess.get_directories_at(root):
		if not directory_name.begins_with("."):
			_collect_paths(root.path_join(directory_name), paths, depth + 1)


func _revision_is_newer(candidate: PackageDiscoveryResult, selected: PackageDiscoveryResult) -> bool:
	var candidate_modified := FileAccess.get_modified_time(candidate.path)
	var selected_modified := FileAccess.get_modified_time(selected.path)
	if candidate_modified != selected_modified:
		return candidate_modified > selected_modified
	return candidate.path.naturalnocasecmp_to(selected.path) > 0


func _safe_path_component(value: String) -> bool:
	return not value.is_empty() and value != "." and value != ".." and value.validate_filename() == value and not value.contains("/") and not value.contains("\\") and not value.contains(":")

func _is_sha256(value: Variant) -> bool:
	if not value is String or value.length() != 64:
		return false
	for character: String in value:
		if not character in "0123456789abcdef":
			return false
	return true


func _is_integer(value: Variant) -> bool:
	return value is int or value is float and is_equal_approx(value, roundf(value))


func _reject(message: String) -> bool:
	last_error = message
	return false

class_name PackageMediaCatalog
extends MediaSource

var package_path: String
var package_hash: String
var _assets: Array[MediaAsset]
var _assets_by_id: Dictionary = {}
var _assets_by_resource: Dictionary = {}
var _ambiguous_resource_keys: Dictionary = {}


func _init(source_path: String, content_hash: String, indexed_assets: Array[MediaAsset]) -> void:
	package_path = source_path
	package_hash = content_hash
	_assets = indexed_assets.duplicate()
	for asset: MediaAsset in _assets:
		_assets_by_id[asset.id] = asset
		if asset.resource_type.is_empty():
			continue
		var key := _resource_key(asset.resource_type, asset.resource_id)
		if _ambiguous_resource_keys.has(key):
			continue
		if _assets_by_resource.has(key):
			_assets_by_resource.erase(key)
			_ambiguous_resource_keys[key] = true
			continue
		_assets_by_resource[key] = asset


func assets() -> Array[MediaAsset]:
	return _assets.duplicate()


func assets_of_kind(kind: String) -> Array[MediaAsset]:
	var result: Array[MediaAsset] = []
	for asset: MediaAsset in _assets:
		if asset.kind == kind:
			result.append(asset)
	result.sort_custom(func(left: MediaAsset, right: MediaAsset) -> bool: return left.resource_id < right.resource_id)
	return result


func asset_by_id(asset_id: String) -> MediaAsset:
	return _assets_by_id.get(asset_id) as MediaAsset


func asset_by_resource(resource_type: String, resource_id: int) -> MediaAsset:
	if resource_type.is_empty():
		return null
	return _assets_by_resource.get(_resource_key(resource_type, resource_id)) as MediaAsset


func resource_status(resource_type: String, resource_id: int) -> StringName:
	if resource_type.is_empty():
		return &"missing"
	var key := _resource_key(resource_type, resource_id)
	if _ambiguous_resource_keys.has(key):
		return &"ambiguous"
	return &"resolved" if _assets_by_resource.has(key) else &"missing"


func owns_asset(asset: MediaAsset) -> bool:
	return asset != null and _assets.has(asset)


func tileset_by_id(tileset_id: String) -> MediaAsset:
	var asset := asset_by_id(tileset_id)
	return asset if asset != null and asset.is_tileset() else null


func battle_tileset() -> MediaAsset:
	var asset := asset_by_id("classic-battle-tiles-302")
	return asset if asset != null and asset.is_battle_tileset() else null


func resolution_diagnostic(resource_type: String, resource_id: int, presentation_role: String, decode_result: String = "not-attempted") -> Dictionary:
	var key := _resource_key(resource_type, resource_id)
	var diagnostic := {
		"authoredResourceType": resource_type,
		"authoredResourceId": resource_id,
		"presentationRole": presentation_role,
		"decodeResult": decode_result,
		"status": "missing",
		"packageAssetId": "",
		"sha256": "",
	}
	if _ambiguous_resource_keys.has(key):
		diagnostic["status"] = "ambiguous"
		return diagnostic
	var asset := asset_by_resource(resource_type, resource_id)
	if asset == null:
		return diagnostic
	diagnostic["status"] = "resolved"
	diagnostic["packageAssetId"] = asset.id
	diagnostic["sha256"] = asset.sha256
	return diagnostic


func read_bytes(asset: MediaAsset) -> PackedByteArray:
	if asset == null or not _assets.has(asset):
		return PackedByteArray()
	var archive := ZIPReader.new()
	if archive.open(package_path) != OK:
		return PackedByteArray()
	var bytes := archive.read_file(asset.path)
	archive.close()
	if bytes.size() != asset.byte_count:
		return PackedByteArray()
	var hashing := HashingContext.new()
	if hashing.start(HashingContext.HASH_SHA256) != OK or hashing.update(bytes) != OK:
		return PackedByteArray()
	if hashing.finish().hex_encode() != asset.sha256:
		return PackedByteArray()
	return bytes


func read_bytes_batch(requested_assets: Array[MediaAsset]) -> Dictionary:
	var result: Dictionary = {}
	if requested_assets.is_empty():
		return result
	var archive := ZIPReader.new()
	if archive.open(package_path) != OK:
		return result
	for asset: MediaAsset in requested_assets:
		if asset == null or not _assets.has(asset):
			continue
		var bytes := archive.read_file(asset.path)
		if bytes.size() != asset.byte_count:
			continue
		var hashing := HashingContext.new()
		if hashing.start(HashingContext.HASH_SHA256) != OK or hashing.update(bytes) != OK:
			continue
		if hashing.finish().hex_encode() == asset.sha256:
			result[asset.id] = bytes
	archive.close()
	return result


static func _resource_key(resource_type: String, resource_id: int) -> String:
	return JSON.stringify([resource_type, resource_id])

class_name PackageMediaValidatorResolver
extends PackageDecoderBase

func _validate_monster_media(monsters: Array[MonsterDefinition], media_assets: Array[MediaAsset]) -> bool:
	var assets_by_resource: Dictionary = {}
	for asset: MediaAsset in media_assets:
		if not asset.resource_type.is_empty():
			assets_by_resource[JSON.stringify([asset.resource_type, asset.resource_id])] = asset
	for monster: MonsterDefinition in monsters:
		if monster.icon_id <= 0:
			continue
		var asset := assets_by_resource.get(JSON.stringify(["cicn", monster.icon_id])) as MediaAsset
		if asset == null or asset.mime_type != "image/png" or asset.width < 1 or asset.height < 1:
			return _reject("Monster '%s' requires unavailable Classic cicn %d." % [monster.id, monster.icon_id])
	return true

func validate_assets(document: Dictionary, files: Dictionary) -> bool:
	if not document.get("assets") is Array:
		return _reject("Asset index must contain an assets array.")
	var ids: Dictionary = {}
	var resources: Dictionary = {}
	var portrait_resource_ids: Dictionary = {}
	var combat_icon_resource_ids: Dictionary = {}
	for asset: Variant in document["assets"]:
		if not asset is Dictionary or not _exact_fields(asset, ["id", "label", "kind", "mimeType", "resourceType", "resourceId", "bytes", "sha256", "path", "width", "height", "durationMs", "sampleRate", "channels", "tileWidth", "tileHeight", "columns", "rows", "landlook", "baseTile"]):
			return _reject("Asset index contains a malformed record.")
		if not asset["id"] is String or asset["id"].is_empty() or ids.has(asset["id"]) or not asset["label"] is String or not asset["kind"] is String:
			return _reject("Asset identities, labels, and kinds must be typed and unique.")
		ids[asset["id"]] = true
		if asset["mimeType"] != null and not asset["mimeType"] is String:
			return _reject("Asset MIME type must be a string or null.")
		if asset["resourceType"] != null and not asset["resourceType"] is String:
			return _reject("Asset resource type must be a string or null.")
		if asset["resourceId"] != null and not _is_integer(asset["resourceId"]):
			return _reject("Asset resource ID must be an integer or null.")
		for optional_integer: String in ["width", "height", "durationMs", "sampleRate", "channels", "tileWidth", "tileHeight", "columns", "rows", "landlook", "baseTile"]:
			if asset[optional_integer] != null and (not _is_integer(asset[optional_integer]) or _integer(asset[optional_integer]) < 0):
				return _reject("Asset %s must be a non-negative integer or null." % optional_integer)
		if asset["kind"] in ["tileset", "battle-tileset"]:
			for tileset_field: String in ["width", "height", "tileWidth", "tileHeight", "columns", "rows"]:
				if asset[tileset_field] == null or _integer(asset[tileset_field]) < 1:
					return _reject("Tileset asset '%s' has invalid %s metadata." % [asset["id"], tileset_field])
			if not String(asset["mimeType"]).begins_with("image/") or _integer(asset["width"]) != _integer(asset["tileWidth"]) * _integer(asset["columns"]) or _integer(asset["height"]) != _integer(asset["tileHeight"]) * _integer(asset["rows"]):
				return _reject("Tileset asset '%s' dimensions do not match its atlas grid." % asset["id"])
		if asset["kind"] == "battle-tileset" and (asset["id"] != "classic-battle-tiles-302" or asset["mimeType"] != "image/png" or asset["resourceType"] != null or asset["resourceId"] != null or _integer(asset["width"]) != 640 or _integer(asset["height"]) != 640 or _integer(asset["tileWidth"]) != 32 or _integer(asset["tileHeight"]) != 32 or _integer(asset["columns"]) != 20 or _integer(asset["rows"]) != 20):
			return _reject("Classic battle atlas must be the role-specific 640 by 640 PICT 302 tile grid.")
		if not _is_integer(asset["bytes"]) or _integer(asset["bytes"]) < 0 or not asset["path"] is String or not _is_sha256(asset["sha256"]) or not files.has(asset["path"]):
			return _reject("Asset index contains a malformed or untracked payload.")
		if not asset["path"].begins_with("assets/media/") or files[asset["path"]]["sha256"] != asset["sha256"] or _integer(files[asset["path"]]["bytes"]) != _integer(asset["bytes"]):
			return _reject("Asset payload identity does not match the manifest.")
		if asset["resourceType"] != null and asset["resourceId"] != null:
			var resource_key := JSON.stringify([asset["resourceType"], _integer(asset["resourceId"])])
			if resources.has(resource_key):
				return _reject("Asset resource identities must be unique.")
			resources[resource_key] = true
			if asset["resourceType"] == "cicn" and asset["kind"] == "portrait":
				portrait_resource_ids[_integer(asset["resourceId"])] = true
			if asset["resourceType"] == "cicn" and asset["kind"] == "combat-icon":
				combat_icon_resource_ids[_integer(asset["resourceId"])] = true
		if asset["kind"] in ["portrait", "combat-icon"]:
			if asset["resourceType"] != "cicn" or asset["resourceId"] == null or asset["mimeType"] != "image/png" or asset["width"] == null or _integer(asset["width"]) < 1 or asset["height"] == null or _integer(asset["height"]) < 1:
				return _reject("Character appearance asset '%s' must be a decoded Classic cicn PNG with positive dimensions." % asset["id"])
	for resource_id: int in range(257, 377):
		if not portrait_resource_ids.has(resource_id):
			return _reject("Character portrait catalog is missing Classic cicn %d." % resource_id)
	for resource_id: int in range(9000, 9120):
		if not combat_icon_resource_ids.has(resource_id):
			return _reject("Character combat-icon catalog is missing Classic cicn %d." % resource_id)
	return true

func validate_presentation_capabilities(manifest: Dictionary, assets: Dictionary) -> bool:
	var declares_battle_atlas: bool = manifest["capabilities"].has("realmz.presentation.battle-atlas-v1")
	var battle_atlas_count := 0
	for asset: Dictionary in assets["assets"]:
		if asset["kind"] == "battle-tileset":
			battle_atlas_count += 1
	if declares_battle_atlas != (battle_atlas_count == 1):
		return _reject("Battle-atlas capability and packaged battle artwork do not agree.")
	return true

func validate_render_references(assets: Dictionary, world: Dictionary) -> bool:
	var tileset_ids: Dictionary = {}
	var image_ids: Dictionary = {}
	for asset: Dictionary in assets["assets"]:
		if asset["kind"] == "tileset":
			tileset_ids[asset["id"]] = true
		if asset["mimeType"] is String and asset["mimeType"].begins_with("image/"):
			image_ids[asset["id"]] = true
	if not world.get("maps") is Array:
		return _reject("World maps must be available for tileset validation.")
	for map: Variant in world["maps"]:
		if not map is Dictionary or map.get("topologyFormat") != "realmz2.compact-cell-rows.v2" or not map.get("cells") is Array:
			return _reject("World map is malformed during tileset validation.")
		for cell: Variant in map["cells"]:
			if not cell is Array or cell.size() != 13 or not cell[9] is String:
				return _reject("Topology render facts are malformed during tileset validation.")
			if not tileset_ids.has(cell[9]):
				return _reject("Topology references missing tileset asset '%s'." % cell[9])
			var overlay_asset_id: Variant = cell[10]
			if overlay_asset_id != null and (not overlay_asset_id is String or not image_ids.has(overlay_asset_id)):
				return _reject("Topology references missing image overlay asset '%s'." % overlay_asset_id)
	return true

func construct_assets(document: Dictionary) -> Array[MediaAsset]:
	var assets: Array[MediaAsset] = []
	for record: Dictionary in document["assets"]:
		assets.append(MediaAsset.new(
			record["id"],
			record["label"],
			record["kind"],
			"" if record["mimeType"] == null else record["mimeType"],
			"" if record["resourceType"] == null else record["resourceType"],
			-1 if record["resourceId"] == null else _integer(record["resourceId"]),
			_integer(record["bytes"]),
			record["sha256"],
			record["path"],
			0 if record["width"] == null else _integer(record["width"]),
			0 if record["height"] == null else _integer(record["height"]),
			0 if record["durationMs"] == null else _integer(record["durationMs"]),
			0 if record["sampleRate"] == null else _integer(record["sampleRate"]),
			0 if record["channels"] == null else _integer(record["channels"]),
			0 if record["tileWidth"] == null else _integer(record["tileWidth"]),
			0 if record["tileHeight"] == null else _integer(record["tileHeight"]),
			0 if record["columns"] == null else _integer(record["columns"]),
			0 if record["rows"] == null else _integer(record["rows"]),
			-1 if record["landlook"] == null else _integer(record["landlook"]),
			-1 if record["baseTile"] == null else _integer(record["baseTile"]),
		))
	return assets

func _construct_character_appearance_options(assets: Array[MediaAsset], races: Array[RaceDefinition]) -> Array[CharacterAppearanceDefinition]:
	var result: Array[CharacterAppearanceDefinition] = []
	for asset: MediaAsset in assets:
		var kind := CharacterAppearanceDefinition.PORTRAIT if asset.kind == "portrait" else CharacterAppearanceDefinition.COMBAT_ICON if asset.kind == "combat-icon" else &""
		if kind == &"":
			continue
		var recommended_races: Array[String] = []
		for race: RaceDefinition in races:
			var first_resource_id: int
			if kind == CharacterAppearanceDefinition.PORTRAIT:
				first_resource_id = 257 if race.default_icon_set == 0 else 251 + race.default_icon_set * 6
			else:
				first_resource_id = 9000 + (race.classic_id - 1) * 6
			if asset.resource_id >= first_resource_id and asset.resource_id < first_resource_id + 6:
				recommended_races.append(race.id)
		result.append(CharacterAppearanceDefinition.new(asset.id, asset.label, kind, asset.resource_id, recommended_races))
	result.sort_custom(func(left: CharacterAppearanceDefinition, right: CharacterAppearanceDefinition) -> bool: return left.classic_resource_id < right.classic_resource_id)
	return result

class_name PackageInstallReceiptStore
extends RefCounted

const KIND: String = "realmz2.install-receipt"
const FORMAT_VERSION: int = 2

var schema_hash: String
var decoder_version: int
var last_error: String = ""


func _init(expected_schema_hash: String, expected_decoder_version: int) -> void:
	schema_hash = expected_schema_hash
	decoder_version = expected_decoder_version


func read(package_path: String) -> Dictionary:
	last_error = ""
	var receipt_path := path_for(package_path)
	if not FileAccess.file_exists(receipt_path):
		return {}
	var value: Variant = JSON.parse_string(FileAccess.get_file_as_string(receipt_path))
	if not value is Dictionary or not _validate(value, package_path):
		if last_error.is_empty():
			last_error = "Installed package receipt is invalid."
		return {}
	return value


func write(package_path: String, content: RealmzContent, archive_sha256: String) -> bool:
	last_error = ""
	if content == null or not _is_sha256(archive_sha256):
		last_error = "Installed package receipt identity is invalid."
		return false
	var receipt := {
		"kind": KIND,
		"formatVersion": FORMAT_VERSION,
		"decoderVersion": decoder_version,
		"schemaHash": schema_hash,
		"campaignId": content.campaign_id,
		"packageHash": content.package_hash,
		"archiveSha256": archive_sha256,
		"archiveBytes": FileAccess.get_size(package_path),
		"archiveModifiedTime": FileAccess.get_modified_time(package_path),
	}
	var receipt_path := path_for(package_path)
	var temporary_path := receipt_path + ".installing"
	if FileAccess.file_exists(temporary_path):
		DirAccess.remove_absolute(ProjectSettings.globalize_path(temporary_path))
	var file := FileAccess.open(temporary_path, FileAccess.WRITE)
	if file == null:
		last_error = "Could not open the temporary package receipt."
		return false
	file.store_string(CanonicalJson.encode(receipt))
	file.flush()
	file.close()
	var readback: Variant = JSON.parse_string(FileAccess.get_file_as_string(temporary_path))
	if not readback is Dictionary or CanonicalJson.encode(readback) != CanonicalJson.encode(receipt):
		DirAccess.remove_absolute(ProjectSettings.globalize_path(temporary_path))
		last_error = "Package receipt failed typed readback."
		return false
	if FileAccess.file_exists(receipt_path):
		DirAccess.remove_absolute(ProjectSettings.globalize_path(receipt_path))
	if DirAccess.rename_absolute(ProjectSettings.globalize_path(temporary_path), ProjectSettings.globalize_path(receipt_path)) != OK:
		DirAccess.remove_absolute(ProjectSettings.globalize_path(temporary_path))
		last_error = "Could not atomically commit the package receipt."
		return false
	return true


func cache_key(package_path: String, receipt: Dictionary) -> String:
	return "%s:%s:%s:%s:%d" % [
		ProjectSettings.globalize_path(package_path).simplify_path().to_lower(),
		receipt.get("packageHash", ""),
		receipt.get("archiveSha256", ""),
		receipt.get("schemaHash", ""),
		int(receipt.get("decoderVersion", -1)),
	]


func validate_archive_sha256(receipt: Dictionary, actual_sha256: String) -> bool:
	last_error = ""
	if not _is_sha256(actual_sha256):
		return _fail("Installed package archive could not be hashed.")
	if actual_sha256 != receipt.get("archiveSha256", ""):
		return _fail("Installed package SHA-256 no longer matches its validated receipt.")
	return true


static func path_for(package_path: String) -> String:
	return package_path + ".receipt.json"


func _validate(receipt: Dictionary, package_path: String) -> bool:
	var fields: Array[String] = ["kind", "formatVersion", "decoderVersion", "schemaHash", "campaignId", "packageHash", "archiveSha256", "archiveBytes", "archiveModifiedTime"]
	if not _exact_fields(receipt, fields):
		return _fail("Installed package receipt has an unsupported shape.")
	if receipt["kind"] != KIND or _integer(receipt["formatVersion"]) != FORMAT_VERSION:
		return _fail("Installed package receipt has an unsupported version.")
	if _integer(receipt["decoderVersion"]) != decoder_version:
		return _fail("Installed package receipt was created by an incompatible package decoder.")
	if receipt["schemaHash"] != schema_hash or not _safe_path_component(receipt["campaignId"]):
		return _fail("Installed package receipt does not match the runtime contract.")
	if not _is_sha256(receipt["packageHash"]) or not _is_sha256(receipt["archiveSha256"]):
		return _fail("Installed package receipt contains malformed identities.")
	if not _is_integer(receipt["archiveBytes"]) or _integer(receipt["archiveBytes"]) != FileAccess.get_size(package_path):
		return _fail("Installed package byte count no longer matches its validated receipt.")
	if not _is_integer(receipt["archiveModifiedTime"]) or _integer(receipt["archiveModifiedTime"]) != FileAccess.get_modified_time(package_path):
		return _fail("Installed package modification identity no longer matches its validated receipt.")
	if package_path.get_file().to_lower() != "%s.realmz2" % receipt["packageHash"]:
		return _fail("Installed package filename does not match its validated identity.")
	if package_path.get_base_dir().get_file().to_lower() != String(receipt["campaignId"]).to_lower():
		return _fail("Installed package campaign directory does not match its validated identity.")
	return true


func _fail(message: String) -> bool:
	last_error = message
	return false


static func _exact_fields(value: Dictionary, fields: Array[String]) -> bool:
	if value.size() != fields.size():
		return false
	for field: String in fields:
		if not value.has(field):
			return false
	return true


static func _integer(value: Variant) -> int:
	return int(value) if _is_integer(value) else -1


static func _is_integer(value: Variant) -> bool:
	return typeof(value) == TYPE_INT or (typeof(value) == TYPE_FLOAT and value == floor(value))


static func _is_sha256(value: Variant) -> bool:
	if not value is String or value.length() != 64:
		return false
	for character: String in value:
		if not character in "0123456789abcdef":
			return false
	return true


static func _safe_path_component(value: Variant) -> bool:
	if not value is String or value.is_empty() or value in [".", ".."]:
		return false
	if value.contains("/") or value.contains("\\") or value.contains(":"):
		return false
	return value == value.get_file() and not value.is_absolute_path()

class_name ClassicAudioPresenter
extends Node

signal sound_observed(sound_id: int)
signal blocking_state_changed(blocking: bool)
signal music_state_changed(playlist_id: int, title: String, playing: bool)

const CHANNEL_COUNT: int = 4

var last_sound_id: int = 0
var master_volume: float = 1.0
var sound_volume: float = 1.0
var music_volume: float = 0.8
var current_music_playlist_id: int = 0
var current_music_title: String = ""
var last_media_diagnostic: Dictionary = {}
var _players: Array[AudioStreamPlayer] = []
var _channel_index: int = -1
var _pending_sounds: Array[Dictionary] = []
var _processing_sounds: bool = false
var _waiting_player: AudioStreamPlayer
var _waiting_finished_callback: Callable
var _music_player: AudioStreamPlayer


func _ready() -> void:
	for index: int in range(CHANNEL_COUNT):
		var player := AudioStreamPlayer.new()
		player.name = "ClassicSoundChannel%d" % (index + 1)
		_players.append(player)
		add_child(player)
	_music_player = AudioStreamPlayer.new()
	_music_player.name = "ClassicMusicChannel"
	add_child(_music_player)
	_apply_volume()


func present_events(events: Array[DomainEvent], media: ClassicMediaCatalog) -> void:
	for event: DomainEvent in events:
		if event.kind != &"sound_requested":
			continue
		if bool(event.payload.get("stopExisting", false)):
			_stop_all()
		last_sound_id = int(event.payload.get("soundId", 0))
		sound_observed.emit(last_sound_id)
		if media == null:
			continue
		var asset := media.asset_by_resource("snd ", last_sound_id)
		if asset == null:
			last_media_diagnostic = media.resolution_diagnostic("snd ", last_sound_id, "classic-sound")
			continue
		var stream := media.audio_stream_by_resource("snd ", last_sound_id)
		last_media_diagnostic = media.resolution_diagnostic("snd ", last_sound_id, "classic-sound", "decoded" if stream != null else "decode-failed")
		if stream == null:
			continue
		_pending_sounds.append({"stream": stream, "waitForCompletion": bool(event.payload.get("waitForCompletion", false))})
	_drain_sound_queue()


func present_sound(sound_id: int, media: ClassicMediaCatalog, wait_for_completion: bool = false, stop_existing: bool = false) -> void:
	present_events([DomainEvent.new(&"sound_requested", {"soundId": sound_id, "waitForCompletion": wait_for_completion, "stopExisting": stop_existing, "source": "classic-presentation-workspace"})], media)


func set_master_volume(value: float) -> void:
	master_volume = clampf(value, 0.0, 1.0)
	_apply_volume()


func set_sound_volume(value: float) -> void:
	sound_volume = clampf(value, 0.0, 1.0)
	_apply_volume()


func set_music_volume(value: float) -> void:
	music_volume = clampf(value, 0.0, 1.0)
	_apply_volume()


func present_music_context(playlist_id: int, settings: PresentationSettings, media: ClassicMediaCatalog, stock_music: ClassicMusicCatalog) -> void:
	if settings == null or not settings.music_enabled or playlist_id <= 0:
		stop_music()
		return
	var mode := settings.music_mode(playlist_id)
	if mode == PresentationSettings.MUSIC_CONTINUE:
		return
	if mode == PresentationSettings.MUSIC_OFF:
		stop_music()
		return
	if current_music_playlist_id == playlist_id and _music_player != null and _music_player.playing:
		return
	var stream: AudioStream
	var title := ""
	if media != null:
		var package_asset := media.asset_by_resource("music", playlist_id)
		if package_asset != null:
			stream = media.audio_stream_by_resource("music", playlist_id)
			title = package_asset.label
	if stream == null and stock_music != null:
		stream = stock_music.stream(playlist_id)
		title = stock_music.title(playlist_id)
	if stream == null:
		return
	_music_player.stop()
	_music_player.stream = stream
	if _music_player.is_inside_tree():
		_music_player.play()
	current_music_playlist_id = playlist_id
	current_music_title = title if not title.is_empty() else ClassicMusicContext.context_name(playlist_id)
	music_state_changed.emit(current_music_playlist_id, current_music_title, true)


func stop_music() -> void:
	if _music_player != null:
		_music_player.stop()
	var changed := current_music_playlist_id != 0 or not current_music_title.is_empty()
	current_music_playlist_id = 0
	current_music_title = ""
	if changed:
		music_state_changed.emit(0, "", false)


func is_blocking() -> bool:
	return _processing_sounds


func _apply_volume() -> void:
	for player: AudioStreamPlayer in _players:
		var effective_sound := master_volume * sound_volume
		player.volume_db = -80.0 if effective_sound <= 0.0 else linear_to_db(effective_sound)
	if _music_player != null:
		var effective_music := master_volume * music_volume
		_music_player.volume_db = -80.0 if effective_music <= 0.0 else linear_to_db(effective_music)


func _drain_sound_queue() -> void:
	if _processing_sounds:
		return
	while not _pending_sounds.is_empty():
		var request: Dictionary = _pending_sounds.pop_front()
		var player := _next_channel()
		if player == null:
			continue
		player.stop()
		player.stream = request["stream"] as AudioStream
		player.play()
		if bool(request["waitForCompletion"]) and player.playing:
			_processing_sounds = true
			blocking_state_changed.emit(true)
			_waiting_player = player
			_waiting_finished_callback = _on_waiting_sound_finished.bind(player)
			player.finished.connect(_waiting_finished_callback, CONNECT_ONE_SHOT)
			return


func _on_waiting_sound_finished(player: AudioStreamPlayer) -> void:
	if player != _waiting_player:
		return
	_waiting_player = null
	_waiting_finished_callback = Callable()
	_processing_sounds = false

	blocking_state_changed.emit(false)
	_drain_sound_queue()


func _next_channel() -> AudioStreamPlayer:
	if _players.is_empty():
		return null
	_channel_index = (_channel_index + 1) % _players.size()
	return _players[_channel_index]


func _stop_all() -> void:
	var was_blocking := _processing_sounds
	if _waiting_player != null and _waiting_finished_callback.is_valid() and _waiting_player.finished.is_connected(_waiting_finished_callback):
		_waiting_player.finished.disconnect(_waiting_finished_callback)
	_waiting_player = null
	_waiting_finished_callback = Callable()
	_processing_sounds = false
	_pending_sounds.clear()
	for player: AudioStreamPlayer in _players:
		player.stop()
	if was_blocking:
		blocking_state_changed.emit(false)

class_name InteractionComponent
extends VBoxContainer

signal response_body_submitted(body: InteractionResponse.Body)
@warning_ignore("unused_signal")
signal combat_targeting_requested(request: CombatTargetingRequest)
@warning_ignore("unused_signal")
signal combat_targeting_confirm_requested
@warning_ignore("unused_signal")
signal combat_targeting_cancel_requested
@warning_ignore("unused_signal")
signal combatant_focus_requested(combatant_id: String, play_sound: bool)
@warning_ignore("unused_signal")
signal reveal_friends_requested
@warning_ignore("unused_signal")
signal presentation_sound_requested(sound_id: int)
@warning_ignore("unused_signal")
signal presentation_status_requested(text: String, is_error: bool)
@warning_ignore("unused_signal")
signal combat_spellbook_requested(actor_id: String, options: Array[InteractionRequestValue.CastOption])
@warning_ignore("unused_signal")
signal combat_spellbook_closed
@warning_ignore("unused_signal")
signal side_workspace_requested(workspace: Control)
@warning_ignore("unused_signal")
signal side_workspace_closed


func build(_request: InteractionRequest) -> void:
	pass


func handle_back() -> bool:
	return false


func preferred_initial_focus() -> Control:
	return null


func add_response(label: String, body: InteractionResponse.Body, enabled: bool = true, reason: String = "") -> Button:
	return add_response_to(self, label, body, enabled, reason)


func add_response_to(parent: Container, label: String, body: InteractionResponse.Body, enabled: bool = true, reason: String = "") -> Button:
	var button := Button.new()
	button.text = label
	button.custom_minimum_size.y = 36.0
	button.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	button.disabled = not enabled
	button.tooltip_text = reason
	button.pressed.connect(func() -> void: response_body_submitted.emit(body))
	parent.add_child(button)
	return button


func add_hint(text: String) -> Label:
	var label := Label.new()
	label.text = text
	label.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
	label.add_theme_color_override("font_color", Color("d5b45d"))
	add_child(label)
	return label


func character_option(value: Variant) -> OptionButton:
	var picker := OptionButton.new()
	picker.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	if value is Array:
		for character: Variant in value:
			if character is Dictionary:
				picker.add_item(String(character.get("name", "Character")))
				picker.set_item_metadata(picker.item_count - 1, String(character.get("id", "")))
			elif character is InteractionRequestValue.ServiceCharacter:
				picker.add_item(character.name)
				picker.set_item_metadata(picker.item_count - 1, character.id)
	return picker

	_spell_record_title = _label("", GOLD, 18)
	_spell_record_title.theme_type_variation = &"ClassicHeading"
	record_content.add_child(_spell_record_title)
	_spell_record_cost = _label("", CYAN, 15)
	record_content.add_child(_spell_record_cost)
	_spell_record_state = _label("", MUTED, 14)
	record_content.add_child(_spell_record_state)
	var spacer := Control.new()
	spacer.size_flags_vertical = Control.SIZE_EXPAND_FILL
	action_content.add_child(spacer)
	var confirm := Button.new()
	confirm.name = "LevelSpellConfirm"
	confirm.text = "Confirm spell selection"
	confirm.theme_type_variation = &"ClassicTheldrowButton"
	confirm.custom_minimum_size.y = 44.0
	confirm.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	confirm.pressed.connect(_submit_spells.bind(body))
	action_content.add_child(confirm)
	if not body.spells.is_empty():
		var initial_spell := _first_spell_at_level(body, _selected_level)
		_refresh_spell_record(initial_spell)
	_refresh_spell_selection(body)


func _build_spell_level_rail(parent: HBoxContainer, body: InteractionRequest.LevelUpRequestBody, available_levels: Array[int]) -> void:
	var panel := PanelContainer.new()
	panel.name = "LevelSpellLevelRail"
	panel.theme_type_variation = &"ClassicTextWell"
	panel.custom_minimum_size.x = 112.0
	panel.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	panel.size_flags_vertical = Control.SIZE_EXPAND_FILL
	panel.size_flags_stretch_ratio = 0.45
	parent.add_child(panel)
	var rail := VBoxContainer.new()
	rail.add_theme_constant_override("separation", 4)
	panel.add_child(rail)
	rail.add_child(SpellSelectionChrome.level_heading())
	var group := ButtonGroup.new()
	for level: int in range(1, 8):
		var button := SpellSelectionChrome.level_button(level, level == _selected_level, available_levels.has(level), _select_spell_level.bind(body, level), "No learnable level %d spells" % level)
		button.name = "LevelSpellLevel%d" % level
		button.button_group = group
		button.size_flags_horizontal = Control.SIZE_EXPAND_FILL
		rail.add_child(button)


func _rebuild_spell_list(body: InteractionRequest.LevelUpRequestBody) -> void:
	if _spell_list == null:
		return
	for child: Node in _spell_list.get_children():
		_spell_list.remove_child(child)
		child.queue_free()
	_spell_buttons.clear()
	var spells := _spells_at_level(body, _selected_level)
	_spell_list_heading.text = "Level %d — Available Spells" % _selected_level
	for spell: InteractionRequestValue.SpellChoice in spells:
		var button := SpellSelectionChrome.spell_button("LevelSpell_%s" % spell.id, "%s  •  %d point%s" % [spell.name, spell.cost, "" if spell.cost == 1 else "s"], _selected_spell_ids.has(spell.id), true, spell.name, _toggle_spell.bind(body, spell.id), _spell_icon(body.character_id, spell.id))
		button.theme_type_variation = &"ClassicTheldrowButton"
		button.set_meta(&"spell_id", spell.id)
		_spell_buttons[spell.id] = button
		_spell_list.add_child(button)


func _select_spell_level(body: InteractionRequest.LevelUpRequestBody, level: int) -> void:
	_selected_level = level
	_rebuild_spell_list(body)
	var spell := _first_spell_at_level(body, level)
	if spell != null:
		_refresh_spell_record(spell)


func _available_spell_levels(body: InteractionRequest.LevelUpRequestBody) -> Array[int]:
	var levels: Array[int] = []
	for spell: InteractionRequestValue.SpellChoice in body.spells:
		var level := ClassicSpellLevelScript.from_classic_id(spell.classic_id)
		if not levels.has(level):
			levels.append(level)
	levels.sort()
	return levels


func _spells_at_level(body: InteractionRequest.LevelUpRequestBody, level: int) -> Array[InteractionRequestValue.SpellChoice]:
	var spells: Array[InteractionRequestValue.SpellChoice] = []
	for spell: InteractionRequestValue.SpellChoice in body.spells:
		if ClassicSpellLevelScript.from_classic_id(spell.classic_id) == level:
			spells.append(spell)
	return spells


func _first_spell_at_level(body: InteractionRequest.LevelUpRequestBody, level: int) -> InteractionRequestValue.SpellChoice:
	var spells := _spells_at_level(body, level)
	return spells[0] if not spells.is_empty() else null


func _toggle_spell(body: InteractionRequest.LevelUpRequestBody, spell_id: String) -> void:
	var button := _spell_buttons.get(spell_id) as Button
	if button == null:
		return
	if button.button_pressed and not _selected_spell_ids.has(spell_id):
		_selected_spell_ids.append(spell_id)
	elif not button.button_pressed:
		_selected_spell_ids.erase(spell_id)
	for spell: InteractionRequestValue.SpellChoice in body.spells:
		if spell.id == spell_id:
			_refresh_spell_record(spell)
			break
	_refresh_spell_selection(body)


func _refresh_spell_selection(body: InteractionRequest.LevelUpRequestBody) -> void:
	if _selection_summary == null:
		return
	var points := 0
	for spell: InteractionRequestValue.SpellChoice in body.spells:
		if _selected_spell_ids.has(spell.id):
			points += spell.cost
	_selection_summary.text = "Selected %d / %d points" % [points, body.point_total]


func _refresh_spell_record(spell: InteractionRequestValue.SpellChoice) -> void:
	if _spell_record_title == null:
		return
	_spell_record_title.text = spell.name
	_spell_record_cost.text = "%d selection point%s" % [spell.cost, "" if spell.cost == 1 else "s"]
	_spell_record_state.text = "Selected" if _selected_spell_ids.has(spell.id) else "Available"


func _submit_spells(body: InteractionRequest.LevelUpRequestBody) -> void:
	var selected_ids: Array[String] = []
	for spell: InteractionRequestValue.SpellChoice in body.spells:
		if _selected_spell_ids.has(spell.id):
			selected_ids.append(spell.id)
	response_body_submitted.emit(InteractionResponse.LevelUpBody.new(&"confirm-spells", body.character_id, selected_ids))


func _build_header(title: String, subtitle: String) -> void:
	var row := HBoxContainer.new()
	row.name = "LevelHeader"
	row.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	add_child(row)
	var heading := _label(title, GOLD, 20)
	heading.theme_type_variation = &"ClassicHeading"
	heading.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	row.add_child(heading)
	var context := _label(subtitle, CYAN, 15)
	context.horizontal_alignment = HORIZONTAL_ALIGNMENT_RIGHT
	row.add_child(context)


func _pane(parent: HBoxContainer, pane_name: String, title: String, ratio: float) -> VBoxContainer:
	var panel := PanelContainer.new()
	panel.name = pane_name
	panel.theme_type_variation = &"ClassicTextWell"
	panel.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	panel.size_flags_vertical = Control.SIZE_EXPAND_FILL
	panel.size_flags_stretch_ratio = ratio
	parent.add_child(panel)
	var content := VBoxContainer.new()
	content.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	content.size_flags_vertical = Control.SIZE_EXPAND_FILL

	content.add_theme_constant_override("separation", 5)
	panel.add_child(content)
	var heading := _label(title, GOLD, 16)
	heading.theme_type_variation = &"ClassicHeading"
	content.add_child(heading)
	return content


func _label(text: String, color: Color, size: int) -> Label:
	var label := Label.new()
	label.text = text
	label.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
	label.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	label.add_theme_color_override("font_color", color)
	label.add_theme_font_size_override("font_size", size)
	return label


func _character(character_id: String) -> CharacterView:
	if _game_view == null:
		return null
	for character: CharacterView in _game_view.party_members:
		if character.id == character_id:
			return character
	return null


func _portrait(character_id: String) -> Texture2D:
	var character := _character(character_id)
	return _media.image_texture(_media.asset_by_id(character.portrait_id)) if character != null and _media != null and not character.portrait_id.is_empty() else null


func _spell_icon(character_id: String, spell_id: String) -> Texture2D:
	var character := _character(character_id)
	if character == null or _media == null:
		return null
	for spell: SpellView in character.spells:
		if spell.id == spell_id and spell.icon_id > 0:
			return _media.image_texture(_media.asset_by_resource(spell.icon_resource_type, spell.icon_id))
	return null

extends InteractionComponent

var _can_cancel: bool = false


func build(request: InteractionRequest) -> void:
	_can_cancel = false
	if request.kind != InteractionRequest.SESSION_LIFECYCLE:
		return
	var body := request.body as InteractionRequest.LifecycleRequestBody
	if body == null: return
	var compact_quit := body.operation == &"quit-application"
	if not compact_quit:
		var context := Label.new()
		context.name = "LifecycleConsequence"
		context.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
		context.text = "Saving is unavailable during battle." if body.in_combat else "Save first, or end this adventure without saving."
		add_child(context)
	var action_host: Container = self
	if compact_quit:
		var actions := HBoxContainer.new()
		actions.name = "LifecycleActions"
		actions.alignment = BoxContainer.ALIGNMENT_CENTER
		actions.add_theme_constant_override("separation", 8)
		add_child(actions)
		action_host = actions
	for option: InteractionRequestValue.LifecycleOption in body.options:
		var action := option.action
		var label := option.label.strip_edges()
		if action.is_empty() or label.is_empty():
			continue
		_can_cancel = _can_cancel or action == &"cancel"
		var button := add_response_to(action_host, label, InteractionResponse.LifecycleBody.new(action))
		if compact_quit:
			button.custom_minimum_size = Vector2(128.0 if action == &"save-and-quit" else 88.0, 38.0)
			button.size_flags_horizontal = Control.SIZE_SHRINK_CENTER
		if action in [&"save-and-end", &"save-and-quit"]:
			button.theme_type_variation = &"ClassicChoiceButton"
		elif action in [&"end-without-saving", &"quit-without-saving"]:
			button.add_theme_color_override("font_color", Color("d48a78"))
			button.add_theme_color_override("font_hover_color", Color("efaa98"))


func handle_back() -> bool:
	if not _can_cancel:
		return false
	response_body_submitted.emit(InteractionResponse.LifecycleBody.new(&"cancel"))
	return true

class_name PickLockTumbler
extends Control

const ClassicPickLockRulesScript := preload("res://src/core/rules/classic_pick_lock_rules.gd")

var marker_position: int = 10
var yellow_threshold: int = 100
var green_threshold: int = 150


func _init() -> void:
	custom_minimum_size = Vector2(360.0, 34.0)
	mouse_filter = Control.MOUSE_FILTER_IGNORE


func configure(position_value: int, yellow: int, green: int) -> void:
	marker_position = position_value
	yellow_threshold = yellow
	green_threshold = green
	queue_redraw()


func _draw() -> void:
	var track := Rect2(2.0, 7.0, size.x - 4.0, size.y - 14.0)
	draw_rect(track, Color("6b2d2d"), true)
	var yellow_x := track.position.x + track.size.x * float(yellow_threshold) / float(ClassicPickLockRulesScript.TRACK_END)
	var green_x := track.position.x + track.size.x * float(green_threshold) / float(ClassicPickLockRulesScript.TRACK_END)
	draw_rect(Rect2(yellow_x, track.position.y, maxf(0.0, green_x - yellow_x), track.size.y), Color("80672d"), true)
	draw_rect(Rect2(green_x, track.position.y, maxf(0.0, track.end.x - green_x), track.size.y), Color("285b43"), true)
	var marker_x := track.position.x + track.size.x * float(marker_position) / float(ClassicPickLockRulesScript.TRACK_END)
	draw_line(Vector2(marker_x, 2.0), Vector2(marker_x, size.y - 2.0), Color("f2d36b"), 3.0)
	draw_rect(track, Color("626a70"), false, 1.0)

class_name SelectionInteraction
extends InteractionComponent

const SpellTargetBadge := preload("res://src/presentation/classic_spell_target_badge.gd")

const GOLD := Color("e0bc53")
const TEXT := Color("d7d9dc")
const CYAN := Color("8fcfd1")
const MUTED := Color("9ca3ad")

var _checks: Array[CheckButton] = []
var _media: ClassicMediaCatalog
var _game_view: GameView
var _ally_summary: Label
var _ally_maximum := 0


func configure(media: ClassicMediaCatalog, game_view: GameView = null) -> void:
	_media = media
	_game_view = game_view


func build(request: InteractionRequest) -> void:
	if request.kind == &"character_selection":
		_build_character_selection(request)
	else:
		_build_ally_selection(request)


func _build_character_selection(request: InteractionRequest) -> void:
	var body := request.body as InteractionRequest.CharacterSelectionRequestBody
	if body == null: return
	if body.spell_context != null:
		_add_spell_target_context(body.spell_context)
	add_hint("Pick %d party member%s from the Party roster." % [body.count, "" if body.count == 1 else "s"])


func _add_spell_target_context(context: InteractionRequestValue.SpellTargetContext) -> void:
	var panel := PanelContainer.new()
	panel.name = "SpellTargetContext"
	panel.theme_type_variation = &"ClassicInset"
	panel.tooltip_text = context.description
	var row := HBoxContainer.new()
	row.add_theme_constant_override("separation", 8)
	var icon_texture := _spell_icon(context)
	if icon_texture != null:
		var icon := TextureRect.new()
		icon.custom_minimum_size = Vector2(48.0, 48.0)
		icon.texture = icon_texture
		icon.expand_mode = TextureRect.EXPAND_IGNORE_SIZE
		icon.stretch_mode = TextureRect.STRETCH_KEEP_ASPECT_CENTERED
		icon.texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST
		row.add_child(icon)
	var facts := VBoxContainer.new()
	facts.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	facts.add_theme_constant_override("separation", 1)
	facts.add_child(_label(context.spell_name, GOLD, 16))
	var source_label: String = String({&"field-spell": "Memorized spell", &"scroll-use": "Scroll", &"item-use": "Item magic"}.get(context.source_kind, "Spell"))
	var cost_label := " • Cost %d SP" % context.spell_point_cost if context.spell_point_cost > 0 else ""
	facts.add_child(_label("%s • Power %d%s" % [source_label, context.power, cost_label], TEXT, 12))
	facts.add_child(_label("%s • %d target%s" % [_target_label(context.target_type), context.target_count, "" if context.target_count == 1 else "s"], MUTED, 12))
	row.add_child(facts)
	var target_badge := SpellTargetBadge.new()
	if target_badge.present(context.target_type, context.target_size, _target_label(context.target_type), Vector2(48.0, 48.0)):
		row.add_child(target_badge)
	else:
		target_badge.free()
	panel.add_child(row)
	add_child(panel)


func _spell_icon(context: InteractionRequestValue.SpellTargetContext) -> Texture2D:
	if _media == null or context.icon_id <= 0:
		return null
	return _media.image_texture(_media.asset_by_resource(context.icon_resource_type, context.icon_id))


static func _target_label(target_type: int) -> String:
	return {0: "Up to power", 1: "Party member", 3: "Fixed area", 4: "Power-sized area", 5: "Caster", 7: "Party state", 9: "All friendly", 10: "All enemies", 12: "Everybody"}.get(target_type, "Classic target type %d" % target_type)


static func _label(text: String, color: Color, size: int) -> Label:
	var label := Label.new()
	label.text = text
	label.text_overrun_behavior = TextServer.OVERRUN_TRIM_ELLIPSIS
	label.add_theme_color_override("font_color", color)
	label.add_theme_font_size_override("font_size", size)
	return label


func _build_ally_selection(request: InteractionRequest) -> void:
	var body := request.body as InteractionRequest.SelectionRequestBody
	if body == null:
		return
	_ally_maximum = body.maximum
	size_flags_vertical = Control.SIZE_EXPAND_FILL
	custom_minimum_size = Vector2(0.0, 320.0)
	add_theme_constant_override("separation", 6)
	var header := HBoxContainer.new()
	header.name = "AllySelectionHeader"
	header.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	add_child(header)
	var title := _label("Surviving Allies", GOLD, 20)
	title.theme_type_variation = &"ClassicHeading"
	title.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	header.add_child(title)
	var capacity := _label("Keep up to %d" % body.maximum, TEXT, 15)
	capacity.horizontal_alignment = HORIZONTAL_ALIGNMENT_RIGHT
	header.add_child(capacity)
	var columns := HBoxContainer.new()
	columns.name = "AllySelectionColumns"
	columns.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	columns.size_flags_vertical = Control.SIZE_EXPAND_FILL
	columns.add_theme_constant_override("separation", 8)
	add_child(columns)
	_build_ally_candidates(columns, body)
	_build_ally_decision(columns)
	_refresh_ally_selection()


func _build_ally_candidates(parent: HBoxContainer, body: InteractionRequest.SelectionRequestBody) -> void:
	var panel := PanelContainer.new()
	panel.name = "AllyCandidates"
	panel.theme_type_variation = &"ClassicTextWell"
	panel.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	panel.size_flags_vertical = Control.SIZE_EXPAND_FILL
	panel.size_flags_stretch_ratio = 1.8
	parent.add_child(panel)
	var content := VBoxContainer.new()
	content.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	content.size_flags_vertical = Control.SIZE_EXPAND_FILL
	content.add_child(_label("Choose who continues with the party", GOLD, 16))
	panel.add_child(content)
	var scroll := ScrollContainer.new()
	scroll.horizontal_scroll_mode = ScrollContainer.SCROLL_MODE_DISABLED
	scroll.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	scroll.size_flags_vertical = Control.SIZE_EXPAND_FILL
	content.add_child(scroll)
	var grid := GridContainer.new()
	grid.name = "AllyCandidateGrid"
	grid.columns = 2
	grid.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	grid.add_theme_constant_override("h_separation", 5)
	grid.add_theme_constant_override("v_separation", 5)
	scroll.add_child(grid)
	if body.candidates.is_empty():
		grid.add_child(_label("No surviving allies were supplied. Continue returns to the adventure.", MUTED, 14))
		return
	for entry: InteractionRequestValue.SelectionCandidate in body.candidates:
		var required := body.required_ids.has(entry.id)
		_add_character_check(grid, entry, required or body.selected_ids.has(entry.id), required)


func _build_ally_decision(parent: HBoxContainer) -> void:
	var panel := PanelContainer.new()
	panel.name = "AllyDecision"
	panel.theme_type_variation = &"ClassicTextWell"
	panel.custom_minimum_size.x = 260.0
	panel.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	panel.size_flags_vertical = Control.SIZE_EXPAND_FILL

	panel.size_flags_stretch_ratio = 0.8
	parent.add_child(panel)
	var content := VBoxContainer.new()
	content.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	content.size_flags_vertical = Control.SIZE_EXPAND_FILL
	content.add_child(_label("Party Allies", GOLD, 16))
	_ally_summary = _label("", CYAN, 15)
	content.add_child(_ally_summary)
	var spacer := Control.new()
	spacer.size_flags_vertical = Control.SIZE_EXPAND_FILL
	content.add_child(spacer)
	var submit := Button.new()
	submit.name = "AllySelectionContinue"
	submit.text = "Continue"
	submit.custom_minimum_size.y = 44.0
	submit.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	submit.pressed.connect(_submit_allies)
	content.add_child(submit)
	panel.add_child(content)


func _add_character_check(parent: Container, entry: InteractionRequestValue.SelectionCandidate, selected: bool, required: bool) -> void:
	var check := CheckButton.new()
	check.name = "AllyCandidate_%s" % entry.id.replace(".", "_")
	check.text = entry.name
	if entry.has_current_health:
		var maximum_health := entry.maximum_health if entry.has_maximum_health else entry.current_health
		check.text += "\nHP %d/%d" % [entry.current_health, maximum_health]
	if required:
		check.text += "  •  Required"
	check.set_meta("character_id", entry.id)
	check.button_pressed = selected
	check.disabled = required
	check.custom_minimum_size.y = 66.0
	check.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	check.alignment = HORIZONTAL_ALIGNMENT_LEFT
	check.icon = _ally_icon(entry.id)
	check.expand_icon = true
	check.toggled.connect(func(_pressed: bool) -> void: _refresh_ally_selection())
	_checks.append(check)
	parent.add_child(check)


func _submit_allies() -> void:
	var ids := _selected_ids()
	if ids.size() > _ally_maximum:
		_ally_summary.text = "Choose no more than %d allies." % _ally_maximum
		return
	response_body_submitted.emit(InteractionResponse.AllySelectionBody.new(ids))


func _refresh_ally_selection() -> void:
	if _ally_summary == null:
		return
	var selected := _selected_ids()
	_ally_summary.text = "%d of %d selected" % [selected.size(), _ally_maximum]
	for check: CheckButton in _checks:
		var required := check.disabled and check.button_pressed
		check.disabled = required or not check.button_pressed and selected.size() >= _ally_maximum


func _selected_ids() -> Array[String]:
	var ids: Array[String] = []
	for check: CheckButton in _checks:
		if check.button_pressed:
			ids.append(String(check.get_meta("character_id")))
	return ids


func _ally_icon(ally_id: String) -> Texture2D:
	if _game_view == null or _media == null:
		return null
	for ally: MonsterView in _game_view.party_allies:
		if ally.id == ally_id and ally.icon_id > 0:
			return _media.image_texture(_media.asset_by_resource(ally.icon_resource_type, ally.icon_id))
	return null

	_inventory_rows = VBoxContainer.new()
	_inventory_rows.name = "InventoryRows"
	_inventory_rows.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	_inventory_rows.add_theme_constant_override("separation", 3)
	scroll.add_child(_inventory_rows)
	_refresh_inventory()


func _build_inspector_pane(parent: HBoxContainer) -> void:
	var content := _pane(parent, "ItemInspectorRail", "Selected Item", 1.05)
	_inspector_facts = VBoxContainer.new()
	_inspector_facts.name = "InspectorFacts"
	_inspector_facts.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	_inspector_facts.size_flags_vertical = Control.SIZE_EXPAND_FILL
	_inspector_facts.add_theme_constant_override("separation", 4)
	content.add_child(_inspector_facts)


func _build_footer() -> void:
	var footer := HBoxContainer.new()
	footer.name = "ShopFooter"
	footer.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	footer.add_theme_constant_override("separation", 5)
	add_child(footer)
	_buy_button = _action_button("ShopBuy", "Buy", _submit_buy)
	_sell_button = _action_button("ShopSellSelected", "Sell", _submit_sell)
	_identify_button = _action_button("ShopIdentify", "Identify", _submit_identify)
	footer.add_child(_buy_button)
	footer.add_child(_sell_button)
	footer.add_child(_identify_button)
	var spacer := Control.new()
	spacer.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	footer.add_child(spacer)
	var leave := _action_button("ShopLeave", "Leave Shop", _submit_leave)
	leave.custom_minimum_size.x = 150.0
	footer.add_child(leave)


func _select_shopper_index(_index: int) -> void:
	_select_character(String(_shopper_picker.get_selected_metadata()))


func _select_character(character_id: String) -> void:
	_selected_character_id = character_id
	_selected_stock = null
	_selected_item = null
	_refresh_inventory()
	_refresh_inspector()


func _select_stock(stock_key: String) -> void:
	_selected_stock = null
	_selected_item = null
	for entry: InteractionRequestValue.ShopStock in _stock:
		if entry.stock_key == stock_key:
			_selected_stock = entry
			break
	_refresh_inspector()


func _select_item(character_id: String, instance_id: String) -> void:
	_selected_stock = null
	_selected_item = null
	for character: InteractionRequestValue.ServiceCharacter in _characters:
		if character.id != character_id:
			continue
		for item: InteractionRequestValue.InventoryItem in character.inventory:
			if item.instance_id == instance_id:
				_selected_item = item
				_selected_character_id = character.id
				break
		break
	_refresh_inspector()


func _refresh_inventory() -> void:
	if _inventory_rows == null:
		return
	for child: Node in _inventory_rows.get_children():
		_inventory_rows.remove_child(child)
		child.free()
	var character := _character_by_id(_selected_character_id)
	if character == null:
		_inventory_rows.add_child(_label("No adventurer is selected.", MUTED))
		return
	for item: InteractionRequestValue.InventoryItem in character.inventory:
		var row := HBoxContainer.new()
		row.add_theme_constant_override("separation", 5)
		var icon := CONTENT_ICON_SCRIPT.new() as Control
		icon.name = "InventoryIcon_%s" % item.instance_id.replace(".", "_")
		icon.configure(item.icon_resource_type, item.icon_id, _media, 46.0, item.name)
		row.add_child(icon)
		var button := Button.new()
		button.name = "Inventory_%s" % item.instance_id.replace(".", "_")
		button.text = "%s\n%s  •  sell %d gold" % [item.name, "Equipped" if item.equipped else "Carried", item.sell_price]
		button.alignment = HORIZONTAL_ALIGNMENT_LEFT
		button.clip_text = true
		button.custom_minimum_size.y = 46.0
		button.size_flags_horizontal = Control.SIZE_EXPAND_FILL
		button.toggle_mode = true
		button.button_group = _inventory_group
		button.pressed.connect(_select_item.bind(character.id, item.instance_id))
		row.add_child(button)
		_inventory_rows.add_child(row)
	if character.inventory.is_empty():
		_inventory_rows.add_child(_label("%s carries no items." % character.name, MUTED))


func _refresh_inspector() -> void:
	if _inspector_facts == null:
		return
	for child: Node in _inspector_facts.get_children():
		_inspector_facts.remove_child(child)
		child.free()
	_buy_button.disabled = _selected_stock == null or _selected_character_id.is_empty() or not _selected_stock.can_buy
	_sell_button.disabled = _selected_item == null or not _selected_item.can_sell
	_identify_button.disabled = _selected_item == null or not _selected_item.can_identify
	_buy_button.tooltip_text = "Select shop stock." if _selected_stock == null else "No shopper is available." if _selected_character_id.is_empty() else _selected_stock.buy_reason if not _selected_stock.can_buy else ""
	_sell_button.tooltip_text = "Select a carried item." if _selected_item == null else _selected_item.sell_reason if not _selected_item.can_sell else ""
	_identify_button.tooltip_text = "Select a carried item." if _selected_item == null else _selected_item.identify_reason if not _selected_item.can_identify else ""
	if _selected_stock != null:
		_add_inspector_record(_selected_stock.name, ["Buy for %d gold" % _selected_stock.buy_price, "%d remaining" % _selected_stock.quantity], _selected_stock.can_buy, _selected_stock.buy_reason, _selected_stock.icon_resource_type, _selected_stock.icon_id)
	elif _selected_item != null:
		var state := "Equipped" if _selected_item.equipped else "Carried"
		var knowledge := "Identified" if _selected_item.identified else "Unidentified"
