signal action_requested(action_id: StringName, value: Variant)
signal setting_changed(setting_id: StringName, value: Variant)

const GOLD := Color("d5b45d")
const CYAN := Color("8fcfd1")
const MUTED := Color("9aa0a8")

var _save_previews: Array[SaveSlotPreview] = []
var _selected_save_key: String = ""
var _save_detail: VBoxContainer
var _load_selected: Button
var _layout_profile: StringName = UiLayoutProfile.WIDE
var _save_and_quit_mode: bool = false


func set_layout_profile(profile_id: StringName) -> void:
	_layout_profile = profile_id


func set_save_previews(previews: Array[SaveSlotPreview]) -> void:
	_save_previews = previews.duplicate()
	if not _save_previews.any(func(preview: SaveSlotPreview) -> bool: return _key(preview) == _selected_save_key):
		_selected_save_key = _key(_save_previews[0]) if not _save_previews.is_empty() else ""


func set_save_and_quit_mode(enabled: bool) -> void:
	if enabled and not _save_and_quit_mode:
		for preview: SaveSlotPreview in _save_previews:
			if preview.source == SaveSlotPreviewScript.PRIMARY and preview.can_load:
				_selected_save_key = _key(preview)
				break
	_save_and_quit_mode = enabled


func present(parent: VBoxContainer, view: GameView, settings: PresentationSettings) -> void:
	if parent == null or view == null or settings == null:
		return
	_add_header(parent, view)
	var tabs := TabContainer.new()
	tabs.name = "SystemWorkspaceTabs"
	tabs.clip_tabs = true
	tabs.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	tabs.size_flags_vertical = Control.SIZE_EXPAND_FILL
	parent.add_child(tabs)
	_build_save_tab(_tab(tabs, "Save & Load"), view)
	_build_display_tab(_tab(tabs, "Display"), settings)
	_build_audio_tab(_tab(tabs, "Audio"), settings)
	_build_accessibility_tab(_tab(tabs, "Accessibility"), settings)
	_build_controls_tab(_tab(tabs, "Controls"), settings)
	_build_diagnostics_tab(_tab(tabs, "Diagnostics"), settings)


func _add_header(parent: VBoxContainer, view: GameView) -> void:
	var row := HBoxContainer.new()
	row.name = "SystemHeader"
	parent.add_child(row)
	var campaign := view.campaign_summary.title if view.campaign_summary != null else view.campaign_id
	var fact := _label("%s  •  %s" % [campaign, view.rules_version], CYAN, 13)
	fact.name = "SystemCampaignContext"
	fact.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	fact.max_lines_visible = 2
	fact.text_overrun_behavior = TextServer.OVERRUN_TRIM_ELLIPSIS
	row.add_child(fact)


func _build_save_tab(parent: VBoxContainer, view: GameView) -> void:
	var columns := HBoxContainer.new()
	columns.name = "SaveWorkspaceColumns"
	columns.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	columns.size_flags_vertical = Control.SIZE_EXPAND_FILL
	columns.add_theme_constant_override("separation", 6)
	parent.add_child(columns)
	var browser := _pane(columns, "SaveSlotBrowser", "Save Slots", 0.85)
	var detail := _pane(columns, "SaveSlotDetail", "Selected Record", 1.25)
	_save_detail = VBoxContainer.new()
	_save_detail.name = "SaveSlotDetailBody"
	_save_detail.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	_save_detail.size_flags_vertical = Control.SIZE_EXPAND_FILL
	_save_detail.add_theme_constant_override("separation", 5)
	detail.add_child(_save_detail)
	var scroll := _scroll("SaveSlotScroll")
	browser.add_child(scroll)
	var rows := VBoxContainer.new()
	rows.name = "SaveSlotRows"
	rows.add_theme_constant_override("separation", 4)
	rows.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	scroll.add_child(rows)
	if _save_previews.is_empty():
		_add_card(rows, "No saves for this campaign", "Return to party setup and begin a new adventure." if view.party_setup_available else "Quick Save creates the first validated slot.", "")
	else:
		var group := ButtonGroup.new()
		for preview: SaveSlotPreview in _save_previews:
			var button := Button.new()
			button.name = "SavePreview_%s_%s" % [preview.slot_id, String(preview.source)]
			button.text = "%s  •  %s\n%s" % [preview.slot_id, preview.source_label(), preview.status_label()]
			button.alignment = HORIZONTAL_ALIGNMENT_LEFT
			button.custom_minimum_size.y = 54.0
			button.toggle_mode = true
			button.button_group = group
			button.button_pressed = _key(preview) == _selected_save_key
			button.pressed.connect(_select_save.bind(preview))
			rows.add_child(button)
	_build_save_footer(parent, view)
	_refresh_save_detail()


func _build_save_footer(parent: VBoxContainer, view: GameView) -> void:
	var footer := HBoxContainer.new()
	footer.name = "SaveWorkspaceFooter"
	footer.add_theme_constant_override("separation", 5)
	parent.add_child(footer)
	if _save_and_quit_mode:
		var save_and_quit := _add_action(footer, "Save and Quit", &"", null)
		save_and_quit.name = "SaveAndQuitSelected"
		save_and_quit.tooltip_text = "Save to the selected slot, then quit Realmz Rebuilt."
		save_and_quit.pressed.connect(_save_selected_and_quit)
	elif not view.party_setup_available:
		_add_action(footer, "Quick Save", &"save", "quick")
	_load_selected = _add_action(footer, "Load Selected", &"", null)
	_load_selected.name = "LoadSelectedSave"
	_load_selected.pressed.connect(_load_selected_preview)
	_add_action(footer, "Refresh", &"refresh_saves", null)
	var spacer := Control.new()
	spacer.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	footer.add_child(spacer)
	var end_adventure := _add_action(footer, "Main Menu", &"end_adventure", null)
	end_adventure.disabled = view.pending_interaction != null and view.pending_interaction.kind != InteractionRequest.COMBAT
	end_adventure.tooltip_text = "Resolve the current interaction first." if end_adventure.disabled else "Close this campaign session and return to the Realmz Rebuilt main menu."


func _select_save(preview: SaveSlotPreview) -> void:
	_selected_save_key = _key(preview)
	_refresh_save_detail()


func _refresh_save_detail() -> void:
	if _save_detail == null or _load_selected == null:
		return
	_clear(_save_detail)
	var preview := _selected_preview()
	_load_selected.disabled = preview == null or not preview.can_load
	_load_selected.tooltip_text = "Select a validated save record." if preview == null else preview.error_message if not preview.can_load else "Restore this validated %s record." % preview.source_label().to_lower()
	if preview == null:
		_add_card(_save_detail, "No selected record", "Save slots appear at left.", "")
		return
	_save_detail.add_child(_label("%s  •  %s" % [preview.slot_id, preview.source_label()], GOLD, 18))
	_save_detail.add_child(_label(preview.status_label(), CYAN if preview.can_load else Color("d48a78"), 14))
	if preview.status != SaveSlotPreviewScript.VALID:
		_save_detail.add_child(_label(preview.error_message, MUTED, 14))
		return
	var party := ", ".join(preview.character_names) if not preview.character_names.is_empty() else "No party members"
	_save_detail.add_child(_label("Day %d  •  %02d:%02d  •  %s %d,%d" % [preview.realmz_day, preview.realmz_hour, preview.realmz_minute, preview.map_id, preview.coordinate.x, preview.coordinate.y], CYAN, 15))
	_save_detail.add_child(_label(party, Color("e0e2e5"), 15))
	_save_detail.add_child(HSeparator.new())

	_save_detail.add_child(_label("Package %s" % preview.package_hash.left(12), MUTED, 13))
	_save_detail.add_child(_label("Rules %s" % preview.rules_version, MUTED, 13))
	if preview.modified_unix > 0:
		_save_detail.add_child(_label("Saved %s" % Time.get_datetime_string_from_unix_time(preview.modified_unix), MUTED, 13))


func _load_selected_preview() -> void:
	var preview := _selected_preview()
	if preview == null or not preview.can_load:
		return
	var action: StringName = &"load_backup" if preview.source == SaveSlotPreviewScript.BACKUP else &"load"
	action_requested.emit(action, preview.slot_id)


func _save_selected_and_quit() -> void:
	var preview := _selected_preview()
	action_requested.emit(&"save_and_quit", preview.slot_id if preview != null else "quick")


func _selected_preview() -> SaveSlotPreview:
	for preview: SaveSlotPreview in _save_previews:
		if _key(preview) == _selected_save_key:
			return preview
	return null


func _key(preview: SaveSlotPreview) -> String:
	return "%s:%s" % [preview.slot_id, String(preview.source)] if preview != null else ""


func _build_display_tab(parent: VBoxContainer, settings: PresentationSettings) -> void:
	var content := _settings_panel(parent, "Display", "Fit keeps the Classic application centered at wide resolutions. Interface density and text size remain independent; exact bitmap art stays at native 1× or 2× pixels.")
	var ui_scale := OptionButton.new()
	for entry: Dictionary in [{"label": "Fit to window", "id": PresentationSettings.UI_SCALE_AUTO}, {"label": "Interface density: 100%", "id": PresentationSettings.UI_SCALE_100}, {"label": "Interface density: 125%", "id": PresentationSettings.UI_SCALE_125}, {"label": "Interface density: 150%", "id": PresentationSettings.UI_SCALE_150}]:
		ui_scale.add_item(entry["label"])
		ui_scale.set_item_metadata(ui_scale.item_count - 1, entry["id"])
		if entry["id"] == settings.ui_scale_mode: ui_scale.select(ui_scale.item_count - 1)
	ui_scale.item_selected.connect(func(index: int) -> void: setting_changed.emit(&"ui_scale_mode", String(ui_scale.get_item_metadata(index))))
	_add_setting_row(content, "Interface scale", ui_scale)
	var text_scale := HSlider.new()
	text_scale.min_value = 0.8; text_scale.max_value = 1.5; text_scale.step = 0.1; text_scale.value = settings.text_scale
	text_scale.tooltip_text = "Text scale %d%%" % int(round(settings.text_scale * 100.0))
	text_scale.value_changed.connect(func(value: float) -> void: setting_changed.emit(&"text_scale", value))
	_add_setting_row(content, "Text size  •  %d%%" % int(round(settings.text_scale * 100.0)), text_scale)
	var typography := OptionButton.new()
	for entry: Dictionary in [
		{"label": "Classic Realmz fonts", "id": PresentationSettings.TYPOGRAPHY_CLASSIC},
		{"label": "Readable modern fonts", "id": PresentationSettings.TYPOGRAPHY_READABLE},
	]:
		typography.add_item(entry["label"])
		typography.set_item_metadata(typography.item_count - 1, entry["id"])
		if entry["id"] == settings.typography_mode:
			typography.select(typography.item_count - 1)
	typography.item_selected.connect(func(index: int) -> void: setting_changed.emit(&"typography_mode", String(typography.get_item_metadata(index))))
	_add_setting_row(content, "Typography", typography)
	var window_mode := OptionButton.new()
	window_mode.add_item("Windowed"); window_mode.set_item_metadata(0, PresentationSettings.WINDOWED)
	window_mode.add_item("Borderless fullscreen"); window_mode.set_item_metadata(1, PresentationSettings.BORDERLESS_FULLSCREEN)
	window_mode.select(1 if settings.window_mode == PresentationSettings.BORDERLESS_FULLSCREEN else 0)
	window_mode.item_selected.connect(func(index: int) -> void: setting_changed.emit(&"window_mode", String(window_mode.get_item_metadata(index))))
	_add_setting_row(content, "Window mode", window_mode)
	_add_setting_toggle(content, "Use topology-derived 3D dungeons", settings.dungeon_3d, &"dungeon_3d")


func _build_audio_tab(parent: VBoxContainer, settings: PresentationSettings) -> void:
	var content := _settings_panel(parent, "Audio", "Presentation audio never advances the simulation.")
	var volume := HSlider.new()
	volume.min_value = 0.0; volume.max_value = 1.0; volume.step = 0.05; volume.value = settings.master_volume
	volume.tooltip_text = "Master volume %d%%" % int(round(settings.master_volume * 100.0))
	volume.value_changed.connect(func(value: float) -> void: setting_changed.emit(&"master_volume", value))
	_add_setting_row(content, "Master volume  •  %d%%" % int(round(settings.master_volume * 100.0)), volume)
	var sound := HSlider.new()
	sound.min_value = 0.0; sound.max_value = 1.0; sound.step = 0.05; sound.value = settings.sound_volume
	sound.tooltip_text = "Sound effects volume %d%%" % int(round(settings.sound_volume * 100.0))
	sound.value_changed.connect(func(value: float) -> void: setting_changed.emit(&"sound_volume", value))
	_add_setting_row(content, "Sound effects  •  %d%%" % int(round(settings.sound_volume * 100.0)), sound)
	var music := HSlider.new()
	music.min_value = 0.0; music.max_value = 1.0; music.step = 0.05; music.value = settings.music_volume
	music.tooltip_text = "Music volume %d%%" % int(round(settings.music_volume * 100.0))
	music.value_changed.connect(func(value: float) -> void: setting_changed.emit(&"music_volume", value))
	_add_setting_row(content, "Music  •  %d%%" % int(round(settings.music_volume * 100.0)), music)
	_add_setting_toggle(content, "Music enabled", settings.music_enabled, &"music_enabled")
	var playlist := Button.new()
	playlist.name = "OpenMusicPlaylist"
	playlist.text = "Open Music Playlist…"
	playlist.tooltip_text = "Configure Castle's 20 context slots as Play, Continue, or Off."
	playlist.pressed.connect(func() -> void: action_requested.emit(&"music_playlist", null))
	content.add_child(playlist)


func _build_accessibility_tab(parent: VBoxContainer, settings: PresentationSettings) -> void:
	var content := _settings_panel(parent, "Accessibility", "Accessibility changes presentation only; Classic rules remain fixed.")
	_add_setting_toggle(content, "Reduced motion", settings.reduced_motion, &"reduced_motion")
	content.add_child(_label("Reduced motion settles combat feedback in one presentation frame without skipping committed events.", MUTED, 14))


func _build_controls_tab(parent: VBoxContainer, settings: PresentationSettings) -> void:
	var content := _settings_panel(parent, "Controls", "Exploration cadence and convenience controls.")
	var movement_row := HBoxContainer.new()
	var movement_speed := HSlider.new()
	movement_speed.min_value = 25.0; movement_speed.max_value = 400.0; movement_speed.step = 25.0; movement_speed.value = settings.exploration_speed_percent
	movement_speed.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	movement_speed.tooltip_text = "%d%%  •  %.3f seconds per held step" % [settings.exploration_speed_percent, HeldMovementControllerScript.BASE_INTERVAL_SECONDS * 100.0 / float(settings.exploration_speed_percent)]
	movement_speed.value_changed.connect(func(value: float) -> void: setting_changed.emit(&"exploration_speed_percent", int(value)))
	movement_row.add_child(movement_speed)
	_add_setting_row(content, "Exploration speed  •  %d%%" % settings.exploration_speed_percent, movement_row)
	_add_setting_toggle(content, "Auto Switch To Melee Weapon", settings.auto_switch_to_melee, &"auto_switch_to_melee")
	_add_setting_toggle(content, "Show travel preview on the exploration map", settings.show_exploration_minimap, &"show_exploration_minimap")
	_add_setting_toggle(content, "Add eligible scenario text to Notes automatically", settings.autojournal_enabled, &"autojournal_enabled")
	content.add_child(_label("Move: arrows, WASD, or numpad  •  Hold Shift in battle to reveal adjacent movement costs  •  Space skips presentation playback", MUTED, 14))


func _build_diagnostics_tab(parent: VBoxContainer, settings: PresentationSettings) -> void:
	var content := _settings_panel(parent, "Diagnostics", "Developer overlays expose detached topology facts without becoming gameplay authority.")
	_add_setting_toggle(content, "Show topology diagnostics", settings.topology_debug, &"topology_debug")
	content.add_child(_label("Topology diagnostics display movement, visibility, and trigger projections derived from the same authoritative map model.", MUTED, 14))


func _settings_panel(parent: VBoxContainer, title: String, description: String) -> VBoxContainer:
	var panel := PanelContainer.new()
	panel.name = "%sSettingsPanel" % title.replace(" ", "")
	panel.theme_type_variation = &"ClassicTextWell"
	panel.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	panel.size_flags_vertical = Control.SIZE_EXPAND_FILL
	parent.add_child(panel)
	var content := VBoxContainer.new()
	content.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	content.size_flags_vertical = Control.SIZE_EXPAND_FILL
	content.add_theme_constant_override("separation", 10)
	panel.add_child(content)
	var heading := _label(title, GOLD, 20)
	heading.theme_type_variation = &"ClassicHeading"
	content.add_child(heading)
	content.add_child(_label(description, MUTED, 14))
	content.add_child(HSeparator.new())
	return content


func _add_setting_row(parent: Container, label: String, control: Control) -> void:
	var row := BoxContainer.new()
	row.vertical = _layout_profile == UiLayoutProfile.COMPACT
	row.add_theme_constant_override("separation", 10)
	parent.add_child(row)
	var caption := _label(label, Color("e0e2e5"), 15)
	caption.custom_minimum_size.x = 0.0 if row.vertical else 230.0
	row.add_child(caption)
	control.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	row.add_child(control)


func _tab(tabs: TabContainer, tab_name: String) -> VBoxContainer:
	var tab := VBoxContainer.new()
	tab.name = tab_name
	tab.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	tab.size_flags_vertical = Control.SIZE_EXPAND_FILL
	tab.add_theme_constant_override("separation", 6)
	tabs.add_child(tab)
	return tab

func _pane(parent: HBoxContainer, pane_name: String, title: String, ratio: float) -> VBoxContainer:
	var panel := PanelContainer.new()
	panel.name = pane_name
	panel.theme_type_variation = &"ClassicTextWell"
	panel.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	panel.size_flags_vertical = Control.SIZE_EXPAND_FILL
	panel.size_flags_stretch_ratio = ratio
	parent.add_child(panel)
	var content := VBoxContainer.new()
	content.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	content.size_flags_vertical = Control.SIZE_EXPAND_FILL
	content.add_theme_constant_override("separation", 5)
	panel.add_child(content)
	var heading := _label(title, GOLD, 18)
	heading.theme_type_variation = &"ClassicHeading"
	content.add_child(heading)
	return content


func _scroll(node_name: String) -> ScrollContainer:
	var scroll := ScrollContainer.new()
	scroll.name = node_name
	scroll.horizontal_scroll_mode = ScrollContainer.SCROLL_MODE_DISABLED
	scroll.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	scroll.size_flags_vertical = Control.SIZE_EXPAND_FILL
	return scroll


func _add_action(parent: Container, label: String, action_id: StringName, value: Variant) -> Button:
	var button := Button.new()
	button.text = label
	button.custom_minimum_size.y = 38.0
	if not action_id.is_empty():
		button.pressed.connect(func() -> void: action_requested.emit(action_id, value))
	parent.add_child(button)
	return button


func _add_card(parent: Container, title: String, subtitle: String, detail: String) -> void:
	var panel := PanelContainer.new()
	panel.theme_type_variation = &"ClassicInset"
	panel.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	var column := VBoxContainer.new()
	column.add_theme_constant_override("separation", 3)
	panel.add_child(column)
	column.add_child(_label(title, GOLD, 16))
	if not subtitle.is_empty(): column.add_child(_label(subtitle, MUTED, 13))
	if not detail.is_empty(): column.add_child(_label(detail, Color.WHITE, 14))
	parent.add_child(panel)


func _add_setting_toggle(parent: Container, label: String, enabled: bool, setting_id: StringName) -> void:
	var toggle := CheckButton.new()
	toggle.text = label
	toggle.button_pressed = enabled
	toggle.toggled.connect(func(value: bool) -> void: setting_changed.emit(setting_id, value))
	parent.add_child(toggle)


func _label(text: String, color: Color, size: int) -> Label:
	var result := Label.new()
	result.text = text
	result.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
	result.add_theme_color_override("font_color", color)
	result.add_theme_font_size_override("font_size", size)
	return result


func _clear(parent: Container) -> void:
	for child: Node in parent.get_children():
		parent.remove_child(child)
		child.queue_free()

func _combatant_name(combatant_id: String) -> String:
	for combatant: InteractionRequestValue.Combatant in _combatants:
		if combatant.id == combatant_id: return combatant.name
	return combatant_id


static func _string_array(value: Variant) -> Array[String]:
	var result: Array[String] = []
	if value is Array:
		for entry: Variant in value:
			result.append(String(entry))
	return result


func accepts_spatial_input() -> bool:
	for panel: Control in _mode_panels:
		if panel.visible:
			return false
	return true


func _build_command_shelf(body: InteractionRequest.CombatRequestBody, actor_id: String, action_ids: Array[String], targets: Array[InteractionRequestValue.CombatTarget], target_panel: Control, spell_panel: Control, scroll_panel: Control, item_panel: Control, bandage_panel: Control, mode_panels: Array[Control], overview: Control) -> void:
	var shelf_center := CenterContainer.new()
	shelf_center.name = "BattleCommandShelfCenter"
	shelf_center.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	overview.add_child(shelf_center)
	var shelf := HBoxContainer.new()
	shelf.name = "BattleCommandShelf"
	shelf.size_flags_horizontal = Control.SIZE_SHRINK_CENTER
	shelf.add_theme_constant_override("separation", 10)
	shelf_center.add_child(shelf)
	var inspection := _command_group(shelf, "BattleInspectionCommands", "View", VIEW_COMMAND_COLOR)
	var inspection_rows := _command_rows(inspection, "BattleInspection")
	_add_presentation_button(inspection_rows[0], "Previous", &"inspect_previous")
	_add_presentation_button(inspection_rows[0], "Center", &"center_active")
	_add_presentation_button(inspection_rows[0], "Next", &"inspect_next")
	_add_presentation_button(inspection_rows[1], "Reveal Friends", &"reveal_friends")
	var primary := _command_group(shelf, "BattlePrimaryCommands", "Action", PRIMARY_COMMAND_COLOR)
	var primary_rows := _command_rows(primary, "BattlePrimary")
	var can_switch := action_ids.has("switch_weapon") and body.weapon_switch.enabled
	var shown_weapon_mode := String(body.weapon_switch.target_mode) if can_switch else String(body.weapon_mode)
	_add_fixed_response(primary_rows[0], "Weapon", "Weapon: %s" % shown_weapon_mode.capitalize(), InteractionResponse.CombatBody.new(&"switch_weapon", actor_id), can_switch, body.weapon_switch.reason)
	_color_command(_add_fixed_response(primary_rows[0], "Guard", "Guard", InteractionResponse.CombatBody.new(&"defend", actor_id), action_ids.has("defend"), "Guard is unavailable during this activation."), TURN_COMMAND_COLOR)
	var weapon_mode := String(body.weapon_mode)
	var target_enabled: bool = action_ids.has("attack") and not targets.is_empty()
	var target_reason := body.melee_attack_reason if weapon_mode == "melee" else body.ranged_attack.reason
	var attack_button := _add_panel_toggle(primary_rows[0], "Fire" if weapon_mode == "missile" else "Attack", target_panel, mode_panels, overview, target_enabled, target_reason)
	_name_command(attack_button, "Attack")
	_accent_command(attack_button)
	var finish_button := _add_fixed_response(primary_rows[0], "Finish", "Finish", InteractionResponse.CombatBody.new(&"finish", actor_id), action_ids.has("finish"), "Finish is unavailable during this activation.")
	_accent_command(finish_button)
	var spell_button := _add_panel_toggle(primary_rows[1], "Spells", spell_panel, mode_panels, overview, action_ids.has("cast_spell") and not body.spell_casts.is_empty(), body.spell_cast_reason)
	_name_command(spell_button, "Spells")
	_color_command(spell_button, VIEW_COMMAND_COLOR)
	spell_button.pressed.connect(func() -> void:
		if spell_panel.visible:
			combat_spellbook_requested.emit(actor_id, _spell_casts)
		else:
			combat_spellbook_closed.emit()
	)
	var scroll_button := _add_panel_toggle(primary_rows[1], "Scrolls", scroll_panel, mode_panels, overview, action_ids.has("use_scroll") and not body.scroll_casts.is_empty(), body.scroll_cast_reason, 647)
	_name_command(scroll_button, "Scrolls")
	_color_command(scroll_button, VIEW_COMMAND_COLOR)
	var item_button := _add_panel_toggle(primary_rows[1], "Items", item_panel, mode_panels, overview, action_ids.has("use_item") and not body.item_casts.is_empty(), body.item_cast_reason)
	_name_command(item_button, "Items")
	_color_command(item_button, VIEW_COMMAND_COLOR)
	var turn := _command_group(shelf, "BattleTurnCommands", "Tactics", TURN_COMMAND_COLOR)
	var turn_rows := _command_rows(turn, "BattleTurn")
	_add_classic_turn_commands(turn_rows[0], turn_rows[1], body, actor_id, bandage_panel, mode_panels, overview)
	var retreat_enabled := action_ids.has("retreat") and body.retreat.enabled
	_accent_command(_add_fixed_response(turn_rows[1], "Escape", "Escape", InteractionResponse.CombatBody.new(&"retreat", actor_id), retreat_enabled, body.retreat.reason))


func _add_classic_turn_commands(first_row: Container, second_row: Container, body: InteractionRequest.CombatRequestBody, actor_id: String, bandage_panel: Control, mode_panels: Array[Control], overview: Control) -> void:
	_color_command(_add_fixed_response(first_row, "AutoTurn", "Auto Turn", InteractionResponse.CombatBody.new(&"auto", actor_id), body.auto_turn.enabled, body.auto_turn.reason), TURN_COMMAND_COLOR)
	_color_command(_add_fixed_response(first_row, "Delay", "Delay", InteractionResponse.CombatBody.new(&"delay", actor_id), body.delay.enabled, body.delay.reason), TURN_COMMAND_COLOR)
	var bandage_enabled := body.bandage.enabled and not body.bandage_targets.is_empty()
	var bandage_reason := body.bandage.reason
	if body.bandage_targets.is_empty() and body.bandage.enabled:
		bandage_reason = "No legal Bandage recipient is available."
	_add_bandage_panel(bandage_panel, actor_id, body.bandage_targets)
	var bandage_button := _add_panel_toggle(first_row, "Bandage", bandage_panel, mode_panels, overview, bandage_enabled, bandage_reason)
	_name_command(bandage_button, "Bandage")
	_color_command(bandage_button, VIEW_COMMAND_COLOR)
	_accent_command(_add_fixed_response(second_row, "TurnUndead", "Turn Undead", InteractionResponse.CombatBody.new(&"turn_undead", actor_id), body.turn_undead.enabled, body.turn_undead.reason))
	_color_command(_add_fixed_response(second_row, "Undo", "Undo", InteractionResponse.CombatBody.new(&"undo", actor_id), body.undo.enabled, body.undo.reason), VIEW_COMMAND_COLOR)


func _command_group(parent: Container, group_name: String, heading_text: String, heading_color: Color) -> VBoxContainer:
	var panel := _summary_panel("%sInset" % group_name, 1.0)
	panel.custom_minimum_size.y = 100.0
	panel.size_flags_horizontal = Control.SIZE_SHRINK_CENTER
	parent.add_child(panel)
	var column := VBoxContainer.new()
	column.name = group_name
	column.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	column.add_theme_constant_override("separation", 4)
	var heading := Label.new()
	heading.text = heading_text.to_upper()
	heading.horizontal_alignment = HORIZONTAL_ALIGNMENT_CENTER
	heading.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	heading.add_theme_font_size_override("font_size", 14)
	heading.add_theme_color_override("font_color", heading_color)
	column.add_child(heading)
	var divider := HSeparator.new()
	divider.name = "%sDivider" % group_name
	divider.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	column.add_child(divider)
	panel.add_child(column)
	return column


func _command_rows(parent: Container, name_prefix: String) -> Array[HBoxContainer]:
	var rows: Array[HBoxContainer] = []
	for suffix: String in ["Primary", "Secondary"]:
		var center := CenterContainer.new()
		center.name = "%s%sCenter" % [name_prefix, suffix]
		center.size_flags_horizontal = Control.SIZE_EXPAND_FILL
		parent.add_child(center)
		var row := HBoxContainer.new()
		row.name = "%s%s" % [name_prefix, suffix]
		row.size_flags_horizontal = Control.SIZE_SHRINK_CENTER
		row.add_theme_constant_override("separation", 5)
		center.add_child(row)
		rows.append(row)
	return rows


func _summary_panel(panel_name: String, stretch_ratio: float) -> PanelContainer:
	var panel := PanelContainer.new()
	panel.name = panel_name
	panel.theme_type_variation = &"BattleSummaryInset"
	panel.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	panel.size_flags_stretch_ratio = stretch_ratio
	panel.clip_contents = true
	return panel


func _build_initiative_panel(round_number: int) -> PanelContainer:
	var panel := _summary_panel("BattleInitiative", 1.55)
	var column := VBoxContainer.new()
	column.add_theme_constant_override("separation", 2)
	var heading := Label.new()
	heading.text = "Round %d • Turn order" % round_number
	heading.add_theme_color_override("font_color", Color("63d8e7"))
	heading.add_theme_font_size_override("font_size", 10)
	column.add_child(heading)
	var turns := HBoxContainer.new()
	turns.name = "BattleInitiativeOrder"
	turns.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	turns.add_theme_constant_override("separation", 3)
	column.add_child(turns)
	panel.add_child(column)
	var ordered := _ordered_combatants_from_active()
	for index: int in mini(ordered.size(), MAX_VISIBLE_TURNS):
		var combatant := ordered[index]
		var button := Button.new()
		button.name = "Initiative%s" % combatant.id.to_pascal_case()

class_name DungeonMap3DPresenter
extends SubViewportContainer

@export var cell_span: float = 2.5
@export var wall_height: float = 2.2
@export var wall_thickness: float = 0.14

var _enabled: bool = false
var _projection: DungeonGeometryProjection
var _viewport: SubViewport
var _geometry_root: Node3D
var _camera: Camera3D
var _floor_material: StandardMaterial3D
var _wall_material: StandardMaterial3D
var _door_material: StandardMaterial3D
var _secret_material: StandardMaterial3D
var _feature_material: StandardMaterial3D
var _party_material: StandardMaterial3D


func _ready() -> void:
	position = Vector2(205.0, 58.0)
	size = Vector2(530.0, 452.0)
	z_index = 6
	mouse_filter = Control.MOUSE_FILTER_IGNORE
	stretch = true
	visible = false
	_floor_material = _material(Color(0.27, 0.25, 0.20))
	_wall_material = _material(Color(0.53, 0.55, 0.58))
	_door_material = _material(Color(0.64, 0.42, 0.20))
	_secret_material = _material(Color(0.45, 0.25, 0.54))
	_feature_material = _material(Color(0.62, 0.62, 0.57))
	_party_material = _material(Color(0.92, 0.70, 0.20))
	_viewport = SubViewport.new()
	_viewport.name = "DungeonViewport"
	_viewport.size = Vector2i(530, 452)
	_viewport.own_world_3d = true
	_viewport.render_target_update_mode = SubViewport.UPDATE_WHEN_VISIBLE
	add_child(_viewport)
	_geometry_root = Node3D.new()
	_geometry_root.name = "TopologyGeometry"
	_viewport.add_child(_geometry_root)
	_camera = Camera3D.new()
	_camera.name = "DungeonCamera"
	_camera.fov = 58.0
	_viewport.add_child(_camera)
	var light := DirectionalLight3D.new()
	light.name = "DungeonLight"
	light.rotation_degrees = Vector3(-55.0, -35.0, 0.0)
	light.light_energy = 1.4
	_viewport.add_child(light)
	var environment_node := WorldEnvironment.new()
	var environment := Environment.new()
	environment.background_mode = Environment.BG_COLOR
	environment.background_color = Color(0.025, 0.027, 0.032)
	environment.ambient_light_source = Environment.AMBIENT_SOURCE_COLOR
	environment.ambient_light_color = Color(0.46, 0.48, 0.54)
	environment.ambient_light_energy = 0.55
	environment_node.environment = environment
	_viewport.add_child(environment_node)


func set_enabled(enabled: bool) -> void:
	_enabled = enabled
	_update_visibility()


func present(game_view: GameView) -> void:
	_projection = null
	if game_view != null and game_view.session_started:
		_projection = DungeonGeometryProjection.from_map_view(game_view.map_view)
	_rebuild_geometry()
	_update_visibility()


func is_active() -> bool:
	return _enabled and _projection != null


func projection() -> DungeonGeometryProjection:
	return _projection


func _update_visibility() -> void:
	visible = is_active()


func _rebuild_geometry() -> void:
	if _geometry_root == null:
		return
	for child: Node in _geometry_root.get_children():
		_geometry_root.remove_child(child)
		child.queue_free()
	if _projection == null:
		return
	for cell: DungeonGeometryProjection.CellProjection in _projection.cells():
		if cell.passable:
			_add_box("Floor_%d_%d" % [cell.coordinate.x, cell.coordinate.y], Vector3(cell_span * 0.94, 0.10, cell_span * 0.94), _cell_center(cell.coordinate) + Vector3(0.0, -0.08, 0.0), _floor_material)
		if cell.features.has(&"column"):
			_add_column(cell.coordinate)
		if cell.features.has(&"stairs"):
			_add_stairs(cell.coordinate)
	var built_edges: Dictionary = {}
	for edge: DungeonGeometryProjection.EdgeProjection in _projection.edges():
		if edge.kind == &"open" or built_edges.has(edge.canonical_key):
			continue
		built_edges[edge.canonical_key] = true
		if edge.kind in [&"door", &"archway"]:
			_add_door_frame(edge)
		else:
			_add_wall(edge, _secret_material if edge.kind == &"secret" else _wall_material)
	_add_party_marker()
	var target := _cell_center(_projection.party_coordinate) + Vector3(0.0, 0.65, 0.0)
	_camera.position = target + Vector3(5.6, 7.5, 7.8)
	_camera.look_at(target, Vector3.UP)


func _add_wall(edge: DungeonGeometryProjection.EdgeProjection, surface_material: Material) -> void:
	var horizontal := edge.direction in [&"north", &"south"]
	var box_dimensions := Vector3(cell_span, wall_height, wall_thickness) if horizontal else Vector3(wall_thickness, wall_height, cell_span)
	_add_box("Edge_%s" % edge.canonical_key, box_dimensions, _edge_center(edge.coordinate, edge.direction) + Vector3(0.0, wall_height * 0.5, 0.0), surface_material)


func _add_door_frame(edge: DungeonGeometryProjection.EdgeProjection) -> void:
	var horizontal := edge.direction in [&"north", &"south"]
	var center := _edge_center(edge.coordinate, edge.direction)
	var post_offset := cell_span * 0.37
	var post_size := Vector3(wall_thickness * 1.35, wall_height * 0.82, wall_thickness * 1.35)
	var left_offset := Vector3(post_offset, 0.0, 0.0) if horizontal else Vector3(0.0, 0.0, post_offset)
	_add_box("DoorPostA_%s" % edge.canonical_key, post_size, center - left_offset + Vector3(0.0, post_size.y * 0.5, 0.0), _door_material)
	_add_box("DoorPostB_%s" % edge.canonical_key, post_size, center + left_offset + Vector3(0.0, post_size.y * 0.5, 0.0), _door_material)
	var lintel_size := Vector3(cell_span, wall_thickness * 1.5, wall_thickness * 1.5) if horizontal else Vector3(wall_thickness * 1.5, wall_thickness * 1.5, cell_span)
	_add_box("DoorLintel_%s" % edge.canonical_key, lintel_size, center + Vector3(0.0, wall_height * 0.84, 0.0), _door_material)
	if edge.kind == &"door" and not edge.passable:
		var panel_size := Vector3(cell_span * 0.62, wall_height * 0.70, wall_thickness * 0.65) if horizontal else Vector3(wall_thickness * 0.65, wall_height * 0.70, cell_span * 0.62)
		_add_box("DoorPanel_%s" % edge.canonical_key, panel_size, center + Vector3(0.0, panel_size.y * 0.5, 0.0), _door_material)


func _add_column(coordinate: Vector2i) -> void:
	var mesh := CylinderMesh.new()
	mesh.top_radius = 0.26
	mesh.bottom_radius = 0.31
	mesh.height = wall_height * 0.88
	var instance := MeshInstance3D.new()
	instance.name = "Column_%d_%d" % [coordinate.x, coordinate.y]
	instance.mesh = mesh
	instance.material_override = _feature_material
	instance.position = _cell_center(coordinate) + Vector3(0.0, mesh.height * 0.5, 0.0)
	_geometry_root.add_child(instance)


func _add_stairs(coordinate: Vector2i) -> void:
	for index: int in range(3):
		var height := 0.12 * float(index + 1)
		_add_box("Stair_%d_%d_%d" % [coordinate.x, coordinate.y, index], Vector3(cell_span * 0.62, height, cell_span * 0.20), _cell_center(coordinate) + Vector3(0.0, height * 0.5, (float(index) - 1.0) * cell_span * 0.20), _feature_material)


func _add_party_marker() -> void:
	var mesh := CylinderMesh.new()
	mesh.top_radius = 0.24

class_name HeldMovementController
extends Node

signal movement_requested(direction: Vector2i)

const BASE_INTERVAL_SECONDS: float = 0.2
const INITIAL_REPEAT_DELAY_SECONDS: float = 0.3

var _speed_percent: int = 100
var _source: StringName = &""
var _direction: Vector2i = Vector2i.ZERO
var _remaining: float = 0.0
var _request_in_progress: bool = false


func _ready() -> void:
	set_process(false)


func _process(delta: float) -> void:
	advance(delta)


func advance(delta: float) -> void:
	if not is_active():
		set_process(false)
		return
	_remaining -= delta
	if _remaining > 0.0:
		return
	# Never catch up missed intervals. A slow frame produces one request and the
	# next interval begins after the synchronous transaction settles.
	_emit_request()


func set_speed_percent(value: int) -> void:
	_speed_percent = clampi(snappedi(value, 25), 25, 400)
	if is_active():
		_remaining = interval_seconds()


func speed_percent() -> int:
	return _speed_percent


func interval_seconds() -> float:
	return BASE_INTERVAL_SECONDS * 100.0 / float(_speed_percent)


func initial_repeat_delay_seconds() -> float:
	return maxf(INITIAL_REPEAT_DELAY_SECONDS, interval_seconds())


func start(source: StringName, direction: Vector2i) -> void:
	if source.is_empty() or direction == Vector2i.ZERO or _request_in_progress:
		return
	_source = source
	_direction = direction
	set_process(true)
	_emit_request(initial_repeat_delay_seconds())


func update(source: StringName, direction: Vector2i) -> void:
	if source != _source or direction == Vector2i.ZERO:
		return
	_direction = direction


func stop(source: StringName = &"") -> void:
	if not source.is_empty() and source != _source:
		return
	_source = &""
	_direction = Vector2i.ZERO
	_remaining = 0.0
	set_process(false)


func is_active() -> bool:
	return not _source.is_empty() and _direction != Vector2i.ZERO


func active_direction() -> Vector2i:
	return _direction


func active_source() -> StringName:
	return _source


func request_in_progress() -> bool:
	return _request_in_progress


func _emit_request(repeat_delay_seconds: float = -1.0) -> void:
	if not is_active() or _request_in_progress:
		return
	var started_at := Time.get_ticks_usec()
	_request_in_progress = true
	movement_requested.emit(_direction)
	_request_in_progress = false
	if is_active():
		# The speed setting describes visible step cadence, so synchronous view and
		# presentation work consumes the current interval. A slow transaction still
		# emits at most once on the next frame; it never queues catch-up steps.
		var elapsed_seconds := float(Time.get_ticks_usec() - started_at) / 1_000_000.0
		var delay_seconds := interval_seconds() if repeat_delay_seconds < 0.0 else repeat_delay_seconds
		_remaining = maxf(delay_seconds - elapsed_seconds, 0.0)

class_name BankInteraction
extends InteractionComponent

const GOLD := Color("e5c45c")
const CYAN := Color("8fcfd1")
const MUTED := Color("aeb6ba")

var _compact := false
var _body: InteractionRequest.BankRequestBody
var _departure_mode := false
var _characters: Array[InteractionRequestValue.ServiceCharacter] = []
var _selected_character_id: String
var _character_picker: OptionButton
var _summary: VBoxContainer
var _character_group := ButtonGroup.new()


func configure(compact: bool) -> void:
	_compact = compact


func build(request: InteractionRequest) -> void:
	_body = request.body as InteractionRequest.BankRequestBody
	if _body == null:
		add_hint("The wealth request is malformed.")
		return
	_departure_mode = request.kind == InteractionRequest.POOLED_WEALTH_DEPARTURE or _body.mode == &"departure"
	_characters = _body.characters.duplicate()
	_selected_character_id = _body.selected_character_id
	if _selected_character_id.is_empty() and not _characters.is_empty():
		_selected_character_id = _characters[0].id
	size_flags_vertical = Control.SIZE_EXPAND_FILL
	custom_minimum_size = Vector2(0.0, 500.0)
	add_theme_constant_override("separation", 6)
	_build_header()
	if _compact:
		_build_compact_character_picker()
	var columns := HBoxContainer.new()
	columns.name = "BankWorkspaceColumns"
	columns.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	columns.size_flags_vertical = Control.SIZE_EXPAND_FILL
	columns.add_theme_constant_override("separation", 6)
	add_child(columns)
	_build_account_pane(columns)
	if not _compact:
		_build_character_pane(columns)
	_build_swap_pane(columns)
	_build_footer()
	_refresh_selected_character()


func _build_header() -> void:
	var row := HBoxContainer.new()
	row.name = "BankHeader"
	row.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	add_child(row)
	var title := _label("Distribute pooled wealth before leaving" if _departure_mode else "Bank-backed Swap", GOLD)
	title.theme_type_variation = &"ClassicHeading"
	title.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	row.add_child(title)
	var load_note := _label("Exact denomination transfers", CYAN)
	load_note.horizontal_alignment = HORIZONTAL_ALIGNMENT_RIGHT
	row.add_child(load_note)


func _build_compact_character_picker() -> void:
	_character_picker = character_option(_characters)
	_character_picker.name = "BankCharacterPicker"
	for index: int in _character_picker.item_count:
		if String(_character_picker.get_item_metadata(index)) == _selected_character_id:
			_character_picker.select(index)
			break
	_character_picker.item_selected.connect(func(_index: int) -> void:
		_selected_character_id = String(_character_picker.get_selected_metadata())
		_refresh_selected_character()
	)
	add_child(_character_picker)


func _build_account_pane(parent: HBoxContainer) -> void:
	var content := _pane(parent, "BankAccount", "Party Wealth", 0.8)
	content.add_child(_wealth_card("Party Pool", _body.pooled_wealth))
	if not _departure_mode:
		content.add_child(_wealth_card("Banked until departure", _body.banked_wealth))
	var explanation := "Done leaves any unassigned wealth behind, then continues this movement attempt." if _departure_mode else "Opening the bank moves banked wealth into the pool. Leaving the location returns the remaining pool to the bank."
	content.add_child(_label(explanation, MUTED))
	var spacer := Control.new()
	spacer.size_flags_vertical = Control.SIZE_EXPAND_FILL
	content.add_child(spacer)


func _build_character_pane(parent: HBoxContainer) -> void:
	var content := _pane(parent, "BankCharacters", "Adventurers", 0.95)
	var scroll := _scroll("BankCharacterScroll")
	content.add_child(scroll)
	var rows := VBoxContainer.new()
	rows.name = "BankCharacterRows"
	rows.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	rows.add_theme_constant_override("separation", 3)
	scroll.add_child(rows)
	if _characters.is_empty():
		rows.add_child(_label("No eligible adventurer was supplied.", MUTED))
		return
	for character: InteractionRequestValue.ServiceCharacter in _characters:
		var button := Button.new()
		button.name = "BankCharacter_%s" % character.id.replace(".", "_")
		button.text = _character_row_text(character)
		button.alignment = HORIZONTAL_ALIGNMENT_LEFT
		button.custom_minimum_size.y = 52.0
		button.size_flags_horizontal = Control.SIZE_EXPAND_FILL
		button.toggle_mode = true
		button.button_group = _character_group
		button.pressed.connect(_select_character.bind(character.id))
		rows.add_child(button)
		button.set_pressed_no_signal(character.id == _selected_character_id)


func _build_swap_pane(parent: HBoxContainer) -> void:
	var content := _pane(parent, "BankSwap", "Selected Adventurer", 1.25)
	_summary = VBoxContainer.new()
	_summary.name = "BankSelectedSummary"
	_summary.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	_summary.size_flags_vertical = Control.SIZE_EXPAND_FILL
	_summary.add_theme_constant_override("separation", 5)
	content.add_child(_summary)


func _build_footer() -> void:
	var footer := HBoxContainer.new()
	footer.name = "BankFooter"
	footer.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	footer.add_theme_constant_override("separation", 5)
	add_child(footer)
	_add_response(footer, "BankPool", "Pool party wealth", InteractionResponse.BankBody.new(&"pool"), _body.pool)
	_add_response(footer, "BankShare", "Share pooled wealth", InteractionResponse.BankBody.new(&"share"), _body.share)
	var spacer := Control.new()
	spacer.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	footer.add_child(spacer)
	var done := add_response_to(footer, "Done", InteractionResponse.BankBody.new(&"leave"))
	done.name = "BankDone"
	done.custom_minimum_size.x = 160.0


func _select_character(character_id: String) -> void:
	_selected_character_id = character_id
	_refresh_selected_character()


func _refresh_selected_character() -> void:
	if _summary == null:
		return
	for child: Node in _summary.get_children():
		_summary.remove_child(child)
		child.free()
	var character := _character_by_id(_selected_character_id)
	if character == null or character.wealth == null:
		_summary.add_child(_label("No selected adventurer is available.", MUTED))
		return
	_summary.add_child(_label(character.name, GOLD))
	_summary.add_child(_label(_wealth_text(character.wealth), CYAN))

	_summary.add_child(_label("Load %d/%d" % [character.load, character.maximum_load], MUTED))
	var separator := HSeparator.new()
	_summary.add_child(separator)
	if character.transfers.is_empty():
		_summary.add_child(_label("No exact transfer increment was supplied.", MUTED))
		return
	for transfer: InteractionRequestValue.Transfer in character.transfers:
		_add_transfer_row(character, transfer)


func _add_transfer_row(character: InteractionRequestValue.ServiceCharacter, transfer: InteractionRequestValue.Transfer) -> void:
	var panel := PanelContainer.new()
	panel.name = "BankTransfer_%s" % String(transfer.denomination)
	panel.theme_type_variation = &"ClassicInset"
	panel.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	_summary.add_child(panel)
	var row := HBoxContainer.new()
	row.add_theme_constant_override("separation", 4)
	panel.add_child(row)
	var denomination := String(transfer.denomination)
	var label := _label("%s\n%d per transfer" % [denomination.capitalize(), transfer.amount], GOLD)
	label.custom_minimum_size.x = 110.0
	row.add_child(label)
	var to_pool := add_response_to(row, "To pool", InteractionResponse.BankBody.new(&"to-pool", character.id, denomination, transfer.amount), transfer.to_pool.enabled, transfer.to_pool.reason)
	to_pool.name = "BankToPool_%s" % denomination
