	return InventoryActionProbe.permit()

func classic_trade_probe(source: CharacterState, destination: CharacterState, instance: ItemInstance, item: ItemDefinition) -> InventoryActionProbe:
	if source == null or destination == null or source == destination or instance == null or item == null:
		return InventoryActionProbe.block("Choose another party member.")
	if instance.equipped and not item.cursed_item_id.is_empty():
		return InventoryActionProbe.block("This cursed equipped item cannot be traded away.")
	if destination.inventory().size() >= MAX_ITEMS:
		return InventoryActionProbe.block("%s already carries 30 items." % destination.name)
	if destination.carried_load + item.instance_weight(instance.charges) > destination.maximum_load:
		return InventoryActionProbe.block("%s cannot carry this item's weight." % destination.name)
	for carried: ItemInstance in destination.inventory():
		if carried.id == instance.id:
			return InventoryActionProbe.block("The destination already has this item instance.")
	return InventoryActionProbe.permit()

func classic_split_probe(character: CharacterState, instance: ItemInstance, item: ItemDefinition) -> InventoryActionProbe:
	if character == null or instance == null or item == null or instance.definition_id != item.id:
		return InventoryActionProbe.block("The carried item is unavailable.")
	if not character.inventory().has(instance):
		return InventoryActionProbe.block("The selected item is no longer carried.")
	if item.weight_per_charge == 0:
		return InventoryActionProbe.block("Classic allows Split only for an item with per-charge weight.")
	if instance.charges < 2:
		return InventoryActionProbe.block("At least two charges are required to split this item.")
	if character.inventory().size() >= MAX_ITEMS:
		return InventoryActionProbe.block("This character already carries 30 items.")
	return InventoryActionProbe.permit()

func classic_join_probe(character: CharacterState, instance: ItemInstance, item: ItemDefinition) -> InventoryActionProbe:
	if character == null or instance == null or item == null or instance.definition_id != item.id:
		return InventoryActionProbe.block("The carried item is unavailable.")
	if item.weight_per_charge == 0:
		return InventoryActionProbe.block("Classic allows Join only for an item with per-charge weight.")
	var matches := _matching_instances(character, instance.definition_id)
	if not matches.has(instance):
		return InventoryActionProbe.block("The selected item is no longer carried.")
	if matches.size() < 2:
		return InventoryActionProbe.block("No other matching stack is available to join.")
	var total_charges := 0
	for candidate: ItemInstance in matches:
		if candidate.charges < 0:
			return InventoryActionProbe.block("Infinite-charge items cannot be joined safely.")
		total_charges += candidate.charges
		if total_charges > 32_767:
			return InventoryActionProbe.block("Joining these stacks would exceed the supported charge limit.")
		if candidate != instance and candidate.equipped and not item.cursed_item_id.is_empty():
			return InventoryActionProbe.block("An equipped cursed stack cannot be absorbed into another item.")
	return InventoryActionProbe.permit()

func equip_classic(character: CharacterState, instance: ItemInstance, item: ItemDefinition, race: RaceDefinition, caste: CasteDefinition, party: Array[CharacterState], definitions: Array[ItemDefinition]) -> InventoryActionProbe:
	var probe := classic_equip_probe(character, instance, item, race, caste, party, definitions)
	if not probe.allowed:
		return probe
	instance.equipped = true
	if not item.cursed_item_id.is_empty():
		instance.identified = true
	return probe

func unequip_classic(character: CharacterState, instance: ItemInstance, item: ItemDefinition, definitions: Array[ItemDefinition]) -> InventoryActionProbe:
	var probe := classic_unequip_probe(character, instance, item, definitions)
	if probe.allowed:
		instance.equipped = false
	return probe

func classic_spell_item_probe(character: CharacterState, instance: ItemInstance, item: ItemDefinition, spell: SpellDefinition, race: RaceDefinition, caste: CasteDefinition, in_combat: bool) -> InventoryActionProbe:
	if instance == null or item == null or instance.definition_id != item.id:
		return InventoryActionProbe.block("The carried item is unavailable.")
	var use_probe := classic_use_probe(character, item, race, caste)
	if not use_probe.allowed:
		return use_probe
	if item.special_2 <= 1100:
		return InventoryActionProbe.block("This item has no Classic spell effect.")
	if spell == null or spell.classic_id != item.special_2:
		return InventoryActionProbe.block("The item's Classic spell is unavailable.")
	if instance.charges == 0:
		return InventoryActionProbe.block("This item has no charges remaining.")
	if instance.charges < 0 and item.initial_charges >= 0:
		return InventoryActionProbe.block("The item's charge state does not match its immutable definition.")
	var power := absi(item.special_1)
	if power < 1 or power > 8:
		return InventoryActionProbe.block("The item's Classic spell power is invalid.")
	if in_combat and not spell.in_combat:
		return InventoryActionProbe.block("This item cannot be used in combat.")
	if not in_combat and not spell.in_camp:
		return InventoryActionProbe.block("This item cannot be used outside combat.")
	return InventoryActionProbe.permit()

func classic_use_probe(character: CharacterState, item: ItemDefinition, race: RaceDefinition, caste: CasteDefinition) -> InventoryActionProbe:
	if character == null or item == null or race == null or caste == null:
		return InventoryActionProbe.block("The character or immutable item definition is unavailable.")
	if not item.specific_race_id.is_empty() and item.specific_race_id != character.race_id:
		return InventoryActionProbe.block("This item requires %s." % item.specific_race_id.replace("_", " ").capitalize())
	if not item.specific_caste_id.is_empty() and item.specific_caste_id != character.caste_id:
		return InventoryActionProbe.block("This item requires %s." % item.specific_caste_id.replace("_", " ").capitalize())
	var category := _first_category(item.item_category_mask_low, item.item_category_mask_high)
	if category < 0:
		return InventoryActionProbe.block("This item has no Classic usability category.")
	if not _mask_has(race.item_category_mask_low, race.item_category_mask_high, category):
		return InventoryActionProbe.block("This race cannot use this item category.")
	if not _mask_has(caste.item_category_mask_low, caste.item_category_mask_high, category):
		return InventoryActionProbe.block("This class cannot use this item category.")
	if (item.race_restrictions & race.descriptor_flags) != 0:
		return InventoryActionProbe.block("This item's race restrictions exclude the character.")
	if item.race_class_only != 0 and (item.race_class_only & race.descriptor_flags) != item.race_class_only:
		return InventoryActionProbe.block("This item requires race traits the character does not have.")
	var caste_class_index := caste.caste_class - 1
	if caste_class_index < 0 or caste_class_index > 15:
		return InventoryActionProbe.block("The character's Classic class group is invalid.")
	if (item.caste_restrictions & (1 << caste_class_index)) != 0:
		return InventoryActionProbe.block("This item's class restrictions exclude the character.")
	if item.caste_class_only != 0 and (item.caste_class_only & (1 << caste_class_index)) == 0:
		return InventoryActionProbe.block("This item requires another Classic class group.")
	return InventoryActionProbe.permit()

func can_equip(character: CharacterState, item: ItemDefinition) -> bool:
	if character == null or item == null:
		return false
	if not item.specific_race_id.is_empty() and item.specific_race_id != character.race_id:
		return false
	if not item.specific_caste_id.is_empty() and item.specific_caste_id != character.caste_id:
		return false
	return true

static func _first_category(low: int, high: int) -> int:
	for index: int in 58:
		if _mask_has(low, high, index):
			return index
	return -1

static func _definitions_by_id(definitions: Array[ItemDefinition]) -> Dictionary:
	var result: Dictionary = {}
	for definition: ItemDefinition in definitions:
		result[definition.id] = definition
	return result

static func _passive_effects_supported(item: ItemDefinition) -> bool:
	if item.strength_bonus != 0 or item.movement_bonus != 0 or item.magic_resistance_bonus != 0 or item.spell_point_bonus != 0:
		return false
	if item.special_3 != 0 or item.special_4 != 0 or item.special_1 == 122:
		return false
	return item.special_1 < 20 or item.special_1 >= 100

func split_classic(character: CharacterState, instance: ItemInstance, item: ItemDefinition, new_instance_id: String) -> InventoryActionProbe:
	var probe := classic_split_probe(character, instance, item)
	if not probe.allowed:
		return probe
	if new_instance_id.is_empty():
		return InventoryActionProbe.block("The split item requires a stable instance identity.")
	var items := character.inventory()
	for carried: ItemInstance in items:
		if carried.id == new_instance_id:
			return InventoryActionProbe.block("The split item identity is already in use.")
	var source_index := items.find(instance)
	if source_index < 0:
		return InventoryActionProbe.block("The selected item is no longer carried.")
	var previous_weight := item.instance_weight(instance.charges)
	var split_charges := int(instance.charges / 2)
	instance.charges -= split_charges
	var split_instance := ItemInstance.new(new_instance_id, instance.definition_id, split_charges, false, instance.identified)
	items.insert(source_index + 1, split_instance)
	character.set_inventory(items)
	var updated_weight := item.instance_weight(instance.charges) + item.instance_weight(split_instance.charges)
	character.carried_load = maxi(0, character.carried_load + updated_weight - previous_weight)
	return probe

func trade_classic(source: CharacterState, destination: CharacterState, instance: ItemInstance, item: ItemDefinition) -> InventoryActionProbe:
	var probe := classic_trade_probe(source, destination, instance, item)
	if not probe.allowed:
		return probe
	var removed := remove_item(source, instance.id, item)
	if removed == null or not restore_item(destination, removed, item):
		if removed != null:
			restore_item(source, removed, item)
		return InventoryActionProbe.block("The item transfer could not be committed.")
	return probe

func _init(is_allowed: bool, disabled_reason: String = "") -> void:
	allowed = is_allowed
	reason = "" if allowed else disabled_reason

func join_classic(character: CharacterState, instance: ItemInstance, item: ItemDefinition) -> InventoryActionProbe:
	var probe := classic_join_probe(character, instance, item)
	if not probe.allowed:
		return probe
	var items := character.inventory()
	var matches := _matching_instances(character, instance.definition_id)
	var total_charges := 0
	var previous_weight := 0
	var merged_equipped := false
	var merged_identified := false
	for candidate: ItemInstance in matches:
		total_charges += candidate.charges
		previous_weight += item.instance_weight(candidate.charges)
		merged_equipped = merged_equipped or candidate.equipped
		merged_identified = merged_identified or candidate.identified
		if candidate != instance:
			items.erase(candidate)
	instance.charges = total_charges
	instance.equipped = merged_equipped
	instance.identified = merged_identified
	character.set_inventory(items)
	character.carried_load = maxi(0, character.carried_load + item.instance_weight(total_charges) - previous_weight)
	return probe

func change_fatigue(party: PartyState, amount: int) -> int:
	party.fatigue = clampi(party.fatigue + amount, 4, 135)
	return party.fatigue

func advance_minutes(state: GameState, content: RealmzContent, minutes: int, condition_ticks: int = 0) -> Array[DomainEvent]:
	var elapsed := maxi(0, minutes)
	var previous_day := state.clock.day()
	state.clock.advance_minutes(elapsed)
	var events: Array[DomainEvent] = [DomainEvent.new(&"time_advanced", {"minutes": elapsed, "day": state.clock.day(), "hour": state.clock.hour()})]
	for day_index: int in state.clock.day() - previous_day:
		for character: CharacterState in state.party.characters():
			var race := content.race_by_id(character.race_id) if content != null else null
			var caste := content.caste_by_id(character.caste_id) if content != null else null
			if race == null or caste == null:
				continue
			var aging := _characters.advance_age_days(character, race, caste, 1)
			if aging != null and aging.changed_group():
				events.append(DomainEvent.new(&"character_age_changed", aging.event_payload(character, race)))
	for tick: int in condition_ticks:
		events.append_array(_conditions.tick_party(state.party))
	return events

func advance_classic_field_time(state: GameState, content: RealmzContent, timeclicks: int, minutes_per_timeclick: int, defer_midnight_recovery: bool = false) -> Array[DomainEvent]:
	var clicks := maxi(0, timeclicks)
	var scale := clampi(minutes_per_timeclick, 1, 5)
	var previous_minutes := state.clock.total_minutes()
	var events := advance_minutes(state, content, clicks * scale)
	var current_minutes := state.clock.total_minutes()
	var first_hour_boundary := floori(float(previous_minutes) / 60.0) + 1
	var last_hour_boundary := floori(float(current_minutes) / 60.0)
	for hour_boundary: int in range(first_hour_boundary, last_hour_boundary + 1):
		events.append_array(_conditions.tick_party(state.party))
		var previous_fatigue := state.party.fatigue
		change_fatigue(state.party, 1)
		events.append(DomainEvent.new(&"fatigue_changed", {"previous": previous_fatigue, "current": state.party.fatigue, "reason": "hour-boundary", "source": "classic"}))
		events.append_array(_restore_spell_points(state.party))
		if hour_boundary % 12 == 0 and not (defer_midnight_recovery and hour_boundary % 24 == 0):
			events.append_array(_restore_half_day_health(state.party, content))
	return events

func _consume_iron_ration(party: PartyState, content: RealmzContent) -> Dictionary:
	var definition := content.item_by_classic_id(877)
	if definition == null:
		return {}
	for character: CharacterState in party.characters():
		for instance: ItemInstance in character.inventory():
			if instance.definition_id != definition.id or instance.charges <= 0:
				continue
			var instance_id := instance.id
			if not _inventory.use_charge(character, instance_id, definition):
				return {}
			return {"characterId": character.id, "instanceId": instance_id, "itemId": definition.id, "chargesRemaining": maxi(0, instance.charges), "source": "classic-half-day"}
	return {}

func _restore_half_day_health(party: PartyState, content: RealmzContent) -> Array[DomainEvent]:
	var events: Array[DomainEvent] = []
	for character: CharacterState in party.characters():
		if character.current_health >= character.maximum_health or character.current_health <= -10:
			continue
		var ration := _consume_iron_ration(party, content)
		var amount := floori(float(character.level) / 3.0)
		if ration.is_empty():
			amount = floori(float(amount) / 2.0)
		amount = maxi(1, amount)
		amount += character.conditions.value(ConditionRules.POISONED)
		if not ration.is_empty():
			events.append(DomainEvent.new(&"rest_ration_consumed", ration))
		if character.conditions.is_active(ConditionRules.TURNED_TO_STONE):
			continue
		var previous_health := character.current_health
		character.current_health = clampi(character.current_health + amount, -10, character.maximum_health)
		var restored := character.current_health - previous_health
		if restored != 0:
			events.append(DomainEvent.new(&"health_recovered", {"characterId": character.id, "amount": restored, "source": "classic-half-day"}))
	for ally: MonsterState in party.allies():
		if ally.current_health >= ally.maximum_health:
			continue
		var previous_health := ally.current_health
		ally.current_health = mini(ally.maximum_health, ally.current_health + floori(float(ally.hit_dice) / 4.0) + 1)
		var restored := ally.current_health - previous_health
		if restored != 0:
			events.append(DomainEvent.new(&"ally_health_recovered", {"allyId": ally.id, "amount": restored, "source": "classic-half-day"}))
	return events

func _restore_spell_points(party: PartyState) -> Array[DomainEvent]:
	var events: Array[DomainEvent] = []
	for character: CharacterState in party.characters():
		if character.current_health <= 0 or character.conditions.is_active(ConditionRules.ANIMATED) or character.spell_points >= character.maximum_spell_points:
			continue
		var amount := mini(maxi(1, floori(float(character.level) / 2.0)), character.maximum_spell_points - character.spell_points)
		character.spell_points += amount
		events.append(DomainEvent.new(&"spell_points_recovered", {"characterId": character.id, "amount": amount, "source": "classic-hour"}))
	for ally: MonsterState in party.allies():
		if ally.spell_points >= ally.maximum_spell_points:
			continue
		var amount := mini(maxi(1, floori(float(ally.hit_dice) / 2.0)), ally.maximum_spell_points - ally.spell_points)
		ally.spell_points += amount
		events.append(DomainEvent.new(&"ally_spell_points_recovered", {"allyId": ally.id, "amount": amount, "source": "classic-hour"}))
	return events

func add_item(character: CharacterState, item: ItemDefinition, instance_id: String, identified: bool = false) -> ItemInstance:
	if character == null or item == null or character.inventory().size() >= MAX_ITEMS:
		return null
	var instance := ItemInstance.new(instance_id, item.id, item.initial_charges, false, identified)
	var items := character.inventory()
	if character.carried_load + item.instance_weight(instance.charges) > character.maximum_load:
		return null
	items.append(instance)
	character.set_inventory(items)
	character.carried_load += item.instance_weight(instance.charges)
	return instance

func _matching_instances(character: CharacterState, definition_id: String) -> Array[ItemInstance]:
	var result: Array[ItemInstance] = []
	if character == null or definition_id.is_empty():
		return result
	for carried: ItemInstance in character.inventory():
		if carried.definition_id == definition_id:
			result.append(carried)
	return result

func restore_item(character: CharacterState, item: ItemInstance, definition: ItemDefinition) -> bool:
	if not can_restore_item(character, item, definition):
		return false
	var items := character.inventory()
	item.equipped = false
	items.append(item)
	character.set_inventory(items)
	character.carried_load += definition.instance_weight(item.charges)
	return true

func signed_32(value: int) -> int:
	var wrapped := value & 0xffffffff
	return wrapped - 0x1_0000_0000 if wrapped >= 0x8000_0000 else wrapped

func available(party: PartyState, kind: WealthState.Kind) -> int:
	if party == null:
		return 0
	var result := party.pooled_wealth.amount(kind)
	for character: CharacterState in party.characters():
		result += character.money.amount(kind)
	return result

func item_price(item: ItemDefinition, shop: ShopDefinition, selling: bool = false) -> int:
	if item == null or shop == null:
		return 0
	return shop_sell_price(item, null, shop.inflation_percent) if selling else shop_buy_price(item, shop.inflation_percent)

func shop_buy_price(item: ItemDefinition, inflation_percent: int) -> int:
	if item == null:
		return 0
	return mini(32_000, int(float(absi(item.cost) * maxi(0, inflation_percent)) / 100.0))

func shop_sell_price(item: ItemDefinition, instance: ItemInstance, inflation_percent: int) -> int:
	if item == null:
		return 0
	var current_charges := item.initial_charges if instance == null else instance.charges
	var condition := 1.0
	if item.initial_charges > 0:
		condition = float(current_charges) / float(item.initial_charges)
	# Castle divides current charges by authored charges. A literal 0/0 reaches
	# nonportable float-to-short conversion; uncharged items retain full condition.
	var half_cost := absi(item.cost) / 2
	var conditioned_cost := absi(int(float(half_cost) * condition))
	var price := mini(32_000, int(float(conditioned_cost * mini(maxi(0, inflation_percent), 100)) / 100.0))
	if instance != null and not instance.identified:
		price /= 50
	return maxi(0, price)

static func experience_multiplier(recommended_levels: int, current_levels: int, difficulty: int) -> float:
	if recommended_levels <= 0 or current_levels <= 0:
		return 0.0
	return clampf(difficulty_multiplier(difficulty) * float(recommended_levels) / float(current_levels), 0.20, 2.50)

func signed_16(value: int) -> int:
	var wrapped := value & 0xffff
	return wrapped - 0x10000 if wrapped >= 0x8000 else wrapped

func _apply_starting_conditions(monster: MonsterState, definition: MonsterDefinition) -> void:
	var values := definition.starting_conditions()
	for index: int in mini(values.size(), monster.conditions.size()):
		monster.conditions.set_value(index, values[index])

func _random_weapon(table_id: int, instance_id: String, rng: RealmzRng) -> String:
	var table_index := 8 if table_id == 10 else table_id - 1
	if table_index < 0 or table_index >= RANDOM_WEAPON_TABLES.size():
		return ""
	var roll := rng.draw(100, StringName("monster.%s.random-weapon" % instance_id))
	for range_row: Array in RANDOM_WEAPON_TABLES[table_index]:
		if roll >= int(range_row[0]) and roll <= int(range_row[1]):
			return "classic.item.%d" % int(range_row[2])
	return ""

func _battle_random_weapon(table_id: int, instance_id: String, rng: RealmzRng) -> String:
	var table_index := 8 if table_id == 10 else table_id - 1
	if table_index < 0 or table_index >= RANDOM_WEAPON_TABLES.size():
		return ""
	var roll := rng.draw(100, StringName("battle.monster.%s.random-weapon" % instance_id))
	var result := ""
	# Authored battle construction does not return from the table scan. Its
	# overlapping roll 85 in table 2 is therefore owned by the later row.
	for range_row: Array in RANDOM_WEAPON_TABLES[table_index]:
		if roll >= int(range_row[0]) and roll <= int(range_row[1]):
			result = "classic.item.%d" % int(range_row[2])
	return result

static func random_weapon_item_ids(table_id: int) -> Array[String]:
	var table_index := 8 if table_id == 10 else table_id - 1
	var result: Array[String] = []
	if table_index < 0 or table_index >= RANDOM_WEAPON_TABLES.size():
		return result
	for range_row: Array in RANDOM_WEAPON_TABLES[table_index]:
		var item_id := "classic.item.%d" % int(range_row[2])
		if not result.has(item_id):
			result.append(item_id)
	return result

func choose_action(monster: MonsterState, definition: MonsterDefinition, rng: RealmzRng, has_adjacent_enemy: bool = false) -> StringName:
	if monster.conditions.is_active(ConditionRules.RUNS_AWAY):
		return &"retreat"
	if rng.draw(100, &"monster.ai.missile") <= definition.missile_percent and not has_adjacent_enemy:
		return &"missile"
	return choose_action_after_missile(monster, definition, rng)

func choose_action_after_missile(monster: MonsterState, definition: MonsterDefinition, rng: RealmzRng) -> StringName:
	# Castle consumes the casting-choice roll after an adjacent missile fallback,
	# an out-of-range missile, or a missile whose power cannot be afforded, and
	# before checking conditions that prevent the cast.
	var cast_roll := rng.draw(100, &"monster.ai.cast")
	if cast_roll <= definition.cast_percent and not monster.conditions.is_active(ConditionRules.STUPID) and not monster.conditions.is_active(ConditionRules.CONFUSED) and not monster.conditions.is_active(ConditionRules.SILENCED) and not monster.conditions.is_active(ConditionRules.HELPLESS):
		return &"cast"
	return &"advance"

func morale_action(monster: MonsterState, definition: MonsterDefinition) -> StringName:
	if monster.current_health <= 0:
		return &"defeated"
	# Castle getup.c computes current/current before the thresholds; preserve the observable 100 percent result.
	var percent := 100
	var surrender_percent := monster.surrender_percent if monster.surrender_percent != 0 else definition.surrender_percent
	if percent < surrender_percent:
		return &"panic" if surrender_percent == 101 else &"surrender"
	if percent < definition.run_percent:
		return &"retreat"
	return &"fight"

func take(party: PartyState, amount: int, kind: WealthState.Kind) -> bool:
	if amount < 0:
		return false
	var total_available := party.pooled_wealth.amount(kind)
	for character: CharacterState in party.characters():
		total_available += character.money.amount(kind)
	if amount > total_available:
		return false
	var from_pool := mini(amount, party.pooled_wealth.amount(kind))
	party.pooled_wealth.add(kind, -from_pool)
	var remaining := amount - from_pool
	var characters := party.characters()
	var index := 0
	while remaining > 0:
		var character := characters[index]
		if character.money.amount(kind) > 0:
			character.money.add(kind, -1)
			character.carried_load = maxi(0, character.carried_load - (15 if kind == WealthState.Kind.JEWELRY else 1))
			remaining -= 1
		index = (index + 1) % characters.size()
	return true

func take_from_pool_and_character(party: PartyState, character: CharacterState, amount: int, kind: WealthState.Kind) -> bool:
	if party == null or character == null:
		return false
	if amount < 0:
		party.pooled_wealth.add(kind, -amount)
		return true
	if amount > party.pooled_wealth.amount(kind) + character.money.amount(kind):
		return false
	var from_pool := mini(amount, party.pooled_wealth.amount(kind))
	party.pooled_wealth.add(kind, -from_pool)
	var from_character := amount - from_pool
	character.money.add(kind, -from_character)
	character.carried_load = maxi(0, character.carried_load - from_character * wealth_weight(kind))
	return true

func share_pooled_wealth(party: PartyState) -> bool:
	if not share_probe(party).allowed:
		return false
	var changed := false
	for kind: WealthState.Kind in [WealthState.Kind.JEWELRY, WealthState.Kind.GEMS, WealthState.Kind.GOLD]:
		var assigned := true
		while party.pooled_wealth.amount(kind) > 0 and assigned:
			assigned = false
			for character: CharacterState in party.characters():
				if party.pooled_wealth.amount(kind) < 1:
					break
				# FD-ECONOMY-003: Castle checks only current load here, so
				# jewelry can overload a recipient even though Swap rejects it.
				if character.carried_load + wealth_weight(kind) <= character.maximum_load:
					assigned = true
					changed = true
					character.money.add(kind, 1)
					character.carried_load += wealth_weight(kind)
					party.pooled_wealth.add(kind, -1)
	return changed

func share_probe(party: PartyState) -> EconomyActionProbe:
	if party == null:
		return EconomyActionProbe.new(false, "No party is available.")
	if party.pooled_wealth.gold < 1 and party.pooled_wealth.gems < 1 and party.pooled_wealth.jewelry < 1:
		return EconomyActionProbe.new(false, "The party wealth pool is empty.")
	for kind: WealthState.Kind in [WealthState.Kind.JEWELRY, WealthState.Kind.GEMS, WealthState.Kind.GOLD]:
		if party.pooled_wealth.amount(kind) < 1:
			continue
		for character: CharacterState in party.characters():
			if character.carried_load + wealth_weight(kind) <= character.maximum_load:
				return EconomyActionProbe.new(true)
	return EconomyActionProbe.new(false, "No adventurer can carry another pooled denomination.")

func transfer_probe(party: PartyState, character: CharacterState, kind: WealthState.Kind, amount: int, to_character: bool) -> EconomyActionProbe:
	if party == null or character == null:
		return EconomyActionProbe.new(false, "The selected adventurer is unavailable.")
	if amount != classic_transfer_increment(kind):
		return EconomyActionProbe.new(false, "The transfer does not use the Classic denomination increment.")
	if to_character:
		if party.pooled_wealth.amount(kind) < amount:
			return EconomyActionProbe.new(false, "The party pool does not contain that amount.")
		if character.carried_load + wealth_weight(kind) * amount > character.maximum_load:
			return EconomyActionProbe.new(false, "%s cannot carry that denomination." % character.name)
		return EconomyActionProbe.new(true)
	if character.money.amount(kind) < amount:
		return EconomyActionProbe.new(false, "%s does not carry that amount." % character.name)
	return EconomyActionProbe.new(true)

func bank_to_pool(party: PartyState) -> void:
	if party == null:
		return
	for kind: WealthState.Kind in [WealthState.Kind.GOLD, WealthState.Kind.GEMS, WealthState.Kind.JEWELRY]:
		party.pooled_wealth.add(kind, party.banked_wealth.amount(kind))
		party.banked_wealth.set_amount(kind, 0)

func pool_probe(party: PartyState) -> EconomyActionProbe:
	if party == null:
		return EconomyActionProbe.new(false, "No party is available.")
	for character: CharacterState in party.characters():
		if character.money.gold > 0 or character.money.gems > 0 or character.money.jewelry > 0:
			return EconomyActionProbe.new(true)
	return EconomyActionProbe.new(false, "No adventurer carries wealth to pool.")

func calculated_load(character: CharacterState, definitions: Array[ItemDefinition]) -> int:
	if character == null:
		return -1
	var definitions_by_id := _definitions_by_id(definitions)
	var total := character.money.gold + character.money.gems + character.money.jewelry * 15
	for instance: ItemInstance in character.inventory():
		var definition: ItemDefinition = definitions_by_id.get(instance.definition_id)
		if definition == null:
			return -1
		total += definition.instance_weight(instance.charges)
	return maxi(0, total)

func equip(character: CharacterState, instance_id: String, definition: ItemDefinition) -> bool:
	if not can_equip(character, definition):
		return false
	for instance: ItemInstance in character.inventory():
		if instance.id == instance_id and instance.definition_id == definition.id:
			instance.equipped = true
			return true
	return false

func use_charge(character: CharacterState, instance_id: String, definition: ItemDefinition) -> bool:
	var items := character.inventory()
	for index: int in items.size():
		var instance := items[index]
		if instance.id != instance_id or instance.definition_id != definition.id or instance.charges == 0:
			continue
		if instance.charges > 0:
			instance.charges -= 1
			character.carried_load = maxi(0, character.carried_load - definition.weight_per_charge)
		if instance.charges == 0 and definition.drop_on_empty:
			items.remove_at(index)
			character.carried_load = maxi(0, character.carried_load - definition.weight)
			character.set_inventory(items)
		return true
	return false

func remove_item(character: CharacterState, instance_id: String, definition: ItemDefinition) -> ItemInstance:
	if character == null or definition == null:
		return null
	var items := character.inventory()
	for index: int in items.size():
		var instance := items[index]
		if instance.id != instance_id or instance.definition_id != definition.id:
			continue
		items.remove_at(index)
		character.set_inventory(items)
		character.carried_load = maxi(0, character.carried_load - definition.instance_weight(instance.charges))
		return instance
	return null

func can_restore_item(character: CharacterState, item: ItemInstance, definition: ItemDefinition) -> bool:
	if character == null or item == null or definition == null or item.definition_id != definition.id:
		return false
	var items := character.inventory()
	if items.size() >= MAX_ITEMS or character.carried_load + definition.instance_weight(item.charges) > character.maximum_load:
		return false
	for carried: ItemInstance in items:
		if carried.id == item.id:
			return false
	return true

func pool_party_wealth(party: PartyState) -> bool:
	if not pool_probe(party).allowed:
		return false
	for character: CharacterState in party.characters():
		party.pooled_wealth.gold += character.money.gold
		party.pooled_wealth.gems += character.money.gems
		party.pooled_wealth.jewelry += character.money.jewelry
		character.carried_load = maxi(0, character.carried_load - character.money.gold - character.money.gems - character.money.jewelry * 15)
		character.money = WealthState.new()
	return true

func _init(is_allowed: bool, unavailable_reason: String = "") -> void:
	allowed = is_allowed
	reason = "" if is_allowed else unavailable_reason

func pool_to_bank(party: PartyState) -> void:
	if party == null:
		return
	for kind: WealthState.Kind in [WealthState.Kind.GOLD, WealthState.Kind.GEMS, WealthState.Kind.JEWELRY]:
		party.banked_wealth.add(kind, party.pooled_wealth.amount(kind))
		party.pooled_wealth.set_amount(kind, 0)

func tick_character(character: CharacterState) -> Array[DomainEvent]:
	var events: Array[DomainEvent] = []
	if character.conditions.is_active(REGENERATING) and character.current_health > -10 and character.current_health < character.maximum_health and not character.conditions.is_active(ANIMATED):
		var healed := mini(absi(character.conditions.value(REGENERATING)), character.maximum_health - character.current_health)
		character.current_health += healed
		events.append(DomainEvent.new(&"condition_healed", {"characterId": character.id, "condition": REGENERATING, "amount": healed}))
	for index: int in [DISEASED, POISONED]:
		if character.conditions.is_active(index) and character.current_health > 0 and character.conditions.value(ANIMATED) > -1:
			var damage := absi(character.conditions.value(index))
			character.current_health -= damage
			events.append(DomainEvent.new(&"condition_damaged", {"characterId": character.id, "condition": index, "amount": damage}))
	if character.conditions.is_active(ENERGY_DRAIN) and character.current_health > 0:
		character.spell_points = maxi(0, character.spell_points - absi(character.conditions.value(ENERGY_DRAIN)))
	if character.conditions.is_active(ABSORBING_ENERGY) and character.maximum_spell_points > 0 and character.current_health > 0:
		character.spell_points = mini(character.maximum_spell_points, character.spell_points + absi(character.conditions.value(ABSORBING_ENERGY)))
	for index: int in character.conditions.decay_positive():
		events.append(DomainEvent.new(&"condition_expired", {"characterId": character.id, "condition": index}))
	return events

func tick_party(party: PartyState) -> Array[DomainEvent]:
	var events: Array[DomainEvent] = []
	for index: int in party.conditions.decay_positive():
		events.append(DomainEvent.new(&"party_condition_expired", {"condition": index}))
	# Castle reduces every positive party condition once, then reduces Torch Lit
	# once more. Values already expired by the shared pass are not decremented again.
	if party.conditions.value(PARTY_TORCH_LIT) > 0:
		party.conditions.add(PARTY_TORCH_LIT, -1)
		if party.conditions.value(PARTY_TORCH_LIT) == 0:
			events.append(DomainEvent.new(&"party_condition_expired", {"condition": PARTY_TORCH_LIT}))
	for character: CharacterState in party.characters():
		events.append_array(tick_character(character))
	for ally: MonsterState in party.allies():
		for index: int in ally.conditions.decay_positive():
			events.append(DomainEvent.new(&"ally_condition_expired", {"allyId": ally.id, "condition": index}))
	return events

