	for target: MonsterView in combat.targets:
		target_ids[target.id] = true
	for monster: MonsterView in combat.monsters:
		if _playback_hides(monster.id):
			continue
		var footprint := combat.battlefield.monster_footprint(monster.id)
		var source_anchor := combat.battlefield.monster_position(monster.id)
		var effective_anchor := _effective_actor_position(combat, monster.id)
		if source_anchor.x >= 0 and effective_anchor.x >= 0 and source_anchor != effective_anchor:
			var offset := effective_anchor - source_anchor
			for index: int in footprint.size():
				footprint[index] += offset
		var visible_footprint: Array[Vector2i] = []
		for coordinate: Vector2i in footprint:
			if coordinate_is_visible(coordinate, camera, visible_cells):
				visible_footprint.append(coordinate)
		if visible_footprint.is_empty():
			continue
		var rect := footprint_rect(visible_footprint, camera, draw_origin)
		if _playback_frame != null and _playback_frame.actor_id == monster.id and _playback_frame.kind == &"move_start":
			rect.position = _interpolated_draw_position(_playback_frame, camera, draw_origin)
		var asset := _media.asset_by_resource(monster.icon_resource_type, monster.icon_id) if _media != null else null
		_draw_actor(rect, _texture_for(asset), monster.name, _actor_is_highlighted(monster.id, combat.active_actor_id), target_ids.has(monster.id), monster.traitor)

func _draw() -> void:
	if _view == null or _view.combat_view == null or _view.combat_view.battlefield == null:
		return
	var combat := _view.combat_view
	var battlefield := combat.battlefield
	var focus_id := camera_focus_id_for(_playback_frame, _camera_focus_id, combat.active_actor_id)
	var active_position := _effective_actor_position(combat, focus_id)
	if active_position.x < 0:
		active_position = battlefield.party_anchor
	var visible_cells := viewport_cells_for(size)
	var camera := tracked_camera_top_left(
		_render_camera_top_left,
		active_position,
		visible_cells,
		_render_camera_focus_id != focus_id or _render_camera_visible_cells != visible_cells
	)
	_render_camera_top_left = camera
	_render_camera_focus_id = focus_id
	_render_camera_visible_cells = visible_cells
	var draw_origin := battlefield_draw_origin(size, visible_cells)
	_draw_header(combat)
	for y: int in visible_cells.y:
		for x: int in visible_cells.x:
			var coordinate := camera + Vector2i(x, y)
			var rect := Rect2(draw_origin + Vector2(x, y) * NATIVE_CELL_SIZE, Vector2.ONE * NATIVE_CELL_SIZE)
			_draw_terrain_cell(battlefield.terrain_at(coordinate), rect)
	_draw_revealed_relationships(combat, camera, visible_cells, draw_origin)
	_draw_movement_options(combat, camera, visible_cells, draw_origin)
	_draw_targeting_preview(combat, camera, visible_cells, draw_origin)
	_draw_characters(combat, camera, visible_cells, draw_origin)
	_draw_monsters(combat, camera, visible_cells, draw_origin)
	_draw_playback_overlay(combat, camera, visible_cells, draw_origin)
	_draw_tactical_legend()
	if not has_battle_artwork():
		draw_string(_ui_font(), Vector2(draw_origin.x + 8.0, draw_origin.y + 20.0), "Battle artwork unavailable", HORIZONTAL_ALIGNMENT_LEFT, -1.0, 13, Color(1.0, 0.78, 0.42))

func _movement_option_for_destination(destination: Vector2i) -> CombatMoveOptionView:
	if _view == null or _view.combat_view == null:
		return null
	for option: CombatMoveOptionView in _view.combat_view.movement_options:
		if option.destination == destination:
			return option
	return null

func _movement_option_toward_local_position(local_position: Vector2) -> CombatMoveOptionView:
	if _view == null or _view.combat_view == null or _view.combat_view.battlefield == null:
		return null
	var origin := actor_position(_view.combat_view, _view.party_members, _view.combat_view.active_actor_id)
	var visible_cells := viewport_cells_for(size)
	var camera := _camera_for_input(origin, visible_cells)
	var draw_origin := battlefield_draw_origin(size, visible_cells)
	return _movement_option_for_direction(click_direction_for_point(cell_rect(origin, camera, draw_origin), local_position))

func _camera_for_input(fallback_focus: Vector2i, visible_cells: Vector2i) -> Vector2i:
	if _render_camera_top_left.x >= 0 and _render_camera_visible_cells == visible_cells:
		return _render_camera_top_left
	return camera_top_left(fallback_focus, visible_cells)

func _submit_movement_option(option: CombatMoveOptionView) -> bool:
	if option == null or not option.enabled or _view == null or _view.combat_view == null:
		return false
	var body := InteractionResponse.CombatBody.new(&"retreat_edge" if option.retreats_from_battle else &"move", _view.combat_view.active_actor_id)
	body.destination = option.destination
	body.has_destination = true
	combat_body_submitted.emit(body)
	return true

func _draw_characters(combat: CombatView, camera: Vector2i, visible_cells: Vector2i, draw_origin: Vector2) -> void:
	var target_ids: Dictionary = {}
	for target: CharacterView in combat.character_targets:
		target_ids[target.id] = true
	for character: CharacterView in _view.party_members:
		if _playback_hides(character.id):
			continue
		var coordinate := _effective_actor_position(combat, character.id)
		if not coordinate_is_visible(coordinate, camera, visible_cells):
			continue
		var rect := _playback_actor_rect(character.id, coordinate, camera, draw_origin)
		var asset := _media.asset_by_id(character.combat_icon_id) if _media != null else null
		_draw_actor(rect, _texture_for(asset), character.name, _actor_is_highlighted(character.id, combat.active_actor_id), target_ids.has(character.id), character.traitor)

func _draw_revealed_relationships(combat: CombatView, camera: Vector2i, visible_cells: Vector2i, draw_origin: Vector2) -> void:
	if not _reveal_friends:
		return
	var origin := actor_position(combat, _view.party_members, combat.active_actor_id)
	if not coordinate_is_visible(origin, camera, visible_cells):
		return
	var start := cell_rect(origin, camera, draw_origin).get_center()
	for character: CharacterView in _view.party_members:
		var coordinate := combat.battlefield.character_position(character.id)
		if character.id == combat.active_actor_id or not coordinate_is_visible(coordinate, camera, visible_cells):
			continue
		var color := Color(0.20, 0.42, 1.0, 0.90) if character.condition_values[ConditionRules.HELPLESS] != 0 else Color(0.18, 0.90, 0.38, 0.86) if combat.friendly_actor_ids.has(character.id) else Color(0.95, 0.22, 0.18, 0.86)
		draw_line(start, cell_rect(coordinate, camera, draw_origin).get_center(), color, 2.0)
	for monster: MonsterView in combat.monsters:
		var coordinate := combat.battlefield.monster_position(monster.id)
		if not coordinate_is_visible(coordinate, camera, visible_cells):
			continue
		var color := Color(0.20, 0.42, 1.0, 0.90) if monster.helpless else Color(0.18, 0.90, 0.38, 0.86) if combat.friendly_actor_ids.has(monster.id) else Color(0.95, 0.22, 0.18, 0.86)
		draw_line(start, cell_rect(coordinate, camera, draw_origin).get_center(), color, 2.0)

func toggle_reveal_friends() -> void:
	_reveal_friends = not _reveal_friends
	queue_redraw()

func dismiss_reveal_friends() -> bool:
	if not _reveal_friends:
		return false
	_reveal_friends = false
	queue_redraw()
	return true

func _begin_held_command(command_id: StringName) -> void:
	_held_command = command_id
	_activate_command(command_id)
	if not _held_command.is_empty():
		_held_command_timer.start()

func _stop_held_command() -> void:
	_held_command = &""
	if _held_command_timer != null:
		_held_command_timer.stop()
	_update_command_availability()

func _on_held_command_button_up() -> void:
	# A synchronous pulse may replace the footer while the pointer is still held.
	# Godot releases the removed BaseButton, but that is not a mouse release.
	if should_stop_held_command_on_button_up(Input.is_mouse_button_pressed(MOUSE_BUTTON_LEFT)):
		_stop_held_command()

func _on_held_command_timeout() -> void:
	if _held_command.is_empty():
		_stop_held_command()
		return
	if _current_view == null or _current_view.pending_interaction != null or not _current_view.availability(_held_command).enabled:
		_stop_held_command()
		return
	_activate_command(_held_command, true)

func _notification(what: int) -> void:
	if what == NOTIFICATION_APPLICATION_FOCUS_OUT:
		_stop_held_command()

func _on_menu_item_pressed(item_id: int, menu: MenuButton) -> void:
	var entry: Dictionary = _menu_actions.get(menu.get_instance_id(), {}).get(item_id, {})
	if entry.is_empty() or not String(entry.get("disabled_reason", "")).is_empty():
		return
	if entry.has("route"):
		_router.open_screen(StringName(entry["route"]))
	elif entry.has("command"):
		_activate_command(StringName(entry["command"]))
	elif entry.has("system"):
		_on_system_action_requested(StringName(entry["system"]), null)

func _fill_menu(menu: MenuButton, entries: Array[Dictionary]) -> void:
	var popup := menu.get_popup()
	popup.clear()
	var actions: Dictionary = {}
	var enabled_count := 0
	for index: int in entries.size():
		var entry := entries[index]
		popup.add_item(String(entry["label"]), index)
		var reason := String(entry.get("disabled_reason", ""))
		if reason.is_empty() and entry.has("route"):
			reason = route_change_reason(_current_view)
		if not reason.is_empty():
			entry["disabled_reason"] = reason
		actions[index] = entry
		if not reason.is_empty():
			popup.set_item_disabled(index, true)
			popup.set_item_tooltip(index, reason)
		else:
			enabled_count += 1
	_menu_actions[menu.get_instance_id()] = actions
	menu.disabled = enabled_count == 0
	if not _menus_connected.has(menu.get_instance_id()):
		popup.id_pressed.connect(_on_menu_item_pressed.bind(menu))
		_menus_connected[menu.get_instance_id()] = true

func _apply_exploration_mode() -> void:
	if not is_node_ready():
		return
	var camping := _current_view != null and _current_view.party_summary != null and _current_view.party_summary.camping
	_world_command_heading.text = "Camp" if camping else "Adventure"
	_world_command_panel.theme_type_variation = &"ClassicInset" if camping else &""

func handle_back() -> bool:
	if _music_dialog != null and _music_dialog.visible:
		_music_dialog.close()
		return true
	if _picture_stage.visible:
		_picture_stage.visible = false
		return true
	var handled := _router.handle_back()
	if handled:
		var play_regions_visible := _current_view != null and _current_view.session_started and not _router.full_stage_overlay_visible()
		_set_play_regions_visible(play_regions_visible)
	return handled

func handle_route_shortcut(event: InputEvent) -> bool:
	for definition: Dictionary in UiRouteCatalog.ROUTES:
		var shortcut := StringName(definition["shortcut"])
		if not shortcut.is_empty() and event.is_action_pressed(shortcut):
			if not route_change_reason(_current_view).is_empty():
				return true
			_router.open_screen(StringName(definition["id"]))
			return true
	return false

func selected_fast_spell(slot_index: int) -> Dictionary:
	if _current_view == null or slot_index < 0 or slot_index >= 10:
		return {}
	var character: CharacterView = null
	for candidate: CharacterView in _current_view.party_members:
		if candidate.id == _selected_character_id:
			character = candidate
			break
	if character == null and not _current_view.party_members.is_empty():
		character = _current_view.party_members[0]
	if character == null or slot_index >= character.fast_spells.size():
		return {}
	var binding := character.fast_spells[slot_index]
	return {
		"characterId": character.id,
		"characterName": character.name,
		"slot": slot_index,
		"spellId": binding.spell_id,
		"spellName": binding.spell_name,
		"power": binding.power,
		"enabled": binding.activation.enabled,
		"reason": binding.activation.reason,
	}

static func held_command_start_sound_id(command_id: StringName, held_repeat: bool) -> int:
	if held_repeat:
		return 0
	return int(HELD_COMMAND_START_SOUND_IDS.get(command_id, 0))

func _contextual_service() -> ServiceView:
	if _current_view == null:
		return null
	for service: ServiceView in _current_view.services:
		if service.service_kind in [&"shop", &"temple"] and not service.actions.is_empty():
			return service
	return null

func submit_movement_direction(direction: Vector2i) -> bool:
	if _playback_frame != null or _targeting != null:
		return false
	var option := _movement_option_for_direction(direction)
	return _submit_movement_option(option)

func _gui_input(event: InputEvent) -> void:
	if _playback_frame != null or _view == null or _view.combat_view == null or _view.combat_view.battlefield == null:
		return
	if _targeting != null:
		_handle_targeting_input(event)
		return
	if event is InputEventMouseMotion:
		var hover_option := _movement_option_toward_local_position((event as InputEventMouseMotion).position)
		var next_hover := hover_option.destination if hover_option != null else Vector2i(-1, -1)
		if next_hover != _hovered_coordinate:
			_hovered_coordinate = next_hover
			queue_redraw()
		return
	if event is InputEventMouseButton and (event as InputEventMouseButton).button_index == MOUSE_BUTTON_LEFT and (event as InputEventMouseButton).pressed:
		if dismiss_reveal_friends():
			accept_event()
			return
		if (event as InputEventMouseButton).ctrl_pressed or (event as InputEventMouseButton).meta_pressed:
			var inspected_id := combatant_at(_view.combat_view, _view.party_members, _coordinate_at_local_position((event as InputEventMouseButton).position))
			if not inspected_id.is_empty():
				focus_combatant(inspected_id)
				combatant_inspected.emit(inspected_id)
				accept_event()
			return
		if _submit_movement_option(_movement_option_toward_local_position((event as InputEventMouseButton).position)):
			accept_event()

func _notification(what: int) -> void:
	if what != NOTIFICATION_MOUSE_EXIT:
		return
	var changed := false
	if _hovered_coordinate != Vector2i(-1, -1):
		_hovered_coordinate = Vector2i(-1, -1)
		changed = true
	if _targeting != null and _targeting.selected_coordinate.x < 0 and _targeting.hovered_coordinate != Vector2i(-1, -1):
		_targeting.hovered_coordinate = Vector2i(-1, -1)
		changed = true
	if changed:
		queue_redraw()

func begin_targeting(configuration: CombatTargetingRequest) -> bool:
	if _playback_frame != null or _view == null or _view.combat_view == null:
		return false
	if configuration == null or not configuration.is_valid():
		return false
	_targeting = CombatTargetingState.new(configuration)
	_reveal_friends = false
	targeting_changed.emit(_targeting)
	queue_redraw()
	return true

func confirm_targeting() -> bool:
	if _targeting == null:
		return false
	var body := _targeting.committed_body()
	if body == null:
		targeting_changed.emit(_targeting)
		return false
	_targeting = null
	queue_redraw()
	combat_body_submitted.emit(body)
	return true

func _presentation_command_definition(definition: Dictionary) -> Dictionary:
	var result := definition.duplicate()
	var command_id := StringName(definition.get("id", &""))
	if command_id == &"search_mode" and _current_view != null and _current_view.party_summary != null and _current_view.party_summary.searching:
		result["label"] = "Stop Search"
		result["tooltip"] = "Stop continuous secret searching"
		return result
	if command_id != &"contextual":
		return result
	var service := _contextual_service()
	if service == null:
		return result
	result["label"] = service.title
	result["tooltip"] = "Enter %s" % service.title
	result["availability"] = &"service_action"
	if service.service_kind == &"temple":
		result["asset_id"] = &"command.temple"
		result["art_region"] = [9, 2, 37, 34]
		result.erase("art_mask")
	else:
		result["asset_id"] = &""
		result.erase("art_region")
		result.erase("art_mask")
	return result

func stop_music() -> void:
	if _music_player != null:
		_music_player.stop()
	var changed := current_music_playlist_id != 0 or not current_music_title.is_empty()
	current_music_playlist_id = 0
	current_music_title = ""
	if changed:
		music_state_changed.emit(0, "", false)

func set_music_volume(value: float) -> void:
	music_volume = clampf(value, 0.0, 1.0)
	_apply_volume()

func _rebuild_command_deck() -> void:
	if not is_node_ready() or _profile == null:
		return
	for grid: GridContainer in [_world_command_grid, _command_grid]:
		for child: Node in grid.get_children():
			grid.remove_child(child)
			child.queue_free()
	_simulation_buttons.clear()
	var context := &"encounter" if _current_view != null and _current_view.pending_interaction != null else _router.current_screen()
	for definition: Dictionary in ClassicCommandCatalog.for_context(context):
		definition = _presentation_command_definition(definition)
		var button: BaseButton
		if bool(definition.get("search_animation", false)):
			var search_button := SEARCH_BUTTON_SCRIPT.new() as BaseButton
			search_button.command_requested.connect(_activate_command)
			search_button.set_meta("search_animation", true)
			button = search_button
		elif bool(definition.get("torch_meter", false)):
			var torch_button := TORCH_BUTTON_SCRIPT.new() as BaseButton
			torch_button.command_requested.connect(_activate_command)
			torch_button.set_meta("torch_meter", true)
			button = torch_button
		else:
			var bitmap := ClassicBitmapButton.new()
			bitmap.configure(definition, _profile.bitmap_scale)
			if bool(definition.get("hold_repeat", false)):
				bitmap.button_down.connect(_begin_held_command.bind(StringName(definition["id"])))
				bitmap.button_up.connect(_on_held_command_button_up)
			else:
				bitmap.command_requested.connect(_activate_command)
			button = bitmap
		button.set_meta("focus_key", "command:%s" % definition["id"])
		var group := StringName(definition.get("group", &"party"))
		var target_grid := _world_command_grid if group == &"world" and _world_command_panel.visible else _command_grid
		target_grid.add_child(button)
		_simulation_buttons[StringName(definition["id"])] = button
	_update_command_availability()

func _update_command_availability() -> void:
	for command_id: StringName in _simulation_buttons:
		var button := _simulation_buttons[command_id] as BaseButton
		var definition := _presentation_command_definition(ClassicCommandCatalog.command(command_id))
		var availability_id := StringName(definition.get("availability", &""))
		var reason := ""
		if _current_view == null or not _current_view.session_started:
			reason = "Begin a campaign first."
		elif _current_view.pending_interaction != null and not String(command_id).begins_with("encounter_"):
			reason = "Resolve the current interaction first."
		elif String(command_id).begins_with("encounter_"):
			reason = "Choose from the active encounter response controls."
		elif not availability_id.is_empty():
			reason = _availability_reason(availability_id)
		if bool(button.get_meta("search_animation", false)):
			var summary := _current_view.party_summary if _current_view != null else null
			button.call("sync_status",
				false if summary == null else summary.searching,
				reason.is_empty(),
				reason
			)
		elif bool(button.get_meta("torch_meter", false)):
			var summary := _current_view.party_summary if _current_view != null else null
			button.call("sync_status",
				0 if summary == null else summary.light_remaining,
				false if summary == null else summary.has_classic_torch,
				reason.is_empty(),
				reason
			)
		else:
			button.disabled = not reason.is_empty()
			button.tooltip_text = reason if not reason.is_empty() else "Break camp" if command_id == &"camp" and _current_view.party_summary != null and _current_view.party_summary.camping else String(definition.get("tooltip", ""))
			if button is ClassicBitmapButton:
				(button as ClassicBitmapButton).set_visual_pressed(_command_is_visually_pressed(command_id))
		button.queue_redraw()

func _command_is_visually_pressed(command_id: StringName) -> bool:
	var party_summary := _current_view.party_summary if _current_view != null else null
	if command_id == &"camp":
		return party_summary != null and party_summary.camping
	if command_id == _held_command:
		return true
	return command_route(command_id) == _router.current_screen()

func has_battle_artwork() -> bool:
	if _atlas_asset == null or _atlas_texture == null:
		return false
	if _upper_atlas_id.is_empty():
		return true
	return _upper_atlas_asset != null and _upper_atlas_texture != null

func position_for(combatant_id: String) -> Vector2i:
	var value: Variant = combatant_positions.get(combatant_id)
	if value is Vector2i:
		return value
	return Vector2i(-1, -1)

func _append_bleeding_result(event: DomainEvent, positions: Dictionary, hidden: Array[String], defeated: bool) -> void:
	var target_id := String(event.payload.get("characterId", ""))
	var frame := _new_frame(&"result", RESULT_SECONDS, positions, hidden)
	frame.target_id = target_id
	frame.result_kind = &"bleeding"
	frame.display_text = "Bled to death" if defeated else "Bleeding"
	_frames.append(frame)
	if defeated and not target_id.is_empty() and not hidden.has(target_id):
		hidden.append(target_id)

func _append_next_actor_cue() -> void:
	if final_view == null or final_view.combat_view == null or final_view.combat_view.outcome != &"active":
		return
	var prior_actor := previous_view.combat_view.active_actor_id if previous_view != null and previous_view.combat_view != null else ""
	var next_actor := final_view.combat_view.active_actor_id
	var prior_round := previous_view.combat_view.round_number if previous_view != null and previous_view.combat_view != null else -1
	if next_actor == prior_actor and final_view.combat_view.round_number == prior_round:
		return
	var positions := _positions_for(final_view)
	var cue := _new_frame(&"actor_cue", CUE_SECONDS, positions, [])
	cue.actor_id = next_actor
	cue.target_id = next_actor
	cue.display_text = "Round %d" % final_view.combat_view.round_number if final_view.combat_view.round_number != prior_round else ""
	_frames.append(cue)

func _assign_camera_focus_ids() -> void:
	var latest_focus_id := ""
	for frame: CombatPlaybackFrame in _frames:
		var frame_focus_id := frame.actor_id if not frame.actor_id.is_empty() else frame.target_id
		if not frame_focus_id.is_empty():
			latest_focus_id = frame_focus_id
		frame.camera_focus_id = latest_focus_id
	var next_focus_id := ""
	for index: int in range(_frames.size() - 1, -1, -1):
		var frame := _frames[index]
		if not frame.camera_focus_id.is_empty():
			next_focus_id = frame.camera_focus_id
		elif not next_focus_id.is_empty():
			frame.camera_focus_id = next_focus_id

func _new_frame(kind: StringName, duration: float, positions: Dictionary, hidden: Array[String]) -> CombatPlaybackFrame:
	var frame := CombatPlaybackFrame.new(kind, duration)
	frame.combatant_positions = positions.duplicate(true)
	frame.hidden_combatant_ids = hidden.duplicate()
	return frame

func _positions_for(view: GameView) -> Dictionary:
	var result: Dictionary = {}
	if view == null or view.combat_view == null or view.combat_view.battlefield == null:
		return result
	for character: CharacterView in view.party_members:
		var coordinate := view.combat_view.battlefield.character_position(character.id)
		if coordinate.x >= 0:
			result[character.id] = coordinate
	for monster: MonsterView in view.combat_view.monsters:
		var coordinate := view.combat_view.battlefield.monster_position(monster.id)
		if coordinate.x >= 0:
			result[monster.id] = coordinate
	return result

func _append_turn_undead_result(event: DomainEvent, positions: Dictionary, hidden: Array[String]) -> void:
	var result_kind := StringName(event.payload.get("result", "resisted"))
	var text := "Resist" if result_kind == &"resisted" else "Destroyed" if result_kind == &"destroyed" else "Turned"
	var result := _new_frame(&"result", RESULT_SECONDS, positions, hidden)
	result.actor_id = String(event.payload.get("actorId", ""))
	result.target_id = String(event.payload.get("targetId", ""))
	result.result_kind = result_kind
	result.display_text = text
	_frames.append(result)
	if result_kind == &"turned":
		for _frame_index_value: int in int(event.payload.get("effectFrameCount", 0)):
			var effect := _new_frame(&"spell_effect", SPELL_EFFECT_SECONDS, positions, hidden)
			effect.actor_id = String(event.payload.get("actorId", ""))
			effect.target_id = String(event.payload.get("targetId", ""))
			effect.to_coordinate = _position_for(effect.target_id, positions)
			effect.effect_resource_id = int(event.payload.get("effectResourceId", 0)) + _frame_index_value
			_frames.append(effect)
	elif result_kind == &"destroyed":
		var target_id := String(event.payload.get("targetId", ""))
		if not target_id.is_empty() and not hidden.has(target_id):
			hidden.append(target_id)

func _position_for(combatant_id: String, positions: Dictionary) -> Vector2i:
	var value: Variant = positions.get(combatant_id)
	if value is Vector2i:
		return value
	var coordinate := _view_position(previous_view, combatant_id)
	if coordinate.x >= 0:
		return coordinate
	return _view_position(final_view, combatant_id)

func _init(frame_kind: StringName, frame_duration_seconds: float) -> void:
	kind = frame_kind
	duration_seconds = maxf(frame_duration_seconds, 0.0)

func _append_spell_cast(event: DomainEvent, positions: Dictionary, hidden: Array[String]) -> void:
	var cast := _new_frame(&"spell_cast", SPELL_CAST_SECONDS, positions, hidden)
	cast.actor_id = String(event.payload.get("actorId", ""))
	cast.target_id = String(event.payload.get("targetId", ""))
	cast.from_coordinate = _position_for(cast.actor_id, positions)
	cast.to_coordinate = _payload_coordinate(event.payload.get("areaCenter"))
	if cast.to_coordinate.x < 0:
		cast.to_coordinate = _position_for(cast.target_id, positions)
	cast.effect_resource_id = int(event.payload.get("classicEffectResourceId", 0))
	_frames.append(cast)

func _append_spell_result(event: DomainEvent, positions: Dictionary, hidden: Array[String]) -> void:
	_append_result(event, positions, hidden)
	if bool(event.payload.get("defeated", false)):
		return
	var effect_ids: Array = event.payload.get("classicResolutionEffectResourceIds", []) as Array
	for effect_value: Variant in effect_ids:
		var effect := _new_frame(&"spell_effect", SPELL_EFFECT_SECONDS, positions, hidden)
		effect.actor_id = String(event.payload.get("actorId", ""))
		effect.target_id = String(event.payload.get("targetId", ""))
		effect.to_coordinate = _payload_coordinate(event.payload.get("areaCenter"))
		if effect.to_coordinate.x < 0:
			effect.to_coordinate = _position_for(effect.target_id, positions)
		effect.effect_resource_id = int(effect_value)
		_frames.append(effect)

static func route_change_reason(game_view: GameView) -> String:
