func _apply_volume() -> void:
	for player: AudioStreamPlayer in _players:
		var effective_sound := master_volume * sound_volume
		player.volume_db = -80.0 if effective_sound <= 0.0 else linear_to_db(effective_sound)
	if _music_player != null:
		var effective_music := master_volume * music_volume
		_music_player.volume_db = -80.0 if effective_music <= 0.0 else linear_to_db(effective_music)

func _drain_sound_queue() -> void:
	if _processing_sounds:
		return
	while not _pending_sounds.is_empty():
		var request: Dictionary = _pending_sounds.pop_front()
		var player := _next_channel()
		if player == null:
			continue
		player.stop()
		player.stream = request["stream"] as AudioStream
		player.play()
		if bool(request["waitForCompletion"]) and player.playing:
			_processing_sounds = true
			blocking_state_changed.emit(true)
			_waiting_player = player
			_waiting_finished_callback = _on_waiting_sound_finished.bind(player)
			player.finished.connect(_waiting_finished_callback, CONNECT_ONE_SHOT)
			return

func _next_channel() -> AudioStreamPlayer:
	if _players.is_empty():
		return null
	_channel_index = (_channel_index + 1) % _players.size()
	return _players[_channel_index]

func _stop_all() -> void:
	var was_blocking := _processing_sounds
	if _waiting_player != null and _waiting_finished_callback.is_valid() and _waiting_player.finished.is_connected(_waiting_finished_callback):
		_waiting_player.finished.disconnect(_waiting_finished_callback)
	_waiting_player = null
	_waiting_finished_callback = Callable()
	_processing_sounds = false
	_pending_sounds.clear()
	for player: AudioStreamPlayer in _players:
		player.stop()
	if was_blocking:
		blocking_state_changed.emit(false)

static func _payload_coordinate(value: Variant) -> Vector2i:
	if value is Vector2i:
		return value
	if value is Array and value.size() == 2:
		return Vector2i(int(value[0]), int(value[1]))
	return Vector2i(-1, -1)

func _install_selected(path: String) -> void:
	if path.get_extension().to_lower() == "realmz2":
		start_requested.emit(path, 1)

static func _sha256(bytes: PackedByteArray) -> String:
	var hashing := HashingContext.new()
	if hashing.start(HashingContext.HASH_SHA256) != OK or hashing.update(bytes) != OK:
		return ""
	return hashing.finish().hex_encode()

func _load_manifest(path: String) -> void:
	var parsed: Variant = JSON.parse_string(FileAccess.get_file_as_string(path))
	if not parsed is Dictionary:
		last_error = "Classic application music manifest is unavailable or malformed."
		return
	var manifest := parsed as Dictionary
	if int(manifest.get("schema_version", 0)) != 1 or String(manifest.get("ownership", "")) != "classic-application" or int(manifest.get("slot_count", 0)) != 20 or String(manifest.get("lookup", "")) != "playlist-id":
		last_error = "Classic application music manifest contract is unsupported."
		return
	for value: Variant in manifest.get("tracks", []):
		if not value is Dictionary:
			last_error = "Classic application music contains a malformed track."
			return
		var record := value as Dictionary
		var playlist_id := int(record.get("playlist_id", 0))
		if playlist_id < 1 or playlist_id > 11 or _tracks.has(playlist_id) or String(record.get("path", "")).is_empty() or int(record.get("bytes", 0)) <= 0 or String(record.get("sha256", "")).length() != 64:
			last_error = "Classic application music contains an incomplete or duplicate track."
			return
		_tracks[playlist_id] = record.duplicate(true)
	if _tracks.size() != 11:
		last_error = "Classic application music does not contain the complete stock track bank."

func _stock_track_id(playlist_id: int) -> int:
	if playlist_id >= 12 and playlist_id <= 14:
		return 1
	return playlist_id

func _gui_input(event: InputEvent) -> void:
	if event is InputEventMouseButton and event.button_index == MOUSE_BUTTON_LEFT:
		if event.pressed:
			_held_direction = _movement_direction_at(event.position)
			if _held_direction != Vector2i.ZERO:
				movement_hold_started.emit(_held_direction)
				accept_event()
		else:
			_held_direction = Vector2i.ZERO
			movement_hold_stopped.emit()
	elif event is InputEventMouseMotion and event.button_mask & MOUSE_BUTTON_MASK_LEFT:
		var next_direction := _movement_direction_at(event.position)
		if next_direction == Vector2i.ZERO and _held_direction != Vector2i.ZERO:
			_held_direction = Vector2i.ZERO
			movement_hold_stopped.emit()
		elif next_direction != Vector2i.ZERO and _held_direction == Vector2i.ZERO:
			_held_direction = next_direction
			movement_hold_started.emit(_held_direction)
		elif next_direction != Vector2i.ZERO and next_direction != _held_direction:
			_held_direction = next_direction
			movement_hold_updated.emit(_held_direction)

