func _draw() -> void:
	if _view == null or _view.map_view == null:
		return
	var map_view := _view.map_view
	var font := get_theme_font(&"font", &"Label")
	var viewport_cells := viewport_cells_for(size, map_origin.y, cell_size)
	var draw_origin := map_draw_origin_for(size, map_origin, cell_size, viewport_cells)
	var map_rect := Rect2(draw_origin, Vector2(viewport_cells) * cell_size)
	_draw_exploration_stage(map_rect)
	var camera := camera_top_left(map_view.party_coordinate, Vector2i(map_view.width, map_view.height), viewport_cells)
	var camera_end := camera + viewport_cells
	for cell: MapCellView in map_view.cells():
		if cell.coordinate.x < camera.x or cell.coordinate.y < camera.y or cell.coordinate.x >= camera_end.x or cell.coordinate.y >= camera_end.y:
			continue
		var rect := Rect2(draw_origin + Vector2(cell.coordinate - camera) * cell_size, Vector2.ONE * cell_size)
		_draw_cell(cell, rect, map_view.level_type, map_view.dark)
		if show_debug_facts:
			draw_rect(rect, Color(0.22, 0.25, 0.30), false, 1.0)
			_draw_edges(cell, rect)
			_draw_features(cell, rect)
			if cell.has_trigger:
				var center := rect.get_center()
				draw_colored_polygon(PackedVector2Array([center + Vector2(0, -6), center + Vector2(6, 0), center + Vector2(0, 6), center + Vector2(-6, 0)]), Color(0.95, 0.72, 0.26))
			if cell.in_random_region:
				draw_rect(rect.grow(-4.0), Color(0.48, 0.29, 0.58, 0.9), false, 2.0)
			var facts := "%s%s%s" % ["M" if cell.passable else "X", "L" if cell.blocks_los else "", "R" if cell.in_random_region else ""]
			draw_string(font, rect.position + Vector2(7, 17), facts, HORIZONTAL_ALIGNMENT_LEFT, -1, 12, Color(0.78, 0.82, 0.88))
	_party_rect = Rect2(draw_origin + Vector2(map_view.party_coordinate - camera) * cell_size, Vector2.ONE * cell_size)
	_draw_party_marker(_party_rect)
	if show_travel_preview:
		_draw_minimap(map_view, font)
	else:
		_minimap_rect = Rect2()

func _draw_exploration_stage(map_rect: Rect2) -> void:
	var gutter := Color(0.035, 0.04, 0.045, 0.72)
	if map_rect.position.x > 8.0:
		_draw_stage_gutter(Rect2(0.0, map_rect.position.y, map_rect.position.x - 4.0, map_rect.size.y), gutter)
	if map_rect.end.x < size.x - 8.0:
		_draw_stage_gutter(Rect2(map_rect.end.x + 4.0, map_rect.position.y, size.x - map_rect.end.x - 4.0, map_rect.size.y), gutter)
	draw_rect(map_rect.grow(4.0), Color(0.08, 0.09, 0.095, 1.0), false, 4.0)
	draw_rect(map_rect.grow(1.0), Color(0.48, 0.49, 0.46, 0.9), false, 1.0)

func _draw_stage_gutter(rect: Rect2, fallback_color: Color) -> void:
	draw_rect(rect, fallback_color, true)
	if GUTTER_TEXTURE != null:
		draw_texture_rect(GUTTER_TEXTURE, rect, true, Color(0.55, 0.57, 0.56, 0.9))
	draw_rect(rect, Color(0.34, 0.35, 0.34, 0.72), false, 1.0)
	if GUTTER_RAIL_TEXTURE == null:
		return
	var source_size := GUTTER_RAIL_TEXTURE.get_size()
	var scale_factor: float = minf(1.0, minf(rect.size.x / source_size.x, rect.size.y / source_size.y))
	var rail_size := source_size * scale_factor
	var rail_rect := Rect2(rect.get_center() - rail_size * 0.5, rail_size)
	draw_texture_rect(GUTTER_RAIL_TEXTURE, rail_rect, false, Color(0.72, 0.74, 0.73, 0.88))

func read_bytes(asset: MediaAsset) -> PackedByteArray:
	if package_media != null and package_media.owns_asset(asset):
		return package_media.read_bytes(asset)
	if application_media != null and application_media.owns_asset(asset):
		return application_media.read_bytes(asset)
	return PackedByteArray()

static func camera_top_left(party_coordinate: Vector2i, map_size: Vector2i, viewport_cells: Vector2i) -> Vector2i:
	var maximum := Vector2i(maxi(map_size.x - viewport_cells.x, 0), maxi(map_size.y - viewport_cells.y, 0))
	return Vector2i(
		clampi(party_coordinate.x - viewport_cells.x / 2, 0, maximum.x),
		clampi(party_coordinate.y - viewport_cells.y / 2, 0, maximum.y)
	)

func asset_by_resource(resource_type: String, resource_id: int) -> MediaAsset:
	if package_media != null:
		var package_status := package_media.resource_status(resource_type, resource_id)
		if package_status == &"ambiguous":
			return null
		if package_status == &"resolved":
			return package_media.asset_by_resource(resource_type, resource_id)
	return application_media.asset_by_resource(resource_type, resource_id) if application_media != null else null

func tileset_by_id(tileset_id: String) -> MediaAsset:
	var asset := asset_by_id(tileset_id)
	return asset if asset != null and asset.is_tileset() else null

static func party_marker_asset_id_for_direction(direction: Vector2i, current_asset_id: StringName = PARTY_MARKER_RIGHT_ASSET_ID) -> StringName:
	if direction.x < 0:
		return PARTY_MARKER_LEFT_ASSET_ID
	if direction.x > 0:
		return PARTY_MARKER_RIGHT_ASSET_ID
	return current_asset_id

func read_bytes_batch(requested_assets: Array[MediaAsset]) -> Dictionary:
	var result: Dictionary = {}
	var package_assets: Array[MediaAsset] = []
	for asset: MediaAsset in requested_assets:
		if package_media != null and package_media.owns_asset(asset):
			package_assets.append(asset)
		elif application_media != null and application_media.owns_asset(asset):
			var bytes := application_media.read_bytes(asset)
			if not bytes.is_empty():
				result[asset.id] = bytes
	if package_media != null:
		result.merge(package_media.read_bytes_batch(package_assets), true)
	return result

func image_texture(asset: MediaAsset) -> Texture2D:
	if asset == null:
		return null
	if _image_textures.has(asset.id):
		return _image_textures[asset.id] as Texture2D
	var bytes := read_bytes(asset)
	var texture: Texture2D
	if not bytes.is_empty():
		var image := Image.new()
		var error := ERR_FILE_UNRECOGNIZED
		match asset.mime_type:
			"image/png": error = image.load_png_from_buffer(bytes)
			"image/jpeg": error = image.load_jpg_from_buffer(bytes)
			"image/webp": error = image.load_webp_from_buffer(bytes)
		if error == OK and (asset.width <= 0 or asset.height <= 0 or image.get_width() == asset.width and image.get_height() == asset.height):
			texture = ImageTexture.create_from_image(image)
	_image_textures[asset.id] = texture
	return texture

func audio_stream_by_resource(resource_type: String, resource_id: int) -> AudioStream:
	var asset := asset_by_resource(resource_type, resource_id)
	if asset == null:
		return null
	if application_media != null and application_media.owns_asset(asset):
		return application_media.audio_stream(asset)
	return _decode_stream(asset, package_media.read_bytes(asset)) if package_media != null else null

static func footprint_rect(footprint: Array[Vector2i], camera: Vector2i, draw_origin: Vector2) -> Rect2:
	if footprint.is_empty():
		return Rect2()
	var minimum := footprint[0]
	var maximum := footprint[0]
	for coordinate: Vector2i in footprint:
		minimum = Vector2i(mini(minimum.x, coordinate.x), mini(minimum.y, coordinate.y))
		maximum = Vector2i(maxi(maximum.x, coordinate.x), maxi(maximum.y, coordinate.y))
	return Rect2(draw_origin + Vector2(minimum - camera) * NATIVE_CELL_SIZE, Vector2(maximum - minimum + Vector2i.ONE) * NATIVE_CELL_SIZE)

static func _decode_stream(asset: MediaAsset, bytes: PackedByteArray) -> AudioStream:
	if bytes.is_empty():
		return null
	var mime := asset.mime_type.to_lower()
	var extension := asset.path.get_extension().to_lower()
	if mime == "audio/wav" or mime == "audio/x-wav" or extension == "wav":
		return AudioStreamWAV.load_from_buffer(bytes)
	if mime in ["audio/mpeg", "audio/mp3"] or extension == "mp3":
		return AudioStreamMP3.load_from_buffer(bytes)
	if mime in ["audio/ogg", "audio/vorbis"] or extension == "ogg":
		return AudioStreamOggVorbis.load_from_buffer(bytes)
	return null

func stream(playlist_id: int) -> AudioStream:
	var stock_track_id := _stock_track_id(playlist_id)
	if _streams.has(stock_track_id):
		return _streams[stock_track_id] as AudioStream
	var record := _tracks.get(stock_track_id, {}) as Dictionary
	if record.is_empty():
		return null
	var path := String(record.get("path", ""))
	var bytes := FileAccess.get_file_as_bytes(path)
	if bytes.size() != int(record.get("bytes", 0)) or _sha256(bytes) != String(record.get("sha256", "")):
		last_error = "Classic application music failed integrity validation for playlist %d." % playlist_id
		return null
	var result := load(path) as AudioStream
	if result is AudioStreamOggVorbis:
		(result as AudioStreamOggVorbis).loop = true
	_streams[stock_track_id] = result
	return result

