func target_with_keyboard() -> bool:
	if mode in [&"combatant", &"sequence"]:
		if candidate_ids.is_empty():
			return false
		var current_index := candidate_ids.find(selected_ids[-1]) if not selected_ids.is_empty() else -1
		selected_ids.assign([candidate_ids[(current_index + 1) % candidate_ids.size()]])
		status_text = "Target selected. Press Space to commit the action."
		return true
	if mode != &"area":
		return false
	var coordinate := hovered_coordinate
	if not validation_deferred and not legal_coordinates.has(coordinate):
		coordinate = legal_coordinates[0] if not legal_coordinates.is_empty() else Vector2i(-1, -1)
	if coordinate.x < 0 or coordinate.y < 0:
		return false
	return select_coordinate(coordinate)

func select_coordinate(coordinate: Vector2i) -> bool:
	if mode != &"area":
		return false
	selected_coordinate = coordinate
	if validation_deferred and coordinate.x >= 0 and coordinate.y >= 0:
		status_text = "Target selected. Confirm to validate and cast."
		return true
	if not legal_coordinates.has(coordinate):
		status_text = "That center is outside the rules-owned range, line of sight, or safe mask boundary."
		return false
	status_text = "Area center is legal. Confirm to commit the spell."
	return true

func _init(target_mode: StringName, body: InteractionResponse.CombatBody) -> void:
	mode = target_mode
	response_body = body.duplicate_body() if body != null else null

static func _ensure_loaded() -> void:
	if not _definitions.is_empty():
		return
	var parsed: Variant = JSON.parse_string(FileAccess.get_file_as_string(MANIFEST_PATH))
	if not parsed is Dictionary:
		push_error("Classic UI asset manifest is unavailable or malformed.")
		return
	for value: Variant in (parsed as Dictionary).get("assets", []):
		if value is Dictionary:
			var record := value as Dictionary
			_definitions[String(record.get("id", ""))] = record

func can_confirm() -> bool:
	match mode:
		&"combatant", &"sequence":
			return not selected_ids.is_empty()
		&"area":
			return selected_coordinate.x >= 0 and selected_coordinate.y >= 0 if validation_deferred else legal_coordinates.has(selected_coordinate)
	return false

func _combatant_rect(combat: CombatView, actor_id: String, camera: Vector2i, visible_cells: Vector2i, draw_origin: Vector2) -> Rect2:
	if actor_id.is_empty() or _playback_hides(actor_id):
		return Rect2()
	var coordinate := _effective_actor_position(combat, actor_id)
	if not coordinate_is_visible(coordinate, camera, visible_cells):
		return Rect2()
	for monster: MonsterView in combat.monsters:
		if monster.id != actor_id:
			continue
		var footprint := combat.battlefield.monster_footprint(actor_id)
		var source_anchor := combat.battlefield.monster_position(actor_id)
		var offset := coordinate - source_anchor
		for index: int in footprint.size():
			footprint[index] += offset
		return footprint_rect(footprint, camera, draw_origin)
	return _playback_actor_rect(actor_id, coordinate, camera, draw_origin)

