static func actor_position(combat: CombatView, party_members: Array[CharacterView], actor_id: String) -> Vector2i:
	if combat == null or combat.battlefield == null or actor_id.is_empty():
		return Vector2i(-1, -1)
	for character: CharacterView in party_members:
		if character.id == actor_id:
			return combat.battlefield.character_position(actor_id)
	return combat.battlefield.monster_position(actor_id)

static func actor_name(combat: CombatView, party_members: Array[CharacterView], actor_id: String) -> String:
	for character: CharacterView in party_members:
		if character.id == actor_id:
			return character.name
	if combat != null:
		for monster: MonsterView in combat.monsters:
			if monster.id == actor_id:
				return monster.name
	return actor_id if not actor_id.is_empty() else "Waiting"

static func combatant_at(combat: CombatView, party_members: Array[CharacterView], coordinate: Vector2i) -> String:
	if combat == null or combat.battlefield == null:
		return ""
	for character: CharacterView in party_members:
		if combat.battlefield.character_position(character.id) == coordinate:
			return character.id
	for monster: MonsterView in combat.monsters:
		if combat.battlefield.monster_footprint(monster.id).has(coordinate):
			return monster.id
	return ""

static func click_direction(origin: Vector2i, destination: Vector2i) -> Vector2i:
	var offset := destination - origin
	return Vector2i(signi(offset.x), signi(offset.y))

static func click_direction_for_point(active_cell: Rect2, point: Vector2) -> Vector2i:
	var offset := point - active_cell.get_center()
	if offset.length_squared() <= 36.0:
		return Vector2i.ZERO
	var horizontal := absf(offset.x)
	var vertical := absf(offset.y)
	if horizontal > vertical * 2.41421356:
		return Vector2i(signi(roundi(offset.x)), 0)
	if vertical > horizontal * 2.41421356:
		return Vector2i(0, signi(roundi(offset.y)))
	return Vector2i(signi(roundi(offset.x)), signi(roundi(offset.y)))

func configure(definition: Dictionary, art_scale: int = 1) -> void:
	command_id = StringName(definition.get("id", &""))
	var asset_id := StringName(definition.get("asset_id", &""))
	var pressed_asset_id := StringName(definition.get("pressed_asset_id", &""))
	var direct_path := String(definition.get("asset_path", ""))
	var source_texture := load(direct_path) as Texture2D if not direct_path.is_empty() else ClassicUiAssetCatalog.texture(asset_id)
	var source_pressed_texture := ClassicUiAssetCatalog.texture(pressed_asset_id)
	var art_region: Array = definition.get("art_region", [])
	var art_clear_regions: Array = definition.get("art_clear_regions", [])
	var art_mask := StringName(definition.get("art_mask", &""))
	_art_texture = _prepare_art_texture(source_texture, art_region, art_clear_regions, art_mask)
	_pressed_art_texture = _prepare_art_texture(source_pressed_texture, art_region, art_clear_regions, art_mask)
	texture_normal = null
	_native_size = Vector2i(_art_texture.get_size()) if _art_texture != null else Vector2i.ZERO
	var pressed_native_size := Vector2i(_pressed_art_texture.get_size()) if _pressed_art_texture != null else Vector2i.ZERO
	_native_size = Vector2i(maxi(_native_size.x, pressed_native_size.x), maxi(_native_size.y, pressed_native_size.y))
	if _native_size.x <= 0 or _native_size.y <= 0:
		_native_size = Vector2i(50, 50)
	tooltip_text = String(definition.get("tooltip", ""))
	_label = String(definition.get("label", "Command"))
	_icon_caption_layout = not StringName(definition.get("group", &"")).is_empty()
	toggle_mode = bool(definition.get("toggle_mode", false))
	var accelerator := String(definition.get("accelerator", ""))
	if not accelerator.is_empty():
		tooltip_text += " [%s]" % accelerator
	set_art_scale(art_scale)

static func _array_coordinate(value: Variant) -> Vector2i:
	if value is Vector2i:
		return value
	if value is Array and value.size() == 2:
		return Vector2i(int(value[0]), int(value[1]))
	return Vector2i(-100_000, -100_000)

static func camera_top_left(active_position: Vector2i, visible_cells: Vector2i) -> Vector2i:
	var maximum := Vector2i(BattlefieldState.SIZE, BattlefieldState.SIZE) - visible_cells
	return Vector2i(
		clampi(active_position.x - floori(float(visible_cells.x) / 2.0), 0, maximum.x),
		clampi(active_position.y - floori(float(visible_cells.y) / 2.0), 0, maximum.y)
	)

static func camera_focus_id_for(frame: CombatPlaybackFrame, inspected_focus_id: String, active_actor_id: String) -> String:
	if frame != null and not frame.camera_focus_id.is_empty():
		return frame.camera_focus_id
	if not inspected_focus_id.is_empty():
		return inspected_focus_id
	return active_actor_id

static func tracked_camera_top_left(current_camera: Vector2i, focus_position: Vector2i, visible_cells: Vector2i, force_recenter: bool = false) -> Vector2i:
	if force_recenter or current_camera.x < 0 or not coordinate_is_visible(focus_position, current_camera, visible_cells) or coordinate_is_at_viewport_edge(focus_position, current_camera, visible_cells):
		return camera_top_left(focus_position, visible_cells)
	return current_camera

static func battlefield_draw_origin(control_size: Vector2, visible_cells: Vector2i) -> Vector2:
	var pixel_size := Vector2(visible_cells) * NATIVE_CELL_SIZE
	return Vector2(
		floorf((control_size.x - pixel_size.x) * 0.5),
		HEADER_HEIGHT + floorf(maxf(control_size.y - HEADER_HEIGHT - pixel_size.y, 0.0) * 0.5)
	)

static func viewport_cells_for(control_size: Vector2) -> Vector2i:
	return Vector2i(
		mini(MAX_VISIBLE_COLUMNS, maxi(1, floori(control_size.x / NATIVE_CELL_SIZE))),
		mini(MAX_VISIBLE_ROWS, maxi(1, floori((control_size.y - HEADER_HEIGHT) / NATIVE_CELL_SIZE)))
	)

func activate() -> void:
	if stream == null:
		stream = ResourceLoader.load(INTRO_STREAM_PATH, "VideoStream", ResourceLoader.CACHE_MODE_IGNORE) as VideoStream
	if is_inside_tree() and stream != null and not is_playing():
		play()

func _creation_context() -> String:
	if view == null or view.campaign_summary == null:
		return "Classic Character Files"
	var summary := view.campaign_summary
	var facts: Array[String] = [summary.title]
	if summary.maximum_level > 0:
		facts.append("Maximum level %d" % summary.maximum_level)
	if not summary.restriction_description.strip_edges().is_empty():
		facts.append(summary.restriction_description.strip_edges())
	return " • ".join(facts)

func _populate_race_class_options() -> void:
	if view == null or race_list == null or caste_list == null:
		return
	for option: DefinitionOptionView in view.race_options:
		if _placeholder_definition_name(option.name, "Race"):
			continue
		var race_restricted := view.campaign_summary != null and view.campaign_summary.banned_races.has(option.id)
		race_list.add_option(option.id, option.name, "Unavailable in this scenario." if race_restricted else option.description, not race_restricted, option.id == selected_race_id)
	if selected_race_id.is_empty() or not race_list.is_enabled(selected_race_id):
		selected_race_id = race_list.first_enabled_id()
	race_list.select_id(selected_race_id)
	_rebuild_caste_options()
	if selected_caste_id.is_empty() or not caste_list.is_enabled(selected_caste_id):
		selected_caste_id = caste_list.first_enabled_id()
	caste_list.select_id(selected_caste_id)
	_refresh_race_class_details()

func _refresh_race_class_details() -> void:
	var race_detail_name := creator_page.find_child("RaceDetailName", true, false) as Label
	var race_detail := creator_page.find_child("RaceDescription", true, false) as Label
	var race_facts := creator_page.find_child("RaceFacts", true, false) as Label
	var race_relations := creator_page.find_child("RaceRelations", true, false) as Label
	var caste_detail_name := creator_page.find_child("CasteDetailName", true, false) as Label
	var caste_detail := creator_page.find_child("CasteDescription", true, false) as Label
	var caste_facts := creator_page.find_child("CasteFacts", true, false) as Label
	var caste_relations := creator_page.find_child("CasteRelations", true, false) as Label
	var race_option := _definition_option(view.race_options if view != null else [], selected_race_id)
	var caste_option := _definition_option(view.caste_options if view != null else [], selected_caste_id)
	if race_detail_name != null:
		race_detail_name.text = race_option.name if race_option != null else "No race selected"
	if race_detail != null:
		race_detail.text = race_option.description if race_option != null else ""
		race_detail.visible = not race_detail.text.is_empty()
	if race_facts != null:
		race_facts.text = "\n".join(race_option.facts) if race_option != null else ""
		race_facts.visible = not race_facts.text.is_empty()
	if race_relations != null:
		race_relations.text = _related_definition_text("Compatible Castes", view.caste_options if view != null else [], race_option.related_ids if race_option != null else [])
	if caste_detail_name != null:
		caste_detail_name.text = caste_option.name if caste_option != null else "No caste selected"
	if caste_detail != null:
		caste_detail.text = caste_option.description if caste_option != null else ""
		caste_detail.visible = not caste_detail.text.is_empty()
	if caste_facts != null:
		caste_facts.text = "\n".join(caste_option.facts) if caste_option != null else ""
		caste_facts.visible = not caste_facts.text.is_empty()
	if caste_relations != null:
		caste_relations.text = _related_definition_text("Compatible Races", view.race_options if view != null else [], caste_option.related_ids if caste_option != null else [])

func _campaign_precedes(left: CampaignPackageView, right: CampaignPackageView) -> bool:
