func build(request: InteractionRequest) -> void:
	_can_cancel = false
	if request.kind != InteractionRequest.SESSION_LIFECYCLE:
		return
	var body := request.body as InteractionRequest.LifecycleRequestBody
	if body == null: return
	var compact_quit := body.operation == &"quit-application"
	if not compact_quit:
		var context := Label.new()
		context.name = "LifecycleConsequence"
		context.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
		context.text = "Saving is unavailable during battle." if body.in_combat else "Save first, or end this adventure without saving."
		add_child(context)
	var action_host: Container = self
	if compact_quit:
		var actions := HBoxContainer.new()
		actions.name = "LifecycleActions"
		actions.alignment = BoxContainer.ALIGNMENT_CENTER
		actions.add_theme_constant_override("separation", 8)
		add_child(actions)
		action_host = actions
	for option: InteractionRequestValue.LifecycleOption in body.options:
		var action := option.action
		var label := option.label.strip_edges()
		if action.is_empty() or label.is_empty():
			continue
		_can_cancel = _can_cancel or action == &"cancel"
		var button := add_response_to(action_host, label, InteractionResponse.LifecycleBody.new(action))
		if compact_quit:
			button.custom_minimum_size = Vector2(128.0 if action == &"save-and-quit" else 88.0, 38.0)
			button.size_flags_horizontal = Control.SIZE_SHRINK_CENTER
		if action in [&"save-and-end", &"save-and-quit"]:
			button.theme_type_variation = &"ClassicChoiceButton"
		elif action in [&"end-without-saving", &"quit-without-saving"]:
			button.add_theme_color_override("font_color", Color("d48a78"))
			button.add_theme_color_override("font_hover_color", Color("efaa98"))

func _render_frame() -> void:
	var positions: Array = _body.frames[_frame_index]
	for index: int in _tumblers.size():
		_tumblers[index].configure(int(positions[index]), _body.yellow_threshold, _body.green_threshold)
	var frames_left := _body.time_limit_frames - _elapsed_frames
	var seconds_left := ceili(float(frames_left) / float(_body.frame_rate))
	_countdown.text = "%d sec" % seconds_left
	if _last_second >= 0 and seconds_left != _last_second and seconds_left > 0:
		presentation_sound_requested.emit(10129)
	_last_second = seconds_left

func _unhandled_key_input(event: InputEvent) -> void:
	if event is InputEventKey and event.pressed and not event.echo and event.keycode == KEY_SPACE:
		get_viewport().set_input_as_handled()
		_submit_current_frame()

func _advance_frame() -> void:
	if _submitted or _body == null:
		return
	_elapsed_frames += 1
	_frame_index = mini(_elapsed_frames, _body.frames.size() - 1)
	_render_frame()
	if _elapsed_frames >= _body.time_limit_frames:
		_submit_current_frame()

func handle_back() -> bool:
	if not _can_cancel:
		return false
	response_body_submitted.emit(InteractionResponse.LifecycleBody.new(&"cancel"))
	return true

func _character(character_id: String) -> CharacterView:
	if _game_view == null:
		return null
	for character: CharacterView in _game_view.party_members:
		if character.id == character_id:
			return character
	return null

func _portrait(character_id: String) -> Texture2D:
	var character := _character(character_id)
	return _media.image_texture(_media.asset_by_id(character.portrait_id)) if character != null and _media != null and not character.portrait_id.is_empty() else null

func _submit_current_frame() -> void:
	if _submitted:
		return
	_submitted = true
	if _timer != null:
		_timer.stop()
	response_body_submitted.emit(InteractionResponse.PickLockBody.new(_frame_index))

func _init() -> void:
	custom_minimum_size = Vector2(360.0, 34.0)
	mouse_filter = Control.MOUSE_FILTER_IGNORE

func configure(game_view: GameView, media: ClassicMediaCatalog) -> void:
	_view = game_view
	_media = media

func build(request: InteractionRequest) -> void:
	var body := request.body as InteractionRequest.AcknowledgeBody
	var player_map_id := "" if body == null else body.player_map_id
	var selected: PlayerMapView
	if _view != null:
		for player_map: PlayerMapView in _view.acquired_player_maps:
			if player_map.id == player_map_id:
				selected = player_map
				break
	if selected == null:
		add_hint("The acquired map is unavailable in the current detached view.")
		add_response("Continue", InteractionResponse.AcknowledgeBody.new())
		return
	var presenter := PlayerMapPresenter.new()
	presenter.name = "ImmediatePlayerMap"
	presenter.present(selected, _media)
	add_child(presenter)
	add_response("Continue", InteractionResponse.AcknowledgeBody.new())

func _draw() -> void:
	var track := Rect2(2.0, 7.0, size.x - 4.0, size.y - 14.0)
	draw_rect(track, Color("6b2d2d"), true)
	var yellow_x := track.position.x + track.size.x * float(yellow_threshold) / float(ClassicPickLockRulesScript.TRACK_END)
	var green_x := track.position.x + track.size.x * float(green_threshold) / float(ClassicPickLockRulesScript.TRACK_END)
	draw_rect(Rect2(yellow_x, track.position.y, maxf(0.0, green_x - yellow_x), track.size.y), Color("80672d"), true)
	draw_rect(Rect2(green_x, track.position.y, maxf(0.0, track.end.x - green_x), track.size.y), Color("285b43"), true)
	var marker_x := track.position.x + track.size.x * float(marker_position) / float(ClassicPickLockRulesScript.TRACK_END)
	draw_line(Vector2(marker_x, 2.0), Vector2(marker_x, size.y - 2.0), Color("f2d36b"), 3.0)
	draw_rect(track, Color("626a70"), false, 1.0)

