			break
	return ", ".join(active)

static func _spellbook_saving_throw(spell: SpellView, power: int) -> String:
	if spell.damage_type < 1:
		return "—"
	if spell.cannot > 1:
		return "No"
	if spell.save_adjust == 0 and spell.save_bonus == 0:
		return "Yes"
	return "%+d" % (spell.save_bonus + power * spell.save_adjust)

