func _add_bandage_panel(parent: Control, actor_id: String, targets: Array[InteractionRequestValue.CombatTarget]) -> void:
	_add_hint_to(parent, "Choose one bleeding party member.")
	var picker := OptionButton.new()
	picker.name = "BandageRecipient"
	picker.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	picker.tooltip_text = "Choose one supplied legal Bandage recipient."
	for target: InteractionRequestValue.CombatTarget in targets:
		if not target.id.is_empty():
			picker.add_item("%s • %d HP" % [target.name, target.current_health])
			picker.set_item_metadata(picker.item_count - 1, target.id)
	picker.disabled = picker.item_count == 0
	parent.add_child(picker)
	var submit := Button.new()
	submit.name = "Bandage"
	submit.text = "Bandage selected character"
	submit.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	submit.disabled = picker.item_count == 0
	submit.tooltip_text = "Bandage the selected party member."
	submit.pressed.connect(func() -> void:
		var target_id := String(picker.get_selected_metadata())
		if target_id.is_empty():
			return
		response_body_submitted.emit(InteractionResponse.CombatBody.new(&"bandage", actor_id, target_id))
	)
	parent.add_child(submit)

func _ordered_combatants_from_active() -> Array[InteractionRequestValue.Combatant]:
	var result: Array[InteractionRequestValue.Combatant] = []
	if _combatants.is_empty():
		return result
	var active_index := 0
	for index: int in _combatants.size():
		if _combatants[index].id == _actor_id:
			active_index = index
			break
	for offset: int in _combatants.size():
		result.append(_combatants[(active_index + offset) % _combatants.size()])
	return result

func _continue_after_combat_death_macro(source_kind: StringName, caller: ScenarioBattleCaller, request_id: String, combatant_id: String, program_id: String, events: Array[DomainEvent], reset_traitor_on_complete: bool = true) -> ScenarioRuntimeOperationResult:
	var combat := _game_state.combat
	if combat == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_continuation", "Monster death-macro completion lost its battle.")
	var monster := combat.monster_by_id(combatant_id)
	if monster != null and reset_traitor_on_complete:
		monster.traitor = false
	var committed: Array[DomainEvent] = []
	committed.assign(events)
	committed.append(DomainEvent.new(&"monster_death_macro_completed", {"battleId": combat.battle_id, "combatantId": combatant_id, "programId": program_id, "revived": monster != null and monster.current_health > 0}))
	var previous_round := combat.round_number
	var continued := _rules.combat_flow.continue_after_monster_death_macro(_game_state, _content, _rng, combatant_id)
	if not continued.ok:
		return ScenarioRuntimeOperationResult.failed(continued.error_code, continued.error_message)
	committed.append_array(continued.events)
	if not CharacterAgingResult.update_payloads(continued.events).is_empty():
		return _wait_for_combat_age_updates(source_kind, caller, request_id, committed, previous_round)
	if not _death_macro_request(continued.events).is_empty():
		return _run_combat_death_macro(source_kind, caller, committed, request_id)
	if continued.completed:
		return _finish_battle_with_allies(source_kind, caller, request_id, committed)
	return ScenarioRuntimeOperationResult.waiting(_combat_request(request_id), ScenarioRuntimeContinuation.combat(source_kind, combat.battle_id, caller), committed)

func _apply_classic_condition(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 3:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 43 requires a five-value Extra Code row.")
	var target_mode := action.extra_code[0]
	var condition_index := action.extra_code[1]
	var duration := action.extra_code[2]
	if target_mode < 0 or target_mode > 2 or condition_index < 0 or condition_index >= ConditionSet.CHARACTER_COUNT:
		return ScenarioRuntimeOperationResult.failed(&"invalid_condition", "Classic opcode 43 has an invalid target or condition index.")
	var targets: Array[CharacterState] = []
	if target_mode == 1:
		targets = _game_state.selected_characters()
	else:
		for character: CharacterState in _game_state.party.characters():
			if target_mode == 0 or character.current_health > 0:
				targets.append(character)
	for character: CharacterState in targets:
		character.conditions.set_value(condition_index, duration)
	var ids: Array[String] = []
	for character: CharacterState in targets:
		ids.append(character.id)
	return ScenarioRuntimeOperationResult.completed(ids, [DomainEvent.new(&"condition_applied", {"characterIds": ids, "condition": condition_index, "duration": duration, "soundId": action.extra_code[3] if action.extra_code.size() > 3 else 0})])

func _select_characters_by_identity(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 50 requires a five-value Extra Code row.")
	var selector := action.extra_code[0]
	if selector < 0 or selector > 4:
		return ScenarioRuntimeOperationResult.failed(&"invalid_character_identity_selector", "Classic opcode 50 has an invalid identity selector.")
	var selected: Array[String] = []
	for character: CharacterState in _game_state.party.characters():
		if action.extra_code[4] != 0 and character.current_health <= 0:
			continue
		var race := _content.race_by_id(character.race_id)
		var caste := _content.caste_by_id(character.caste_id)
		var matches := false
		match selector:
			0:
				matches = race != null and race.classic_id == action.extra_code[2]
			1:
				matches = character.gender == action.extra_code[1]
			2:
				matches = caste != null and caste.classic_id == action.extra_code[2]
			3:
				if action.extra_code[2] < 1 or action.extra_code[2] > 32:
					return ScenarioRuntimeOperationResult.failed(&"invalid_race_descriptor", "Classic opcode 50 race descriptor is outside 1 through 32.")
				matches = race != null and (race.descriptor_flags & (1 << (action.extra_code[2] - 1))) != 0
			4:
				matches = caste != null and caste.caste_class == action.extra_code[2]
		if matches:
			selected.append(character.id)
	_game_state.set_selected_character_ids(selected)
	return ScenarioRuntimeOperationResult.completed(selected, [DomainEvent.new(&"characters_selected_by_identity", {"selector": selector, "characterIds": selected, "livingOnly": action.extra_code[4] != 0, "source": "classic"})])

func _select_characters_by_misc(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 3:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 52 requires a five-value Extra Code row.")
	var selector := action.extra_code[0]
	var value := action.extra_code[1]
	var source_mode := action.extra_code[2]
	if selector < 0 or selector > 8 or source_mode < 0 or source_mode > 2:
		return ScenarioRuntimeOperationResult.failed(&"invalid_character_selector", "Classic miscellaneous character selector is invalid.")
	var candidates := _game_state.selected_characters()
	if source_mode != 2:
		candidates = []
		for character: CharacterState in _game_state.party.characters():
			if source_mode == 0 or character.current_health > 0:
				candidates.append(character)
	var selected: Array[String] = []
	var party := _game_state.party.characters()
	for character: CharacterState in candidates:
		var matches := false
		match selector:
			0:
				matches = character.movement < value
			1:
				matches = party.find(character) < value
			2:
				matches = _character_has_classic_item(character, absi(value), false)
			3:
				matches = _rng.draw(100, &"classic.misc-character-percent") <= value
			4:
				matches = _rng.draw(25, &"classic.misc-character-attribute") >= _character_attribute(character, absi(value))
			5:
				matches = _rng.draw(100, &"classic.misc-character-save") > character.save_value(absi(value))
			6:
				matches = not _game_state.selected_character_ids().is_empty() and _game_state.selected_character_ids()[0] == character.id
			7:
				matches = _character_has_classic_item(character, absi(value), true)
			8:
				matches = party.find(character) == value
		if matches:
			selected.append(character.id)
	_game_state.set_selected_character_ids(selected)
	return ScenarioRuntimeOperationResult.completed(selected, [DomainEvent.new(&"characters_selected_by_rule", {"selector": selector, "value": value, "characterIds": selected})])

func _set_spellcasting_flags(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if action.operand_id == 0:
		return ScenarioRuntimeOperationResult.completed(false)
	if action.extra_code.size() < 3:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 69 requires a five-value Extra Code row.")
	_game_state.character_spellcasting_blocked = action.extra_code[0] != 0
	_game_state.monster_spellcasting_blocked = action.extra_code[1] != 0
	_game_state.spell_charging = action.extra_code[2] != 0
	return ScenarioRuntimeOperationResult.completed(true, [DomainEvent.new(&"spellcasting_flags_changed", {"characterCastingBlocked": _game_state.character_spellcasting_blocked, "monsterCastingBlocked": _game_state.monster_spellcasting_blocked, "charging": _game_state.spell_charging, "source": "classic"})])

func _branch_on_ally(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 87 requires a five-value Extra Code row.")
	var monster := _content.monster_by_classic_id_for_set(absi(action.extra_code[0]), _game_state.monster_set)
	var present := false
	if monster != null:
		for ally: MonsterState in _game_state.party.allies():
			var ally_definition := _content.monster_by_id(ally.definition_id)
			if ally_definition != null and ally_definition.classic_id == monster.classic_id:
				present = true
				break
	var event := DomainEvent.new(&"ally_branch_checked", {"classicMonsterId": absi(action.extra_code[0]), "present": present})
	if present:
		var matched := _branch_target_mode(action.extra_code[1], action.extra_code[3], action.gosub)
		matched.events.append(event)
		return matched
	match action.extra_code[2]:
		0:
			var missing := _branch_target_mode(action.extra_code[1], action.extra_code[4], action.gosub)
			missing.events.append(event)
			return missing
		1:
			return ScenarioRuntimeOperationResult.completed(false, [event])
		2:
			var message := _content.message_by_id(action.extra_code[4])
			if message == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_message", "Classic opcode 87 references unavailable message %d." % action.extra_code[4])
			return ScenarioRuntimeOperationResult.completed(false, [event, DomainEvent.new(&"message_shown", {"messageId": message.id, "text": message.text, "source": "classic-ally-check"})], ScenarioVmDirective.finish())
	return ScenarioRuntimeOperationResult.failed(&"invalid_ally_branch", "Classic opcode 87 has an invalid absent-ally behavior.")

func _remove_classic_ally(classic_monster_id: int) -> int:
	var removed := 0
	var retained: Array[MonsterState] = []
	for ally: MonsterState in _game_state.party.allies():
		var definition := _content.monster_by_id(ally.definition_id)
		if definition != null and definition.classic_id == classic_monster_id:
			removed += 1
		else:
			retained.append(ally)
	_game_state.party.set_allies(retained)
	return removed

func _add_classic_ally(classic_monster_id: int) -> ScenarioRuntimeOperationResult:
	var definition := _content.monster_by_classic_id_for_set(classic_monster_id, _game_state.monster_set)
	if definition == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_monster", "Classic opcode 89 references unavailable monster %d." % classic_monster_id)
	var ally := _rules.monsters.build_monster(definition, _game_state.next_instance_id("party.ally"), 0, _game_state.difficulty, _game_state.clock.day(), _rng)
	if ally == null or not _game_state.party.add_ally(ally):
		return ScenarioRuntimeOperationResult.failed(&"ally_add_failed", "The ally could not join the party.")
	return ScenarioRuntimeOperationResult.completed(ally.id, [DomainEvent.new(&"ally_added", {"allyId": ally.id, "monsterId": definition.id})])

func _branch_on_party_condition(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 4:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 40 requires a five-value Extra Code row.")
	var required_state := action.extra_code[0]
	var condition_index := action.extra_code[3]
	if required_state not in [1, 2] or condition_index < 0 or condition_index >= ConditionSet.PARTY_COUNT:
		return ScenarioRuntimeOperationResult.failed(&"invalid_party_condition", "Classic party-condition branch has an invalid state or condition.")
	var active := _game_state.party.conditions.is_active(condition_index)
	if required_state == 1 and not active or required_state == 2 and active:
		return ScenarioRuntimeOperationResult.completed(false)
	return _branch_target_mode(action.extra_code[1] - 1, action.extra_code[2], action.gosub)

func _branch_target_mode(mode: int, target_id: int, gosub: bool) -> ScenarioRuntimeOperationResult:
	if mode == 0:
		return _branch_xap(target_id, gosub)
	return ScenarioRuntimeOperationResult.failed(&"unsupported_branch_target", "Classic branch target mode %d is not available in this execution context." % mode)

func _branch_xap(target_id: int, gosub: bool) -> ScenarioRuntimeOperationResult:
	if target_id == 0:
		return ScenarioRuntimeOperationResult.completed(false)
	return ScenarioRuntimeOperationResult.completed(true, [], ScenarioVmDirective.branch_xap(target_id, gosub))

func _with_age_update_interactions(operation: ScenarioRuntimeOperationResult, request_id: String) -> ScenarioRuntimeOperationResult:
	if operation == null or operation.state != ScenarioRuntimeOperationResult.State.COMPLETED:
		return operation
	var updates := CharacterAgingResult.update_bodies(operation.events)
	if updates.is_empty():
		return operation
	var continuation := ScenarioRuntimeContinuation.age_updates(ScenarioRuntimeContinuation.CLASSIC_AGE_UPDATES, updates, 1, operation.value, operation.directive)
	var events: Array[DomainEvent] = []
	events.assign(operation.events)
	events.append(CharacterAgingResult.sound_event_for_update(updates[0]))
	return ScenarioRuntimeOperationResult.waiting(InteractionRequest.age_update_body(request_id, updates[0]), continuation, events)

func apply_scenario_spell(action: ClassicActionDefinition, entire_party: bool) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 4:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode %d requires a four-value Extra Code row." % action.opcode)
	var spell := _content.spell_by_classic_id(int(action.extra_code[0]))
	if spell == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_spell", "Classic opcode %d references unavailable packed spell %d." % [action.opcode, int(action.extra_code[0])])
	var targets := _game_state.party.characters() if entire_party else _game_state.selected_characters()
	if targets.is_empty():
		return ScenarioRuntimeOperationResult.failed(&"no_selected_characters", "Classic opcode %d has no selected character targets." % action.opcode)
	var events: Array[DomainEvent] = []
	for character: CharacterState in targets:
		var before_health := character.current_health
		var before_conditions := character.conditions.values()
		var caste := _content.caste_by_id(character.caste_id)
		var race := _content.race_by_id(character.race_id)
		var resolution := _rules.magic.resolve_scenario_spell(character, spell, int(action.extra_code[1]), int(action.extra_code[2]), int(action.extra_code[3]) != 0, _rng, caste, race)
		if resolution == null:
			return ScenarioRuntimeOperationResult.failed(&"invalid_spell_effect", "Classic scenario spell inputs are invalid.")
		events.append(DomainEvent.new(&"scenario_spell_applied", {
			"spellId": spell.id,
			"classicSpellId": spell.classic_id,
			"characterId": character.id,
			"powerLevel": int(action.extra_code[1]),
			"saved": resolution.saved,
			"damage": resolution.damage,
			"duration": resolution.duration,
			"healthBefore": before_health,
			"healthAfter": character.current_health,
			"conditionsChanged": before_conditions != character.conditions.values(),
			"source": "classic",
		}))
		if resolution.aging != null and resolution.aging.changed_group():
			events.append(DomainEvent.new(&"character_age_changed", resolution.aging.event_payload(character, race)))
	return ScenarioRuntimeOperationResult.completed(targets.size(), events)

func _resume_combat_death_macro(continuation: ScenarioRuntimeContinuation, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	var combat_continuation := continuation.body as ScenarioRuntimeContinuation.CombatBody
	if _game_state.combat == null or _game_state.combat.battle_id != combat_continuation.battle_id:
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_continuation", "The pending monster death macro is unavailable.")
	var snapshot := combat_continuation.macro_vm
	if snapshot == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_death_macro_continuation", "The pending monster death-macro state is invalid.")
	var vm := ScenarioVm.new()
	vm.configure(_content.scenario)
	if not vm.restore(snapshot):
		return ScenarioRuntimeOperationResult.failed(&"invalid_death_macro_continuation", "The pending monster death macro cannot be restored.")
	var result := vm.resume(response, _runtime_api())
	if result.state == ScenarioVmResult.State.FAILED:
		return ScenarioRuntimeOperationResult.failed(result.error_code, result.error_message)
	if result.state == ScenarioVmResult.State.SUSPENDED:
		return ScenarioRuntimeOperationResult.failed(&"nested_host_handoff", "A resumed monster death macro cannot suspend a second battle into the application host.")
	if result.state == ScenarioVmResult.State.WAITING:
		var next_continuation := ScenarioRuntimeContinuation.combat_macro(continuation.kind, combat_continuation.source_kind, combat_continuation.battle_id, combat_continuation.caller, combat_continuation.program_id, vm.snapshot(), combat_continuation.combatant_id, combat_continuation.reset_traitor_on_complete)
		return ScenarioRuntimeOperationResult.waiting(result.interaction, next_continuation, result.events)
	return _continue_after_combat_death_macro(combat_continuation.source_kind, combat_continuation.caller, request_id, combat_continuation.combatant_id, combat_continuation.program_id, result.events, combat_continuation.reset_traitor_on_complete)

func execute(action: ClassicActionDefinition, request_id: String, context: ScenarioExecutionContext) -> ScenarioRuntimeOperationResult:
	match action.opcode:
		2, 48, 56, 107:
			return _battle.start_classic_battle(action, request_id)
		10:
			return _rewards.grant_treasure(action.operand_id, request_id)
		11:
			return _rewards.begin_experience_reward(action.operand_id, request_id)
		65:
			return _rewards.grant_random_items(action, request_id)
	return super.execute(action, request_id, context)

func resume_battle(continuation: ScenarioRuntimeContinuation, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	match continuation.kind:
		ScenarioRuntimeContinuation.CLASSIC_COMBAT, ScenarioRuntimeContinuation.SAFE_COMBAT:
			return _resume_battle(continuation, response, request_id)
		ScenarioRuntimeContinuation.CLASSIC_COMBAT_RETREAT, ScenarioRuntimeContinuation.SAFE_COMBAT_RETREAT:
			return _resume_battle_retreat(continuation, response, request_id)
		ScenarioRuntimeContinuation.CLASSIC_COMBAT_AGE, ScenarioRuntimeContinuation.SAFE_COMBAT_AGE:
			return _resume_combat_age_updates(continuation, response, request_id)
		ScenarioRuntimeContinuation.CLASSIC_COMBAT_MACRO, ScenarioRuntimeContinuation.SAFE_COMBAT_MACRO:
			return _resume_battle_macro(continuation, response, request_id)
		ScenarioRuntimeContinuation.CLASSIC_COMBAT_DEATH_MACRO, ScenarioRuntimeContinuation.SAFE_COMBAT_DEATH_MACRO:
			return _resume_combat_death_macro(continuation, response, request_id)
		ScenarioRuntimeContinuation.CLASSIC_COMBAT_ALLY, ScenarioRuntimeContinuation.SAFE_COMBAT_ALLY:
			return _resume_ally_selection(continuation, response)
		ScenarioRuntimeContinuation.CLASSIC_COMBAT_FUMBLE, ScenarioRuntimeContinuation.SAFE_COMBAT_FUMBLE:
			return _resume_fumble_recovery(continuation, response, request_id)
	return ScenarioRuntimeOperationResult.failed(&"unknown_interaction_continuation", "Battle continuation is unavailable.")

func _start_classic_battle(action: ClassicActionDefinition, request_id: String) -> ScenarioRuntimeOperationResult:
	var battle_id := action.operand_id
	var prelude: Array[DomainEvent] = []
	if not action.extra_code.is_empty():
		var low := action.extra_code[0]
		var high := action.extra_code[1] if action.extra_code.size() > 1 else 0
		battle_id = absi(low)
		if high != 0:
			battle_id = _rng.draw_between(absi(low), absi(high), StringName("classic.opcode-%d.battle" % action.opcode))
		var sound_id := action.extra_code[3] if action.opcode == 56 else action.extra_code[2]
		var message_id := action.extra_code[4] if action.opcode == 56 else action.extra_code[3]
		if sound_id != 0:
			prelude.append(DomainEvent.new(&"sound_requested", {"soundId": sound_id, "source": "classic-battle"}))
		if message_id != 0:
			var message := _content.message_by_id(absi(message_id))
			if message == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_message", "Classic opcode %d references unavailable battle message %d." % [action.opcode, message_id])
			prelude.append(DomainEvent.new(&"message_shown", {"messageId": message.id, "text": message.text, "source": "classic-battle"}))
	var caller_mode := action.extra_code[4] if action.opcode in [2, 48] and action.extra_code.size() > 4 else 0
	var caller := ScenarioBattleCaller.classic(action.opcode, action.gosub, caller_mode, action.extra_code[4] if action.opcode == 107 and action.extra_code.size() > 4 else action.extra_code[2] if action.opcode == 56 and action.extra_code.size() > 2 else 0)
	var battle := _content.battle_by_classic_id(absi(battle_id))
	if battle == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_battle", "Classic opcode %d references unavailable battle %d." % [action.opcode, battle_id])
	var operation := start_battle_definition(battle, request_id, "classic", caller)
	if operation.state != ScenarioRuntimeOperationResult.State.FAILED:
		operation.events = prelude + operation.events
	return operation

static func party_defeat_handoff_is_valid(content: RealmzContent, state: GameState, handoff: ScenarioRuntimeHandoff) -> bool:
	if content == null or state == null or state.combat == null or handoff == null or handoff.caller == null:
		return false
	if handoff.kind != ScenarioRuntimeHandoff.PARTY_DEFEAT or handoff.battle_id != state.combat.battle_id or handoff.source_kind not in [ScenarioRuntimeHandoff.CLASSIC_COMBAT, ScenarioRuntimeHandoff.SAFE_COMBAT]:
		return false
	if not state.combat.completed or state.combat.outcome != &"defeat":
		return false
	var caller := handoff.caller
	if handoff.source_kind == ScenarioRuntimeHandoff.SAFE_COMBAT:
		return caller.kind == ScenarioBattleCaller.SAFE
	if caller.kind != ScenarioBattleCaller.CLASSIC:
		return false
	var opcode := caller.opcode
	var target := caller.branch_target
	if opcode == 107 or opcode == 56 and target >= 0:
		return content.scenario.program_by_id("xap:%d" % target) != null
	return true

func complete_party_defeat_handoff(handoff: ScenarioRuntimeHandoff) -> ScenarioRuntimeOperationResult:
	if not party_defeat_handoff_is_valid(_content, _game_state, handoff):
		return ScenarioRuntimeOperationResult.failed(&"invalid_party_defeat_handoff", "The suspended total-party defeat no longer matches its battle caller.")
	var caller := handoff.caller
	if caller.kind == ScenarioBattleCaller.CLASSIC and caller.opcode == 2 and caller.mode == 10:
		return ScenarioRuntimeOperationResult.failed(&"classic_mode_10_defeat_unresolved", "Classic battle mode 10 revives and restarts its caller without running Party Death; that source-specific restart is not yet available.")
	if caller.kind == ScenarioBattleCaller.CLASSIC and caller.opcode == 56 and caller.branch_target == -1:
		return ScenarioRuntimeOperationResult.failed(&"classic_battle_loss_return_unresolved", "Classic opcode 56 uses a distinct experience-loss and party-backup return that is not yet available.")
	var combat := _game_state.combat
	var battle_id := combat.battle_id
	var directive: ScenarioVmDirective
	if caller.kind == ScenarioBattleCaller.CLASSIC:
		match caller.opcode:
			56:
				directive = ScenarioVmDirective.branch_xap(caller.branch_target, caller.gosub)
			107:
				directive = ScenarioVmDirective.branch_xap(caller.branch_target, false)
	combat.outcome = &"retreated"
	_game_state.last_battle_outcome = &"retreated"
	var events: Array[DomainEvent] = [
		DomainEvent.new(&"party_defeat_revived", {"battleId": battle_id, "source": "classic-party-death-hook", "callerOpcode": caller.opcode if caller.kind == ScenarioBattleCaller.CLASSIC else 0}),
		DomainEvent.new(&"battle_returned", {"battleId": battle_id, "outcome": "retreated"}),
	]
	_game_state.combat = null
	return ScenarioRuntimeOperationResult.completed(battle_id, events, directive)

func start_battle_definition(battle: BattleDefinition, request_id: String, source: String, caller: ScenarioBattleCaller) -> ScenarioRuntimeOperationResult:
	var result := _rules.combat_flow.start_battle(_game_state, _content, battle, _rng)
	if not result.ok:
		return ScenarioRuntimeOperationResult.failed(result.error_code, result.error_message)
	var events: Array[DomainEvent] = []
	if battle.message_before_id != 0:
		var before := _content.message_by_id(absi(battle.message_before_id))
		if before == null:
			return ScenarioRuntimeOperationResult.failed(&"unknown_message", "Battle '%s' references unavailable before-message %d." % [battle.id, battle.message_before_id])
		events.append(DomainEvent.new(&"message_shown", {"messageId": before.id, "text": before.text, "source": "classic-battle-definition"}))
	events.append_array(result.events)
	var continuation_kind := ScenarioRuntimeContinuation.SAFE_COMBAT if source == "scenario-action" else ScenarioRuntimeContinuation.CLASSIC_COMBAT
	if not CharacterAgingResult.update_payloads(result.events).is_empty():
		return _wait_for_combat_age_updates(continuation_kind, caller, request_id, events, _game_state.combat.round_number)
	if not _death_macro_request(result.events).is_empty():
		return _run_combat_death_macro(continuation_kind, caller, events, request_id)
	if result.completed:
		return _finish_battle_with_allies(continuation_kind, caller, request_id, events)
	return ScenarioRuntimeOperationResult.waiting(_combat_request(request_id), ScenarioRuntimeContinuation.combat(continuation_kind, battle.id, caller), events)

func _resume_battle(continuation: ScenarioRuntimeContinuation, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	var body := response.body as InteractionResponse.CombatBody
	if response.kind != &"combat_action" or body == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Combat response requires actorId, action, and optional targetId strings.")
	var combat_continuation := continuation.body as ScenarioRuntimeContinuation.CombatBody
	if _game_state.combat == null or _game_state.combat.battle_id != combat_continuation.battle_id:
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_continuation", "The pending battle is unavailable.")
	var previous_round := _game_state.combat.round_number
	var caller := combat_continuation.caller
	if caller == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_continuation", "The pending battle lost its originating caller.")
	var result: CombatFlowResult
	if body.action == &"set_auto":
		if _game_state.party.character_by_id(body.actor_id) == null:
			return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Persistent Auto requires a party character and an enabled boolean.")
		var auto_state_checkpoint := _game_state.to_data()
		var auto_rng_checkpoint := _rng.checkpoint()
		if not _game_state.set_combat_auto(body.actor_id, body.enabled):
			return ScenarioRuntimeOperationResult.failed(&"invalid_combat_auto_character", "Persistent Auto could not be changed for this character.")
		var toggle_sound := 147 if body.enabled else 139
		var auto_events: Array[DomainEvent] = [
			DomainEvent.new(&"sound_requested", {"soundId": toggle_sound, "waitForCompletion": false, "source": "classic-combat-auto-toggle"}),
			DomainEvent.new(&"combat_auto_changed", {"characterId": body.actor_id, "enabled": body.enabled, "source": "classic"}),
		]
		if not body.enabled or _game_state.combat.active_actor_id() != body.actor_id:
			return ScenarioRuntimeOperationResult.waiting(_combat_request(request_id), continuation, auto_events)
		auto_events.append(DomainEvent.new(&"sound_requested", {"soundId": 141, "waitForCompletion": false, "source": "classic-combat-auto-button"}))
		result = _rules.combat_flow.run_persistent_auto_characters(_game_state, _content, _rng)
		if not result.ok:
			if not _game_state.restore_from_data(auto_state_checkpoint) or not _rng.rollback(auto_rng_checkpoint):
				return ScenarioRuntimeOperationResult.failed(&"combat_auto_rollback_failed", "Persistent Auto failed and could not restore its toggle transaction.")
			return ScenarioRuntimeOperationResult.failed(result.error_code, result.error_message)
		if result.ok:
			var combined_events: Array[DomainEvent] = []
			combined_events.append_array(auto_events)
			combined_events.append_array(result.events)
			result.events = combined_events
	elif body.action == &"retreat":
		var retreat_probe: Variant = _rules.combat_flow.probe_character_retreat(_game_state.combat, _game_state.party.characters(), body.actor_id)
		if not retreat_probe.allowed:
			return ScenarioRuntimeOperationResult.failed(retreat_probe.reason, retreat_probe.reason_text)
		return _wait_for_battle_retreat(continuation, body.actor_id, &"explicit", Vector2i(-100_000, -100_000), request_id)
	elif body.action == &"retreat_edge":
		var edge_destination := body.destination if body.has_destination else CombatFlow.INVALID_COORDINATE
		var edge_probe: Variant = _rules.combat_flow.probe_edge_retreat(_game_state.combat, body.actor_id, edge_destination)
		if not edge_probe.allowed:
			return ScenarioRuntimeOperationResult.failed(edge_probe.reason, edge_probe.reason_text)
		if not edge_probe.forced:
			return _wait_for_battle_retreat(continuation, body.actor_id, &"edge", edge_destination, request_id)
		result = _rules.combat_flow.retreat_character(_game_state, _content, body.actor_id, &"edge", edge_destination, _rng)
	elif body.action == &"move":
		if not body.has_destination:
			return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Combat movement requires a two-integer destination.")
		result = _rules.combat_flow.move_character(_game_state, _content, body.actor_id, body.destination, _rng, body.auto_switch_to_melee)
	elif body.action == &"cast_spell":
		if body.spell_id.is_empty():
			return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Combat spell casting requires a spellId string and integer power.")
		var target_coordinate := body.target_coordinate if body.has_target_coordinate else CombatFlow.INVALID_COORDINATE
		result = _rules.combat_flow.cast_spell(_game_state, _content, body.actor_id, body.target_id, body.spell_id, body.power, _rng, target_coordinate, body.rotation, body.target_ids)
	elif body.action == &"use_item":
		if body.item_instance_id.is_empty():
			return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Combat item use requires an itemInstanceId string.")
		result = _rules.combat_flow.use_spell_item(_game_state, _content, body.actor_id, body.target_id, body.item_instance_id, _rng)
	elif body.action == &"use_scroll":
		if body.scroll_slot < 0:
			return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Combat scroll use requires an integer scrollSlot.")
		var scroll_target_coordinate := body.target_coordinate if body.has_target_coordinate else CombatFlow.INVALID_COORDINATE
		result = _rules.combat_flow.use_combat_scroll(_game_state, _content, body.actor_id, body.scroll_slot, body.target_id, _rng, scroll_target_coordinate, body.rotation, body.target_ids)
	else:
		result = _rules.combat_flow.submit_action(_game_state, _content, body.actor_id, body.action, body.target_id, _rng)
	if not result.ok:
		if body.action == &"move" and result.error_code == &"melee_weapon_mode_required":
			var warning_events: Array[DomainEvent] = [
				DomainEvent.new(&"sound_requested", {"soundId": 6000, "waitForCompletion": false, "source": "classic-auto-weapon-switch-warning"}),
				DomainEvent.new(&"combat_action_unavailable", {"actorId": body.actor_id, "action": "move", "reason": String(result.error_code), "message": result.error_message, "source": "classic"}),
			]
			return ScenarioRuntimeOperationResult.waiting(_combat_request(request_id), continuation, warning_events)
		return ScenarioRuntimeOperationResult.failed(result.error_code, result.error_message)
	if not CharacterAgingResult.update_payloads(result.events).is_empty():
		return _wait_for_combat_age_updates(continuation.kind, caller, request_id, result.events, previous_round)
	if not _death_macro_request(result.events).is_empty():
		return _run_combat_death_macro(continuation.kind, caller, result.events, request_id)
	if result.completed:
		var completed_events: Array[DomainEvent] = []
		completed_events.assign(result.events)
		return _finish_battle_with_allies(continuation.kind, caller, request_id, completed_events)
	if _game_state.combat.round_number > previous_round and _game_state.combat.macro_id < 0:
		return _run_battle_macro(continuation.kind, caller, result.events, request_id)
	return ScenarioRuntimeOperationResult.waiting(_combat_request(request_id), continuation, result.events)

func _wait_for_battle_retreat(continuation: ScenarioRuntimeContinuation, actor_id: String, mode: StringName, destination: Vector2i, request_id: String) -> ScenarioRuntimeOperationResult:
	var source_kind := continuation.kind
	var combat_continuation := continuation.body as ScenarioRuntimeContinuation.CombatBody
	var retreat_kind := ScenarioRuntimeContinuation.SAFE_COMBAT_RETREAT if source_kind == ScenarioRuntimeContinuation.SAFE_COMBAT else ScenarioRuntimeContinuation.CLASSIC_COMBAT_RETREAT
	var next_continuation := ScenarioRuntimeContinuation.combat_retreat(retreat_kind, source_kind, _game_state.combat.battle_id, combat_continuation.caller, actor_id, mode, destination)
	var request := InteractionRequest.yes_no(request_id, "Will this character flee from battle?", "Embrace Cowardice", "Stay and Fight")
	return ScenarioRuntimeOperationResult.waiting(request, next_continuation)

func _resume_battle_retreat(continuation: ScenarioRuntimeContinuation, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	var body := response.body as InteractionResponse.YesNoBody
	if response.kind != InteractionRequest.YES_NO or body == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Escape confirmation requires a yes/no response.")
	var combat_continuation := continuation.body as ScenarioRuntimeContinuation.CombatBody
	if _game_state.combat == null or _game_state.combat.completed or _game_state.combat.battle_id != combat_continuation.battle_id or _game_state.combat.active_actor_id() != combat_continuation.actor_id:
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_continuation", "The character awaiting Escape confirmation is unavailable.")
	var source_kind := combat_continuation.source_kind
	var caller := combat_continuation.caller
	if caller == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_continuation", "The pending retreat lost its originating battle caller.")
	var mode := combat_continuation.mode
	var destination := combat_continuation.destination
	var probe: Variant = _rules.combat_flow.probe_character_retreat(_game_state.combat, _game_state.party.characters(), combat_continuation.actor_id) if mode == &"explicit" else _rules.combat_flow.probe_edge_retreat(_game_state.combat, combat_continuation.actor_id, destination) if mode == &"edge" else null
	if probe == null or not probe.allowed or probe.forced:
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_continuation", "The saved Escape confirmation no longer represents a promptable Classic action.")
	if not body.accepted:
		return ScenarioRuntimeOperationResult.waiting(_combat_request(request_id), ScenarioRuntimeContinuation.combat(source_kind, combat_continuation.battle_id, caller), [DomainEvent.new(&"combat_retreat_declined", {"actorId": combat_continuation.actor_id, "mode": String(mode), "source": "classic"})])
	var previous_round := _game_state.combat.round_number
	var result := _rules.combat_flow.retreat_character(_game_state, _content, combat_continuation.actor_id, mode, destination, _rng)
	if not result.ok:
		return ScenarioRuntimeOperationResult.failed(result.error_code, result.error_message)
	if not CharacterAgingResult.update_payloads(result.events).is_empty():
		return _wait_for_combat_age_updates(source_kind, caller, request_id, result.events, previous_round)
	if not _death_macro_request(result.events).is_empty():
		return _run_combat_death_macro(source_kind, caller, result.events, request_id)
	if result.completed:
		var completed_events: Array[DomainEvent] = []
		completed_events.assign(result.events)
		return _finish_battle_with_allies(source_kind, caller, request_id, completed_events)
	if _game_state.combat.round_number > previous_round and _game_state.combat.macro_id < 0:
		return _run_battle_macro(source_kind, caller, result.events, request_id)
	return ScenarioRuntimeOperationResult.waiting(_combat_request(request_id), ScenarioRuntimeContinuation.combat(source_kind, combat_continuation.battle_id, caller), result.events)

func _finish_battle_with_fumbles(source_kind: StringName, caller: ScenarioBattleCaller, request_id: String, events: Array[DomainEvent]) -> ScenarioRuntimeOperationResult:
	var combat := _game_state.combat
	if combat == null or not combat.completed:
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_continuation", "Post-battle fumbled-weapon recovery requires a completed battle.")
	var reward: ScenarioRuntimeOperationResult = _rewards.begin_completed_battle_reward(request_id, caller)
	reward.events = events + reward.events
	return reward

func _resume_ally_selection(continuation: ScenarioRuntimeContinuation, response: InteractionResponse) -> ScenarioRuntimeOperationResult:
	var body := response.body as InteractionResponse.AllySelectionBody
	if response.kind != &"ally_selection" or body == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Ally selection requires selectedIds.")
	var combat_continuation := continuation.body as ScenarioRuntimeContinuation.CombatBody
	if _game_state.combat == null or not _game_state.combat.completed or _game_state.combat.battle_id != combat_continuation.battle_id:
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_continuation", "The completed battle is unavailable for ally selection.")
	if _rules.combat_flow.ally_selection_payload(_game_state, _content).is_empty():
		return _finish_battle_with_fumbles(combat_continuation.source_kind, combat_continuation.caller, String(response.request_id), [])
	var selected := _rules.combat_flow.apply_ally_selection(_game_state, _content, body.selected_ids)
	if not selected.ok:
		return ScenarioRuntimeOperationResult.failed(selected.error_code, selected.error_message)
	var events: Array[DomainEvent] = []
	events.assign(selected.events)
	return _finish_battle_with_fumbles(combat_continuation.source_kind, combat_continuation.caller, String(response.request_id), events)

func _resume_fumble_recovery(continuation: ScenarioRuntimeContinuation, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	var body := response.body as InteractionResponse.TreasureBody
	if response.kind != InteractionRequest.TREASURE_DISTRIBUTION or body == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Fumbled-weapon recovery requires a treasure-distribution response.")
	var combat_continuation := continuation.body as ScenarioRuntimeContinuation.CombatBody
	if _game_state.combat == null or not _game_state.combat.completed or _game_state.combat.battle_id != combat_continuation.battle_id:
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_continuation", "The completed battle is unavailable for fumbled-weapon recovery.")
	var recovered := _rules.combat_flow.apply_fumble_recovery(_game_state, _content, body.action, body.instance_id, body.character_id)
	if not recovered.ok:
		return ScenarioRuntimeOperationResult.failed(recovered.error_code, recovered.error_message)
	var events: Array[DomainEvent] = []
	events.assign(recovered.events)
	return _finish_battle_with_fumbles(combat_continuation.source_kind, combat_continuation.caller, request_id, events)

func _run_battle_macro(source_kind: StringName, caller: ScenarioBattleCaller, preceding_events: Array[DomainEvent], request_id: String) -> ScenarioRuntimeOperationResult:
	var combat := _game_state.combat
	if combat == null or combat.completed or combat.macro_id >= 0:
		return ScenarioRuntimeOperationResult.waiting(_combat_request(request_id), ScenarioRuntimeContinuation.combat(source_kind, combat.battle_id, caller), preceding_events)
	var program_id := "xap:%d" % absi(combat.macro_id)
	var vm := ScenarioVm.new()
	vm.configure(_content.scenario)
	var macro_context := ScenarioExecutionContext.calling(&"battle-macro").set_battle(combat.battle_id)
	var started := vm.start_program(program_id, macro_context)
	if started.state == ScenarioVmResult.State.FAILED:
		return ScenarioRuntimeOperationResult.failed(started.error_code, started.error_message)
	var result := vm.run(_runtime_api())
	var events: Array[DomainEvent] = []
	events.assign(preceding_events)
	events.append(DomainEvent.new(&"battle_macro_started", {"battleId": combat.battle_id, "programId": program_id, "round": combat.round_number}))
	events.append_array(result.events)
	if result.state == ScenarioVmResult.State.FAILED:
		return ScenarioRuntimeOperationResult.failed(result.error_code, result.error_message)
	if result.state == ScenarioVmResult.State.SUSPENDED:
		return ScenarioRuntimeOperationResult.failed(&"nested_host_handoff", "A battle macro cannot suspend a second battle into the application host.")
	if result.state == ScenarioVmResult.State.WAITING:
		var macro_kind := ScenarioRuntimeContinuation.SAFE_COMBAT_MACRO if source_kind == ScenarioRuntimeContinuation.SAFE_COMBAT else ScenarioRuntimeContinuation.CLASSIC_COMBAT_MACRO
		return ScenarioRuntimeOperationResult.waiting(result.interaction, ScenarioRuntimeContinuation.combat_macro(macro_kind, source_kind, combat.battle_id, caller, program_id, vm.snapshot()), events)
	return _continue_after_battle_macro(source_kind, caller, request_id, program_id, events)

func _resume_battle_macro(continuation: ScenarioRuntimeContinuation, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	var combat_continuation := continuation.body as ScenarioRuntimeContinuation.CombatBody
	if _game_state.combat == null or _game_state.combat.battle_id != combat_continuation.battle_id:
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_continuation", "The pending battle macro is unavailable.")
	var snapshot := combat_continuation.macro_vm
	if snapshot == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_macro_continuation", "The pending battle macro state is invalid.")
	var vm := ScenarioVm.new()
	vm.configure(_content.scenario)
	if not vm.restore(snapshot):
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_macro_continuation", "The pending battle macro cannot be restored.")
	var result := vm.resume(response, _runtime_api())
	if result.state == ScenarioVmResult.State.FAILED:
		return ScenarioRuntimeOperationResult.failed(result.error_code, result.error_message)
	if result.state == ScenarioVmResult.State.SUSPENDED:
		return ScenarioRuntimeOperationResult.failed(&"nested_host_handoff", "A resumed battle macro cannot suspend a second battle into the application host.")
	if result.state == ScenarioVmResult.State.WAITING:
		var next_continuation := ScenarioRuntimeContinuation.combat_macro(continuation.kind, combat_continuation.source_kind, combat_continuation.battle_id, combat_continuation.caller, combat_continuation.program_id, vm.snapshot())
		return ScenarioRuntimeOperationResult.waiting(result.interaction, next_continuation, result.events)
	return _continue_after_battle_macro(combat_continuation.source_kind, combat_continuation.caller, request_id, combat_continuation.program_id, result.events)

func _continue_after_battle_macro(source_kind: StringName, caller: ScenarioBattleCaller, request_id: String, program_id: String, events: Array[DomainEvent]) -> ScenarioRuntimeOperationResult:
	var committed: Array[DomainEvent] = []
	committed.assign(events)
	committed.append(DomainEvent.new(&"battle_macro_completed", {"battleId": _game_state.combat.battle_id, "programId": program_id, "round": _game_state.combat.round_number}))
	if _game_state.combat.completed:
		return _finish_battle_with_allies(source_kind, caller, request_id, committed)
	return ScenarioRuntimeOperationResult.waiting(_combat_request(request_id), ScenarioRuntimeContinuation.combat(source_kind, _game_state.combat.battle_id, caller), committed)

func _run_combat_death_macro(source_kind: StringName, caller: ScenarioBattleCaller, preceding_events: Array[DomainEvent], request_id: String) -> ScenarioRuntimeOperationResult:
	var request := _death_macro_request(preceding_events)
	var combat := _game_state.combat
	if request.is_empty() or combat == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_death_macro_request", "Monster death-macro execution requires an active combatant request.")
	var combatant_id := str(request.get("combatantId", ""))
	var program_id := str(request.get("programId", ""))
	var monster := combat.monster_by_id(combatant_id)
	if monster == null or program_id.is_empty():
		return ScenarioRuntimeOperationResult.failed(&"invalid_death_macro_request", "Monster death-macro execution references unavailable content.")
	var vm := ScenarioVm.new()
	vm.configure(_content.scenario)
	var death_context := ScenarioExecutionContext.calling(&"monster-death-macro")
	death_context.set_battle(combat.battle_id)
	death_context.set_combatant(combatant_id, int(request.get("classicMonsterId", 0)), bool(request.get("traitor", monster.traitor)), true)
	var started := vm.start_program(program_id, death_context)
	if started.state == ScenarioVmResult.State.FAILED:
		return ScenarioRuntimeOperationResult.failed(started.error_code, started.error_message)
	var result := vm.run(_runtime_api())
	var events: Array[DomainEvent] = []
	events.assign(preceding_events)
	events.append(DomainEvent.new(&"monster_death_macro_started", {"battleId": combat.battle_id, "combatantId": combatant_id, "programId": program_id}))
	events.append_array(result.events)
	if result.state == ScenarioVmResult.State.FAILED:
		return ScenarioRuntimeOperationResult.failed(result.error_code, result.error_message)
	if result.state == ScenarioVmResult.State.SUSPENDED:
		return ScenarioRuntimeOperationResult.failed(&"nested_host_handoff", "A monster death macro cannot suspend a second battle into the application host.")
	if result.state == ScenarioVmResult.State.WAITING:
		var macro_kind := ScenarioRuntimeContinuation.SAFE_COMBAT_DEATH_MACRO if source_kind == ScenarioRuntimeContinuation.SAFE_COMBAT else ScenarioRuntimeContinuation.CLASSIC_COMBAT_DEATH_MACRO
		return ScenarioRuntimeOperationResult.waiting(result.interaction, ScenarioRuntimeContinuation.combat_macro(macro_kind, source_kind, combat.battle_id, caller, program_id, vm.snapshot(), combatant_id, bool(request.get("resetTraitorOnComplete", true))), events)
	return _continue_after_combat_death_macro(source_kind, caller, request_id, combatant_id, program_id, events, bool(request.get("resetTraitorOnComplete", true)))

func _finish_battle_with_allies(source_kind: StringName, caller: ScenarioBattleCaller, request_id: String, events: Array[DomainEvent]) -> ScenarioRuntimeOperationResult:
	var combat := _game_state.combat
	if combat == null or not combat.completed:
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_continuation", "Post-battle ally selection requires a completed battle.")
	if combat.outcome == &"defeat":
		if caller.kind == ScenarioBattleCaller.CLASSIC and caller.opcode == 2 and caller.mode == 10:
			return ScenarioRuntimeOperationResult.failed(&"classic_mode_10_defeat_unresolved", "Classic battle mode 10 bypasses Party Death and restarts its encounter; that caller-specific path is unresolved.")
		return ScenarioRuntimeOperationResult.suspended(ScenarioRuntimeHandoff.party_defeat(combat.battle_id, source_kind, caller), events)
	var payload := _rules.combat_flow.ally_selection_payload(_game_state, _content)
	if not payload.is_empty():
		var ally_kind := ScenarioRuntimeContinuation.SAFE_COMBAT_ALLY if source_kind == ScenarioRuntimeContinuation.SAFE_COMBAT else ScenarioRuntimeContinuation.CLASSIC_COMBAT_ALLY
		return ScenarioRuntimeOperationResult.waiting(InteractionRequest.from_payload(request_id, &"ally_selection", payload), ScenarioRuntimeContinuation.combat_terminal(ally_kind, source_kind, combat.battle_id, caller), events)
	return _finish_battle_with_fumbles(source_kind, caller, request_id, events)

func _set_map_darkness(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 2:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 106 requires a five-value Extra Code row.")
	if action.extra_code[0] not in [1, 2]:
		return ScenarioRuntimeOperationResult.failed(&"invalid_darkness", "Classic opcode 106 darkness value must be 1 or 2.")
	var map := _content.world.map_by_id(_game_state.party.map_id)
	if map == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_map", "Classic opcode 106 requires the party's current map.")
	var dark := action.extra_code[0] == 2
	var unchanged := _game_state.world.map_is_dark(map) == dark
	if unchanged and action.extra_code[1] != 0:
		return ScenarioRuntimeOperationResult.completed(false, [DomainEvent.new(&"map_darkness_unchanged", {"mapId": map.id, "dark": dark})], ScenarioVmDirective.finish())
	_game_state.world.set_map_darkness(map.id, dark)
	return ScenarioRuntimeOperationResult.completed(dark, [DomainEvent.new(&"map_darkness_changed", {"mapId": map.id, "dark": dark, "source": "classic"})])

func resume_resolution(continuation: ScenarioRuntimeContinuation, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	var owner := continuation.body as ScenarioRuntimeContinuation.ThiefBody
	var acknowledgement := response.body as InteractionResponse.AcknowledgeBody
	var encounter := _content.complex_encounter_by_id(owner.encounter_id) if owner != null else null
	var thief := _thief_definition(encounter)
	var character := _state.party.character_by_id(owner.character_id) if owner != null else null
	if response.kind != InteractionRequest.ACKNOWLEDGE or acknowledgement == null or acknowledgement.take_note or owner == null or encounter == null or thief == null or character == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Thief Encounter result acknowledgement does not match its source action.")
	if owner.phase == &"trap-message":
		return _apply_trap(encounter, thief, owner.gosub, character, request_id, owner.encounter_attempt)
	if owner.phase != &"action-message":
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Thief Encounter result has an unknown stage.")
	if owner.trap_pending:
		return _wait_for_trap_message(encounter, owner.gosub, character, owner.action_index, owner.succeeded, request_id, [], owner.encounter_attempt)
	return _finish_action(encounter, thief, owner.gosub, character, owner.action_index, owner.succeeded, request_id, [], owner.encounter_attempt)

func _attempt(encounter: ComplexEncounterDefinition, gosub: bool, selection: InteractionResponse.ThiefEncounterBody, request_id: String, encounter_attempt: int) -> ScenarioRuntimeOperationResult:
	var thief := _thief_definition(encounter)
	var character := _state.party.character_by_id(selection.character_id)
	var action_index := selection.action_index
	var flags := _state.thief_encounter_type_flags(thief) if thief != null else []
	if thief == null or character == null or not _character_eligible(character) or not _action_available(character, thief, flags, action_index):
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Thief Encounter action or character is unavailable.")
	flags[action_index] = false
	var trap_armed := flags[9]
	if trap_armed and action_index in [4, 6, 7]:
		if action_index == 4:
			flags[4] = true
		_state.set_thief_encounter_type_flags(thief, flags)
		return _wait_for_trap_message(encounter, gosub, character, action_index, false, request_id, [], encounter_attempt)
	_state.set_thief_encounter_type_flags(thief, flags)
	if action_index in LOCK_ACTIONS:
		return _start_pick_lock(encounter, thief, gosub, character, action_index, request_id, encounter_attempt)
	var chance := character.ability_value(ClassicPickLockRulesScript.ability_index(action_index)) + thief.modifiers()[action_index]
	var succeeded := _rng.draw(100, &"classic.thief-encounter") <= chance
	if succeeded and action_index == 1 and trap_armed:
		flags[2] = true
	_state.set_thief_encounter_type_flags(thief, flags)
	var event := _action_event(encounter, thief, character, action_index, chance, succeeded)
	return _present_action_result(encounter, thief, gosub, character, action_index, succeeded, not succeeded and trap_armed and action_index != 1, request_id, [event], encounter_attempt)

func _resume_reward_level(reward: ClassicRewardState, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	var body := response.body as InteractionResponse.LevelUpBody
	if response.kind != InteractionRequest.LEVEL_UP or body == null or body.action != &"continue" or body.character_id != reward.pending_level_result.get("characterId"):
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "The level result must be acknowledged by its character ID.")
	var character_id := String(reward.pending_level_result.get("characterId", ""))
	reward.pending_level_result.clear()
	reward.level_index += 1
	return _advance_reward_levels(reward, request_id, [DomainEvent.new(&"level_result_acknowledged", {"characterId": character_id})])

func _level_result_request(reward: ClassicRewardState, request_id: String) -> InteractionRequest:
	if reward.pending_level_result.is_empty():
		return null
	var result := reward.pending_level_result
	return InteractionRequest.from_payload(request_id, InteractionRequest.LEVEL_UP, {"mode": "result", "prompt": "Review the level gained.", "characterId": result["characterId"], "characterName": result["characterName"], "level": result["level"], "gains": {"stamina": result["stamina"], "spellPoints": result["spellPoints"], "toHit": result["toHit"], "magicResistance": result["magicResistance"]}})

func _advance_reward_levels(reward: ClassicRewardState, request_id: String, events: Array[DomainEvent] = []) -> ScenarioRuntimeOperationResult:
	var ids := reward.level_character_ids()
	while reward.level_index < ids.size():
		var character := _game_state.party.character_by_id(ids[reward.level_index])
		var race: RaceDefinition = null if character == null else _content.race_by_id(character.race_id)
		var caste: CasteDefinition = null if character == null else _content.caste_by_id(character.caste_id)
		if character == null or race == null or caste == null or character.current_health <= 0 or character.experience <= 0:
			return ScenarioRuntimeOperationResult.failed(&"invalid_reward_progression", "A character in the level-up queue is no longer eligible.")
		var threshold_index := clampi(character.level, 1, 30) - 1
		character.experience -= caste.victory_threshold(threshold_index)
		var level_result := _rules.characters.level_up(character, race, caste, _rng)
		if level_result == null:
			return ScenarioRuntimeOperationResult.failed(&"character_level_failed", "Character '%s' could not level." % character.id)
		reward.pending_level_result = {"characterId": character.id, "characterName": character.name, "level": character.level, "stamina": level_result.stamina_gained, "spellPoints": level_result.spell_points_gained, "toHit": level_result.to_hit_gained, "magicResistance": level_result.magic_resistance_gained}
		if character.spellcaster_type > 0 and character.maximum_spell_points > 0:
			var spell_ids := reward.spell_character_ids()
			spell_ids.append(character.id)
			reward.set_spell_character_ids(spell_ids)
		events.append(DomainEvent.new(&"character_leveled", reward.pending_level_result))
		return _wait_for_reward(reward, request_id, events)
	reward.phase = ClassicRewardState.SPELL_PHASE
	return _advance_reward_spells(reward, request_id, events)

func _branch_on_misc(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 86 requires a five-value Extra Code row.")
	var test_kind := action.extra_code[0]
	var expected := action.extra_code[1]
	var selected_only := expected < 0 and test_kind in [0, 1, 2, 5, 6]
	var characters := _game_state.selected_characters() if selected_only else _game_state.party.characters()
	var matched := false
	match test_kind:
		0:
			for character: CharacterState in characters:
				var caste := _content.caste_by_id(character.caste_id)
				if caste != null and caste.classic_id == absi(expected):
					matched = true
					break
		1:
			for character: CharacterState in characters:
				var race := _content.race_by_id(character.race_id)
				if race != null and race.classic_id == absi(expected):
					matched = true
					break
		2:
			for character: CharacterState in characters:
				if character.gender == absi(expected):
					matched = true
					break
		3:
			matched = _game_state.party_in_boat
		4:
			matched = _game_state.party_camping
		5:
			for character: CharacterState in characters:
				var caste := _content.caste_by_id(character.caste_id)
				if caste != null and caste.caste_class == absi(expected):
					matched = true
					break
		6:
			if absi(expected) < 1 or absi(expected) > 32:
				return ScenarioRuntimeOperationResult.failed(&"invalid_race_descriptor", "Classic opcode 86 race descriptor is outside 1 through 32.")
			var descriptor_mask := 1 << (absi(expected) - 1)
			for character: CharacterState in characters:
				var race := _content.race_by_id(character.race_id)
				if race != null and (race.descriptor_flags & descriptor_mask) != 0:
					matched = true
					break
		7:
			var total_level := 0
			for character: CharacterState in _game_state.party.characters():
				total_level += character.level
			matched = total_level > expected
		8:
			var selected_level := 0
			for character: CharacterState in _game_state.selected_characters():
				selected_level += character.level
			matched = selected_level > expected
		_:
			return ScenarioRuntimeOperationResult.failed(&"invalid_misc_branch", "Classic opcode 86 test kind is unavailable.")
	var target_id := action.extra_code[3] if matched else action.extra_code[4]
	var event := DomainEvent.new(&"misc_branch_checked", {"testKind": test_kind, "expected": expected, "matched": matched, "targetId": target_id})
	if target_id == 0:
		return ScenarioRuntimeOperationResult.completed(matched, [event])
	var branch := _branch_target_mode(action.extra_code[2], target_id, action.gosub)
	branch.events.append(event)
	return branch

func resume_pick_lock(continuation: ScenarioRuntimeContinuation, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	var owner := continuation.body as ScenarioRuntimeContinuation.ThiefBody
	var selection := response.body as InteractionResponse.PickLockBody
	var encounter := _content.complex_encounter_by_id(owner.encounter_id) if owner != null else null
	var thief := _thief_definition(encounter)
	var character := _state.party.character_by_id(owner.character_id) if owner != null else null
	if response.kind != InteractionRequest.PICK_LOCK or selection == null or encounter == null or thief == null or character == null or character.current_health <= 0:
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Pick Lock response does not match its source character and encounter.")
	var chance := ClassicPickLockRulesScript.chance(character.ability_value(ClassicPickLockRulesScript.ability_index(owner.action_index)), thief.modifiers()[owner.action_index])
	var resolved := ClassicPickLockRulesScript.resolve(_rng, thief.tumblers, chance, selection.frame_index)
	if resolved.is_empty():
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Pick Lock response selected a frame outside the source timer.")
	var flags := _state.thief_encounter_type_flags(thief)
	var succeeded: bool = resolved["succeeded"]
	var event := _action_event(encounter, thief, character, owner.action_index, chance, succeeded)
	event.payload.merge({"frameIndex": selection.frame_index, "positions": resolved["positions"]}, true)
	if succeeded and owner.action_index == 2:
		flags[9] = false
	_state.set_thief_encounter_type_flags(thief, flags)
	return _present_action_result(encounter, thief, owner.gosub, character, owner.action_index, succeeded, not succeeded and flags[9], request_id, [event], owner.encounter_attempt)

func _branch_from_values(values: Array[int], gosub: bool) -> ScenarioRuntimeOperationResult:
	match values[2]:
		0:
			return _branch_xap(values[3], gosub)
		3:
			return ScenarioRuntimeOperationResult.completed(true, [], ScenarioVmDirective.finish())
	return ScenarioRuntimeOperationResult.failed(&"unsupported_branch_mode", "Classic branch mode %d is not available in this execution context." % values[2])

func replace_scenario_program(action: ClassicActionDefinition, context: ScenarioExecutionContext) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 7 requires a five-value Extra Code row.")
	var values := action.extra_code
	var source_program_id := "xap:%d" % int(values[2])
	var target_program_id := ""
	match int(values[0]):
		-1:
			target_program_id = "simple:%d:result:%d" % [int(values[1]), int(values[4])]
		-2:
			target_program_id = "complex:%d:result:%d" % [int(values[1]), int(values[4])]
		_:
			var current_trigger := _content.trigger_by_id(context.trigger_id)
			var current_map: MapDefinition = null
			if current_trigger != null and not current_trigger.map_id.is_empty():
				current_map = _content.world.map_by_id(current_trigger.map_id)
			if current_map == null:
				current_map = _content.world.map_by_id(_game_state.party.map_id)
			if current_map == null:
				return ScenarioRuntimeOperationResult.failed(&"missing_trigger_context", "Classic opcode 7 cannot resolve the current map.")
			var level_type := current_map.level_type
			if int(values[3]) != 0:
				if int(values[3]) not in [1, 2]:
					return ScenarioRuntimeOperationResult.failed(&"invalid_map_type", "Classic opcode 7 map type must be 1 for land or 2 for dungeon.")
				level_type = &"land" if int(values[3]) == 1 else &"dungeon"
			var target_map := _content.world.map_by_type_and_index(level_type, int(values[0]))
			if target_map == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_map", "Classic opcode 7 references unavailable %s map %d." % [String(level_type), int(values[0])])
			var target_trigger := _content.trigger_by_map_record(target_map.id, int(values[1]))
			if target_trigger == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_trigger", "Classic opcode 7 references unavailable Action Point record %d on map '%s'." % [int(values[1]), target_map.id])
			target_program_id = target_trigger.program_id
	if _content.scenario.program_by_id(source_program_id) == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_scenario_program", "Classic opcode 7 references unavailable source XAP %d." % int(values[2]))
	if _content.scenario.program_by_id(target_program_id) == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_scenario_program", "Classic opcode 7 references unavailable target program '%s'." % target_program_id)
	_game_state.set_scenario_program_override(target_program_id, source_program_id)
	return ScenarioRuntimeOperationResult.completed(true, [DomainEvent.new(&"scenario_program_replaced", {"sourceProgramId": target_program_id, "targetProgramId": source_program_id, "source": "classic"})])

func branch_to_trigger_program(action: ClassicActionDefinition, context: ScenarioExecutionContext) -> ScenarioRuntimeOperationResult:
	var current_trigger := _content.trigger_by_id(context.trigger_id)
	if current_trigger == null:
		return ScenarioRuntimeOperationResult.failed(&"missing_trigger_context", "Classic opcode 8 requires an Action Point origin.")
	var target_trigger := _content.trigger_by_map_record(current_trigger.map_id, action.operand_id)
	if target_trigger == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_trigger", "Classic opcode 8 references unavailable Action Point record %d on map '%s'." % [action.operand_id, current_trigger.map_id])
	return ScenarioRuntimeOperationResult.completed(target_trigger.program_id, [DomainEvent.new(&"scenario_program_redirected", {"triggerId": current_trigger.id, "targetTriggerId": target_trigger.id, "source": "classic"})], ScenarioVmDirective.branch_program(target_trigger.program_id, false, context))

func _branch_on_quest_value(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 77 requires a five-value Extra Code row.")
	var quest_id := action.extra_code[0]
	if quest_id < 0 or quest_id >= 100:
		return ScenarioRuntimeOperationResult.failed(&"invalid_quest", "Classic opcode 77 references quest %d outside 0 through 99." % quest_id)
	var matched := _game_state.quest_value(quest_id) >= action.extra_code[1]
	var target_id := action.extra_code[4] if matched else action.extra_code[3]
	var event := DomainEvent.new(&"quest_value_branch_checked", {"questId": quest_id, "value": _game_state.quest_value(quest_id), "minimum": action.extra_code[1], "matched": matched, "targetId": target_id})
	if target_id == 0:
		return ScenarioRuntimeOperationResult.completed(matched, [event])
	var branch := _branch_target_mode(action.extra_code[2], target_id, action.gosub)
	branch.events.append(event)
	return branch

func resume_thief(continuation: ScenarioRuntimeContinuation, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	var owner := continuation.body as ScenarioRuntimeContinuation.ThiefBody
	var selection := response.body as InteractionResponse.ThiefEncounterBody
	var encounter := _content.complex_encounter_by_id(owner.encounter_id) if owner != null else null
	if response.kind != InteractionRequest.THIEF_ENCOUNTER or selection == null or encounter == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Thief Encounter response does not match its source encounter.")
	if selection.action == &"back":
		var complex_request := _encounters.complex_encounter_request(encounter, request_id)
		if complex_request == null:
			return ScenarioRuntimeOperationResult.failed(&"encounter_has_no_options", "Complex Encounter has no available responses after leaving its Thief actions.")
		return ScenarioRuntimeOperationResult.waiting(complex_request, ScenarioRuntimeContinuation.encounter(ScenarioRuntimeContinuation.CLASSIC_COMPLEX_ENCOUNTER, encounter.id, owner.gosub, [], owner.encounter_attempt))
	return _attempt(encounter, owner.gosub, selection, request_id, owner.encounter_attempt)

func _present_action_result(encounter: ComplexEncounterDefinition, thief: ThiefEncounterDefinition, gosub: bool, character: CharacterState, action_index: int, succeeded: bool, trap_pending: bool, request_id: String, events: Array[DomainEvent], encounter_attempt: int) -> ScenarioRuntimeOperationResult:
	var text_ids := thief.success_text() if succeeded else thief.failure_text()
	var sound_ids := thief.success_sounds() if succeeded else thief.failure_sounds()
	var signed_message_id := text_ids[action_index]
	var message_id := absi(signed_message_id)
	var message := _content.message_by_id(message_id)
	if message_id != 0 and message == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_message", "Thief Encounter references unavailable message %d." % signed_message_id)
	if message != null:
		events.append(DomainEvent.new(&"message_shown", {"messageId": message.id, "text": message.text, "source": "classic-thief", "classicClick": signed_message_id > 0}))
	if sound_ids[action_index] != 0:
		events.append(DomainEvent.new(&"sound_requested", {"soundId": sound_ids[action_index], "waitForCompletion": false, "source": "classic-thief"}))
	if signed_message_id <= 0:
		if trap_pending:
			return _wait_for_trap_message(encounter, gosub, character, action_index, succeeded, request_id, events, encounter_attempt)
		return _finish_action(encounter, thief, gosub, character, action_index, succeeded, request_id, events, encounter_attempt)
	var request := InteractionRequest.from_payload(request_id, InteractionRequest.ACKNOWLEDGE, {"prompt": message.text if message != null else "", "messageId": message_id, "presentation": "classic-textbox", "soundId": sound_ids[action_index]})
	return ScenarioRuntimeOperationResult.waiting(request, ScenarioRuntimeContinuation.thief_resolution(encounter.id, gosub, action_index, character.id, &"action-message", succeeded, trap_pending, encounter_attempt), events) if request != null else ScenarioRuntimeOperationResult.failed(&"invalid_thief_encounter", "Thief Encounter result could not create its textbox stage.")

func _finish_action(encounter: ComplexEncounterDefinition, thief: ThiefEncounterDefinition, gosub: bool, character: CharacterState, action_index: int, succeeded: bool, request_id: String, events: Array[DomainEvent], encounter_attempt: int) -> ScenarioRuntimeOperationResult:
	var codes := thief.success_codes() if succeeded else thief.failure_codes()
	var outcome := codes[action_index]
	if succeeded and action_index in LOCK_ACTIONS and outcome != 0 and outcome != 4:
		var gained := 300 * thief.tumblers
		character.experience += gained
		events.append(DomainEvent.new(&"experience_awarded", {"characterId": character.id, "amount": gained, "source": "thief-encounter"}))
	if outcome == 0:
		return _wait_for_thief(encounter, gosub, request_id, events, encounter_attempt)
	var attempt := encounter_attempt + 1
	if outcome == 4 and encounter.max_times > 1 and attempt >= encounter.max_times:
		outcome = 3
	if outcome < 1 or outcome > 4:
		return ScenarioRuntimeOperationResult.failed(&"invalid_encounter_outcome", "Thief Encounter produced invalid result %d." % outcome)
	_state.record_encounter_attempt(&"complex", encounter.id)
	var context := ScenarioExecutionContext.encounter(&"complex", encounter.id, "", -1, &"thief").set_thief_action(action_index, character.id).set_encounter_attempt(attempt)
	var program_id := encounter.result_program_id(outcome)
	return ScenarioRuntimeOperationResult.completed(outcome, events, ScenarioVmDirective.branch_encounter_result(program_id, gosub, context, attempt < encounter.max_times))

func _start_pick_lock(encounter: ComplexEncounterDefinition, thief: ThiefEncounterDefinition, gosub: bool, character: CharacterState, action_index: int, request_id: String, encounter_attempt: int) -> ScenarioRuntimeOperationResult:
	var chance := ClassicPickLockRulesScript.chance(character.ability_value(ClassicPickLockRulesScript.ability_index(action_index)), thief.modifiers()[action_index])
	var frames := ClassicPickLockRulesScript.preview(_rng.snapshot(), thief.tumblers, chance)
	if frames.is_empty():
		return ScenarioRuntimeOperationResult.failed(&"invalid_pick_lock_state", "Pick Lock could not build its deterministic tumbler sequence.")
	var request := InteractionRequest.from_payload(request_id, InteractionRequest.PICK_LOCK, {
		"encounterId": encounter.id, "actionIndex": action_index, "actionLabel": ClassicPickLockRulesScript.action_label(action_index),
		"characterId": character.id, "characterName": character.name, "portraitId": character.portrait_id,
		"chancePercent": chance, "yellowThreshold": ClassicPickLockRulesScript.yellow_threshold(chance),
		"greenThreshold": ClassicPickLockRulesScript.green_threshold(chance), "frameRate": ClassicPickLockRulesScript.FRAME_RATE,
		"timeLimitFrames": ClassicPickLockRulesScript.time_limit_frames(thief.tumblers),
		"frames": frames,
	})
	if request == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_pick_lock_state", "Pick Lock generated an invalid typed interaction.")
	return ScenarioRuntimeOperationResult.waiting(request, ScenarioRuntimeContinuation.pick_lock(encounter.id, gosub, action_index, character.id, encounter_attempt), [DomainEvent.new(&"pick_lock_started", {"encounterId": encounter.id, "characterId": character.id, "actionIndex": action_index, "chancePercent": chance, "tumblers": ClassicPickLockRulesScript.tumbler_count(thief.tumblers)})])

func _recalculate_party_movement() -> void:
	for character: CharacterState in _game_state.party.characters():
		var race := _content.race_by_id(character.race_id)
		var caste := _content.caste_by_id(character.caste_id)
		_rules.characters.recalculate_movement(character, race, caste.movement_bonus)

func begin(encounter: ComplexEncounterDefinition, gosub: bool, request_id: String, encounter_attempt: int = 0) -> ScenarioRuntimeOperationResult:
	var request := _thief_request(encounter, request_id, true)
	if request == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_thief_encounter", "The Thief Encounter has no available living character or prompt.")
	return ScenarioRuntimeOperationResult.waiting(request, ScenarioRuntimeContinuation.thief_encounter(encounter.id, gosub, encounter_attempt), [DomainEvent.new(&"thief_encounter_opened", {"encounterId": encounter.id})])

static func shop_accepts_item(item: ItemDefinition, accept_ranges: Array[int]) -> bool:
	if item == null or accept_ranges.is_empty():
		return accept_ranges.is_empty()
	if accept_ranges.size() != 4:
		return false
	var failures := 0
	if accept_ranges[0] != 0 and not (accept_ranges[0] <= item.classic_id and item.classic_id <= accept_ranges[1]):
		failures += 1
	if accept_ranges[2] != 0 and not (accept_ranges[2] <= item.classic_id and item.classic_id <= accept_ranges[3]):
		failures += 1
	return failures < 2

func execute(action: ClassicActionDefinition, request_id: String, context: ScenarioExecutionContext) -> ScenarioRuntimeOperationResult:
	match action.opcode:
		21:
			return _branch_on_item(action)
		22:
			return _mutate_items(action)
		33:
			return _take_wealth(action)
		36:
			return toggle_equipment_storage(action.operand_id != 0)
		38:
			return _branch_on_item_result(action)
		49:
			return _configure_banking()
		51:
			return _mutate_shop(action)
		60:
			return _clear_character_money(action)
		91:
			return _drop_equipment()
	return super.execute(action, request_id, context)

func execute(action: ClassicActionDefinition, _request_id: String, context: ScenarioExecutionContext) -> ScenarioRuntimeOperationResult:
	match action.opcode:
		7:
			return replace_scenario_program(action, context)
		8:
			return branch_to_trigger_program(action, context)
		24:
			return ScenarioRuntimeOperationResult.completed(null, [DomainEvent.new(&"action_point_kept", {"triggerId": context.trigger_id, "source": "classic"})], ScenarioVmDirective.finish())
		25:
			var trigger_id := context.trigger_id
			if trigger_id.is_empty():
				return ScenarioRuntimeOperationResult.failed(&"missing_trigger_context", "Classic opcode 25 requires an Action Point origin.")
			_game_state.world.disable_trigger(trigger_id)
			return ScenarioRuntimeOperationResult.completed(true, [DomainEvent.new(&"trigger_disabled", {"triggerId": trigger_id, "source": "classic"})])
		42:
			return _percent_branch(action, context)
		46:
			return _branch_on_quest(action)
		64:
			return _branch_on_game_time(action)
		77:
			return _branch_on_quest_value(action)
		86:
			return _branch_on_misc(action)
		98, 99:
			return ScenarioRuntimeOperationResult.completed(null, [DomainEvent.new(&"classic_control_marker", {"opcode": action.opcode, "operandId": action.operand_id})])
	return super.execute(action, _request_id, context)

func _branch_on_item_result(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 38 requires a five-value Extra Code row.")
	var possessed := _party_has_classic_item(absi(action.extra_code[0]))
	var test_mode := action.extra_code[1]
	if test_mode == 2 or test_mode == 0 and not possessed or test_mode == 1 and possessed:
		return _branch_from_values(action.extra_code, false)
	if test_mode not in [0, 1, 2]:
		return ScenarioRuntimeOperationResult.failed(&"invalid_item_branch", "Classic item result branch has an invalid test mode.")
	return ScenarioRuntimeOperationResult.completed(false)

func _mutate_items(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 22 requires a five-value Extra Code row.")
	var source := _content.item_by_classic_id(absi(action.extra_code[0]))
	if source == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_item", "Classic item mutation references unavailable item %d." % action.extra_code[0])
	var operation := action.extra_code[2]
	var maximum := action.extra_code[1]
	if maximum < 0 or operation not in [1, 2, 3]:
		return ScenarioRuntimeOperationResult.failed(&"invalid_item_mutation", "Classic item mutation has an invalid count or operation.")
	var replacement := _content.item_by_classic_id(absi(action.extra_code[4])) if operation == 3 else null
	if operation == 3 and replacement == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_item", "Classic item replacement is unavailable.")
	var changed := 0
	for character: CharacterState in _game_state.party.characters():
		var items := character.inventory()
		for index: int in range(items.size() - 1, -1, -1):
			if maximum > 0 and changed >= maximum:
				break
			var instance: ItemInstance = items[index]
			if instance.definition_id != source.id:
				continue
			match operation:
				1:
					_rules.inventory.remove_item(character, instance.id, source)
				2:
					var previous_weight := source.instance_weight(instance.charges)
					instance.charges = clampi(instance.charges + action.extra_code[3], -1, 32_767)
					character.carried_load = maxi(0, character.carried_load - previous_weight + source.instance_weight(instance.charges))
				3:
					var was_equipped := instance.equipped
					_rules.inventory.remove_item(character, instance.id, source)
					var replacement_instance := _rules.inventory.add_item(character, replacement, _game_state.next_instance_id("classic.replacement"), false)
					if replacement_instance == null:
						return ScenarioRuntimeOperationResult.failed(&"inventory_full", "Classic replacement item no longer fits the character inventory.")
					if was_equipped and _rules.inventory.can_equip(character, replacement):
						replacement_instance.equipped = true
			changed += 1
		if maximum > 0 and changed >= maximum:
			break
	return ScenarioRuntimeOperationResult.completed(changed, [DomainEvent.new(&"party_items_changed", {"itemId": source.id, "operation": operation, "changed": changed})])

func _party_has_classic_item(classic_item_id: int, minimum_charges: int = -1, equipped_only: bool = false) -> bool:
	var definition := _content.item_by_classic_id(classic_item_id)
	if definition == null:
		return false
	for character: CharacterState in _game_state.party.characters():
		for instance: ItemInstance in character.inventory():
			if instance.definition_id == definition.id and (minimum_charges < 0 or instance.charges >= minimum_charges) and (not equipped_only or instance.equipped):
				return true
	return false

func _branch_from_values(values: Array[int], gosub: bool) -> ScenarioRuntimeOperationResult:
	match values[2]:
		0:
			return _branch_xap(values[3], gosub)
		3:
			return ScenarioRuntimeOperationResult.completed(true, [], ScenarioVmDirective.finish())
	return ScenarioRuntimeOperationResult.failed(&"unsupported_branch_mode", "Classic branch mode %d is not available in this execution context." % values[2])

func grant_treasure_definition(treasure: TreasureDefinition, request_id: String) -> ScenarioRuntimeOperationResult:
	var roll := _rules.economy.roll_treasure(treasure, _rng)
	return _begin_reward(&"scenario", treasure.id, roll.experience, roll.wealth, roll.item_ids, request_id)

func _rollback_failed_reward(operation: ScenarioRuntimeOperationResult, state_checkpoint: Dictionary, rng_checkpoint: Dictionary) -> ScenarioRuntimeOperationResult:
	if operation.state != ScenarioRuntimeOperationResult.State.FAILED:
		return operation
	operation.events.clear()
	if _game_state.to_data() == state_checkpoint and _rng.checkpoint() == rng_checkpoint:
		return operation
	var state_restored := _game_state.restore_from_data(state_checkpoint)
	var rng_restored := _rng.rollback(rng_checkpoint)
	if not state_restored or not rng_restored:
		return ScenarioRuntimeOperationResult.failed(&"reward_rollback_failed", "Reward processing failed and could not restore its deterministic transaction boundary.")
	# Restoring GameState replaces its owned object graph. Callers must return
	# immediately and resolve any subsequent state through _game_state again.
	return operation

func _begin_reward(origin: StringName, source_id: String, total_experience: int, wealth: WealthState, item_ids: Array[String], request_id: String, battle_stage: StringName = ClassicRewardState.NO_BATTLE_STAGE, bonus_treasure_classic_id: int = 0, leading_items: Array[ItemInstance] = []) -> ScenarioRuntimeOperationResult:
	if wealth == null or item_ids.size() + leading_items.size() > ClassicRewardState.MAX_PENDING_ITEMS:
		return ScenarioRuntimeOperationResult.failed(&"invalid_reward", "The reward exceeds the supported Classic reward bounds.")
	var experience_multiplier := _game_state.experience_multiplier
	if experience_multiplier < 0.0:
		var campaign := _content.campaign_definition()
		var current_levels := 0
		for party_character: CharacterState in _game_state.party.characters():
			current_levels += party_character.level
		experience_multiplier = PartySetupRules.experience_multiplier(campaign.recommended_party_levels, current_levels, _game_state.difficulty) if campaign != null and campaign.guidance_authored and campaign.recommended_party_levels > 0 else 1.0
	var scaled_experience := PartySetupRules.scale_experience_by_multiplier(total_experience, experience_multiplier)
	var scaled_wealth := WealthState.new(
		PartySetupRules.scale_money(wealth.gold, _game_state.difficulty),
		PartySetupRules.scale_money(wealth.gems, _game_state.difficulty),
		PartySetupRules.scale_money(wealth.jewelry, _game_state.difficulty),
	)
	var reward_definitions: Array[ItemDefinition] = []
	var unique_owned: Dictionary = {}
	for character: CharacterState in _game_state.party.characters():
		for carried: ItemInstance in character.inventory():
			unique_owned[carried.definition_id] = true
	for item_id: String in item_ids:
		var definition := _content.item_by_id(item_id)
		if definition == null:
			return ScenarioRuntimeOperationResult.failed(&"unknown_item", "Reward '%s' references unavailable item '%s'." % [source_id, item_id])
		if definition.cost < 0 and unique_owned.has(definition.id):
			continue
		reward_definitions.append(definition)
		if definition.cost < 0:
			unique_owned[definition.id] = true
	var reward := ClassicRewardState.new(origin, source_id, scaled_experience, scaled_wealth)
	reward.battle_stage = battle_stage
	reward.bonus_treasure_classic_id = bonus_treasure_classic_id
	var items: Array[ItemInstance] = leading_items.duplicate()
	for definition: ItemDefinition in reward_definitions:
		var identified := absi(definition.item_type) == 24
		items.append(ItemInstance.new(_game_state.next_instance_id("reward.item"), definition.id, definition.initial_charges, false, identified))
	if not reward.set_items(items):
		return ScenarioRuntimeOperationResult.failed(&"invalid_reward", "The reward contains invalid item instances.")
	var awards: Dictionary = {}
	var recipients := _reward_experience_recipients(origin)
	var share := 0 if recipients.is_empty() else int(float(reward.experience_pool) / float(recipients.size()))
	reward.experience_share = share
	for character: CharacterState in recipients:
		var race := _content.race_by_id(character.race_id)
		var awarded := _rules.characters.battle_experience(character, race, share)
		awards[character.id] = awarded
	if not reward.set_experience_awards(awards):
		return ScenarioRuntimeOperationResult.failed(&"invalid_reward", "The reward experience recipients are invalid.")
	_game_state.party.pooled_wealth.gold += scaled_wealth.gold
	_game_state.party.pooled_wealth.gems += scaled_wealth.gems
	_game_state.party.pooled_wealth.jewelry += scaled_wealth.jewelry
	for character: CharacterState in recipients:
		character.experience += int(awards[character.id])
	var events: Array[DomainEvent] = [DomainEvent.new(&"reward_opened", {"origin": String(origin), "sourceId": source_id, "experiencePool": reward.experience_pool, "experienceShare": reward.experience_share, "experienceByCharacter": awards, "wealth": scaled_wealth.to_data(), "itemCount": items.size()})]
	if items.is_empty() and scaled_wealth.gold == 0 and scaled_wealth.gems == 0 and scaled_wealth.jewelry == 0 and scaled_experience == 0:
		return _complete_reward(reward, request_id, events)
	return _wait_for_reward(reward, request_id, events)

func _reward_experience_recipients(origin: StringName) -> Array[CharacterState]:
	var result: Array[CharacterState] = []
	for character: CharacterState in _game_state.party.characters():
		if character.current_health <= 0 or character.conditions.value(ConditionRules.ANIMATED) < 0:
			continue
		if origin == &"battle" and (_game_state.combat == null or _game_state.combat.battlefield == null or not _game_state.combat.battlefield.has_actor(character.id)):
			continue
		result.append(character)
	return result

func _wait_for_reward(reward: ClassicRewardState, request_id: String, events: Array[DomainEvent] = []) -> ScenarioRuntimeOperationResult:
	var request := _reward_request(reward, request_id)
	if request == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_reward_continuation", "The reward has no valid interaction for its current phase.")
	return ScenarioRuntimeOperationResult.waiting(request, ScenarioRuntimeContinuation.reward(reward), events)

func _reward_request(reward: ClassicRewardState, request_id: String) -> InteractionRequest:
	if reward.phase == ClassicRewardState.LEVEL_PHASE:
		return _level_result_request(reward, request_id)
	if reward.phase == ClassicRewardState.SPELL_PHASE:
		return _reward_spell_request(reward, request_id)
	if reward.completion_pending:
		var summary := "%d unclaimed item%s and %d gold, %d gems, %d jewelry will be left behind." % [reward.items().size(), "" if reward.items().size() == 1 else "s", _game_state.party.pooled_wealth.gold, _game_state.party.pooled_wealth.gems, _game_state.party.pooled_wealth.jewelry]
		return InteractionRequest.from_payload(request_id, InteractionRequest.TREASURE_DISTRIBUTION, {"mode": "completion-confirmation", "prompt": "Leave the remaining treasure behind?", "summary": summary})
	var pending_items := reward.items()
	var item_payloads: Array[Dictionary] = []
	for pending: ItemInstance in pending_items:
		var item_payload := _reward_item_payload(reward, pending)
		if item_payload.is_empty():
			return null
		item_payloads.append(item_payload)
	var characters: Array[Dictionary] = []
	var has_share_capacity := false
	for character: CharacterState in _game_state.party.characters():
		var enabled := pending_items.any(func(item: ItemInstance) -> bool:
			var definition := _content.item_by_id(item.definition_id)
			return definition != null and _rules.inventory.can_restore_item(character, item, definition)
		)
		var reason := "" if enabled or pending_items.is_empty() else "This character cannot receive any remaining item."
		characters.append({
			"id": character.id,
			"name": character.name,
			"enabled": enabled,
			"reason": reason,
			"wealth": character.money.to_data(),
			"canTakeGold": _game_state.party.pooled_wealth.gold >= 5 and character.carried_load + 5 <= character.maximum_load,
			"canTakeGems": _game_state.party.pooled_wealth.gems >= 1 and character.carried_load + 1 <= character.maximum_load,
			"canTakeJewelry": _game_state.party.pooled_wealth.jewelry >= 1 and character.carried_load + 15 <= character.maximum_load,
			"goldReason": "The pool has fewer than 5 gold or the character cannot carry it.",
			"gemsReason": "The pool has no gems or the character cannot carry one.",
			"jewelryReason": "The pool has no jewelry or the character cannot carry one.",
			"itemCount": character.inventory().size(),
			"maximumMovement": character.maximum_movement,
			"load": character.carried_load,
			"maximumLoad": character.maximum_load,
		})
		has_share_capacity = has_share_capacity or character.carried_load < character.maximum_load
	var detect_rows := _reward_caster_rows(63, 5)
	var identify_rows := _reward_caster_rows(48, 25)
	var has_pending_items := not pending_items.is_empty()
	return InteractionRequest.from_payload(request_id, InteractionRequest.TREASURE_DISTRIBUTION, {
		"mode": "ordinary",
		"prompt": "Distribute the treasure, then choose Done.",
		"origin": String(reward.origin),
		"sourceId": reward.source_id,
		"experiencePool": reward.experience_pool,
		"experienceShare": reward.experience_share,
		"wealth": _game_state.party.pooled_wealth.to_data(),
		"items": item_payloads,
		"remaining": pending_items.size(),
		"characters": characters,
		"hasShareCapacity": has_share_capacity,
		"detect": {"visible": has_pending_items, "casters": [] if reward.magic_detected else detect_rows, "reason": "Magic has already been detected for this treasure." if reward.magic_detected else "No living caster knows Detect Magic with 5 spell points."},
		"identify": {"visible": has_pending_items, "casters": [] if reward.identified else identify_rows, "reason": "This treasure has already been identified." if reward.identified else "No living caster knows Identify with 25 spell points."},
	})

func _reward_item_payload(reward: ClassicRewardState, item: ItemInstance) -> Dictionary:
	var definition := _content.item_by_id(item.definition_id)
	if definition == null:
		return {}
	var assignments: Array[Dictionary] = []
	for character: CharacterState in _game_state.party.characters():
		var enabled := _rules.inventory.can_restore_item(character, item, definition)
		var reason := ""
		if character.inventory().size() >= InventoryRules.MAX_ITEMS:
			reason = "Inventory is full."
		elif character.carried_load + definition.instance_weight(item.charges) > character.maximum_load:
			reason = "The item would exceed maximum load."
		elif not enabled:
			reason = "This character cannot receive the item."
		assignments.append({"characterId": character.id, "enabled": enabled, "reason": reason})
	return {
		"instanceId": item.id,
		"definitionId": item.definition_id,
		"name": definition.name if item.identified else definition.unidentified_name,
		"charges": item.charges,
		"identified": item.identified,
		"magical": reward.magic_detected and definition.magical,
		"iconResourceType": "cicn",
		"iconId": definition.visible_icon_id(item.identified),
		"description": definition.description if item.identified else "Specials are unknown.",
		"facts": _reward_item_facts(item, definition),
		"assignments": assignments,
	}

func begin_completed_battle_reward(request_id: String, caller: ScenarioBattleCaller = null) -> ScenarioRuntimeOperationResult:
	var combat := _game_state.combat
	if combat == null or not combat.completed:
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_continuation", "Battle rewards require a completed battle.")
	if combat.rewards_completed:
		return ScenarioRuntimeOperationResult.completed(String(combat.outcome))
	if combat.rewards_started:
		return ScenarioRuntimeOperationResult.failed(&"battle_reward_already_started", "The completed battle already has an active reward continuation.")
	var bonus_treasure_id := caller.mode if combat.outcome == &"victory" and caller != null and caller.kind == ScenarioBattleCaller.CLASSIC and caller.opcode == 48 else 0
	if bonus_treasure_id != 0 and _content.treasure_by_classic_id(absi(bonus_treasure_id)) == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_treasure", "Classic opcode 48 references unavailable bonus treasure %d." % bonus_treasure_id)
	var experience_only := combat.outcome == &"victory" and caller != null and caller.kind == ScenarioBattleCaller.CLASSIC and caller.opcode == 2 and caller.mode == 5
	var defeated_monsters: Array[Dictionary] = []
	var reward_monsters: Array[Dictionary] = []
	var recovered_fumbles: Array[ItemInstance] = []
	for fumbled: ItemInstance in combat.fumbled_items():
		var definition := _content.item_by_id(fumbled.definition_id)
		if definition == null:
			return ScenarioRuntimeOperationResult.failed(&"unknown_item", "Battle recovery references unavailable item '%s'." % fumbled.definition_id)
		var recovered := ItemInstance.from_data(fumbled.to_data())
		if recovered == null:
			return ScenarioRuntimeOperationResult.failed(&"invalid_reward", "A fumbled battle item cannot enter the reward queue.")
		recovered.equipped = false
		recovered.identified = true
		recovered_fumbles.append(recovered)
	var pending_item_count := recovered_fumbles.size()
	if pending_item_count > ClassicRewardState.MAX_PENDING_ITEMS:
		return ScenarioRuntimeOperationResult.failed(&"invalid_reward", "The battle reward exceeds the supported Classic reward bounds.")
	if combat.outcome == &"victory":
		for monster: MonsterState in combat.monsters():
			var definition := _content.monster_by_id(monster.definition_id)
			if definition == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_monster", "Battle reward references unavailable monster content.")
			var parchment_eligible := definition.can_summon != -1 and definition.type_flag(0) and not definition.type_flag(7)
			var rations_eligible := definition.can_summon != -1 and not definition.type_flag(7) and not definition.type_flag(1)
			for incidental_classic_id: int in [806 if parchment_eligible else 0, 877 if rations_eligible else 0]:
				if incidental_classic_id == 0:
					continue
				if _content.item_by_classic_id(incidental_classic_id) == null:
					return ScenarioRuntimeOperationResult.failed(&"unknown_item", "Battle reward can generate unavailable Classic item %d." % incidental_classic_id)
				pending_item_count += 1
				if pending_item_count > ClassicRewardState.MAX_PENDING_ITEMS:
					return ScenarioRuntimeOperationResult.failed(&"invalid_reward", "The battle reward exceeds the supported Classic reward bounds.")
			reward_monsters.append({"monster": monster, "definition": definition, "parchmentEligible": parchment_eligible, "rationsEligible": rations_eligible})
			if not monster.traitor or monster.current_health >= 1:
				continue
			var loot := monster.loot_item_ids()
			if loot.is_empty():
				loot = definition.item_ids()
				if not loot.is_empty() and definition.random_weapon_table > 0:
					loot[0] = monster.weapon_id
			if not experience_only:
				for item_id: String in loot:
					if item_id.is_empty():
						continue
					if _content.item_by_id(item_id) == null:
						return ScenarioRuntimeOperationResult.failed(&"unknown_item", "Battle reward references unavailable item '%s'." % item_id)
					pending_item_count += 1
					if pending_item_count > ClassicRewardState.MAX_PENDING_ITEMS:
						return ScenarioRuntimeOperationResult.failed(&"invalid_reward", "The battle reward exceeds the supported Classic reward bounds.")
			defeated_monsters.append({"monster": monster, "definition": definition, "loot": loot})
	# Validate the whole source-owned reward before consuming RNG or claiming its
	# one-shot battle continuation. A malformed package therefore remains retryable.
	var state_checkpoint := _game_state.to_data()
	var rng_checkpoint := _rng.checkpoint()
	combat.rewards_started = true
	var item_ids: Array[String] = []
	var wealth := WealthState.new()
	var experience := 0
	var events: Array[DomainEvent] = []
	if combat.outcome == &"victory":
		for row: Dictionary in defeated_monsters:
			var monster: MonsterState = row["monster"]
			var definition: MonsterDefinition = row["definition"]
			var money := definition.money_values()
			for kind: WealthState.Kind in [WealthState.Kind.GOLD, WealthState.Kind.GEMS, WealthState.Kind.JEWELRY]:
				var maximum := maxi(0, money[kind] if kind < money.size() else 0)
				# Castle calls randrange for all three denominations even when the
				# authored maximum is zero. The zero-result draw still advances the
				# gameplay stream and therefore affects later scenario randomness.
				var amount := _rng.draw_between(0, maximum, StringName("battle.reward.%s.money.%d" % [monster.id, kind]))
				if not experience_only:
					wealth.add(kind, amount)
			experience += _monster_reward_experience(monster, definition)
			if not experience_only:
				for item_id: String in row["loot"]:
					if not item_id.is_empty():
						item_ids.append(item_id)
		for row: Dictionary in reward_monsters:
			var monster: MonsterState = row["monster"]
			if row["parchmentEligible"] and _rng.draw_classic(100, StringName("battle.reward.%s.parchment" % monster.id)) < 10:
				item_ids.append(_content.item_by_classic_id(806).id)
			if row["rationsEligible"] and _rng.draw_classic(100, StringName("battle.reward.%s.rations" % monster.id)) < 10:
				item_ids.append(_content.item_by_classic_id(877).id)
		events.append(DomainEvent.new(&"battle_reward_constructed", {"battleId": combat.battle_id, "experience": experience, "experienceOnly": experience_only, "wealth": wealth.to_data(), "itemCount": recovered_fumbles.size() + item_ids.size()}))
	var operation := _begin_reward(&"battle", combat.battle_id, experience, wealth, item_ids, request_id, ClassicRewardState.ORDINARY_BATTLE_STAGE, absi(bonus_treasure_id), recovered_fumbles)
	if operation.state == ScenarioRuntimeOperationResult.State.FAILED:
		return _rollback_failed_reward(operation, state_checkpoint, rng_checkpoint)
	combat.clear_fumbled_items()
	operation.events = events + operation.events
	return operation

func _take_wealth(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	var values := action.extra_code
	var amount := absi(action.operand_id) if values.is_empty() else absi(values[0])
	var kind := WealthState.Kind.GOLD if values.size() < 2 else clampi(values[1], WealthState.Kind.GOLD, WealthState.Kind.JEWELRY) as WealthState.Kind
	var paid := _rules.economy.take(_game_state.party, amount, kind)
	return ScenarioRuntimeOperationResult.completed(paid, [DomainEvent.new(&"wealth_taken", {"amount": amount, "kind": kind, "paid": paid, "source": "classic"})])

func _branch_on_item(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 21 requires a five-value Extra Code row.")
	var values := action.extra_code
	var possessed := _party_has_classic_item(absi(values[0]))
	if possessed:
		return _branch_target_mode(values[1], values[3], action.gosub)
	match int(values[2]):
		0:
			return _branch_target_mode(values[1], values[4], action.gosub)
		1:
			return ScenarioRuntimeOperationResult.completed(false)
		2:
			var message := _content.message_by_id(values[4])
			if message == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_message", "Classic item branch references unavailable message %d." % values[4])
			return ScenarioRuntimeOperationResult.completed(false, [DomainEvent.new(&"message_shown", {"messageId": message.id, "text": message.text, "source": "classic-item-check"})], ScenarioVmDirective.finish())
	return ScenarioRuntimeOperationResult.failed(&"invalid_item_branch", "Classic item possession branch has an invalid failure mode.")

func _branch_on_game_time(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 64 requires a five-value Extra Code row.")
	var day_limit := action.extra_code[0]
	var hour_limit := action.extra_code[1]
	if day_limit < -1 or hour_limit < -1 or hour_limit > 23:
		return ScenarioRuntimeOperationResult.failed(&"invalid_game_time_test", "Classic opcode 64 has an invalid day or hour limit.")
	var before_or_equal := (day_limit == -1 or _game_state.clock.day() <= day_limit) and (hour_limit == -1 or _game_state.clock.hour() <= hour_limit)
	var target_id := action.extra_code[3] if before_or_equal else action.extra_code[4]
	var branch := _branch_xap(target_id, action.gosub)
	branch.events.append(DomainEvent.new(&"game_time_branch_checked", {"day": _game_state.clock.day(), "hour": _game_state.clock.hour(), "dayLimit": day_limit, "hourLimit": hour_limit, "beforeOrEqual": before_or_equal, "targetId": target_id}))
	return branch

func _branch_on_quest(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 46 requires a five-value Extra Code row.")
	var is_set := _game_state.quest_is_set(action.extra_code[0])
	var condition := action.extra_code[1]
	var should_branch := condition == 2 or condition == 1 and is_set or condition == 0 and not is_set
	return _branch_from_values(action.extra_code, action.gosub) if should_branch else ScenarioRuntimeOperationResult.completed(false)

func _percent_branch(action: ClassicActionDefinition, context: ScenarioExecutionContext) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 42 requires a five-value Extra Code row.")
	var roll := _rng.draw(100, &"classic.percent-branch")
	if roll > action.extra_code[0]:
		return ScenarioRuntimeOperationResult.completed(false, [DomainEvent.new(&"percent_branch_checked", {"chance": action.extra_code[0], "roll": roll, "matched": false})])
	var event := DomainEvent.new(&"percent_branch_checked", {"chance": action.extra_code[0], "roll": roll, "matched": true})
	match action.extra_code[1]:
		-2:
			var trigger_id := context.trigger_id
			if not trigger_id.is_empty():
				_game_state.world.disable_trigger(trigger_id)
			return ScenarioRuntimeOperationResult.completed(true, [event], ScenarioVmDirective.finish())
		1:
			var branch := _branch_from_values(action.extra_code, false)
			branch.events.append(event)
			return branch
		2:
			return ScenarioRuntimeOperationResult.completed(true, [event], ScenarioVmDirective.finish())
	return ScenarioRuntimeOperationResult.completed(true, [event])

func execute(action: ClassicActionDefinition, request_id: String, context: ScenarioExecutionContext) -> ScenarioRuntimeOperationResult:
	match action.opcode:
		119:
			return _revive_after_combat_macro(context)
		120:
			return _alter_combat_monsters(action)
		121:
			return _deanimate_lower_undead()
		122:
			return cause_fumble(action, context)
		123:
			return _cause_monsters_to_route(action, context)
		124:
			return _spawn_classic_monsters(action)
		126:
			return _branch_battle_round_macro(action)
		127:
			return _continue_if_monster_present(action)
	return super.execute(action, request_id, context)

func _revive_after_combat_macro(context: ScenarioExecutionContext) -> ScenarioRuntimeOperationResult:
	var living_party := 0
	for character: CharacterState in _game_state.party.characters():
		if character.current_health > 0:
			living_party += 1
	if living_party == 0:
		var revived_party: Array[String] = []
		for character: CharacterState in _game_state.party.characters():
			character.current_health = 1
			character.conditions.set_value(ConditionRules.ANIMATED, 0)
			revived_party.append(character.id)
		return ScenarioRuntimeOperationResult.completed(revived_party, [DomainEvent.new(&"party_revived", {"characterIds": revived_party, "source": "classic-death-macro"})], ScenarioVmDirective.finish())
	if _game_state.combat == null:
		return ScenarioRuntimeOperationResult.failed(&"revival_outside_combat", "Classic opcode 119 has no combatant to revive.")
	var combatant_id := context.combatant_id
	var monster := _game_state.combat.monster_by_id(combatant_id)
	if monster == null:
		return ScenarioRuntimeOperationResult.failed(&"missing_combatant_context", "Classic opcode 119 requires its death-macro combatant identity.")
	monster.current_health = 1
	monster.traitor = false
	return ScenarioRuntimeOperationResult.completed(monster.id, [DomainEvent.new(&"monster_revived", {"monsterId": monster.id, "source": "classic-death-macro"})])

func _alter_combat_monsters(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if _game_state.combat == null or _game_state.combat.completed:
		return ScenarioRuntimeOperationResult.completed(0, [DomainEvent.new(&"combat_monsters_altered", {"count": 0, "reason": "no-active-battle", "source": "classic"})])
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 120 requires a five-value Extra Code row.")
	var target_kind := action.extra_code[0]
	var definition := _content.monster_by_classic_id_for_set(absi(action.extra_code[1]), _game_state.monster_set)
	var remaining := maxi(0, action.extra_code[2])
	if target_kind < 1 or target_kind > 2 or definition == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_combat_monster_target", "Classic opcode 120 references an unavailable monster kind or identity.")
	var candidates := _game_state.party.allies() if target_kind == 1 else _game_state.combat.monsters()
	var altered: Array[String] = []
	for monster: MonsterState in candidates:
		if remaining <= 0:
			break
		var candidate_definition := _content.monster_by_id(monster.definition_id)
		if candidate_definition == null or candidate_definition.classic_id != definition.classic_id:
			continue
		if action.extra_code[3] != -1:
			monster.icon_id = action.extra_code[3]
			altered.append(monster.id)
			remaining -= 1
		elif action.extra_code[4] != -1 and monster.traitor != (action.extra_code[4] != 0):
			monster.traitor = action.extra_code[4] != 0
			altered.append(monster.id)
			remaining -= 1
	return ScenarioRuntimeOperationResult.completed(altered.size(), [DomainEvent.new(&"combat_monsters_altered", {"count": altered.size(), "monsterIds": altered, "classicMonsterId": definition.classic_id, "targetKind": target_kind, "source": "classic"})])

func _deanimate_lower_undead() -> ScenarioRuntimeOperationResult:
	if _game_state.combat == null or _game_state.combat.completed:
		return ScenarioRuntimeOperationResult.failed(&"no_active_battle", "Classic opcode 121 requires an active battle.")
	var affected: Array[String] = []
	for monster: MonsterState in _game_state.combat.monsters():
		var definition := _content.monster_by_id(monster.definition_id)
		if definition != null and definition.type_flag(1) and not definition.type_flag(5) and monster.current_health > 0:
			monster.current_health = 0
			affected.append(monster.id)
	return ScenarioRuntimeOperationResult.completed(affected, [DomainEvent.new(&"lower_undead_deanimated", {"monsterIds": affected})])

func _cause_monsters_to_route(action: ClassicActionDefinition, context: ScenarioExecutionContext) -> ScenarioRuntimeOperationResult:
	if _game_state.combat == null or _game_state.combat.completed:
		return ScenarioRuntimeOperationResult.completed(0, [DomainEvent.new(&"combat_route_applied", {"count": 0, "reason": "no-active-battle", "source": "classic"})])
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 123 requires a five-value Extra Code row.")
	var source_traitor := true
	var source_id := context.combatant_id
	var source_monster := _game_state.combat.monster_by_id(source_id)
	if source_monster != null:
		source_traitor = source_monster.traitor
	var definition_ids: Dictionary = {}
	for classic_id: int in action.extra_code:
		if classic_id == 0:
			continue
		var definition := _content.monster_by_classic_id_for_set(absi(classic_id), _game_state.monster_set)
		if definition == null:
			return ScenarioRuntimeOperationResult.failed(&"unknown_monster", "Classic opcode 123 references unavailable monster %d." % classic_id)
		definition_ids[definition.classic_id] = true
	var routed: Array[String] = []
	for monster: MonsterState in _game_state.combat.monsters():
		var routed_definition := _content.monster_by_id(monster.definition_id)
		if routed_definition != null and monster.current_health > 0 and monster.traitor == source_traitor and definition_ids.has(routed_definition.classic_id):
			monster.conditions.set_value(ConditionRules.RUNS_AWAY, -1)
			monster.surrender_percent = 50
			routed.append(monster.id)
	return ScenarioRuntimeOperationResult.completed(routed.size(), [DomainEvent.new(&"combat_route_applied", {"count": routed.size(), "monsterIds": routed, "traitorSide": source_traitor, "source": "classic"})])

func _spawn_classic_monsters(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if _game_state.combat == null or _game_state.combat.completed:
		return ScenarioRuntimeOperationResult.failed(&"no_active_battle", "Classic opcode 124 requires an active battle.")
	if action.extra_code.size() < 3:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 124 requires a five-value Extra Code row.")
	var definition := _content.monster_by_classic_id_for_set(absi(action.extra_code[1]), _game_state.monster_set)
	if definition == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_monster", "Classic opcode 124 references unavailable monster %d." % action.extra_code[1])
	var authored_count := action.extra_code[2]
	var count := _rng.draw(absi(authored_count), &"classic.combat.spawn-count") if authored_count < 0 else authored_count
	var spawned: Array[String] = []
	for _index: int in maxi(0, count):
		var monster := _rules.monsters.build_monster(definition, _game_state.next_instance_id("combat.spawn"), -1, _game_state.difficulty, _game_state.clock.day(), _rng)
		if monster != null and _game_state.combat.add_monster(monster):
			_game_state.combat.append_turn_actor(monster.id)
			spawned.append(monster.id)
	return ScenarioRuntimeOperationResult.completed(spawned, [DomainEvent.new(&"combat_monsters_spawned", {"monsterId": definition.id, "instanceIds": spawned, "soundId": action.extra_code[3] if action.extra_code.size() > 3 else 0})])

func _branch_battle_round_macro(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if _game_state.combat == null or _game_state.combat.completed:
		return ScenarioRuntimeOperationResult.failed(&"battle_macro_outside_combat", "Classic opcode 126 requires an active battle macro.")
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 126 requires a five-value Extra Code row.")
	var combat := _game_state.combat
	if combat.macro_id > 0:
		return ScenarioRuntimeOperationResult.completed(false, [], ScenarioVmDirective.finish())
	var mode := action.extra_code[0]
	var matched := false
	match mode:
		0:
			matched = combat.round_number - 1 == action.extra_code[1]
		1:
			matched = _rng.draw(100, &"classic.battle-round-macro-percent") <= action.extra_code[1]
		_:
			return ScenarioRuntimeOperationResult.failed(&"invalid_battle_macro_test", "Classic opcode 126 has an invalid round test mode.")
	if not matched:
		return ScenarioRuntimeOperationResult.completed(false, [DomainEvent.new(&"battle_macro_tested", {"matched": false, "mode": mode, "round": combat.round_number, "source": "classic"})], ScenarioVmDirective.finish())
	if action.extra_code[2] != 1:
		combat.macro_id = 0
	var target_id := action.extra_code[3]
	if action.extra_code[2] == 2:
		target_id = _rng.draw_between(action.extra_code[3], action.extra_code[4], &"classic.battle-round-macro-target")
	if target_id <= 0:
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_macro_target", "Classic opcode 126 references an invalid Extra Action Point target.")
	return ScenarioRuntimeOperationResult.completed(true, [DomainEvent.new(&"battle_macro_tested", {"matched": true, "mode": mode, "round": combat.round_number, "targetId": target_id, "repeating": action.extra_code[2] == 1, "source": "classic"})], ScenarioVmDirective.branch_xap(target_id, false))

func _continue_if_monster_present(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if _game_state.combat == null or _game_state.combat.completed:
		return ScenarioRuntimeOperationResult.failed(&"monster_test_outside_combat", "Classic opcode 127 requires an active battle macro.")
	var definition := _content.monster_by_classic_id_for_set(absi(action.operand_id), _game_state.monster_set)
	if definition == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_monster", "Classic opcode 127 references unavailable monster %d." % action.operand_id)
	var present := false
	for monster: MonsterState in _game_state.combat.monsters():
		var present_definition := _content.monster_by_id(monster.definition_id)
		if present_definition != null and present_definition.classic_id == definition.classic_id and monster.current_health > 0:
			present = true
			break
	var directive: ScenarioVmDirective = null if present else ScenarioVmDirective.finish()
	return ScenarioRuntimeOperationResult.completed(present, [DomainEvent.new(&"battle_monster_presence_checked", {"classicMonsterId": definition.classic_id, "present": present, "source": "classic"})], directive)

func cause_fumble(action: ClassicActionDefinition, context: ScenarioExecutionContext) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 2:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 122 requires message and sound fields.")
	if _game_state.combat == null or _game_state.combat.completed:
		return ScenarioRuntimeOperationResult.completed(false, [DomainEvent.new(&"combat_fumble_skipped", {"reason": "no-active-battle", "source": "classic"})])
	var actor_id := context.combatant_id if not context.combatant_id.is_empty() else _game_state.combat.active_actor_id()
	var result := _rules.combat_flow.cause_active_fumble(_game_state, _content, actor_id)
	if not result.ok:
		return ScenarioRuntimeOperationResult.failed(result.error_code, result.error_message)
	if result.events.any(func(event: DomainEvent) -> bool: return event.kind == &"combat_fumble_skipped" and event.payload.get("reason") in ["no-physical-action", "not-party-actor"]):
		return ScenarioRuntimeOperationResult.completed(false, result.events)
	var events: Array[DomainEvent] = []
	if int(action.extra_code[1]) != 0:
		events.append(DomainEvent.new(&"sound_requested", {"soundId": absi(int(action.extra_code[1])), "waitForCompletion": int(action.extra_code[1]) < 0, "source": "classic"}))
	if int(action.extra_code[0]) != 0:
		var message := _content.message_by_id(absi(int(action.extra_code[0])))
		if message != null:
			events.append(DomainEvent.new(&"message_shown", {"messageId": message.id, "text": message.text, "source": "classic"}))
	events.append_array(result.events)
	var changed := false
	for event: DomainEvent in result.events:
		if event.kind == &"combatant_fumbled":
			changed = true
			break
	return ScenarioRuntimeOperationResult.completed(changed, events)

func _resume_reward(continuation: ScenarioRuntimeContinuation, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	if continuation == null or continuation.kind != ScenarioRuntimeContinuation.CLASSIC_REWARD:
		return ScenarioRuntimeOperationResult.failed(&"invalid_reward_continuation", "The reward continuation is malformed.")
	var reward_body := continuation.body as ScenarioRuntimeContinuation.RewardBody
	var reward := ClassicRewardState.from_data(reward_body.state.to_data()) if reward_body != null and reward_body.state != null else null
	if reward == null or not _reward_state_is_valid(reward):
		return ScenarioRuntimeOperationResult.failed(&"invalid_reward_continuation", "The saved reward state is invalid.")
	if reward.phase == ClassicRewardState.LEVEL_PHASE:
		return _resume_reward_level(reward, response, request_id)
	if reward.phase == ClassicRewardState.SPELL_PHASE:
		return _resume_reward_spells(reward, response, request_id)
	var body := response.body as InteractionResponse.TreasureBody
	if response.kind != InteractionRequest.TREASURE_DISTRIBUTION or body == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Treasure distribution requires a typed action.")
	var action := String(body.action)
	var events: Array[DomainEvent] = []
	if reward.completion_pending:
		if action == "cancel-completion":
			reward.completion_pending = false
			return _wait_for_reward(reward, request_id)
		if action != "confirm-completion":
			return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Treasure completion must be confirmed or cancelled.")
		var abandoned := reward.items().size()
		var no_items: Array[ItemInstance] = []
		reward.set_items(no_items)
		var forfeited := _game_state.party.pooled_wealth.to_data()
		_game_state.party.pooled_wealth = WealthState.new()
		reward.completion_pending = false
		events.append(DomainEvent.new(&"reward_remainder_left", {"itemCount": abandoned, "wealth": forfeited}))
		return _begin_reward_progression(reward, request_id, events)
	match action:
		"assign":
			var mutation := _assign_reward_item(reward, body)
			if not mutation.is_empty():
				return ScenarioRuntimeOperationResult.failed(StringName(mutation["code"]), mutation["message"])
			events.append(DomainEvent.new(&"reward_item_assigned", {"instanceId": body.instance_id, "characterId": body.character_id}))
		"discard":
			var discarded := reward.remove_item(body.instance_id)
			if discarded == null:
				return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "The item being left behind is not pending treasure.")
			events.append(DomainEvent.new(&"reward_item_left", {"instanceId": discarded.id, "itemId": discarded.definition_id}))
		"pool":
			var movement_error := _money_movement_context_error()
			if not movement_error.is_empty():
				return ScenarioRuntimeOperationResult.failed(&"invalid_money_context", movement_error)
			var pool_probe := _rules.economy.pool_probe(_game_state.party)
			if not pool_probe.allowed:
				return ScenarioRuntimeOperationResult.failed(&"money_action_unavailable", pool_probe.reason)
			_rules.economy.pool_party_wealth(_game_state.party)
			_recalculate_party_movement()
			events.append(DomainEvent.new(&"reward_wealth_pooled", _game_state.party.pooled_wealth.to_data()))
			events.append(DomainEvent.new(&"sound_requested", {"soundId": 128, "waitForCompletion": false, "source": "classic-reward-pool"}))
		"share":
			var movement_error := _money_movement_context_error()
			if not movement_error.is_empty():
				return ScenarioRuntimeOperationResult.failed(&"invalid_money_context", movement_error)
			var share_probe := _rules.economy.share_probe(_game_state.party)
			if not share_probe.allowed:
				return ScenarioRuntimeOperationResult.failed(&"money_action_unavailable", share_probe.reason)
			_rules.economy.share_pooled_wealth(_game_state.party)
			_recalculate_party_movement()
			events.append(DomainEvent.new(&"reward_wealth_shared", _game_state.party.pooled_wealth.to_data()))
			events.append(DomainEvent.new(&"sound_requested", {"soundId": 128, "waitForCompletion": false, "source": "classic-reward-share"}))
		"transfer":
			var transfer_error := _transfer_reward_wealth(body)
			if not transfer_error.is_empty():
				return ScenarioRuntimeOperationResult.failed(StringName(transfer_error["code"]), transfer_error["message"])
			events.append(DomainEvent.new(&"reward_wealth_transferred", {"characterId": body.character_id, "direction": String(body.direction), "kind": String(body.wealth_kind), "amount": body.amount}))
			events.append(DomainEvent.new(&"sound_requested", {"soundId": 10051 if body.direction == &"to-character" else 663, "waitForCompletion": false, "source": "classic-reward-swap"}))
		"detect", "identify":
			var detection_error := _apply_reward_detection(reward, action, body)
			if not detection_error.is_empty():
				return ScenarioRuntimeOperationResult.failed(StringName(detection_error["code"]), detection_error["message"])
			events.append(DomainEvent.new(&"reward_magic_%s" % ("detected" if action == "detect" else "identified"), {"characterId": body.character_id}))
		"done":
			if not reward.items().is_empty() or _reward_has_pooled_wealth():
				reward.completion_pending = true
				return _wait_for_reward(reward, request_id)
			return _begin_reward_progression(reward, request_id)
		_:
			return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "The treasure action is unavailable.")
	return _wait_for_reward(reward, request_id, events)

func _request_complex_encounter(action: ClassicActionDefinition, request_id: String, context: ScenarioExecutionContext) -> ScenarioRuntimeOperationResult:
	var encounter := _content.complex_encounter_by_id(action.operand_id)
	if encounter == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_encounter", "Classic opcode 5 references unavailable Complex Encounter %d." % action.operand_id)
	var request := complex_encounter_request(encounter, request_id)
	if request == null:
		return ScenarioRuntimeOperationResult.failed(&"encounter_has_no_options", "Complex Encounter %d has no available responses." % encounter.id)
	return ScenarioRuntimeOperationResult.waiting(request, ScenarioRuntimeContinuation.encounter(ScenarioRuntimeContinuation.CLASSIC_COMPLEX_ENCOUNTER, encounter.id, action.gosub, [], _encounter_attempt(context, &"complex", encounter.id)))

func resume(continuation: ScenarioRuntimeContinuation, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	match continuation.kind:
		ScenarioRuntimeContinuation.CLASSIC_SHOP:
			return _resume_shop(continuation, response, request_id)
		ScenarioRuntimeContinuation.CLASSIC_TEMPLE:
			return _resume_temple(continuation, response, request_id)
		ScenarioRuntimeContinuation.CLASSIC_TEMPLE_EXIT:
			return _resume_temple_exit(continuation, response, request_id)
		ScenarioRuntimeContinuation.CLASSIC_BANKING:
			return _resume_banking(continuation, response, request_id)
	return ScenarioRuntimeOperationResult.failed(&"unknown_interaction_continuation", "Service continuation is unavailable.")

func request_shop_definition(shop: ShopDefinition, request_id: String, accept_ranges: Array[int] = []) -> ScenarioRuntimeOperationResult:
	if _game_state.bank_available:
		_rules.economy.bank_to_pool(_game_state.party)
	return ScenarioRuntimeOperationResult.waiting(
		shop_request(shop, request_id, accept_ranges),
		ScenarioRuntimeContinuation.shop(shop.id, accept_ranges),
		[DomainEvent.new(&"shop_opened", {"shopId": shop.id, "acceptRanges": accept_ranges.duplicate(), "bankAvailable": _game_state.bank_available})]
	)

func request_available_temple(request_id: String) -> ScenarioRuntimeOperationResult:
	if not _game_state.temple_available:
		return ScenarioRuntimeOperationResult.failed(&"temple_unavailable", "No Classic temple is available at this location.")
	if _game_state.bank_available:
		_rules.economy.bank_to_pool(_game_state.party)
	var characters := _game_state.party.characters()
	var selected_character_id := "" if characters.is_empty() else characters[0].id
	var continuation := ScenarioRuntimeContinuation.temple(ScenarioRuntimeContinuation.CLASSIC_TEMPLE, _game_state.temple_cost_percent, _game_state.bank_available, selected_character_id)
	return ScenarioRuntimeOperationResult.waiting(temple_request(_game_state.temple_cost_percent, request_id, selected_character_id), continuation, [
		DomainEvent.new(&"temple_opened", {"costPercent": _game_state.temple_cost_percent, "bankAvailable": _game_state.bank_available}),
		DomainEvent.new(&"music_requested", {"musicId": 10, "source": "classic-temple"}),
		DomainEvent.new(&"sound_requested", {"soundId": 10105, "waitForCompletion": false, "source": "classic-temple-entry"}),
	])

func shop_request(shop: ShopDefinition, request_id: String, accept_ranges: Array[int] = []) -> InteractionRequest:
	var stock: Array[Dictionary] = []
	var characters: Array[Dictionary] = []
	var item_ids := shop.item_ids()
	for index: int in item_ids.size():
		var item := _content.item_by_id(item_ids[index])
		if item != null:
			stock.append(_shop_stock_view(item, "base:%d" % index, index, _game_state.shop_quantity(shop, index), shop))
	var buyback_items := _game_state.shop_buyback_items(shop.id)
	var buyback_ids: Array = buyback_items.keys()
	buyback_ids.sort_custom(func(left: Variant, right: Variant) -> bool:
		var left_item := _content.item_by_id(String(left))
		var right_item := _content.item_by_id(String(right))
		return left_item != null and right_item != null and left_item.classic_id < right_item.classic_id
	)
	for item_id: Variant in buyback_ids:
		if item_ids.has(String(item_id)):
			continue
		var item := _content.item_by_id(String(item_id))
		if item != null:
			stock.append(_shop_stock_view(item, "buyback:%s" % item.id, -1, int(buyback_items[item_id]), shop))
	var party_gold := _rules.economy.available(_game_state.party, WealthState.Kind.GOLD)
	for character: CharacterState in _game_state.party.characters():
		var inventory: Array[Dictionary] = []
		for instance: ItemInstance in character.inventory():
			var definition := _content.item_by_id(instance.definition_id)
			if definition == null:
				continue
			var can_sell := not instance.equipped and shop_accepts_item(definition, accept_ranges)
			var sell_reason := ""
			if instance.equipped:
				sell_reason = "Unequip this item before selling it."
			elif not shop_accepts_item(definition, accept_ranges):
				sell_reason = "This shop does not accept this item."
			var can_identify := not instance.identified and party_gold >= 20
			var identify_reason := ""
			if instance.identified:
				identify_reason = "This item is already identified."
			elif party_gold < 20:
				identify_reason = "Identification costs 20 gold."
			inventory.append({
				"instanceId": instance.id,
				"itemId": definition.id,
				"name": definition.name if instance.identified else definition.unidentified_name,
				"identified": instance.identified,
				"equipped": instance.equipped,
				"charges": instance.charges,
				"sellPrice": _rules.economy.shop_sell_price(definition, instance, _game_state.shop_inflation(shop)),
				"canSell": can_sell,
				"sellReason": sell_reason,
				"canIdentify": can_identify,
				"identifyReason": identify_reason,
				"iconResourceType": "cicn",
				"iconId": definition.visible_icon_id(instance.identified),
			})
		characters.append({"id": character.id, "name": character.name, "inventory": inventory})
	return InteractionRequest.from_payload(request_id, &"shop_action", {
		"shopId": shop.id,
		"inflationPercent": _game_state.shop_inflation(shop),
		"partyGold": party_gold,
		"identifyPrice": 20,
		"stock": stock,
		"characters": characters,
		"acceptRanges": accept_ranges.duplicate(),
		"actions": ["buy", "sell", "identify", "leave"],
	})

func temple_request(cost_percent: int, request_id: String, selected_character_id: String = "") -> InteractionRequest:
	var characters: Array[Dictionary] = []
	for character: CharacterState in _game_state.party.characters():
		var conditions: Array[Dictionary] = []
		for index: int in character.conditions.size():
			if character.conditions.value(index) != 0:
				conditions.append({"index": index, "name": _rules.temple.condition_name(index), "value": character.conditions.value(index)})
				if conditions.size() == 5:
					break
		characters.append({
			"id": character.id,
			"name": character.name,
			"currentHealth": character.current_health,
			"maximumHealth": character.maximum_health,
			"personalGold": character.money.gold,
			"availableGold": character.money.gold + _game_state.party.pooled_wealth.gold,
			"load": character.carried_load,
			"maximumLoad": character.maximum_load,
			"portraitId": character.portrait_id,
			"conditions": conditions,
		})
	return InteractionRequest.from_payload(request_id, InteractionRequest.TEMPLE, {
		"costPercent": cost_percent,
		"characters": characters,
		"services": _rules.temple.service_rows(cost_percent),
		"pooledWealth": _game_state.party.pooled_wealth.to_data(),
		"bankAvailable": _game_state.bank_available,
		"selectedCharacterId": selected_character_id,
		"actions": ["service", "pool", "share", "leave"],
	})

func _request_shop(classic_shop_id: int, request_id: String, accept_ranges: Array[int] = []) -> ScenarioRuntimeOperationResult:
	var shop := _content.shop_by_classic_id(absi(classic_shop_id))
	if shop == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_shop", "Classic opcode 6 references unavailable shop %d." % classic_shop_id)
	return request_shop_definition(shop, request_id, accept_ranges)

func execute(action: ClassicActionDefinition, request_id: String, context: ScenarioExecutionContext) -> ScenarioRuntimeOperationResult:
	match action.opcode:
		6:
			return _request_shop(action.operand_id, request_id)
		32:
			return _configure_temple(action)
		73:
			return _configure_shop(action, request_id)
	return super.execute(action, request_id, context)

func _configure_shop(action: ClassicActionDefinition, request_id: String) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 73 requires a five-value Extra Code row.")
	var shop := _content.shop_by_classic_id(absi(action.extra_code[0]))
	if shop == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_shop", "Classic opcode 73 references unavailable shop %d." % action.extra_code[0])
	var accept_ranges: Array[int] = [action.extra_code[1], action.extra_code[2], action.extra_code[3], action.extra_code[4]]
	if not _game_state.set_active_shop(shop.id, accept_ranges):
		return ScenarioRuntimeOperationResult.failed(&"invalid_shop_configuration", "Classic opcode 73 shop restrictions are invalid.")
	if action.extra_code[0] < 0:
		return _request_shop(action.extra_code[0], request_id, accept_ranges)
	return ScenarioRuntimeOperationResult.completed(shop.id, [DomainEvent.new(&"shop_available", {"shopId": shop.id, "acceptRanges": accept_ranges})])

func _resume_shop(continuation: ScenarioRuntimeContinuation, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	var body := response.body as InteractionResponse.ShopBody
	if response.kind != &"shop_action" or body == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Shop response requires an action string.")
	var service := continuation.body as ScenarioRuntimeContinuation.ServiceBody
	var shop := _content.shop_by_id(service.shop_id)
	if shop == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_shop", "The pending shop is unavailable.")
	var operation := String(body.action)
	if operation == "leave":
		if _game_state.bank_available:
			_rules.economy.pool_to_bank(_game_state.party)
		return ScenarioRuntimeOperationResult.completed(true, [DomainEvent.new(&"shop_closed", {"shopId": shop.id, "pooledWealthReturnedToBank": _game_state.bank_available})])
	var events: Array[DomainEvent] = []
	match operation:
		"buy":
			if body.character_id.is_empty() or body.stock_key.is_empty():
				return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Shop buy requires stock identity and characterId.")
			var stock_entry := resolve_shop_stock(shop, body.stock_key)
			if stock_entry == null or stock_entry.quantity < 1:
				return ScenarioRuntimeOperationResult.failed(&"shop_item_unavailable", "The selected shop item is out of stock.")
			var character := _game_state.party.character_by_id(body.character_id)
			var item := stock_entry.item
			if character == null or item == null or character.inventory().size() >= InventoryRules.MAX_ITEMS or character.carried_load + item.instance_weight(item.initial_charges) > character.maximum_load:
				return ScenarioRuntimeOperationResult.failed(&"inventory_full", "The selected character cannot carry this item.")
			var price := _rules.economy.shop_buy_price(item, _game_state.shop_inflation(shop))
			if not _rules.economy.take(_game_state.party, price, WealthState.Kind.GOLD):
				return ScenarioRuntimeOperationResult.failed(&"insufficient_gold", "The party cannot afford this item.")
			var instance := _rules.inventory.add_item(character, item, _game_state.next_instance_id("shop.item"), true)
			if instance == null:
				_game_state.party.pooled_wealth.gold += price
				return ScenarioRuntimeOperationResult.failed(&"inventory_full", "The item could not be added after purchase validation.")
			if stock_entry.kind == &"base":
				var stock_index := stock_entry.index
				_game_state.set_shop_quantity(shop, stock_index, _game_state.shop_quantity(shop, stock_index) - 1)
			else:
				_game_state.set_shop_buyback_quantity(shop.id, item.id, stock_entry.quantity - 1)
			events.append(DomainEvent.new(&"shop_item_bought", {"shopId": shop.id, "itemId": item.id, "instanceId": instance.id, "characterId": character.id, "price": price}))
		"sell":
			if body.character_id.is_empty() or body.instance_id.is_empty():
				return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Shop sell requires characterId and instanceId.")
			var character := _game_state.party.character_by_id(body.character_id)
			if character == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_character", "The shop sale character is unavailable.")
			var instance: ItemInstance = null
			for candidate: ItemInstance in character.inventory():
				if candidate.id == body.instance_id:
					instance = candidate
					break
			if instance == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_item_instance", "The sold item instance is unavailable.")
			var item := _content.item_by_id(instance.definition_id)
			if item == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_item", "The sold item definition is unavailable.")
			if instance.equipped:
				return ScenarioRuntimeOperationResult.failed(&"equipped_item", "Unequip this item before selling it.")
			var accept_ranges: Array[int] = []
			accept_ranges.assign(service.accept_ranges)
			if not ClassicServiceOperations.shop_accepts_item(item, accept_ranges):
				return ScenarioRuntimeOperationResult.failed(&"shop_rejects_item", "This shop does not accept the selected item.")
			var price := _rules.economy.shop_sell_price(item, instance, _game_state.shop_inflation(shop))
			if _rules.inventory.remove_item(character, instance.id, item) == null:
				return ScenarioRuntimeOperationResult.failed(&"shop_sale_failed", "The selected item could not be removed.")
			_game_state.party.pooled_wealth.gold += price
			var base_index := shop.item_ids().find(item.id)
			if base_index >= 0:
				_game_state.set_shop_quantity(shop, base_index, _game_state.shop_quantity(shop, base_index) + 1)
			else:
				_game_state.set_shop_buyback_quantity(shop.id, item.id, _game_state.shop_buyback_quantity(shop.id, item.id) + 1)
			events.append(DomainEvent.new(&"shop_item_sold", {"shopId": shop.id, "itemId": item.id, "instanceId": instance.id, "characterId": character.id, "price": price}))
		"identify":
			if body.character_id.is_empty() or body.instance_id.is_empty():
				return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Shop identification requires characterId and instanceId.")
			var character := _game_state.party.character_by_id(body.character_id)
			if character == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_character", "The identification character is unavailable.")
			var instance: ItemInstance = null
			for candidate: ItemInstance in character.inventory():
				if candidate.id == body.instance_id:
					instance = candidate
					break
			if instance == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_item_instance", "The identification item is unavailable.")
			if instance.identified:
				return ScenarioRuntimeOperationResult.failed(&"already_identified", "This item is already identified.")
			if not _rules.economy.take(_game_state.party, 20, WealthState.Kind.GOLD):
				return ScenarioRuntimeOperationResult.failed(&"insufficient_gold", "Identification costs 20 gold.")
			instance.identified = true
			events.append(DomainEvent.new(&"item_identified", {"shopId": shop.id, "instanceId": instance.id, "characterId": character.id, "price": 20, "source": "classic-shop"}))
			events.append(DomainEvent.new(&"sound_requested", {"soundId": 683, "waitForCompletion": false, "source": "classic-shop-identify"}))
		_:
			return ScenarioRuntimeOperationResult.failed(&"unknown_shop_action", "Shop action '%s' is unavailable." % operation)
	var ranges: Array[int] = []
	ranges.assign(service.accept_ranges)
	return ScenarioRuntimeOperationResult.waiting(shop_request(shop, request_id, ranges), continuation, events)

func _resume_temple(continuation: ScenarioRuntimeContinuation, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	var body := response.body as InteractionResponse.TempleBody
	if response.kind != InteractionRequest.TEMPLE or body == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Temple response requires an action.")
	var operation := String(body.action)
	var service := continuation.body as ScenarioRuntimeContinuation.ServiceBody
	var cost_percent := service.cost_percent
	var selected_character_id := service.selected_character_id
	if not body.character_id.is_empty():
		if _game_state.party.character_by_id(body.character_id) == null:
			return ScenarioRuntimeOperationResult.failed(&"unknown_character", "The selected temple character is unavailable.")
		selected_character_id = body.character_id
	var next_continuation := ScenarioRuntimeContinuation.temple(ScenarioRuntimeContinuation.CLASSIC_TEMPLE, cost_percent, service.bank_available, selected_character_id)
	match operation:
		"leave":
			if service.bank_available:
				_rules.economy.pool_to_bank(_game_state.party)
				return ScenarioRuntimeOperationResult.completed(true, [DomainEvent.new(&"temple_closed", {"pooledWealthReturnedToBank": true})])
			if _has_pooled_wealth():
				var prompt := "Pooled wealth remains. Return to the temple to distribute it before leaving?"
				var request := InteractionRequest.yes_no(request_id, prompt, "Return", "Leave it behind")
				return ScenarioRuntimeOperationResult.waiting(request, ScenarioRuntimeContinuation.temple(ScenarioRuntimeContinuation.CLASSIC_TEMPLE_EXIT, cost_percent, false, selected_character_id))
			return ScenarioRuntimeOperationResult.completed(true, [DomainEvent.new(&"temple_closed", {"pooledWealthReturnedToBank": false})])
		"pool":
			var movement_error := _money_movement_context_error()
			if not movement_error.is_empty():
				return ScenarioRuntimeOperationResult.failed(&"invalid_money_context", movement_error)
			var pool_probe := _rules.economy.pool_probe(_game_state.party)
			if not pool_probe.allowed:
				return ScenarioRuntimeOperationResult.failed(&"money_action_unavailable", pool_probe.reason)
			_rules.economy.pool_party_wealth(_game_state.party)
			_recalculate_party_movement()
			return ScenarioRuntimeOperationResult.waiting(temple_request(cost_percent, request_id, selected_character_id), next_continuation, [
				DomainEvent.new(&"wealth_pooled", {"source": "classic-temple"}),
				DomainEvent.new(&"sound_requested", {"soundId": 128, "waitForCompletion": false, "source": "classic-temple-pool"}),
			])
		"share":
			var movement_error := _money_movement_context_error()
			if not movement_error.is_empty():
				return ScenarioRuntimeOperationResult.failed(&"invalid_money_context", movement_error)
			var share_probe := _rules.economy.share_probe(_game_state.party)
			if not share_probe.allowed:
				return ScenarioRuntimeOperationResult.failed(&"money_action_unavailable", share_probe.reason)
			_rules.economy.share_pooled_wealth(_game_state.party)
			_recalculate_party_movement()
			return ScenarioRuntimeOperationResult.waiting(temple_request(cost_percent, request_id, selected_character_id), next_continuation, [
				DomainEvent.new(&"wealth_shared", {"source": "classic-temple", "remaining": _game_state.party.pooled_wealth.to_data()}),
				DomainEvent.new(&"sound_requested", {"soundId": 128, "waitForCompletion": false, "source": "classic-temple-share"}),
			])
		"service":
			return _apply_temple_service(next_continuation, body, request_id)
	return ScenarioRuntimeOperationResult.failed(&"unknown_temple_action", "Temple action '%s' is unavailable." % operation)

func _apply_temple_service(continuation: ScenarioRuntimeContinuation, body: InteractionResponse.TempleBody, request_id: String) -> ScenarioRuntimeOperationResult:
	if body.character_id.is_empty() or body.service_id.is_empty():
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Temple service requires characterId and serviceId.")
	var character := _game_state.party.character_by_id(body.character_id)
	var service_id := StringName(body.service_id)
	if character == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_character", "Temple service target is unavailable.")
	if not TempleRules.SERVICE_IDS.has(service_id):
		return ScenarioRuntimeOperationResult.failed(&"unknown_temple_service", "Temple service '%s' is unavailable." % service_id)
	var service := continuation.body as ScenarioRuntimeContinuation.ServiceBody
	var cost := _rules.temple.service_cost(service_id, service.cost_percent)
	var next_continuation := ScenarioRuntimeContinuation.temple(ScenarioRuntimeContinuation.CLASSIC_TEMPLE, service.cost_percent, service.bank_available, character.id)
	var events: Array[DomainEvent] = [DomainEvent.new(&"sound_requested", {"soundId": 10129, "waitForCompletion": false, "source": "classic-temple-service"})]
	if cost > _game_state.party.pooled_wealth.gold + character.money.gold:
		events.append(DomainEvent.new(&"temple_service_rejected", {"serviceId": String(service_id), "characterId": character.id, "cost": cost, "reason": "insufficient_gold"}))
		return ScenarioRuntimeOperationResult.waiting(temple_request(service.cost_percent, request_id, character.id), next_continuation, events)
	if not _rules.economy.take_from_pool_and_character(_game_state.party, character, cost, WealthState.Kind.GOLD):
		return ScenarioRuntimeOperationResult.failed(&"temple_payment_failed", "Temple payment could not be committed after affordability validation.")
	var result := _rules.temple.apply_service(character, service_id, _rng, _content.item_definitions())
	if result == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_temple_service", "Temple service '%s' is unavailable." % service_id)
	events.append(DomainEvent.new(&"temple_service_completed", result.to_event_data(character.id, cost)))
	return ScenarioRuntimeOperationResult.waiting(temple_request(service.cost_percent, request_id, character.id), next_continuation, events)

func resolve_shop_stock(shop: ShopDefinition, stock_key: String) -> ShopStockResolution:
	if stock_key.begins_with("base:"):
		var index_text := stock_key.trim_prefix("base:")
		if not index_text.is_valid_int():
			return null
		var index := index_text.to_int()
		var item_ids := shop.item_ids()
		if index < 0 or index >= item_ids.size():
			return null
		return ShopStockResolution.new(&"base", index, _content.item_by_id(item_ids[index]), _game_state.shop_quantity(shop, index))
	if stock_key.begins_with("buyback:"):
		var item_id := stock_key.trim_prefix("buyback:")
		var quantity := _game_state.shop_buyback_quantity(shop.id, item_id)
		if quantity < 1:
			return null
		return ShopStockResolution.new(&"buyback", -1, _content.item_by_id(item_id), quantity)
	return null

func _resume_temple_exit(continuation: ScenarioRuntimeContinuation, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	var body := response.body as InteractionResponse.YesNoBody
	if response.kind != InteractionRequest.YES_NO or body == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Temple exit requires a yes/no response.")
	if body.accepted:
		var service := continuation.body as ScenarioRuntimeContinuation.ServiceBody
		return ScenarioRuntimeOperationResult.waiting(
			temple_request(service.cost_percent, request_id, service.selected_character_id),
			ScenarioRuntimeContinuation.temple(ScenarioRuntimeContinuation.CLASSIC_TEMPLE, service.cost_percent, false, service.selected_character_id),
			[DomainEvent.new(&"temple_exit_cancelled", {"reason": "pooled_wealth"})]
		)
	var discarded := _game_state.party.pooled_wealth.to_data()
	_game_state.party.pooled_wealth = WealthState.new()
	return ScenarioRuntimeOperationResult.completed(true, [
		DomainEvent.new(&"pooled_wealth_discarded", {"source": "classic-temple-exit", "wealth": discarded}),
		DomainEvent.new(&"temple_closed", {"pooledWealthReturnedToBank": false}),
	])

func execute(action: ClassicActionDefinition, request_id: String, context: ScenarioExecutionContext) -> ScenarioRuntimeOperationResult:
	match action.opcode:
		-23, 23:
			return _mutate_random_region(action, action.opcode == -23)
		12:
			return _mutate_tile(action)
		13:
			return _mutate_triggers(action)
		20:
			return _move_between_maps(action, false, true)
		29:
			return _acquire_player_map(action, request_id)
		37:
			return _move_between_maps(action, true)
		45:
			return _move_between_maps(action, false, false)
		47:
			var quest_id := absi(action.operand_id)
			if not _game_state.set_quest_value(quest_id, 0 if action.operand_id < 0 else 1):
				return ScenarioRuntimeOperationResult.failed(&"invalid_quest", "Classic opcode 47 references quest %d outside 0 through 99." % quest_id)
			return ScenarioRuntimeOperationResult.completed(_game_state.quest_value(quest_id), [DomainEvent.new(&"quest_changed", {"questId": quest_id, "value": _game_state.quest_value(quest_id)})])
		61:
			return _shift_party(action)
		63:
			return _alter_game_time(action)
		66:
			_game_state.camping_allowed = action.operand_id == 0
			return ScenarioRuntimeOperationResult.completed(_game_state.camping_allowed, [DomainEvent.new(&"camping_availability_changed", {"allowed": _game_state.camping_allowed, "source": "classic"})])
		76:
			return _adjust_quest_value(action)
		101:
			return _back_up_party()
		103:
			return _test_or_set_party_mode(action)
		104:
			_game_state.random_encounters_enabled = action.operand_id != 0
			return ScenarioRuntimeOperationResult.completed(_game_state.random_encounters_enabled, [DomainEvent.new(&"random_encounters_changed", {"enabled": _game_state.random_encounters_enabled})])
		106:
			return _set_map_darkness(action)
	return super.execute(action, request_id, context)

func complex_encounter_request(encounter: ComplexEncounterDefinition, request_id: String) -> InteractionRequest:
	var prompt := _content.message_by_id(absi(encounter.prompt_message_id))
	if prompt == null:
		return null
	var actions: Array[Dictionary] = []
	if encounter.action_result != 0:
		var labels := encounter.action_labels()
		for slot: int in labels.size():
			var label := labels[slot].strip_edges()
			if not label.is_empty() and label != "*":
				actions.append({"id": "choice:%d" % slot, "kind": "choice", "slot": slot, "label": label})
	if encounter.word_result != 0:
		actions.append({"id": "word", "kind": "word", "label": "Speak a word"})
	for spell_id: int in encounter.spell_ids():
		if spell_id != 0:
			actions.append({"id": "spell", "kind": "spell", "label": "Cast a spell"})
			break
	for item_id: int in encounter.item_ids():
		if item_id != 0:
			actions.append({"id": "item", "kind": "item", "label": "Use an item"})
			break
	if encounter.thief:
		var thief_encounter := _content.thief_encounter_by_id(encounter.thief_success)
		if thief_encounter != null:
			actions.append({"id": "thief", "kind": "thief", "label": "Thief action"})
	if encounter.can_back_out:
		actions.append({"id": "back", "kind": "back", "label": "Back out"})
	if actions.is_empty():
		return null
	var characters: Array[Dictionary] = []
	var items: Array[Dictionary] = []
	var spells: Array[Dictionary] = []
	var seen_items: Dictionary = {}
	var seen_spells: Dictionary = {}
	for character: CharacterState in _game_state.party.characters():
		if character.current_health > 0:
			characters.append({"id": character.id, "name": character.name})
		for instance: ItemInstance in character.inventory():
			var item := _content.item_by_id(instance.definition_id)
			if item != null and not seen_items.has(item.classic_id):
				seen_items[item.classic_id] = true
				items.append({"classicItemId": item.classic_id, "name": item.name})
		for spell_id: String in character.known_spells():
			var spell := _content.spell_by_id(spell_id)
			if spell != null and not seen_spells.has(spell.classic_id):
				seen_spells[spell.classic_id] = true
				spells.append({"classicSpellId": spell.classic_id, "name": spell.name})
	return InteractionRequest.from_payload(request_id, &"complex_encounter", {"encounterKind": "complex", "encounterId": encounter.id, "prompt": prompt.text, "actions": actions, "characters": characters, "items": items, "spells": spells, "canBackOut": encounter.can_back_out})

func _request_classic_choice(action: ClassicActionDefinition, request_id: String) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 3 requires a five-value Extra Code row.")
	var yes_id := action.extra_code[3]
	var no_id := action.extra_code[4]
	var yes_label_value: Variant
	var no_label_value: Variant
	if yes_id == 0:
		yes_label_value = "Yes"
		no_label_value = "No"
	else:
		yes_label_value = _classic_choice_label(yes_id)
		no_label_value = _classic_choice_label(no_id)
	if yes_label_value == null or no_label_value == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_option_label", "Classic opcode 3 references an unavailable option label.")
	var request := InteractionRequest.from_payload(request_id, &"yes_no", {"yesId": yes_id, "yesLabel": yes_label_value, "noId": no_id, "noLabel": no_label_value})
	return ScenarioRuntimeOperationResult.waiting(request, ScenarioRuntimeContinuation.classic_choice(action.extra_code, action.gosub))

func _classic_choice_label(label_id: int) -> Variant:
	if _content.has_option_labels():
		var option_label := _content.option_label_by_id(absi(label_id))
		if option_label == null:
			return null
		return option_label.text
	var message := _content.message_by_id(absi(label_id))
	if message == null:
		return null
	return message.text

func _mutate_timed_encounter(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 5:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 54 requires a five-value Extra Code row.")
	var encounter_id := action.extra_code[0]
	var current := _game_state.timed_encounter_override(encounter_id)
	if action.extra_code[1] > -1:
		current["percent"] = action.extra_code[1]
	if action.extra_code[2] > -1:
		current["increment"] = action.extra_code[2]
	if action.extra_code[3] != 0:
		current["day"] = _game_state.clock.day()
	if action.extra_code[4] > -1:
		current["day"] = int(current.get("day", 0)) + action.extra_code[4]
	_game_state.set_timed_encounter_override(encounter_id, current)
	return ScenarioRuntimeOperationResult.completed(current, [DomainEvent.new(&"timed_encounter_changed", {"encounterId": encounter_id, "state": current})])

func execute(action: ClassicActionDefinition, request_id: String, context: ScenarioExecutionContext) -> ScenarioRuntimeOperationResult:
	match action.opcode:
		1:
			return _show_message(action, request_id)
		9:
			return ScenarioRuntimeOperationResult.completed(null, [DomainEvent.new(&"sound_requested", {
				"soundId": absi(action.operand_id),
				"waitForCompletion": action.operand_id < 0,
				"source": "classic",
			})])
		19:
			return _show_random_message(action)
		26:
			return ScenarioRuntimeOperationResult.waiting(
				InteractionRequest.from_payload(request_id, &"acknowledge", {"prompt": "Continue", "soundId": 30005}),
				ScenarioRuntimeContinuation.empty(ScenarioRuntimeContinuation.CLASSIC_ACKNOWLEDGE)
			)
		27:
			return ScenarioRuntimeOperationResult.completed(null, [DomainEvent.new(&"picture_requested", {
				"pictureId": absi(action.operand_id),
				"source": "classic",
			})])
		28:
			return ScenarioRuntimeOperationResult.completed(null, [DomainEvent.new(&"map_redraw_requested", {"source": "classic"})])
		62:
			var scrolling_message := _content.message_by_id(absi(action.operand_id))
			if scrolling_message == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_message", "Classic opcode 62 references unavailable scrolling text %d." % action.operand_id)
			return ScenarioRuntimeOperationResult.completed(scrolling_message.id, [DomainEvent.new(&"scrolling_text_requested", {
				"messageId": scrolling_message.id,
				"text": scrolling_message.text,
				"source": "classic",
			})])
	return super.execute(action, request_id, context)

func _show_message(action: ClassicActionDefinition, request_id: String) -> ScenarioRuntimeOperationResult:
	var message_id := absi(action.operand_id)
	var message := _content.message_by_id(message_id)
	if message == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_message", "Classic opcode 1 references unavailable message %d." % action.operand_id)
	var event := DomainEvent.new(&"message_shown", {"messageId": message_id, "text": message.text, "source": "classic", "classicClick": action.operand_id > 0})
	if action.operand_id <= 0:
		return ScenarioRuntimeOperationResult.completed(null, [event])
	var journal_eligible := GameState.journal_message_id_is_valid(message_id)
	var request := InteractionRequest.from_payload(request_id, &"acknowledge", {
		"prompt": message.text,
		"messageId": message_id,
		"presentation": "classic-textbox",
		"journalEligible": journal_eligible,
		"journalRecorded": journal_eligible and _game_state.journal_message_is_recorded(message_id),
	})
	return ScenarioRuntimeOperationResult.waiting(request, ScenarioRuntimeContinuation.textbox(message_id), [event])

func _show_random_message(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	var message_ids: Array[int] = []
	for value: int in action.extra_code:
		if value != 0 and _content.message_by_id(value) != null:
			message_ids.append(value)
	if message_ids.is_empty() and _content.message_by_id(action.operand_id) != null:
		message_ids.append(action.operand_id)
	if message_ids.is_empty():
		return ScenarioRuntimeOperationResult.failed(&"unknown_message", "Classic opcode 19 has no available message.")
	var selected_id := message_ids[_rng.draw_between(0, message_ids.size() - 1, &"classic.random-message")]
	var message := _content.message_by_id(selected_id)
	return ScenarioRuntimeOperationResult.completed(selected_id, [DomainEvent.new(&"message_shown", {
		"messageId": selected_id,
		"text": message.text,
		"source": "classic-random",
	})])

func _bank_request(request_id: String, selected_character_id: String = "") -> InteractionRequest:
	var characters: Array[Dictionary] = []
	for character: CharacterState in _game_state.party.characters():
		var transfers: Array[Dictionary] = []
		for denomination: String in ["gold", "gems", "jewelry"]:
			var kind := _wealth_kind(denomination)
			var amount := EconomyRules.classic_transfer_increment(kind as WealthState.Kind)
			var to_pool := _rules.economy.transfer_probe(_game_state.party, character, kind as WealthState.Kind, amount, false)
			var to_character := _rules.economy.transfer_probe(_game_state.party, character, kind as WealthState.Kind, amount, true)
			transfers.append({
				"denomination": denomination,
				"amount": amount,
				"toPool": _economy_probe_data(to_pool),
				"toCharacter": _economy_probe_data(to_character),
			})
		characters.append({
			"id": character.id,
			"name": character.name,
			"wealth": character.money.to_data(),
			"load": character.carried_load,
			"maximumLoad": character.maximum_load,
			"transfers": transfers,
		})
	if selected_character_id.is_empty() and not characters.is_empty():
		selected_character_id = String(characters[0]["id"])
	return InteractionRequest.from_payload(request_id, InteractionRequest.BANK, {
		"selectedCharacterId": selected_character_id,
		"pooledWealth": _game_state.party.pooled_wealth.to_data(),
		"bankedWealth": _game_state.party.banked_wealth.to_data(),
		"pool": _economy_probe_data(_rules.economy.pool_probe(_game_state.party)),
		"share": _economy_probe_data(_rules.economy.share_probe(_game_state.party)),
		"characters": characters,
		"actions": ["pool", "share", "to-pool", "to-character", "leave"],
	})

func _resume_banking(continuation: ScenarioRuntimeContinuation, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	var body := response.body as InteractionResponse.BankBody
	if response.kind != InteractionRequest.BANK or body == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Bank response requires an action.")
	var action := String(body.action)
	if action == "leave":
		return ScenarioRuntimeOperationResult.completed(true, [
			DomainEvent.new(&"bank_closed", {"pooledWealthReturnedToBank": false}),
			DomainEvent.new(&"sound_requested", {"soundId": 141, "waitForCompletion": false, "source": "classic-bank-swap-done"}),
		])
	var selected_character_id := body.character_id
	var events: Array[DomainEvent] = []
	match action:
		"pool":
			var movement_error := _money_movement_context_error()
			if not movement_error.is_empty():
				return ScenarioRuntimeOperationResult.failed(&"invalid_money_context", movement_error)
			var probe := _rules.economy.pool_probe(_game_state.party)
			if not probe.allowed:
				return ScenarioRuntimeOperationResult.failed(&"money_action_unavailable", probe.reason)
			_rules.economy.pool_party_wealth(_game_state.party)
			_recalculate_party_movement()
			events.append(DomainEvent.new(&"wealth_pooled", {"source": "classic-bank", "wealth": _game_state.party.pooled_wealth.to_data()}))
			events.append(DomainEvent.new(&"sound_requested", {"soundId": 128, "waitForCompletion": false, "source": "classic-bank-pool"}))
		"share":
			var movement_error := _money_movement_context_error()
			if not movement_error.is_empty():
				return ScenarioRuntimeOperationResult.failed(&"invalid_money_context", movement_error)
			var probe := _rules.economy.share_probe(_game_state.party)
			if not probe.allowed:
				return ScenarioRuntimeOperationResult.failed(&"money_action_unavailable", probe.reason)
			_rules.economy.share_pooled_wealth(_game_state.party)
			_recalculate_party_movement()
			events.append(DomainEvent.new(&"wealth_shared", {"source": "classic-bank", "remaining": _game_state.party.pooled_wealth.to_data()}))
			events.append(DomainEvent.new(&"sound_requested", {"soundId": 128, "waitForCompletion": false, "source": "classic-bank-share"}))
		"to-pool", "to-character":
			if body.character_id.is_empty() or body.denomination.is_empty() or body.amount < 1:
				return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Bank-backed Swap requires character, denomination, and amount.")
			var movement_error := _money_movement_context_error()
			if not movement_error.is_empty():
				return ScenarioRuntimeOperationResult.failed(&"invalid_money_context", movement_error)
			var character := _game_state.party.character_by_id(body.character_id)
			var kind := _wealth_kind(body.denomination)
			var amount := body.amount
			if character == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_character", "The selected bank character is unavailable.")
			if kind < 0:
				return ScenarioRuntimeOperationResult.failed(&"unknown_wealth_kind", "The selected bank denomination is unavailable.")
			if amount != EconomyRules.classic_transfer_increment(kind as WealthState.Kind):
				return ScenarioRuntimeOperationResult.failed(&"invalid_money_increment", "Classic Swap moves five gold or one gem or jewelry per action.")
			var to_character := action == "to-character"
			var probe := _rules.economy.transfer_probe(_game_state.party, character, kind as WealthState.Kind, amount, to_character)
			if not probe.allowed:
				return ScenarioRuntimeOperationResult.failed(&"money_action_unavailable", probe.reason)
			var transferred := _rules.economy.transfer_pool_to_character(_game_state.party, character, kind as WealthState.Kind, amount) if to_character else _rules.economy.transfer_character_to_pool(_game_state.party, character, kind as WealthState.Kind, amount)
			if not transferred:
				return ScenarioRuntimeOperationResult.failed(&"money_action_unavailable", "The selected bank transfer is no longer available.")
			_recalculate_party_movement()
			events.append(DomainEvent.new(&"wealth_transferred", {"source": "classic-bank", "characterId": character.id, "direction": action, "kind": body.denomination, "amount": amount}))
			events.append(DomainEvent.new(&"sound_requested", {"soundId": 10051 if to_character else 663, "waitForCompletion": false, "source": "classic-bank-swap"}))
		_:
			return ScenarioRuntimeOperationResult.failed(&"unknown_bank_action", "Bank action '%s' is unavailable." % action)
	return ScenarioRuntimeOperationResult.waiting(_bank_request(request_id, selected_character_id), continuation, events)

func _advance_reward_spells(reward: ClassicRewardState, request_id: String, events: Array[DomainEvent] = []) -> ScenarioRuntimeOperationResult:
	if reward.spell_index >= reward.spell_character_ids().size():
		return _complete_reward(reward, request_id, events)
	return _wait_for_reward(reward, request_id, events)

func _money_movement_context_error() -> String:
	for character: CharacterState in _game_state.party.characters():
		if _content.race_by_id(character.race_id) == null or _content.caste_by_id(character.caste_id) == null:
			return "Character '%s' has no package-backed race or class for Classic movement recalculation." % character.id
	return ""

func _apply_trap(encounter: ComplexEncounterDefinition, thief: ThiefEncounterDefinition, gosub: bool, selected: CharacterState, request_id: String, encounter_attempt: int) -> ScenarioRuntimeOperationResult:
	var flags := _state.thief_encounter_type_flags(thief)
	flags[9] = false
	flags[1] = false
	flags[6] = true
	_state.set_thief_encounter_type_flags(thief, flags)
	var targets: Array[CharacterState] = [selected] if flags[8] else _state.party.characters()
	var damage_by_character: Dictionary = {}
	if thief.low_damage != 0 and thief.high_damage >= thief.low_damage:
		for target: CharacterState in targets:
			var damage := _rng.draw_between(thief.low_damage, thief.high_damage, &"classic.thief-trap-damage")
			target.current_health = _rules.arithmetic.signed_16(target.current_health - damage)
			damage_by_character[target.id] = damage
	var prompts := thief.prompts()
	var trap_sound := prompts[1] if prompts.size() > 1 else 0
	var spell_power := prompts[2] if prompts.size() > 2 else 0
	var events: Array[DomainEvent] = [DomainEvent.new(&"thief_trap_sprung", {"encounterId": encounter.id, "thiefEncounterId": thief.id, "characterId": selected.id, "targetIds": targets.map(func(value: CharacterState) -> String: return value.id), "damageByCharacter": damage_by_character, "spellId": thief.spell_id, "spellPower": spell_power, "soundId": trap_sound})]
	return _wait_for_thief(encounter, gosub, request_id, events, encounter_attempt)

func _wait_for_thief(encounter: ComplexEncounterDefinition, gosub: bool, request_id: String, events: Array[DomainEvent], encounter_attempt: int) -> ScenarioRuntimeOperationResult:
	var request := _thief_request(encounter, request_id, false)
	if request == null:
		return ScenarioRuntimeOperationResult.failed(&"party_defeated", "No living party character remains for the Thief Encounter.")
	return ScenarioRuntimeOperationResult.waiting(request, ScenarioRuntimeContinuation.thief_encounter(encounter.id, gosub, encounter_attempt), events)

func _thief_request(encounter: ComplexEncounterDefinition, request_id: String, play_opening_sound: bool) -> InteractionRequest:
	var thief := _thief_definition(encounter)
	if thief == null:
		return null
	var prompt_id := absi(thief.prompts()[0]) if not thief.prompts().is_empty() else 0
	var message := _content.message_by_id(prompt_id)
	var flags := _state.thief_encounter_type_flags(thief)
	var characters: Array[Dictionary] = []
	for character: CharacterState in _state.party.characters():
		if not _character_eligible(character):
			continue
		var actions: Array[Dictionary] = []
		for index: int in ClassicPickLockRulesScript.ACTION_LABELS.size():
			var ability := character.ability_value(ClassicPickLockRulesScript.ability_index(index))
			var value := ability + thief.modifiers()[index] if ability != 0 else 0
			var enabled := _action_available(character, thief, flags, index)
			var reason := "" if enabled else "This action is no longer available." if not flags[index] else "This character lacks the required ability." if ability == 0 else "The authored modifier reduces this action below zero."
			actions.append({"index": index, "label": ClassicPickLockRulesScript.action_label(index), "value": value, "enabled": enabled, "reason": reason})
		characters.append({"id": character.id, "name": character.name, "portraitId": character.portrait_id, "actions": actions})
	var sounds := thief.prompt_sounds()
	var opening_sound := sounds[0] if play_opening_sound and not sounds.is_empty() else 0
	return InteractionRequest.from_payload(request_id, InteractionRequest.THIEF_ENCOUNTER, {"encounterId": encounter.id, "prompt": message.text if message != null else "Choose a thief action.", "soundId": opening_sound, "characters": characters}) if not characters.is_empty() else null

static func _action_available(character: CharacterState, thief: ThiefEncounterDefinition, flags: Array[bool], action_index: int) -> bool:
	var ability_index := ClassicPickLockRulesScript.ability_index(action_index)
	var ability := character.ability_value(ability_index)
	return ability_index >= 0 and flags.size() == 10 and flags[action_index] and ability != 0 and ability + thief.modifiers()[action_index] > 0

static func _action_event(encounter: ComplexEncounterDefinition, thief: ThiefEncounterDefinition, character: CharacterState, action_index: int, chance: int, succeeded: bool) -> DomainEvent:
	var text_ids := thief.success_text() if succeeded else thief.failure_text()
	var sound_ids := thief.success_sounds() if succeeded else thief.failure_sounds()
	return DomainEvent.new(&"thief_action_resolved", {"encounterId": encounter.id, "thiefEncounterId": thief.id, "characterId": character.id, "actionIndex": action_index, "chancePercent": chance, "succeeded": succeeded, "messageId": absi(text_ids[action_index]), "signedMessageId": text_ids[action_index], "classicClick": text_ids[action_index] > 0, "soundId": sound_ids[action_index]})

func _wait_for_trap_message(encounter: ComplexEncounterDefinition, gosub: bool, character: CharacterState, action_index: int, succeeded: bool, request_id: String, events: Array[DomainEvent] = [], encounter_attempt: int = 0) -> ScenarioRuntimeOperationResult:
	# Castle uses application STR# class 3, item 55 here, not scenario Data SD2.
	# Rebuilt preserves that identity while using concise modern host wording.
	var request := InteractionRequest.from_payload(request_id, InteractionRequest.ACKNOWLEDGE, {"prompt": "A trap is sprung.", "presentation": "classic-textbox"})
	events.append(DomainEvent.new(&"thief_trap_warning", {"resourceStringClass": 3, "resourceStringId": 55}))
	return ScenarioRuntimeOperationResult.waiting(request, ScenarioRuntimeContinuation.thief_resolution(encounter.id, gosub, action_index, character.id, &"trap-message", succeeded, true, encounter_attempt), events) if request != null else ScenarioRuntimeOperationResult.failed(&"invalid_thief_encounter", "Thief Encounter trap could not create its textbox stage.")

func _configure_temple(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if not _game_state.set_active_temple(action.operand_id):
		return ScenarioRuntimeOperationResult.failed(&"invalid_temple_cost", "Classic opcode 32 temple cost is outside signed 16-bit range.")
	return ScenarioRuntimeOperationResult.completed(action.operand_id, [
		DomainEvent.new(&"temple_available", {"costPercent": action.operand_id}),
		DomainEvent.new(&"sound_requested", {"soundId": 10105, "waitForCompletion": false, "source": "classic-temple-offer"}),
	])

func _reward_spell_request(reward: ClassicRewardState, request_id: String) -> InteractionRequest:
	var ids := reward.spell_character_ids()
	if reward.spell_index < 0 or reward.spell_index >= ids.size():
		return null
	var character := _game_state.party.character_by_id(ids[reward.spell_index])
	var caste: CasteDefinition = null if character == null else _content.caste_by_id(character.caste_id)
	if character == null or caste == null:
		return null
	var spells: Array[Dictionary] = []
	for spell: SpellDefinition in _reward_spell_candidates(character, caste):
		spells.append({"id": spell.id, "name": spell.name, "classicId": spell.classic_id, "cost": _rules.characters.spell_selection_cost(spell), "selected": character.known_spells().has(spell.id)})
	return InteractionRequest.from_payload(request_id, InteractionRequest.LEVEL_UP, {"mode": "spell-selection", "prompt": "Choose the spells this character knows.", "characterId": character.id, "characterName": character.name, "pointTotal": _rules.characters.spell_selection_total(character, caste), "spells": spells})

func _resume_reward_spells(reward: ClassicRewardState, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	var ids := reward.spell_character_ids()
	var body := response.body as InteractionResponse.LevelUpBody
	if response.kind != InteractionRequest.LEVEL_UP or body == null or body.action != &"confirm-spells" or reward.spell_index < 0 or reward.spell_index >= ids.size() or body.character_id != ids[reward.spell_index]:
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Spell selection requires the pending character and spell IDs.")
	var character := _game_state.party.character_by_id(ids[reward.spell_index])
	var caste: CasteDefinition = null if character == null else _content.caste_by_id(character.caste_id)
	if character == null or caste == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_reward_progression", "The spell-selection character is unavailable.")
	var candidates: Dictionary = {}
	for spell: SpellDefinition in _reward_spell_candidates(character, caste):
		candidates[spell.id] = spell
	var selected: Array[String] = []
	var spent := 0
	for value: String in body.spell_ids:
		if selected.has(value) or not candidates.has(value):
			return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "The selected spell list contains an unavailable or duplicate spell.")
		selected.append(value)
		spent += _rules.characters.spell_selection_cost(candidates[value])
	var total := _rules.characters.spell_selection_total(character, caste)
	if spent > total:
		return ScenarioRuntimeOperationResult.failed(&"spell_selection_budget_exceeded", "The selected spells exceed the Classic point budget.")
	character.set_known_spells(selected)
	reward.spell_index += 1
	return _advance_reward_spells(reward, request_id, [DomainEvent.new(&"level_spells_selected", {"characterId": character.id, "spellIds": selected, "pointsRemaining": total - spent})])

func _reward_spell_candidates(character: CharacterState, caste: CasteDefinition) -> Array[SpellDefinition]:
	var result: Array[SpellDefinition] = []
	var maximum_level := _rules.characters.maximum_spell_selection_level(caste)
	for spell: SpellDefinition in _content.spell_definitions():
		if int(float(spell.classic_id) / 1000.0) == character.spellcaster_type and spell.classic_tier() >= 0 and spell.classic_tier() < maximum_level and spell.classic_slot() >= 1 and spell.classic_slot() <= 12:
			result.append(spell)
	result.sort_custom(func(left: SpellDefinition, right: SpellDefinition) -> bool: return left.classic_id < right.classic_id)
	return result

func _complete_reward(reward: ClassicRewardState, request_id: String, events: Array[DomainEvent] = []) -> ScenarioRuntimeOperationResult:
	var completed_events: Array[DomainEvent] = []
	completed_events.assign(events)
	completed_events.append(DomainEvent.new(&"reward_completed", {"origin": String(reward.origin), "sourceId": reward.source_id, "experienceByCharacter": reward.experience_awards()}))
	if reward.origin == &"battle":
		if _game_state.combat == null or _game_state.combat.battle_id != reward.source_id or not _game_state.combat.rewards_started:
			return ScenarioRuntimeOperationResult.failed(&"invalid_battle_continuation", "The battle reward no longer matches its completed battle.")
		var combat := _game_state.combat
		if reward.battle_stage == ClassicRewardState.ORDINARY_BATTLE_STAGE and reward.bonus_treasure_classic_id != 0:
			var bonus_treasure := _content.treasure_by_classic_id(reward.bonus_treasure_classic_id)
			if bonus_treasure == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_treasure", "The pending opcode 48 bonus treasure is unavailable.")
			var bonus_roll := _rules.economy.roll_treasure(bonus_treasure, _rng)
			completed_events.append(DomainEvent.new(&"battle_bonus_reward_started", {"battleId": combat.battle_id, "treasureId": bonus_treasure.id, "classicTreasureId": reward.bonus_treasure_classic_id}))
			var bonus := _begin_reward(&"battle", combat.battle_id, bonus_roll.experience, bonus_roll.wealth, bonus_roll.item_ids, request_id, ClassicRewardState.BONUS_BATTLE_STAGE)
			bonus.events = completed_events + bonus.events
			return bonus
		combat.rewards_completed = true
		var outcome := combat.outcome
		var battle := _content.battle_by_id(reward.source_id)
		if battle != null:
			_append_battle_after_message(battle, completed_events)
		completed_events.append(DomainEvent.new(&"battle_returned", {"battleId": reward.source_id, "outcome": String(outcome)}))
		# The completed battle remains session-owned through every ally, fumble,
		# treasure, level, and spell boundary. Release it only after the terminal
		# reward transaction has committed so both direct and VM callers return once.
		_game_state.combat = null
	return ScenarioRuntimeOperationResult.completed(reward.source_id, completed_events)

func _money_movement_context_error() -> String:
	for character: CharacterState in _game_state.party.characters():
		if _content.race_by_id(character.race_id) == null or _content.caste_by_id(character.caste_id) == null:
			return "Character '%s' has no package-backed race or class for Classic movement recalculation." % character.id
	return ""

func _recalculate_party_movement() -> void:
	for character: CharacterState in _game_state.party.characters():
		var race := _content.race_by_id(character.race_id)
		var caste := _content.caste_by_id(character.caste_id)
		_rules.characters.recalculate_movement(character, race, caste.movement_bonus)

func grant_item(character_id: String, item_id: String, identified: bool) -> ScenarioRuntimeOperationResult:
	var character := _game_state.party.character_by_id(character_id)
	var item := _content.item_by_id(item_id)
	if character == null or item == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_item_target", "Grant Item references an unavailable character or item.")
	var instance := _rules.inventory.add_item(character, item, _game_state.next_instance_id("scenario.item"), identified)
	if instance == null:
		return ScenarioRuntimeOperationResult.failed(&"inventory_full", "The character cannot carry the granted item.")
	return ScenarioRuntimeOperationResult.completed(instance.id, [DomainEvent.new(&"item_granted", {"characterId": character.id, "itemId": item.id, "instanceId": instance.id, "identified": identified})])

func _reward_state_is_valid(reward: ClassicRewardState) -> bool:
	if reward.source_id.is_empty() or reward.origin not in [&"scenario", &"battle"]:
		return false
	if reward.origin == &"battle" and (_game_state.combat == null or not _game_state.combat.completed or not _game_state.combat.rewards_started or _game_state.combat.rewards_completed or _game_state.combat.battle_id != reward.source_id):
		return false
	if (reward.origin == &"battle" and reward.battle_stage not in [ClassicRewardState.ORDINARY_BATTLE_STAGE, ClassicRewardState.BONUS_BATTLE_STAGE]) or (reward.origin != &"battle" and (reward.battle_stage != ClassicRewardState.NO_BATTLE_STAGE or reward.bonus_treasure_classic_id != 0)) or (reward.battle_stage == ClassicRewardState.BONUS_BATTLE_STAGE and reward.bonus_treasure_classic_id != 0):
		return false
	if reward.bonus_treasure_classic_id != 0 and _content.treasure_by_classic_id(reward.bonus_treasure_classic_id) == null:
		return false
	for item: ItemInstance in reward.items():
		if _content.item_by_id(item.definition_id) == null:
			return false
	for character_id: Variant in reward.experience_awards():
		if _game_state.party.character_by_id(String(character_id)) == null:
			return false
	for character_id: String in reward.level_character_ids():
		if _game_state.party.character_by_id(character_id) == null:
			return false
	for character_id: String in reward.spell_character_ids():
		if _game_state.party.character_by_id(character_id) == null:
			return false
	if not reward.pending_level_result.is_empty() and _game_state.party.character_by_id(String(reward.pending_level_result.get("characterId", ""))) == null:
		return false
	return true

func trace() -> Array[Dictionary]:
	var ordered: Array[Dictionary] = []
	for offset: int in _trace.size():
		ordered.append(_trace[(_trace_start + offset) % _trace.size()].duplicate(true))
	return ordered

func _init(initial_seed: int = 1, trace_limit: int = DEFAULT_TRACE_LIMIT) -> void:
	_state = _normalize_seed(initial_seed)
	_trace_limit = trace_limit if trace_limit >= 0 else UNLIMITED_TRACE

func draw(range_max: int, semantic_tag: StringName) -> int:
	if range_max <= 0 or range_max > 32_767:
		push_error("RealmzRng range must be between 1 and 32767.")
		return 0
	return _draw_scaled(range_max, semantic_tag)

func draw_classic(range_value: int, semantic_tag: StringName) -> int:
	if range_value < -32_768 or range_value > 32_767:
		push_error("Castle Rand range must fit a signed 16-bit value.")
		return 0
	return _draw_scaled(range_value, semantic_tag)

func _draw_scaled(range_value: int, semantic_tag: StringName) -> int:
	var raw: int = _next_raw()
	var positive_raw: int = -raw if raw < 0 else raw
	# C integer division truncates toward zero for Castle's signed Rand parameter.
	var result: int = 1 + int(float(positive_raw * range_value) / float(RAW_SCALE))
	_append_trace({
		"drawIndex": _draw_count,
		"tag": String(semantic_tag),
		"range": range_value,
		"raw": raw,
		"result": result,
	})
	_draw_count += 1
	return result

func _latest_trace_entry() -> Dictionary:
	if _trace.is_empty():
		return {}
	var index := (_trace_start + _trace.size() - 1) % _trace.size()
	return _trace[index]

func _next_raw() -> int:
	_state = (_state * MULTIPLIER) % MODULUS
	var low_word: int = _state & 0xffff
	if low_word == 0x8000:
		return 0
	if low_word >= 0x8000:
		return low_word - 0x10000
	return low_word

func draw_between(low: int, high: int, semantic_tag: StringName) -> int:
	if high < low or high - low + 1 > 32_767:
		push_error("RealmzRng inclusive range is invalid.")
		return low
	var result := draw(high - low + 1, semantic_tag) - 1 + low
	var latest := _latest_trace_entry()
	if not latest.is_empty():
		latest["low"] = low
		latest["high"] = high
		latest["result"] = result
	return result

func _append_trace(entry: Dictionary) -> void:
	if _trace_limit == 0:
		return
	if _trace_limit < 0 or _trace.size() < _trace_limit:
		_trace.append(entry)
		return
	_trace[_trace_start] = entry
	_trace_start = (_trace_start + 1) % _trace_limit

func _next_raw() -> int:
	if _script_index >= _scripted_values.size():
		push_error("ScriptedRng exhausted its fixture values.")
		return 0
	var raw: int = _scripted_values[_script_index]
	_script_index += 1
	if raw < -32_767 or raw > 32_767:
		push_error("ScriptedRng values must match QuickDraw's signed 16-bit output contract.")
		return 0
	return raw

func _restore_source_position(value: Variant) -> bool:
	if not value is int or value < 0 or value > _scripted_values.size():
		return false
	_script_index = value
	return true

func checkpoint() -> Dictionary:
	return {
		"generatorState": _state,
		"drawCount": _draw_count,
		"trace": trace(),
		"sourcePosition": _source_position(),
	}

func rollback(checkpoint_data: Dictionary) -> bool:
	if not checkpoint_data.has("generatorState") or not checkpoint_data.has("drawCount") or not checkpoint_data.has("trace") or not checkpoint_data.has("sourcePosition"):
		return false
	var generator_state := int(checkpoint_data["generatorState"])
	var draw_count := int(checkpoint_data["drawCount"])
	var trace_value: Variant = checkpoint_data["trace"]
	if generator_state <= 0 or generator_state >= MODULUS or draw_count < 0 or not trace_value is Array or (_trace_limit >= 0 and trace_value.size() > _trace_limit):
		return false
	var restored_trace: Array[Dictionary] = []
	for entry: Variant in trace_value:
		if not entry is Dictionary:
			return false
		restored_trace.append((entry as Dictionary).duplicate(true))
	if not _restore_source_position(checkpoint_data["sourcePosition"]):
		return false
	_state = generator_state
	_draw_count = draw_count
	_trace = restored_trace
	_trace_start = 0
	return true

func adjacent_actor_ids(battlefield: BattlefieldState, actor_id: String, anchor_override: Vector2i = Vector2i(-1, -1)) -> Array[String]:
	var result: Array[String] = []
	if battlefield == null or not battlefield.has_actor(actor_id):
		return result
	var anchor := battlefield.actor_position(actor_id) if anchor_override.x < 0 else anchor_override
	var actor_cells := battlefield.actor_footprint_at(actor_id, anchor)
	for candidate_id: String in battlefield.actor_ids():
		if candidate_id == actor_id:
			continue
		if _footprints_are_adjacent(actor_cells, battlefield.actor_footprint(candidate_id)):
			result.append(candidate_id)
	return result

func _decorate_land(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, rng: RealmzRng) -> String:
	for y: int in range(2, 88):
		for x: int in range(2, 88):
			var coordinate := Vector2i(x, y)
			var bottom := terrain_set.tile_by_id(battlefield.terrain_at(coordinate))
			var top := terrain_set.tile_by_id(battlefield.terrain_at(coordinate + Vector2i.UP))
			if bottom == null or top == null:
				return "Land battle terrain references an unavailable effective mapstats tile."
			if bottom.forest != 0:
				# Castle combatmap.c uses bottom.ispath in both sums. Preserve that observable
				# draw branch until a named fidelity decision adjudicates the apparent typo.
				var bottom_blocked := bottom.solid + int(bottom.shore) + bottom.need_boat + int(bottom.blocks_los) + int(bottom.is_path)
				var top_blocked := top.solid + int(top.shore) + top.need_boat + int(top.blocks_los) + int(bottom.is_path)
				if bottom_blocked == 0 and top_blocked == 0:
					_decorate_forest_cell(battlefield, coordinate, bottom.forest, terrain_set.base_tile, rng)
				else:
					battlefield.set_terrain(coordinate, terrain_set.base_tile)
			elif battlefield.terrain_at(coordinate) == terrain_set.base_tile:
				_decorate_rubble_cell(battlefield, coordinate, terrain_set.landlook, rng)
	return ""

func place_character(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, actor_id: String, party_index: int, formation: Dictionary) -> bool:
	if battlefield == null or terrain_set == null or actor_id.is_empty() or party_index < 0 or formation.is_empty():
		return false
	var quotient := int(float(party_index) / 3.0)
	var horizontal_sign := int(formation.get("horizontalSign", -1))
	var vertical_sign := int(formation.get("verticalSign", 1))
	var base := Vector2i.ZERO
	if bool(formation.get("swapAxes", false)):
		base = Vector2i(quotient * horizontal_sign, party_index - 3 * absi(quotient) + absi(quotient) * vertical_sign)
	else:
		base = Vector2i(party_index - 3 * absi(quotient) + absi(quotient) * horizontal_sign, quotient * vertical_sign)
	var coordinate := _find_character_cell(battlefield, terrain_set, base)
	return coordinate.x >= 0 and battlefield.place_character(actor_id, coordinate)

func find_monster_position(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, desired_local: Vector2i, size: int) -> Vector2i:
	if battlefield == null or terrain_set == null or size < 0 or size > 3:
		return Vector2i(-1, -1)
	var center := battlefield.party_anchor + desired_local
	for radius: int in range(1, _maximum_useful_radius(center) + 1):
		var start := -radius
		var stop := radius
		for vertical_offset: int in range(start, stop):
			for horizontal_offset: int in range(start, stop):
				# Earlier radii already proved the interior illegal. Skipping those
				# repeated probes preserves this radius's row-major first candidate.
				if not _is_new_radius_edge(horizontal_offset, vertical_offset, radius):
					continue
				var candidate := center + Vector2i(horizontal_offset, vertical_offset)
				if _monster_position_is_legal(battlefield, terrain_set, candidate, size):
					return candidate
	return Vector2i(-1, -1)

func place_monster(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, actor_id: String, desired_local: Vector2i, size: int) -> bool:
	var coordinate := find_monster_position(battlefield, terrain_set, desired_local, size)
	return coordinate.x >= 0 and battlefield.place_monster(actor_id, coordinate, size)

func _find_character_cell(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, base_local: Vector2i) -> Vector2i:
	var center := battlefield.party_anchor + base_local
	for radius: int in range(1, _maximum_useful_radius(center) + 1):
		for vertical_offset: int in range(-radius, radius):
			for horizontal_offset: int in range(-radius, radius):
				if not _is_new_radius_edge(horizontal_offset, vertical_offset, radius):
					continue
				var candidate := center + Vector2i(horizontal_offset, vertical_offset)
				if not _inside_good_rect(candidate) or battlefield.is_occupied(candidate):
					continue
				var terrain := terrain_set.tile_by_id(battlefield.terrain_at(candidate))
				if terrain != null and terrain.solid == 0:
					return candidate
	return Vector2i(-1, -1)

func _monster_position_is_legal(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, anchor: Vector2i, size: int) -> bool:
	if not _inside_good_rect(anchor):
		return false
	var footprint := BattlefieldState.footprint_cells(anchor, size)
	for coordinate: Vector2i in footprint:
		if not BattlefieldState.contains(coordinate) or battlefield.is_occupied(coordinate):
			return false
		var terrain := terrain_set.tile_by_id(battlefield.terrain_at(coordinate))
		if terrain == null:
			return false
		if coordinate == anchor:
			if size == 0 and terrain.solid != 0 or terrain.solid == 2:
				return false
		elif terrain.solid > 1:
			return false
	return true

func _land_build(map_id: String, cell: MapCell, world_state: WorldState, terrain_set: BattleTerrainSetDefinition) -> Array:
	var tile := _effective_land_tile(map_id, cell, world_state)
	if tile <= 0 or tile >= 201:
		tile = terrain_set.base_tile
	var definition := terrain_set.tile_by_id(tile)
	if definition == null:
		return []
	return definition.combat_build()

func _dungeon_build(cell: MapCell) -> Array:
	var floor_in_battle := cell.terrain_id != "classic.dungeon.wall"
	for feature: MapFeature in cell.features():
		if feature.kind in [&"door", &"stairs", &"secret", &"no-wall-in-battle"]:
			floor_in_battle = true
			break
	var tile := DUNGEON_FLOOR_TILE if floor_in_battle else DUNGEON_WALL_TILE
	return [[tile, tile, tile], [tile, tile, tile], [tile, tile, tile]]

func build_terrain(map: MapDefinition, world_state: WorldState, terrain_set: BattleTerrainSetDefinition, party_coordinate: Vector2i, rng: RealmzRng) -> BattlefieldBuildResult:
	if map == null or world_state == null or terrain_set == null or rng == null:
		return BattlefieldBuildResult.failed(&"invalid_battlefield_input", "Battlefield generation requires a map, overlays, terrain catalog, and session randomness.")
	if map.topology.width < SOURCE_SIZE or map.topology.height < SOURCE_SIZE:
		return BattlefieldBuildResult.failed(&"battlefield_map_too_small", "Map '%s' cannot provide Castle's 30 by 30 battle source window." % map.id)
	if map.level_type == &"land" and terrain_set.landlook != map.landlook or map.level_type == &"dungeon" and terrain_set.landlook != -1:
		return BattlefieldBuildResult.failed(&"battlefield_terrain_mismatch", "Map '%s' references a battle terrain catalog for a different Classic map type." % map.id)
	var requested_origin := party_coordinate - Vector2i(15, 15)
	var source_origin := Vector2i(
		clampi(requested_origin.x, 0, map.topology.width - SOURCE_SIZE),
		clampi(requested_origin.y, 0, map.topology.height - SOURCE_SIZE)
	)
	var map_shift := (requested_origin - source_origin) * SCALE
	var tiles: Array[int] = []
	tiles.resize(BattlefieldState.CELL_COUNT)
	tiles.fill(terrain_set.base_tile if map.level_type == &"land" else DUNGEON_FLOOR_TILE)
	var battlefield := BattlefieldState.new(map.id, tiles, source_origin, map_shift)
	for source_y: int in SOURCE_SIZE:
		for source_x: int in SOURCE_SIZE:
			var cell := map.topology.effective_cell_at(source_origin + Vector2i(source_x, source_y), world_state)
			if cell == null:
				return BattlefieldBuildResult.failed(&"battlefield_missing_cell", "Map '%s' is missing a cell inside Castle's battle source window." % map.id)
			var build: Array = _dungeon_build(cell) if map.level_type == &"dungeon" else _land_build(map.id, cell, world_state, terrain_set)
			if build.is_empty():
				return BattlefieldBuildResult.failed(&"battlefield_missing_build", "Map '%s' cannot resolve battle terrain for cell %s." % [map.id, cell.coordinate])
			for sub_y: int in SCALE:
				for sub_x: int in SCALE:
					battlefield.set_terrain(Vector2i(source_x * SCALE + sub_x, source_y * SCALE + sub_y), int(build[sub_y][sub_x]))
	var decoration_error := _decorate_dungeon(battlefield, terrain_set, rng) if map.level_type == &"dungeon" else _decorate_land(battlefield, terrain_set, rng)
	if not decoration_error.is_empty():
		return BattlefieldBuildResult.failed(&"battlefield_decoration_failed", decoration_error)
	return BattlefieldBuildResult.succeeded(battlefield)

func roll_formation(battlefield: BattlefieldState, battle: BattleDefinition, rng: RealmzRng) -> Dictionary:
	if battlefield == null or battle == null or rng == null:
		return {}
	var direction := rng.draw(360, &"battle.setup.direction")
	var distance := rng.draw_classic(battle.distance, &"battle.setup.distance")
	var degree := float(direction) / 57.3
	var monster_origin := Vector2i(int(cos(degree) * float(distance) - 5.0), int(sin(degree) * float(distance) - 5.0))
	var swap_axes := direction < 45 or direction > 315 or direction > 135 and direction < 225
	var vertical_sign := -1 if direction < 180 else 1
	var horizontal_sign := 1 if direction > 90 and direction < 270 else -1
	battlefield.direction_degrees = direction
	battlefield.rolled_distance = distance
	return {
		"monsterOrigin": monster_origin,
		"swapAxes": swap_axes,
		"verticalSign": vertical_sign,
		"horizontalSign": horizontal_sign,
	}

func _decorate_forest_cell(battlefield: BattlefieldState, coordinate: Vector2i, forest: int, base_tile: int, rng: RealmzRng) -> void:
	var top_coordinate := coordinate + Vector2i.UP
	match forest:
		1:
			if rng.draw(100, &"battle.terrain.forest-primary") < 20:
				var bottom_tile := 200 + rng.draw_between(67, 71, &"battle.terrain.forest-tile")
				battlefield.set_terrain(coordinate, bottom_tile)
				battlefield.set_terrain(top_coordinate, bottom_tile - 6 if not _between(battlefield.terrain_at(top_coordinate), 267, 271) else 266)
			elif rng.draw(100, &"battle.terrain.forest-secondary") < 10:
				battlefield.set_terrain(coordinate, 200 + rng.draw_between(81, 91, &"battle.terrain.forest-rubble"))
			else:
				battlefield.set_terrain(coordinate, base_tile)
		2:
			if rng.draw(100, &"battle.terrain.forest-primary") < 20:
				battlefield.set_terrain(coordinate, 200 + rng.draw_between(107, 111, &"battle.terrain.forest-tile"))
				battlefield.set_terrain(top_coordinate, 200 + rng.draw_between(101, 105, &"battle.terrain.forest-top") if not _between(battlefield.terrain_at(top_coordinate), 307, 311) else 306)
			elif rng.draw(100, &"battle.terrain.forest-secondary") < 10:
				battlefield.set_terrain(coordinate, 200 + rng.draw_between(121, 131, &"battle.terrain.forest-rubble"))
			else:
				battlefield.set_terrain(coordinate, base_tile)
		3:
			if rng.draw(100, &"battle.terrain.forest-primary") < 20 and not _between(battlefield.terrain_at(top_coordinate), 273, 280):
				var bottom_tile := 200 + rng.draw_between(77, 80, &"battle.terrain.forest-tile")
				battlefield.set_terrain(coordinate, bottom_tile)
				battlefield.set_terrain(top_coordinate, bottom_tile - 4)
			elif rng.draw(100, &"battle.terrain.forest-secondary") < 10:
				battlefield.set_terrain(coordinate, 200 + rng.draw_between(92, 100, &"battle.terrain.forest-rubble"))
			else:
				battlefield.set_terrain(coordinate, base_tile)
		4:
			if rng.draw(100, &"battle.terrain.forest-primary") < 20 and not _between(battlefield.terrain_at(top_coordinate), 381, 391):
				var bottom_tile := 200 + rng.draw_between(186, 190, &"battle.terrain.forest-tile")
				battlefield.set_terrain(coordinate, bottom_tile)
				if not _between(battlefield.terrain_at(top_coordinate), 307, 311):
					battlefield.set_terrain(top_coordinate, bottom_tile - 5)
			elif rng.draw(100, &"battle.terrain.forest-secondary") < 10:
				battlefield.set_terrain(coordinate, 200 + rng.draw_between(159, 171, &"battle.terrain.forest-rubble"))
			else:
				battlefield.set_terrain(coordinate, base_tile)
		5:
			if rng.draw(100, &"battle.terrain.forest-primary") < 20 and not _between(battlefield.terrain_at(top_coordinate), 391, 400):
				var bottom_tile := 200 + rng.draw_between(196, 200, &"battle.terrain.forest-tile")
				battlefield.set_terrain(coordinate, bottom_tile)
				if not _between(battlefield.terrain_at(top_coordinate), 317, 321):
					battlefield.set_terrain(top_coordinate, bottom_tile - 5)
			elif rng.draw(100, &"battle.terrain.forest-secondary") < 10:
				battlefield.set_terrain(coordinate, 200 + rng.draw_between(172, 180, &"battle.terrain.forest-rubble"))
			else:
				battlefield.set_terrain(coordinate, base_tile)

static func _effective_land_tile(map_id: String, cell: MapCell, world_state: WorldState) -> int:
	var terrain_id := world_state.terrain_for(map_id, cell)
	var prefix := "classic.terrain."
	if terrain_id.begins_with(prefix):
		var suffix := terrain_id.trim_prefix(prefix)
		if suffix.is_valid_int():
			return int(suffix)
	return cell.render_tile

static func _maximum_useful_radius(center: Vector2i) -> int:
	var required := maxi(
		maxi(absi(GOOD_MINIMUM - center.x), absi((GOOD_MAXIMUM_EXCLUSIVE - 1) - center.x)),
		maxi(absi(GOOD_MINIMUM - center.y), absi((GOOD_MAXIMUM_EXCLUSIVE - 1) - center.y))
	) + 2
	return mini(required, MAX_SEARCH_RADIUS)

func _decorate_dungeon(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, rng: RealmzRng) -> String:
	for y: int in range(2, 88):
		for x: int in range(2, 88):
			var coordinate := Vector2i(x, y)
			var roll := rng.draw(100, &"battle.terrain.dungeon-rubble-chance")
			var definition := terrain_set.tile_by_id(battlefield.terrain_at(coordinate))
			if definition == null:
				return "Dungeon battle terrain references an unavailable Combat Data BD tile."
			if roll < 10 and definition.solid == 0:
				battlefield.set_terrain(coordinate, 200 + rng.draw_between(141, 158, &"battle.terrain.dungeon-rubble-tile"))
	return ""

func classic_range(battlefield: BattlefieldState, first_actor_id: String, second_actor_id: String) -> int:
	if battlefield == null or first_actor_id == second_actor_id or not battlefield.has_actor(first_actor_id) or not battlefield.has_actor(second_actor_id):
		return -1
	# getrange.c measures actor anchors and stores sqrt() in a short, truncating
	# the Euclidean distance before comparing it with the spell range.
	return floori(Vector2(battlefield.actor_position(second_actor_id) - battlefield.actor_position(first_actor_id)).length())

func classic_coordinate_range(battlefield: BattlefieldState, actor_id: String, destination: Vector2i) -> int:
	if battlefield == null or not battlefield.has_actor(actor_id) or not BattlefieldState.contains(destination):
		return -1
	return floori(Vector2(destination - battlefield.actor_position(actor_id)).length())

func projectile_target_is_valid(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, first_actor_id: String, second_actor_id: String, maximum_range: int, require_line_of_sight: bool = true) -> bool:
	var distance := classic_range(battlefield, first_actor_id, second_actor_id)
	return distance >= 0 and distance <= maximum_range and (not require_line_of_sight or has_line_of_sight(battlefield, terrain_set, first_actor_id, second_actor_id))

func coordinate_target_is_valid(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, actor_id: String, destination: Vector2i, maximum_range: int, require_line_of_sight: bool = true) -> bool:
	var distance := classic_coordinate_range(battlefield, actor_id, destination)
	return distance >= 0 and distance <= maximum_range and (not require_line_of_sight or has_line_of_sight_to_coordinate(battlefield, terrain_set, actor_id, destination))

func has_line_of_sight(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, from_actor_id: String, to_actor_id: String) -> bool:
	if battlefield == null or terrain_set == null or not battlefield.has_actor(from_actor_id) or not battlefield.has_actor(to_actor_id):
		return false
	return has_line_of_sight_to_coordinate(battlefield, terrain_set, from_actor_id, battlefield.actor_position(to_actor_id))

func has_line_of_sight_to_coordinate(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, from_actor_id: String, destination: Vector2i) -> bool:
	if battlefield == null or terrain_set == null or not battlefield.has_actor(from_actor_id) or not BattlefieldState.contains(destination):
		return false
	var occupied_cells: Dictionary = {}
	for actor_id: String in battlefield.actor_ids():
		for coordinate: Vector2i in battlefield.actor_footprint(actor_id):
			occupied_cells[coordinate] = true
	var origin := battlefield.actor_position(from_actor_id)
	var part := Vector2(origin * 32)
	var step := Vector2(destination - origin) * 32.0 / 128.0
	# FD-COMBAT-008 retains Castle's 128 center-offset samples but removes the
	# animation-delay term from the divisor. Presentation speed cannot alter AI.
	for _sample: int in 128:
		var coordinate := Vector2i(floori((part.x + 16.0) / 32.0), floori((part.y + 16.0) / 32.0))
		if not BattlefieldState.contains(coordinate):
			return false
		# Castle's field contains actor IDs, so occupied cells do not expose their
		# underlying terrain to cansee(). Preserve that observable distinction.
		if not occupied_cells.has(coordinate):
			var terrain := terrain_set.tile_by_id(battlefield.terrain_at(coordinate))
			if terrain == null or terrain.blocks_los:
				return false
		part += step
	return true

func _probe_step_with_cost_floor(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, actor_id: String, direction: Vector2i, movement_available: int, cost_floor: int, anchor_override: Vector2i = Vector2i(-1, -1), ignore_occupants: bool = false) -> BattlefieldStepResult:
	if battlefield == null or terrain_set == null or not battlefield.has_actor(actor_id):
		return BattlefieldStepResult.blocked(&"invalid_actor")
	if direction == Vector2i.ZERO or absi(direction.x) > 1 or absi(direction.y) > 1:
		return BattlefieldStepResult.blocked(&"invalid_direction")
	var destination := (battlefield.actor_position(actor_id) if anchor_override.x < 0 else anchor_override) + direction
	var footprint := battlefield.actor_footprint_at(actor_id, destination)
	if footprint.is_empty():
		return BattlefieldStepResult.blocked(&"invalid_actor", destination)
	var maximum_cost := maxi(0, cost_floor)
	for coordinate: Vector2i in footprint:
		if not BattlefieldState.contains(coordinate):
			return _blocked_with_cost(&"outside_battlefield", destination, maximum_cost)
		var occupant := battlefield.actor_at(coordinate, actor_id)
		if not ignore_occupants and not occupant.is_empty():
			return _blocked_with_cost(&"occupied", destination, maximum_cost, occupant)
		var terrain := terrain_set.tile_by_id(battlefield.terrain_at(coordinate))
		if terrain == null:
			return _blocked_with_cost(&"missing_terrain", destination, maximum_cost)
		var size := battlefield.actor_size(actor_id)
		if size == 0 and terrain.solid != 0 or size > 0 and terrain.solid > 1:
			return _blocked_with_cost(&"solid_terrain", destination, maximum_cost)
		maximum_cost = maxi(maximum_cost, _movement_cost(terrain, direction))
	if maximum_cost > movement_available:
		var result := BattlefieldStepResult.blocked(&"insufficient_movement", destination)
		result.movement_cost = maximum_cost
		return result
	return BattlefieldStepResult.permitted(destination, maximum_cost)

func probe_monster_step_toward(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, actor_id: String, target: Vector2i, movement_available: int, rng: RealmzRng) -> BattlefieldStepResult:
	if battlefield == null or terrain_set == null or rng == null or not battlefield.has_actor(actor_id):
		return BattlefieldStepResult.blocked(&"invalid_actor")
	var origin := battlefield.actor_position(actor_id)
	var direction := Vector2i(signi(target.x - origin.x), signi(target.y - origin.y))
	var maximum_cost := 0
	for attempt: int in 21:
		var probe := _probe_step_with_cost_floor(battlefield, terrain_set, actor_id, direction, movement_available, maximum_cost)
		maximum_cost = maxi(maximum_cost, probe.movement_cost)
		if probe.allowed:
			return probe
		direction = _shift_monster_direction(origin, target, direction, rng, actor_id, attempt)
	var blocked := BattlefieldStepResult.blocked(&"monster_path_blocked", origin)
	blocked.movement_cost = maximum_cost
	return blocked

func probe_path_step_toward_actors(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, actor_id: String, target_ids: Array[String], movement_available: int) -> BattlefieldStepResult:
	if battlefield == null or terrain_set == null or not battlefield.has_actor(actor_id):
		return BattlefieldStepResult.blocked(&"invalid_actor")
	var valid_targets: Array[String] = []
	for target_id: String in target_ids:
		if target_id != actor_id and battlefield.has_actor(target_id) and not valid_targets.has(target_id):
			valid_targets.append(target_id)
	if valid_targets.is_empty():
		return BattlefieldStepResult.blocked(&"invalid_actor")
	var origin := battlefield.actor_position(actor_id)
	var actor_size := battlefield.actor_size(actor_id)
	var target_cells: Dictionary = {}
	for target_id: String in valid_targets:
		for coordinate: Vector2i in battlefield.actor_footprint(target_id):
			target_cells[coordinate] = true
	var goals := _route_goal_anchors(target_cells, actor_size)
	var origin_index := _route_index(origin)
	if goals[origin_index] != 0:
		return BattlefieldStepResult.blocked(&"already_adjacent", origin)
	var occupied_cells: Dictionary = {}
	for candidate_id: String in battlefield.actor_ids():
		if candidate_id == actor_id:
			continue
		for coordinate: Vector2i in battlefield.actor_footprint(candidate_id):
			occupied_cells[coordinate] = true
	var heuristics := _route_heuristics(goals)
	var distances := PackedInt32Array()
	distances.resize(BattlefieldState.CELL_COUNT)
	distances.fill(0x3fff_ffff)
	distances[origin_index] = 0
	var first_steps := PackedInt32Array()
	first_steps.resize(BattlefieldState.CELL_COUNT)
	first_steps.fill(-1)
	var closed := PackedByteArray()
	closed.resize(BattlefieldState.CELL_COUNT)
	var heap: Array[Vector4i] = []
	var sequence := 0
	_route_heap_push(heap, Vector4i(heuristics[origin_index], heuristics[origin_index], sequence, origin_index))
	while not heap.is_empty():
		var current := _route_heap_pop(heap)
		var current_index := current.w
		if closed[current_index] != 0:
			continue
		closed[current_index] = 1
		if goals[current_index] != 0:
			var first_step := _route_coordinate(first_steps[current_index])
			return _probe_step_with_cost_floor(battlefield, terrain_set, actor_id, first_step - origin, movement_available, 0)
		var anchor := _route_coordinate(current_index)
		for direction: Vector2i in DIRECTIONS:
			# Only the immediate step must respect current actors. Later route cells
			# are a wall-following forecast: mobile combatants may vacate them before
			# this actor reaches them, while terrain remains authoritative.
			var destination := anchor + direction
			if not BattlefieldState.contains(destination):
				continue
			var destination_index := _route_index(destination)
			if closed[destination_index] != 0:
				continue
			var footprint := BattlefieldState.footprint_cells(destination, actor_size)
			if not _route_footprint_is_passable(battlefield, terrain_set, actor_size, footprint, occupied_cells, anchor == origin):
				continue
			var next_distance := distances[current_index] + 1
			if next_distance >= distances[destination_index]:
				continue
			distances[destination_index] = next_distance
			first_steps[destination_index] = destination_index if current_index == origin_index else first_steps[current_index]
			sequence += 1
			_route_heap_push(heap, Vector4i(next_distance + heuristics[destination_index], heuristics[destination_index], sequence, destination_index))
	return BattlefieldStepResult.blocked(&"path_not_found", origin)

static func _route_footprint_is_passable(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, actor_size: int, footprint: Array[Vector2i], occupied_cells: Dictionary, respect_occupants: bool) -> bool:
	for coordinate: Vector2i in footprint:
		if not BattlefieldState.contains(coordinate) or respect_occupants and occupied_cells.has(coordinate):
			return false
		var terrain := terrain_set.tile_by_id(battlefield.terrain_at(coordinate))
		if terrain == null or actor_size == 0 and terrain.solid != 0 or actor_size > 0 and terrain.solid > 1:
			return false
	return true

static func _route_goal_anchors(target_cells: Dictionary, actor_size: int) -> PackedByteArray:
	var result := PackedByteArray()
	result.resize(BattlefieldState.CELL_COUNT)
	var offsets := BattlefieldState.footprint_cells(Vector2i.ZERO, actor_size)
	for value: Variant in target_cells:
		var target_cell: Vector2i = value
		for direction: Vector2i in DIRECTIONS:
			for offset: Vector2i in offsets:
				var anchor := target_cell - direction - offset
				if BattlefieldState.contains(anchor):
					result[_route_index(anchor)] = 1
	return result

static func _route_heuristics(goals: PackedByteArray) -> PackedInt32Array:
	var result := PackedInt32Array()
	result.resize(BattlefieldState.CELL_COUNT)
	result.fill(0x3fff_ffff)
	var queue := PackedInt32Array()
	queue.resize(BattlefieldState.CELL_COUNT)
	var cursor := 0
	var count := 0
	for index: int in BattlefieldState.CELL_COUNT:
		if goals[index] != 0:
			result[index] = 0
			queue[count] = index
			count += 1
	while cursor < count:
		var index := queue[cursor]
		cursor += 1
		var coordinate := _route_coordinate(index)
		for direction: Vector2i in DIRECTIONS:
			var neighbor := coordinate + direction
			if not BattlefieldState.contains(neighbor):
				continue
			var neighbor_index := _route_index(neighbor)
			if result[neighbor_index] <= result[index] + 1:
				continue
			result[neighbor_index] = result[index] + 1
			queue[count] = neighbor_index
			count += 1
	return result

func probe_monster_step_away(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, actor_id: String, target: Vector2i, movement_available: int, rng: RealmzRng) -> BattlefieldStepResult:
	if battlefield == null or not battlefield.has_actor(actor_id):
		return BattlefieldStepResult.blocked(&"invalid_actor")
	var origin := battlefield.actor_position(actor_id)
	return probe_monster_step_toward(battlefield, terrain_set, actor_id, origin * 2 - target, movement_available, rng)

func are_adjacent(battlefield: BattlefieldState, first_actor_id: String, second_actor_id: String) -> bool:
	if battlefield == null or first_actor_id == second_actor_id:
		return false
	return _footprints_are_adjacent(battlefield.actor_footprint(first_actor_id), battlefield.actor_footprint(second_actor_id))

static func _shift_monster_direction(origin: Vector2i, target: Vector2i, direction: Vector2i, rng: RealmzRng, actor_id: String, attempt: int) -> Vector2i:
	var result := direction
	var net_x := absi(target.x - origin.x)
	var net_y := absi(target.y - origin.y)
	var tag_prefix := "combat.monster-shift.%s.%d" % [actor_id, attempt]
	if net_x > net_y:
		if result.y != 0 and rng.draw(2, StringName(tag_prefix + ".drop-y")) == 1:
			result.y = 0
		else:
			result.y = -1
			var y_roll := rng.draw(3, StringName(tag_prefix + ".y"))
			if y_roll == 1:
				result.y = 1
			elif y_roll == 2:
				result.y = 0
			var x_roll := rng.draw(3, StringName(tag_prefix + ".x"))
			if x_roll == 1:
				result.x = -1
			elif x_roll == 2:
				result.x = 1
			if x_roll == 3 and result.y != 0:
				result.x = 0
			else:
				result.x = -1 if rng.draw(2, StringName(tag_prefix + ".x-sign")) == 1 else 1
	else:
		if result.x != 0:
			result.x = 0
		else:
			result.x = -1
			var x_roll := rng.draw(3, StringName(tag_prefix + ".x"))
			if x_roll == 1:
				result.x = 1
			elif x_roll == 2:
				result.x = 0
			result.y = -1
			var y_roll := rng.draw(3, StringName(tag_prefix + ".y"))
			if y_roll == 1:
				result.y = -1
			elif y_roll == 2:
				result.y = 1
			elif y_roll == 3:
				result.y = 0
	return result

static func _footprints_are_adjacent(first: Array[Vector2i], second: Array[Vector2i]) -> bool:
	if first.is_empty() or second.is_empty():
		return false
	for first_cell: Vector2i in first:
		for second_cell: Vector2i in second:
			var delta := second_cell - first_cell
			if delta != Vector2i.ZERO and absi(delta.x) <= 1 and absi(delta.y) <= 1:
				return true
	return false

static func _movement_cost(terrain: BattleTerrainTileDefinition, direction: Vector2i) -> int:
	var cost := maxi(0, floori(float(terrain.movement_time) / 2.0) - 1)
	if direction.x != 0:
		cost += 1
	if direction.y != 0:
		cost += 1
	return cost

func visible_icon_id(identified: bool) -> int:
	if identified or icon_id <= 0:
		return icon_id
	for icon_range: Vector3i in UNIDENTIFIED_ICON_RANGES:
		if icon_id >= icon_range.x and icon_id <= icon_range.y:
			return icon_range.z
	return icon_id

func _init(message_id: int, message_text: String) -> void:
	id = message_id
	text = message_text

static func selected_placed_trigger_ids(content: RealmzContent, cell: MapCell) -> Array[String]:
	var selected_id := ""
	var selected_record_index := 2_147_483_647
	for trigger_id: String in cell.trigger_ids():
		var trigger := content.trigger_by_id(trigger_id)
		if trigger != null and trigger.classic_record_index < selected_record_index:
			selected_id = trigger.id
			selected_record_index = trigger.classic_record_index
	var selected_ids: Array[String] = []
	if not selected_id.is_empty():
		selected_ids.append(selected_id)
	return selected_ids

static func set_location_note(context: SessionWorkflowContext, text: String) -> SessionWorkflowResult:
	var map := context.content.world.map_by_id(context.state.party.map_id)
	if map == null or map.topology.cell_at(context.state.party.coordinate) == null:
		return SessionWorkflowResult.failed(&"location_note_unavailable", "The current map location is unavailable.")
	if not LocationNoteState.text_is_valid(text):
		return SessionWorkflowResult.failed(&"location_note_too_long", "Classic location notes are limited to 255 encoded bytes.")
	var existing := context.state.world.location_note_at(map.id, context.state.party.coordinate)
	var darkness_value := _current_location_note_darkness(context, map)
	if existing == null and not text.is_empty() and context.state.world.next_location_note_ordinal(map.level_type) < 0:
		return SessionWorkflowResult.failed(&"location_note_capacity", "The Classic location-note file for this map type is full.")
	if existing != null and existing.text == text and existing.darkness_value == darkness_value or existing == null and text.is_empty():
		return SessionWorkflowResult.failed(&"location_note_unchanged", "Change or clear the current location note before saving.")
	var committed := false
	if text.is_empty():
		committed = context.state.world.remove_location_note(map.id, context.state.party.coordinate)
	else:
		var ordinal := existing.record_ordinal if existing != null else context.state.world.next_location_note_ordinal(map.level_type)
		committed = context.state.world.upsert_location_note(LocationNoteState.new(map.id, map.level_type, map.level_index, context.state.party.coordinate, text, darkness_value, ordinal))
	if not committed:
		return SessionWorkflowResult.failed(&"invalid_location_note", "The location note could not be committed.")
	var event_kind: StringName = &"location_note_removed" if text.is_empty() else &"location_note_updated"
	return SessionWorkflowResult.completed([DomainEvent.new(event_kind, {
		"mapId": map.id,
		"x": context.state.party.coordinate.x,
		"y": context.state.party.coordinate.y,
		"textBytes": text.to_utf8_buffer().size(),
		"source": "classic",
	})])

static func _current_location_note_darkness(context: SessionWorkflowContext, map: MapDefinition) -> int:
	if map == null or map.level_type == &"dungeon" or not context.state.world.map_is_dark(map):
		return 0
	return clampi(int(context.state.party.conditions.value(0) / 30) + 1, 1, 255)

