static func set_fast_spell(context: SessionWorkflowContext, payload: PlayerIntent.SpellPayload) -> SessionWorkflowResult:
	if context.state.combat != null and not context.state.combat.completed:
		return SessionWorkflowResult.failed(&"fast_spell_binding_in_battle", "Fast Spell bindings cannot be changed during battle.")
	var character := context.state.party.character_by_id(payload.caster_id)
	if character == null or payload.scroll_slot < 0 or payload.scroll_slot >= 10:
		return SessionWorkflowResult.failed(&"invalid_fast_spell_slot", "The selected Fast Spell slot is unavailable.")
	if payload.spell_id.is_empty():
		if not character.clear_fast_spell(payload.scroll_slot):
			return SessionWorkflowResult.failed(&"fast_spell_binding_failed", "The Fast Spell slot could not be cleared.")
		return SessionWorkflowResult.completed([DomainEvent.new(&"fast_spell_changed", {"characterId": character.id, "slot": payload.scroll_slot, "spellId": "", "power": 0, "source": "classic"})])
	var spell := context.content.spell_by_id(payload.spell_id)
	if spell == null or not character.known_spells().has(spell.id):
		return SessionWorkflowResult.failed(&"invalid_fast_spell", "Fast Spells must reference a spell known by this character.")
	if payload.power < 1 or payload.power > 7 or spell.cost < 0 and payload.power != 1:
		return SessionWorkflowResult.failed(&"invalid_fast_spell_power", "The selected spell does not support that Fast Spell power.")
	if not character.bind_fast_spell(payload.scroll_slot, spell.id, payload.power):
		return SessionWorkflowResult.failed(&"fast_spell_binding_failed", "The Fast Spell binding could not be committed.")
	return SessionWorkflowResult.completed([DomainEvent.new(&"fast_spell_changed", {"characterId": character.id, "slot": payload.scroll_slot, "spellId": spell.id, "power": payload.power, "source": "classic"})])

static func classic_torch_item(context: SessionWorkflowContext) -> Array[String]:
	var torch := context.content.item_by_classic_id(805)
	if torch == null:
		return []
	for character: CharacterState in context.state.party.characters():
		for instance: ItemInstance in character.inventory():
			if instance.definition_id == torch.id:
				return [character.id, instance.id]
	return []

static func classic_torch_probe(context: SessionWorkflowContext) -> InventoryActionProbe:
	var identity := classic_torch_item(context)
	if identity.is_empty():
		return InventoryActionProbe.block("The party carries no usable torch.")
	var character := context.state.party.character_by_id(identity[0])
	var instance := _item_instance(character, identity[1])
	var item: ItemDefinition = null if instance == null else context.content.item_by_id(instance.definition_id)
	var spell: SpellDefinition = null if item == null else context.content.spell_by_classic_id(item.special_2)
	return field_spell_item_probe(context, character, instance, item, spell)

static func begin_field_scroll(context: SessionWorkflowContext, payload: PlayerIntent.SpellPayload, request_revision: int) -> MagicTransitionResult:
	var character := context.state.party.character_by_id(payload.caster_id)
	var scroll := character.scroll_at(payload.scroll_slot) if character != null else null
	var spell := context.content.spell_by_id(scroll.spell_id) if scroll != null and not scroll.is_empty() else null
	var probe := scroll_use_probe(context, character, payload.scroll_slot, spell)
	if not probe.allowed:
		return MagicTransitionResult.failed(&"scroll_unavailable", probe.reason)
	var target_ids := field_spell_target_ids(context, character, spell, payload.target_ids, payload.target_id)
	var required_count := field_spell_target_count(context, spell, scroll.power)
	if target_ids.size() == required_count:
		return MagicTransitionResult.committed(commit_field_scroll(context, character.id, payload.scroll_slot, spell.id, scroll.power, target_ids), true)
	if not target_ids.is_empty():
		return MagicTransitionResult.failed(&"invalid_scroll_target", "The scroll requires exactly %d valid party target%s." % [required_count, "" if required_count == 1 else "s"])
	var targeting := SessionContinuation.TargetingBody.new()
	targeting.character_id = character.id
	targeting.scroll_slot = payload.scroll_slot
	targeting.spell_id = spell.id
	targeting.power = scroll.power
	targeting.target_count = required_count
	var continuation := SessionContinuation.targeting_selection(&"scroll-target-selection", targeting)
	var interaction := scroll_target_request("session.scroll:%s:%d:%d" % [character.id, payload.scroll_slot, request_revision], character, payload.scroll_slot, spell, scroll.power, required_count, context.state.party.characters())
	return MagicTransitionResult.waiting(continuation, interaction, [DomainEvent.new(&"scroll_target_requested", {"characterId": character.id, "slot": payload.scroll_slot, "spellId": spell.id, "power": scroll.power, "targetCount": required_count, "source": "classic"})])

static func resume_field_scroll(context: SessionWorkflowContext, targeting: SessionContinuation.TargetingBody, target_ids: Array[String]) -> MagicTransitionResult:
	if targeting == null:
		return MagicTransitionResult.failed(&"invalid_session_continuation", "The scroll target continuation is unavailable.")
	if target_ids.size() != targeting.target_count:
		return MagicTransitionResult.failed(&"invalid_scroll_target", "The scroll requires exactly %d target%s." % [targeting.target_count, "" if targeting.target_count == 1 else "s"])
	var character := context.state.party.character_by_id(targeting.character_id)
	var scroll := character.scroll_at(targeting.scroll_slot) if character != null else null
	if scroll == null or scroll.spell_id != targeting.spell_id or scroll.power != targeting.power:
		return MagicTransitionResult.failed(&"invalid_session_continuation", "The scroll awaiting a target no longer matches its committed state.")
	return MagicTransitionResult.committed(commit_field_scroll(context, targeting.character_id, targeting.scroll_slot, targeting.spell_id, targeting.power, target_ids), true)

static func commit_field_scroll(context: SessionWorkflowContext, character_id: String, slot_index: int, spell_id: String, power: int, requested_target_ids: Array[String]) -> SessionWorkflowResult:
	var character := context.state.party.character_by_id(character_id)
	var spell := context.content.spell_by_id(spell_id)
	var probe := scroll_use_probe(context, character, slot_index, spell)
	if not probe.allowed:
		return SessionWorkflowResult.failed(&"scroll_unavailable", probe.reason)
	var selected_value: Variant = _selected_party_targets(context.state.party, requested_target_ids)
	if selected_value == null:
		return SessionWorkflowResult.failed(&"invalid_scroll_target", "The scroll target selection contains an unavailable or duplicate character.")
	if (selected_value as Dictionary).size() != field_spell_target_count(context, spell, power):
		return SessionWorkflowResult.failed(&"invalid_scroll_target", "The scroll target selection has the wrong number of characters.")
	var selected: Dictionary = selected_value
	var targets := _ordered_party_targets(context.state.party, selected)
	var castes: Array[CasteDefinition] = []
	var races: Array[RaceDefinition] = []
	for target: CharacterState in targets:
		castes.append(context.content.caste_by_id(target.caste_id))
		races.append(context.content.race_by_id(target.race_id))
	var allow_empty := spell.target_type == 7 or absi(spell.special) == 68
	var resolution := context.rules.magic.resolve_field_spell(character, targets, spell, power, context.rng, castes, races, false, allow_empty)
	if resolution == null or not resolution.cast:
		return SessionWorkflowResult.failed(&"scroll_spell_failed", "The scroll spell could not be resolved.")
	if not character.clear_scroll(slot_index):
		return SessionWorkflowResult.failed(&"scroll_commit_failed", "The resolved scroll could not be removed from its case.")
	var events: Array[DomainEvent] = [DomainEvent.new(&"scroll_used", {"characterId": character.id, "slot": slot_index, "spellId": spell.id, "power": power, "source": "classic"})]
	_append_field_spell_events(context, events, character, spell, power, resolution, &"classic-scroll", &"classic-scroll", &"scroll_spell_resolved")
	return SessionWorkflowResult.completed(events)

static func field_spell_probe(context: SessionWorkflowContext, character: CharacterState, spell: SpellDefinition, power: int) -> InventoryActionProbe:
	if character == null or spell == null or not character.known_spells().has(spell.id):
		return InventoryActionProbe.block("The character does not know that spell.")
	if context.state.character_spellcasting_blocked:
		return InventoryActionProbe.block("Classic scenario state currently blocks character spellcasting.")
	if character.current_health < 1 or character.spell_points < 1:
		return InventoryActionProbe.block("The character cannot cast in their current state.")
	for condition: int in [ConditionRules.CONFUSED, ConditionRules.SILENCED, ConditionRules.HELPLESS, ConditionRules.STUPID, ConditionRules.ANIMATED]:
		if character.conditions.is_active(condition):
			return InventoryActionProbe.block("The character's current Classic condition prevents spellcasting.")
	if not spell.in_camp:
		return InventoryActionProbe.block("This spell cannot be cast outside battle.")
	if power < 1 or power > 7 or spell.cost < 0 and power != 1:
		return InventoryActionProbe.block("This spell does not support the selected power level.")
	if character.spell_points < absi(spell.cost * power):
		return InventoryActionProbe.block("The character does not have enough spell points.")
	if spell.target_type < 0 or spell.target_type > 12:
		return InventoryActionProbe.block("This spell has an invalid Classic field target type.")
	if spell.target_type in [3, 7, 9] and not context.state.party.allies().is_empty():
		return InventoryActionProbe.block("This spell also targets allied creatures; that Classic field branch is not implemented yet.")
	if not field_spell_effect_supported(spell):
		return InventoryActionProbe.block("This spell's Classic field effect is not implemented yet.")
	return InventoryActionProbe.permit()

static func begin_adventure(context: SessionWorkflowContext, pending: bool) -> SessionWorkflowResult:
	if context.state.party_setup_completed or pending:
		return SessionWorkflowResult.failed(&"party_setup_closed", "Party setup is no longer active.")
	if context.state.character_draft != null:
		return SessionWorkflowResult.failed(&"character_draft_active", "Finish or cancel the character currently being created before beginning.")
	var characters := context.state.party.characters()
	if characters.is_empty():
		return SessionWorkflowResult.failed(&"empty_party", "Add or import at least one character before beginning.")
	var aggregate_error := _aggregate_party_level_error(context, characters)
	if not aggregate_error.is_empty():
		return SessionWorkflowResult.failed(&"party_level_limit_exceeded", aggregate_error)
	context.state.experience_multiplier = party_experience_multiplier(characters, context.state.difficulty, context.content.campaign_definition())
	context.state.party_setup_completed = true
	var character_ids: Array[String] = []
	for character: CharacterState in characters:
		character_ids.append(character.id)
	return SessionWorkflowResult.completed([DomainEvent.new(&"party_created", {"characterIds": character_ids})])

static func party_has_classic_item(context: SessionWorkflowContext, classic_item_id: int) -> bool:
	var definition := context.content.item_by_classic_id(classic_item_id)
	if definition == null:
		return false
	for character: CharacterState in context.state.party.characters():
		for item: ItemInstance in character.inventory():
			if item.definition_id == definition.id:
				return true
	return false

static func timed_encounter_requirements_met(context: SessionWorkflowContext, encounter: TimedEncounterDefinition, map: MapDefinition, exploration: SessionContinuation.ExplorationBody) -> bool:
	if encounter.required_item_id > 0 and not party_has_classic_item(context, encounter.required_item_id):
		return false
	if encounter.required_quest_id > -1 and not context.state.quest_is_set(encounter.required_quest_id):
		return false
	if encounter.location_kind == TimedEncounterDefinition.LocationKind.ANY:
		return true
	if encounter.location_kind == TimedEncounterDefinition.LocationKind.LAND and map.level_type != &"land" or encounter.location_kind == TimedEncounterDefinition.LocationKind.DUNGEON and map.level_type != &"dungeon":
		return false
	if map.level_index != encounter.required_level or exploration == null:
		return false
	var coordinate := exploration.timed_check_coordinate
	if encounter.required_random_rectangle > -1:
		var region := map.random_region_by_index(encounter.required_random_rectangle)
		if region == null or not region.bounds.has_point(coordinate):
			return false
	if encounter.required_x > -1 and coordinate.x != encounter.required_x:
		return false
	if encounter.required_y > -1 and coordinate.y != encounter.required_y:
		return false
	return true

static func trade_item(context: SessionWorkflowContext, payload: PlayerIntent.ItemActionPayload) -> SessionWorkflowResult:
	var source := context.state.party.character_by_id(payload.actor_id)
	var destination := context.state.party.character_by_id(payload.destination_character_id)
	var instance := _item_instance(source, payload.item_id)
	var definition: ItemDefinition = null if instance == null else context.content.item_by_id(instance.definition_id)
	if source == null or destination == null or instance == null or definition == null:
		return SessionWorkflowResult.failed(&"invalid_item_trade", "Trade requires a carried item and two current party members.")
	var probe := context.rules.inventory.trade_classic(source, destination, instance, definition)
	if not probe.allowed:
		return SessionWorkflowResult.failed(&"item_cannot_trade", probe.reason)
	return SessionWorkflowResult.completed([DomainEvent.new(&"item_traded", {"fromCharacterId": source.id, "toCharacterId": destination.id, "instanceId": instance.id, "itemId": definition.id})])

static func begin_field_spell_item(context: SessionWorkflowContext, actor_id: String, instance_id: String, requested_target: String, requested_targets: Array[String], request_revision: int) -> MagicTransitionResult:
	var character := context.state.party.character_by_id(actor_id)
	if character == null:
		character = item_owner(context, instance_id)
	var instance := _item_instance(character, instance_id)
	var item: ItemDefinition = null if instance == null else context.content.item_by_id(instance.definition_id)
	var spell: SpellDefinition = null if item == null else context.content.spell_by_classic_id(item.special_2)
	var probe := field_spell_item_probe(context, character, instance, item, spell)
	if not probe.allowed:
		return MagicTransitionResult.failed(item_use_error_code(instance, item, spell), probe.reason)
	var power := absi(item.special_1)
	var random_power_checkpoint: Dictionary = {}
	if power == 8:
		random_power_checkpoint = context.rng.checkpoint()
		power = context.rng.draw(7, StringName("item.use.power.%s" % instance.id))
	var target_ids := field_item_target_ids(context, character, spell, requested_targets, requested_target)
	var required_count := field_item_target_count(context, spell, power)
	if target_ids.size() == required_count:
		var committed := MagicTransitionResult.committed(commit_field_spell_item(context, character.id, instance.id, spell.id, power, target_ids))
		if not committed.ok and not random_power_checkpoint.is_empty():
			context.rng.rollback(random_power_checkpoint)
		return committed
	if not target_ids.is_empty():
		if not random_power_checkpoint.is_empty():
			context.rng.rollback(random_power_checkpoint)
		return MagicTransitionResult.failed(&"invalid_item_use_target", "The item requires exactly %d valid party target%s." % [required_count, "" if required_count == 1 else "s"])
	var targeting := SessionContinuation.TargetingBody.new()
	targeting.character_id = character.id
	targeting.instance_id = instance.id
	targeting.spell_id = spell.id
	targeting.power = power
	targeting.target_count = required_count
	targeting.starting_charges = instance.charges
	var continuation := SessionContinuation.targeting_selection(&"item-use-target-selection", targeting)
	var interaction := item_target_request("session.item-use:%s:%d" % [instance.id, request_revision], character, instance.id, item, spell, power, required_count, context.state.party.characters())
	return MagicTransitionResult.waiting(continuation, interaction, [DomainEvent.new(&"item_target_requested", {"characterId": character.id, "instanceId": instance.id, "itemId": item.id, "spellId": spell.id, "power": power, "targetCount": required_count, "source": "classic"})])

static func commit_field_spell_item(context: SessionWorkflowContext, character_id: String, instance_id: String, spell_id: String, power: int, requested_target_ids: Array[String]) -> SessionWorkflowResult:
	var character := context.state.party.character_by_id(character_id)
	var instance := _item_instance(character, instance_id)
	var item: ItemDefinition = null if instance == null else context.content.item_by_id(instance.definition_id)
	var spell := context.content.spell_by_id(spell_id)
	var probe := field_spell_item_probe(context, character, instance, item, spell)
	if not probe.allowed:
		return SessionWorkflowResult.failed(item_use_error_code(instance, item, spell), probe.reason)
	var selected_value: Variant = _selected_party_targets(context.state.party, requested_target_ids)
	if selected_value == null:
		return SessionWorkflowResult.failed(&"invalid_item_use_target", "The item target selection contains an unavailable or duplicate character.")
	if (selected_value as Dictionary).size() != field_item_target_count(context, spell, power):
		return SessionWorkflowResult.failed(&"invalid_item_use_target", "The item target selection has the wrong number of characters.")
	var selected: Dictionary = selected_value
	var targets := _ordered_party_targets(context.state.party, selected)
	if targets.size() != selected.size():
		return SessionWorkflowResult.failed(&"invalid_item_use_target", "The item target selection is unavailable.")
	if not context.rules.inventory.use_charge(character, instance.id, item):
		return SessionWorkflowResult.failed(&"item_charge_commit_failed", "The validated item charge could not be committed.")
	var castes: Array[CasteDefinition] = []
	var races: Array[RaceDefinition] = []
	for target: CharacterState in targets:
		castes.append(context.content.caste_by_id(target.caste_id))
		races.append(context.content.race_by_id(target.race_id))
	var allow_empty := spell.target_type == 7 or absi(spell.special) == 68
	var resolution := context.rules.magic.resolve_field_spell(character, targets, spell, power, context.rng, castes, races, false, allow_empty)
	if resolution == null or not resolution.cast:
		return SessionWorkflowResult.failed(&"item_spell_failed", "The item spell could not be resolved.")
	var charges_remaining := -1
	var dropped := true
	for carried: ItemInstance in character.inventory():
		if carried.id == instance_id:
			charges_remaining = carried.charges
			dropped = false
			break
	var events: Array[DomainEvent] = [DomainEvent.new(&"item_used", {"characterId": character.id, "instanceId": instance_id, "itemId": item.id, "spellId": spell.id, "power": power, "chargesRemaining": charges_remaining, "droppedOnEmpty": dropped, "source": "classic"})]
	var native_sound_id := item.sound_id + 600
	if item.sound_id != 0:
		events.append(DomainEvent.new(&"sound_requested", {"soundId": absi(native_sound_id), "waitForCompletion": native_sound_id < 0, "source": "classic-item"}))
	_append_field_spell_events(context, events, character, spell, power, resolution, &"classic-item", &"classic-item", &"item_spell_resolved", {"itemId": item.id, "instanceId": instance_id})
	return SessionWorkflowResult.completed(events)

static func item_owner(context: SessionWorkflowContext, instance_id: String) -> CharacterState:
	for character: CharacterState in context.state.party.characters():
		if _item_instance(character, instance_id) != null:
			return character
	return null

static func item_use_error_code(instance: ItemInstance, item: ItemDefinition, spell: SpellDefinition) -> StringName:
	if instance == null or item == null:
		return &"unknown_item_instance"
	if instance.charges == 0:
		return &"item_has_no_charges"
	if item.special_2 <= 1100:
		return &"item_has_no_spell_effect"
	if spell == null:
		return &"unknown_item_spell"
	return &"item_cannot_be_used"

static func item_target_request(request_id: String, character: CharacterState, instance_id: String, item: ItemDefinition, spell: SpellDefinition, power: int, required_count: int, party: Array[CharacterState]) -> InteractionRequest:
	var display_name := item.unidentified_name
	for carried: ItemInstance in character.inventory():
		if carried.id == instance_id:
			display_name = item.name if carried.identified else item.unidentified_name
			break
	return _character_selection_request(request_id, character, "%s uses %s. Choose %d target%s." % [character.name, display_name, required_count, "" if required_count == 1 else "s"], required_count, party, &"item-use", instance_id, spell, power)

static func make_scroll(context: SessionWorkflowContext, payload: PlayerIntent.SpellPayload) -> SessionWorkflowResult:
	if context.state.combat != null and not context.state.combat.completed:
		return SessionWorkflowResult.failed(&"scroll_scribing_in_battle", "Classic scroll scribing is available only while camped.")
	var character := context.state.party.character_by_id(payload.caster_id)
	var spell := context.content.spell_by_id(payload.spell_id)
	var probe := make_scroll_probe(context, character, spell, payload.power)
	if not probe.allowed:
		return SessionWorkflowResult.failed(&"scroll_scribing_unavailable", probe.reason)
	var slot_index := _first_empty_scroll_slot(character)
	var parchment := _parchment_instance(context, character)
	var parchment_definition: ItemDefinition = null if parchment == null else context.content.item_by_id(parchment.definition_id)
	if slot_index < 0 or parchment == null or parchment_definition == null or not context.rules.inventory.use_charge(character, parchment.id, parchment_definition):
		return SessionWorkflowResult.failed(&"scroll_scribing_commit_failed", "The validated scroll materials could not be committed.")
	var cost := absi(spell.cost * payload.power * 2)
	character.spell_points -= cost
	if not character.write_scroll(slot_index, spell.id, payload.power):
		return SessionWorkflowResult.failed(&"scroll_scribing_commit_failed", "The validated scroll slot could not be committed.")
	var events: Array[DomainEvent] = [DomainEvent.new(&"scroll_created", {"characterId": character.id, "slot": slot_index, "spellId": spell.id, "power": payload.power, "cost": cost, "parchmentInstanceId": parchment.id, "source": "classic"})]
	var sound_id := spell.sound_start + 600
	if sound_id != 0:
		events.append(DomainEvent.new(&"sound_requested", {"soundId": absi(sound_id), "waitForCompletion": false, "source": "classic-scroll-scribing"}))
	return SessionWorkflowResult.completed(events)

static func import_vault_character(context: SessionWorkflowContext, pending: bool, payload: PlayerIntent.VaultImportPayload) -> SessionWorkflowResult:
	if context.state.party_setup_completed or pending:
		return SessionWorkflowResult.failed(&"party_setup_closed", "Vault import is available only during party setup.")
	if context.state.character_draft != null:
		return SessionWorkflowResult.failed(&"character_draft_active", "Finish or cancel the character currently being created before importing from the vault.")
	if payload == null or payload.character_id.is_empty() or payload.revision_hash.is_empty() or payload.character_state == null:
		return SessionWorkflowResult.failed(&"invalid_vault_import", "A validated vault character revision is required.")
	var imported := CharacterState.from_data(payload.character_state.to_data())
	if imported == null or imported.id != payload.character_id:
		return SessionWorkflowResult.failed(&"invalid_vault_import", "The vault character state is malformed.")
	var restrictions := context.content.campaign_definition().restrictions
	var maximum_party_size := clampi(restrictions.maximum_party_size, 1, 6)
	var current_characters := context.state.party.characters()
	if current_characters.size() >= maximum_party_size:
		return SessionWorkflowResult.failed(&"invalid_party_size", "This campaign allows no more than %d characters." % maximum_party_size)
	if context.content.race_by_id(imported.race_id) == null or context.content.caste_by_id(imported.caste_id) == null:
		return SessionWorkflowResult.failed(&"vault_character_ineligible", "The vault character's race or class is not defined by this campaign.")
	if restrictions.banned_races.has(imported.race_id) or restrictions.banned_castes.has(imported.caste_id):
		return SessionWorkflowResult.failed(&"vault_character_ineligible", "The campaign restrictions reject this vault character.")
	if restrictions.maximum_level > 0 and imported.level > restrictions.maximum_level:
		return SessionWorkflowResult.failed(&"vault_character_ineligible", "The vault character exceeds this campaign's maximum level.")
	var prospective_party := current_characters.duplicate()
	prospective_party.append(imported)
	var aggregate_error := _aggregate_party_level_error(context, prospective_party)
	if not aggregate_error.is_empty():
		return SessionWorkflowResult.failed(&"vault_character_ineligible", aggregate_error)
	var race := context.content.race_by_id(imported.race_id)
	var caste := context.content.caste_by_id(imported.caste_id)
	context.rules.characters.ensure_age_group(imported, race, caste)
	if not race.eligible_caste_ids.is_empty() and not race.eligible_caste_ids.has(caste.id):
		return SessionWorkflowResult.failed(&"vault_character_ineligible", "The vault character's race cannot use that class.")
	if not caste.eligible_race_ids.is_empty() and not caste.eligible_race_ids.has(race.id):
		return SessionWorkflowResult.failed(&"vault_character_ineligible", "The vault character's class is not available to that race.")
	var imported_item_ids: Dictionary = {}
	for item: ItemInstance in imported.inventory():
		if context.content.item_by_id(item.definition_id) == null:
			return SessionWorkflowResult.failed(&"vault_character_ineligible", "The vault character carries an item unavailable in this campaign.")
		if imported_item_ids.has(item.id) or context.state.party.owns_item_instance(item.id):
			return SessionWorkflowResult.failed(&"duplicate_item_ownership", "That character revision does not uniquely own every exact item instance.")
		imported_item_ids[item.id] = true
	var imported_load := context.rules.inventory.calculated_load(imported, context.content.item_definitions())
	if imported_load < 0 or imported_load > imported.maximum_load:
		return SessionWorkflowResult.failed(&"vault_character_ineligible", "The vault character's carried wealth and items exceed this character's load limit.")
	# Vault revisions preserve item identity and equipment state, but load is derived
	# again from the target package so stale local revisions cannot bypass capacity.
	imported.carried_load = imported_load
	for spell_id: String in imported.known_spells():
		if context.content.spell_by_id(spell_id) == null:
			return SessionWorkflowResult.failed(&"vault_character_ineligible", "The vault character knows a spell unavailable in this campaign.")
	for scroll: SpellScrollState in imported.scroll_case():
		if not scroll.is_empty() and context.content.spell_by_id(scroll.spell_id) == null:
			return SessionWorkflowResult.failed(&"vault_character_ineligible", "The vault character's scroll case contains a spell unavailable in this campaign.")
	for binding: FastSpellBindingState in imported.fast_spells():
		if binding.is_empty():
			continue
		var bound_spell := context.content.spell_by_id(binding.spell_id)
		if bound_spell == null or not imported.known_spells().has(binding.spell_id):
			return SessionWorkflowResult.failed(&"vault_character_ineligible", "The vault character's Fast Spell bindings reference an unavailable or unknown spell.")
		if binding.power < 1 or binding.power > 7 or bound_spell.cost < 0 and binding.power != 1:
			return SessionWorkflowResult.failed(&"vault_character_ineligible", "The vault character's Fast Spell bindings contain an invalid power.")
	if context.content.has_character_appearance_catalog():
		var portrait := context.content.appearance_by_id(imported.portrait_id) if not imported.portrait_id.is_empty() else null
		if (portrait != null and portrait.kind != CharacterAppearanceDefinition.PORTRAIT) or (not imported.portrait_id.is_empty() and portrait == null):
			return SessionWorkflowResult.failed(&"vault_character_ineligible", "The vault character uses a portrait unavailable in this campaign package.")
		var combat_icon := context.content.appearance_by_id(imported.combat_icon_id) if not imported.combat_icon_id.is_empty() else null
		if (combat_icon != null and combat_icon.kind != CharacterAppearanceDefinition.COMBAT_ICON) or (not imported.combat_icon_id.is_empty() and combat_icon == null):
			return SessionWorkflowResult.failed(&"vault_character_ineligible", "The vault character uses a combat icon unavailable in this campaign package.")
	for current: CharacterState in current_characters:
		if current.id == imported.id or current.name.to_lower() == imported.name.to_lower():
			return SessionWorkflowResult.failed(&"duplicate_party_member", "That vault character is already represented in the party.")
	if not context.state.party.add_character(imported):
		return SessionWorkflowResult.failed(&"vault_character_ineligible", "The validated vault character could not be added to the party.")
	return SessionWorkflowResult.completed([DomainEvent.new(&"vault_character_imported", {"characterId": imported.id, "revisionHash": payload.revision_hash, "sourceCampaignId": payload.source_campaign_id})])

static func make_scroll_probe(context: SessionWorkflowContext, character: CharacterState, spell: SpellDefinition, power: int) -> InventoryActionProbe:
	if character == null or spell == null or not character.known_spells().has(spell.id):
		return InventoryActionProbe.block("The character does not know that spell.")
	if not context.state.party_camping:
		return InventoryActionProbe.block("Enter camp before making a scroll.")
	if character.current_health < 1 or character.spellcaster_type < 1:
		return InventoryActionProbe.block("The selected character cannot scribe scrolls.")
	if not _has_equipped_scroll_case(context, character):
		return InventoryActionProbe.block("Equip a scroll case before making a scroll.")
	if _first_empty_scroll_slot(character) < 0:
		return InventoryActionProbe.block("The scroll case already contains five spells.")
	if _parchment_instance(context, character) == null:
		return InventoryActionProbe.block("The character has no parchment.")
	if power < 1 or power > 7 or spell.cost < 0 and power != 1:
		return InventoryActionProbe.block("This spell does not support the selected scroll power.")
	if character.spell_points < absi(spell.cost * power * 2):
		return InventoryActionProbe.block("Scribing requires twice the spell's normal spell-point cost.")
	return InventoryActionProbe.permit()

static func resume_field_spell_item(context: SessionWorkflowContext, targeting: SessionContinuation.TargetingBody, target_ids: Array[String]) -> MagicTransitionResult:
	if targeting == null:
		return MagicTransitionResult.failed(&"invalid_session_continuation", "The item target continuation is unavailable.")
	if target_ids.size() != targeting.target_count:
		return MagicTransitionResult.failed(&"invalid_item_use_target", "The item requires exactly %d target%s." % [targeting.target_count, "" if targeting.target_count == 1 else "s"])
	var character := context.state.party.character_by_id(targeting.character_id)
	var instance := _item_instance(character, targeting.instance_id)
	if instance == null or instance.charges != targeting.starting_charges:
		return MagicTransitionResult.failed(&"invalid_session_continuation", "The item awaiting a target no longer matches its committed state.")
	return MagicTransitionResult.committed(commit_field_spell_item(context, targeting.character_id, targeting.instance_id, targeting.spell_id, targeting.power, target_ids))

static func unequip_item(context: SessionWorkflowContext, payload: PlayerIntent.ItemActionPayload) -> SessionWorkflowResult:
	var character := context.state.party.character_by_id(payload.actor_id)
	var instance := _item_instance(character, payload.item_id)
	var definition: ItemDefinition = null if instance == null else context.content.item_by_id(instance.definition_id)
	if character == null or instance == null or definition == null:
		return SessionWorkflowResult.failed(&"unknown_item_instance", "The selected character does not carry that item instance.")
	var probe := context.rules.inventory.unequip_classic(character, instance, definition, context.content.item_definitions())
	if not probe.allowed:
		return SessionWorkflowResult.failed(&"item_cannot_unequip", probe.reason)
	return SessionWorkflowResult.completed([DomainEvent.new(&"item_unequipped", {"characterId": character.id, "instanceId": instance.id, "itemId": definition.id})])

static func equip_item(context: SessionWorkflowContext, payload: PlayerIntent.ItemActionPayload) -> SessionWorkflowResult:
	var character := context.state.party.character_by_id(payload.actor_id)
	var instance := _item_instance(character, payload.item_id)
	var definition: ItemDefinition = null if instance == null else context.content.item_by_id(instance.definition_id)
	if character == null or instance == null or definition == null:
		return SessionWorkflowResult.failed(&"unknown_item_instance", "The selected character does not carry that item instance.")
	var probe := context.rules.inventory.equip_classic(character, instance, definition, context.content.race_by_id(character.race_id), context.content.caste_by_id(character.caste_id), context.state.party.characters(), context.content.item_definitions())
	if not probe.allowed:
		return SessionWorkflowResult.failed(&"item_cannot_equip", probe.reason)
	return SessionWorkflowResult.completed([DomainEvent.new(&"item_equipped", {"characterId": character.id, "instanceId": instance.id, "itemId": definition.id, "identified": instance.identified})])

static func begin_classic_torch(context: SessionWorkflowContext, request_revision: int) -> MagicTransitionResult:
	var identity := classic_torch_item(context)
	if identity.is_empty():
		return MagicTransitionResult.failed(&"torch_unavailable", "The party carries no usable torch.")
	return begin_field_spell_item(context, identity[0], identity[1], "", [], request_revision)

static func rebase_post_time_location(context: SessionWorkflowContext, continuation: SessionContinuation) -> bool:
	var exploration := continuation.exploration()
	if continuation.kind != &"post-clock" or exploration == null:
		return false
	var map := context.content.world.map_by_id(context.state.party.map_id)
	var cell: MapCell = null if map == null else map.topology.cell_at(context.state.party.coordinate)
	if cell == null:
		return false
	exploration.map_id = map.id
	exploration.coordinate = context.state.party.coordinate
	exploration.timed_check_coordinate = context.state.party.coordinate
	exploration.random_region_ids.assign(cell.random_rect_ids())
	exploration.random_region_index = cell.random_rect_ids().size() - 1
	return true

static func scroll_use_probe(context: SessionWorkflowContext, character: CharacterState, slot_index: int, spell: SpellDefinition) -> InventoryActionProbe:
	if character == null or slot_index < 0 or slot_index >= 5:
		return InventoryActionProbe.block("The scroll slot is unavailable.")
	var scroll := character.scroll_at(slot_index)
	if scroll == null or scroll.is_empty() or spell == null or spell.id != scroll.spell_id or scroll.power < 1 or scroll.power > 7:
		return InventoryActionProbe.block("This scroll slot is empty or invalid.")
	if character.current_health < 1 or character.conditions.is_active(ConditionRules.ANIMATED):
		return InventoryActionProbe.block("The selected character cannot use a scroll.")
	if not _has_equipped_scroll_case(context, character):
		return InventoryActionProbe.block("Equip the scroll case before using its spells.")
	if not spell.in_camp:
		return InventoryActionProbe.block("This scroll cannot be used outside battle; Classic offers to discard it.")
	if spell.target_type < 0 or spell.target_type > 12:
		return InventoryActionProbe.block("This scroll has an invalid Classic field target type.")
	if spell.target_type in [3, 7, 9] and not context.state.party.allies().is_empty():
		return InventoryActionProbe.block("This scroll also targets allied creatures; that Classic field branch is not implemented yet.")
	if not field_spell_effect_supported(spell):
		return InventoryActionProbe.block("This scroll's Classic field effect is not implemented yet.")
	return InventoryActionProbe.permit()

static func generate_character_draft(context: SessionWorkflowContext, pending: bool, payload: PlayerIntent.CharacterDraftPayload) -> SessionWorkflowResult:
	if context.state.party_setup_completed or pending:
		return SessionWorkflowResult.failed(&"party_setup_closed", "Character creation is available only during party setup.")
	if payload == null or payload.spec == null:
		return SessionWorkflowResult.failed(&"invalid_character_spec", "Generate Character requires exactly one typed specification.")
	var maximum_party_size := clampi(context.content.campaign_definition().restrictions.maximum_party_size, 1, 6)
	var current_characters := context.state.party.characters()
	if current_characters.size() >= maximum_party_size:
		return SessionWorkflowResult.failed(&"invalid_party_size", "This campaign allows no more than %d characters." % maximum_party_size)
	var names: Dictionary = {}
	for current: CharacterState in current_characters:
		names[current.name.to_lower()] = true
	var validation := _character_creation_error(context, payload.spec, names)
	if not validation.is_empty():
		return SessionWorkflowResult.failed(StringName(validation["code"]), String(validation["message"]))
	var character_id := context.state.character_draft.generated_character.id if context.state.character_draft != null and context.state.character_draft.generated_character != null else _next_party_character_id(context.state)
	var character := _create_character_from_spec(context, payload.spec, character_id)
	if character == null:
		return SessionWorkflowResult.failed(&"character_creation_failed", "Realmz rules rejected the character draft.")
	var draft := CharacterDraft.new()
	draft.name = payload.spec.name
	draft.gender = payload.spec.gender
	draft.starting_level = payload.spec.starting_level
	draft.race_id = payload.spec.race_id
	draft.caste_id = payload.spec.caste_id
	draft.portrait_id = character.portrait_id
	draft.combat_icon_id = character.combat_icon_id
	draft.generated_character = character
	context.state.character_draft = draft
	return SessionWorkflowResult.completed([DomainEvent.new(&"character_draft_generated", {"characterId": character.id, "name": character.name})])

static func cancel_character_draft(context: SessionWorkflowContext, pending: bool) -> SessionWorkflowResult:
	if context.state.party_setup_completed or pending:
		return SessionWorkflowResult.failed(&"party_setup_closed", "Character creation is available only during party setup.")
	if context.state.character_draft == null:
		return SessionWorkflowResult.failed(&"no_character_draft", "There is no generated character to cancel.")
	var character_id := context.state.character_draft.generated_character.id if context.state.character_draft.generated_character != null else ""
	context.state.character_draft = null
	return SessionWorkflowResult.completed([DomainEvent.new(&"character_draft_cancelled", {"characterId": character_id})])

static func set_character_draft_spells(context: SessionWorkflowContext, pending: bool, spell_ids: Array[String]) -> SessionWorkflowResult:
	if context.state.party_setup_completed or pending:
		return SessionWorkflowResult.failed(&"party_setup_closed", "Spell selection is available only during character creation.")
	if context.state.character_draft == null or context.state.character_draft.generated_character == null:
		return SessionWorkflowResult.failed(&"no_character_draft", "Generate the character before choosing spells.")
	var character := context.state.character_draft.generated_character
	var caste := context.content.caste_by_id(character.caste_id)
	var candidate_ids: Dictionary = {}
	for spell: SpellDefinition in _character_spell_candidates(context, character, caste):
		candidate_ids[spell.id] = spell
	var selected: Array[String] = []
	var spent := 0
	for spell_id: String in spell_ids:
		if selected.has(spell_id) or not candidate_ids.has(spell_id):
			return SessionWorkflowResult.failed(&"invalid_character_spell", "The selected spell is not available to this character.")
		selected.append(spell_id)
		spent += context.rules.characters.spell_selection_cost(candidate_ids[spell_id] as SpellDefinition)
	var total := context.rules.characters.spell_selection_total(character, caste)
	if spent > total:
		return SessionWorkflowResult.failed(&"character_spell_budget_exceeded", "The selected spells exceed this character's Classic selection points.")
	character.set_known_spells(selected)
	return SessionWorkflowResult.completed([DomainEvent.new(&"character_draft_spells_changed", {"characterId": character.id, "spellIds": selected, "remaining": total - spent})])

static func resume_field_spell(context: SessionWorkflowContext, targeting: SessionContinuation.TargetingBody, target_ids: Array[String]) -> MagicTransitionResult:
	if targeting == null:
		return MagicTransitionResult.failed(&"invalid_session_continuation", "The field-spell target continuation is unavailable.")
	if target_ids.size() != targeting.target_count:
		return MagicTransitionResult.failed(&"invalid_field_spell_target", "The spell requires exactly %d target%s." % [targeting.target_count, "" if targeting.target_count == 1 else "s"])
	var character := context.state.party.character_by_id(targeting.character_id)
	if character == null or character.spell_points != targeting.starting_spell_points:
		return MagicTransitionResult.failed(&"invalid_session_continuation", "The field spell awaiting a target no longer matches its committed state.")
	return MagicTransitionResult.committed(commit_field_spell(context, targeting.character_id, targeting.spell_id, targeting.power, target_ids), true)

static func commit_field_spell(context: SessionWorkflowContext, character_id: String, spell_id: String, power: int, requested_target_ids: Array[String]) -> SessionWorkflowResult:
	var character := context.state.party.character_by_id(character_id)
	var spell := context.content.spell_by_id(spell_id)
	var probe := field_spell_probe(context, character, spell, power)
	if not probe.allowed:
		return SessionWorkflowResult.failed(&"field_spell_unavailable", probe.reason)
	var selected_value: Variant = _selected_party_targets(context.state.party, requested_target_ids)
	if selected_value == null:
		return SessionWorkflowResult.failed(&"invalid_field_spell_target", "The spell target selection contains an unavailable or duplicate character.")
	if (selected_value as Dictionary).size() != field_spell_target_count(context, spell, power):
		return SessionWorkflowResult.failed(&"invalid_field_spell_target", "The spell target selection has the wrong number of characters.")
	var selected: Dictionary = selected_value
	var targets := _ordered_party_targets(context.state.party, selected)
	var castes: Array[CasteDefinition] = []
	var races: Array[RaceDefinition] = []
	for target: CharacterState in targets:
		castes.append(context.content.caste_by_id(target.caste_id))
		races.append(context.content.race_by_id(target.race_id))
	var allow_empty := spell.target_type == 7 or absi(spell.special) == 68
	var resolution := context.rules.magic.resolve_field_spell(character, targets, spell, power, context.rng, castes, races, true, allow_empty)
	if resolution == null or not resolution.cast:
		return SessionWorkflowResult.failed(&"field_spell_failed", "The field spell could not be resolved.")
	var events: Array[DomainEvent] = [DomainEvent.new(&"field_spell_cast", {"characterId": character.id, "spellId": spell.id, "power": power, "cost": resolution.cost, "source": "classic"})]
	_append_field_spell_events(context, events, character, spell, power, resolution, &"classic-field-spell", &"classic", &"field_spell_resolved")
	return SessionWorkflowResult.completed(events)

static func _append_field_spell_events(context: SessionWorkflowContext, events: Array[DomainEvent], character: CharacterState, spell: SpellDefinition, power: int, resolution: GroupSpellResolution, sound_source: StringName, state_source: StringName, event_kind: StringName, event_context: Dictionary = {}) -> void:
	var start_sound := spell.sound_start + 600
	if start_sound != 0:
		events.append(DomainEvent.new(&"sound_requested", {"soundId": absi(start_sound), "waitForCompletion": true, "source": String(sound_source)}))
	var special := absi(spell.special)
	if special == 68:
		context.state.party.fatigue = 4
		events.append(DomainEvent.new(&"party_fatigue_changed", {"fatigue": 4, "spellId": spell.id, "source": String(state_source)}))
	elif spell.target_type == 7:
		var condition_index := 0 if special == 50 else special
		var next_value := power * 30 - 1 if special == 50 else maxi(context.state.party.conditions.value(condition_index), resolution.duration)
		if special != 50 or power * 30 > context.state.party.conditions.value(condition_index):
			context.state.party.conditions.set_value(condition_index, next_value)
		events.append(DomainEvent.new(&"party_condition_changed", {"condition": condition_index, "value": context.state.party.conditions.value(condition_index), "spellId": spell.id, "source": String(state_source)}))
	for index: int in resolution.resolutions.size():
		var target_resolution := resolution.resolutions[index]
		var payload := {"characterId": character.id, "targetId": resolution.target_ids[index], "spellId": spell.id, "power": power, "saved": target_resolution.saved, "damage": target_resolution.damage, "healing": maxi(0, -target_resolution.damage), "duration": target_resolution.duration, "source": "classic"}
		payload.merge(event_context, true)
		events.append(DomainEvent.new(event_kind, payload))
		if target_resolution.aging != null and target_resolution.aging.changed_group():
			var target := context.state.party.character_by_id(resolution.target_ids[index])
			events.append(DomainEvent.new(&"character_age_changed", target_resolution.aging.event_payload(target, context.content.race_by_id(target.race_id))))
	if spell.target_type == 11 and spell.sound_end + 600 != 0:
		events.append(DomainEvent.new(&"sound_requested", {"soundId": absi(spell.sound_end + 600), "waitForCompletion": false, "source": String(sound_source)}))

static func begin_field_spell(context: SessionWorkflowContext, payload: PlayerIntent.SpellPayload, request_revision: int) -> MagicTransitionResult:
	var character := context.state.party.character_by_id(payload.caster_id)
	var spell := context.content.spell_by_id(payload.spell_id)
	var probe := field_spell_probe(context, character, spell, payload.power)
	if not probe.allowed:
		return MagicTransitionResult.failed(&"field_spell_unavailable", probe.reason)
	var target_ids := field_spell_target_ids(context, character, spell, payload.target_ids, payload.target_id)
	var required_count := field_spell_target_count(context, spell, payload.power)
	if target_ids.size() == required_count:
		return MagicTransitionResult.committed(commit_field_spell(context, character.id, spell.id, payload.power, target_ids), true)
	if not target_ids.is_empty():
		return MagicTransitionResult.failed(&"invalid_field_spell_target", "The spell requires exactly %d valid party target%s." % [required_count, "" if required_count == 1 else "s"])
	var targeting := SessionContinuation.TargetingBody.new()
	targeting.character_id = character.id
	targeting.spell_id = spell.id
	targeting.power = payload.power
	targeting.target_count = required_count
	targeting.starting_spell_points = character.spell_points
	var continuation := SessionContinuation.targeting_selection(&"field-spell-target-selection", targeting)
	var interaction := field_spell_target_request("session.field-spell:%s:%d" % [spell.id, request_revision], character, spell, payload.power, required_count, context.state.party.characters())
	return MagicTransitionResult.waiting(continuation, interaction, [DomainEvent.new(&"field_spell_target_requested", {"characterId": character.id, "spellId": spell.id, "power": payload.power, "targetCount": required_count, "source": "classic"})])

static func _has_equipped_scroll_case(context: SessionWorkflowContext, character: CharacterState) -> bool:
	if character == null:
		return false
	for instance: ItemInstance in character.inventory():
		var definition := context.content.item_by_id(instance.definition_id)
		if instance.equipped and definition != null and absi(definition.item_type) == 13:
			return true
	return false

static func _first_empty_scroll_slot(character: CharacterState) -> int:
	if character == null:
		return -1
	for index: int in character.scroll_case().size():
		if character.scroll_at(index).is_empty():
			return index
	return -1

static func _selected_party_targets(party: PartyState, target_ids: Array[String]) -> Variant:
	var selected: Dictionary = {}
	for target_id: String in target_ids:
		if target_id.is_empty() or selected.has(target_id) or party.character_by_id(target_id) == null:
			return null
		selected[target_id] = true
	return selected

static func _ordered_party_targets(party: PartyState, selected: Dictionary) -> Array[CharacterState]:
	var targets: Array[CharacterState] = []
	for member: CharacterState in party.characters():
		if selected.has(member.id):
			targets.append(member)
	return targets

static func _item_instance(character: CharacterState, instance_id: String) -> ItemInstance:
	if character == null:
		return null
	for item: ItemInstance in character.inventory():
		if item.id == instance_id:
			return item
	return null

func present_media_events(events: Array[DomainEvent], media: ClassicMediaCatalog) -> void:
	set_package_media(media)
	if media == null:
		return
	for event: DomainEvent in events:
		if event.kind != &"picture_requested":
			continue
		var picture_id := int(event.payload.get("pictureId", 0))
		var asset := media.asset_by_resource("PICT", picture_id)
		if asset == null:
			last_picture_media_diagnostic = media.resolution_diagnostic("PICT", picture_id, "classic-picture")
			_picture.texture = null
			_picture.tooltip_text = "Scenario picture unavailable"
			_picture_caption.text = ""
			_picture_stage.visible = true
			continue
		var image := _decode_image(asset, media.read_bytes(asset))
		last_picture_media_diagnostic = media.resolution_diagnostic("PICT", picture_id, "classic-picture", "decoded" if image != null else "decode-failed")
		_picture.texture = ImageTexture.create_from_image(image) if image != null else null
		_picture.texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST
		_picture.tooltip_text = "Scenario picture" if image != null else "Scenario picture unavailable"
		_picture_caption.text = ""
		_picture_stage.visible = true

static func _parchment_instance(context: SessionWorkflowContext, character: CharacterState) -> ItemInstance:
	if character == null:
		return null
	for instance: ItemInstance in character.inventory():
		var definition := context.content.item_by_id(instance.definition_id)
		if definition != null and definition.classic_id == 806 and instance.charges != 0:
			return instance
	return null

static func field_item_target_count(context: SessionWorkflowContext, spell: SpellDefinition, power: int) -> int:
	if spell.target_type == 7 or absi(spell.special) == 68:
		return 0
	if spell.target_type == 5:
		return 1
	if spell.target_type > 2:
		return context.state.party.characters().size()
	return mini(power, context.state.party.characters().size()) if spell.target_type == 0 else 1

static func field_spell_target_count(context: SessionWorkflowContext, spell: SpellDefinition, power: int) -> int:
	if spell.target_type == 7 or absi(spell.special) == 68:
		return 0
	if spell.target_type == 5:
		return 1
	if spell.target_type > 2:
		return context.state.party.characters().size()
	return mini(power, context.state.party.characters().size()) if spell.target_type == 0 else 1

static func field_spell_effect_supported(spell: SpellDefinition) -> bool:
	var special := absi(spell.special)
	if spell.target_type == 7:
		return special == 50 or special >= 1 and special < ConditionSet.PARTY_COUNT
	if special == 68:
		return true
	if special > 0 and special < 41 or special in [48, 57, 59, 60, 61, 64, 66, 91, 92] or special > 99:
		return true
	return special == 0 and absi(spell.damage_type) >= 1 and absi(spell.damage_type) < 8 and (spell.damage_min != 0 or spell.damage_max != 0 or spell.power_damage_min != 0 or spell.power_damage_max != 0)

static func prepare_character_finalize(context: SessionWorkflowContext, pending: bool) -> CharacterFinalizeWorkflowResult:
	if context.state.party_setup_completed or pending:
		return CharacterFinalizeWorkflowResult.failed(&"party_setup_closed", "Character creation is available only during party setup.")
	if context.state.character_draft == null or context.state.character_draft.generated_character == null:
		return CharacterFinalizeWorkflowResult.failed(&"no_character_draft", "Generate and review the character before finalizing it.")
	var maximum_party_size := clampi(context.content.campaign_definition().restrictions.maximum_party_size, 1, 6)
	var current_characters := context.state.party.characters()
	if current_characters.size() >= maximum_party_size:
		return CharacterFinalizeWorkflowResult.failed(&"invalid_party_size", "This campaign allows no more than %d characters." % maximum_party_size)
	var draft := context.state.character_draft
	var names: Dictionary = {}
	for current: CharacterState in current_characters:
		names[current.name.to_lower()] = true
	var validation := _character_creation_error(context, draft.to_creation_spec(), names)
	if not validation.is_empty():
		return CharacterFinalizeWorkflowResult.failed(StringName(validation["code"]), String(validation["message"]))
	var caste := context.content.caste_by_id(draft.generated_character.caste_id)
	var total := context.rules.characters.spell_selection_total(draft.generated_character, caste)
	var spent := 0
	for spell_id: String in draft.generated_character.known_spells():
		spent += context.rules.characters.spell_selection_cost(context.content.spell_by_id(spell_id))
	return CharacterFinalizeWorkflowResult.ready(draft.generated_character.id, draft.generated_character.name, maxi(0, total - spent))

static func commit_character_draft(context: SessionWorkflowContext) -> CharacterFinalizeWorkflowResult:
	if context.state.character_draft == null or context.state.character_draft.generated_character == null:
		return CharacterFinalizeWorkflowResult.failed(&"no_character_draft", "The generated character is no longer available.")
	var maximum_party_size := clampi(context.content.campaign_definition().restrictions.maximum_party_size, 1, 6)
	if context.state.party.characters().size() >= maximum_party_size:
		return CharacterFinalizeWorkflowResult.failed(&"invalid_party_size", "This campaign allows no more than %d characters." % maximum_party_size)
	var character := CharacterState.from_data(context.state.character_draft.generated_character.to_data())
	if character == null:
		return CharacterFinalizeWorkflowResult.failed(&"character_creation_failed", "Realmz rules rejected the generated character.")
	var party_context := context.state.party.characters()
	party_context.append(character)
	var aggregate_error := _aggregate_party_level_error(context, party_context)
	if not aggregate_error.is_empty():
		return CharacterFinalizeWorkflowResult.failed(&"party_level_limit_exceeded", aggregate_error)
	if not _materialize_initial_inventory(context, character, context.content.caste_by_id(character.caste_id), party_context) or not context.state.party.add_character(character):
		return CharacterFinalizeWorkflowResult.failed(&"character_creation_failed", "Realmz rules rejected the generated character.")
	context.state.character_draft = null
	return CharacterFinalizeWorkflowResult.committed(character.id, character.name, [DomainEvent.new(&"character_finalized", {"characterId": character.id})])

static func character_draft_is_valid(content: RealmzContent, state: GameState, rules: RealmzRules) -> bool:
	if state.character_draft == null:
		return true
	if state.party_setup_completed or state.character_draft.finalized or state.character_draft.generated_character == null:
		return false
	var draft := state.character_draft
	var character := draft.generated_character
	if character.name != draft.name or character.gender != draft.gender or character.race_id != draft.race_id or character.caste_id != draft.caste_id or character.portrait_id != draft.portrait_id or character.combat_icon_id != draft.combat_icon_id:
		return false
	var race := content.race_by_id(character.race_id)
	var caste := content.caste_by_id(character.caste_id)
	if race == null or caste == null:
		return false
	var restrictions := content.campaign_definition().restrictions
	if restrictions.banned_races.has(race.id) or restrictions.banned_castes.has(caste.id):
		return false
	if not race.eligible_caste_ids.is_empty() and not race.eligible_caste_ids.has(caste.id):
		return false
	if not caste.eligible_race_ids.is_empty() and not caste.eligible_race_ids.has(race.id):
		return false
	for current: CharacterState in state.party.characters():
		if current.id == character.id or current.name.to_lower() == character.name.to_lower():
			return false
	var candidate_ids: Dictionary = {}
	for spell: SpellDefinition in content.spell_definitions():
		if int(spell.classic_id / 1000) == character.spellcaster_type:
			var tier := spell.classic_tier()
			if tier >= 0 and tier < rules.characters.maximum_spell_selection_level(caste):
				candidate_ids[spell.id] = spell
	var spent := 0
	for spell_id: String in character.known_spells():
		if not candidate_ids.has(spell_id):
			return false
		spent += rules.characters.spell_selection_cost(candidate_ids[spell_id] as SpellDefinition)
	if spent > rules.characters.spell_selection_total(character, caste):
		return false
	for item: ItemInstance in character.inventory():
		if content.item_by_id(item.definition_id) == null:
			return false
	return true

static func party_experience_multiplier(characters: Array[CharacterState], difficulty: int, campaign: CampaignDefinition) -> float:
	if campaign == null or not campaign.guidance_authored or campaign.recommended_party_levels <= 0:
		return 1.0
	var current_levels := 0
	for character: CharacterState in characters:
		current_levels += character.level
	var multiplier := PartySetupRules.experience_multiplier(campaign.recommended_party_levels, current_levels, difficulty)
	return 1.0 if multiplier <= 0.0 else multiplier

static func set_party_setup_options(context: SessionWorkflowContext, pending: bool, difficulty: int, monster_set: int) -> SessionWorkflowResult:
	if context.state.party_setup_completed or pending:
		return SessionWorkflowResult.failed(&"party_setup_closed", "Party setup options are no longer available.")
	if difficulty < -2 or difficulty > 2:
		return SessionWorkflowResult.failed(&"invalid_difficulty", "Classic difficulty must be between Novice and Veteran.")
	if not context.content.available_monster_sets().has(monster_set):
		return SessionWorkflowResult.failed(&"unavailable_monster_set", "That Classic monster set is not present in this campaign package.")
	context.state.difficulty = difficulty
	context.state.monster_set = monster_set
	return SessionWorkflowResult.completed([DomainEvent.new(&"party_setup_options_changed", {"difficulty": difficulty, "monsterSet": monster_set})])

static func remove_party_member(context: SessionWorkflowContext, pending: bool, character_id: String) -> SessionWorkflowResult:
	if context.state.party_setup_completed or pending:
		return SessionWorkflowResult.failed(&"party_setup_closed", "Party members can be removed only during party setup.")
	context.state.set_combat_auto(character_id, false)
	if character_id.is_empty() or not context.state.party.remove_character(character_id):
		return SessionWorkflowResult.failed(&"unknown_party_member", "The selected character is not in the setup party.")
	context.state.set_selected_character_ids([])
	return SessionWorkflowResult.completed([DomainEvent.new(&"party_member_removed", {"characterId": character_id})])

static func reorder_party(context: SessionWorkflowContext, character_ids: Array[String]) -> SessionWorkflowResult:
	var current := context.state.party.characters()
	if current.size() < 2:
		return SessionWorkflowResult.failed(&"party_order_unavailable", "At least two party members are required to change party order.")
	var previous_ids: Array[String] = []
	for character: CharacterState in current:
		previous_ids.append(character.id)
	if not context.state.party.reorder_characters(character_ids):
		return SessionWorkflowResult.failed(&"invalid_party_order", "Party Order requires every current character exactly once.")
	return SessionWorkflowResult.completed([DomainEvent.new(&"party_reordered", {"previousCharacterIds": previous_ids, "characterIds": character_ids.duplicate(), "source": "classic"})])

static func field_spell_target_ids(context: SessionWorkflowContext, character: CharacterState, spell: SpellDefinition, requested_targets: Array[String], requested_target: String) -> Array[String]:
	if spell.target_type == 5:
		return [character.id]
	if spell.target_type > 2:
		if spell.target_type == 7 or absi(spell.special) == 68:
			return []
		return _party_character_ids(context.state.party)
	var values: Array[String] = requested_targets.duplicate()
	if values.is_empty() and not requested_target.is_empty():
		values.append(requested_target)
	return values

static func change_character_appearance(context: SessionWorkflowContext, payload: PlayerIntent.AppearancePayload) -> SessionWorkflowResult:
	if not context.state.party_setup_completed:
		return SessionWorkflowResult.failed(&"appearance_change_unavailable", "Begin the adventure before changing appearance.")
	if context.state.combat != null and not context.state.combat.completed:
		return SessionWorkflowResult.failed(&"appearance_change_unavailable", "Appearance changes are unavailable during battle.")
	if not context.content.has_character_appearance_catalog():
		return SessionWorkflowResult.failed(&"appearance_change_unavailable", "This package does not contain the complete Classic portrait and combat-icon catalogs.")
	var character := context.state.party.character_by_id(payload.character_id)
	if character == null:
		return SessionWorkflowResult.failed(&"unknown_party_member", "The selected character is not in the active party.")
	if payload.appearance_kind not in [CharacterAppearanceDefinition.PORTRAIT, CharacterAppearanceDefinition.COMBAT_ICON]:
		return SessionWorkflowResult.failed(&"invalid_appearance_kind", "Choose either a portrait or a combat icon.")
	var appearance := context.content.appearance_by_id(payload.appearance_id)
	if appearance == null or appearance.kind != payload.appearance_kind:
		return SessionWorkflowResult.failed(&"invalid_character_appearance", "The selected appearance is unavailable for that role.")
	var previous_id := character.portrait_id if payload.appearance_kind == CharacterAppearanceDefinition.PORTRAIT else character.combat_icon_id
	if previous_id == appearance.id:
		return SessionWorkflowResult.failed(&"appearance_unchanged", "Choose a different appearance before applying the change.")
	if payload.appearance_kind == CharacterAppearanceDefinition.PORTRAIT:
		character.portrait_id = appearance.id
	else:
		character.combat_icon_id = appearance.id
	return SessionWorkflowResult.completed([DomainEvent.new(&"character_appearance_changed", {
		"characterId": character.id,
		"appearanceKind": String(payload.appearance_kind),
		"previousAppearanceId": previous_id,
		"appearanceId": appearance.id,
		"source": "classic-character-menu",
	})])

static func _character_creation_error(context: SessionWorkflowContext, spec: CharacterCreationSpec, existing_names: Dictionary) -> Dictionary:
	if spec == null:
		return {"code": &"invalid_character_spec", "message": "A character specification is required."}
	if spec.name.is_empty() or spec.name.length() > 24 or spec.gender not in [1, 2]:
		return {"code": &"invalid_character_spec", "message": "Every party member requires a valid name and gender."}
	if not CharacterRules.STARTING_LEVELS.has(spec.starting_level):
		return {"code": &"invalid_starting_level", "message": "Starting level must be one of Castle's fixed character-creation choices."}
	if existing_names.has(spec.name.to_lower()):
		return {"code": &"duplicate_character_name", "message": "Party member names must be unique."}
	var race := context.content.race_by_id(spec.race_id)
	var caste := context.content.caste_by_id(spec.caste_id)
	if race == null or caste == null:
		return {"code": &"unknown_character_definition", "message": "Party creation references an unavailable race or caste."}
	var restrictions := context.content.campaign_definition().restrictions
	if restrictions.banned_races.has(race.id):
		return {"code": &"restricted_race", "message": "This campaign does not allow the selected race."}
	if restrictions.banned_castes.has(caste.id):
		return {"code": &"restricted_caste", "message": "This campaign does not allow the selected class."}
	if restrictions.maximum_level > 0 and spec.starting_level > restrictions.maximum_level:
		return {"code": &"restricted_starting_level", "message": "This campaign allows characters only through level %d." % restrictions.maximum_level}
	if not race.eligible_caste_ids.is_empty() and not race.eligible_caste_ids.has(caste.id):
		return {"code": &"incompatible_race_class", "message": "The selected race cannot use that class."}
	if not caste.eligible_race_ids.is_empty() and not caste.eligible_race_ids.has(race.id):
		return {"code": &"incompatible_class_race", "message": "The selected class is not available to that race."}
	if context.content.has_character_appearance_catalog() and _resolved_character_appearance(context, spec, race).is_empty():
		return {"code": &"invalid_character_appearance", "message": "The selected portrait or combat icon is unavailable in this campaign package."}
	return {}

static func _create_character_from_spec(context: SessionWorkflowContext, spec: CharacterCreationSpec, character_id: String, add_starting_items: bool = false, party_context: Array[CharacterState] = []) -> CharacterState:
	var race := context.content.race_by_id(spec.race_id)
	var character := context.rules.characters.create_character(character_id, spec.name, race, context.content.caste_by_id(spec.caste_id), spec.gender, context.rng, false, spec.starting_level)
	if character == null:
		return null
	var appearance := _resolved_character_appearance(context, spec, race)
	character.portrait_id = String(appearance.get("portraitId", spec.portrait_id))
	character.combat_icon_id = String(appearance.get("combatIconId", spec.combat_icon_id))
	if add_starting_items:
		var equipment_context := party_context.duplicate()
		equipment_context.append(character)
		if not _materialize_initial_inventory(context, character, context.content.caste_by_id(spec.caste_id), equipment_context):
			return null
	return character

static func _materialize_initial_inventory(context: SessionWorkflowContext, character: CharacterState, caste: CasteDefinition, party_context: Array[CharacterState]) -> bool:
	if character == null or caste == null or not character.inventory().is_empty():
		return false
	var definitions := context.content.item_definitions()
	character.carried_load = context.rules.inventory.calculated_load(character, definitions)
	if character.carried_load < 0 or character.carried_load > character.maximum_load:
		return false
	var added: Array[ItemInstance] = []
	for index: int in caste.start_items().size():
		var definition := context.content.item_by_id(caste.start_items()[index])
		if definition == null:
			return false
		var instance := context.rules.inventory.add_item(character, definition, "%s.item.%d" % [character.id, index], true)
		# Castle tests capacity before writing the item record. Its separate numitems
		# counter advances too early; the direct model keeps only records that fit.
		if instance != null:
			added.append(instance)
	var race := context.content.race_by_id(character.race_id)
	for instance: ItemInstance in added:
		var definition := context.content.item_by_id(instance.definition_id)
		context.rules.inventory.equip_classic(character, instance, definition, race, caste, party_context, definitions)
	return context.rules.inventory.calculated_load(character, definitions) == character.carried_load

static func create_party(context: SessionWorkflowContext, pending: bool, specs: Array[CharacterCreationSpec]) -> SessionWorkflowResult:
	if context.state.party_setup_completed or pending:
		return SessionWorkflowResult.failed(&"party_setup_closed", "Party creation is available only during party setup.")
	if context.state.character_draft != null:
		return SessionWorkflowResult.failed(&"character_draft_active", "Finish or cancel the character currently being created.")
	var maximum_party_size := clampi(context.content.campaign_definition().restrictions.maximum_party_size, 1, 6)
	if specs.is_empty() or specs.size() > maximum_party_size:
		return SessionWorkflowResult.failed(&"invalid_party_size", "This campaign allows one through %d characters." % maximum_party_size)
	var requested_levels := 0
	for requested: CharacterCreationSpec in specs:
		requested_levels += requested.starting_level
	var campaign := context.content.campaign_definition()
	if campaign != null and campaign.guidance_authored and campaign.maximum_party_levels > 0 and requested_levels > campaign.maximum_party_levels:
		return SessionWorkflowResult.failed(&"party_level_limit_exceeded", "This party's combined %d levels exceed the scenario maximum of %d." % [requested_levels, campaign.maximum_party_levels])
	var created: Array[CharacterState] = []
	var names: Dictionary = {}
	for index: int in specs.size():
		var spec: CharacterCreationSpec = specs[index]
		var validation := _character_creation_error(context, spec, names)
		if not validation.is_empty():
			return SessionWorkflowResult.failed(StringName(validation["code"]), String(validation["message"]))
		var character := _create_character_from_spec(context, spec, "party.character.%d" % (index + 1), true, created)
		if character == null:
			return SessionWorkflowResult.failed(&"character_creation_failed", "Realmz rules rejected a party member.")
		names[spec.name.to_lower()] = true
		created.append(character)
	context.state.party = PartyState.new(context.state.party.map_id, context.state.party.coordinate, created)
	context.state.experience_multiplier = party_experience_multiplier(created, context.state.difficulty, campaign)
	context.state.party_setup_completed = true
	var character_ids: Array[String] = []
	for character: CharacterState in created:
		character_ids.append(character.id)
	return SessionWorkflowResult.completed([DomainEvent.new(&"party_created", {"characterIds": character_ids})])

func run() -> void:
	var loaded := PackageRepository.new().load_package(FIXTURE_PATH)
	assert_true(loaded.is_ok(), "topology fixture loads: %s" % loaded.error_message)
	if not loaded.is_ok():
		return
	var world_state := WorldState.new()
	var land := loaded.content.world.map_by_id("land:0")
	var hidden_cell := land.topology.cell_at(Vector2i(0, 1))
	var hidden_feature := hidden_cell.feature_by_kind(&"secret")
	assert_not_null(hidden_feature, "land secret is an explicit feature")
	var hidden_probe := land.topology.probe_entry(hidden_cell.coordinate, Vector2i.LEFT, world_state)
	assert_equal(hidden_probe.reason, &"secret_hidden", "hidden land secret blocks movement through topology")
	assert_equal(hidden_probe.target_cell, hidden_cell, "a blocked destination retains its authoritative terrain facts for Classic attempt timing")
	world_state.discover_secret(hidden_feature.id)
	assert_true(land.topology.probe_entry(hidden_cell.coordinate, Vector2i.LEFT, world_state).allowed, "discovery overlay changes the same topology query")
	assert_true(land.topology.probe_land_entry(Vector2i.ZERO, world_state).allowed, "land entry checks the destination tile without inventing a diagonal edge")
	assert_equal(land.topology.probe_entry(Vector2i.ZERO, Vector2i(-1, -1), world_state).reason, &"invalid_direction", "edge-based topology entry remains cardinal for dungeons and pathfinding")
	assert_equal(land.topology.find_path(Vector2i(1, 1), Vector2i.ZERO, world_state, &"land"), [Vector2i.ZERO], "land pathfinding uses the same direct diagonal probe without corner blocking")
	assert_equal(land.topology.visible_cells(Vector2i(1, 1), 8, world_state, false).size(), 8100, "non-LOS land view derives every Classic map cell from topology")
	var bounded_visibility := land.topology.visible_cells(Vector2i(1, 1), 2, world_state, true)
	assert_true(bounded_visibility.all(func(coordinate: Vector2i) -> bool: return coordinate.x <= 3 and coordinate.y <= 3), "LOS visibility probes only the bounded radius neighborhood")
	assert_true(bounded_visibility.size() <= 16, "edge-clamped LOS visibility never traverses the complete map")

	var dungeon := loaded.content.world.map_by_id("dungeon:0")
	assert_equal(dungeon.topology.probe_entry(Vector2i.ZERO, Vector2i.LEFT, world_state).reason, &"terrain_blocked", "dungeon wall blocks movement")
	var door_probe := dungeon.topology.probe_entry(Vector2i(1, 0), Vector2i.LEFT, world_state)
	assert_true(door_probe.allowed, "dungeon door permits the Classic movement attempt")
	assert_equal(door_probe.door_id, "dungeon:0:cell:1,0:door", "movement and rendering share the explicit door identity")
	assert_equal(dungeon.topology.find_path(Vector2i(2, 0), Vector2i(1, 0), world_state, &"dungeon"), [Vector2i(1, 0)], "pathfinding traverses the same explicit door edge")
	assert_true(dungeon.topology.find_path(Vector2i(2, 0), Vector2i.ZERO, world_state, &"dungeon").is_empty(), "pathfinding cannot route into blocked wall terrain")
	var diagonal_world := WorldDefinition.new([land, loaded.content.world.map_by_id("land:1")], [MapTransition.new("layout:land:0:northwest:land:1", "land:0", &"northwest", "land:1", &"southeast")])
	var diagonal_transition := diagonal_world.probe_movement("land:0", Vector2i.ZERO, Vector2i(-1, -1), world_state)
	assert_true(diagonal_transition.allowed, "a diagonal land boundary probe follows the authored Layout neighbor")
	assert_equal(diagonal_transition.target_map.id, "land:1", "diagonal Layout movement selects the diagonal map")
	assert_equal(diagonal_transition.target_coordinate, Vector2i(89, 89), "diagonal Layout movement wraps to the opposite target corner")
	var secret_probe := dungeon.topology.probe_entry(Vector2i(0, 1), Vector2i.RIGHT, world_state)
	assert_true(secret_probe.allowed, "matching directional secret passage permits entry")
	assert_equal(secret_probe.secret_id, "dungeon:0:cell:0,1:secret:east", "secret passage returns its stable overlay identity")
	assert_false(dungeon.topology.probe_entry(Vector2i(0, 1), Vector2i.UP, world_state).allowed, "nonmatching secret direction remains blocked")

	world_state.open_door(door_probe.door_id)
	world_state.mark_visited("dungeon:0", Vector2i(1, 0))
	var restored := WorldState.from_data(world_state.to_data())
	assert_not_null(restored, "world overlays serialize as typed state")
	assert_true(restored.door_is_open(door_probe.door_id), "door overlay survives serialization")
	assert_true(restored.secret_is_discovered(hidden_feature.id), "secret discovery survives serialization")
	assert_true(restored.was_visited("dungeon:0", Vector2i(1, 0)), "minimap visitation survives serialization")

static func _aggregate_party_level_error(context: SessionWorkflowContext, characters: Array[CharacterState]) -> String:
	var campaign := context.content.campaign_definition()
	if campaign == null or not campaign.guidance_authored or campaign.maximum_party_levels <= 0:
		return ""
	var current_levels := 0
	for character: CharacterState in characters:
		current_levels += character.level
	if current_levels <= campaign.maximum_party_levels:
		return ""
	return "This party's combined %d levels exceed the scenario maximum of %d." % [current_levels, campaign.maximum_party_levels]

static func field_item_target_ids(context: SessionWorkflowContext, character: CharacterState, spell: SpellDefinition, requested_targets: Array[String], requested_target: String) -> Array[String]:
	if spell.target_type == 7 or absi(spell.special) == 68:
		return []
	if spell.target_type == 5:
		return [character.id]
	if spell.target_type > 2:
		return _party_character_ids(context.state.party)
	var values: Array[String] = requested_targets.duplicate()
	if values.is_empty() and not requested_target.is_empty():
		values.append(requested_target)
	return values

static func field_spell_item_probe(context: SessionWorkflowContext, character: CharacterState, instance: ItemInstance, item: ItemDefinition, spell: SpellDefinition) -> InventoryActionProbe:
	var probe := context.rules.inventory.classic_spell_item_probe(character, instance, item, spell, context.content.race_by_id(character.race_id) if character != null else null, context.content.caste_by_id(character.caste_id) if character != null else null, false)
	if not probe.allowed:
		return probe
	if not field_spell_effect_supported(spell):
		return InventoryActionProbe.block("This item's Classic field spell effect is not implemented yet.")
	if spell.target_type < 0 or spell.target_type > 12:
		return InventoryActionProbe.block("This item's Classic field target type is invalid.")
	if spell.target_type in [3, 9] and not context.state.party.allies().is_empty():
		return InventoryActionProbe.block("This item also targets allied creatures; that Classic field branch is not implemented yet.")
	return InventoryActionProbe.permit()

static func identify_inventory(context: SessionWorkflowContext, payload: PlayerIntent.SpellPayload) -> SessionWorkflowResult:
	var probe := inventory_identify_probe(context, payload.target_id, payload.caster_id, payload.spell_id)
	if not probe.allowed:
		return SessionWorkflowResult.failed(&"inventory_identification_unavailable", probe.reason)
	var target := context.state.party.character_by_id(payload.target_id)
	var caster := context.state.party.character_by_id(payload.caster_id)
	var instance_ids: Array[String] = []
	for instance: ItemInstance in target.inventory():
		instance.identified = true
		instance_ids.append(instance.id)
	caster.spell_points -= 25
	return SessionWorkflowResult.completed([
		DomainEvent.new(&"inventory_identified", {"characterId": target.id, "casterId": caster.id, "spellId": payload.spell_id, "instanceIds": instance_ids, "cost": 25, "source": "classic-items"}),
		DomainEvent.new(&"sound_requested", {"soundId": 683, "waitForCompletion": false, "source": "classic-items-identify"}),
	])

func project(context: SessionWorkflowContext, pending_interaction: InteractionRequest, revision: int, started: bool, events: Array[DomainEvent] = []) -> GameView:
	if _cached_view != null and _cached_view.revision == revision:
		return _cached_view
	if not started:
		_cached_view = GameView.new(revision, false, null)
		return _cached_view
	if _can_project_ordinary_movement(context, pending_interaction, events):
		_cached_view = _project_ordinary_movement(context, revision)
		return _cached_view
	_cached_view = _project_complete(context, pending_interaction, revision)
	return _cached_view

func _can_project_ordinary_movement(context: SessionWorkflowContext, pending_interaction: InteractionRequest, events: Array[DomainEvent]) -> bool:
	if _cached_view == null or pending_interaction != null or _cached_view.pending_interaction != null or _cached_view.combat_view != null or events.is_empty():
		return false
	if _cached_view.party_map_id != context.state.party.map_id:
		return false
	var moved_count := 0
	for event: DomainEvent in events:
		match event.kind:
			&"party_moved":
				if event.payload.has("source"):
					return false
				if String(event.payload.get("fromMapId", "")) != _cached_view.party_map_id or String(event.payload.get("mapId", "")) != context.state.party.map_id:
					return false
				var origin := Vector2i(int(event.payload.get("fromX", -100000)), int(event.payload.get("fromY", -100000)))
				var destination := Vector2i(int(event.payload.get("x", -100000)), int(event.payload.get("y", -100000)))
				var delta := destination - origin
				if origin != _cached_view.party_coordinate or destination != context.state.party.coordinate or delta == Vector2i.ZERO or absi(delta.x) > 1 or absi(delta.y) > 1:
					return false
				moved_count += 1
			&"time_advanced": pass
			&"fatigue_changed":
				if String(event.payload.get("source", "")) != "classic" or String(event.payload.get("reason", "")) != "hour-boundary" or int(event.payload.get("current", -1)) != context.state.party.fatigue:
					return false
			&"random_encounter_checked":
				if bool(event.payload.get("triggered", false)):
					return false
			_:
				return false
	return moved_count == 1

static func _first_empty_scroll_slot(character: CharacterState) -> int:
	if character == null:
		return -1
	for index: int in character.scroll_case().size():
		if character.scroll_at(index).is_empty():
			return index
	return -1

func _test_public_magic_matrix() -> void:
	var rules := RealmzRules.new()
