static func from_data(data: Variant) -> PresentationSettings:
	if not data is Dictionary:
		return null
	var schema_value: Variant = data.get("schemaVersion")
	if not schema_value is int and not schema_value is float:
		return null
	var schema_version := int(schema_value)
	if float(schema_version) != float(schema_value):
		return null
	if data.get("kind") != "realmz2.presentation-settings" or schema_version not in [1, 2, 3, 4, 5, 6, 7, SCHEMA_VERSION]:
		return null
	if not data.get("masterVolume") is float or not data.get("topologyDebug") is bool or not data.get("textScale") is float or not data.get("reducedMotion") is bool:
		return null
	if schema_version >= 2 and not data.get("dungeon3d") is bool:
		return null
	if schema_version >= 3:
		if not data.get("uiScaleMode") is String or not data.get("windowMode") is String:
			return null
		if data["uiScaleMode"] not in [UI_SCALE_AUTO, UI_SCALE_100, UI_SCALE_125, UI_SCALE_150]:
			return null
		if data["windowMode"] not in [WINDOWED, BORDERLESS_FULLSCREEN]:
			return null
	if schema_version >= 4 and not data.get("autoSwitchToMelee") is bool:
		return null
	if schema_version >= 5:
		var speed_value: Variant = data.get("explorationSpeedPercent")
		if not speed_value is int and not speed_value is float:
			return null
		var speed := int(speed_value)
		if float(speed) != float(speed_value) or speed < 25 or speed > 400 or speed % 25 != 0:
			return null
	if schema_version >= 6 and (not data.get("showExplorationMinimap") is bool or not data.get("autojournalEnabled") is bool):
		return null
	if schema_version >= 7:
		if not data.get("typographyMode") is String or data["typographyMode"] not in [TYPOGRAPHY_CLASSIC, TYPOGRAPHY_READABLE]:
			return null
	if schema_version == SCHEMA_VERSION:
		if not data.get("soundVolume") is float or not data.get("musicVolume") is float or not data.get("musicEnabled") is bool or not data.get("musicPlaylistModes") is Array:
			return null
		if float(data["soundVolume"]) < 0.0 or float(data["soundVolume"]) > 1.0 or float(data["musicVolume"]) < 0.0 or float(data["musicVolume"]) > 1.0:
			return null
		var modes := data["musicPlaylistModes"] as Array
		if modes.size() != MUSIC_SLOT_COUNT:
			return null
		for mode: Variant in modes:
			if (not mode is int and not mode is float) or float(int(mode)) != float(mode) or int(mode) not in [MUSIC_OFF, MUSIC_PLAY, MUSIC_CONTINUE]:
				return null
	var volume: float = data["masterVolume"]
	var scale: float = data["textScale"]
	if volume < 0.0 or volume > 1.0 or scale < 0.8 or scale > 1.5:
		return null
	var settings := PresentationSettings.new()
	settings.master_volume = volume
	settings.sound_volume = float(data.get("soundVolume", 1.0))
	settings.music_volume = float(data.get("musicVolume", 0.8))
	settings.music_enabled = bool(data.get("musicEnabled", true))
	settings.music_playlist_modes = _music_modes_from_data(data.get("musicPlaylistModes", []))
	settings.topology_debug = data["topologyDebug"]
	settings.text_scale = scale
	settings.reduced_motion = data["reducedMotion"]
	settings.auto_switch_to_melee = bool(data.get("autoSwitchToMelee", true))
	settings.dungeon_3d = bool(data.get("dungeon3d", false))
	settings.ui_scale_mode = String(data.get("uiScaleMode", UI_SCALE_AUTO))
	settings.window_mode = String(data.get("windowMode", WINDOWED))
	settings.exploration_speed_percent = int(data.get("explorationSpeedPercent", 100))
	settings.show_exploration_minimap = bool(data.get("showExplorationMinimap", false))
	settings.autojournal_enabled = bool(data.get("autojournalEnabled", true))
	settings.typography_mode = String(data.get("typographyMode", TYPOGRAPHY_CLASSIC))
	return settings

func set_music_mode(playlist_id: int, mode: int) -> bool:
	if playlist_id < 1 or playlist_id > MUSIC_SLOT_COUNT or mode not in [MUSIC_OFF, MUSIC_PLAY, MUSIC_CONTINUE]:
		return false
	music_playlist_modes[playlist_id - 1] = mode
	return true

static func _music_modes_from_data(value: Variant) -> Array[int]:
	if not value is Array or (value as Array).size() != MUSIC_SLOT_COUNT:
		return _default_music_modes()
	var result: Array[int] = []
	for mode: Variant in value as Array:
		result.append(int(mode))
	return result

static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1

func region_for(tile_id: int) -> Rect2i:
	if not is_tileset() and not is_battle_tileset():
		return Rect2i()
	var atlas_index := maxi(tile_id - 1, 0)
	if atlas_index >= columns * rows:
		return Rect2i()
	return Rect2i((atlas_index % columns) * tile_width, floori(float(atlas_index) / float(columns)) * tile_height, tile_width, tile_height)

func read_bytes_batch(requested_assets: Array[MediaAsset]) -> Dictionary:
	var result: Dictionary = {}
	for asset: MediaAsset in requested_assets:
		result[asset.id] = read_bytes(asset)
	return result

func _init(state_value: int, completed_draws: int) -> void:
	generator_state = state_value
	draw_count = completed_draws

static func from_data(data: Variant) -> RealmzRngState:
	if not data is Dictionary or not data.has("generatorState") or not data.has("drawCount"):
		return null
	var generator := _integer(data["generatorState"])
	var draws := _integer(data["drawCount"])
	if generator < 0 or draws < 0:
		return null
	if generator <= 0 or generator >= RealmzRng.MODULUS:
		return null
	return RealmzRngState.new(generator, draws)

static func _roll_weapon_elements_character(weapon: ItemDefinition, defender: CharacterState, rng: RealmzRng, effects: Array[Dictionary]) -> int:
	var total := 0
	var ranges: Array[int] = [weapon.heat, weapon.cold, weapon.electric]
	var names: Array[StringName] = [&"fire", &"cold", &"electrical"]
	var save_indexes: Array[int] = [1, 2, 3]
	var conditions: Array[int] = [ConditionRules.FIRE_PROTECTION, ConditionRules.COLD_PROTECTION, ConditionRules.ELECTRICAL_PROTECTION]
	for index: int in 3:
		if ranges[index] == 0:
			continue
		var rolled := rng.draw(ranges[index], StringName("combat.attack.weapon-%s" % names[index]))
		var save_roll := rng.draw(100, StringName("combat.attack.weapon-%s-save" % names[index]))
		var save_chance := defender.save_value(save_indexes[index])
		var saved := save_roll <= save_chance
		var effective := int(float(rolled) / 2.0) if saved else rolled
		var protected := defender.conditions.is_active(conditions[index])
		if protected:
			effective = int(float(effective) / 2.0)
		effects.append({"element": String(names[index]), "rolled": rolled, "saveIndex": save_indexes[index], "saveChance": save_chance, "saveRoll": save_roll, "saved": saved, "protected": protected, "amount": effective})
		total += effective
	return total

func _roll_weapon_elements_monster(weapon: ItemDefinition, defender: MonsterState, defender_definition: MonsterDefinition, rng: RealmzRng, effects: Array[Dictionary]) -> int:
	var total := 0
	var ranges: Array[int] = [weapon.heat, weapon.cold, weapon.electric]
	var names: Array[StringName] = [&"fire", &"cold", &"electrical"]
	var save_indexes: Array[int] = [1, 2, 3]
	var conditions: Array[int] = [ConditionRules.FIRE_PROTECTION, ConditionRules.COLD_PROTECTION, ConditionRules.ELECTRICAL_PROTECTION]
	for index: int in 3:
		if ranges[index] == 0 or defender_definition.spell_immune(save_indexes[index]):
			continue
		var rolled := rng.draw(ranges[index], StringName("combat.attack.weapon-%s" % names[index]))
		var effective := rolled
		var protected := defender.conditions.is_active(conditions[index])
		if protected:
			effective = int(float(effective) / 2.0)
		var save_roll := rng.draw(100, StringName("combat.attack.weapon-%s-save" % names[index]))
		var save_chance := _monster_save_chance(defender, defender_definition, save_indexes[index])
		var saved := _monster_saved(defender, defender_definition, save_indexes[index], save_roll, save_chance)
		if saved:
			effective = int(float(effective) / 2.0)
		effects.append({"element": String(names[index]), "rolled": rolled, "saveIndex": save_indexes[index], "saveChance": save_chance, "saveRoll": save_roll, "saved": saved, "protected": protected, "amount": effective})
		total += effective
	return total

func resolve_monster_attack(attacker: MonsterState, attacker_definition: MonsterDefinition, attack_index: int, defender: CharacterState, race: RaceDefinition, caste: CasteDefinition, rng: RealmzRng, charm_save_bonus: int = 0, context: MonsterAttackContext = null, allow_fumbles: bool = false) -> AttackResolution:
	if attacker == null or attacker_definition == null or defender == null or rng == null:
		return null
	var attack_context := context if context != null else MonsterAttackContext.new(null, 0, false, defender.luck)
	var invalid_weapon := _invalid_weapon_reason(attack_context.attacker_weapon)
	if not invalid_weapon.is_empty():
		return _blocked_monster_attack(invalid_weapon)
	var condition_roll := _roll_weapon_condition_character(attack_context.attacker_weapon, defender, rng)
	if condition_roll.get("blocked", false):
		return _blocked_monster_attack(StringName(condition_roll.get("reason", "invalid_weapon_condition")))
	var chance := _monster_attack_base_chance(attacker, attacker_definition, attack_context)
	chance += _attacker_condition_modifier(attacker.conditions)
	if attacker.conditions.is_active(ConditionRules.PROTECTION_FROM_EVIL):
		chance += 10
	chance -= rng.draw_classic(attack_context.defender_luck, &"combat.monster-attack.defender-luck")
	chance -= attack_context.defender_armor if attack_context.defender_armor >= 0 else defender.armor
	chance += _defender_condition_modifier(defender.conditions, false)
	if attacker_definition.type_flag(4) and defender.conditions.is_active(ConditionRules.PROTECTION_FROM_EVIL):
		chance -= 10
	chance = maxi(10, chance)
	var roll := rng.draw(100, &"combat.monster-attack.hit")
	var hit := roll <= chance or _monster_weapon_auto_hits(attack_context.attacker_weapon)
	var helpless := defender.conditions.is_active(ConditionRules.HELPLESS)
	if helpless:
		hit = true
	var fumble_roll := _monster_fumble_roll(attacker, rng, allow_fumbles)
	if _monster_fumbled(attack_context.attacker_weapon, fumble_roll):
		return _fumbled_attack(chance, roll, fumble_roll)
	if not hit:
		return _with_monster_fumble_roll(AttackResolution.new(false, false, chance, roll, 0), fumble_roll)
	var attacks := attacker_definition.attacks()
	var attack := _monster_attack_row(attacks, attack_index)
	var damage := attacker_definition.damage_bonus + attacker.conditions.value(ConditionRules.ATTACK_BONUS)
	if attacker.conditions.is_active(ConditionRules.STRONG):
		damage += 3
	var effects: Array[Dictionary] = []
	var elemental_damage := 0
	if helpless:
		damage = defender.current_health + rng.draw(10, &"combat.monster-attack.helpless-damage")
	elif attack_context.attacker_weapon != null:
		damage += attack_context.attacker_weapon.damage_bonus
		damage += rng.draw(maxi(1, attack_context.attacker_weapon.vs_small), &"combat.monster-attack.weapon-physical")
		elemental_damage = _roll_weapon_elements_character(attack_context.attacker_weapon, defender, rng, effects)
	else:
		damage += rng.draw_between(attack.damage_min, attack.damage_max, &"combat.monster-attack.damage")
	damage = maxi(0, damage)
	var resolution_physical_damage_reduction := 0
	if attack_context.party_dragon_hide and damage > 1:
		var damage_before_dragon_hide := damage
		damage = maxi(1, damage - 5)
		resolution_physical_damage_reduction = damage_before_dragon_hide - damage
	var resolution := AttackResolution.new(true, defender.current_health - damage - elemental_damage <= 0, chance, roll, damage + elemental_damage)
	_with_monster_fumble_roll(resolution, fumble_roll)
	resolution.physical_damage = damage
	resolution.physical_damage_reduction = resolution_physical_damage_reduction
	resolution.physical_feedback_sound_id = 694 if resolution_physical_damage_reduction > 0 else 0
	resolution.weapon_effects = effects
	if attack.special != 0:
		resolution.special_code = attack.special
		var potency_low := int(float(attacker.hit_dice) / 2.0)
		resolution.special_potency = maxi(1, rng.draw_between(potency_low, attacker.hit_dice, &"combat.monster-attack.special-potency"))
	if _is_status_special(attack.special):
		_apply_party_status_special(resolution, defender, rng)
	elif _is_resource_special(attack.special):
		_apply_party_resource_special(resolution, attacker, defender, rng)
	elif attack.special == 10:
		_apply_party_charm_special(resolution, attacker, defender, rng, charm_save_bonus)
	elif _is_elemental_special(attack.special):
		_apply_party_elemental_special(resolution, attack, defender, rng)
	elif attack.special == 17:
		resolution.special_handled = true
		resolution.special_save_index = 7
		resolution.special_save_chance = defender.save_value(7)
		resolution.special_save_roll = rng.draw(100, &"combat.monster-attack.special-save")
		resolution.special_saved = resolution.special_save_roll <= resolution.special_save_chance
		if not resolution.special_saved:
			resolution.special_applied = true
			var age_factor := _signed_16(attack.damage_max * attacker.hit_dice)
			resolution.special_age_days = int(float(race.max_age) * 0.01 * float(age_factor)) if race != null else 0
			if race != null and caste != null:
				resolution.aging = _characters.advance_age_days(defender, race, caste, resolution.special_age_days)
	elif attack.special in [18, 19]:
		_apply_party_permanent_affliction(resolution, defender, rng)
	resolution.damage_deferred = resolution.aging != null and resolution.aging.changed_group()
	if resolution.damage_deferred:
		_record_weapon_condition_character(defender, condition_roll, resolution)
	else:
		_apply_weapon_condition_character(defender, condition_roll, resolution)
	if not resolution.damage_deferred and not resolution.physical_damage_skipped:
		defender.current_health -= damage + elemental_damage + resolution.special_damage_amount
		resolution.killed = defender.current_health <= 0
	return resolution

func _init(condition_rules: ConditionRules, character_rules: CharacterRules) -> void:
	_conditions = condition_rules
	_characters = character_rules

func resolve_character_attack(attacker: CharacterState, equipment: CharacterCombatEquipment, defender: MonsterState, defender_definition: MonsterDefinition, rng: RealmzRng, realmz_day: int = 0, behind: bool = false, allow_fumbles: bool = false, can_queue_fumble: bool = true) -> AttackResolution:
	if attacker == null or equipment == null or not equipment.valid or defender == null or defender_definition == null or rng == null:
		return null
	var invalid_weapon := _invalid_weapon_reason(equipment.melee_weapon)
	if not invalid_weapon.is_empty():
		return _blocked_character_attack(invalid_weapon)
	var condition_roll := _roll_weapon_condition_monster(equipment.melee_weapon, defender, defender_definition, rng)
	if condition_roll.get("blocked", false):
		return _blocked_character_attack(StringName(condition_roll.get("reason", "invalid_weapon_condition")))
	var type_damage := 0
	var chance := 50 + attacker.to_hit + (20 if behind else 0) + 5 * equipment.equipped_damage_bonus
	if equipment.melee_weapon != null and equipment.melee_weapon.special_1 == 121:
		chance += 5 * equipment.melee_weapon.damage_bonus
	chance += _attacker_condition_modifier(attacker.conditions)
	if defender_definition.type_flag(4) and attacker.conditions.is_active(ConditionRules.PROTECTION_FROM_EVIL):
		chance += 10
	chance += rng.draw_classic(equipment.effective_luck, &"combat.attack.luck")
	for index: int in 8:
		if defender_definition.type_flag(index):
			chance += 5 * attacker.special_value(index)
			type_damage += attacker.special_value(index)
	chance -= defender.armor
	chance += _defender_condition_modifier(defender.conditions, true)
	chance -= int(float(maxi(0, realmz_day)) / 120.0)
	chance = maxi(5, chance)
	var roll := rng.draw(100, &"combat.attack.hit")
	var hit := roll <= chance or defender.conditions.is_active(ConditionRules.HELPLESS)
	var fumble := _character_fumble(attacker, equipment, rng, allow_fumbles, can_queue_fumble)
	if fumble.get("fumbled", false):
		return _fumbled_attack(chance, roll, int(fumble["roll"]))
	var magic_requirement := _magic_weapon_requirement_reason(attacker, equipment, defender_definition, hit)
	if not magic_requirement.is_empty():
		return _with_fumble_observation(_blocked_character_attack(magic_requirement, chance, roll), fumble)
	var weapon_requirement := _required_weapon_reason(equipment, defender_definition, hit)
	if not weapon_requirement.is_empty():
		return _with_fumble_observation(_blocked_character_attack(weapon_requirement, chance, roll), fumble)
	if equipment.melee_weapon != null and equipment.melee_weapon.special_1 == 120:
		hit = true
	if not hit:
		return _with_fumble_observation(AttackResolution.new(false, false, chance, roll, 0), fumble)
	var reflected := defender.conditions.is_active(ConditionRules.REFLECTING_ATTACKS) and rng.draw(100, &"combat.attack.reflect") < 34
	var physical_damage := type_damage + equipment.effective_damage_bonus + attacker.conditions.value(ConditionRules.ATTACK_BONUS)
	if attacker.conditions.is_active(ConditionRules.STRONG):
		physical_damage += 3
	var effects: Array[Dictionary] = []
	var elemental_damage := 0
	if equipment.is_armed():
		if reflected:
			elemental_damage = _roll_weapon_elements_character(equipment.melee_weapon, attacker, rng, effects)
		else:
			elemental_damage = _roll_weapon_elements_monster(equipment.melee_weapon, defender, defender_definition, rng, effects)
		physical_damage += _roll_weapon_physical(equipment.melee_weapon, defender_definition if not reflected else null, rng)
	else:
		physical_damage += rng.draw(maxi(1, attacker.hand_to_hand), &"combat.attack.unarmed-damage")
	var critical_rolls: Array[int] = [rng.draw(100, &"combat.attack.sneak-critical"), rng.draw(100, &"combat.attack.major-wound-critical")]
	physical_damage = maxi(0, physical_damage)
	if not reflected and defender.conditions.is_active(ConditionRules.HELPLESS):
		physical_damage = defender.current_health
	elif reflected and attacker.conditions.is_active(ConditionRules.HELPLESS):
		physical_damage = attacker.current_health
	var total_damage := physical_damage + elemental_damage
	var resolution := AttackResolution.new(true, false, chance, roll, total_damage, reflected)
	_with_fumble_observation(resolution, fumble)
	resolution.physical_damage = physical_damage
	resolution.weapon_effects = effects
	resolution.critical_rolls = critical_rolls
	if reflected:
		_apply_weapon_condition_character(attacker, condition_roll, resolution)
		attacker.current_health -= total_damage
		resolution.killed = attacker.current_health <= 0
		return resolution
	_apply_weapon_condition_monster(defender, condition_roll, resolution)
	defender.current_health -= total_damage
	resolution.killed = defender.current_health <= 0
	return resolution

func resolve_character_attack_character(attacker: CharacterState, attacker_equipment: CharacterCombatEquipment, defender: CharacterState, defender_equipment: CharacterCombatEquipment, rng: RealmzRng, behind: bool = false, allow_fumbles: bool = false, can_queue_fumble: bool = true) -> AttackResolution:
	if attacker == null or attacker_equipment == null or not attacker_equipment.valid or defender == null or defender_equipment == null or not defender_equipment.valid or rng == null:
		return null
	var invalid_weapon := _invalid_weapon_reason(attacker_equipment.melee_weapon)
	if not invalid_weapon.is_empty():
		return _blocked_character_attack(invalid_weapon)
	var condition_roll := _roll_weapon_condition_character(attacker_equipment.melee_weapon, defender, rng)
	if condition_roll.get("blocked", false):
		return _blocked_character_attack(StringName(condition_roll.get("reason", "invalid_weapon_condition")))
	var chance := 50 + attacker.to_hit + (20 if behind else 0) + 5 * attacker_equipment.equipped_damage_bonus
	if attacker_equipment.melee_weapon != null and attacker_equipment.melee_weapon.special_1 == 121:
		chance += 5 * attacker_equipment.melee_weapon.damage_bonus
	chance += _attacker_condition_modifier(attacker.conditions)
	chance += rng.draw_classic(attacker_equipment.effective_luck, &"combat.attack.luck")
	chance -= defender_equipment.effective_armor
	chance += _defender_condition_modifier(defender.conditions, false)
	chance = maxi(5, chance)
	var roll := rng.draw(100, &"combat.attack.hit")
	var hit := roll <= chance or defender.conditions.is_active(ConditionRules.HELPLESS)
	var fumble := _character_fumble(attacker, attacker_equipment, rng, allow_fumbles, can_queue_fumble)
	if fumble.get("fumbled", false):
		return _fumbled_attack(chance, roll, int(fumble["roll"]))
	if attacker_equipment.melee_weapon != null and attacker_equipment.melee_weapon.special_1 == 120:
		hit = true
	if not hit:
		return _with_fumble_observation(AttackResolution.new(false, false, chance, roll, 0), fumble)
	var reflected := defender.conditions.is_active(ConditionRules.REFLECTING_ATTACKS) and rng.draw(100, &"combat.attack.reflect") < 34
	var target := attacker if reflected else defender
	var physical_damage := attacker_equipment.effective_damage_bonus + attacker.conditions.value(ConditionRules.ATTACK_BONUS)
	if attacker.conditions.is_active(ConditionRules.STRONG):
		physical_damage += 3
	var effects: Array[Dictionary] = []
	var elemental_damage := 0
	if attacker_equipment.is_armed():
		elemental_damage = _roll_weapon_elements_character(attacker_equipment.melee_weapon, target, rng, effects)
		physical_damage += _roll_weapon_physical(attacker_equipment.melee_weapon, null, rng)
	else:
		physical_damage += rng.draw(maxi(1, attacker.hand_to_hand), &"combat.attack.unarmed-damage")
	var critical_rolls: Array[int] = [rng.draw(100, &"combat.attack.sneak-critical"), rng.draw(100, &"combat.attack.major-wound-critical")]
	physical_damage = maxi(0, physical_damage)
	if target.conditions.is_active(ConditionRules.HELPLESS):
		physical_damage = target.current_health
	var total_damage := physical_damage + elemental_damage
	var resolution := AttackResolution.new(true, false, chance, roll, total_damage, reflected)
	_with_fumble_observation(resolution, fumble)
	resolution.physical_damage = physical_damage
	resolution.weapon_effects = effects
	resolution.critical_rolls = critical_rolls
	_apply_weapon_condition_character(target, condition_roll, resolution)
	target.current_health -= total_damage
	resolution.killed = target.current_health <= 0
	return resolution

static func _character_fumble(attacker: CharacterState, equipment: CharacterCombatEquipment, rng: RealmzRng, allow_fumbles: bool, can_queue_fumble: bool) -> Dictionary:
	if not allow_fumbles:
		return {}
	var roll := rng.draw(1000 + 100 * attacker.level, &"combat.attack.fumble")
	if roll <= 50 or roll >= 60 or not equipment.is_armed():
		return {"roll": roll}
	if not equipment.melee_weapon.cursed_item_id.is_empty():
		return {"roll": roll, "blockedReason": &"cursed_weapon"}
	if not can_queue_fumble:
		return {"roll": roll, "blockedReason": &"fumble_queue_full"}
	return {"roll": roll, "fumbled": true}

static func _magic_weapon_requirement_reason(attacker: CharacterState, equipment: CharacterCombatEquipment, defender: MonsterDefinition, hit: bool) -> StringName:
	if defender.magic_to_hit <= 0:
		return &""
	if equipment.is_armed():
		if hit and defender.magic_to_hit > equipment.melee_weapon.damage_bonus:
			return &"classic_magic_weapon_required"
		return &""
	if defender.magic_to_hit > attacker.level / 8:
		return &"classic_magic_weapon_required"
	return &""

static func _required_weapon_reason(equipment: CharacterCombatEquipment, defender: MonsterDefinition, hit: bool) -> StringName:
	if not hit or defender.required_weapon == 0:
		return &""
	if not equipment.is_armed():
		if defender.required_weapon == -1:
			return &"classic_blunt_weapon_required"
		if defender.required_weapon == -2:
			return &"classic_sharp_weapon_required"
		return &"classic_specific_weapon_required"
	if defender.required_weapon == -1:
		return &"" if equipment.melee_weapon.blunt == -1 else &"classic_blunt_weapon_required"
	if defender.required_weapon == -2:
		return &"" if equipment.melee_weapon.blunt == -2 else &"classic_sharp_weapon_required"
	# FD-COMBAT-003: Castle's minus-1024 comparison cannot match the shipped
	# 1..999 item IDs. Divinity defines this byte as the ordinary Item Number.
	var required_item_id := defender.required_weapon & 0xff
	return &"" if equipment.melee_weapon.classic_id == required_item_id else &"classic_specific_weapon_required"

static func _invalid_weapon_reason(weapon: ItemDefinition) -> StringName:
	if weapon == null:
		return &""
	if weapon.vs_small < 0 or weapon.vs_large < 0 or weapon.heat < 0 or weapon.cold < 0 or weapon.electric < 0 or weapon.vs_undead < 0 or weapon.vs_demon_devil < 0 or weapon.vs_evil < 0:
		return &"unsupported_negative_weapon_range"
	if weapon.special_1 == -10:
		if weapon.special_3 < 20 or weapon.special_3 >= 60:
			return &"invalid_weapon_condition"
		if weapon.special_2 == 1 and (weapon.special_4 < 0 or weapon.special_4 >= 8):
			return &"invalid_weapon_condition_save"
	return &""

func _roll_weapon_condition_monster(weapon: ItemDefinition, defender: MonsterState, defender_definition: MonsterDefinition, rng: RealmzRng) -> Dictionary:
	if weapon == null or weapon.special_1 != -10:
		return {}
	var result := {"index": weapon.special_3 - 20, "amount": weapon.special_5, "applies": false}
	match weapon.special_2:
		1:
			var roll := rng.draw(100, &"combat.attack.weapon-condition-save")
			var chance := _monster_save_chance(defender, defender_definition, weapon.special_4)
			result["saveIndex"] = weapon.special_4
			result["saveChance"] = chance
			result["saveRoll"] = roll
			result["applies"] = not _monster_saved(defender, defender_definition, weapon.special_4, roll, chance)
		2:
			var roll := rng.draw(100, &"combat.attack.weapon-condition-chance")
			result["chance"] = weapon.special_4
			result["roll"] = roll
			result["applies"] = roll <= weapon.special_4
		_:
			result["applies"] = true
	return result

static func _monster_save_chance(monster: MonsterState, definition: MonsterDefinition, save_index: int) -> int:
	if save_index == 7:
		var total := 0
		for index: int in 6:
			total += monster.save_value(index) if monster.has_runtime_saves() else definition.save_value(index)
		return int(float(total) / 6.0)
	return (monster.save_value(save_index - 1) if monster.has_runtime_saves() else definition.save_value(save_index - 1)) if save_index > 0 else 0

func _agility(id: String, characters: Array[CharacterState], monsters: Array[MonsterState]) -> int:
	for character: CharacterState in characters:
		if character.id == id:
			return character.agility
	for monster: MonsterState in monsters:
		if monster.id == id:
			return monster.agility
	return 0

func _party_first(order: Array[String], characters: Array[CharacterState]) -> Array[String]:
	var party_ids: Dictionary = {}
	for character: CharacterState in characters:
		party_ids[character.id] = true
	var first: Array[String] = []
	var last: Array[String] = []
	for id: String in order:
		if party_ids.has(id):
			first.append(id)
		else:
			last.append(id)
	first.append_array(last)
	return first

func _monsters_first(order: Array[String], monsters: Array[MonsterState]) -> Array[String]:
	var monster_ids: Dictionary = {}
	for monster: MonsterState in monsters:
		monster_ids[monster.id] = true
	var first: Array[String] = []
	var last: Array[String] = []
	for id: String in order:
		if monster_ids.has(id):
			first.append(id)
		else:
			last.append(id)
	first.append_array(last)
	return first

static func _monster_saved(_monster: MonsterState, definition: MonsterDefinition, save_index: int, roll: int, chance: int) -> bool:
	if save_index < 6 and definition.spell_immune(save_index):
		return true
	if save_index > 0 and roll <= chance:
		return true
	return definition.type_flag(1) and save_index in [0, 4, 5]

func initiative_order(characters: Array[CharacterState], monsters: Array[MonsterState], surprise: int, rng: RealmzRng) -> Array[String]:
	var order: Array[String] = []
	for character: CharacterState in characters:
		if character.current_health > 0:
			order.append(character.id)
	for monster: MonsterState in monsters:
		if monster.current_health > 0:
			order.append(monster.id)
	if surprise > 0:
		return _party_first(order, characters)
	if surprise < 0:
		return _monsters_first(order, monsters)
	for index: int in range(order.size() - 1, 0, -1):
		var swap_index := rng.draw_between(0, index, &"combat.initiative.slot")
		var held := order[index]
		order[index] = order[swap_index]
		order[swap_index] = held
	for left: int in order.size():
		for right: int in range(left, order.size() - 1):
			if _agility(order[right + 1], characters, monsters) > _agility(order[right], characters, monsters):
				var held := order[right]
				order[right] = order[right + 1]
				order[right + 1] = held
	return order

func _commit_reaction_move(state: GameState, content: RealmzContent, reaction: CombatReactionState, events: Array[DomainEvent]) -> bool:
	var combat := state.combat
	if combat == null or combat.battlefield == null or not _combatant_is_alive(state, reaction.mover_id) or combat.battlefield.actor_position(reaction.mover_id) != reaction.origin:
		return false
	var movement_remaining := 0
	if reaction.kind == CombatReactionState.CHARACTER_MOVE:
		if state.party.character_by_id(reaction.mover_id) == null:
			return false
	else:
		if combat.active_turn == null or combat.active_turn.actor_id != reaction.mover_id:
			return false
	if not combat.battlefield.move_actor(reaction.mover_id, reaction.destination):
		return false
	if reaction.kind == CombatReactionState.CHARACTER_MOVE:
		var character := state.party.character_by_id(reaction.mover_id)
		character.movement = maxi(0, character.movement - reaction.movement_cost)
		movement_remaining = character.movement
	else:
		combat.active_turn.movement_remaining = maxi(0, combat.active_turn.movement_remaining - reaction.movement_cost)
		movement_remaining = combat.active_turn.movement_remaining
	events.append(DomainEvent.new(&"combatant_moved", {
		"actorId": reaction.mover_id,
		"from": [reaction.origin.x, reaction.origin.y],
		"to": [reaction.destination.x, reaction.destination.y],
		"cost": reaction.movement_cost,
		"movementRemaining": movement_remaining,
		"automatic": reaction.kind != CombatReactionState.CHARACTER_MOVE or _flow().is_processing_auto(),
	}))
	var terrain_set: BattleTerrainSetDefinition = _flow()._battle_terrain_set(content, combat.battlefield)
	var terrain: BattleTerrainTileDefinition = terrain_set.tile_by_id(combat.battlefield.terrain_at(reaction.destination)) if terrain_set != null else null
	if terrain != null and terrain.sound != 0:
		events.append(DomainEvent.new(&"sound_requested", {"soundId": terrain.sound, "waitForCompletion": terrain.sound < 0, "source": "classic-battle-movement"}))
	if reaction.kind == CombatReactionState.MONSTER_RETREAT and _flow()._retreating_monster_reached_edge(state, content, reaction.mover_id, reaction.destination, events):
		reaction.set_phase(CombatReactionState.GUARD_AFTER, [])
		return true
	reaction.set_phase(CombatReactionState.GUARD_AFTER, _guarding_hostiles(state, reaction.mover_id))
	return true

func _resolve_monster_reaction(state: GameState, content: RealmzContent, attacker: MonsterState, target_id: String, action: StringName, behind: bool, rng: RealmzRng, events: Array[DomainEvent]) -> int:
	var combat := state.combat
	combat.invalidate_undo()
	var definition := content.monster_by_id(attacker.definition_id)
	if definition == null:
		return REACTION_COMPLETED
	_flow()._prepare_monster_melee_weapon(attacker, definition, content)
	var weapon := content.item_by_id(attacker.weapon_id) if not attacker.weapon_id.is_empty() else null
	var character_target := state.party.character_by_id(target_id)
	if character_target != null:
		var race := content.race_by_id(character_target.race_id)
		var caste := content.caste_by_id(character_target.caste_id)
		var charm_bonus := 50 if state.party.conditions.is_active(ConditionRules.PARTY_CHARM_RESISTANCE) else 0
		var defender_equipment := _rules.inventory.combat_equipment(character_target, content.item_definitions())
		var defender_luck := defender_equipment.effective_luck if defender_equipment.valid else character_target.luck
		var defender_armor := defender_equipment.effective_armor if defender_equipment.valid else character_target.armor
		var reaction_context := MonsterAttackContext.new(weapon, state.clock.day(), behind, defender_luck, state.party.conditions.is_active(ConditionRules.PARTY_DRAGON_HIDE), defender_armor)
		var reaction_resolution := _rules.combat.resolve_monster_attack(attacker, definition, 0, character_target, race, caste, rng, charm_bonus, reaction_context, true)
		if reaction_resolution.total_damage() > 0:
			combat.mark_attacked(character_target.id)
		if reaction_resolution.fumbled:
			_flow()._commit_monster_fumble(attacker, events)
		if reaction_resolution.special_handled:
			_flow()._append_monster_special_events(events, attacker.id, character_target.id, &"character", reaction_resolution)
			if reaction_resolution.aging != null and reaction_resolution.aging.changed_group():
				events.append(DomainEvent.new(&"character_age_changed", reaction_resolution.aging.event_payload(character_target, race)))
				combat.pending_monster_attack = PendingMonsterAttack.new(attacker.id, character_target.id, action, reaction_resolution.damage, reaction_resolution.chance, reaction_resolution.roll, reaction_resolution.weapon_condition_index, reaction_resolution.weapon_condition_before, reaction_resolution.weapon_condition_after, reaction_resolution.physical_feedback_sound_id)
				return REACTION_WAITING
		_flow()._append_monster_physical_feedback(events, reaction_resolution.physical_feedback_sound_id)
		_flow()._append_monster_attack_audio(events, attacker, definition, 0, weapon, reaction_resolution, rng)
		var reaction_event := DomainEvent.new(&"combat_attack_resolved", {"actorId": attacker.id, "targetId": character_target.id, "targetKind": "character", "action": String(action), "attackIndex": 0, "hit": reaction_resolution.hit, "damage": reaction_resolution.total_damage(), "defeated": reaction_resolution.killed, "chance": reaction_resolution.chance, "roll": reaction_resolution.roll})
		_flow()._append_physical_result_effect(reaction_event, reaction_resolution.hit, weapon != null)
		_append_reaction_identity(reaction_event, action, behind)
		events.append(reaction_event)
		if reaction_resolution.killed:
			combat.pending_reaction.mover_killed = true
			_flow()._mark_character_bleeding(state, character_target, true)
			_flow()._remove_defeated_position(combat, character_target.id, true)
			return REACTION_MOVER_DEFEATED
		return REACTION_COMPLETED
	var monster_target := combat.monster_by_id(target_id)
	if monster_target == null:
		return REACTION_COMPLETED
	var target_definition := content.monster_by_id(monster_target.definition_id)
	var context := MonsterAttackContext.new(weapon, state.clock.day(), behind)
	var resolution := _rules.combat.resolve_monster_attack_monster(attacker, definition, 0, monster_target, target_definition, rng, context, true)
	if resolution.total_damage() > 0:
		combat.mark_attacked(monster_target.id)
	if resolution.fumbled:
		_flow()._commit_monster_fumble(attacker, events)
	if resolution.special_handled:
		_flow()._append_monster_special_events(events, attacker.id, monster_target.id, &"monster", resolution)
	_flow()._append_monster_attack_audio(events, attacker, definition, 0, weapon, resolution, rng)
	var event := DomainEvent.new(&"combat_attack_resolved", {"actorId": attacker.id, "targetId": monster_target.id, "targetKind": "monster", "action": String(action), "attackIndex": 0, "hit": resolution.hit, "damage": resolution.total_damage(), "defeated": resolution.killed, "chance": resolution.chance, "roll": resolution.roll})
	_flow()._append_physical_result_effect(event, resolution.hit, weapon != null)
	_append_reaction_identity(event, action, behind)
	events.append(event)
	if resolution.killed:
		combat.pending_reaction.mover_killed = true
		var death_macro_requested = _flow()._request_monster_death_macro(monster_target, target_definition, events)
		_flow()._remove_defeated_position(combat, monster_target.id, not death_macro_requested)
		return REACTION_DEATH_MACRO if death_macro_requested else REACTION_MOVER_DEFEATED
	return REACTION_COMPLETED

func _guarding_hostiles(state: GameState, mover_id: String, anchor_override: Vector2i = Vector2i(-1, -1)) -> Array[String]:
	var result: Array[String] = []
	for attacker_id: String in _flow()._hostile_adjacent_ids(state, mover_id, anchor_override):
		if state.combat.is_guarding(attacker_id) and not _combatant_is_helpless(state, attacker_id):
			result.append(attacker_id)
	return result

func _withdrawal_hostiles(state: GameState, reaction: CombatReactionState) -> Array[String]:
	var result: Array[String] = []
	if _combatant_is_invisible(state, reaction.mover_id):
		return result
	var after := _rules.battlefield.adjacent_actor_ids(state.combat.battlefield, reaction.mover_id, reaction.destination)
	for attacker_id: String in reaction.origin_hostiles():
		if not after.has(attacker_id) and not _combatant_is_helpless(state, attacker_id):
			result.append(attacker_id)
	return result

func _guarding_actor_ids(state: GameState, actor_ids: Array[String]) -> Array[String]:
	var result: Array[String] = []
	for actor_id: String in actor_ids:
		if state.combat.is_guarding(actor_id) and not _combatant_is_helpless(state, actor_id):
			result.append(actor_id)
	return result

func _combatant_is_alive(state: GameState, actor_id: String) -> bool:
	var character := state.party.character_by_id(actor_id)
	if character != null:
		return character.current_health > 0
	var monster := state.combat.monster_by_id(actor_id) if state.combat != null else null
	return monster != null and monster.current_health > 0

func _combatant_is_helpless(state: GameState, actor_id: String) -> bool:
	var character := state.party.character_by_id(actor_id)
	if character != null:
		return character.conditions.is_active(ConditionRules.HELPLESS)
	var monster := state.combat.monster_by_id(actor_id) if state.combat != null else null
	return monster != null and monster.conditions.is_active(ConditionRules.HELPLESS)

func _combatant_is_invisible(state: GameState, actor_id: String) -> bool:
	var character := state.party.character_by_id(actor_id)
	if character != null:
		return character.conditions.is_active(ConditionRules.INVISIBLE)
	var monster := state.combat.monster_by_id(actor_id) if state.combat != null else null
	return monster != null and monster.conditions.is_active(ConditionRules.INVISIBLE)

func resolve_monster_attack_monster(attacker: MonsterState, attacker_definition: MonsterDefinition, attack_index: int, defender: MonsterState, defender_definition: MonsterDefinition, rng: RealmzRng, context: MonsterAttackContext = null, allow_fumbles: bool = false) -> AttackResolution:
	if attacker == null or attacker_definition == null or defender == null or defender_definition == null or rng == null:
		return null
	var attack_context := context if context != null else MonsterAttackContext.new()
	var invalid_weapon := _invalid_weapon_reason(attack_context.attacker_weapon)
	if not invalid_weapon.is_empty():
		return _blocked_monster_attack(invalid_weapon)
	var condition_roll := _roll_weapon_condition_monster(attack_context.attacker_weapon, defender, defender_definition, rng)
	if condition_roll.get("blocked", false):
		return _blocked_monster_attack(StringName(condition_roll.get("reason", "invalid_weapon_condition")))
	var chance := _monster_attack_base_chance(attacker, attacker_definition, attack_context)
	chance += _attacker_condition_modifier(attacker.conditions)
	if attacker.conditions.is_active(ConditionRules.PROTECTION_FROM_EVIL):
		chance += 10
	chance -= defender.armor
	chance += _defender_condition_modifier(defender.conditions, false)
	if attacker_definition.type_flag(4) and defender.conditions.is_active(ConditionRules.PROTECTION_FROM_EVIL):
		chance -= 10
	chance = maxi(10, chance)
	var roll := rng.draw(100, &"combat.monster-attack.hit")
	var hit := roll <= chance or _monster_weapon_auto_hits(attack_context.attacker_weapon)
	var helpless := defender.conditions.is_active(ConditionRules.HELPLESS)
	if helpless:
		hit = true
	var fumble_roll := _monster_fumble_roll(attacker, rng, allow_fumbles)
	if _monster_fumbled(attack_context.attacker_weapon, fumble_roll):
		return _fumbled_attack(chance, roll, fumble_roll)
	if not hit:
		return _with_monster_fumble_roll(AttackResolution.new(false, false, chance, roll, 0), fumble_roll)
	var weapon_requirement := _monster_required_weapon_reason(attack_context.attacker_weapon, defender_definition)
	if not weapon_requirement.is_empty():
		return _with_monster_fumble_roll(_blocked_monster_attack(weapon_requirement, chance, roll), fumble_roll)
	var attacks := attacker_definition.attacks()
	var attack := _monster_attack_row(attacks, attack_index)
	var damage := attacker_definition.damage_bonus + attacker.conditions.value(ConditionRules.ATTACK_BONUS)
	if attacker.conditions.is_active(ConditionRules.STRONG):
		damage += 3
	var effects: Array[Dictionary] = []
	var elemental_damage := 0
	if helpless:
		damage = defender.current_health
	elif attack_context.attacker_weapon != null:
		damage += attack_context.attacker_weapon.damage_bonus
		damage += rng.draw(maxi(1, attack_context.attacker_weapon.vs_small), &"combat.monster-attack.weapon-physical")
		elemental_damage = _roll_weapon_elements_monster(attack_context.attacker_weapon, defender, defender_definition, rng, effects)
		elemental_damage += _roll_monster_weapon_type_damage(attack_context.attacker_weapon, defender_definition, rng, effects)
	else:
		damage += rng.draw_between(attack.damage_min, attack.damage_max, &"combat.monster-attack.damage")
	damage = maxi(0, damage)
	var resolution := AttackResolution.new(true, defender.current_health - damage - elemental_damage <= 0, chance, roll, damage + elemental_damage)
	_with_monster_fumble_roll(resolution, fumble_roll)
	resolution.physical_damage = damage
	resolution.weapon_effects = effects
	if attack.special != 0:
		resolution.special_code = attack.special
		var potency_low := int(float(attacker.hit_dice) / 2.0)
		resolution.special_potency = maxi(1, rng.draw_between(potency_low, attacker.hit_dice, &"combat.monster-attack.special-potency"))
		if _is_status_special(attack.special):
			resolution.special_handled = true
			resolution.special_save_index = _status_save_index(attack.special)
			resolution.special_condition_index = _status_condition_index(attack.special)
			resolution.special_condition_before = defender.conditions.value(resolution.special_condition_index)
			resolution.special_condition_after = resolution.special_condition_before
		elif _is_resource_special(attack.special):
			resolution.special_handled = true
			resolution.special_save_index = _resource_save_index(attack.special)
			resolution.special_resource = &"spell_points" if attack.special == 8 else &"experience"
		elif attack.special == 17:
			resolution.special_handled = true
		elif attack.special == 10:
			resolution.special_handled = true
			resolution.special_save_index = 0
			resolution.special_allegiance_before = defender.traitor
			resolution.special_allegiance_after = defender.traitor
		elif _is_elemental_special(attack.special):
			resolution.special_handled = true
			resolution.special_save_index = attack.special - 10
			resolution.special_condition_index = _elemental_condition_index(attack.special)
			resolution.special_element = _elemental_name(attack.special)
		elif attack.special in [18, 19]:
			resolution.special_handled = true
			resolution.special_save_index = 7
			resolution.special_condition_index = ConditionRules.BLIND if attack.special == 18 else ConditionRules.TURNED_TO_STONE
		if defender.magic_resistance > 100:
			resolution.special_blocked = true
			resolution.special_block_reason = &"magic_resistance"
			resolution.hit = false
			resolution.damage = 0
			resolution.killed = false
			return resolution
	if _is_status_special(attack.special):
		_apply_monster_status_special(resolution, defender, defender_definition, rng)
	elif attack.special == 8:
		_apply_monster_spell_drain(resolution, attacker, defender, defender_definition, rng)
	elif attack.special == 9:
		resolution.special_blocked = true
		resolution.special_block_reason = &"party_target_only"
	elif attack.special == 10:
		_apply_monster_charm_special(resolution, attacker, defender, defender_definition, rng)
	elif _is_elemental_special(attack.special):
		_apply_monster_elemental_special(resolution, attack, defender, defender_definition, rng)
	elif attack.special == 17:
		resolution.special_handled = true
	elif attack.special in [18, 19]:
		_apply_monster_permanent_affliction(resolution, defender, defender_definition, rng)
	_apply_weapon_condition_monster(defender, condition_roll, resolution)
	if not resolution.physical_damage_skipped:
		defender.current_health -= damage + elemental_damage + resolution.special_damage_amount
		resolution.killed = defender.current_health <= 0
	return resolution

static func _monster_attack_row(attacks: Array[MonsterAttackDefinition], attack_index: int) -> MonsterAttackDefinition:
	if attacks.is_empty():
		return MonsterAttackDefinition.new(1, 1)
	var selected := attacks[clampi(attack_index, 0, attacks.size() - 1)]
	if selected.damage_min == 0:
		return attacks[0]
	return selected

static func _monster_required_weapon_reason(weapon: ItemDefinition, defender: MonsterDefinition) -> StringName:
	if defender.required_weapon == 0:
		return &""
	if weapon == null:
		if defender.required_weapon == -1:
			return &"classic_blunt_weapon_required"
		if defender.required_weapon == -2:
			return &"classic_sharp_weapon_required"
		return &"classic_specific_weapon_required"
	if defender.required_weapon == -1:
		return &"" if weapon.blunt == -1 else &"classic_blunt_weapon_required"
	if defender.required_weapon == -2:
		return &"" if weapon.blunt == -2 else &"classic_sharp_weapon_required"
	var required_item_id := defender.required_weapon & 0xff
	return &"" if weapon.classic_id == required_item_id else &"classic_specific_weapon_required"

static func _apply_weapon_condition_monster(defender: MonsterState, condition_roll: Dictionary, resolution: AttackResolution) -> void:
	if condition_roll.is_empty() or not condition_roll.get("applies", false):
		return
	var index := int(condition_roll["index"])
	resolution.weapon_condition_index = index
	resolution.weapon_condition_before = defender.conditions.value(index)
	resolution.weapon_condition_after = resolution.weapon_condition_before
	if resolution.weapon_condition_before > -1:
		resolution.weapon_condition_after += int(condition_roll["amount"])
		defender.conditions.set_value(index, resolution.weapon_condition_after)

static func _record_weapon_condition_character(defender: CharacterState, condition_roll: Dictionary, resolution: AttackResolution) -> void:
	if condition_roll.is_empty() or not condition_roll.get("applies", false):
		return
	var index := int(condition_roll["index"])
	resolution.weapon_condition_index = index
	resolution.weapon_condition_before = defender.conditions.value(index)
	resolution.weapon_condition_after = resolution.weapon_condition_before
	if resolution.weapon_condition_before > -1:
		resolution.weapon_condition_after += int(condition_roll["amount"])

func _init(flow: RefCounted, rules: ContextType) -> void:
	_flow_ref = weakref(flow)
	_rules = rules

func _commit_character_fumble(state: GameState, character: CharacterState, equipment: CharacterCombatEquipment, events: Array[DomainEvent]) -> bool:
	if state.combat == null or equipment == null or equipment.melee_weapon == null or equipment.melee_weapon_instance_id.is_empty() or not state.combat.can_queue_fumbled_item():
		return false
	var instance: ItemInstance = null
	for carried: ItemInstance in character.inventory():
		if carried.id == equipment.melee_weapon_instance_id and carried.definition_id == equipment.melee_weapon.id and carried.equipped:
			instance = carried
			break
	if instance == null or not state.combat.queue_fumbled_item(instance):
		return false
	var removed := _rules.inventory.remove_item(character, instance.id, equipment.melee_weapon)
	if removed == null:
		state.combat.remove_fumbled_item(instance.id)
		instance.equipped = true
		return false
	# FD-COMBAT-005 preserves the exact runtime item and its remaining charges.
	# Castle's short-only queue reconstructs the item from its definition at booty.
	removed.identified = true
	_append_fumble_feedback(events, character.id, removed, true)
	return true

func _fire_character_projectile(state: GameState, content: RealmzContent, actor: CharacterState, equipment: CharacterCombatEquipment, target_id: String, rng: RealmzRng) -> CombatFlowResult:
	var combat := state.combat
	var profile = _flow().character_projectile_profile(actor, content, equipment)
	if not profile.available:
		return CombatFlowResult.failed(profile.error_code, profile.error_message)
	var target := combat.monster_by_id(target_id)
	if target == null or target.current_health <= 0 or target.traitor == actor.traitor:
		return CombatFlowResult.failed(&"invalid_projectile_target", "This source-backed projectile slice can target only a living hostile monster.")
	if not _flow().projectile_target_is_valid(combat, content, actor.id, target.id, profile.maximum_range, profile.spell.range_min + profile.spell.range_max > 0):
		return CombatFlowResult.failed(&"projectile_target_unavailable", "The target is outside the Classic projectile range or line of sight.")
	var definition := content.monster_by_id(target.definition_id)
	var caste := content.caste_by_id(actor.caste_id)
	if definition == null or caste == null:
		return CombatFlowResult.failed(&"projectile_target_unavailable", "Projectile resolution requires the target monster and caster caste definitions.")
	_prepare_character_turn(combat, actor)
	if not _rules.inventory.use_charge(actor, profile.item_instance_id, profile.item):
		return CombatFlowResult.failed(&"projectile_charge_unavailable", "The selected projectile charge could not be consumed atomically.")
	combat.invalidate_undo()
	var resolution := _rules.magic.resolve_character_projectile(actor, caste, profile.item, target, profile.spell, profile.power_level, rng)
	if resolution == null:
		return CombatFlowResult.failed(&"unsupported_projectile_spell", "The selected projectile cannot be resolved by the source-backed missile rules.")
	if resolution.total_damage > 0:
		combat.mark_attacked(target.id)
	combat.active_turn.physical_action_committed = true
	actor.attacks_remaining = _rules.arithmetic.signed_16(actor.attacks_remaining - 2)
	actor.movement = maxi(0, actor.movement - 12)
	var events: Array[DomainEvent] = [DomainEvent.new(&"combat_projectile_resolved", {
		"actorId": actor.id,
		"targetId": target.id,
		"targetKind": "monster",
		"itemId": profile.item.id,
		"spellId": profile.spell.id,
		"powerLevel": profile.power_level,
		"range": _rules.battlefield.classic_range(combat.battlefield, actor.id, target.id),
		"hitCount": resolution.hit_count,
		"missCount": resolution.miss_count,
		"damage": resolution.total_damage,
		"defeated": resolution.target_defeated,
		"source": "classic",
	})]
	var death_macro_requested := resolution.target_defeated and _request_monster_death_macro(target, definition, events)
	_flow()._remove_defeated_position(combat, target.id, resolution.target_defeated and not death_macro_requested)
	if not _character_can_continue(actor):
		_flow()._advance_turn(state, rng, events)
	if death_macro_requested:
		return CombatFlowResult.succeeded(events)
	if _flow()._finish_if_resolved(state, content, events):
		return CombatFlowResult.succeeded(events, true)
	_flow()._process_monster_turns(state, content, rng, events)
	return CombatFlowResult.succeeded(events, state.combat.completed)

func probe_delay(state: GameState, actor_id: String) -> CombatCommandProbeType:
	var actor := state.party.character_by_id(actor_id) if state != null else null
	var combat := state.combat if state != null else null
	if actor == null or combat == null or combat.completed or combat.active_actor_id() != actor_id or actor.current_health <= 0 or actor.traitor:
		return CombatCommandProbeType.new(false, "Only the active loyal character can Delay.")
	if not _is_fresh_character_activation(combat, actor):
		return CombatCommandProbeType.new(false, "Delay is available only before moving, attacking, or casting this activation.")
	return CombatCommandProbeType.new(true)

func _submit_character_attack(state: GameState, content: RealmzContent, actor: CharacterState, target_id: String, rng: RealmzRng) -> CombatFlowResult:
	var combat := state.combat
	var events: Array[DomainEvent] = []
	var equipment := _rules.inventory.combat_equipment(actor, content.item_definitions())
	if not equipment.valid: return CombatFlowResult.failed(equipment.error_code, equipment.error_message)
	if combat.character_weapon_mode(actor.id) == &"missile": return _fire_character_projectile(state, content, actor, equipment, target_id, rng)
	if combat.battlefield == null: return CombatFlowResult.failed(&"missing_battlefield", "Melee requires the session-owned Classic battlefield.")
	if not _rules.battlefield.are_adjacent(combat.battlefield, actor.id, target_id): return CombatFlowResult.failed(&"combat_target_not_adjacent", "Classic melee can target only an enemy in an adjacent battlefield footprint.")
	var monster_target := combat.monster_by_id(target_id)
	if monster_target != null and monster_target.current_health > 0 and monster_target.traitor != actor.traitor:
		var definition := content.monster_by_id(monster_target.definition_id)
		if definition == null: return CombatFlowResult.failed(&"unknown_monster_definition", "The selected monster has no immutable definition.")
		_prepare_character_turn(combat, actor)
		combat.invalidate_undo()
		combat.active_turn.physical_action_committed = true
		var resolution := _rules.combat.resolve_character_attack(actor, equipment, monster_target, definition, rng, state.clock.day(), false, true, combat.can_queue_fumbled_item())
		if resolution.total_damage() > 0: combat.mark_attacked(monster_target.id)
		if resolution.fumbled and not _commit_character_fumble(state, actor, equipment, events): return CombatFlowResult.failed(&"invalid_fumble_state", "The fumbled melee weapon could not enter the battle recovery queue.")
		_append_character_attack_audio(events, actor, equipment, resolution, &"monster")
		events.append(_character_attack_event(actor.id, monster_target.id, &"monster", resolution, equipment.melee_weapon != null))
		var macro_requested := resolution.killed and _request_monster_death_macro(monster_target, definition, events)
		_flow()._remove_defeated_position(combat, monster_target.id, resolution.killed and not macro_requested)
	else:
		var character_target := state.party.character_by_id(target_id)
		if character_target == null or character_target.id == actor.id or character_target.current_health <= 0 or character_target.traitor == actor.traitor: return CombatFlowResult.failed(&"invalid_combat_target", "The selected combatant is unavailable to this allegiance.")
		var target_equipment := _rules.inventory.combat_equipment(character_target, content.item_definitions())
		if not target_equipment.valid: return CombatFlowResult.failed(target_equipment.error_code, target_equipment.error_message)
		_prepare_character_turn(combat, actor)
		combat.invalidate_undo()
		combat.active_turn.physical_action_committed = true
		var resolution := _rules.combat.resolve_character_attack_character(actor, equipment, character_target, target_equipment, rng, false, true, combat.can_queue_fumbled_item())
		if resolution.total_damage() > 0: combat.mark_attacked(character_target.id)
		if resolution.fumbled and not _commit_character_fumble(state, actor, equipment, events): return CombatFlowResult.failed(&"invalid_fumble_state", "The fumbled melee weapon could not enter the battle recovery queue.")
		_append_character_attack_audio(events, actor, equipment, resolution, &"character")
		events.append(_character_attack_event(actor.id, character_target.id, &"character", resolution, equipment.melee_weapon != null))
		_mark_character_bleeding(state, character_target, resolution.killed)
		_flow()._remove_defeated_position(combat, character_target.id, resolution.killed)
	_consume_character_attack(actor)
	if not _character_can_continue(actor): _flow()._advance_turn(state, rng, events)
	return CombatFlowResult.succeeded(events)

func submit_action(state: GameState, content: RealmzContent, actor_id: String, action: StringName, target_id: String, rng: RealmzRng) -> CombatFlowResult:
	var combat := state.combat
	if combat == null or combat.completed:
		return CombatFlowResult.failed(&"no_active_battle", "No Realmz battle is accepting combat actions.")
	if combat.active_actor_id() != actor_id:
		return CombatFlowResult.failed(&"wrong_combat_actor", "Combat action actor '%s' does not own the current turn." % actor_id)
	var actor := state.party.character_by_id(actor_id)
	if actor == null or actor.current_health <= 0 or actor.traitor or combat.battlefield == null or not combat.battlefield.has_actor(actor.id):
		return CombatFlowResult.failed(&"invalid_combat_actor", "The current combat actor is unavailable.")
	var events: Array[DomainEvent] = []
	match action:
		&"attack":
			var attack_result := _submit_character_attack(state, content, actor, target_id, rng)
			if not attack_result.ok: return attack_result
			events.append_array(attack_result.events)
			if _flow()._events_include(events, &"monster_death_macro_requested"):
				return CombatFlowResult.succeeded(events)
		&"switch_weapon":
			var equipment := _rules.inventory.combat_equipment(actor, content.item_definitions())
			if not equipment.valid:
				return CombatFlowResult.failed(equipment.error_code, equipment.error_message)
			var current_mode := combat.character_weapon_mode(actor.id)
			var next_mode: StringName = &"melee" if current_mode == &"missile" else &"missile"
			if next_mode == &"missile" and equipment.missile_weapon == null:
				return CombatFlowResult.failed(&"missile_weapon_unavailable", "The active character has no equipped Classic type-15 missile weapon.")
			_prepare_character_turn(combat, actor)
			if not combat.set_character_weapon_mode(actor.id, next_mode):
				return CombatFlowResult.failed(&"invalid_weapon_mode", "The active character's battle weapon mode could not be changed.")
			events.append(DomainEvent.new(&"combat_weapon_mode_changed", {"actorId": actor.id, "mode": String(next_mode)}))
		&"defend":
			_prepare_character_turn(combat, actor)
			var guard_roll := rng.draw(100, &"combat.guard-sound")
			var guard_sound := 10121 if guard_roll < 50 else 10123
			combat.set_guarding(actor.id, true)
			events.append(DomainEvent.new(&"sound_requested", {"soundId": guard_sound, "waitForCompletion": false, "source": "classic-combat-guard"}))
			events.append(DomainEvent.new(&"combatant_guarded", {"actorId": actor.id, "roll": guard_roll, "soundId": guard_sound, "source": "classic"}))
			_flow()._advance_turn(state, rng, events)
		&"delay":
			var delay_probe := probe_delay(state, actor.id)
			if not delay_probe.allowed:
				return CombatFlowResult.failed(&"combat_delay_unavailable", delay_probe.reason_text)
			_prepare_character_turn(combat, actor)
			actor.attacks_remaining = _rules.arithmetic.signed_16(actor.attacks_remaining - actor.normal_attacks - actor.attack_bonus)
			var round_advanced := combat.delay_active_actor()
			if round_advanced:
				_flow()._process_bleeding_round(state, rng, events)
			events.append(DomainEvent.new(&"combat_turn_delayed", {"actorId": actor.id, "roundAdvanced": round_advanced, "source": "classic-corrected", "fidelityDecision": "FD-COMBAT-012"}))
		&"bandage":
			var bandage_probe := probe_bandage(state, actor.id, target_id)
			if not bandage_probe.allowed:
				return CombatFlowResult.failed(&"combat_bandage_unavailable", bandage_probe.reason_text)
			_prepare_character_turn(combat, actor)
			if not combat.set_character_bleeding(target_id, false):
				return CombatFlowResult.failed(&"invalid_bandage_target", "The selected bleeding state could not be cleared.")
			actor.attacks_remaining = 0
			actor.movement = 0
			events.append(DomainEvent.new(&"sound_requested", {"soundId": 10105, "waitForCompletion": false, "source": "classic-combat-bandage"}))
			if _flow().is_processing_auto():
				var bandage_roll := rng.draw(100, StringName("combat.auto.%s.bandage-sound" % actor.id))
				var bandage_sound := 10121 if bandage_roll < 50 else 10123
				events.append(DomainEvent.new(&"sound_requested", {"soundId": bandage_sound, "waitForCompletion": false, "source": "classic-combat-auto-bandage"}))
			events.append(DomainEvent.new(&"combatant_bandaged", {"actorId": actor.id, "targetId": target_id, "source": "classic-corrected", "fidelityDecision": "FD-COMBAT-013"}))
			_flow()._advance_turn(state, rng, events)
		&"turn_undead":
			var turn_result := _turn_undead(state, content, actor, rng)
			if not turn_result.ok:
				return turn_result
			events.append_array(turn_result.events)
			if not combat.pending_spell_death_macro_id().is_empty():
				return CombatFlowResult.succeeded(events)
		&"undo":
			var undo_probe := probe_undo(state, actor.id)
			if not undo_probe.allowed:
				return CombatFlowResult.failed(&"combat_undo_unavailable", undo_probe.reason_text)
			var from_position := combat.battlefield.actor_position(actor.id)
			var start_position := combat.undo_state.start_position
			if from_position != start_position and not combat.battlefield.move_actor(actor.id, start_position):
				return CombatFlowResult.failed(&"combat_undo_position_blocked", "The activation-start position is no longer available.")
			actor.attacks_remaining = _rules.arithmetic.signed_16(actor.attacks_remaining - actor.normal_attacks - actor.attack_bonus)
			combat.restart_active_turn_after_undo()
			_prepare_character_turn(combat, actor)
			combat.invalidate_undo()
			events.append(DomainEvent.new(&"sound_requested", {"soundId": 664, "waitForCompletion": false, "source": "classic-combat-undo"}))
			if not actor.conditions.is_active(ConditionRules.ANIMATED):
				events.append(DomainEvent.new(&"sound_requested", {"soundId": 138, "waitForCompletion": false, "source": "classic-combat-activation"}))
			events.append(DomainEvent.new(&"combat_turn_undone", {"actorId": actor.id, "from": [from_position.x, from_position.y], "to": [start_position.x, start_position.y], "attacksRemaining": actor.attacks_remaining, "movementRemaining": actor.movement, "source": "classic"}))
		&"auto":
			var auto_result = _flow().run_auto_activation_chain(state, content, actor.id, rng)
			if not auto_result.ok:
				return auto_result
			auto_result.events.push_front(DomainEvent.new(&"sound_requested", {"soundId": 141, "waitForCompletion": false, "source": "classic-combat-auto-button"}))
			return auto_result
		&"finish", &"pass":
			_prepare_character_turn(combat, actor)
			actor.movement = 0
			combat.set_guarding(actor.id, false)
			events.append(DomainEvent.new(&"combat_turn_passed", {"actorId": actor.id, "action": String(action)}))
			_flow()._advance_turn(state, rng, events)
		&"retreat":
			return _flow().retreat_character(state, content, actor_id, &"explicit", Vector2i(-100_000, -100_000), rng)
		_:
			return CombatFlowResult.failed(&"unknown_combat_action", "Combat action '%s' is not available." % action)
	if _flow()._finish_if_resolved(state, content, events):
		return CombatFlowResult.succeeded(events, true)
	_flow()._process_monster_turns(state, content, rng, events)
	return CombatFlowResult.succeeded(events, state.combat.completed)

func create_character(character_id: String, character_name: String, race: RaceDefinition, caste: CasteDefinition, gender: int, rng: RealmzRng, include_initial_items: bool = true, starting_level: int = 1) -> CharacterState:
	if race == null or caste == null or rng == null or not STARTING_LEVELS.has(starting_level):
		return null
	var attributes: Array[int] = []
	for index: int in ATTRIBUTE_COUNT:
		var rolled := rng.draw_between(1, 18, StringName("character.create.attribute.%d" % index)) + race.attribute_bonus(index) + caste.attribute_bonus(index)
		rolled = clampi(rolled, caste.attribute_minimum(index), caste.attribute_maximum(index))
		rolled = clampi(rolled, race.attribute_minimum(index), race.attribute_maximum(index))
		attributes.append(rolled)
	# Castle's seven-iteration loop aliases its final profile offset back to Luck,
	# consumes the roll, and never assigns the value. The draw is observable in
	# every later creation roll, so the deterministic session must retain it.
	rng.draw_between(1, 18, &"character.create.attribute.discarded")
	if gender == 2:
		attributes[0] -= 1
		attributes[3] += 1
		attributes[2] += 1
	else:
		attributes[0] += 1
		attributes[3] -= 1
	var save_values: Array[int] = []
	var special_values: Array[int] = []
	for index: int in 8:
		save_values.append(50 + race.save_bonus(index) + caste.save_bonus(index))
		special_values.append(race.hit_modifier(index))
	var age_group_count := clampi(caste.minimum_age_group, 1, 5)
	for age_index: int in age_group_count:
		var age_change := race.age_change(age_index)
		for attribute_index: int in ATTRIBUTE_COUNT:
			attributes[attribute_index] += age_change[attribute_index]
		for save_index: int in 7:
			save_values[save_index] += age_change[8 + save_index]
	for index: int in ATTRIBUTE_COUNT:
		attributes[index] = clampi(attributes[index], caste.attribute_minimum(index), caste.attribute_maximum(index))
		attributes[index] = clampi(attributes[index], race.attribute_minimum(index), race.attribute_maximum(index))
	for threshold: int in [80, 90, 95]:
		if rng.draw(100, StringName("character.create.special-bonus.%d.roll" % threshold)) > threshold:
			var special_index := rng.draw_between(0, 7, StringName("character.create.special-bonus.%d.index" % threshold))
			special_values[special_index] += 1
	var vitality_bonus := maxi(0, attributes[4] - 16)
	vitality_bonus = mini(vitality_bonus, caste.maximum_stamina_bonus)
	var maximum_health := rng.draw(maxi(1, caste.initial_stamina_die()), &"character.create.stamina") + vitality_bonus
	var result := CharacterState.new(character_id, character_name, maximum_health, maximum_health)
	result.race_id = race.id
	result.caste_id = caste.id
	result.gender = gender
	result.prestige_penalty = 10 * (starting_level - 1) * (starting_level - 1)
	result.experience = -caste.victory_threshold(starting_level - 1)
	result.age_group = age_group_count
	result.brawn = attributes[0]
	result.knowledge = attributes[1]
	result.judgment = attributes[2]
	result.agility = attributes[3]
	result.vitality = attributes[4]
	result.luck = attributes[5]
	var strength := strength_bonuses(result.brawn, caste.maximum_damage_bonus())
	result.to_hit = caste.initial_to_hit() + strength.to_hit_bonus
	result.damage_bonus = strength.damage_bonus
	result.dodge = 2 * result.agility + caste.initial_dodge()
	result.armor = 0
	if result.agility > 14:
		result.armor -= 2 * (14 - result.agility)
	result.magic_resistance = int(float(result.knowledge + result.judgment) / 10.0) * caste.magic_resistance_multiplier + race.magic_resistance
	result.two_hand = clampi(race.two_hand_bonus + caste.two_hand_bonus, 0, 100)
	result.missile = race.missile_bonus + caste.initial_missile() if caste.can_use_missile else 0
	result.hand_to_hand = caste.initial_hand_to_hand()
	result.maximum_movement = race.base_movement + caste.movement_bonus
	result.movement = result.maximum_movement
	result.normal_attacks = mini(race.base_attacks + caste.bonus_attacks, 2 * race.maximum_attacks)
	result.attacks_remaining = result.normal_attacks
	result.maximum_load = maxi(500, result.brawn * result.brawn * 20)
	result.money.gold = maxi(0, caste.start_money)
	var selected_age_range := race.age_range(clampi(caste.minimum_age_group - 1, 0, 4))
	if selected_age_range.y >= selected_age_range.x and selected_age_range.y > 0:
		result.age_days = rng.draw_between(selected_age_range.x, selected_age_range.y, &"character.create.age") * 365
	for index: int in 8:
		result.set_save_value(index, save_values[index])
		result.set_special_value(index, special_values[index])
	for index: int in ConditionSet.CHARACTER_COUNT:
		var starting_condition := race.condition_level(index)
		if caste.condition_level(index) == 1:
			starting_condition = -1
		result.conditions.set_value(index, starting_condition)
	_configure_spellcaster(result, caste, rng, starting_level)
	_initialize_abilities(result, race, caste)
	for _index: int in starting_level - 1:
		if level_up(result, race, caste, rng) == null:
			return null
	if include_initial_items:
		add_initial_items(result, caste)
	return result

func infer_age_group(age_days: int, race: RaceDefinition) -> int:
	if race == null:
		return 0
	var age_years := floori(float(age_days) / 365.0)
	for index: int in 5:
		var authored_range := race.age_range(index)
		if age_years >= authored_range.x and age_years <= authored_range.y:
			return index + 1
	return 0

func recalculate_movement(character: CharacterState, race: RaceDefinition, movement_bonus: int = 0) -> int:
	character.carried_load = maxi(0, character.carried_load)
	character.maximum_load = maxi(500, character.brawn * character.brawn * 20)
	var movement := 1.0 + (float(character.maximum_load - character.carried_load) / float(character.maximum_load)) * float(race.base_movement)
	if character.conditions.is_active(2):
		movement -= character.conditions.value(2)
	if character.conditions.is_active(6):
		movement /= 2.0
	if character.conditions.is_active(23):
		movement *= 2.0
	character.maximum_movement = maxi(2, int(movement)) + movement_bonus
	character.movement = mini(character.movement, character.maximum_movement)
	return character.maximum_movement

func spell_selection_total(character: CharacterState, caste: CasteDefinition) -> int:
	if character == null or caste == null or character.spellcaster_type < 1:
		return 0
	var start_level_sum := 0
	for row: Vector3i in caste.spellcaster_rows():
		start_level_sum += row.y
	var relative_level := character.level - (start_level_sum - 1)
	if relative_level < 1:
		return 0
	var bonus_attribute := character.judgment if character.spellcaster_type == 2 else character.knowledge
	var total := 3 * relative_level + int(relative_level * (relative_level - 1) / 2.0)
	if bonus_attribute > 15:
		total += relative_level * (bonus_attribute - 15)
	return total

static func _frames(rng: RealmzRng, authored_tumblers: int, chance_percent: int, iterations: int, preview_mode: bool) -> Array[Array]:
	var count := tumbler_count(authored_tumblers)
	var yellow := yellow_threshold(chance_percent)
	var green := green_threshold(chance_percent)
	var positions: Array[int] = []
	for _index: int in count:
		positions.append(8 + int(yellow / 2.0))
	var result: Array[Array] = [positions.duplicate()]
	for _iteration: int in iterations:
		for tumbler_index: int in count:
			if positions[tumbler_index] >= green:
				continue
			var suffix := &"preview" if preview_mode else &"resolve"
			var delta := rng.draw(JUMP_RANGE, StringName("classic.pick-lock.delta.%s" % suffix))
			var advances := rng.draw(100, StringName("classic.pick-lock.direction.%s" % suffix)) <= ADVANCE_PERCENT
			positions[tumbler_index] = clampi(positions[tumbler_index] + (delta if advances else -delta), 10, TRACK_END)
		result.append(positions.duplicate())
	return result

func maximum_spell_selection_level(caste: CasteDefinition) -> int:
	if caste == null:
		return 0
	var result := 0
	for row: Vector3i in caste.spellcaster_rows():
		result += row.z
	return clampi(result, 0, 7)

func add_initial_items(character: CharacterState, caste: CasteDefinition) -> bool:
	if character == null or caste == null or not character.inventory().is_empty():
		return false
	var items: Array[ItemInstance] = []
	for index: int in caste.start_items().size():
		var item_id := caste.start_items()[index]
		items.append(ItemInstance.new("%s.item.%d" % [character.id, index], item_id))
	character.set_inventory(items)
	return true

func ensure_age_group(character: CharacterState, race: RaceDefinition, caste: CasteDefinition = null) -> int:
	if character == null or race == null:
		return 0
	if character.age_group >= 1 and character.age_group <= 5:
		return character.age_group
	character.age_group = infer_age_group(character.age_days, race)
	if character.age_group == 0:
		character.age_group = clampi(caste.minimum_age_group if caste != null else 1, 1, 5)
	return character.age_group

func advance_age_days(character: CharacterState, race: RaceDefinition, caste: CasteDefinition, day_change: int) -> CharacterAgingResult:
	if character == null or race == null or caste == null:
		return null
	var previous_days := character.age_days
	var previous_group := ensure_age_group(character, race, caste)
	character.age_days = _signed_32(character.age_days + day_change)
	var target_group := infer_age_group(character.age_days, race)
	if target_group > character.age_group and character.age_group < 5:
		character.age_group += 1
		_apply_age_change(character, race, caste, character.age_group, 1)
		return CharacterAgingResult.new(previous_days, character.age_days, previous_group, character.age_group, 1, character.age_group)
	if target_group > 0 and target_group < character.age_group and character.age_group > 1:
		var erased_group := character.age_group
		_apply_age_change(character, race, caste, erased_group, -1)
		character.age_group -= 1
		return CharacterAgingResult.new(previous_days, character.age_days, previous_group, character.age_group, -1, erased_group)
	return CharacterAgingResult.new(previous_days, character.age_days, previous_group, character.age_group)

func battle_experience(character: CharacterState, race: RaceDefinition, share: int) -> int:
	if character == null or race == null:
		return 0
	if floori(float(character.age_days) / 365.0) >= race.max_age:
		return int(float(share) * 0.6666666)
	return share

func level_up(character: CharacterState, race: RaceDefinition, caste: CasteDefinition, rng: RealmzRng) -> LevelUpResult:
	if character == null or race == null or caste == null or rng == null:
		return null
	character.level += 1
	# Castle consumes this registration-era roll even though the open-source
	# registration branch no longer changes the character.
	rng.draw(100, &"character.level.registration-check")
	character.normal_attacks = race.base_attacks + caste.bonus_attacks
	for required_level: int in caste.attack_levels():
		if required_level > 0 and required_level <= character.level:
			character.normal_attacks += 1
	character.normal_attacks = mini(character.normal_attacks, 2 * race.maximum_attacks)
	character.attacks_remaining = character.normal_attacks
	for index: int in ConditionSet.CHARACTER_COUNT:
		if caste.condition_level(index) == character.level:
			var current_condition := character.conditions.value(index)
			character.conditions.set_value(index, -1 if current_condition > -1 else current_condition - 1)
	character.to_hit += caste.level_to_hit()
	character.dodge += caste.level_dodge()
	character.hand_to_hand += caste.level_hand_to_hand()
	if caste.level_missile() > 0:
		character.missile += rng.draw(caste.level_missile(), &"character.level.missile")
	character.spellcaster_type = _level_spellcaster_type(caste)
	var spell_gain := _level_spell_points(character, caste, rng)
	character.spell_points += spell_gain
	character.maximum_spell_points += spell_gain
	var vitality_bonus := mini(maxi(0, character.vitality - 16), caste.maximum_stamina_bonus)
	var stamina_gain := rng.draw(maxi(1, caste.level_stamina_die()), &"character.level.stamina") + vitality_bonus
	character.current_health += stamina_gain
	character.maximum_health += stamina_gain
	var magic_gain := 1 if rng.draw(100, &"character.level.magic-resistance") <= character.judgment + character.knowledge + character.vitality else 0
	character.magic_resistance += magic_gain
	for index: int in 14:
		var ability_die := caste.level_ability_die(index)
		if ability_die > 0:
			character.set_ability_value(index, character.ability_value(index) + rng.draw(ability_die, StringName("character.level.ability.%d" % index)))
	for index: int in 12:
		character.set_ability_value(index, clampi(character.ability_value(index), 0, 100))
	character.dodge = clampi(character.dodge, 0, 100)
	character.missile = clampi(character.missile, 0, 100)
	character.magic_resistance = clampi(character.magic_resistance, 0, 100)
	character.two_hand = clampi(character.two_hand, 0, 100)
	character.damage_bonus = clampi(character.damage_bonus, 0, 200)
	character.hand_to_hand = clampi(character.hand_to_hand, 0, 200)
	return LevelUpResult.new(stamina_gain, spell_gain, caste.level_to_hit(), magic_gain)

static func update_payloads(events: Array[DomainEvent]) -> Array[Dictionary]:
	var updates: Array[Dictionary] = []
	for event: DomainEvent in events:
		if event.kind == &"character_age_changed" and event.payload.get("presentation") == "classic-age-update":
			updates.append(event.payload.duplicate(true))
	return updates

func _resolve_character_reaction(state: GameState, content: RealmzContent, attacker: CharacterState, target_id: String, action: StringName, behind: bool, rng: RealmzRng, events: Array[DomainEvent]) -> int:
	var combat := state.combat
	combat.invalidate_undo()
	var equipment := _rules.inventory.combat_equipment(attacker, content.item_definitions())
	if not equipment.valid:
		events.append(DomainEvent.new(&"combat_reaction_failed", {"actorId": attacker.id, "targetId": target_id, "reason": String(equipment.error_code)}))
		return REACTION_COMPLETED
	var monster_target := combat.monster_by_id(target_id)
	if monster_target != null:
		var definition := content.monster_by_id(monster_target.definition_id)
		var reaction_resolution := _rules.combat.resolve_character_attack(attacker, equipment, monster_target, definition, rng, state.clock.day(), behind, true, combat.can_queue_fumbled_item())
		if reaction_resolution.total_damage() > 0:
			combat.mark_attacked(monster_target.id)
		if reaction_resolution.fumbled and not _flow()._commit_character_fumble(state, attacker, equipment, events):
			events.append(DomainEvent.new(&"combat_fumble_failed", {"actorId": attacker.id, "reason": "invalid-fumble-state"}))
		_flow()._append_character_attack_audio(events, attacker, equipment, reaction_resolution, &"monster")
		var reaction_event = _flow()._character_attack_event(attacker.id, monster_target.id, &"monster", reaction_resolution, equipment.melee_weapon != null)
		_append_reaction_identity(reaction_event, action, behind)
		events.append(reaction_event)
		if reaction_resolution.killed:
			combat.pending_reaction.mover_killed = true
			var death_macro_requested = _flow()._request_monster_death_macro(monster_target, definition, events)
			_flow()._remove_defeated_position(combat, monster_target.id, not death_macro_requested)
			return REACTION_DEATH_MACRO if death_macro_requested else REACTION_MOVER_DEFEATED
		return REACTION_COMPLETED
	var character_target := state.party.character_by_id(target_id)
	if character_target == null:
		return REACTION_COMPLETED
	var target_equipment := _rules.inventory.combat_equipment(character_target, content.item_definitions())
	if not target_equipment.valid:
		events.append(DomainEvent.new(&"combat_reaction_failed", {"actorId": attacker.id, "targetId": target_id, "reason": String(target_equipment.error_code)}))
		return REACTION_COMPLETED
	var resolution := _rules.combat.resolve_character_attack_character(attacker, equipment, character_target, target_equipment, rng, behind, true, combat.can_queue_fumbled_item())
	if resolution.total_damage() > 0:
		combat.mark_attacked(character_target.id)
	if resolution.fumbled and not _flow()._commit_character_fumble(state, attacker, equipment, events):
		events.append(DomainEvent.new(&"combat_fumble_failed", {"actorId": attacker.id, "reason": "invalid-fumble-state"}))
	_flow()._append_character_attack_audio(events, attacker, equipment, resolution, &"character")
	var event = _flow()._character_attack_event(attacker.id, character_target.id, &"character", resolution, equipment.melee_weapon != null)
	_append_reaction_identity(event, action, behind)
	events.append(event)
	if resolution.killed:
		combat.pending_reaction.mover_killed = true
		_flow()._mark_character_bleeding(state, character_target, true)
		_flow()._remove_defeated_position(combat, character_target.id, true)
		return REACTION_MOVER_DEFEATED
	return REACTION_COMPLETED

func _consume_character_attack(character: CharacterState) -> void:
	character.attacks_remaining = _rules.arithmetic.signed_16(character.attacks_remaining - 2)
	character.movement = maxi(0, character.movement - 3)

static func _projectile_spell_unavailable_reason(spell: SpellDefinition) -> String:
	if spell.target_type != 1:
		return "Classic projectile spell '%s' does not use a single-target picker." % spell.id
	if absi(spell.spell_class) != 9:
		return "Classic projectile spell '%s' is not missile class 9." % spell.id
	if absi(spell.damage_type) != 9:
		return "Elemental projectile spell '%s' requires its source-backed save and special-effect path." % spell.id
	if spell.special != 0:
		return "Projectile spell '%s' uses unresolved Classic special %d." % [spell.id, spell.special]
	return ""

func character_scroll_options(state: GameState, content: RealmzContent, caster_id: String) -> Array[CombatSpellOptionView]:
	var result: Array[CombatSpellOptionView] = []
	if state == null or content == null or state.combat == null or state.combat.active_actor_id() != caster_id:
		return result
	var caster := state.party.character_by_id(caster_id)
	if caster == null:
		return result
	for scroll_slot: int in caster.scroll_case().size():
		var scroll := caster.scroll_at(scroll_slot)
		var spell := content.spell_by_id(scroll.spell_id) if scroll != null and not scroll.is_empty() else null
		if spell == null:
			continue
		if spell.target_type == 0:
			if probe_character_scroll_cast(state, content, caster_id, scroll_slot).allowed:
				var candidates := _character_actor_spell_candidates(state, content, caster, spell, scroll.power)
				result.append(CombatScrollOptionViewType.new(scroll_slot, spell, scroll.power, null, "Choose up to %d actors" % scroll.power, &"sequence", 0, INVALID_COORDINATE, [], scroll.power, candidates))
			continue
		if spell.target_type in [9, 10, 12]:
			if probe_character_scroll_cast(state, content, caster_id, scroll_slot).allowed:
				result.append(CombatScrollOptionViewType.new(scroll_slot, spell, scroll.power, null, _group_spell_target_label(spell.target_type), &"automatic"))
			continue
		if spell.target_type in [3, 4]:
			if probe_character_scroll_cast(state, content, caster_id, scroll_slot).allowed:
				var shape := _rules.spell_areas.shape_for(spell, scroll.power)
				var offsets := _rules.spell_areas.pattern(shape)
				var legal_coordinates := _legal_area_spell_target_coordinates(state, content, caster_id, spell, scroll.power, shape)
				result.append(CombatScrollOptionViewType.new(scroll_slot, spell, scroll.power, null, "Choose battlefield point", &"area", shape, state.combat.battlefield.actor_position(caster_id), offsets, 1, [], legal_coordinates))
			continue
		if spell.target_type == 5:
			if probe_character_scroll_cast(state, content, caster_id, scroll_slot, caster_id).allowed:
				result.append(CombatScrollOptionViewType.new(scroll_slot, spell, scroll.power, _spell_target_view(state, content, caster_id)))
			continue
		for target: CombatSpellTargetView in _character_actor_spell_candidates(state, content, caster, spell, scroll.power):
			if probe_character_scroll_cast(state, content, caster_id, scroll_slot, target.id).allowed:
				result.append(CombatScrollOptionViewType.new(scroll_slot, spell, scroll.power, target))
	return result

func probe_character_spell_cast(state: GameState, content: RealmzContent, caster_id: String, target_id: String, spell_id: String, power_level: int, target_coordinate: Vector2i = INVALID_COORDINATE, rotation: int = 0, target_ids: Array[String] = []) -> CombatSpellCastProbe:
	var choice_probe := probe_character_spell_choice(state, content, caster_id, spell_id, power_level)
	if not choice_probe.allowed:
		return choice_probe
	var combat := state.combat
	var caster := state.party.character_by_id(caster_id)
	var spell := content.spell_by_id(spell_id)
	var repeated_target := spell.target_type == 0
	var group_target := spell.target_type in [9, 10, 12]
	var area_target := spell.target_type in [3, 4]
	if area_target and rotation != 0:
		return CombatSpellCastProbe.blocked(&"invalid_area_rotation", "This non-rotating Classic area spell requires rotation zero.")
	if repeated_target:
		if target_ids.size() > power_level:
			return CombatSpellCastProbe.blocked(&"too_many_spell_targets", "A repeated-target spell may select at most one distinct actor per power level.")
		var seen: Dictionary = {}
		for selected_id: String in target_ids:
			if selected_id.is_empty() or seen.has(selected_id):
				return CombatSpellCastProbe.blocked(&"invalid_repeated_spell_targets", "Repeated spell targets must be nonempty and distinct.")
			seen[selected_id] = true
			var selection := _spell_target_selection(state, content, selected_id)
			if selection == null:
				return CombatSpellCastProbe.blocked(&"invalid_spell_target", "A selected repeated-spell actor is unavailable.")
			if not _spell_actor_target_is_valid(state, content, caster.id, selected_id, spell, power_level):
				return CombatSpellCastProbe.blocked(&"spell_target_unavailable", "A selected repeated-spell actor is outside the Classic spell range or line of sight.")
		if target_ids.is_empty() and _character_actor_spell_candidates(state, content, caster, spell, power_level).is_empty():
			return CombatSpellCastProbe.blocked(&"spell_target_unavailable", "No actor is available within this repeated spell's Classic range and line of sight.")
	elif area_target:
		var shape := _rules.spell_areas.shape_for(spell, power_level, rotation)
		if target_coordinate == INVALID_COORDINATE:
			return CombatSpellCastProbe.blocked(&"invalid_spell_target", "Choose a battlefield center for this area spell.")
		if not _rules.spell_areas.pattern_fits(target_coordinate, shape):
			return CombatSpellCastProbe.blocked(&"spell_area_outside_battlefield", "The complete Classic area mask must remain inside the validated battlefield.")
		var map := content.world.map_by_id(combat.battlefield.map_id)
		var terrain_set := content.world.battle_terrain_set_by_id(map.battle_terrain_set_id) if map != null else null
		var maximum_range := absi(spell.range_min + spell.range_max * power_level)
		if terrain_set == null or not _rules.battlefield.coordinate_target_is_valid(combat.battlefield, terrain_set, caster.id, target_coordinate, maximum_range, spell.range_min + spell.range_max > 0):
			return CombatSpellCastProbe.blocked(&"spell_target_unavailable", "The area center is outside the Classic spell range or line of sight.")
	elif not group_target:
		if _spell_target_selection(state, content, target_id) == null:
			return CombatSpellCastProbe.blocked(&"invalid_spell_target", "The spell target is unavailable.")
		if not _spell_actor_target_is_valid(state, content, caster.id, target_id, spell, power_level):
			return CombatSpellCastProbe.blocked(&"spell_target_unavailable", "The target is outside the Classic spell range or line of sight.")
	return CombatSpellCastProbe.permitted()

func _hostile_adjacent_ids(state: GameState, actor_id: String) -> Array[String]:
	var actor := state.party.character_by_id(actor_id)
	var result: Array[String] = []
	if actor == null:
		return result
	for target_id: String in _rules.battlefield.adjacent_actor_ids(state.combat.battlefield, actor_id):
		if not _actor_is_friendly(state, actor, target_id):
			result.append(target_id)
	return result

func _hostile_adjacent_ids_for_monster(state: GameState, monster: MonsterState) -> Array[String]:
	var result: Array[String] = []
	for target_id: String in _rules.battlefield.adjacent_actor_ids(state.combat.battlefield, monster.id):
		var character := state.party.character_by_id(target_id)
		var target_monster := state.combat.monster_by_id(target_id)
		if (character != null and character.current_health > 0 and character.traitor != monster.traitor) or (target_monster != null and target_monster.current_health > 0 and target_monster.traitor != monster.traitor):
			result.append(target_id)
	return result

static func _actor_is_friendly(state: GameState, actor: CharacterState, target_id: String) -> bool:
	var character := state.party.character_by_id(target_id)
	if character != null:
		return character.traitor == actor.traitor
	var monster := state.combat.monster_by_id(target_id)
	return monster != null and monster.traitor == actor.traitor

static func _target_health(state: GameState, target_id: String) -> int:
	var character := state.party.character_by_id(target_id)
	if character != null:
		return character.current_health
	var monster := state.combat.monster_by_id(target_id)
	return monster.current_health if monster != null else 0x7fff_ffff

static func _target_maximum_health(state: GameState, target_id: String) -> int:
	var character := state.party.character_by_id(target_id)
	if character != null:
		return character.maximum_health
	var monster := state.combat.monster_by_id(target_id)
	return monster.maximum_health if monster != null else 1

func _opposed_actor_ids(state: GameState, actor: CharacterState) -> Array[String]:
	var result: Array[String] = []
	for character: CharacterState in state.party.characters():
		if character.id != actor.id and character.current_health > 0 and character.traitor != actor.traitor and state.combat.battlefield.has_actor(character.id):
			result.append(character.id)
	for monster: MonsterState in state.combat.monsters():
		if monster.current_health > 0 and monster.traitor != actor.traitor and state.combat.battlefield.has_actor(monster.id):
			result.append(monster.id)
	return result

static func _target_hard_immune(state: GameState, content: RealmzContent, target_id: String, spell: SpellDefinition) -> bool:
	var character := state.party.character_by_id(target_id)
	if character != null:
		return character.magic_resistance > 100
	var monster := state.combat.monster_by_id(target_id)
	var definition := content.monster_by_id(monster.definition_id) if monster != null else null
	return monster != null and (monster.magic_resistance > 100 or definition != null and definition.spell_immune(spell.spell_class))

static func _roll_weapon_physical(weapon: ItemDefinition, defender_definition: MonsterDefinition, rng: RealmzRng) -> int:
	var damage := 0
	if defender_definition != null:
		if weapon.vs_undead != 0 and defender_definition.type_flag(1):
			damage += rng.draw(maxi(1, weapon.vs_undead), &"combat.attack.weapon-versus-undead")
		if weapon.vs_demon_devil != 0 and defender_definition.type_flag(2):
			damage += rng.draw(maxi(1, weapon.vs_demon_devil), &"combat.attack.weapon-versus-demon-devil")
		if weapon.vs_evil != 0 and defender_definition.type_flag(4):
			damage += rng.draw(maxi(1, weapon.vs_evil), &"combat.attack.weapon-versus-evil")
	# Castle's player melee path always uses the small-target weapon die, including Rand(0).
	damage += rng.draw(maxi(1, weapon.vs_small), &"combat.attack.weapon-physical")
	return damage

func character_scroll_unavailable_reason(state: GameState, content: RealmzContent, caster_id: String) -> String:
	if state == null or state.combat == null or state.combat.active_actor_id() != caster_id:
		return "Only the active character may use a scroll."
	var caster := state.party.character_by_id(caster_id)
	if caster == null:
		return "The active character is unavailable."
	if not _has_equipped_scroll_case(caster, content):
		return "Equip a scroll case before using its spells."
	for scroll_slot: int in caster.scroll_case().size():
		var scroll := caster.scroll_at(scroll_slot)
		if scroll == null or scroll.is_empty():
			continue
		var spell := content.spell_by_id(scroll.spell_id)
		if spell == null:
			return "A stored scroll references an unavailable spell."
		var target_id := caster_id if spell.target_type == 5 else ""
		var probe := probe_character_scroll_cast(state, content, caster_id, scroll_slot, target_id)
		if not probe.allowed:
			return probe.reason_text
	return "The equipped scroll case contains no combat-ready spells."

func _best_damage_spell(state: GameState, content: RealmzContent, actor: CharacterState, spell: SpellDefinition, option: CombatSpellOptionView, actors_by_cell: Dictionary, area_placement_cache: Dictionary) -> Dictionary:
	var expected := expected_spell_effect(spell, option.power)
	if expected <= 0:
		return {}
	if spell.target_type in [3, 4]:
		return _best_area(state, content, actor, spell, option, expected, actors_by_cell, area_placement_cache)
	var targets := _hostile_spell_targets(state, content, actor, spell, option.power)
	if targets.is_empty():
		return {}
	var cost_penalty := absi(spell.cost * option.power) * 3
	if spell.target_type == 10:
		return {"action": &"cast_spell", "spellId": spell.id, "power": option.power, "score": 360 + targets.size() * expected * 6 - cost_penalty}
	if spell.target_type == 0:
		var selected: Array[String] = []
		for target_id: String in targets:
			if selected.size() >= option.power:
				break
			selected.append(target_id)
		return {"action": &"cast_spell", "spellId": spell.id, "power": option.power, "targetIds": selected, "score": 350 + selected.size() * expected * 5 - cost_penalty}
	var best: Dictionary = {}
	for target_id: String in targets:
		var score := 350 + expected * 5 + _lethal_bonus(state, target_id, expected) - cost_penalty
		best = _prefer(best, {"action": &"cast_spell", "spellId": spell.id, "power": option.power, "targetId": target_id, "score": score})
	return best

func _best_area(state: GameState, content: RealmzContent, actor: CharacterState, spell: SpellDefinition, option: CombatSpellOptionView, expected: int, actors_by_cell: Dictionary, area_placement_cache: Dictionary) -> Dictionary:
	var maximum_range := absi(spell.range_min + spell.range_max * option.power)
	var cache_key := "%d:%d:%d:%d" % [option.area_shape, maximum_range, 1 if spell.range_min + spell.range_max > 0 else 0, spell.spell_class]
	if not area_placement_cache.has(cache_key):
		var placements: Array[Dictionary] = []
		for center: Vector2i in _area_candidate_centers(state, content, actor, spell, option):
			var hostile_ids: Dictionary = {}
			var harms_friend := false
			for offset: Vector2i in option.area_offsets:
				var target_id := String(actors_by_cell.get(center + offset, ""))
				if target_id.is_empty():
					continue
				if _actor_is_friendly(state, actor, target_id):
					harms_friend = true
				elif not _target_hard_immune(state, content, target_id, spell) and not _target_reflects(state, target_id):
					hostile_ids[target_id] = true
			if not harms_friend and not hostile_ids.is_empty():
				placements.append({"center": center, "hostileCount": hostile_ids.size()})
		area_placement_cache[cache_key] = placements
	var best: Dictionary = {}
	for placement: Dictionary in area_placement_cache[cache_key]:
		var score := 370 + int(placement["hostileCount"]) * expected * 7 - option.cost * 3
		best = _prefer(best, {"action": &"cast_spell", "spellId": spell.id, "power": option.power, "coordinate": placement["center"], "score": score})
	return best

func _area_candidate_centers(state: GameState, content: RealmzContent, actor: CharacterState, spell: SpellDefinition, option: CombatSpellOptionView) -> Array[Vector2i]:
	var unique: Dictionary = {}
	for target_id: String in _opposed_actor_ids(state, actor):
		if _target_hard_immune(state, content, target_id, spell) or _target_reflects(state, target_id):
			continue
		for target_cell: Vector2i in state.combat.battlefield.actor_footprint(target_id):
			for offset: Vector2i in option.area_offsets:
				unique[target_cell - offset] = true
	var map := content.world.map_by_id(state.combat.battlefield.map_id)
	var terrain_set := content.world.battle_terrain_set_by_id(map.battle_terrain_set_id) if map != null else null
	if terrain_set == null:
		return []
	var maximum_range := absi(spell.range_min + spell.range_max * option.power)
	var require_line_of_sight := spell.range_min + spell.range_max > 0
	var result: Array[Vector2i] = []
	for value: Variant in unique:
		var center: Vector2i = value
		if _rules.spell_areas.pattern_fits(center, option.area_shape) and _rules.battlefield.coordinate_target_is_valid(state.combat.battlefield, terrain_set, actor.id, center, maximum_range, require_line_of_sight):
			result.append(center)
	result.sort_custom(func(left: Vector2i, right: Vector2i) -> bool: return left.y < right.y or (left.y == right.y and left.x < right.x))
	return result

func _best_heal(state: GameState, content: RealmzContent, actor: CharacterState, spell: SpellDefinition, power: int) -> Dictionary:
	var best: Dictionary = {}
	for target: CharacterState in state.party.characters():
		if target.current_health <= 0 or target.traitor != actor.traitor or target.current_health >= target.maximum_health:
			continue
		if not _flow().probe_character_spell_cast(state, content, actor.id, target.id, spell.id, power).allowed:
			continue
		var health_percent := 100 * target.current_health / maxi(1, target.maximum_health)
		if health_percent > 65:
			continue
		var urgency := 980 if health_percent <= 35 else 680
		var score := urgency + 100 - health_percent - absi(spell.cost * power) * 3
		best = _prefer(best, {"action": &"cast_spell", "spellId": spell.id, "power": power, "targetId": target.id, "score": score})
	return best

func bandage_candidate_ids(state: GameState) -> Array[String]:
	var result: Array[String] = []
	if state == null or state.combat == null:
		return result
	for character: CharacterState in state.party.characters():
		if state.combat.is_character_bleeding(character.id) and character.current_health > -10:
			result.append(character.id)
	return result

func turn_undead_target_ids(state: GameState, content: RealmzContent) -> Array[String]:
	var result: Array[String] = []
	if state == null or state.combat == null or content == null or state.combat.battlefield == null:
		return result
	for monster: MonsterState in state.combat.monsters():
		var definition := content.monster_by_id(monster.definition_id)
		# Providence normalizes Castle's unsigned byte sentinel 255 to signed -1.
		if monster.current_health > 0 and monster.traitor and state.combat.battlefield.has_actor(monster.id) and definition != null and definition.can_summon != -1 and (definition.type_flag(1) or definition.type_flag(2)):
			result.append(monster.id)
	return result

func probe_turn_undead(state: GameState, content: RealmzContent, actor_id: String) -> CombatCommandProbeType:
	var actor := state.party.character_by_id(actor_id) if state != null else null
	var combat := state.combat if state != null else null
	if actor == null or combat == null or combat.completed or combat.active_actor_id() != actor_id or actor.current_health <= 0 or actor.traitor:
		return CombatCommandProbeType.new(false, "Only the active loyal character can Turn Undead.")
	if not state.priest_turning_allowed:
		return CombatCommandProbeType.new(false, "This campaign location forbids priest turning.")
	if actor.ability_value(13) <= 0:
		return CombatCommandProbeType.new(false, "This character has no Turn Undead ability.")
	if combat.has_used_turn_undead(actor.id):
		return CombatCommandProbeType.new(false, "This character has already attempted Turn Undead in this battle.")
	if combat.active_turn != null and actor.attacks_remaining < 2:
		return CombatCommandProbeType.new(false, "Turn Undead requires one remaining attack.")
	if turn_undead_target_ids(state, content).is_empty():
		return CombatCommandProbeType.new(false, "No hostile undead or nether spawn can be turned.")
	return CombatCommandProbeType.new(true)

func _turn_undead(state: GameState, content: RealmzContent, actor: CharacterState, rng: RealmzRng) -> CombatFlowResult:
	_prepare_character_turn(state.combat, actor)
	var probe := probe_turn_undead(state, content, actor.id)
	if not probe.allowed:
		return CombatFlowResult.failed(&"combat_turn_undead_unavailable", probe.reason_text)
	var combat := state.combat
	combat.invalidate_undo()
	var target_ids := turn_undead_target_ids(state, content)
	var macro_count := 0
	for target_id: String in target_ids:
		var target := combat.monster_by_id(target_id)
		var definition := content.monster_by_id(target.definition_id) if target != null else null
		if definition != null and definition.death_macro > 0:
			macro_count += 1
	if macro_count > CombatState.MAX_SPELL_DEATH_MACROS - combat.spell_death_macro_queue().size():
		return CombatFlowResult.failed(&"combat_turn_undead_macro_limit", "Turn Undead would exceed the bounded death-macro queue.")
	var events: Array[DomainEvent] = [DomainEvent.new(&"sound_requested", {"soundId": 659, "waitForCompletion": false, "source": "classic-combat-turn-undead"})]
	combat.mark_turn_undead_used(actor.id)
	events.append(DomainEvent.new(&"combat_turn_undead_attempted", {"actorId": actor.id, "ability": actor.ability_value(13), "targetIds": target_ids.duplicate(), "source": "classic"}))
	for target_id: String in target_ids:
		var target := combat.monster_by_id(target_id)
		var definition := content.monster_by_id(target.definition_id)
		var threshold := maxi(25, 100 - actor.ability_value(13) + 5 * target.hit_dice) + target.magic_resistance
		var roll := rng.draw(100, StringName("combat.turn-undead.%s" % target.id))
		var margin := roll - threshold
		var result_kind := "resisted"
		var experience_award := 0
		if margin > 0 and margin < 30:
			result_kind = "destroyed"
			experience_award = 25 * target.hit_dice
			target.current_health = 0
			events.append(DomainEvent.new(&"sound_requested", {"soundId": 132, "waitForCompletion": false, "source": "classic-combat-turn-undead"}))
			if not _queue_spell_death_macro(combat, target, definition):
				_flow()._remove_defeated_position(combat, target.id, true)
		elif margin >= 30:
			result_kind = "turned"
			experience_award = 50 * target.hit_dice
			target.traitor = actor.traitor
			target.target_id = ""
			combat.set_guarding(target.id, false)
			events.append(DomainEvent.new(&"sound_requested", {"soundId": 630, "waitForCompletion": false, "source": "classic-combat-turn-undead"}))
		actor.experience = _rules.arithmetic.signed_32(actor.experience + experience_award)
		events.append(DomainEvent.new(&"combat_turn_undead_resolved", {
			"actorId": actor.id,
			"targetId": target.id,
			"result": result_kind,
			"threshold": threshold,
			"roll": roll,
			"margin": margin,
			"experience": experience_award,
			"effectResourceType": "CIcon" if result_kind == "turned" else "",
			"effectResourceId": 12056 if result_kind == "turned" else 0,
			"effectFrameCount": 8 if result_kind == "turned" else 0,
			"source": "classic",
		}))
	actor.attacks_remaining = _rules.arithmetic.signed_16(actor.attacks_remaining - 2)
	var advances_turn := not _character_can_continue(actor)
	if not combat.pending_spell_death_macro_id().is_empty():
		if not combat.begin_spell_death_macro_sequence(actor.id, advances_turn) or not _request_next_spell_death_macro(combat, content, events):
			return CombatFlowResult.failed(&"invalid_turn_undead_macro_queue", "Turn Undead could not begin its source-ordered death-macro continuation.")
		return CombatFlowResult.succeeded(events)
	if advances_turn:
		_flow()._advance_turn(state, rng, events)
	return CombatFlowResult.succeeded(events)

func probe_undo(state: GameState, actor_id: String) -> CombatCommandProbeType:
	var actor := state.party.character_by_id(actor_id) if state != null else null
	var combat := state.combat if state != null else null
	if actor == null or combat == null or combat.completed or combat.active_actor_id() != actor_id or actor.current_health <= 0:
		return CombatCommandProbeType.new(false, "Only the active living character can Undo.")
	if actor.traitor or actor.conditions.is_active(ConditionRules.HELPLESS) or actor.conditions.is_active(ConditionRules.CONFUSED):
		return CombatCommandProbeType.new(false, "This character's current combat state prevents Undo.")
	if combat.pending_reaction != null or combat.pending_monster_attack != null:
		return CombatCommandProbeType.new(false, "Resolve the current combat result before using Undo.")
	var undo := combat.undo_state
	if combat.active_turn == null or undo == null or not undo.available or undo.actor_id != actor_id or undo.round_number != combat.round_number or undo.turn_index != combat.turn_index:
		return CombatCommandProbeType.new(false, "Undo is unavailable after a combat result.")
	if combat.battlefield == null or not combat.battlefield.has_actor(actor_id):
		return CombatCommandProbeType.new(false, "The active character has no battlefield position to restore.")
	var occupant := combat.battlefield.actor_at(undo.start_position, actor_id)
	if not occupant.is_empty():
		return CombatCommandProbeType.new(false, "The activation-start position is occupied.")
	return CombatCommandProbeType.new(true)

func cause_active_fumble(state: GameState, content: RealmzContent, actor_id: String) -> CombatFlowResult:
	if state == null or content == null or state.combat == null or state.combat.completed:
		return CombatFlowResult.failed(&"no_active_battle", "No Realmz battle can receive a fumble operation.")
	if actor_id.is_empty():
		actor_id = state.combat.active_actor_id()
	if actor_id != state.combat.active_actor_id():
		return CombatFlowResult.failed(&"invalid_fumble_actor", "Classic opcode 122 can affect only the active physical combatant.")
	if state.combat.active_turn == null or not state.combat.active_turn.physical_action_committed:
		return CombatFlowResult.succeeded([DomainEvent.new(&"combat_fumble_skipped", {"combatantId": actor_id, "reason": "no-physical-action", "source": "classic"})])
	var events: Array[DomainEvent] = []
	var character := state.party.character_by_id(actor_id)
	# Castle's outer q[up] < 10 guard excludes monster initiative IDs (10+).
	# The monster branch nested below that guard is therefore unreachable.
	if character == null:
		return CombatFlowResult.succeeded([DomainEvent.new(&"combat_fumble_skipped", {"combatantId": actor_id, "reason": "not-party-actor", "source": "classic"})])
	var equipment := _rules.inventory.combat_equipment(character, content.item_definitions())
	if not equipment.valid:
		return CombatFlowResult.failed(equipment.error_code, equipment.error_message)
	if not equipment.is_armed():
		return CombatFlowResult.succeeded([DomainEvent.new(&"combat_fumble_skipped", {"combatantId": actor_id, "reason": "unarmed", "source": "classic"})])
	if not equipment.melee_weapon.cursed_item_id.is_empty():
		return CombatFlowResult.succeeded([DomainEvent.new(&"combat_fumble_skipped", {"combatantId": actor_id, "reason": "cursed-weapon", "source": "classic"})])
	if not state.combat.can_queue_fumbled_item():
		return CombatFlowResult.succeeded([DomainEvent.new(&"combat_fumble_skipped", {"combatantId": actor_id, "reason": "queue-full", "source": "classic"})])
	if not _commit_character_fumble(state, character, equipment, events):
		return CombatFlowResult.failed(&"invalid_fumble_state", "The active character's melee weapon could not enter the recovery queue.")
	return CombatFlowResult.succeeded(events)

func probe_bandage(state: GameState, actor_id: String, target_id: String = "") -> CombatCommandProbeType:
	var actor := state.party.character_by_id(actor_id) if state != null else null
	var combat := state.combat if state != null else null
	if actor == null or combat == null or combat.completed or combat.active_actor_id() != actor_id or actor.current_health <= 0 or actor.traitor:
		return CombatCommandProbeType.new(false, "Only the active loyal character can Bandage.")
	if not _is_fresh_character_activation(combat, actor):
		return CombatCommandProbeType.new(false, "Bandage is available only before moving, attacking, or casting this activation.")
	var candidates := bandage_candidate_ids(state)
	if candidates.is_empty():
		return CombatCommandProbeType.new(false, "No party member is bleeding.")
	if not target_id.is_empty() and not candidates.has(target_id):
		return CombatCommandProbeType.new(false, "The selected party member is not a legal bleeding recipient.")
	return CombatCommandProbeType.new(true)

func _best_party_spell(state: GameState, content: RealmzContent, actor: CharacterState) -> Dictionary:
	var best: Dictionary = {}
	var actors_by_cell := _actors_by_cell(state.combat.battlefield)
	var area_placement_cache: Dictionary = {}
	for option: CombatSpellOptionView in _flow().character_spell_options(state, content, actor.id):
		var spell := content.spell_by_id(option.spell_id)
		if spell == null:
			continue
		if _flow()._is_source_backed_combat_healing_spell(spell):
			best = _prefer(best, _best_heal(state, content, actor, spell, option.power))
		elif spell.target_type in [0, 1, 3, 4, 10]:
			best = _prefer(best, _best_damage_spell(state, content, actor, spell, option, actors_by_cell, area_placement_cache))
	return best

static func _weighted_choice(candidates: Array[Dictionary], rng: RealmzRng, semantic_tag: StringName) -> Dictionary:
	var choices: Array[Dictionary] = []
	for candidate: Dictionary in candidates:
		if not candidate.is_empty() and int(candidate.get("score", 0)) > 0:
			choices.append(candidate)
	if choices.is_empty():
		return {}
	choices.sort_custom(func(left: Dictionary, right: Dictionary) -> bool:
		var left_score := int(left.get("score", 0))
		var right_score := int(right.get("score", 0))
		return left_score > right_score or (left_score == right_score and _choice_key(left) < _choice_key(right))
	)
	if choices.size() == 1:
		return choices[0]
	var weights: Array[int] = []
	var total_weight := 0
	for choice: Dictionary in choices:
		var weight := maxi(1, int(choice.get("score", 0)))
		weights.append(weight)
		total_weight += weight
	while total_weight > MAX_WEIGHTED_DRAW:
		var divisor := (total_weight + MAX_WEIGHTED_DRAW - 1) / MAX_WEIGHTED_DRAW
		total_weight = 0
		for index: int in weights.size():
			weights[index] = maxi(1, weights[index] / divisor)
			total_weight += weights[index]
	var roll := rng.draw(total_weight, semantic_tag)
	var threshold := 0
	for index: int in choices.size():
		threshold += weights[index]
		if roll <= threshold:
			return choices[index]
	return choices.back()

func _init(is_allowed: bool, reason: String = "") -> void:
	allowed = is_allowed
	reason_text = reason

static func _target_reflects(state: GameState, target_id: String) -> bool:
	var character := state.party.character_by_id(target_id)
	if character != null:
		return character.conditions.is_active(ConditionRules.REFLECTING_SPELLS)
	var monster := state.combat.monster_by_id(target_id)
	return monster != null and monster.conditions.is_active(ConditionRules.REFLECTING_SPELLS)

func _best_projectile(state: GameState, content: RealmzContent, actor: CharacterState) -> Dictionary:
	if state.combat.character_weapon_mode(actor.id) != &"missile":
		return {}
	var profile = _flow().character_projectile_profile(actor, content, _rules.inventory.combat_equipment(actor, content.item_definitions()))
	if profile == null or not profile.available:
		return {"action": &"switch_weapon", "score": 110}
	var best: Dictionary = {}
	for target_id: String in _opposed_actor_ids(state, actor):
		if _flow().projectile_target_is_valid(state.combat, content, actor.id, target_id, profile.maximum_range, profile.spell.range_min + profile.spell.range_max > 0):
			best = _prefer(best, {"action": &"attack", "targetId": target_id, "score": 330 + _lethal_pressure(state, target_id)})
	return best if not best.is_empty() else {"action": &"switch_weapon", "score": 110}

func _hostile_spell_targets(state: GameState, content: RealmzContent, actor: CharacterState, spell: SpellDefinition, power: int) -> Array[String]:
	var result: Array[String] = []
	for target_id: String in _opposed_actor_ids(state, actor):
		var target_character := state.party.character_by_id(target_id)
		var target_monster := state.combat.monster_by_id(target_id)
		if _target_hard_immune(state, content, target_id, spell) or (target_character != null and target_character.conditions.is_active(ConditionRules.REFLECTING_SPELLS)) or (target_monster != null and target_monster.conditions.is_active(ConditionRules.REFLECTING_SPELLS)):
			continue
		if _flow().probe_character_spell_cast(state, content, actor.id, target_id, spell.id, power).allowed:
			result.append(target_id)
	result.sort_custom(func(left: String, right: String) -> bool: return _target_health(state, left) < _target_health(state, right) or (_target_health(state, left) == _target_health(state, right) and left < right))
	return result

static func _actors_by_cell(battlefield: BattlefieldState) -> Dictionary:
	var result: Dictionary = {}
	for actor_id: String in battlefield.actor_ids():
		for coordinate: Vector2i in battlefield.actor_footprint(actor_id):
			result[coordinate] = actor_id
	return result

static func _choice_key(choice: Dictionary) -> String:
	var target_ids: Array = choice.get("targetIds", [])
	return "%s|%s|%s|%s|%s" % [String(choice.get("action", "")), String(choice.get("spellId", "")), String(choice.get("targetId", "")), ",".join(target_ids), str(choice.get("coordinate", Vector2i(-1, -1)))]

func _init(flow: RefCounted, rules: ContextType) -> void:
	_flow_ref = weakref(flow)
	_rules = rules

func choose_party_action(state: GameState, content: RealmzContent, actor: CharacterState, rng: RealmzRng) -> Dictionary:
	var choices: Array[Dictionary] = []
	if _flow().probe_bandage(state, actor.id).allowed:
		var bandage: Dictionary = {}
		for target_id: String in _flow().bandage_candidate_ids(state):
			var target := state.party.character_by_id(target_id)
			bandage = _prefer(bandage, {"action": &"bandage", "targetId": target_id, "score": 1100 - (target.current_health if target != null else 0)})
		_append_positive_choice(choices, bandage)
	if _flow().probe_turn_undead(state, content, actor.id).allowed:
		choices.append({"action": &"turn_undead", "score": 760})
	_append_positive_choice(choices, _best_party_spell(state, content, actor))
	var adjacent_ids := _hostile_adjacent_ids(state, actor.id)
	if not adjacent_ids.is_empty():
		if state.combat.character_weapon_mode(actor.id) == &"missile":
			choices.append({"action": &"switch_weapon", "score": 640})
		else:
			var melee: Dictionary = {}
			for target_id: String in adjacent_ids:
				melee = _prefer(melee, {"action": &"attack", "targetId": target_id, "score": 520 + _lethal_pressure(state, target_id)})
			_append_positive_choice(choices, melee)
	else:
		_append_positive_choice(choices, _best_projectile(state, content, actor))
		choices.append({"action": &"move", "score": 100})
	var selected := _weighted_choice(choices, rng, StringName("combat.auto.%s.action-choice" % actor.id))
	return {"action": &"defend", "score": 0} if selected.is_empty() else selected

func choose_monster_action(state: GameState, content: RealmzContent, monster: MonsterState, definition: MonsterDefinition, rng: RealmzRng, allow_missile: bool = true) -> StringName:
	if monster.conditions.is_active(ConditionRules.RUNS_AWAY):
		return &"retreat"
	var adjacent := not _hostile_adjacent_ids_for_monster(state, monster).is_empty()
	var choices: Array[Dictionary] = [{"action": &"advance", "score": 560 if adjacent else 100}]
	var spell_plan := best_monster_spell_plan(state, content, monster, definition)
	var cast_score := int(spell_plan.get("score", -1)) + definition.cast_percent
	if not spell_plan.is_empty() and cast_score > 0:
		choices.append({"action": &"cast", "score": cast_score})
	if allow_missile and not adjacent and not definition.item_id_at(1).is_empty():
		var missile_score := 250 + definition.missile_percent * 2
		if missile_score > 0:
			choices.append({"action": &"missile", "score": missile_score})
	var selected := _weighted_choice(choices, rng, StringName("combat.monster.%s.action-choice" % monster.id))
	return StringName(selected.get("action", &"advance"))

func best_monster_spell_plan(state: GameState, content: RealmzContent, monster: MonsterState, definition: MonsterDefinition) -> Dictionary:
	if state.monster_spellcasting_blocked or state.combat.was_attacked(monster.id) or definition.magic_attack_count <= 0:
		return {}
	for condition: int in [ConditionRules.STUPID, ConditionRules.CONFUSED, ConditionRules.SILENCED, ConditionRules.HELPLESS]:
		if monster.conditions.is_active(condition):
			return {}
	var best: Dictionary = {}
	for slot: int in 10:
		var spell := content.spell_by_id(definition.spell_id_at(slot))
		if spell == null or not _flow()._monster_spell_unavailable_reason(spell).is_empty():
			continue
		var maximum_power := mini(7, monster.spell_points / maxi(1, spell.cost))
		for power: int in range(1, maximum_power + 1):
			var plan := _monster_spell_power_plan(state, content, monster, spell, slot, power)
			best = _prefer(best, plan)
	return best

func _monster_spell_power_plan(state: GameState, content: RealmzContent, monster: MonsterState, spell: SpellDefinition, slot: int, power: int) -> Dictionary:
	var friendly := spell.cannot == 4
	var candidates: Array[String] = []
	for character: CharacterState in state.party.characters():
		if character.current_health > 0 and (character.traitor == monster.traitor) == friendly and not _target_reflects(state, character.id) and (friendly or not _target_hard_immune(state, content, character.id, spell)) and state.combat.battlefield.has_actor(character.id) and _flow()._spell_actor_target_is_valid(state, content, monster.id, character.id, spell, power):
			candidates.append(character.id)
	for candidate: MonsterState in state.combat.monsters():
		if candidate.current_health > 0 and (candidate.traitor == monster.traitor) == friendly and not _target_reflects(state, candidate.id) and (friendly or not _target_hard_immune(state, content, candidate.id, spell)) and state.combat.battlefield.has_actor(candidate.id) and content.monster_by_id(candidate.definition_id) != null and _flow()._spell_actor_target_is_valid(state, content, monster.id, candidate.id, spell, power):
			candidates.append(candidate.id)
	if candidates.is_empty():
		return {}
	var healing: bool = _flow()._is_source_backed_combat_healing_spell(spell)
	var target_scores: Dictionary = {}
	for target_id: String in candidates:
		target_scores[target_id] = _monster_target_score(state, target_id, spell, power, healing)
	candidates.sort_custom(func(left: String, right: String) -> bool: return int(target_scores[left]) > int(target_scores[right]) or (target_scores[left] == target_scores[right] and left < right))
	var selected: Array[String] = []
	for target_id: String in candidates:
		if selected.size() >= (power if spell.target_type == 0 else 1):
			break
		if not healing or _target_missing_health(state, target_id) > 0:
			selected.append(target_id)
	if selected.is_empty():
		return {}
	var score := 0
	for target_id: String in selected:
		score += _monster_target_score(state, target_id, spell, power, healing)
	return {"spellId": spell.id, "spellSlot": slot, "power": power, "targetIds": selected, "score": score - spell.cost * power * 3}

func _monster_target_score(state: GameState, target_id: String, spell: SpellDefinition, power: int, healing: bool) -> int:
	var expected := expected_spell_effect(spell, power)
	if healing:
		var missing := _target_missing_health(state, target_id)
		var health_percent := 100 * _target_health(state, target_id) / maxi(1, _target_maximum_health(state, target_id))
		return (950 if health_percent <= 35 else 650 if health_percent <= 65 else 180) + mini(missing, expected) * 5
	return 340 + expected * 5 + _lethal_bonus(state, target_id, expected)

static func _append_positive_choice(choices: Array[Dictionary], candidate: Dictionary) -> void:
	if not candidate.is_empty() and int(candidate.get("score", 0)) > 0:
		choices.append(candidate)

static func _inventory_identify_cast(context: SessionWorkflowContext, target: CharacterState) -> Array[String]:
	for caster: CharacterState in context.state.party.characters():
		var spells: Array[SpellDefinition] = []
		for spell_id: String in caster.known_spells():
			var spell := context.content.spell_by_id(spell_id)
			if spell != null and absi(spell.special) == 48:
				spells.append(spell)
		spells.sort_custom(func(left: SpellDefinition, right: SpellDefinition) -> bool: return left.classic_id < right.classic_id)
		for spell: SpellDefinition in spells:
			if InventoryMagicServicesWorkflow.inventory_identify_probe(context, target.id, caster.id, spell.id).allowed:
				return [caster.id, spell.id]
	return []

func trigger_by_map_record(map_id: String, record_index: int) -> TriggerDefinition:
	for value: Variant in _triggers.values():
		var trigger := value as TriggerDefinition
		if trigger.map_id == map_id and trigger.classic_record_index == record_index:
			return trigger
	return null

func _init(option_label_id: int, option_text: String) -> void:
	id = option_label_id
	text = option_text

func _init(campaign: String, package_identity: String, content_identity: String, rules: String, start_map: String, start_position: Vector2i, world_definition: WorldDefinition, scenario_definition: ScenarioDefinition, messages: Array[MessageDefinition], triggers: Array[TriggerDefinition], simple_encounters: Array[SimpleEncounterDefinition] = [], races: Array[RaceDefinition] = [], castes: Array[CasteDefinition] = [], items: Array[ItemDefinition] = [], spells: Array[SpellDefinition] = [], monsters: Array[MonsterDefinition] = [], battles: Array[BattleDefinition] = [], treasures: Array[TreasureDefinition] = [], shops: Array[ShopDefinition] = [], complex_encounters: Array[ComplexEncounterDefinition] = [], thief_encounters: Array[ThiefEncounterDefinition] = [], authored_timed_encounters: Array[TimedEncounterDefinition] = [], authored_option_labels: Array[OptionLabelDefinition] = [], campaign_definition: CampaignDefinition = null, appearance_options: Array[CharacterAppearanceDefinition] = [], monster_sets: Dictionary = {}) -> void:
	campaign_id = campaign
	package_hash = package_identity
	content_id = content_identity
	rules_version = rules
	start_map_id = start_map
	start_coordinate = start_position
	world = world_definition
	scenario = scenario_definition
	self.campaign = campaign_definition if campaign_definition != null else CampaignDefinition.new()
	self.campaign.id = campaign_id if self.campaign.id.is_empty() else self.campaign.id
	for message: MessageDefinition in messages:
		_messages[message.id] = message
	for option_label: OptionLabelDefinition in authored_option_labels:
		_option_labels[option_label.id] = option_label
	for trigger: TriggerDefinition in triggers:
		_triggers[trigger.id] = trigger
	for encounter: SimpleEncounterDefinition in simple_encounters:
		_simple_encounters[encounter.id] = encounter
	for encounter: ComplexEncounterDefinition in complex_encounters:
		_complex_encounters[encounter.id] = encounter
	for encounter: ThiefEncounterDefinition in thief_encounters:
		_thief_encounters[encounter.id] = encounter
	for encounter: TimedEncounterDefinition in authored_timed_encounters:
		_timed_encounters[encounter.id] = encounter
	for race: RaceDefinition in races:
		_races[race.id] = race
	for caste: CasteDefinition in castes:
		_castes[caste.id] = caste
	for item: ItemDefinition in items:
		_items[item.id] = item
	for spell: SpellDefinition in spells:
		_spells[spell.id] = spell
	for monster: MonsterDefinition in monsters:
		_monsters[monster.id] = monster
	for set_id: Variant in monster_sets:
		var records: Dictionary = {}
		for monster: MonsterDefinition in monster_sets[set_id]:
			records["classic.monster.%d" % monster.classic_id] = monster
			_monsters[monster.id] = monster
		_monster_sets[int(set_id)] = records
	for battle: BattleDefinition in battles:
		_battles[battle.id] = battle
	for treasure: TreasureDefinition in treasures:
		_treasures[treasure.id] = treasure
	for shop: ShopDefinition in shops:
		_shops[shop.id] = shop
	for option: CharacterAppearanceDefinition in appearance_options:
		_appearance_options[option.id] = option
		_appearance_by_resource[_appearance_resource_key(option.kind, option.classic_resource_id)] = option

