	return terrain_set != null and _rules.battlefield.projectile_target_is_valid(combat.battlefield, terrain_set, actor_id, target_id, maximum_range, require_line_of_sight)

func probe_edge_retreat(combat: CombatState, actor_id: String, destination: Vector2i):
	if combat == null or combat.completed or combat.battlefield == null or combat.active_actor_id() != actor_id or not combat.battlefield.has_actor(actor_id):
		return CombatRetreatProbeType.blocked(&"invalid_combat_actor", "The active character is unavailable.")
	var origin := combat.battlefield.actor_position(actor_id)
	var direction := destination - origin
	if direction == Vector2i.ZERO or absi(direction.x) > 1 or absi(direction.y) > 1:
		return CombatRetreatProbeType.blocked(&"invalid_direction", "Battlefield-edge retreat requires one adjacent movement direction.")
	if destination.x >= 2 and destination.y >= 2 and destination.x <= 87 and destination.y <= 87:
		return CombatRetreatProbeType.blocked(&"not_battlefield_edge", "This movement does not enter Castle's retreat band.")
	var forced := origin.x < 1 or origin.y < 1 or origin.x > 88 or origin.y > 88
	return CombatRetreatProbeType.permitted(127, forced)

func retreat_character(state: GameState, content: RealmzContent, actor_id: String, mode: StringName, destination: Vector2i, rng: RealmzRng) -> CombatFlowResult:
	var combat := state.combat
	if combat == null or combat.completed or combat.battlefield == null or combat.active_actor_id() != actor_id:
		return CombatFlowResult.failed(&"invalid_combat_actor", "The active character cannot retreat.")
	var actor := state.party.character_by_id(actor_id)
	if actor == null:
		return CombatFlowResult.failed(&"invalid_combat_actor", "The active character cannot retreat.")
	var probe: Variant = probe_character_retreat(combat, state.party.characters(), actor_id) if mode == &"explicit" else probe_edge_retreat(combat, actor_id, destination) if mode == &"edge" else null
	if probe == null:
		return CombatFlowResult.failed(&"invalid_retreat_mode", "The retreat route is unavailable.")
	if not probe.allowed:
		return CombatFlowResult.failed(probe.reason, probe.reason_text)
	if not combat.mark_character_retreated(actor.id):
		return CombatFlowResult.failed(&"invalid_retreat_state", "The active character's Escape state could not be recorded.")
	combat.battlefield.remove_character(actor.id)
	combat.set_guarding(actor.id, false)
	combat.clear_active_turn()
	actor.attacks_remaining = 0
	actor.movement = 0
	actor.prestige_penalty = _rules.arithmetic.signed_32(actor.prestige_penalty + 200)
	var events: Array[DomainEvent] = [DomainEvent.new(&"combatant_retreated", {"actorId": actor.id, "mode": String(mode), "forced": probe.forced, "prestigePenalty": 200, "nearestEnemyRange": probe.nearest_enemy_range, "source": "classic"})]
	if not _flow()._has_loyal_battlefield_character(state):
		_flow()._complete_battle(state, content, &"retreated", events)
		return CombatFlowResult.succeeded(events, true)
	_flow()._advance_turn(state, rng, events)
	_flow()._process_monster_turns(state, content, rng, events)
	return CombatFlowResult.succeeded(events, state.combat.completed)

func move_character(state: GameState, content: RealmzContent, actor_id: String, destination: Vector2i, rng: RealmzRng, auto_switch_to_melee: bool = false) -> CombatFlowResult:
	var combat := state.combat
	if combat == null or combat.completed or rng == null:
		return CombatFlowResult.failed(&"no_active_battle", "No Realmz battle is accepting tactical movement.")
	if combat.pending_reaction != null or combat.pending_monster_attack != null:
		return CombatFlowResult.failed(&"combat_reaction_pending", "The previous Classic combat reaction must finish before another movement command.")
	if combat.active_actor_id() != actor_id:
		return CombatFlowResult.failed(&"wrong_combat_actor", "Combat movement actor '%s' does not own the current turn." % actor_id)
	var actor := state.party.character_by_id(actor_id)
	if actor == null or actor.current_health <= 0 or actor.traitor or combat.battlefield == null:
		return CombatFlowResult.failed(&"invalid_combat_actor", "The current combat actor or battlefield is unavailable.")
	var terrain_set = _flow()._battle_terrain_set(content, combat.battlefield)
	if terrain_set == null:
		return CombatFlowResult.failed(&"missing_battle_terrain", "The active battlefield has no validated Classic terrain catalog.")
	var origin := combat.battlefield.actor_position(actor_id)
	var direction := destination - origin
	var available_movement := actor.maximum_movement if combat.active_turn == null else actor.movement
	var probe := _rules.battlefield.probe_step(combat.battlefield, terrain_set, actor_id, direction, available_movement)
	var contact_target_id = _flow()._hostile_contact_target_id(state, actor.id, probe.occupant_id) if probe.reason == &"occupied" else ""
	var automatic_actor = _flow().is_processing_auto() or actor.traitor or actor.conditions.is_active(ConditionRules.ANIMATED)
	var should_auto_switch := false
	if not contact_target_id.is_empty() and combat.character_weapon_mode(actor.id) != &"melee":
		if not auto_switch_to_melee or automatic_actor or not _classic_projectile_uses_point_blank_auto_switch(actor, content):
			return CombatFlowResult.failed(&"melee_weapon_mode_required", "Switch to the melee weapon before attacking an occupied hostile footprint.")
		should_auto_switch = true
	if not probe.allowed and contact_target_id.is_empty():
		return CombatFlowResult.failed(probe.reason, _flow()._movement_failure_message(probe))
	if not contact_target_id.is_empty():
		var equipment := _rules.inventory.combat_equipment(actor, content.item_definitions())
		if not equipment.valid:
			return CombatFlowResult.failed(equipment.error_code, equipment.error_message)
	_flow()._prepare_character_turn(combat, actor)
	combat.pending_reaction = CombatReactionState.new(CombatReactionState.CHARACTER_MOVE, actor.id, origin, destination, 3 if not contact_target_id.is_empty() else probe.movement_cost)
	combat.pending_reaction.auto_switch_to_melee = should_auto_switch
	var origin_hostiles = _flow()._hostile_adjacent_ids(state, actor.id)
	combat.pending_reaction.set_origin_hostiles(origin_hostiles)
	combat.pending_reaction.set_phase(CombatReactionState.GUARD_BEFORE, _guarding_actor_ids(state, origin_hostiles))
	var events: Array[DomainEvent] = []
	var reaction_result := _continue_pending_reaction(state, content, rng, events)
	if reaction_result == REACTION_MOVER_DEFEATED:
		if combat.active_actor_id() == actor.id:
			_flow()._advance_turn(state, rng, events)
		if _flow()._finish_if_resolved(state, content, events):
			return CombatFlowResult.succeeded(events, true)
		_flow()._process_monster_turns(state, content, rng, events)
	return CombatFlowResult.succeeded(events, state.combat.completed)

func _init(flow: RefCounted, rules: ContextType) -> void:
	_flow_ref = weakref(flow)
	_rules = rules

func probe_character_retreat(combat: CombatState, characters: Array[CharacterState], actor_id: String):
	if combat == null or combat.completed or combat.battlefield == null or combat.active_actor_id() != actor_id or not combat.battlefield.has_actor(actor_id):
		return CombatRetreatProbeType.blocked(&"invalid_combat_actor", "The active character is unavailable.")
	var actor: CharacterState = null
	for character: CharacterState in characters:
		if character.id == actor_id:
			actor = character
			break
	if actor == null or actor.current_health <= 0 or actor.traitor:
		return CombatRetreatProbeType.blocked(&"invalid_combat_actor", "Only a living loyal character can retreat.")
	var nearest_range := 127
	var origin := combat.battlefield.actor_position(actor_id)
	for character: CharacterState in characters:
		if character.id != actor_id and character.current_health > 0 and character.traitor != actor.traitor and combat.battlefield.has_actor(character.id):
			nearest_range = mini(nearest_range, floori(Vector2(combat.battlefield.actor_position(character.id) - origin).length()))
	for monster: MonsterState in combat.monsters():
		if monster.current_health > 0 and monster.traitor != actor.traitor and combat.battlefield.has_actor(monster.id):
			nearest_range = mini(nearest_range, floori(Vector2(combat.battlefield.actor_position(monster.id) - origin).length()))
	if nearest_range < 10:
		return CombatRetreatProbeType.blocked(&"enemy_too_close", "Classic Escape requires every enemy to be at least 10 battlefield cells away.", nearest_range)
	for condition: int in [ConditionRules.HELPLESS, ConditionRules.CONFUSED, ConditionRules.TANGLED, ConditionRules.SLOW]:
		if actor.conditions.is_active(condition):
			return CombatRetreatProbeType.blocked(&"retreat_condition_blocked", "This character's current condition prevents Escape.", nearest_range)
	return CombatRetreatProbeType.permitted(nearest_range)

func _legal_area_spell_target_coordinates(state: GameState, content: RealmzContent, caster_id: String, spell: SpellDefinition, power_level: int, shape: int) -> Array[Vector2i]:
	var result: Array[Vector2i] = []
	if state == null or state.combat == null or state.combat.battlefield == null or content == null or spell == null:
		return result
	var map := content.world.map_by_id(state.combat.battlefield.map_id)
	var terrain_set := content.world.battle_terrain_set_by_id(map.battle_terrain_set_id) if map != null else null
	if terrain_set == null:
		return result
	var origin := state.combat.battlefield.actor_position(caster_id)
	var maximum_range := absi(spell.range_min + spell.range_max * power_level)
	var minimum := Vector2i(maxi(0, origin.x - maximum_range - 1), maxi(0, origin.y - maximum_range - 1))
	var maximum := Vector2i(mini(BattlefieldState.SIZE - 1, origin.x + maximum_range + 1), mini(BattlefieldState.SIZE - 1, origin.y + maximum_range + 1))
	var require_line_of_sight := spell.range_min + spell.range_max > 0
	for y: int in range(minimum.y, maximum.y + 1):
		for x: int in range(minimum.x, maximum.x + 1):
			var coordinate := Vector2i(x, y)
			if _rules.spell_areas.pattern_fits(coordinate, shape) and _rules.battlefield.coordinate_target_is_valid(state.combat.battlefield, terrain_set, caster_id, coordinate, maximum_range, require_line_of_sight):
				result.append(coordinate)
	return result

static func _has_equipped_scroll_case(character: CharacterState, content: RealmzContent) -> bool:
	if character == null or content == null:
		return false
	for instance: ItemInstance in character.inventory():
		var definition := content.item_by_id(instance.definition_id)
		if instance.equipped and definition != null and absi(definition.item_type) == 13:
			return true
	return false

func _resolve_reaction_attack(state: GameState, content: RealmzContent, attacker_id: String, reaction: CombatReactionState, rng: RealmzRng, events: Array[DomainEvent]) -> int:
	var combat := state.combat
	if not _combatant_is_alive(state, attacker_id) or _combatant_is_helpless(state, attacker_id):
		return REACTION_COMPLETED
	combat.set_guarding(attacker_id, false)
	var action: StringName = &"withdrawal" if reaction.phase == CombatReactionState.WITHDRAWAL else &"guard"
	var behind := reaction.phase == CombatReactionState.WITHDRAWAL
	var character_attacker := state.party.character_by_id(attacker_id)
	if character_attacker != null:
		return _resolve_character_reaction(state, content, character_attacker, reaction.mover_id, action, behind, rng, events)
	var monster_attacker := combat.monster_by_id(attacker_id)
	if monster_attacker == null:
		return REACTION_COMPLETED
	return _resolve_monster_reaction(state, content, monster_attacker, reaction.mover_id, action, behind, rng, events)

func _character_actor_spell_candidates(state: GameState, content: RealmzContent, caster: CharacterState, spell: SpellDefinition, power_level: int) -> Array[CombatSpellTargetView]:
	var result: Array[CombatSpellTargetView] = []
	for character: CharacterState in state.party.characters():
		if character.current_health <= 0 or not state.combat.battlefield.has_actor(character.id):
			continue
		if _spell_actor_target_is_valid(state, content, caster.id, character.id, spell, power_level):
			result.append(CombatSpellTargetView.new(character.id, &"character", character.name, character.current_health, character.maximum_health))
	for monster: MonsterState in state.combat.monsters():
		if monster.current_health <= 0 or not state.combat.battlefield.has_actor(monster.id):
			continue
		if _spell_actor_target_is_valid(state, content, caster.id, monster.id, spell, power_level):
			result.append(CombatSpellTargetView.new(monster.id, &"monster", monster.name, monster.current_health, monster.maximum_health))
	return result

static func _spell_target_view(state: GameState, content: RealmzContent, target_id: String) -> CombatSpellTargetView:
	var character := state.party.character_by_id(target_id)
	if character != null:
		return CombatSpellTargetView.new(character.id, &"character", character.name, character.current_health, character.maximum_health)
	var monster := state.combat.monster_by_id(target_id) if state.combat != null else null
	if monster != null and content.monster_by_id(monster.definition_id) != null:
		return CombatSpellTargetView.new(monster.id, &"monster", monster.name, monster.current_health, monster.maximum_health)
	return null

func _spell_actor_target_is_valid(state: GameState, content: RealmzContent, caster_id: String, target_id: String, spell: SpellDefinition, power_level: int) -> bool:
	var maximum_range := absi(spell.range_min + spell.range_max * power_level)
	if caster_id == target_id:
		var map := content.world.map_by_id(state.combat.battlefield.map_id)
		var terrain_set := content.world.battle_terrain_set_by_id(map.battle_terrain_set_id) if map != null else null
		return terrain_set != null and _rules.battlefield.coordinate_target_is_valid(state.combat.battlefield, terrain_set, caster_id, state.combat.battlefield.actor_position(caster_id), maximum_range, spell.range_min + spell.range_max > 0)
	return _flow().projectile_target_is_valid(state.combat, content, caster_id, target_id, maximum_range, spell.range_min + spell.range_max > 0)

static func _spell_target_selection(state: GameState, content: RealmzContent, target_id: String) -> SpellTargetSelection:
	var character := state.party.character_by_id(target_id)
	if character != null and character.current_health > 0 and state.combat.battlefield.has_actor(character.id):
		return SpellTargetSelection.for_character(character)
	var monster := state.combat.monster_by_id(target_id)
	if monster == null or monster.current_health <= 0 or not state.combat.battlefield.has_actor(monster.id):
		return null
	var definition := content.monster_by_id(monster.definition_id)
	return SpellTargetSelection.for_monster(monster, definition) if definition != null else null

static func _group_target_matches(target_type: int, target_traitor: bool, caster_traitor: bool) -> bool:
	if target_type == 12:
		return true
	if target_type == 9:
		return target_traitor == caster_traitor
	return target_traitor != caster_traitor

func character_spell_unavailable_reason(state: GameState, content: RealmzContent, caster_id: String) -> String:
	if state == null or state.combat == null:
		return ""
	var caster := state.party.character_by_id(caster_id)
	if caster == null or caster.maximum_spell_attacks <= 0 or caster.known_spells().is_empty():
		return ""
	var first_reason := ""
	for spell_id: String in caster.known_spells():
		for power_level: int in range(1, 8):
			var probe := probe_character_spell_choice(state, content, caster_id, spell_id, power_level)
			if probe.allowed:
				return ""
			if first_reason.is_empty() and not probe.reason_text.is_empty():
				first_reason = probe.reason_text
	return first_reason

func _continue_pending_reaction(state: GameState, content: RealmzContent, rng: RealmzRng, events: Array[DomainEvent]) -> int:
	var combat := state.combat
	var operation_guard := 256
	while combat != null and combat.pending_reaction != null and operation_guard > 0:
		var reaction := combat.pending_reaction
		if reaction.mover_killed or not _combatant_is_alive(state, reaction.mover_id):
			reaction.mover_killed = true
			combat.pending_reaction = null
			return REACTION_MOVER_DEFEATED
		if reaction.has_next_attacker():
			var attacker_id := reaction.take_next_attacker()
			var attack_result := _resolve_reaction_attack(state, content, attacker_id, reaction, rng, events)
			if attack_result != REACTION_COMPLETED:
				if attack_result == REACTION_MOVER_DEFEATED:
					combat.pending_reaction = null
				return attack_result
			operation_guard -= 1
			continue
		match reaction.phase:
			CombatReactionState.GUARD_BEFORE:
				if reaction.kind == CombatReactionState.CHARACTER_MOVE:
					var contact_target_id = _flow()._hostile_contact_target_id(state, reaction.mover_id, reaction.destination)
					if not contact_target_id.is_empty():
						if reaction.auto_switch_to_melee and combat.character_weapon_mode(reaction.mover_id) != &"melee":
							if not combat.set_character_weapon_mode(reaction.mover_id, &"melee"):
								combat.pending_reaction = null
								events.append(DomainEvent.new(&"combat_contact_attack_failed", {"actorId": reaction.mover_id, "targetId": contact_target_id, "reason": "invalid_weapon_mode"}))
								return REACTION_COMPLETED
							events.append(DomainEvent.new(&"sound_requested", {"soundId": 141, "waitForCompletion": false, "source": "classic-auto-weapon-switch"}))
							events.append(DomainEvent.new(&"combat_weapon_mode_changed", {"actorId": reaction.mover_id, "mode": "melee", "source": "classic-auto-weapon-switch"}))
						combat.pending_reaction = null
						var contact_result = _flow().submit_action(state, content, reaction.mover_id, &"attack", contact_target_id, rng)
						if not contact_result.ok:
							events.append(DomainEvent.new(&"combat_contact_attack_failed", {"actorId": reaction.mover_id, "targetId": contact_target_id, "reason": String(contact_result.error_code)}))
							return REACTION_COMPLETED
						events.append_array(contact_result.events)
						return REACTION_COMPLETED
					reaction.auto_switch_to_melee = false
					reaction.set_phase(CombatReactionState.WITHDRAWAL, _withdrawal_hostiles(state, reaction))
				else:
					if not _commit_reaction_move(state, content, reaction, events):
						combat.pending_reaction = null
						return REACTION_MOVER_DEFEATED
			CombatReactionState.WITHDRAWAL:
				if not _commit_reaction_move(state, content, reaction, events):
					combat.pending_reaction = null
					return REACTION_MOVER_DEFEATED
			CombatReactionState.GUARD_AFTER:
				combat.pending_reaction = null
				return REACTION_COMPLETED
		operation_guard -= 1
	if operation_guard == 0:
		events.append(DomainEvent.new(&"combat_reaction_failed", {"reason": "reaction-budget-exhausted"}))
		if combat != null:
			combat.pending_reaction = null
	return REACTION_COMPLETED

func _classic_projectile_uses_point_blank_auto_switch(actor: CharacterState, content: RealmzContent) -> bool:
	var equipment := _rules.inventory.combat_equipment(actor, content.item_definitions())
	if not equipment.valid or equipment.missile_weapon == null:
		return false
	var projectile_item := equipment.missile_weapon
	if projectile_item.special_2 <= 1100:
		return false
	var spell := content.spell_by_classic_id(absi(projectile_item.special_2))
	return spell != null and spell.spell_class == 9 and spell.damage_type == 9

param(
    [string[]]$Suite = @(),
    [string[]]$Case = @(),
    [ValidateRange(1, 3600)]
    [int]$TimeoutSeconds = 120,
    [string]$GodotPath = "",
    [string]$CastleRoot = "",
    [string]$RemakeRoot = "",
    [string]$ProvidenceRoot = ""
)

$ErrorActionPreference = "Stop"
$repoRoot = Split-Path -Parent $PSScriptRoot

if ([string]::IsNullOrWhiteSpace($GodotPath)) {
    $candidate = Get-ChildItem "$env:LOCALAPPDATA\Microsoft\WinGet\Packages" -Recurse -Filter "Godot_v4.7.1-stable_win64_console.exe" -ErrorAction SilentlyContinue |
        Select-Object -First 1 -ExpandProperty FullName
    if (-not $candidate) {
        throw "Godot 4.7.1 console executable was not found. Pass -GodotPath explicitly."
    }
    $GodotPath = $candidate
}

$suiteFragments = @($Suite | ForEach-Object { $_.Trim() } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique)
$caseFragments = @($Case | ForEach-Object { $_.Trim() } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique)
if ($suiteFragments.Count -eq 0 -and $caseFragments.Count -eq 0) {
    throw "At least one non-empty -Suite or -Case fragment is required."
}
if ($suiteFragments.Count -eq 0 -and $caseFragments.Count -gt 0) {
    throw "Named case filters require at least one -Suite fragment."
}

& "$PSScriptRoot\run_tests.ps1" -Suite $suiteFragments -Case $caseFragments -TimeoutSeconds $TimeoutSeconds -GodotPath $GodotPath

& "$PSScriptRoot\ui-assets\verify-classic-application-media.ps1"
if ($LASTEXITCODE -ne 0) { throw "Classic application media verification failed." }

$changedPaths = @(
    git -C $repoRoot status --porcelain=v1 --untracked-files=all |
        ForEach-Object {
            if ($_.Length -lt 4) { return }
            $path = $_.Substring(3)
            if ($path.Contains(" -> ")) { $path = $path.Split(" -> ")[-1] }
            $path.Trim('"') -replace '\\', '/'
        } |
        Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
        Select-Object -Unique
)

if (@($changedPaths | Where-Object { $_ -eq "src" -or $_.StartsWith("src/") -or $_ -eq "project.godot" }).Count -gt 0) {
    & "$PSScriptRoot\verify_architecture.ps1"
    if ($LASTEXITCODE -ne 0) { throw "Architecture boundary verification failed." }
} else {
    Write-Host "Architecture boundary verification skipped: no product source changed."
}

& "$PSScriptRoot\verify_hotspot_test_budget.ps1"
if ($LASTEXITCODE -ne 0) { throw "Hotspot and test-budget verification failed." }

$referenceArguments = @{}
if (-not [string]::IsNullOrWhiteSpace($CastleRoot)) { $referenceArguments.CastleRoot = $CastleRoot }
if (-not [string]::IsNullOrWhiteSpace($RemakeRoot)) { $referenceArguments.RemakeRoot = $RemakeRoot }
if (-not [string]::IsNullOrWhiteSpace($ProvidenceRoot)) { $referenceArguments.ProvidenceRoot = $ProvidenceRoot }

& "$PSScriptRoot\verify_differential_evidence.ps1" @referenceArguments
if ($LASTEXITCODE -ne 0) { throw "Differential evidence verification failed." }

& "$PSScriptRoot\verify_application_workflow_inventory.ps1" -Check @referenceArguments
if ($LASTEXITCODE -ne 0) { throw "Application workflow inventory verification failed." }

& "$PSScriptRoot\verify_gameplay_parity_inventory.ps1" -GodotPath $GodotPath
if ($LASTEXITCODE -ne 0) { throw "Gameplay parity inventory verification failed." }

& "$PSScriptRoot\analyze_gameplay_feature_reports.ps1" -SelfTest

git -C $repoRoot diff --check
if ($LASTEXITCODE -ne 0) { throw "git diff --check failed." }

$addedTrackedLines = @(git -C $repoRoot diff --no-ext-diff --unified=0 HEAD -- . | Where-Object { $_ -match '^\+(?!\+\+)' } | ForEach-Object { $_.Substring(1) })
$localPathPattern = '(?i)([a-z]:[\\/](users|documents|realmz|godot)|/(users|home)/[^/\s]+/)'
foreach ($line in $addedTrackedLines) {
    if ($line -match $localPathPattern) {
        throw "Changed text contains a machine-local absolute path: $line"
    }
}

foreach ($path in $changedPaths) {
    $extension = [System.IO.Path]::GetExtension($path).ToLowerInvariant()
    if ($extension -eq ".r2save") {
        throw "Save artifact must not enter a workflow commit: $path"
    }
    $isAllowedRealmz2 = $path.StartsWith("tests/fixtures/packages/") -or
        $path -eq "src/infrastructure/characters/realmz-classic-character-library.realmz2"
    if ($extension -eq ".realmz2" -and -not $isAllowedRealmz2) {
        throw "Campaign package outside the synthetic fixture boundary must not enter a workflow commit: $path"
    }
    $fullPath = Join-Path $repoRoot $path
    $trackedMatches = @(git -C $repoRoot ls-files -- $path)
    if ($trackedMatches.Count -gt 0 -or -not (Test-Path -LiteralPath $fullPath -PathType Leaf)) {
        continue
    }
    try {
        $untrackedText = Get-Content -LiteralPath $fullPath -Raw -ErrorAction Stop
    } catch {
        continue
    }
    if ($untrackedText -match $localPathPattern) {
        throw "Untracked text contains a machine-local absolute path: $path"
    }
}

Write-Host "Workflow verification complete: $($suiteFragments.Count) suite filter(s), $($caseFragments.Count) case filter(s), $($changedPaths.Count) changed path(s)."
exit 0

static func _populate_spell_actions(context: SessionWorkflowContext, result: GameView) -> void:
	var state := context.state
	var content := context.content
	var rules := context.rules
	var blocked_reason := "Resolve the current interaction first." if result.pending_interaction != null else "Complete party setup first." if result.party_setup_available else ""
	var battle_active := result.combat_view != null and result.combat_view.outcome == &"active"
	for member_view: CharacterView in result.party_members:
		var character := state.party.character_by_id(member_view.id)
		for spell_view: SpellView in member_view.spells:
			var spell := content.spell_by_id(spell_view.id)
			if not blocked_reason.is_empty():
				spell_view.field_cast = ActionAvailabilityView.new(&"cast_spell", false, blocked_reason)
				spell_view.make_scroll = ActionAvailabilityView.new(&"cast_spell", false, blocked_reason)
				continue
			if battle_active:
				spell_view.field_cast = ActionAvailabilityView.new(&"cast_spell", false, "Use the tactical spell action during battle.")
				spell_view.make_scroll = ActionAvailabilityView.new(&"cast_spell", false, "Scroll scribing is unavailable during battle.")
				continue
			var first_reason := ""
			for power: int in range(1, 8):
				var probe := _field_spell_probe(context, character, spell, power)
				if probe.allowed:
					spell_view.power_levels.append(power)
				elif first_reason.is_empty():
					first_reason = probe.reason
				if spell != null and spell.cost < 0:
					break
			spell_view.field_cast = ActionAvailabilityView.new(&"cast_spell", not spell_view.power_levels.is_empty(), first_reason)
			var make_reason := ""
			for power: int in range(1, 8):
				var make_probe := _make_scroll_probe(context, character, spell, power)
				if make_probe.allowed:
					spell_view.scroll_power_levels.append(power)
				elif make_reason.is_empty():
					make_reason = make_probe.reason
				if spell != null and spell.cost < 0:
					break
			spell_view.make_scroll = ActionAvailabilityView.new(&"cast_spell", not spell_view.scroll_power_levels.is_empty(), make_reason)
		for scroll_view: SpellScrollView in member_view.scrolls:
			if not blocked_reason.is_empty():
				scroll_view.use = ActionAvailabilityView.new(&"cast_spell", false, blocked_reason)
				continue
			if battle_active:
				var combat_scroll := character.scroll_at(scroll_view.slot_index)
				var combat_scroll_spell := content.spell_by_id(combat_scroll.spell_id) if combat_scroll != null and not combat_scroll.is_empty() else null
				var combat_target_id := character.id if combat_scroll_spell != null and combat_scroll_spell.target_type == 5 else ""
				var combat_probe := rules.combat_flow.probe_character_scroll_cast(state, content, character.id, scroll_view.slot_index, combat_target_id)
				scroll_view.use = ActionAvailabilityView.new(&"cast_spell", combat_probe.allowed, combat_probe.reason_text)
				continue
			var scroll := character.scroll_at(scroll_view.slot_index)
			var scroll_spell := content.spell_by_id(scroll.spell_id) if scroll != null and not scroll.is_empty() else null
			var scroll_probe := _scroll_use_probe(context, character, scroll_view.slot_index, scroll_spell)
			scroll_view.use = ActionAvailabilityView.new(&"cast_spell", scroll_probe.allowed, scroll_probe.reason)
		for fast_spell: FastSpellBindingView in member_view.fast_spells:
			if fast_spell.spell_id.is_empty():
				continue
			var bound_spell := content.spell_by_id(fast_spell.spell_id)
			if bound_spell == null or not character.known_spells().has(fast_spell.spell_id):
				fast_spell.activation = ActionAvailabilityView.new(&"cast_spell", false, "The stored spell is unavailable to this character.")
				continue
			if battle_active:
				var option_available := false
				for option: CombatSpellOptionView in rules.combat_flow.character_spell_options(state, content, character.id):
					if option.spell_id == bound_spell.id and option.power == fast_spell.power:
						option_available = true
						break
				fast_spell.activation = ActionAvailabilityView.new(&"cast_spell", option_available, "No legal target or casting action is currently available." if not option_available else "")
			else:
				var field_probe := _field_spell_probe(context, character, bound_spell, fast_spell.power)
				fast_spell.activation = ActionAvailabilityView.new(&"cast_spell", field_probe.allowed, field_probe.reason)

func snapshot() -> SessionSnapshot:
	if not _started or (_scenario_vm.is_active() and _scenario_vm.pending_request() == null):
		return null
	var state := GameState.from_data(_state.to_data())
	var vm_state := ScenarioVmSnapshot.from_data(_scenario_vm.snapshot().to_data())
	var action_state := ScenarioActionState.from_data(_scenario_action_state.to_data())
	var interaction: InteractionRequest = null
	if _session_interaction != null:
		interaction = InteractionRequest.from_data(_session_interaction.to_data())
	if state == null or vm_state == null or action_state == null or _session_interaction != null and interaction == null:
		return null
	var continuation := null if _session_continuation.is_empty() else SessionContinuation.from_data(_session_continuation.to_data())
	var battle_return := null if _battle_return_continuation.is_empty() else SessionContinuation.from_data(_battle_return_continuation.to_data())
	return SessionSnapshot.new(_content.campaign_id, _content.package_hash, _content.rules_version, _view_revision, state, _rng.snapshot(), vm_state, action_state, continuation, battle_return, interaction)

func _commit_coordinator_result(result: SessionCoordinatorResult) -> SessionStep:
	_apply_coordinator_context()
	if result == null:
		return _finish_failed(&"invalid_coordinator_result", "The session coordinator returned no typed result.", [])
	match result.state:
		SessionCoordinatorResult.State.COMPLETED:
			return _finish_completed(result.events)
		SessionCoordinatorResult.State.WAITING:
			return _finish_waiting(result.interaction, result.events)
		SessionCoordinatorResult.State.FAILED:
			return _finish_failed(result.error_code, result.error_message, result.events)
		SessionCoordinatorResult.State.CLOSE:
			return _commit_close(result.events, result.close_reason)
	return _finish_failed(&"invalid_coordinator_result", "The session coordinator returned an unknown state.", [])

func start(content: RealmzContent, initial_seed: int) -> SessionStep:
	if _started:
		return SessionStep.failed(_view_revision, &"session_already_started", "The session has already started.")
	if content == null or content.scenario == null:
		return SessionStep.failed(_view_revision, &"invalid_content", "Validated Realmz content is required.")
	var start_map := content.world.map_by_id(content.start_map_id)
	if start_map == null or start_map.topology.cell_at(content.start_coordinate) == null:
		return SessionStep.failed(_view_revision, &"invalid_start_location", "The package start location is unavailable.")
	var starting_characters: Array[CharacterState] = []
	var game_state := GameState.new(PartyState.new(content.start_map_id, content.start_coordinate, starting_characters), RealmzClock.new())
	game_state.world.mark_visited(content.start_map_id, content.start_coordinate)
	var random_source := RealmzRng.new(initial_seed)
	var action_state := ScenarioActionState.new()
	var scenario_vm := ScenarioVm.new()
	scenario_vm.configure(content.scenario)
	_content = content
	_state = game_state
	_rng = random_source
	_rules = RealmzRules.new()
	_scenario_action_state = action_state
	_scenario_vm = scenario_vm
	_runtime_api = RealmzRuntimeApi.new(_content, _state, _rng, _scenario_action_state, _rules)
	_session_continuation.clear()
	_battle_return_continuation.clear()
	_session_interaction = null
	_view_projector.clear()
	_started = true
	_view_revision = 1
	return SessionStep.completed(_view_revision, [DomainEvent.new("session_started", {"campaignId": content.campaign_id})])

func _finalize_character(_intent: PlayerIntent) -> SessionStep:
	var result := LifecyclePartyWorkflow.prepare_character_finalize(_workflow_context(), _pending_interaction() != null)
	if not result.ok:
		return _finish_failed(result.error_code, result.error_message, result.events)
	if result.remaining_spell_points > 0:
		var request_id := "character-spells:%s:%d" % [result.character_id, _view_revision + 1]
		_set_continuation(SessionContinuation.character_spell_confirmation(result.character_id, result.remaining_spell_points))
		_session_interaction = SessionInteractionFactory.character_spell_confirmation(request_id, result.remaining_spell_points)
		return _finish_waiting(_session_interaction, [DomainEvent.new(&"character_spell_confirmation_requested", {"characterId": result.character_id, "remaining": result.remaining_spell_points})])
	return _commit_character_draft()

func _begin_adventure() -> SessionStep:
