	if kind == &"post-clock":
		return {"kind": String(kind), "mapId": map_id, "x": coordinate.x, "y": coordinate.y, "timedDay": timed_day, "timedEncounterIndex": timed_encounter_index, "activeTimedProgramId": active_timed_program_id, "midnightRecoveryPending": midnight_recovery_pending, "timedCheckX": timed_check_coordinate.x, "timedCheckY": timed_check_coordinate.y, "checkRandom": check_random, "randomRegionIds": random_region_ids.duplicate(), "randomRegionIndex": random_region_index, "activeRandomProgramId": active_random_program_id, "activeRandomRegionId": active_random_region_id, "randomBattleStage": String(random_battle_stage), "resumeKind": String(resume_kind), "directionX": direction.x, "directionY": direction.y}
	return {"kind": String(kind), "mapId": map_id, "x": coordinate.x, "y": coordinate.y, "triggerIds": trigger_ids.duplicate(), "triggerIndex": trigger_index, "activeTriggerId": active_trigger_id, "randomRegionIds": random_region_ids.duplicate(), "randomRegionIndex": random_region_index, "activeRandomProgramId": active_random_program_id, "activeRandomRegionId": active_random_region_id, "randomBattleStage": String(random_battle_stage), "actionPointDestinationDepth": action_point_destination_depth}

func _payload_data(kind: StringName) -> Dictionary:
	if kind == &"pooled-wealth-departure":
		return {"kind": String(kind), "stage": String(stage), "directionX": direction.x, "directionY": direction.y}
	return {"kind": String(kind), "serviceId": service_id, "runtimeContinuation": {} if runtime_continuation == null else runtime_continuation.to_data()}

func _payload_data(kind: StringName) -> Dictionary:
	if kind == &"character-spell-confirmation":
		return {"kind": String(kind), "characterId": character_id, "remaining": remaining}
	if kind == &"character-vault-publication":
		return {"kind": String(kind), "characterId": character_id}
	var data := {"kind": String(kind), "hook": String(hook), "programId": program_id, "resumeKind": String(resume_kind), "serviceId": service_id, "partyRevived": party_revived}
	if resume_kind == &"scenario-party-defeat":
		data["suspendedVm"] = {} if suspended_vm == null else suspended_vm.to_data()
		data["suspendedOwner"] = {} if suspended_owner == null else suspended_owner.to_data()
		data["vmHandoff"] = {} if vm_handoff == null else vm_handoff.to_data()
	return data

func _payload_data(kind: StringName) -> Dictionary:
	if kind == &"drop-item-confirmation":
		return {"kind": String(kind), "characterId": character_id, "instanceId": instance_id}
	var data := {"kind": String(kind), "characterId": character_id, "spellId": spell_id, "power": power, "targetCount": target_count}
	if kind == &"item-use-target-selection":
		data["instanceId"] = instance_id
		data["startingCharges"] = starting_charges
	elif kind == &"field-spell-target-selection":
		data["startingSpellPoints"] = starting_spell_points
	else:
		data["scrollSlot"] = scroll_slot
	return data

func _payload_data(kind: StringName) -> Dictionary:
	var serialized_updates: Array[Dictionary] = []
	for update: InteractionRequest.AgeUpdateBody in updates:
		serialized_updates.append(update.to_data())
	return {"kind": String(kind), "updates": serialized_updates, "index": index, "resumeKind": String(resume_kind), "resumeContinuation": {} if resume_continuation == null else resume_continuation.to_data()}

func _payload_data(kind: StringName) -> Dictionary:
	if kind == &"combat-retreat-confirmation":
		return {"kind": String(kind), "battleId": battle_id, "actorId": actor_id, "mode": String(mode), "destination": [destination.x, destination.y]}
	if kind == &"combat-death-macro":
		return {"kind": String(kind), "battleId": battle_id, "combatantId": combatant_id, "programId": program_id, "resetTraitorOnComplete": reset_traitor_on_complete}
	return {"kind": String(kind), "battleId": battle_id}

func _respond_session_ally_selection(response: InteractionResponse) -> SessionStep:
	_ensure_coordinators()
	return _commit_coordinator_result(_response_coordinator._respond_session_ally_selection(response))

func _finish_with_age_updates(events: Array[DomainEvent], resume_kind: StringName, resume_continuation: SessionContinuation = null) -> SessionStep:
	_ensure_coordinators()
	return _commit_coordinator_result(_response_coordinator._finish_with_age_updates(events, resume_kind, resume_continuation))

static func _event_payload(events: Array[DomainEvent], kind: StringName) -> Dictionary:
	for index: int in range(events.size() - 1, -1, -1):
		if events[index].kind == kind:
			return events[index].payload
	return {}

static func _events_keep_trigger(events: Array[DomainEvent], trigger_id: String) -> bool:
	for event: DomainEvent in events:
		if event.kind == &"action_point_kept" and String(event.payload.get("triggerId", "")) == trigger_id:
			return true
	return false

func _respond_session_fumble_recovery(response: InteractionResponse) -> SessionCoordinatorResult:
	var body = response.body as InteractionResponse.TreasureBody
	if response.kind != InteractionRequest.TREASURE_DISTRIBUTION or body == null:
		return _context.failed(&"invalid_interaction_response", "Fumbled-weapon recovery requires a treasure-distribution response.")
	var continuation = _context.session_continuation.combat()
	if continuation == null or _context.state.combat == null or not _context.state.combat.completed or _context.state.combat.battle_id != continuation.battle_id:
		return _context.failed(&"invalid_session_continuation", "The completed battle is unavailable for fumbled-weapon recovery.")
	var result = _context.rules.combat_flow.apply_fumble_recovery(_context.state, _context.content, body.action, body.instance_id, body.character_id)
	if not result.ok:
		return _context.failed(result.error_code, result.error_message)
	_context.session_interaction = null
	_context.session_continuation.clear()
	var events: Array[DomainEvent] = []
	events.assign(result.events)
	return _context.scenario()._finish_direct_battle_recovery(events)

func _respond_session_battle_reward(response: InteractionResponse) -> SessionCoordinatorResult:
	var continuation = _context.session_continuation.reward()
	if continuation == null or _context.state.combat == null or not _context.state.combat.completed or _context.state.combat.battle_id != continuation.battle_id:
		return _context.failed(&"invalid_session_continuation", "The completed battle is unavailable for reward distribution.")
	if continuation.runtime_continuation == null:
		return _context.failed(&"invalid_session_continuation", "The battle reward continuation is unavailable.")
	var return_continuation = _context.battle_return_continuation.copy()
	var battle_outcome = _context.state.combat.outcome
	var result = _context.runtime_api.resume_classic(continuation.runtime_continuation, response, response.request_id)
	if result.state == ScenarioRuntimeOperationResult.State.FAILED:
		return _context.failed(result.error_code, result.error_message, result.events)
	if result.state == ScenarioRuntimeOperationResult.State.WAITING:
		continuation.runtime_continuation = result.continuation.copy()
		_context.session_interaction = result.interaction
		return _context.waiting(_context.session_interaction, result.events)
	_context.session_interaction = null
	_context.session_continuation.clear()
	return _context.scenario()._finish_after_direct_battle(result.events, return_continuation, battle_outcome)

func _finish_magic_transition(result: InventoryMagicServicesWorkflow.MagicTransitionResult) -> SessionCoordinatorResult:
	if result == null:
		return _context.failed(&"invalid_workflow_result", "The magic workflow returned no result.")
	if not result.ok:
		return _context.failed(result.error_code, result.error_message)
	if result.completed:
		if result.process_age_updates:
			return _finish_magic_workflow(SessionWorkflowResult.completed(result.events))
		return _context.completed(result.events)
	if result.continuation == null or result.continuation.is_empty() or result.interaction == null:
		return _context.failed(&"invalid_workflow_result", "The magic workflow returned an incomplete interaction transition.")
	_context.set_continuation(result.continuation)
	_context.session_interaction = result.interaction
	return _context.waiting(_context.session_interaction, result.events)

func _finish_magic_workflow(result: SessionWorkflowResult) -> SessionCoordinatorResult:
	if result == null:
		return _context.failed(&"invalid_workflow_result", "The magic workflow returned no result.")
	if not result.ok:
		return _context.failed(result.error_code, result.error_message)
	if not CharacterAgingResult.update_payloads(result.events).is_empty():
		return _finish_with_age_updates(result.events, &"completed")
	return _context.completed(result.events)

func _commit_character_draft(events: Array[DomainEvent] = []) -> SessionCoordinatorResult:
	var result := LifecyclePartyWorkflow.commit_character_draft(_context.workflow_context())
	if not result.ok:
