static func from_data(data: Variant) -> ScenarioFrame:
	if not data is Dictionary:
		return null
	for field: String in ["kind", "definitionId", "cursor", "returnTarget", "countsAsClassicCall", "parameters", "locals", "context", "iterators"]:
		if not data.has(field):
			return null
	var saved_cursor := _integer(data["cursor"])
	if data["kind"] not in ["program", "action"] or not data["definitionId"] is String or data["definitionId"].is_empty() or saved_cursor < 0 or not data["returnTarget"] is String or not data["countsAsClassicCall"] is bool:
		return null
	if not data["parameters"] is Dictionary or not data["locals"] is Dictionary or not data["context"] is Dictionary or not data["iterators"] is Array:
		return null
	var context := ScenarioExecutionContext.from_data(data["context"])
	if context == null:
		return null
	var frame := ScenarioFrame.new(StringName(data["kind"]), data["definitionId"], saved_cursor)
	frame.return_target = data["returnTarget"]
	frame.counts_as_classic_call = data["countsAsClassicCall"]
	frame._parameters = data["parameters"].duplicate(true)
	frame._locals = data["locals"].duplicate(true)
	frame._context = context
	for iterator: Variant in data["iterators"]:
		if not iterator is Dictionary:
			return null
		frame._iterators.append(iterator.duplicate(true))
	return frame

static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1

func to_data() -> Dictionary:
	var result: Dictionary = {}
	var keys: Array = _values.keys()
	keys.sort()
	for key: Variant in keys:
		result[key] = _encode(_values[key])
	return result

static func from_data(data: Variant) -> ScenarioActionState:
	if not data is Dictionary or data.size() > MAX_ENTRIES:
		return null
	var state := ScenarioActionState.new()
	for key: Variant in data.keys():
		if not key is String or key.is_empty():
			return null
		var decoded := _decode(data[key], 0)
		if not decoded["ok"]:
			return null
		state._values[key] = decoded["value"]
	return state

static func _json_safe(value: Variant, depth: int) -> bool:
	if depth > 32:
		return false
	if value == null or value is bool or value is int or value is String:
		return true
	if value is float:
		return not is_nan(value) and not is_inf(value)
	if value is Array:
		if value.size() > 256:
			return false
		for child: Variant in value:
			if not _json_safe(child, depth + 1):
				return false
		return true
	if value is Dictionary:
		if value.size() > 256:
			return false
		for key: Variant in value.keys():
			if not key is String or not _json_safe(value[key], depth + 1):
				return false
		return true
	return false

static func _encode(value: Variant) -> Dictionary:
	if value == null:
		return {"type": "null"}
	if value is bool:
		return {"type": "bool", "value": value}
	if value is int:
		return {"type": "int", "value": value}
	if value is float:
		return {"type": "float", "value": value}
	if value is String:
		return {"type": "string", "value": value}
	if value is Array:
		var entries: Array[Dictionary] = []
		for child: Variant in value:
			entries.append(_encode(child))
		return {"type": "array", "value": entries}
	var fields: Dictionary = {}
	var keys: Array = value.keys()
	keys.sort()
	for key: Variant in keys:
		fields[key] = _encode(value[key])
	return {"type": "record", "value": fields}

func resume_safe(continuation: ScenarioRuntimeContinuation, response: InteractionResponse, request_id: String = "") -> ScenarioRuntimeOperationResult:
	if continuation == null or response == null or not response.is_supported_kind():
		return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "The response payload does not match its interaction kind.")
	match continuation.kind:
		ScenarioRuntimeContinuation.SAFE_AGE_UPDATES:
			return _resume_age_update_interactions(continuation, response, request_id if not request_id.is_empty() else String(response.request_id))
		ScenarioRuntimeContinuation.SAFE_CHOICE:
			var choice_continuation := continuation.body as ScenarioRuntimeContinuation.ChoiceBody
			var option_count: int = choice_continuation.option_count
			var choice := response.body as InteractionResponse.ChoiceBody
			if response.kind != &"scenario_choice" or choice == null or choice.index < 0 or choice.index >= option_count:
				return ScenarioRuntimeOperationResult.failed(&"invalid_interaction_response", "Scenario choice response must identify an available option.")
			return ScenarioRuntimeOperationResult.completed(choice.index)
		ScenarioRuntimeContinuation.SAFE_COMBAT, ScenarioRuntimeContinuation.SAFE_COMBAT_RETREAT, ScenarioRuntimeContinuation.SAFE_COMBAT_AGE, ScenarioRuntimeContinuation.SAFE_COMBAT_MACRO, ScenarioRuntimeContinuation.SAFE_COMBAT_DEATH_MACRO, ScenarioRuntimeContinuation.SAFE_COMBAT_ALLY, ScenarioRuntimeContinuation.SAFE_COMBAT_FUMBLE, ScenarioRuntimeContinuation.CLASSIC_REWARD:
			return _battle_reward_operations.resume(continuation, response, request_id if not request_id.is_empty() else String(response.request_id))
		_:
			return ScenarioRuntimeOperationResult.failed(&"unknown_interaction_continuation", "Scenario Action interaction continuation is unavailable.")

func copy() -> ScenarioBattleCaller:
	var duplicate := from_data(to_data())
	assert(duplicate != null, "A live typed battle caller must round-trip through its wire codec")
	return duplicate

func to_data() -> Dictionary:
	match kind:
		SAFE:
			if policy != SAFE_POLICY:
				return {}
			return {"kind": String(kind), "version": VERSION, "data": {"policy": String(policy)}}
		CLASSIC:
			if opcode not in [2, 48, 56, 107]:
				return {}
			return {
				"kind": String(kind),
				"version": VERSION,
				"data": {
					"opcode": opcode,
					"gosub": gosub,
					"mode": mode,
					"branchTarget": branch_target,
				},
			}
	return {}

static func from_data(value: Variant) -> ScenarioBattleCaller:
	if not value is Dictionary or value.size() != 3 or not value.get("kind") is String or _integer(value.get("version")) != VERSION or not value.get("data") is Dictionary:
		return null
	var data: Dictionary = value["data"]
	match StringName(value["kind"]):
		SAFE:
			if data.size() != 1 or not data.get("policy") is String or data["policy"] != String(SAFE_POLICY):
				return null
			return safe_continue()
		CLASSIC:
			if data.size() != 4 or not data.get("gosub") is bool:
				return null
			var parsed_opcode: Variant = _integer(data.get("opcode"))
			var parsed_mode: Variant = _integer(data.get("mode"))
			var parsed_branch_target: Variant = _integer(data.get("branchTarget"))
			if parsed_opcode == null or parsed_mode == null or parsed_branch_target == null or int(parsed_opcode) not in [2, 48, 56, 107]:
				return null
			return classic(int(parsed_opcode), data["gosub"], int(parsed_mode), int(parsed_branch_target))
	return null

static func _integer(value: Variant) -> Variant:
	if value is int:
