func assert_not_null(value: Variant, message: String) -> void:
	assertions += 1
	if value == null:
		failures.append(message)

func _initialize() -> void:
	_write = "--write" in OS.get_cmdline_user_args()
	var repository := PackageRepository.new()
	var loaded := repository.load_bundled_package(APPLICATION_PACKAGE_PATH, APPLICATION_PACKAGE_ID, APPLICATION_PACKAGE_HASH)
	if not loaded.is_ok():
		_fail("Application package load failed: %s" % loaded.error_message)
		repository.close()
		return
	var inventory := _build_inventory(loaded.content)
	var inventory_errors := _inventory_errors(inventory)
	if not inventory_errors.is_empty():
		_fail("Parity inventory invariant failed: %s" % "; ".join(inventory_errors))
		repository.close()
		return
	var inventory_text := CanonicalJson.encode(inventory) + "\n"
	var report_text := _build_report(inventory)
	var ok := _write_or_check(INVENTORY_PATH, inventory_text)
	ok = _write_or_check(REPORT_PATH, report_text) and ok
	repository.close()
	if ok:
		print("Gameplay parity inventory %s." % ["written" if _write else "verified"])
		quit(0)

func _build_inventory(content: RealmzContent) -> Dictionary:
	var opcodes: Array[Dictionary] = []
	var opcode_counts := {"executable": 0, "classic-reserved": 0, "unsupported-pending": 0}
	for opcode: int in ClassicOpcodeCatalog.classic_opcode_identities():
		var disposition := String(ClassicOpcodeCatalog.disposition(opcode))
		opcode_counts[disposition] = int(opcode_counts.get(disposition, 0)) + 1
		opcodes.append({
			"disposition": disposition,
			"evidence": _opcode_evidence(disposition, ClassicOpcodeCatalog.evidence_reference(opcode)),
			"evidenceReference": ClassicOpcodeCatalog.evidence_reference(opcode),
			"normalizedOpcode": ClassicOpcodeCatalog.normalize(opcode),
			"opcode": opcode,
			"owner": String(ClassicOpcodeCatalog.owner(opcode)),
		})

	var spells: Array[Dictionary] = []
	var signature_groups: Dictionary = {}
	var role_counts := {
		String(SpellCapabilities.ROLE_APPLICATION_EFFECT): 0,
		String(SpellCapabilities.ROLE_RESERVED_STANDARD): 0,
		String(SpellCapabilities.ROLE_STOCK_PLAYER): 0,
		String(SpellCapabilities.ROLE_UNKNOWN): 0,
	}
	for spell: SpellDefinition in content.spell_definitions():
		var role := String(SpellCapabilities.application_role(spell))
		var behavior_signature: Dictionary = SpellCapabilities.behavior_signature(spell)
		var signature_id := CanonicalJson.encode(behavior_signature).sha256_text().substr(0, 16)
		role_counts[role] = int(role_counts.get(role, 0)) + 1
		var group: Array = signature_groups.get(signature_id, [])
		group.append(spell.classic_id)
		signature_groups[signature_id] = group
		spells.append({
			"behaviorSignature": behavior_signature,
			"classicId": spell.classic_id,
			"evidence": _spell_evidence(role),
			"id": spell.id,
			"name": spell.name,
			"packedFamily": SpellCapabilities.packed_family(spell),
			"packedLevel": SpellCapabilities.packed_level(spell),
			"packedSlot": SpellCapabilities.packed_slot(spell),
			"presentationSignature": {
				"lookEnd": spell.look_end,
				"lookStart": spell.look_start,
				"queueIcon": spell.queue_icon,
				"soundEnd": spell.sound_end,
				"soundStart": spell.sound_start,
			},
			"role": role,
			"signatureId": signature_id,
		})
	var signatures: Array[Dictionary] = []
	var signature_ids: Array = signature_groups.keys()
	signature_ids.sort()
	for signature_id: String in signature_ids:
		var classic_ids: Array = signature_groups[signature_id]
		classic_ids.sort()
		signatures.append({"classicIds": classic_ids, "count": classic_ids.size(), "signatureId": signature_id})

	var opcode_summary := ClassicOpcodeCatalog.parity_summary()
	return {
		"applicationPackage": {"campaignId": APPLICATION_PACKAGE_ID, "packageHash": APPLICATION_PACKAGE_HASH},
		"corpusSpells": [],
		"evidenceAxes": ["discovered", "compilerPreserved", "runtimeTested", "routeProven", "ordinaryPlayCertified"],
		"featureReportContract": {
			"analyzer": "tools/analyze_gameplay_feature_reports.ps1",
			"formatVersion": FEATURE_REPORT_FORMAT_VERSION,
			"providenceCommit": FEATURE_REPORT_PROVIDENCE_COMMIT,
			"schemaHash": FEATURE_REPORT_SCHEMA_HASH,
		},
		"formatVersion": 2,
		"opcodeSummary": {
			"classicReserved": opcode_counts["classic-reserved"],
			"executable": opcode_counts["executable"],
			"missingEvidence": opcode_summary["missingEvidence"],
			"pending": opcode_counts["unsupported-pending"],
			"total": opcodes.size(),
			"unowned": opcode_summary["unowned"],
			"unknown": opcode_summary["unknown"],
		},
		"opcodes": opcodes,
		"policy": {
			"commercialCorpus": "local-untracked-sidecars-only",
			"runtimeTestedMeaning": "semantic public-boundary behavior proof, not package decoding or handler presence",
			"signatureMeaning": "mechanical fields only; presentation art and sound remain separately inventoried",
		},
		"spellSummary": {
			"applicationEffects": role_counts[String(SpellCapabilities.ROLE_APPLICATION_EFFECT)],
			"behaviorSignatures": signatures.size(),
			"reservedStandardSlots": role_counts[String(SpellCapabilities.ROLE_RESERVED_STANDARD)],
			"stockPlayer": role_counts[String(SpellCapabilities.ROLE_STOCK_PLAYER)],
			"totalDefinitions": spells.size(),
			"unknown": role_counts[String(SpellCapabilities.ROLE_UNKNOWN)],
		},
		"spells": spells,
		"spellSignatures": signatures,
	}

func _inventory_errors(inventory: Dictionary) -> Array[String]:
	var errors: Array[String] = []
	var opcode_summary: Dictionary = inventory["opcodeSummary"]
	var spell_summary: Dictionary = inventory["spellSummary"]
	if opcode_summary != ClassicOpcodeCatalog.parity_summary():
		errors.append("opcode summary does not match the complete catalog audit")
	if spell_summary["totalDefinitions"] != 420 or spell_summary["stockPlayer"] != 252 or spell_summary["applicationEffects"] != 105 or spell_summary["reservedStandardSlots"] != 63:
		errors.append("application spell roles do not match the pinned package denominator")
	if spell_summary["unknown"] != 0:
		errors.append("application spell catalog contains unowned definitions")
	if spell_summary["behaviorSignatures"] <= 0 or spell_summary["behaviorSignatures"] > spell_summary["totalDefinitions"]:
		errors.append("application spell behavior signatures are malformed")
	var feature_report_contract: Dictionary = inventory["featureReportContract"]
	if feature_report_contract["formatVersion"] != FEATURE_REPORT_FORMAT_VERSION or feature_report_contract["providenceCommit"] != FEATURE_REPORT_PROVIDENCE_COMMIT or feature_report_contract["schemaHash"] != FEATURE_REPORT_SCHEMA_HASH:
		errors.append("Providence feature-report contract metadata is stale")
	return errors

func _opcode_evidence(disposition: String, reference: String) -> Dictionary:
	var runtime_status := "missing" if disposition == "unsupported-pending" else "not-applicable" if disposition == "classic-reserved" else "partial"
	return {
		"compilerPreserved": {"evidence": "", "status": "not-assessed"},
		"discovered": {"evidence": reference, "status": "verified"},
		"ordinaryPlayCertified": {"evidence": "", "status": "not-assessed"},
		"routeProven": {"evidence": "", "status": "not-assessed"},
		"runtimeTested": {"evidence": reference if disposition == "executable" else "", "status": runtime_status},
	}

func _reward_response(request: InteractionRequest) -> InteractionResponse:
	if request.kind == InteractionRequest.LEVEL_UP:
		if request.body.to_data().get("mode") == "result":
			return InteractionResponse.from_data(request.request_id, request.kind, {"action": "continue", "characterId": request.body.to_data()["characterId"]})
		return InteractionResponse.from_data(request.request_id, request.kind, {"action": "confirm-spells", "characterId": request.body.to_data()["characterId"], "spellIds": []})
	if request.body.to_data().get("mode") == "completion-confirmation":
		return InteractionResponse.from_data(request.request_id, request.kind, {"action": "confirm-completion"})
	var items: Variant = request.body.to_data().get("items", [])
	if items is Array and not items.is_empty():
		return InteractionResponse.from_data(request.request_id, request.kind, {"action": "discard", "instanceId": items[0]["instanceId"]})
	return InteractionResponse.from_data(request.request_id, request.kind, {"action": "done"})

func _spell_evidence(role: String) -> Dictionary:
	var reserved := role == String(SpellCapabilities.ROLE_RESERVED_STANDARD)
	return {
		"compilerPreserved": {"evidence": "pinned-application-package", "status": "verified"},
		"discovered": {"evidence": "pinned-application-package", "status": "verified"},
		"ordinaryPlayCertified": {"evidence": "", "status": "not-applicable" if reserved else "not-assessed"},
		"routeProven": {"evidence": "", "status": "not-applicable" if reserved else "not-assessed"},
		"runtimeTested": {"evidence": "", "status": "not-applicable" if reserved else "not-assessed"},
	}

func _write_or_check(path: String, expected: String) -> bool:
	if _write:
		var file := FileAccess.open(path, FileAccess.WRITE)
		if file == null:
			_fail("Could not write %s" % path)
			return false
		file.store_string(expected)
		file.close()
		return true
	if not FileAccess.file_exists(path):
		_fail("Missing generated parity artifact: %s" % path)
		return false
	if FileAccess.get_file_as_string(path) != expected:
		_fail("Stale generated parity artifact: %s (run tools/verify_gameplay_parity_inventory.ps1 -Write)" % path)
		return false
	return true

func _initialize() -> void:
	var arguments := OS.get_cmdline_user_args()
	if arguments.size() != 1:
		printerr("Usage: godot --headless --path <project> --script res://tools/movement_performance_probe.gd -- <package.realmz2>")
		call_deferred("_quit_cleanly", 2)
		return
	var loaded := PACKAGE_REPOSITORY_SCRIPT.new().load_package(arguments[0])
	if not loaded.is_ok():
		printerr("PACKAGE_REJECTED %s: %s" % [loaded.error_code, loaded.error_message])
		call_deferred("_quit_cleanly", 1)
		return
	var session := GameSession.new()
	var step := session.start(loaded.content, 1)
	if step.state == SessionStep.State.FAILED or not _assemble_six_character_party(session, loaded.content):
		printerr("SESSION_REJECTED: a six-character public setup could not be prepared")
		call_deferred("_quit_cleanly", 1)
		return
	var pair := _safe_movement_pair(session, loaded.content)
	if pair.is_empty() or not _place_party(session, loaded.content, pair["origin"]):
		printerr("SESSION_REJECTED: no trigger-free movement pair is available")
		call_deferred("_quit_cleanly", 1)
		return
	var direction: Vector2i = pair["direction"]
	var transaction_samples: Array[int] = []
	var projection_samples: Array[int] = []
	var event_kinds: Array[String] = []
	var event_sequences: Dictionary = {}
	var fatigue_payload: Dictionary = {}
	var ordinary_projection_count := 0
	for index: int in 60:
		var previous_view := session.view()
		var started_at := Time.get_ticks_usec()
		step = session.submit_intent(PlayerIntent.move(direction))
		var transaction_done := Time.get_ticks_usec()
		var view := session.view(step.events)
		var projection_done := Time.get_ticks_usec()
		if step.state != SessionStep.State.COMPLETED or view.pending_interaction != null:
			printerr("MOVEMENT_INTERRUPTED step=%d state=%d events=%s" % [index, step.state, step.events.map(func(event: DomainEvent) -> String: return String(event.kind))])
			call_deferred("_quit_cleanly", 1)
			return
		if index == 0:
			for event: DomainEvent in step.events:
				event_kinds.append(String(event.kind))
		var sequence := ",".join(step.events.map(func(event: DomainEvent) -> String: return String(event.kind)))
		event_sequences[sequence] = int(event_sequences.get(sequence, 0)) + 1
		for event: DomainEvent in step.events:
			if event.kind == &"fatigue_changed" and fatigue_payload.is_empty():
				fatigue_payload = event.payload.duplicate(true)
		if view.domain_revisions.is_ordinary_exploration_update_from(previous_view.domain_revisions):
			ordinary_projection_count += 1
		if index >= 10:
			transaction_samples.append(transaction_done - started_at)
			projection_samples.append(projection_done - transaction_done)
		direction = -direction
	var total_samples: Array[int] = []
	for index: int in transaction_samples.size():
		total_samples.append(transaction_samples[index] + projection_samples[index])
	var output := {
		"campaignId": loaded.content.campaign_id,
		"partySize": session.view().party_members.size(),
		"sampleCount": total_samples.size(),
		"transactionP95Ms": _p95_milliseconds(transaction_samples),
		"projectionP95Ms": _p95_milliseconds(projection_samples),
		"transactionPlusProjectionP95Ms": _p95_milliseconds(total_samples),
		"scheduledStepsPerSecond100": 5,
		"scheduledStepsPerSecond400": 20,
		"ordinaryProjectionCount": ordinary_projection_count,
		"eventKinds": event_kinds,
		"eventSequences": event_sequences,
		"fatiguePayload": fatigue_payload,
		"finalX": session.view().party_coordinate.x,
		"finalY": session.view().party_coordinate.y,
	}
	print(CanonicalJson.encode(output))
	if ordinary_projection_count != 60:
		printerr("MOVEMENT_INCREMENTAL_PROJECTION_MISSED expected=60 actual=%d sequences=%s" % [ordinary_projection_count, event_sequences])
		call_deferred("_quit_cleanly", 1)
		return
	if float(output["transactionPlusProjectionP95Ms"]) >= 50.0:
		printerr("MOVEMENT_P95_EXCEEDED expectedBelowMs=50 actualMs=%s" % output["transactionPlusProjectionP95Ms"])
		call_deferred("_quit_cleanly", 1)
		return
	call_deferred("_quit_cleanly", 0)

func _assemble_six_character_party(session: GameSession, content: RealmzContent) -> bool:
	var races := content.race_definitions()
	var castes := content.caste_definitions()
	if races.is_empty() or castes.is_empty():
		return false
	var race := races[0]
	var caste: CasteDefinition
	for candidate: CasteDefinition in castes:
		if race.eligible_caste_ids.is_empty() or race.eligible_caste_ids.has(candidate.id):
			caste = candidate
			break
	if caste == null:
		return false
	for index: int in 6:
		var character := CharacterState.new("movement-probe-%d" % index, "Probe %d" % (index + 1), 20, 20)
		character.race_id = race.id
		character.caste_id = caste.id
		var imported := session.submit_intent(PlayerIntent.import_vault_character(character.id, "%064d" % (index + 1), character, "movement-probe", content.package_hash))
		if imported.state == SessionStep.State.FAILED:
			return false
	var started := session.submit_intent(PlayerIntent.begin_adventure())
	for ignored: int in 16:
		if started.state != SessionStep.State.WAITING_FOR_INTERACTION:
			break
		if started.interaction == null or started.interaction.kind != InteractionRequest.ACKNOWLEDGE:
			return false
		started = session.respond(InteractionResponse.acknowledge(started.interaction))
	return started.state == SessionStep.State.COMPLETED and session.view().party_members.size() == 6

func _safe_movement_pair(session: GameSession, content: RealmzContent) -> Dictionary:
	var state := session.snapshot().game_state
	var map := content.world.map_by_id(state.party.map_id)
	if map == null:
		return {}
	var directions := MapTopology.land_directions() if map.level_type == &"land" else MapTopology.cardinal_directions()
	for cell: MapCell in map.topology.cells():
		if not _safe_cell(cell):
			continue
		for direction: Vector2i in directions:
			var movement := content.world.probe_movement(map.id, cell.coordinate, direction, state.world)
			if movement.allowed and movement.target_map == map and _safe_cell(movement.topology_result.target_cell):
				return {"origin": cell.coordinate, "direction": direction}
	return {}

func _place_party(session: GameSession, content: RealmzContent, coordinate: Vector2i) -> bool:
	var snapshot := session.snapshot()
	snapshot.game_state.party.coordinate = coordinate
	snapshot.game_state.world.mark_visited(snapshot.game_state.party.map_id, coordinate)
	return session.restore(content, snapshot).state == SessionStep.State.COMPLETED

