func _initialize() -> void:
	var requested_fragments: Array[String] = []
	var requested_cases: Array[String] = []
	var arguments := OS.get_cmdline_user_args()
	var argument_index: int = 0
	while argument_index < arguments.size():
		var argument: String = arguments[argument_index]
		if argument_index + 1 >= arguments.size() or argument not in ["--suite", "--case"]:
			printerr(USAGE)
			quit(2)
			return
		var fragment: String = arguments[argument_index + 1]
		if fragment.is_empty() or fragment.begins_with("--"):
			printerr(USAGE)
			quit(2)
			return
		if argument == "--suite":
			requested_fragments.append(fragment)
		else:
			requested_cases.append(fragment)
		argument_index += 2
	for fragment: String in requested_fragments:
		var fragment_matches_suite: bool = false
		for suite_script: Script in SUITES:
			if suite_script.resource_path.contains(fragment):
				fragment_matches_suite = true
				break
		if not fragment_matches_suite:
			printerr("No test suite matches filter '%s'." % fragment)
			quit(2)
			return
	if not requested_cases.is_empty() and requested_fragments.is_empty():
		printerr("Named case filters require at least one --suite filter so unrelated suites are never instantiated.")
		quit(2)
		return
	var selected_suites: Array[Script] = []
	for suite_script: Script in SUITES:
		if requested_fragments.is_empty():
			selected_suites.append(suite_script)
			continue
		for fragment: String in requested_fragments:
			if suite_script.resource_path.contains(fragment):
				selected_suites.append(suite_script)
				break
	if selected_suites.is_empty():
		printerr("No test suite matches the requested filters.")
		quit(2)
		return
	for case_fragment: String in requested_cases:
		var fragment_matches_case: bool = false
		for suite_script: Script in selected_suites:
			var suite: RealmzTestCase = suite_script.new()
			for method: Dictionary in _test_methods(suite):
				if String(method["name"]).contains(case_fragment):
					fragment_matches_case = true
					break
			if fragment_matches_case:
				break
		if not fragment_matches_case:
			printerr("No test case in the selected suites matches filter '%s'." % case_fragment)
			quit(2)
			return
	var assertion_count: int = 0
	var failure_count: int = 0
	for suite_script: Script in selected_suites:
		var suite_started: int = Time.get_ticks_msec()
		print("RUN SUITE: %s" % suite_script.resource_path)
		var suite: RealmzTestCase = suite_script.new()
		if requested_cases.is_empty():
			suite.run()
		else:
			var selected_methods := _selected_test_methods(suite, requested_cases)
			var shared_arguments: Array = []
			if selected_methods.any(func(method: Dictionary) -> bool: return not (method.get("args", []) as Array).is_empty()):
				shared_arguments = suite.selected_case_arguments()
			for method: Dictionary in selected_methods:
				var method_name := String(method["name"])
				var method_arguments: Array = method.get("args", []) as Array
				if not method_arguments.is_empty() and method_arguments.size() != shared_arguments.size():
					printerr("Test case '%s' needs %d shared argument(s), but its suite prepared %d." % [method_name, method_arguments.size(), shared_arguments.size()])
					quit(2)
					return
				var case_started: int = Time.get_ticks_msec()
				var assertions_before: int = suite.assertions
				print("RUN CASE: %s::%s" % [suite_script.resource_path, method_name])
				if method_arguments.is_empty():
					suite.call(method_name)
				else:
					suite.callv(method_name, shared_arguments)
				print("DONE CASE: %s::%s (%d assertions, %d ms)" % [suite_script.resource_path, method_name, suite.assertions - assertions_before, Time.get_ticks_msec() - case_started])
		print("DONE SUITE: %s (%d assertions, %d ms)" % [suite_script.resource_path, suite.assertions, Time.get_ticks_msec() - suite_started])
		assertion_count += suite.assertions
		for failure: String in suite.failures:
			failure_count += 1
			printerr("FAIL %s: %s" % [suite_script.resource_path, failure])
	if failure_count == 0:
		print("PASS: %d assertions across %d suites" % [assertion_count, selected_suites.size()])
		quit(0)
	else:
		printerr("FAILED: %d failures across %d assertions" % [failure_count, assertion_count])
		quit(1)

func _test_methods(suite: RealmzTestCase) -> Array[Dictionary]:
	var methods: Array[Dictionary] = []
	for method: Dictionary in suite.get_method_list():
		if String(method.get("name", "")).begins_with("_test_"):
			methods.append(method)
	return methods

func _selected_test_methods(suite: RealmzTestCase, fragments: Array[String]) -> Array[Dictionary]:
	var selected: Array[Dictionary] = []
	var methods := _test_methods(suite)
	for fragment: String in fragments:
		for method: Dictionary in methods:
			if String(method["name"]).contains(fragment) and not selected.has(method):
				selected.append(method)
	return selected

func _combat_view(state: GameState, content: RealmzContent, rules: RealmzRules, revision: int) -> GameView:
	var members: Array[CharacterView] = []
	for character: CharacterState in state.party.characters():
		var member := CharacterView.new(character, content)
		member.apply_equipment(rules.inventory.combat_equipment(character, content.item_definitions()))
		members.append(member)
	var combat := CombatView.new(state.combat, state.party.characters(), content, rules.inventory, rules.battlefield, rules.combat_flow, state) if state.combat != null else null
	return GameView.new(revision, true, null, state.party.map_id, state.party.coordinate, state.clock.day(), state.clock.hour(), state.clock.minute(), null, members, state.party.fatigue, state.party.pooled_wealth.gold, combat)

func _playback_metrics(previous: GameView, events: Array[DomainEvent], final: GameView) -> Dictionary:
	var controller := CombatPlaybackController.new()
	if not controller.begin(previous, events, final, false):
		return {"frames": 0, "seconds": 0.0}
	var frames := 0
	var seconds := 0.0
	while controller.is_active() and frames < 10_000:
		var frame := controller.current_frame()
		if frame == null:
			break
		frames += 1
		seconds += frame.duration_seconds
		controller.advance(frame.duration_seconds + 0.001, false)
	return {"frames": frames, "seconds": snappedf(seconds, 0.001)}

func _fresh_state(content: RealmzContent) -> GameState:
	var races := content.race_definitions()
	var castes := content.caste_definitions()
	if races.is_empty() or castes.is_empty():
		return null
	var race := races[0]
	var caste: CasteDefinition = null
	for candidate: CasteDefinition in castes:
		if race.eligible_caste_ids.is_empty() or race.eligible_caste_ids.has(candidate.id):
			caste = candidate
			break
	if caste == null:
		return null
	var characters: Array[CharacterState] = []
	var combat_spell_ids: Array[String] = []
	for spell: SpellDefinition in content.spell_definitions():
		if spell.in_combat:
			combat_spell_ids.append(spell.id)
			if combat_spell_ids.size() == 12:
				break
	for index: int in 6:
		var character := CharacterState.new("combat-probe-%d" % index, "Probe %d" % (index + 1), 40, 40)
		character.race_id = race.id
		character.caste_id = caste.id
		character.level = 5
		character.maximum_movement = 12
		character.movement = 12
		character.normal_attacks = 2
		if index == 0:
			character.set_known_spells(combat_spell_ids)
			character.maximum_spell_attacks = 3
			character.spell_points = 500
		characters.append(character)
	var state := GameState.new(PartyState.new(content.start_map_id, content.start_coordinate, characters), RealmzClock.new())
	state.party_setup_completed = true
	state.world.mark_visited(content.start_map_id, content.start_coordinate)
	return state

func _initialize() -> void:
	var arguments := OS.get_cmdline_user_args()
	if arguments.size() < 1 or arguments.size() > 2:
		printerr("Usage: godot --headless --path <project> --script res://tools/combat_performance_probe.gd -- <package.realmz2> [classic-battle-id]")
		call_deferred("_quit_cleanly", 2)
		return
	var loaded := PACKAGE_REPOSITORY_SCRIPT.new().load_package(arguments[0])
	if not loaded.is_ok():
		printerr("PACKAGE_REJECTED %s: %s" % [loaded.error_code, loaded.error_message])
		call_deferred("_quit_cleanly", 1)
		return
	var content: RealmzContent = loaded.content
	var package_media: PackageMediaCatalog = loaded.media
	var battle_id := int(arguments[1]) if arguments.size() == 2 else DEFAULT_BATTLE_ID
	var battle := content.battle_by_classic_id(battle_id)
	if battle == null:
		printerr("BATTLE_REJECTED: Classic battle %d is unavailable" % battle_id)
		call_deferred("_quit_cleanly", 1)
		return
	var state := _fresh_state(content)
	if state == null:
		printerr("STATE_REJECTED: package has no compatible race/caste pair")
		call_deferred("_quit_cleanly", 1)
		return
	var rules := RealmzRules.new()
	var rng := RealmzRng.new(17)
	var setup_started := Time.get_ticks_usec()
	var setup := rules.combat_flow.start_battle(state, content, battle, rng)
	var setup_us := Time.get_ticks_usec() - setup_started
	if not setup.ok or state.combat == null:
		printerr("BATTLE_REJECTED %s: %s" % [setup.error_code, setup.error_message])
		call_deferred("_quit_cleanly", 1)
		return
	var character_ids: Array[String] = []
	for character: CharacterState in state.party.characters():
		if character.current_health > 0 and state.combat.battlefield.has_actor(character.id):
			character_ids.append(character.id)
	var monster_ids: Array[String] = []
	for monster: MonsterState in state.combat.monsters():
		if monster.current_health > 0 and state.combat.battlefield.has_actor(monster.id):
			monster_ids.append(monster.id)
	if character_ids.is_empty() or monster_ids.is_empty():
		printerr("BATTLE_REJECTED: probe requires living party and monster actors")
		call_deferred("_quit_cleanly", 1)
		return
	state.combat.set_turn_order(character_ids + monster_ids)
	var combat_data := state.combat.to_data()
	combat_data["attackedActorIds"] = []
	state.combat = CombatState.from_data(combat_data)
	var previous_view := _combat_view(state, content, rules, 1)
	var view_started := Time.get_ticks_usec()
	var view := CombatView.new(state.combat, state.party.characters(), content, rules.inventory, rules.battlefield, rules.combat_flow, state)
	var view_us := Time.get_ticks_usec() - view_started
	var spell_options_started := Time.get_ticks_usec()
	var spell_options := rules.combat_flow.character_spell_options(state, content, character_ids[0])
	var spell_options_us := Time.get_ticks_usec() - spell_options_started
	var spell_reason_started := Time.get_ticks_usec()
	rules.combat_flow.character_spell_unavailable_reason(state, content, character_ids[0])
	var spell_reason_us := Time.get_ticks_usec() - spell_reason_started
	var checkpoint_started := Time.get_ticks_usec()
	state.to_data()
	var checkpoint_us := Time.get_ticks_usec() - checkpoint_started
	var auto_started := Time.get_ticks_usec()
	var auto := rules.combat_flow.submit_action(state, content, character_ids[0], &"auto", "", rng)
	var auto_us := Time.get_ticks_usec() - auto_started
	if not auto.ok:
		printerr("AUTO_REJECTED %s: %s" % [auto.error_code, auto.error_message])
		call_deferred("_quit_cleanly", 1)
		return
	var final_view := _combat_view(state, content, rules, 2)
	var auto_playback := _playback_metrics(previous_view, auto.events, final_view)
	var setup_view := _combat_view(state, content, rules, 3)
	var setup_playback := _playback_metrics(null, setup.events, setup_view)
	var combat_assets: Array[MediaAsset] = []
	for monster: MonsterState in state.combat.monsters():
		var definition := content.monster_by_id(monster.definition_id)
		if definition == null:
			continue
		var asset := package_media.asset_by_resource("cicn", definition.icon_id)
		if asset != null and not combat_assets.has(asset):
			combat_assets.append(asset)
	var individual_media_started := Time.get_ticks_usec()
	for asset: MediaAsset in combat_assets:
		package_media.read_bytes(asset)
	var individual_media_us := Time.get_ticks_usec() - individual_media_started
	var batch_media_started := Time.get_ticks_usec()
	package_media.read_bytes_batch(combat_assets)
	var batch_media_us := Time.get_ticks_usec() - batch_media_started
	print(CanonicalJson.encode({
		"autoEventCount": auto.events.size(),
		"autoEventKinds": auto.events.map(func(event: DomainEvent) -> String: return String(event.kind)),
		"autoMs": _milliseconds(auto_us),
		"autoPlaybackFrames": auto_playback["frames"],
		"autoPlaybackSeconds": auto_playback["seconds"],
		"battleClassicId": battle_id,
		"battleSetupEventCount": setup.events.size(),
		"battleSetupEventKinds": setup.events.map(func(event: DomainEvent) -> String: return String(event.kind)),
		"battleSetupMs": _milliseconds(setup_us),
		"battleSetupPlaybackFrames": setup_playback["frames"],
		"battleSetupPlaybackSeconds": setup_playback["seconds"],
		"combatViewMs": _milliseconds(view_us),
		"combatSpellOptionCount": spell_options.size(),
		"combatSpellOptionsMs": _milliseconds(spell_options_us),
		"combatSpellUnavailableReasonMs": _milliseconds(spell_reason_us),
		"combatPackageAssetCount": combat_assets.size(),
		"combatPackageAssetIndividualReadMs": _milliseconds(individual_media_us),
		"combatPackageAssetBatchReadMs": _milliseconds(batch_media_us),
		"monsterCount": monster_ids.size(),
		"partySize": character_ids.size(),
		"rngDrawCount": rng.snapshot().draw_count,
		"stateCheckpointMs": _milliseconds(checkpoint_us),
		"viewMovementOptionCount": view.movement_options.size(),
	}))
	call_deferred("_quit_cleanly", 0)

static func _age_update_from_data(value: Variant) -> InteractionRequest.AgeUpdateBody:
	if not value is Dictionary:
		return null
	var request := InteractionRequest.age_update("continuation.age", value)
	return null if request == null else request.body as InteractionRequest.AgeUpdateBody

static func _valid_session_continuation(content: RealmzContent, state: GameState, continuation: SessionContinuation, vm_interaction: InteractionRequest, session_interaction: InteractionRequest) -> bool:
	if continuation == null or continuation.is_empty():
		return false
	match continuation.kind:
		&"boat-choice":
			return _valid_boat_continuation(content, state, continuation, vm_interaction, session_interaction)
		&"application-hook":
			var application := continuation.application()
			if application == null or vm_interaction == null or session_interaction != null or application.program_id.is_empty():
				return false
			if content.scenario.application_hook_program_id(application.hook) != application.program_id or content.scenario.program_by_id(application.program_id) == null:
				return false
			match application.resume_kind:
				&"begin-adventure":
					return application.hook == ScenarioApplicationHooks.START_GAME and application.service_id.is_empty() and state.party_setup_completed and not state.party.characters().is_empty()
				&"service":
					return application.hook in [ScenarioApplicationHooks.SHOP, ScenarioApplicationHooks.TEMPLE] and not application.service_id.is_empty() and ((application.service_id == state.active_shop_id and content.shop_by_id(application.service_id) != null) or (application.service_id == "realmz.service.temple" and state.temple_available))
				&"end-adventure":
					return application.hook == ScenarioApplicationHooks.END_ADVENTURE and application.service_id.is_empty()
				&"end-adventure-close":
					return application.hook == ScenarioApplicationHooks.PARTY_DEATH and application.service_id.is_empty()
				&"party-defeat":
					return application.hook == ScenarioApplicationHooks.PARTY_DEATH and application.service_id.is_empty() and state.combat != null and state.combat.completed and state.combat.outcome == &"defeat"
				&"scenario-party-defeat":
					if application.hook != ScenarioApplicationHooks.PARTY_DEATH or not application.service_id.is_empty() or application.suspended_owner == null:
						return false
					var saved := application.suspended_vm
					return ScenarioVm.handoff_is_valid(application.vm_handoff, saved) and RealmzRuntimeApi.party_defeat_handoff_is_valid(content, state, application.vm_handoff.runtime) and suspended_scenario_owner_is_valid(content, state, application.suspended_owner, saved)
			return false
		&"pooled-wealth-departure":
			var service := continuation.service()
			if service == null or vm_interaction != null or session_interaction == null or state.party == null or state.bank_available:
				return false
			var departure_probe := content.world.probe_movement(state.party.map_id, state.party.coordinate, service.direction, state.world, state.party_in_boat)
			if not departure_probe.allowed and departure_probe.reason == &"invalid_direction":
				return false
			if service.stage == &"warning":
				return SessionInteractionFactory.has_pooled_wealth(state.party) and session_interaction.to_data() == SessionInteractionFactory.pooled_wealth_departure_warning(session_interaction.request_id).to_data()
			if service.stage == &"distribution":
				var bank_body := session_interaction.body as InteractionRequest.BankRequestBody
				return session_interaction.kind == InteractionRequest.POOLED_WEALTH_DEPARTURE and bank_body != null and bank_body.mode == &"departure" and state.party.character_by_id(bank_body.selected_character_id) != null and session_interaction.to_data() == SessionInteractionFactory.pooled_wealth_departure_distribution(state, session_interaction.request_id, bank_body.selected_character_id).to_data()
			return false
		&"service-interaction":
			var service := continuation.service()
			if service == null or vm_interaction != null or session_interaction == null:
				return false
			var runtime := service.runtime_continuation
			if runtime == null:
				return false
			var runtime_body := runtime.body as ScenarioRuntimeContinuation.ServiceBody
			var selected_temple_character := "" if runtime_body == null else runtime_body.selected_character_id
			match runtime.kind:
				&"classic-shop":
					return service.service_id == state.active_shop_id and not service.service_id.is_empty() and content.shop_by_id(service.service_id) != null and session_interaction.kind == InteractionRequest.SHOP
				&"classic-temple":
					var temple_body := session_interaction.body as InteractionRequest.TempleRequestBody
					return runtime_body != null and service.service_id == "realmz.service.temple" and state.temple_available and runtime_body.cost_percent == state.temple_cost_percent and runtime_body.bank_available == state.bank_available and state.party.character_by_id(selected_temple_character) != null and session_interaction.kind == InteractionRequest.TEMPLE and temple_body != null and temple_body.selected_character_id == selected_temple_character
				&"classic-temple-exit":
					return runtime_body != null and service.service_id == "realmz.service.temple" and state.temple_available and not state.bank_available and runtime_body.cost_percent == state.temple_cost_percent and not runtime_body.bank_available and state.party.character_by_id(selected_temple_character) != null and session_interaction.kind == InteractionRequest.YES_NO
				&"classic-banking":
					return service.service_id == "realmz.service.bank" and state.bank_available and session_interaction.kind == InteractionRequest.BANK
			return false
