static func _valid_thief_vm_continuation(content: RealmzContent, state: GameState, rng_state: RealmzRngState, vm: ScenarioVm) -> bool:
	var snapshot := vm.snapshot()
	if snapshot.pending_continuation == null:
		return true
	var runtime := snapshot.pending_continuation.runtime
	if runtime == null or runtime.kind not in [ScenarioRuntimeContinuation.CLASSIC_THIEF_ENCOUNTER, ScenarioRuntimeContinuation.CLASSIC_PICK_LOCK, ScenarioRuntimeContinuation.CLASSIC_THIEF_RESOLUTION]:
		return true
	var owner := runtime.body as ScenarioRuntimeContinuation.ThiefBody
	var encounter := content.complex_encounter_by_id(owner.encounter_id) if owner != null else null
	var thief := content.thief_encounter_by_id(encounter.thief_success) if encounter != null and encounter.thief else null
	var request := vm.pending_request()
	if owner == null or encounter == null or thief == null or request == null:
		return false
	if runtime.kind == ScenarioRuntimeContinuation.CLASSIC_THIEF_ENCOUNTER:
		var body := request.body as InteractionRequest.ThiefEncounterRequestBody
		return request.kind == InteractionRequest.THIEF_ENCOUNTER and body != null and body.encounter_id == encounter.id and _valid_thief_request(content, state, thief, body)
	if runtime.kind == ScenarioRuntimeContinuation.CLASSIC_THIEF_RESOLUTION:
		return _valid_thief_resolution_request(content, state, thief, owner, request)
	var body := request.body as InteractionRequest.PickLockRequestBody
	var character := state.party.character_by_id(owner.character_id)
	if request.kind != InteractionRequest.PICK_LOCK or body == null or owner.action_index not in [2, 4, 6, 7] or body.encounter_id != encounter.id or body.action_index != owner.action_index or body.character_id != owner.character_id or character == null or character.current_health <= 0 or character.conditions.is_active(ConditionRules.ANIMATED):
		return false
	var flags := state.thief_encounter_type_flags(thief)
	var chance := ClassicPickLockRulesScript.chance(character.ability_value(ClassicPickLockRulesScript.ability_index(owner.action_index)), thief.modifiers()[owner.action_index])
	var expected_frames := ClassicPickLockRulesScript.preview(rng_state, thief.tumblers, chance)
	return flags.size() == 10 and not flags[owner.action_index] and chance > 0 and body.action_label == ClassicPickLockRulesScript.action_label(owner.action_index) and body.character_name == character.name and body.portrait_id == character.portrait_id and body.chance_percent == chance and body.yellow_threshold == ClassicPickLockRulesScript.yellow_threshold(chance) and body.green_threshold == ClassicPickLockRulesScript.green_threshold(chance) and body.frame_rate == ClassicPickLockRulesScript.FRAME_RATE and body.time_limit_frames == ClassicPickLockRulesScript.time_limit_frames(thief.tumblers) and body.frames == expected_frames

static func _valid_thief_request(content: RealmzContent, state: GameState, thief: ThiefEncounterDefinition, body: InteractionRequest.ThiefEncounterRequestBody) -> bool:
	var prompt_id := absi(thief.prompts()[0]) if not thief.prompts().is_empty() else 0
	var message := content.message_by_id(prompt_id)
	if body.prompt != (message.text if message != null else "Choose a thief action."):
		return false
	var opening_sounds := thief.prompt_sounds()
	if body.sound_id not in [0, opening_sounds[0] if not opening_sounds.is_empty() else 0]:
		return false
	var flags := state.thief_encounter_type_flags(thief)
	var eligible: Array[CharacterState] = []
	for character: CharacterState in state.party.characters():
		if character.current_health > 0 and not character.conditions.is_active(ConditionRules.ANIMATED):
			eligible.append(character)
	if flags.size() != 10 or body.characters.size() != eligible.size():
		return false
	for index: int in eligible.size():
		var character := eligible[index]
		var detached := body.characters[index]
		if detached.id != character.id or detached.name != character.name or detached.portrait_id != character.portrait_id or detached.actions.size() != 8:
			return false
		for action_index: int in 8:
			var action := detached.actions[action_index]
			var ability := character.ability_value(ClassicPickLockRulesScript.ability_index(action_index))
			var effective := ability + thief.modifiers()[action_index]
			var expected_enabled := flags[action_index] and ability != 0 and effective > 0
			var expected_reason := "" if expected_enabled else "This action is no longer available." if not flags[action_index] else "This character lacks the required ability." if ability == 0 else "The authored modifier reduces this action below zero."
			if action.index != action_index or action.label != ClassicPickLockRulesScript.action_label(action_index) or action.value != (effective if ability != 0 else 0) or action.enabled != expected_enabled or action.reason != expected_reason:
				return false
	return true

static func _valid_thief_resolution_request(content: RealmzContent, state: GameState, thief: ThiefEncounterDefinition, owner: ScenarioRuntimeContinuation.ThiefBody, request: InteractionRequest) -> bool:
	var body := request.body as InteractionRequest.AcknowledgeBody
	var character := state.party.character_by_id(owner.character_id)
	if request.kind != InteractionRequest.ACKNOWLEDGE or body == null or character == null or owner.action_index < 0 or owner.action_index > 7 or body.presentation != &"classic-textbox" or not body.has_presentation or body.has_journal_state or body.has_player_map_id:
		return false
	var flags := state.thief_encounter_type_flags(thief)
	if flags.size() != 10:
		return false
	if owner.phase == &"trap-message":
		return owner.trap_pending and flags[9] and body.prompt == "A trap is sprung." and not body.has_message_id and not body.has_sound_id
	if owner.phase != &"action-message" or flags[owner.action_index]:
		return false
	var text_ids := thief.success_text() if owner.succeeded else thief.failure_text()
	var sound_ids := thief.success_sounds() if owner.succeeded else thief.failure_sounds()
	var signed_message_id := text_ids[owner.action_index]
	var message_id := absi(signed_message_id)
	var message := content.message_by_id(message_id)
	return signed_message_id > 0 and message != null and body.has_message_id and body.message_id == message_id and body.prompt == message.text and body.has_sound_id and body.sound_id == sound_ids[owner.action_index] and (not owner.trap_pending or not owner.succeeded and flags[9])

static func _valid_post_move_continuation(content: RealmzContent, state: GameState, continuation: SessionContinuation, vm_interaction: InteractionRequest, session_interaction: InteractionRequest) -> bool:
	var exploration := continuation.exploration()
	if continuation.kind != &"post-move" or exploration == null or exploration.action_point_destination_depth < 0 or exploration.action_point_destination_depth > 1:
		return false
	var map := content.world.map_by_id(exploration.map_id)
	var cell: MapCell = null if map == null else map.topology.cell_at(exploration.coordinate)
	if cell == null or state.party.map_id != map.id or state.party.coordinate != exploration.coordinate or exploration.trigger_ids != ExplorationTimeWorkflow.selected_placed_trigger_ids(content, cell) or exploration.random_region_ids != cell.random_rect_ids():
		return false
	if exploration.random_region_index < -1 or exploration.random_region_index >= exploration.random_region_ids.size():
		return false
	if session_interaction != null:
		return vm_interaction == null and exploration.active_trigger_id.is_empty() and exploration.active_random_program_id.is_empty() and exploration.random_battle_stage == &"surprise-choice" and session_interaction.kind == InteractionRequest.YES_NO and exploration.random_region_index >= 0 and exploration.random_region_ids[exploration.random_region_index] == exploration.active_random_region_id and map.random_region_by_id(exploration.active_random_region_id) != null
	if vm_interaction == null or not exploration.random_battle_stage.is_empty() or not exploration.active_random_region_id.is_empty():
		return false
	if not exploration.active_random_program_id.is_empty():
		return exploration.active_trigger_id.is_empty() and content.scenario.program_by_id(exploration.active_random_program_id) != null
	return exploration.trigger_index >= 0 and exploration.trigger_index < exploration.trigger_ids.size() and not exploration.active_trigger_id.is_empty() and exploration.trigger_ids[exploration.trigger_index] == exploration.active_trigger_id and content.trigger_by_id(exploration.active_trigger_id) != null

static func _eligible_field_healer(context: SessionWorkflowContext, character: CharacterState) -> bool:
	if character == null or character.spellcaster_type not in [1, 2] or character.current_health < 1 or character.spell_points < 10 or context.state.character_spellcasting_blocked:
		return false
	for condition_index: int in [ConditionRules.CONFUSED, ConditionRules.SILENCED, ConditionRules.HELPLESS, ConditionRules.STUPID, ConditionRules.ANIMATED]:
		if character.conditions.is_active(condition_index):
			return false
	for spell_id: String in character.known_spells():
		var spell := context.content.spell_by_id(spell_id)
		if spell != null and absi(spell.special) == 57:
			return true
	return false

static func complete_area_search(context: SessionWorkflowContext, preceding_events: Array[DomainEvent]) -> ClockTransitionResult:
	var current_map := context.content.world.map_by_id(context.state.party.map_id)
	if current_map == null:
		return ClockTransitionResult.failed(&"unknown_map", "The current map is unavailable for Area Search.", preceding_events)
	var events: Array[DomainEvent] = []
	events.assign(preceding_events)
	var previous_day := context.state.clock.day()
	events.append_array(context.rules.clock.advance_classic_field_time(context.state, context.content, 1, classic_time_scale(current_map), true))
	return ClockTransitionResult.completed(current_map, events, true, context.state.clock.day() if context.state.clock.day() != previous_day else 0)

static func _valid_boat_continuation(content: RealmzContent, state: GameState, continuation: SessionContinuation, vm_interaction: InteractionRequest, session_interaction: InteractionRequest) -> bool:
	var boat := continuation.boat()
	var prompt: InteractionRequest.YesNoRequestBody = null
	if session_interaction != null:
		prompt = session_interaction.body as InteractionRequest.YesNoRequestBody
	if boat == null or vm_interaction != null or session_interaction == null or session_interaction.kind != InteractionRequest.YES_NO or prompt == null or state.party.map_id != boat.source_map_id or state.party.coordinate != boat.source_coordinate:
		return false
	var movement := content.world.probe_movement(boat.source_map_id, boat.source_coordinate, boat.direction, state.world, state.party_in_boat)
	if movement.target_map == null or movement.target_map.id != boat.target_map_id or movement.target_coordinate != boat.target_coordinate:
		return false
	if boat.action == &"board":
		return not state.party_in_boat and movement.reason == &"board_boat" and prompt.prompt == "Board this boat?" and prompt.yes_label == "Board" and prompt.no_label == "Stay ashore"
	if boat.action == &"disembark":
		return state.party_in_boat and movement.reason == &"boat_shore" and prompt.prompt == "Leave the boat here and go ashore?" and prompt.yes_label == "Leave boat" and prompt.no_label == "Remain aboard"
	return false

static func from_data(value: Variant) -> SessionContinuation:
	if not value is Dictionary or value.size() != 3 or value.get("version") != VERSION or not value.get("kind") is String or value["kind"].is_empty() or not value.get("data") is Dictionary:
		return null
	return _from_wire_payload(StringName(value["kind"]), value["data"])

static func _from_wire_payload(continuation_kind: StringName, data: Dictionary) -> SessionContinuation:
	match continuation_kind:
		&"post-clock":
			return _decode_post_clock(data)
		&"post-move":
			return _decode_post_move(data)
		&"boat-choice":
			return _decode_boat(data)
		&"application-hook":
			return _decode_application(data)
		&"character-spell-confirmation":
			var remaining := _integer(data.get("remaining"))
			return character_spell_confirmation(data["characterId"], remaining) if _has_exact_fields(data, ["characterId", "remaining"]) and data.get("characterId") is String and not data["characterId"].is_empty() and remaining >= 1 else null
		&"character-vault-publication":
			return character_vault_publication(data["characterId"]) if _has_exact_fields(data, ["characterId"]) and data.get("characterId") is String and not data["characterId"].is_empty() else null
		&"item-use-target-selection", &"field-spell-target-selection", &"scroll-target-selection", &"drop-item-confirmation":
			return _decode_targeting(continuation_kind, data)
		&"service-interaction":
			if not _has_exact_fields(data, ["serviceId", "runtimeContinuation"]) or not data.get("serviceId") is String or data["serviceId"].is_empty():
				return null
			var service_runtime := ScenarioRuntimeContinuation.from_data(data.get("runtimeContinuation"))
			if service_runtime == null or service_runtime.kind not in [ScenarioRuntimeContinuation.CLASSIC_SHOP, ScenarioRuntimeContinuation.CLASSIC_TEMPLE, ScenarioRuntimeContinuation.CLASSIC_TEMPLE_EXIT, ScenarioRuntimeContinuation.CLASSIC_BANKING]:
				return null
			return service_interaction(data["serviceId"], service_runtime)
		&"pooled-wealth-departure":
			var direction_x := _signed_integer(data.get("directionX"))
			var direction_y := _signed_integer(data.get("directionY"))
			if not _has_exact_fields(data, ["stage", "directionX", "directionY"]) or data.get("stage") not in ["warning", "distribution"] or direction_x < -1 or direction_x > 1 or direction_y < -1 or direction_y > 1 or Vector2i(direction_x, direction_y) == Vector2i.ZERO:
				return null
			return pooled_wealth_departure(StringName(data["stage"]), Vector2i(direction_x, direction_y))
		&"age-updates":
			return _decode_age(data)
		&"combat-retreat-confirmation", &"combat-death-macro", &"combat-ally-selection", &"combat-fumble-recovery":
			return _decode_combat(continuation_kind, data)
		&"combat-reward":
			if not _has_exact_fields(data, ["battleId", "runtimeContinuation"]) or not data.get("battleId") is String or data["battleId"].is_empty():
				return null
			var reward_runtime := ScenarioRuntimeContinuation.from_data(data.get("runtimeContinuation"))
			var reward_state := reward_runtime.body as ScenarioRuntimeContinuation.RewardBody if reward_runtime != null and reward_runtime.kind == ScenarioRuntimeContinuation.CLASSIC_REWARD else null
			if reward_state == null or reward_state.state == null or reward_state.state.origin != &"battle" or reward_state.state.source_id != data["battleId"]:
				return null
			return combat_reward(data["battleId"], reward_runtime)
	return null

static func _decode_targeting(continuation_kind: StringName, data: Dictionary) -> SessionContinuation:
	if continuation_kind == &"drop-item-confirmation":
		if not _has_exact_fields(data, ["characterId", "instanceId"]) or not _nonempty_strings(data, ["characterId", "instanceId"]):
			return null
		var drop := TargetingBody.new()
		drop.character_id = data["characterId"]
		drop.instance_id = data["instanceId"]
		return targeting_selection(continuation_kind, drop)
	var fields: Array[String] = ["characterId", "spellId", "power", "targetCount"]
	match continuation_kind:
		&"item-use-target-selection": fields.append_array(["instanceId", "startingCharges"])
		&"field-spell-target-selection": fields.append("startingSpellPoints")
		&"scroll-target-selection": fields.append("scrollSlot")
	if not _has_exact_fields(data, fields) or not _nonempty_strings(data, ["characterId", "spellId"]):
		return null
	var power := _integer(data.get("power"))
	var target_count := _integer(data.get("targetCount"))
	if power < 1 or power > 7 or target_count < 1 or target_count > 6:
		return null
	var body := TargetingBody.new()
	body.character_id = data["characterId"]
	body.spell_id = data["spellId"]
	body.power = power
	body.target_count = target_count
	if continuation_kind == &"item-use-target-selection":
		var charges := _integer(data.get("startingCharges"))
		if not data.get("instanceId") is String or data["instanceId"].is_empty() or charges < -1 or charges > 32767:
			return null
		body.instance_id = data["instanceId"]
		body.starting_charges = charges
	elif continuation_kind == &"field-spell-target-selection":
		var spell_points := _integer(data.get("startingSpellPoints"))
		if spell_points < 0 or spell_points > 32767:
			return null
		body.starting_spell_points = spell_points
	else:
		var slot := _integer(data.get("scrollSlot"))
		if slot < 0 or slot >= 5:
			return null
		body.scroll_slot = slot
	return targeting_selection(continuation_kind, body)

static func _decode_age(data: Dictionary) -> SessionContinuation:
	if not _has_exact_fields(data, ["updates", "index", "resumeKind", "resumeContinuation"]) or not data.get("updates") is Array or data["updates"].is_empty() or data["updates"].size() > 30 or not data.get("resumeKind") is String or not data.get("resumeContinuation") is Dictionary:
		return null
	var index := _integer(data.get("index"))
	if index < 1 or index > data["updates"].size():
		return null
	var body := AgeBody.new()
	for update: Variant in data["updates"]:
		var typed_update := _age_update_from_data(update)
		if typed_update == null:
			return null
		body.updates.append(typed_update)
	body.index = index
	body.resume_kind = StringName(data["resumeKind"])
	if body.resume_kind in [&"completed", &"combat-monster-turns"]:
		if not data["resumeContinuation"].is_empty():
			return null
	elif body.resume_kind in [&"post-clock", &"post-move"]:
		body.resume_continuation = from_data(data["resumeContinuation"])
		if body.resume_continuation == null or body.resume_continuation.kind != body.resume_kind:
			return null
	else:
		return null
	return age_updates(body)

static func _decode_combat(continuation_kind: StringName, data: Dictionary) -> SessionContinuation:
	if not data.get("battleId") is String or data["battleId"].is_empty():
		return null
	var body := CombatBody.new()
	body.battle_id = data["battleId"]
	match continuation_kind:
		&"combat-retreat-confirmation":
			if not _has_exact_fields(data, ["battleId", "actorId", "mode", "destination"]) or not data.get("actorId") is String or data["actorId"].is_empty() or data.get("mode") not in ["explicit", "edge"] or not data.get("destination") is Array or data["destination"].size() != 2:
				return null
			var x_value: Variant = _signed_integer_or_null(data["destination"][0])
			var y_value: Variant = _signed_integer_or_null(data["destination"][1])
			if x_value == null or y_value == null:
				return null
			var destination := Vector2i(int(x_value), int(y_value))
			if data["mode"] == "explicit" and destination != Vector2i(-100_000, -100_000) or data["mode"] == "edge" and destination == Vector2i(-100_000, -100_000):
				return null
			body.actor_id = data["actorId"]
			body.mode = StringName(data["mode"])
			body.destination = destination
		&"combat-death-macro":
			if not _has_exact_fields(data, ["battleId", "combatantId", "programId", "resetTraitorOnComplete"]) or not _nonempty_strings(data, ["combatantId", "programId"]) or not data.get("resetTraitorOnComplete") is bool:
				return null
			body.combatant_id = data["combatantId"]
			body.program_id = data["programId"]
			body.reset_traitor_on_complete = data["resetTraitorOnComplete"]
		&"combat-ally-selection", &"combat-fumble-recovery":
			if not _has_exact_fields(data, ["battleId"]):
				return null
	return combat_state(continuation_kind, body)

static func _acquired_player_maps_are_valid(content: RealmzContent, state: GameState) -> bool:
	if content == null or state == null:
		return false
	for player_map_id: String in state.world.acquired_map_ids():
		if content.world.player_map_by_id(player_map_id) == null:
			return false
	return true

static func search(context: SessionWorkflowContext) -> ClockTransitionResult:
	if context.state.party_camping:
		return ClockTransitionResult.failed(&"search_while_camped", "Search is replaced by scroll scribing while camped.")
	if context.state.party.fatigue > 134:
		return ClockTransitionResult.failed(&"area_search_exhausted", "The party is too fatigued to continue Area Search.")
	context.state.mark_searched(context.state.party.map_id, context.state.party.coordinate)
	var current_map := context.content.world.map_by_id(context.state.party.map_id)
	if current_map == null:
		return ClockTransitionResult.failed(&"unknown_map", "The current map is unavailable for Area Search.")
	var discovered: Array[String] = []
	var first_roll: int = 0
	for y: int in range(context.state.party.coordinate.y - 1, context.state.party.coordinate.y + 2):
		for x: int in range(context.state.party.coordinate.x - 1, context.state.party.coordinate.x + 2):
			var cell := current_map.topology.cell_at(Vector2i(x, y))
			if cell == null:
				continue
			for feature: MapFeature in cell.features():
				if feature.kind != &"secret" or context.state.world.secret_is_discovered(feature.id, feature.initial_state == &"revealed"):
					continue
				var roll := context.rng.draw(100, StringName("exploration.search.%s" % feature.id))
				if first_roll == 0:
					first_roll = roll
				if roll <= 100:
					context.state.world.discover_secret(feature.id)
					discovered.append(feature.id)
	var events: Array[DomainEvent] = [DomainEvent.new(&"search_completed", {"mapId": context.state.party.map_id, "x": context.state.party.coordinate.x, "y": context.state.party.coordinate.y, "roll": first_roll, "discoveredSecrets": discovered})]
	for secret_id: String in discovered:
		events.append(DomainEvent.new(&"secret_discovered", {"secretId": secret_id}))
	var previous_day := context.state.clock.day()
	# Castle's held Area Search first calls checkforsecret(TRUE), which advances
	# four field timeclicks. Its separate outer timeclick and random check resume
	# only after this phase's timed/random continuation has settled.
	events.append_array(context.rules.clock.advance_classic_field_time(context.state, context.content, 4, classic_time_scale(current_map), true))
	return ClockTransitionResult.completed(current_map, events, true, context.state.clock.day() if context.state.clock.day() != previous_day else 0)

static func toggle_search(context: SessionWorkflowContext) -> SessionWorkflowResult:
	if context.state.party_camping:
		return SessionWorkflowResult.failed(&"search_while_camped", "Search is replaced by scroll scribing while camped.")
	if context.state.combat != null and not context.state.combat.completed:
		return SessionWorkflowResult.failed(&"search_during_battle", "Search mode is unavailable during battle.")
	var searching := not context.state.party.conditions.is_active(ConditionRules.PARTY_SEARCHING)
	context.state.party.conditions.set_value(ConditionRules.PARTY_SEARCHING, -1 if searching else 0)
	return SessionWorkflowResult.completed([
		DomainEvent.new(&"search_mode_changed", {"searching": searching, "source": "classic"}),
		_sound_event(141, "classic-search-mode"),
	])

static func depart_camp_for_movement(context: SessionWorkflowContext, direction: Vector2i, preceding_events: Array[DomainEvent] = []) -> MovementTransitionResult:
	var movement := context.content.world.probe_movement(context.state.party.map_id, context.state.party.coordinate, direction, context.state.world, context.state.party_in_boat)
	if not movement.allowed and movement.reason == &"invalid_direction":
		return MovementTransitionResult.failed(&"invalid_direction", "Movement requires a cardinal direction, or a diagonal direction on a land map.")
	var map := context.content.world.map_by_id(context.state.party.map_id)
	if map == null:
		return MovementTransitionResult.failed(&"unknown_map", "The current map is unavailable for camp departure.")
	context.state.party_camping = false
	var events: Array[DomainEvent] = []
	events.assign(preceding_events)
	events.append(DomainEvent.new(&"camp_mode_changed", {"camping": false, "source": "classic-movement"}))
	events.append(DomainEvent.new(&"camp_departed_for_movement", {"mapId": map.id, "x": context.state.party.coordinate.x, "y": context.state.party.coordinate.y, "direction": [direction.x, direction.y], "source": "classic"}))
	var previous_day := context.state.clock.day()
	events.append_array(context.rules.clock.advance_classic_field_time(context.state, context.content, 2 if map.level_type == &"dungeon" else 15, classic_time_scale(map), true))
	return MovementTransitionResult.after_clock(map, events, &"move", direction, true, context.state.clock.day() if context.state.clock.day() != previous_day else 0, context.state.party.coordinate + direction)

static func commit_move(context: SessionWorkflowContext, direction: Vector2i, preceding_events: Array[DomainEvent] = []) -> MovementTransitionResult:
	var movement := context.content.world.probe_movement(context.state.party.map_id, context.state.party.coordinate, direction, context.state.world, context.state.party_in_boat)
	if not movement.allowed and movement.reason == &"invalid_direction":
		return MovementTransitionResult.failed(&"invalid_direction", "Movement requires a cardinal direction, or a diagonal direction on a land map.")
	if not movement.allowed:
		if movement.reason == &"board_boat":
			context.state.boat_shore_attempts = 0
			return MovementTransitionResult.awaiting_choice(&"board", movement, direction, preceding_events)
		if movement.reason == &"boat_shore":
			context.state.boat_shore_attempts += 1
			if context.state.boat_shore_attempts > 2:
				context.state.boat_shore_attempts = 0
				return MovementTransitionResult.awaiting_choice(&"disembark", movement, direction, preceding_events)
		elif not (context.state.party_in_boat and movement.reason == &"boat_terrain_blocked"):
			context.state.boat_shore_attempts = 0
		return commit_blocked_attempt(context, movement, preceding_events)
	context.state.boat_shore_attempts = 0
	return commit_permitted_move(context, movement, direction, preceding_events)

static func commit_blocked_attempt(context: SessionWorkflowContext, movement: WorldMovementResult, preceding_events: Array[DomainEvent] = [], include_collision_sound: bool = true) -> MovementTransitionResult:
	var blocked_events: Array[DomainEvent] = []
	blocked_events.assign(preceding_events)
	blocked_events.append(DomainEvent.new(&"movement_blocked", {"reason": String(movement.reason)}))
	if include_collision_sound and context.state.party_in_boat and movement.reason in [&"boat_shore", &"boat_terrain_blocked"]:
		blocked_events.append(_sound_event(-148, "classic-boat-collision"))
	append_movement_sound(blocked_events, movement)
	var attempt_cost := blocked_land_attempt_cost(movement)
	if attempt_cost <= 0:
		return MovementTransitionResult.completed(blocked_events)
	var previous_day := context.state.clock.day()
	blocked_events.append_array(context.rules.clock.advance_classic_field_time(context.state, context.content, attempt_cost, classic_time_scale(movement.source_map), true))
	return MovementTransitionResult.after_clock(movement.source_map, blocked_events, &"completed", Vector2i.ZERO, true, context.state.clock.day() if context.state.clock.day() != previous_day else 0, movement.target_coordinate)

static func complete_heal(context: SessionWorkflowContext, preceding_events: Array[DomainEvent]) -> SessionWorkflowResult:
	var events: Array[DomainEvent] = []
	events.assign(preceding_events)
	for healer: CharacterState in context.state.party.characters():
		if not _eligible_field_healer(context, healer):
			continue
		for target: CharacterState in context.state.party.characters():
			if target.current_health >= target.maximum_health or target.current_health <= -10 or target.conditions.is_active(ConditionRules.TURNED_TO_STONE) or healer.spell_points < 10:
				continue
			healer.spell_points -= 10
			var amount := mini(context.rng.draw(8, StringName("exploration.heal.%s.%s" % [healer.id, target.id])), target.maximum_health - target.current_health)
			target.current_health += amount
			events.append(DomainEvent.new(&"spell_points_spent", {"characterId": healer.id, "amount": 10, "source": "classic-heal"}))
			events.append(DomainEvent.new(&"health_recovered", {"characterId": target.id, "amount": amount, "source": "classic-heal"}))
	events.append(DomainEvent.new(&"party_heal_completed", {"mapId": context.state.party.map_id, "source": "classic"}))
	return SessionWorkflowResult.completed(events)

static func set_persistent_auto(context: SessionWorkflowContext, payload: PlayerIntent.CombatAutoPayload) -> CombatFlowResult:
	if context.state == null or context.state.combat == null or context.state.combat.completed:
		return CombatFlowResult.failed(&"combat_auto_unavailable", "Persistent Auto can be changed only during an active battle.")
	var character := context.state.party.character_by_id(payload.character_id)
	if character == null or character.current_health <= 0:
		return CombatFlowResult.failed(&"invalid_combat_auto_character", "Persistent Auto requires a living party character.")
	var state_checkpoint := context.state.to_data()
	var rng_checkpoint := context.rng.checkpoint()
	if not context.state.set_combat_auto(payload.character_id, payload.enabled):
		return CombatFlowResult.failed(&"invalid_combat_auto_character", "Persistent Auto could not be changed for this character.")
	var toggle_sound := 147 if payload.enabled else 139
	var events: Array[DomainEvent] = [
		DomainEvent.new(&"sound_requested", {"soundId": toggle_sound, "waitForCompletion": false, "source": "classic-combat-auto-toggle"}),
		DomainEvent.new(&"combat_auto_changed", {"characterId": payload.character_id, "enabled": payload.enabled, "source": "classic"}),
	]
	if payload.enabled and context.state.combat.active_actor_id() == payload.character_id:
		events.append(DomainEvent.new(&"sound_requested", {"soundId": 141, "waitForCompletion": false, "source": "classic-combat-auto-button"}))
		var automatic := context.rules.combat_flow.run_persistent_auto_characters(context.state, context.content, context.rng)
		if not automatic.ok:
			if not context.state.restore_from_data(state_checkpoint) or not context.rng.rollback(rng_checkpoint):
				return CombatFlowResult.failed(&"combat_auto_rollback_failed", "Persistent Auto failed and could not restore its toggle transaction.")
			return CombatFlowResult.failed(automatic.error_code, automatic.error_message)
		events.append_array(automatic.events)
		return CombatFlowResult.succeeded(events, automatic.completed)
	return CombatFlowResult.succeeded(events)

static func _populate_inventory_item_actions(context: SessionWorkflowContext, result: GameView) -> void:
	var state := context.state
	var content := context.content
	var rules := context.rules
	var context_reason := ""
	if result.pending_interaction != null:
		context_reason = "Resolve the current interaction first."
	elif result.party_setup_available:
		context_reason = "Begin the adventure before changing carried equipment."
	elif result.combat_view != null and result.combat_view.outcome == &"active":
		context_reason = "Use the battle action flow during combat."
	var party := state.party.characters()
	var definitions := content.item_definitions()
	for member_view: CharacterView in result.party_members:
		var character := state.party.character_by_id(member_view.id)
		if character == null:
			continue
		var race := content.race_by_id(character.race_id)
		var caste := content.caste_by_id(character.caste_id)
		var identify_cast := _inventory_identify_cast(context, character)
		for item_view: ItemView in member_view.items:
			var instance := _item_instance(character, item_view.instance_id)
			var definition: ItemDefinition = null if instance == null else content.item_by_id(instance.definition_id)
			var actions := InventoryItemActionsView.new()
			if not context_reason.is_empty():
				actions.block_all(context_reason)
				item_view.actions = actions
				continue
			var equip_probe := rules.inventory.classic_equip_probe(character, instance, definition, race, caste, party, definitions)
			var unequip_probe := rules.inventory.classic_unequip_probe(character, instance, definition, definitions)
			var drop_probe := rules.inventory.classic_drop_probe(character, instance)
			var split_probe := rules.inventory.classic_split_probe(character, instance, definition)
			var join_probe := rules.inventory.classic_join_probe(character, instance, definition)
			var use_probe := InventoryMagicServicesWorkflow.field_spell_item_probe(context, character, instance, definition, content.spell_by_classic_id(definition.special_2) if definition != null else null)
			actions.equip = ActionAvailabilityView.new(&"equip_item", equip_probe.allowed, equip_probe.reason)
			actions.unequip = ActionAvailabilityView.new(&"unequip_item", unequip_probe.allowed, unequip_probe.reason)
			actions.drop = ActionAvailabilityView.new(&"drop_item", drop_probe.allowed, drop_probe.reason)
			actions.split = ActionAvailabilityView.new(&"split_item", split_probe.allowed, split_probe.reason)
			actions.join = ActionAvailabilityView.new(&"join_item", join_probe.allowed, join_probe.reason)
			actions.use = ActionAvailabilityView.new(&"use_item", use_probe.allowed, use_probe.reason)
			if identify_cast.is_empty():
				actions.identify = ActionAvailabilityView.new(&"identify_item", false, "No living party member knows Identify Objects with 25 spell points.")
			else:
				actions.identify_caster_id = String(identify_cast[0])
				actions.identify_spell_id = String(identify_cast[1])
				actions.identify = ActionAvailabilityView.new(&"identify_item", true)
			for destination: CharacterState in party:
				if destination == character:
					continue
				var trade_probe := rules.inventory.classic_trade_probe(character, destination, instance, definition)
				actions.trade_targets.append(ItemTransferTargetView.new(destination.id, destination.name, trade_probe.allowed, trade_probe.reason, destination.carried_load, destination.carried_load + item_view.weight, destination.maximum_load))
			var enabled_targets := actions.trade_targets.filter(func(target: ItemTransferTargetView) -> bool: return target.enabled)
			var trade_reason := "Choose another party member." if actions.trade_targets.is_empty() else actions.trade_targets[0].reason if enabled_targets.is_empty() else ""
			actions.trade = ActionAvailabilityView.new(&"trade_item", not enabled_targets.is_empty(), trade_reason)
			item_view.actions = actions

func _assert_vm_combat_auto_round_trip(content: RealmzContent, session: GameSession, character_id: String, phase: String) -> void:
	var enabled := session.submit_intent(PlayerIntent.set_combat_auto(character_id, true))
	assert_equal([enabled.state, enabled.error_code, enabled.interaction.kind], [SessionStep.State.WAITING_FOR_INTERACTION, &"", InteractionRequest.COMBAT], "the %s sixth member enables persistent Auto through VM combat" % phase)
	assert_true(_event_has(enabled.events, &"combat_auto_changed"), "%s VM Auto publishes the committed change" % phase)
	var body := enabled.interaction.body as InteractionRequest.CombatRequestBody
	assert_true(body != null and body.auto_character_ids.has(character_id) and (phase != "active" or body.auto_character_ids.size() == 6), "the next %s VM combat request projects sixth-member Auto after one activation" % phase)
	var saved := save_round_trip(session.snapshot())
	assert_not_null(saved, "%s sixth-member Auto crosses the save envelope" % phase)
	if saved == null:
		return
	var restored := GameSession.new()
	assert_equal(restored.restore(content, saved).state, SessionStep.State.COMPLETED, "%s sixth-member Auto restores with its VM continuation" % phase)
	assert_true(restored.view().combat_view.auto_character_ids.has(character_id), "restored %s VM combat retains sixth-member Auto" % phase)
	var disabled_id := restored.view().combat_view.active_actor_id if phase == "active" else character_id
	var disabled := restored.submit_intent(PlayerIntent.set_combat_auto(disabled_id, false))
	assert_equal([disabled.state, disabled.error_code, disabled.interaction.kind, restored.view().combat_view.auto_character_ids.has(disabled_id)], [SessionStep.State.WAITING_FOR_INTERACTION, &"", InteractionRequest.COMBAT, false], "restored %s VM combat disables Auto at the next activation boundary" % phase)

func assert_equal(actual: Variant, expected: Variant, message: String) -> void:
	assertions += 1
	if actual != expected:
		failures.append("%s (expected %s, got %s)" % [message, str(expected), str(actual)])

func to_data() -> Dictionary:
	match kind:
		FINISH:
			return {"kind": String(kind)}
		BRANCH_XAP:
			return {"kind": String(kind), "targetId": target_id, "gosub": gosub}
		BRANCH_PROGRAM:
			return {"kind": String(kind), "programId": program_id, "gosub": gosub, "context": context.to_data()}
		BRANCH_ENCOUNTER_RESULT:
			return {"kind": String(kind), "programId": program_id, "gosub": gosub, "context": context.to_data(), "repeatEncounter": repeat_encounter}
	return {}

static func from_data(value: Variant) -> ScenarioVmDirective:
	if not value is Dictionary or not value.get("kind") is String:
		return null
	match StringName(value["kind"]):
		FINISH:
			return finish() if value.size() == 1 else null
		BRANCH_XAP:
			if value.size() != 3 or not value.get("targetId") is int or not value.get("gosub") is bool:
				return null
			return branch_xap(value["targetId"], value["gosub"])
		BRANCH_PROGRAM:
			if value.size() != 4 or not value.get("programId") is String or value["programId"].is_empty() or not value.get("gosub") is bool or not value.get("context") is Dictionary:
				return null
			var restored_context := ScenarioExecutionContext.from_data(value["context"])
			return null if restored_context == null else branch_program(value["programId"], value["gosub"], restored_context)
		BRANCH_ENCOUNTER_RESULT:
			if value.size() != 5 or not value.get("programId") is String or value["programId"].is_empty() or not value.get("gosub") is bool or not value.get("context") is Dictionary or not value.get("repeatEncounter") is bool:
				return null
			var restored_context := ScenarioExecutionContext.from_data(value["context"])
			return null if restored_context == null else branch_encounter_result(value["programId"], value["gosub"], restored_context, value["repeatEncounter"])
	return null

static func reward(state: ClassicRewardState) -> ScenarioRuntimeContinuation:
	var typed := RewardBody.new()
	typed.state = ClassicRewardState.from_data(state.to_data())
	return ScenarioRuntimeContinuation.new(CLASSIC_REWARD, typed)

static func from_data(value: Variant) -> ScenarioRuntimeHandoff:
	if not value is Dictionary or value.size() != 3 or not value.get("kind") is String or _integer(value.get("version")) != VERSION or not value.get("data") is Dictionary or value["kind"] != String(PARTY_DEFEAT):
		return null
	var data: Dictionary = value["data"]
	if data.size() != 3 or not data.get("battleId") is String or data["battleId"].is_empty() or not data.get("sourceKind") is String or data["sourceKind"] not in [String(CLASSIC_COMBAT), String(SAFE_COMBAT)]:
		return null
	var parsed_caller := ScenarioBattleCaller.from_data(data.get("caller"))
	if parsed_caller == null:
		return null
	var result := party_defeat(data["battleId"], StringName(data["sourceKind"]), parsed_caller)
	return result if result._caller_matches_source() else null

func to_data() -> Dictionary:
	var continuation_data := body.to_data() if body != null else {}
	return {"kind": String(kind), "version": VERSION, "data": continuation_data}

static func _decode_encounter(continuation_kind: StringName, data: Dictionary) -> ScenarioRuntimeContinuation:
	var encounter_id := _integer(data.get("encounterId"))
	var encounter_attempt := _integer(data.get("encounterAttempt", 0))
	# Classic encounter tables are zero-based; encounter 0 is ordinary authored
	# content, not a missing identity.
	if encounter_id < 0 or encounter_attempt < 0 or not data.get("gosub") is bool:
		return null
	if continuation_kind == CLASSIC_COMPLEX_ENCOUNTER:
		return encounter(continuation_kind, encounter_id, data["gosub"], [], encounter_attempt) if data.size() == (3 if data.has("encounterAttempt") else 2) else null
	var indexes := _integers(data.get("optionIndexes"))
	if data.size() != (4 if data.has("encounterAttempt") else 3) or indexes.is_empty() or indexes.size() > 10:
		return null
	for index: int in indexes:
		if index < 0:
			return null
	return encounter(continuation_kind, encounter_id, data["gosub"], indexes, encounter_attempt)

func copy() -> ScenarioRuntimeHandoff:
	var duplicate := from_data(to_data())
	assert(duplicate != null, "A live typed runtime handoff must round-trip through its wire codec")
	return duplicate

func to_data() -> Dictionary:
	if kind != PARTY_DEFEAT or battle_id.is_empty() or source_kind not in [CLASSIC_COMBAT, SAFE_COMBAT] or caller == null or not _caller_matches_source():
		return {}
	var caller_data := caller.to_data()
	if caller_data.is_empty():
		return {}
	return {
		"kind": String(kind),
		"version": VERSION,
		"data": {
			"battleId": battle_id,
			"sourceKind": String(source_kind),
			"caller": caller_data,
		},
	}

static func from_data(value: Variant) -> ScenarioRuntimeContinuation:
	if not value is Dictionary or value.size() != 3 or not value.get("kind") is String or value.get("version") != VERSION or not value.get("data") is Dictionary:
		return null
	var continuation_kind := StringName(value["kind"])
	var data: Dictionary = value["data"]
	match continuation_kind:
		CLASSIC_ACKNOWLEDGE, CLASSIC_BANKING:
			return empty(continuation_kind) if data.is_empty() else null
		CLASSIC_TEXTBOX:
			var message_id := _integer(data.get("messageId"))
			return textbox(message_id) if data.size() == 1 and message_id > 0 else null
		CLASSIC_PLAYER_MAP:
			return player_map(data["playerMapId"]) if data.size() == 1 and data.get("playerMapId") is String and not data["playerMapId"].is_empty() else null
		SAFE_CHOICE:
			var option_count := _integer(data.get("optionCount"))
			return safe_choice(option_count) if data.size() == 1 and option_count >= 1 and option_count <= 256 else null
		CLASSIC_CHOICE:
			var values := _integers(data.get("values"))
			return classic_choice(values, data["gosub"]) if data.size() == 2 and values.size() == 5 and data.get("gosub") is bool else null
		CLASSIC_SIMPLE_ENCOUNTER, CLASSIC_COMPLEX_ENCOUNTER:
			return _decode_encounter(continuation_kind, data)
		CLASSIC_THIEF_ENCOUNTER, CLASSIC_PICK_LOCK, CLASSIC_THIEF_RESOLUTION:
			return _decode_thief(continuation_kind, data)
		CLASSIC_CHARACTER_SELECTION:
			var count := _integer(data.get("count"))
			if data.size() != 3 or count < 1 or count > 6 or not data.get("allowDead") is bool or not data.get("invert") is bool:
				return null
			return character_selection(count, data["allowDead"], data["invert"])
		CLASSIC_CHARACTER_ABILITY:
			var ability_values := _integers(data.get("values"))
			return character_ability(ability_values, data["gosub"]) if data.size() == 2 and ability_values.size() == 5 and data.get("gosub") is bool else null
		CLASSIC_AGE_UPDATES, SAFE_AGE_UPDATES:
			return _decode_age(continuation_kind, data)
		CLASSIC_SHOP:
			var ranges := _integers(data.get("acceptRanges"))
			return shop(data["shopId"], ranges) if data.size() == 2 and data.get("shopId") is String and not data["shopId"].is_empty() and ranges.size() in [0, 4] and ranges.size() == data["acceptRanges"].size() else null
		CLASSIC_TEMPLE, CLASSIC_TEMPLE_EXIT:
			var cost_percent := _integer(data.get("costPercent"))
			if data.size() != 3 or cost_percent < -32768 or cost_percent > 32767 or not data.get("bankAvailable") is bool or not data.get("selectedCharacterId") is String or data["selectedCharacterId"].is_empty():
				return null
			return temple(continuation_kind, cost_percent, data["bankAvailable"], data["selectedCharacterId"])
		CLASSIC_COMBAT, SAFE_COMBAT, CLASSIC_COMBAT_RETREAT, SAFE_COMBAT_RETREAT, CLASSIC_COMBAT_AGE, SAFE_COMBAT_AGE, CLASSIC_COMBAT_MACRO, SAFE_COMBAT_MACRO, CLASSIC_COMBAT_DEATH_MACRO, SAFE_COMBAT_DEATH_MACRO, CLASSIC_COMBAT_ALLY, SAFE_COMBAT_ALLY, CLASSIC_COMBAT_FUMBLE, SAFE_COMBAT_FUMBLE:
			return _decode_combat(continuation_kind, data)
		CLASSIC_REWARD:
			var reward_state := ClassicRewardState.from_data(data.get("state"))
			return reward(reward_state) if data.size() == 1 and reward_state != null else null
	return null

func _caller_matches_source() -> bool:
	if caller == null:
		return false
	return source_kind == SAFE_COMBAT and caller.kind == ScenarioBattleCaller.SAFE or source_kind == CLASSIC_COMBAT and caller.kind == ScenarioBattleCaller.CLASSIC

static func _integer(value: Variant) -> Variant:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return null

